UPDATE public.movies SET tmdb_id = 558449, overview_en = COALESCE(overview_en, 'Years after witnessing the death of the revered hero Maximus at the hands of his uncle, Lucius is forced to enter the Colosseum after his home is conquered by the tyrannical Emperors who now lead Rome with an iron fist. With rage in his heart and the future of the Empire at stake, Lucius must look to his past to find strength and honor to return the glory of Rome to its people.'), poster_url = 'https://image.tmdb.org/t/p/w780/xLIOLFWm4PgkXKVmHcmnjuxktSg.jpg', backdrop_url = 'https://image.tmdb.org/t/p/w1280/tOqIwliWMovSIZ9DyvHcHI7p2im.jpg', trailer_url = 'https://www.youtube.com/watch?v=TQwSz88ITAE', director = 'Ridley Scott', cast_members = ARRAY['Paul Mescal', 'Denzel Washington', 'Pedro Pascal', 'Connie Nielsen', 'Joseph Quinn', 'Fred Hechinger', 'ליאור רז', 'Derek Jacobi']::TEXT[], certification_origin = 'US: R', updated_at = NOW() WHERE id = 'a1000000-0000-0000-0000-000000000007'::UUID;

UPDATE public.movies SET tmdb_id = 1241982, overview_en = COALESCE(overview_en, 'After receiving an unexpected call from her wayfinding ancestors, Moana journeys alongside Maui and a new crew to the far seas of Oceania and into dangerous, long-lost waters for an adventure unlike anything she''s ever faced.'), poster_url = 'https://image.tmdb.org/t/p/w780/g8ikn2lfi4R04U7BtXvHmYvnUTV.jpg', backdrop_url = 'https://image.tmdb.org/t/p/w1280/vYqt6kb4lcF8wwqsMMaULkP9OEn.jpg', trailer_url = 'https://www.youtube.com/watch?v=JdSl4RMNtGE', director = 'David G. Derrick Jr.', cast_members = ARRAY['Auliʻi Cravalho', 'Dwayne Johnson', 'Hualālai Chung', 'Rose Matafeo', 'David Fane', 'Awhimai Fraser', 'Khaleesi Lambert-Tsuda', 'Temuera Morrison']::TEXT[], certification_origin = 'US: PG', updated_at = NOW() WHERE id = 'a1000000-0000-0000-0000-000000000008'::UUID;

