  v.id, v.tmdb_id, v.title, v.original_title, v.description, v.overview_en,
  v.poster_url, v.backdrop_url, v.trailer_url, v.director, v.cast_members,
  v.genres, v.duration_minutes, v.release_date, v.age_rating, v.certification_origin,
  v.rating, v.status
FROM (VALUES
  ('2134ccc5-6029-5d8b-bb9f-5bfdc47f6b3a'::UUID, 567973, 'Hai Phượng', 'Hai Phượng', 'Hai Phượng kể về cuộc hành trình đầy gay cấn và gian của khi người mẹ vùng quê tìm cách cứu con mình thoát khỏi đường dây bắt cóc khổng lồ. Không tấc sắc trong tay, người phụ nữ thân cô thế cô làm sao chống lại bọn xã hội đen tàn ác để giành lại nguồn sống của đời mình?', 'When a little girl is kidnapped by a trafficking ring, they soon find they messed with the wrong child. Her mother, a notorious former gang leader, is close on their trail and will go to any lengths to bring her child home.', 'https://image.tmdb.org/t/p/w780/otvxdOzeAc9RVMjEZCuExPhHuH2.jpg', 'https://image.tmdb.org/t/p/w1280/jXc41btarmyCRM9WMDzJ4b0zpRW.jpg', 'https://www.youtube.com/watch?v=SXiWz0yLLdE', 'Lê Văn Kiệt', ARRAY['Ngô Thanh Vân', 'Phan Thanh Nhiên', 'Phạm Anh Khoa', 'Thanh Hoa', 'Mai Cát Vi', 'Thanh Hiền', 'Pompatama', 'Lê Trang']::TEXT[], ARRAY['Hành Động', 'Chính Kịch', 'Giật Gân']::TEXT[], 100, '2019-02-22', NULL, 'US: NC-17', 6.6, 'ended'),
  ('741d3819-3425-55df-86be-19224d2c9f6e'::UUID, 293644, 'Băng Nhóm Của Top Cat', 'Don Gato: El Inicio de la Pandilla', 'Top Cat đã tìm được cách quyến rũ trái tim của các bạn! Bạn đã bao giờ tự hỏi cội nguồn của chú mèo này? Top Cat Begins sẽ tiết lộ nguồn gốc của tất cả những điều bạn biết về vị anh hùng hài hước này. Cuộc phiêu lưu tiếp theo điên rồ đến nỗi bạn phải tận mắt chứng chiến mới có thể tin.', 'Top Cat and his new feline friend hatch a scheme to steal from the fearful Mr. Big.', 'https://image.tmdb.org/t/p/w780/71h3zDCJwhmmOg8gWHRGAgfy79c.jpg', 'https://image.tmdb.org/t/p/w1280/ul1YQyy7KNGUPvhrDmb1W81QpY9.jpg', 'https://www.youtube.com/watch?v=YGdDihSGhUY', 'Andrés Couturier', ARRAY['Rául Anaya', 'Mauricio Pérez', 'Octavio Rojas', 'Gerardo Alonso', 'Jesús Guzmán', 'Mario Filio', 'Miguel Ángel Ghigliazza', 'Ricardo Tejedo']::TEXT[], ARRAY['Hài', 'Hoạt Hình', 'Gia Đình']::TEXT[], 89, '2015-10-30', NULL, 'IE: PG', 6.8, 'ended'),
  ('d6a32f54-4784-5bc0-8dd2-90b77cdfa82a'::UUID, 36266, 'Xích lô', 'Xích lô', 'Bộ phim lấy bối cảnh của Thành phố Hồ Chí Minh, kể về câu chuyện một anh thanh niên làm nghề lái xe xích lô, vì khó khăn mưu sinh mà phải tham gia vào một băng đảng tội ác. Từ đó anh phải sống trong sự dằn vặt và sợ hãi, nhiều lần tính chuyện rút chân khỏi băng đảng nhưng đều thất bại.', 'Follows a young cyclo driver on his poverty-driven descent into criminality in modern-day Ho Chi Minh City. The boy''s struggles to scratch out a living for his two sisters and grandfather in the mean streets of the city lead to petty crime on behalf of a mysterious Madame from whom he rents his cyclo.', 'https://image.tmdb.org/t/p/w780/mdOsnSVTLwHMEH1juOLMiwXcO5o.jpg', 'https://image.tmdb.org/t/p/w1280/bcSj4j8CfPRCHetc3pHhE1cHXU8.jpg', 'https://www.youtube.com/watch?v=xqPxeyfzOd4', 'Trần Anh Hùng', ARRAY['Le Van Loc', 'Lương Triều Vỹ', 'Như Quỳnh', 'Hoàng Phúc', 'Ngo Quang Hai', 'Tuyết Ngân', 'Doan Viet Ha', 'Bùi Hoàng Huy']::TEXT[], ARRAY['Chính Kịch', 'Tội Phạm']::TEXT[], 123, '1995-09-27', NULL, 'US: R', 6.9, 'ended'),
  ('4b678c1b-ccfa-5f38-aef0-13181786bad6'::UUID, 544812, 'Vợ Ba', 'Vợ ba', 'Người vợ ba lấy bối cảnh vùng thôn quê Việt Nam cuối thế kỷ 19. Nội dung phim xoay quanh câu chuyện về cô gái tên Mây (Nguyễn Phương Trà My thủ vai) được gả làm vợ ba cho một gia đình giàu có. Tưởng như bắt đầu một cuộc sống sung túc, đầy đủ, cô gái trẻ không ngờ mình bị lôi vào một cuộc tranh đấu ngầm trong gia đình mới với vợ cả và vợ hai để có được vị trí quan trọng ở nhà chồng.  Dựa trên những câu chuyện có thật về thân phận người phụ nữ Việt Nam trong xã hội xưa, phim cũng đề cập đến các vấn đề của xã hội lúc đó như hôn nhân sắp đặt, tục đa thê, trọng nam khinh nữ.', 'Though only 14 years old, May is selected to be the third wife of a wealthy landowner. Her new home seems idyllic, her husband favours her, and she quickly becomes pregnant with what she is certain will be the desired male progeny. But trouble is quietly brewing: she witnesses a forbidden tryst that will spark a chain reaction of misfortunes — and stir in May urges that until now had been dormant.', 'https://image.tmdb.org/t/p/w780/lFP2MX4YZngLSGo8HErp8v6BJGW.jpg', 'https://image.tmdb.org/t/p/w1280/xjscUUYPSJ6i4RDouqCXNWfAq7O.jpg', 'https://www.youtube.com/watch?v=P7CSaxXFRkA', 'Ash Mayfair', ARRAY['Phương Trà My', 'Tran Nu Yen Khe', 'Lê Vũ Long', 'Như Quỳnh', 'Maya', 'Lâm Thanh Mỹ', 'Mai Cát Vi', 'Nguyễn Thanh Tâm']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 96, '2019-01-11', NULL, 'US: R', 6.5, 'ended'),
  ('f36ea5fd-2df2-523b-a6b0-a152587c6a23'::UUID, 821937, '578: Phát Đạn Của Kẻ Điên', '578: Phát Đạn Của Kẻ Điên', 'Hùng, một người cha sẵn sàng đánh đổi mọi thứ, thậm chí đặt mạng sống của mình vào hiểm nguy trong cuộc truy đuổi đơn độc nhưng vô cùng khốc liệt với kẻ ác để tìm lại công lý cho cô con gái bé nhỏ của mình. Nhưng điều anh không ngờ rằng phía sau kẻ ác đó lại là cả một thế lực ngầm …', NULL, 'https://image.tmdb.org/t/p/w780/cPTphSqJ0dF0EPeeAR1qeeNbMPV.jpg', 'https://image.tmdb.org/t/p/w1280/6a3aiSYNqABoV1Fq8n10LMOBxhH.jpg', 'https://www.youtube.com/watch?v=NPFxwf3MuAQ', 'Lương Đình Dũng', ARRAY['Alexandre Nguyen', 'Thanh Thảo', 'H''Hen Niê', 'Hoàng Phúc', 'Ngọc Tình', 'Tuấn Hạc', 'Jessica Minh Anh', 'Thảo Tâm']::TEXT[], ARRAY['Hành Động', 'Giật Gân']::TEXT[], 95, '2022-05-20', NULL, 'DE: 16', 6, 'ended'),
  ('8dfe0c40-742a-5b4b-9eff-9a2e1418807d'::UUID, 988667, 'Thanh Sói', 'Thanh Sói: Cúc Dại Trong Đêm', 'Bộ phim Thanh Sói là một tác phẩm điện ảnh hành động thuộc "vũ trụ" Hai Phượng. Phim là câu chuyện về thời trẻ của nữ trùm Thanh Sói với hướng khai thác thú vị và niềm tin rằng tất cả nhân vật xấu đều xuất phát từ lý do nào đó. Nỗi đau có thể thay đổi tất cả.', NULL, 'https://image.tmdb.org/t/p/w780/virYZ52mRzDES9y9qEhSeA9SNNC.jpg', 'https://image.tmdb.org/t/p/w1280/VfSmdfBgwwAJOTfSlXD0HZx5ju.jpg', 'https://www.youtube.com/watch?v=kUc4LuzPEDE', 'Ngô Thanh Vân', ARRAY['Đồng Ánh Quỳnh', 'Tóc Tiên', 'Rima Thanh Vy', 'Ngô Thanh Vân', 'Thuận Nguyễn', 'Song Luân', 'Gi A Nguyễn', 'Phan Thanh Nhiên']::TEXT[], ARRAY['Hành Động', 'Chính Kịch', 'Giật Gân']::TEXT[], 109, '2022-12-30', 'T18', 'KR: 19', 7, 'ended'),
  ('34824531-0c89-5d2b-96e9-441bb6443415'::UUID, 34899, 'Mùa hè chiều thẳng đứng', 'Mùa hè chiều thẳng đứng', 'Mùa hè chiều thẳng đứng kể về câu chuyện gia đình của 3 chị em gái: Sương (Như Quỳnh), Khanh (Lê Khanh) và Liên (Trần Nữ Yên Khê) quanh ngày giỗ mẹ tại Hà Nội.', 'Hanoi comes across almost picture-perfect in director Tran Anh Hung''s beautiful, elegiac tale about the lives and loves of three Vietnamese sisters. A mood characteristic of Hung''s films is set early on with the vivid sounds of birds, insects and water and the way the lighting enhances the subtle use of color. They all combine to gem-like effect here.', 'https://image.tmdb.org/t/p/w780/bPNqPKauazzh1MLcikMaLO7KjL3.jpg', 'https://image.tmdb.org/t/p/w1280/cIlvOmtoHSAuvY4oBKGxBvnDuoe.jpg', 'https://www.youtube.com/watch?v=4ma2Bt8c1Kc', 'Trần Anh Hùng', ARRAY['Tran Nu Yen Khe', 'Như Quỳnh', 'Lê Khanh', 'Ngo Quang Hai', 'Chu Hùng', 'Mạnh Cường', 'Le Tuan Anh', 'Doan Viet Ha']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn']::TEXT[], 112, '2000-05-24', NULL, 'US: PG-13', 6.6, 'ended'),
  ('2a4c78b0-4027-520d-b18e-5c075220fccb'::UUID, 947890, 'Bóng Ðè', 'Bóng Ðè', 'Sau khi trải qua bi kịch gia đình, một góa phụ tên Thanh đã chuyển hai cô con gái của mình đến một ngôi nhà tổ tiên đã tồn tại hàng thế kỷ. Cả hai cô con gái đều bị chứng tê liệt khi ngủ và những cơn ác mộng ban đêm. Người cha tìm đến sự giúp đỡ của một nhà tâm lý học địa phương, nhưng những bí mật và ảo giác rùng rợn cuối cùng đã chứng minh rằng mọi thứ không như vẻ bề ngoài trong ngôi nhà cổ của gia đình.', 'After suffering a family tragedy, a widower named Thanh moves his two daughters to a centuries-old ancestral home. Both daughters fall prey to sleep paralysis and night terrors. Their father seeks the help of a local psychologist, but chilling secrets and visions eventually prove that all is not what it seems in the old family house.', 'https://image.tmdb.org/t/p/w780/nVSpK8qzaKUyLDUhIZvgfSGmM1u.jpg', 'https://image.tmdb.org/t/p/w1280/aJAJ31F6PIUHjogoRbn5y1siYEl.jpg', 'https://www.youtube.com/watch?v=FWKCoBpmp-U', 'Lê Văn Kiệt', ARRAY['Lâm Thanh Mỹ', 'Quang Tuấn', 'Mai Cát Vi', 'Diệu Nhi']::TEXT[], ARRAY['Kinh Dị']::TEXT[], 101, '2022-03-24', NULL, 'US: NR', 6.4, 'ended'),
  ('a1f28a37-e18b-5c23-b165-d64813e60eb8'::UUID, 1114816, 'Bên Trong Vỏ Kén Vàng', 'Bên Trong Vỏ Kén Vàng', 'Bên Trong Vỏ Kén Vàng được phát triển từ phim ngắn Hãy thức tỉnh và sẵn sàng (Stay Awake, Be Ready) của Phạm Thiên Ân kể về Thiện, người em rể phải mang xác chị dâu và cháu trai tên Đạo về quê trao lại cho anh trai, sau khi chị mình qua đời trong một tai nạn xe. Hành trình của Thiện bật lên trong anh nhiều suy ngẫm về ý nghĩa của cuộc sống.', 'After a Vietnamese woman dies in a car crash in Saigon, her brother-in-law and her young son transport her body back to the former’s hometown in rural Vietnam, where they plan to give her a funeral.', 'https://image.tmdb.org/t/p/w780/vQtSctHhbDuzzHeZ7CUMem5YR2M.jpg', 'https://image.tmdb.org/t/p/w1280/z94oO4k3bvOrtI5b3Dksv7k3M3y.jpg', 'https://www.youtube.com/watch?v=IqdAUaqbhmk', 'Phạm Thiên Ân', ARRAY['Le Phong Vu', 'Nguyen Thinh', 'Nguyen Thi Truc Quynh', 'Vu Ngoc Manh', 'Dylan Besseau', 'Phi Điểu', 'Nguyen Van Lu''u', 'Mạnh Cường']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 179, '2023-08-11', NULL, 'KR: 15', 6.3, 'ended'),
  ('73c85cda-a64f-5815-b8a7-a4aa6e6b2e62'::UUID, 1013665, 'Đảo Độc Đắc - Tử Mẫu Thiên Linh Cái', 'Đảo Độc Đắc - Tử Mẫu Thiên Linh Cái', '“Đảo độc đắc - Tử mẫu Thiên linh cái” tiếp tục gieo rắc nỗi ám ảnh lẫn loạt dấu hỏi lớn về một trong những loại bùa ngải đáng sợ của vùng Đông Nam Á.  Ai mới thực sự là người đang “ẩn nấp” đằng sau gương mặt tà ác, quỷ dị và nắm giữ những bí mật kinh hoàng? Một hòn đảo chết chóc cùng sự xuất hiện bí ẩn rợn người của nhân ngư kì quái có liên quan gì đến loại bùa ngải tàn bạo và kinh hãi này?', NULL, 'https://image.tmdb.org/t/p/w780/A6PH1Jq5Jjq2UgcKVMQvF474IiA.jpg', 'https://image.tmdb.org/t/p/w1280/jEbbQWm9vusMDqUyqdT4yOc2i3T.jpg', 'https://www.youtube.com/watch?v=C_shKncUMEI', 'Lê Bình Giang', ARRAY['Trần Nghĩa', 'Trần Tiểu Vy', 'Trần Phong', 'Minh Dự', 'Sở Lam', 'Tân Trề', 'Lê Huỳnh', 'Hoàng Yến Chibi']::TEXT[], ARRAY['Giật Gân', 'Hành Động', 'Chính Kịch', 'Kinh Dị']::TEXT[], 92, '2022-12-23', 'T18', 'VN: C18', 6.1, 'ended'),
  ('22775c56-5cef-5f35-b0fb-68260132d9a8'::UUID, 682201, 'Vô Diện Sát Nhân', 'Vô Diện Sát Nhân', 'Lâu rồi bác sĩ Phương Anh không được ngủ ngon. Giữa đêm, cô thường thức giấc vì những cơn ác mộng có nội dung tương tự. Trong mơ bác sĩ luôn thấy một kẻ không lộ rõ mặt, bám theo cô với con dao nhọn hoắt trên tay hòng cướp mạng. Cơn ác mộng lặp đi lặp lại khiến cuộc sống vốn hoàn hảo của Phương Anh đã bị đảo lộn hoàn toàn. Thế nhưng, điều kinh hoàng hơn còn xảy ra, khi tên Vô Diện Sát Nhân bước ra đời thực và truy sát cô.', NULL, 'https://image.tmdb.org/t/p/w780/eyVcHgdCqlgv9ZMU1jhTATpvcz5.jpg', 'https://image.tmdb.org/t/p/w1280/2lCSWwW0Xr8mqlaN6CJpa4B6Oar.jpg', 'https://www.youtube.com/watch?v=8efH5QWJ334', 'Đinh Công Hiếu', ARRAY['Phương Anh Đào', 'Quách Ngọc Tuyên', 'Hiếu Nguyễn', 'Oanh Kiều', 'Hoàng Phúc', 'Steven Nguyễn']::TEXT[], ARRAY['Kinh Dị']::TEXT[], 87, '2022-08-26', 'T18', 'VN: C18', 6.7, 'ended'),
  ('f64712f1-d4c1-5a0e-a4bd-ecd7786ebad2'::UUID, 413416, 'Cô Hầu Gái', 'Cô Hầu Gái', 'Năm 2007, các nhà làm phim Việt Nam đã có một bước đi khá táo bạo khi hợp tác cùng điện ảnh Hàn Quốc trong một bộ phim kinh dị được đầu tư rất công phu mang tên “Mười”, sự thành công của Muoi chính là chất xúc tác quan trọng để những sản phẩm hợp tác tiếp theo được ra đời, trong đó mới đây nhất chính là Cô Hầu Gái của đạo diễn Derek Nguyen. Ra mắt vào năm 2016, có một điểm khá thú vị khi tên của phim trùng với tên của một sản phẩm điện ảnh của điện ảnh Hàn cũng phát hành trong năm 2016, một “siêu phẩm” 18+ của đạo diễn Chan-wook Park với vai nữ chính được đảm nhiệm bởi Min-hee Kim, chính vì vậy mà để phân biệt, chúng ta sẽ gọi The Housemaid là Cô Hầu Gái (bản Việt Nam).', 'When an orphaned Vietnamese girl is hired to be a housemaid at a haunted rubber plantation in 1953 French Indochina, she unexpectedly falls in love with the French landowner and awakens the vengeful ghost of his dead wife... who is out for blood.', 'https://image.tmdb.org/t/p/w780/uDS7ZNsMViDSXAb37txP1AL5Rcb.jpg', 'https://image.tmdb.org/t/p/w1280/b5SnA6t9syc00FgtdP9ybrDfWC2.jpg', 'https://www.youtube.com/watch?v=TPM0OnAIobk', 'Derek Nguyen', ARRAY['Nhung Kate', 'Jean-Michel Richaud', 'Kim Xuân', 'Svitlana Kovalenko', 'Huỳnh Kiến An', 'Rosie Fellner', 'Phi Phung', 'Linh Sơn']::TEXT[], ARRAY['Lãng Mạn', 'Kinh Dị']::TEXT[], 105, '2016-09-16', NULL, NULL, 5.9, 'ended'),
  ('623c486e-5c3d-5ee2-9901-71e57d4c618c'::UUID, 55208, 'Bẫy Rồng', 'Bẫy Rồng', 'Câu chuyện trong Bẫy rồng được mở đầu đầy ẩn dụ về những mối quan hệ lắt léo trong giới giang hồ, ở đó kẻ đặt bẫy người khác có khi cũng chính là con mồi, và ngược lại.Câu chuyện bắt đầu khi một băng nhóm giang hồ do Trinh, biệt danh Phượng Hoàng (Ngô Thanh Vân) nhận nhiệm vụ giành giật một chiếc máy tính xách tay có khả năng xâm nhập và điều khiển vệ tinh Vinasat 1, đang nằm trong tay một băng mafia người Pháp – những tên này tới Sài Gòn với mục đích rao bán chiếc máy tính xách tay trên với số tiền khổng lồ.Để thực hiện phi vụ, Trinh chiêu mộ một số tay giang hồ cộm cán – trong đó có Quân, biệt danh Hổ (Johnny Trí Nguyễn) và mua vũ khí từ các băng đảng khác. Những cuộc xung đột nảy lửa diễn ra ngay từ đầu bởi ...', 'Trinh, a mercenary, must complete a series of organized crime jobs for her boss in order to win the release of her kidnapped daughter. She hires several mercenaries to help, including Quan, who she becomes attracted to. Trinh and Quan''s relationship becomes complicated as it becomes evident that their motivations are not the same.', 'https://image.tmdb.org/t/p/w780/ArtKpRv3pqwISJp1yEbUJA8w2ZP.jpg', 'https://image.tmdb.org/t/p/w1280/33Aymd6PReoLuJXOzcXrj7tSVj2.jpg', 'https://www.youtube.com/watch?v=K_XzuDju_E0', 'Lê Thanh Sơn', ARRAY['Johnny Trí Nguyễn', 'Ngô Thanh Vân', 'Hiếu Hiền', 'Hoàng Phúc', 'Lâm Minh Thắng', 'Nguyễn Hậu', 'Isabelle Du']::TEXT[], ARRAY['Hành Động', 'Giật Gân', 'Lãng Mạn']::TEXT[], 90, '2009-12-09', NULL, 'KR: 청소년 관람불가', 5, 'ended'),
  ('9a716dfd-6c33-5949-ba2f-dd0a4f77db66'::UUID, 1057856, 'Chị Chị Em Em 2', 'Chị Chị Em Em 2', 'Dựa trên giai thoại mỹ nhân Ba Trà & Tư Nhị, Chị Chị Em Em 2 xoay quanh giai đoạn 2 đệ nhất mỹ nhân Ba Trà và Tư Nhị gặp gỡ nhau, từ đó tái hiện cuộc sống hoa lệ nhiều góc khuất tại Sài thành cách đây một thế kỷ...', NULL, 'https://image.tmdb.org/t/p/w780/XV6ecel5ermCG6ofctciMAy6pk.jpg', 'https://image.tmdb.org/t/p/w1280/mr3yPBo7KmUTU6NyshEc25JpOl8.jpg', 'https://www.youtube.com/watch?v=bd9gCumR8TY', 'Vũ Ngọc Đãng', ARRAY['Minh Hằng', 'Ngọc Trinh', 'Ngọc Nga', 'Lê Giang', 'Kim Phương', 'Trung Dân', 'Công Ninh', 'Emma Lê']::TEXT[], ARRAY['Giật Gân', 'Chính Kịch']::TEXT[], 115, '2023-10-12', NULL, 'BR: 14', 7, 'ended'),
  ('d2e772e2-1813-55d7-8ad5-1555601bef3c'::UUID, 361996, 'Tôi Thấy Hoa Vàng Trên Cỏ Xanh', 'Tôi Thấy Hoa Vàng Trên Cỏ Xanh', 'Lấy bối cảnh tại vùng quê Việt Nam, bộ phim kể về câu chuyện tình cảm ngây thơ trong sáng, tình bạn đẹp và tình làng xóm.', NULL, 'https://image.tmdb.org/t/p/w780/6WGjbxZtlpbQ55qK6t50DzddbFE.jpg', 'https://image.tmdb.org/t/p/w1280/scpWtLGk723uoc2Ke8cFvvYEKpB.jpg', 'https://www.youtube.com/watch?v=wmjiCP6R-7I', 'Victor Vũ', ARRAY['Thịnh Vinh', 'Trọng Khang', 'Lâm Thanh Mỹ', 'My Anh', 'Mai Thế Hiệp', 'Cong Huan', 'Duc Sang', 'Mai Trần']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 103, '2015-10-02', NULL, 'JP: G', 6.9, 'ended'),
  ('0d9b9964-37c4-5bf8-95ac-89379f976685'::UUID, 143653, 'Thiên Mệnh Anh Hùng', 'Thiên Mệnh Anh Hùng', 'Sau vụ thảm án Lệ Chi viên, gia tộc Nguyễn Trãi chỉ có một người may mắn sống sót. Đó là một đứa bé 5 tuổi, cháu nội Nguyễn Trãi, được một gia tướng đem đi trốn thật xa để tránh sự truy sát của phe đảng Tuyên Từ Hoàng thái hậu. Vua Lê Nhân Tông lên ngôi lúc mới 2 tuổi. Tất cả mọi việc trong triều đều do Tuyên Từ Hoàng thái hậu nắm quyền nhiếp chính. 16 năm sau, đứa bé năm xưa may mắn thoát chết, nay đã là một thanh niên 21 tuổi khôi ngô, cường tráng và tinh thông võ nghệ mang tên mới là Trần Nguyên Vũ. Sau khi được ân sư cho biết thân thế thật sự, Nguyên Vũ đã xuống núi và bắt đầu cuộc phiêu lưu hấp dẫn và nguy hiểm vào sâu trong triều đình với quyết tâm trả thù kẻ đã hại gia đình và minh oan cho dòng tộc.', NULL, 'https://image.tmdb.org/t/p/w780/9UGmOCzmBjxYl1Er3Ot7Tt6CbI1.jpg', 'https://image.tmdb.org/t/p/w1280/ypoSMjYcDj7ve4TFvpczbr016h3.jpg', 'https://www.youtube.com/watch?v=kiTeyH3xASE', 'Victor Vũ', ARRAY['Huỳnh Đông', 'Midu', 'Khương Ngọc', 'Minh Thuận', 'Vân Trang', 'Dũng Nhi', 'Van Anh', 'Kim Hiền']::TEXT[], ARRAY['Phiêu Lưu', 'Chính Kịch', 'Hành Động']::TEXT[], 90, '2012-01-20', NULL, 'JP: R18+', 6.3, 'ended'),
  ('4f3809ad-bcef-5bb2-a1e8-96a4d449ab62'::UUID, 846586, 'Trong lòng đất', 'Trong lòng đất', 'Phim xoay quanh hai thợ mỏ là Nam và người yêu là Việt phải làm việc bên dưới lòng đất sâu 300 m, nơi được xem là chứa đầy nguy hiểm và bóng tối bao trùm. Lúc này, Nam không muốn tiếp tục tương lai của bản thân mình ở một nơi chỉ quanh quẩn là than đá nên đã nhờ những kẻ buôn người đưa mình đến phương Tây để đổi đời. Trước khi rời đi, Nam cùng với Việt và mẹ của anh đã đi tìm hài cốt của cha mình khi linh hồn cha anh là một người lính của Quân đội nhân dân Việt Nam báo mộng giấc mơ của mẹ. Tuy nhiên, sau cùng, cuộc tìm kiếm của họ lại không mang về kết quả nào. Sau đó, cả hai người phải quay về khu mỏ và bị mắc kẹt lại đây sau cơn mưa dữ dội. Tại đây, Nam chợt nhìn thấy được tương lai sắp tới của mình, bị nhốt trong thùng xe tải, trong bóng tối, trong cái nóng bức và ngột ngạt của quá khứ. Nam và Việt cả hai vẫn nằm cạnh nhau, cởi trần, nóng bức.', 'In the depths of the underground coal mines, where danger awaits and darkness prevails, Nam and Việt, both young miners, cherish fleeting moments, knowing that one of them will soon leave for a new life across the sea.', 'https://image.tmdb.org/t/p/w780/axtvB6qoORMZQ2qPZdaFcBOM8g3.jpg', 'https://image.tmdb.org/t/p/w1280/5b3azqxrk2T2o14rK8shAFmXcox.jpg', 'https://www.youtube.com/watch?v=gAnrjuST6wo', 'Truong Minh Quy', ARRAY['Phạm Thanh Hải', 'Bảo Định', 'Nguyên Thį Nga', 'Lê Viêt Tųng', 'Ngân Khánh', 'Lê Hồ Lan', 'Trịnh Văn Hồng', 'Võ Thị Kim Thúy']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 124, '2024-09-25', NULL, 'US: NR', 7, 'ended'),
  ('b7e705dc-9cb1-5090-b463-6b7cdeef52c6'::UUID, 17075, 'Cú và chim se sẻ', 'Cú và chim se sẻ', 'Thúy, một cô bé 10 tuổi mồ côi cha mẹ, làm việc trong xưởng thủ công của ông chú khắc nghiệt. Sau một lần làm sai bị ông chú mắng vô dụng và tâm hồn treo ngược cành cây, Thúy trốn nhà bỏ lên Sài Gòn và kiếm sống bằng nghề bán postcards và sau đó là hoa hồng ở các tụ điểm du lịch hay nhậu nhẹt ở trung tâm thành phố.  Và rồi, trong những lúc lang thang khắp thành phố, Thúy kết bạn với Hải, một người trông coi sở thú đang thất tình vì bị người yêu chối bỏ, và Lan, nữ tiếp viên hàng không xinh đẹp nhưng cũng không hạnh phúc khi yêu một đồng nghiệp đã có gia đình. Ba tâm hồn cô đơn lạc lõng trong thành phố này dần dần kết nối với nhau, không những thế, Thúy còn làm "bà mai" để kết nối hai người lớn lại với nhau.', 'In modern-day Saigon, three lonely strangers form a unique family as a ten-year old orphan plays matchmaker to a zookeeper and a beautiful flight attendant.', 'https://image.tmdb.org/t/p/w780/zHowwWgNrZzFucNKW6Ufcoan5y7.jpg', 'https://image.tmdb.org/t/p/w1280/fG1PGkvZV1Br1qpPIMAPQZ0IKc7.jpg', 'https://www.youtube.com/watch?v=mMhrg0PUK3Q', 'Stephane Gauger', ARRAY['Cat Ly', 'Lê Thế Lữ', 'Han Thi Pham', 'Nguyễn Hậu', 'Trọng Hải', 'Teresa Michelle Lee', 'Hoang Long', 'Bùi Thị Noan']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 97, '2008-11-06', NULL, 'KR: 12', 6.3, 'ended'),
  ('b61384d6-7e2d-511b-8660-a034dc3bbc3b'::UUID, 893030, 'Những Đứa Trẻ Trong Sương', 'Những Đứa Trẻ Trong Sương', 'Phim kể câu chuyện của cô bé Má Thị Di, người Mông, 14 tuổi. Một ngày mùa xuân, Di được cậu bé Vang trạc tuổi chọn làm vợ. Di cố gắng chống lại sự sắp đặt theo truyền thống. Mẹ của em mâu thuẫn giữa việc tôn trọng tục lệ hay bảo vệ hạnh phúc của con. Trong khi bà nội và bố cho Di quyền tự quyết định.', NULL, 'https://image.tmdb.org/t/p/w780/se8AYBla3ZmfV6NrSGzBjZp59J0.jpg', 'https://image.tmdb.org/t/p/w1280/seTn1MqKEArbwnqQLVq5HUCjlNz.jpg', 'https://www.youtube.com/watch?v=C2dVG2xHRVg', 'Hà Lệ Diễm', ARRAY['Má Thị Di', 'Châu Thị Xay', 'Má A Pho', 'Má Thị La', 'Má A Cớ', 'Giàng Thị La', 'Giàng Thị Cở', 'Giàng Thị Máy']::TEXT[], ARRAY['Phim Tài Liệu']::TEXT[], 92, '2022-05-07', NULL, 'KR: 12', 6.9, 'ended'),
  ('d0f3debe-00b1-55d4-8da9-0a8f5e5c1a91'::UUID, 618010, 'Mắt Biếc', 'Mắt Biếc', 'Bộ phim xoay quanh mối tình đơn phương của Ngạn với Hà Lan, cô bạn gái có cặp mắt hút hồn nhưng cá tính bướng bỉnh. Một chuyện tình nhiều cung bậc, từ ngộ nghĩnh trẻ con, rồi tình yêu thuở học trò trong sáng, trải qua bao biến cố, trở thành một cuộc "đuổi hình bắt bóng" buồn da diết nhưng không nguôi hi vọng. Câu chuyện càng trở nên éo le hơn khi Trà Long - con gái của Hà Lan lớn lên lại nhen nhóm một tình yêu như thế với Ngạn.', 'Ngạn''s unrequited love for Hà Lan, a stubborn girl with dreamy eyes is a love story with many facets, from childish playfulness and innocent high school romance to a poignant chase that, despite numerous events, becomes a bittersweet pursuit of love, yet one that never loses hope. The story becomes even more complicated when Trà Long, Hà Lan''s daughter, grows up and develops feelings for Ngạn.', 'https://image.tmdb.org/t/p/w780/aa7a3oVW3frg5HO2jBCiofX0eND.jpg', 'https://image.tmdb.org/t/p/w1280/DwTyJZKMH7rcJFDpQ5X3fZs6K9.jpg', 'https://www.youtube.com/watch?v=MNm77lvTfi4', 'Victor Vũ', ARRAY['Trần Nghĩa', 'Trúc Anh', 'Trần Phong', 'Đỗ Khánh Vân', 'Thảo Tâm', 'Hưng Võ', 'Phạm Đình Thái Ngân', 'Lâm Bảo Danh']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn']::TEXT[], 117, '2019-12-20', NULL, NULL, 6.7, 'ended'),
  ('954747bd-ede6-5a17-bbc6-50d5c972bd09'::UUID, 637536, 'Chị Chị Em Em', 'Chị Chị Em Em', 'Sự kết hợp chưa từng có giữa Thanh Hằng và Chi Pu cùng câu chuyện ly kỳ về yêu - hận - tình - thù đằng sau hai người phụ nữ xinh đẹp chắc chắn sẽ khiến bạn tò mò.', 'This is a psychological film exploring the love story revolving around two beautiful women - Thien Kim and Bao Nhi. Face to face in a game where only one person wins, when the happiness of a small home is about to be swept away by a storm, who will fiercely fight for what they want and who will resign to keep peaceful?', 'https://image.tmdb.org/t/p/w780/2bAjCwJ1sZMtpr1GywZSboKqXW1.jpg', 'https://image.tmdb.org/t/p/w1280/kqq9zk5237TEGs4LKTCrIFKUem4.jpg', 'https://www.youtube.com/watch?v=HMtYJ7FQKg4', 'Kathy Uyen', ARRAY['Thanh Hằng', 'Chi Pu', 'Lãnh Thanh', 'Kathy Uyen']::TEXT[], ARRAY['Giật Gân', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 94, '2019-12-18', NULL, 'KR: 15', 5.5, 'ended'),
  ('1e89b2ee-480a-55cb-b22a-44000a37b154'::UUID, 1210973, 'Mai', 'Mai', 'Mai, một nhân viên massage 37 tuổi có quá khứ nhiều vết xước, sống khép kín và bị xã hội dị nghị. Cuộc sống cô thay đổi khi gặp Dương - chàng trai trẻ đào hoa, quyết tâm chinh phục cô. Tình yêu cháy bỏng của họ gặp sóng gió bởi định kiến xã hội, khoảng cách tuổi tác và nỗi sợ hãi của chính Mai.', NULL, 'https://image.tmdb.org/t/p/w780/2nF8xD200rcDawuCg5ObxxqA2fC.jpg', 'https://image.tmdb.org/t/p/w1280/zZ6nRdNQNxRnZ1LQ2ttPBZl9AXV.jpg', 'https://www.youtube.com/watch?v=Yz96EBNwMGw', 'Trấn Thành', ARRAY['Phương Anh Đào', 'Tuấn Trần', 'Trấn Thành', 'Hồng Đào', 'Uyển Ân', 'Ngọc Giàu', 'Việt Anh', 'Kim Phương']::TEXT[], ARRAY['Lãng Mạn', 'Chính Kịch']::TEXT[], 131, '2024-02-10', NULL, 'GB: 15', 7.3, 'ended'),
  ('4cb68bec-278f-586e-8234-c79b03af4a31'::UUID, 386370, 'Quyên', 'Quyên', 'Quyên là bộ phim được chuyển thể từ cuốn tiểu thuyết cùng tên của nhà văn Nguyễn Văn Thọ. Chuyện phim kể về cuộc đời của cô gái Hà Nội tên Quyên trong thời kỳ hỗn mang khi bức tường Berlin sụp đổ.', NULL, 'https://image.tmdb.org/t/p/w780/n1aExcEG2YoVoxPSUsMEzu0PtSy.jpg', 'https://image.tmdb.org/t/p/w1280/n0b5yZjbzRnfczaErHNWJITIa4r.jpg', NULL, 'Nguyễn Phan Quang Bình', ARRAY['Trần Bảo Sơn', 'Gary Daniels', 'Vũ Ngọc Anh', 'David Tran', 'Hiếu Nguyễn']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 90, '2015-06-19', NULL, NULL, 8.5, 'ended'),
  ('bc298c3c-c2d3-52b6-89dc-5291a66f0460'::UUID, 1312078, 'CÁM', 'CÁM', 'Cám - một cô gái sinh ra với khuôn mặt dị dạng do một lời nguyền truyền qua nhiều thế hệ. Cám bị cha mình xem như một vết nhơ của gia đình và bị đày xuống nhà sau, sống như người hầu và chịu đựng sự ngược đãi. Trong khi đó, người chị cùng cha khác mẹ của cô là Tấm nhận được tình yêu thương và sự nuông chiều của cha. Mặc dù được bao bọc, Tấm vẫn cố gắng chăm sóc Cám, nhưng lòng căm thù của Cám ngày càng sâu sắc do sự lạnh lùng của gia đình.', NULL, 'https://image.tmdb.org/t/p/w780/61t9rICHV9jZJtf4HcUJUP7och0.jpg', 'https://image.tmdb.org/t/p/w1280/54PQfX2WYGzV3o9tv3YUcRoO5O7.jpg', 'https://www.youtube.com/watch?v=gW0b5Bsa34o', 'Trần Hữu Tấn', ARRAY['Lâm Thanh Mỹ', 'Rima Thanh Vy', 'Thuý Diễm', 'Trần Doãn Hoàng', 'Ngô Hải Nam', 'Quốc Cường', 'Nguyễn Thị Ngọc Hiệp', 'Hạnh Thúy']::TEXT[], ARRAY['Kinh Dị']::TEXT[], 122, '2024-09-20', NULL, 'KR: 15', 9, 'ended'),
  ('193cdf2e-2f6d-5aa4-939a-4692c6c7fb17'::UUID, 1573869, 'Mùi Phở', 'Mùi Phở', 'A story of generational conflict and the clash between tradition and modern life, centered on phở—an icon of Vietnamese cuisine. Beneath the disputes and disagreements, hidden truths gradually surface, unfolding a journey back to familial warmth through humor, wit, and charming moments.', 'A story of generational conflict and the clash between tradition and modern life, centered on phở—an icon of Vietnamese cuisine. Beneath the disputes and disagreements, hidden truths gradually surface, unfolding a journey back to familial warmth through humor, wit, and charming moments.', 'https://image.tmdb.org/t/p/w780/jYqoE2CDjSe3jKjHrCsPuvitfUe.jpg', 'https://image.tmdb.org/t/p/w1280/5Khb0mc2PEQTY5o2JbAORXmQ0Y7.jpg', 'https://www.youtube.com/watch?v=PfLNuXyLA4Q', 'Minh Beta', ARRAY['Thu Trang', 'Xuân Hinh', 'Quốc Tuấn', 'Hà Hương', 'Thanh Hương', 'Thanh Thanh Hiền', 'Chu Mạnh Cường', 'Hải Triều']::TEXT[], ARRAY['Gia Đình', 'Chính Kịch', 'Hài']::TEXT[], 111, '2026-02-17', NULL, 'DE: 12', 5, 'ended'),
  ('5b6fd6ad-0eca-5b9a-a4d9-393eb8513f08'::UUID, 1528577, 'Thỏ Ơi!!', 'Thỏ Ơi!!', 'Với tâm thế luôn mang đến những điều mới để cho khán giả của mình không nhàm chán, Thỏ Ơi!! - bộ phim điện ảnh thứ 4 của đạo diễn Trấn Thành hứa hẹn sẽ mang đến một màu sắc hoàn toàn khác biệt.', NULL, 'https://image.tmdb.org/t/p/w780/rWXJZWweOoDjZXLQuKSsHw14GaO.jpg', 'https://image.tmdb.org/t/p/w1280/wDUrTRRXh7DzhZtTI1YkAkTc89S.jpg', 'https://www.youtube.com/watch?v=4jHXsiMveEk', 'Trấn Thành', ARRAY['Trấn Thành', 'Pháo', 'LyLy', 'Pháp Kiều', 'Gil Le', 'Ali Hoàng Dương', 'BB Trần', 'Ngọc Diệp']::TEXT[], ARRAY['Lãng Mạn', 'Chính Kịch', 'Giật Gân']::TEXT[], 127, '2026-02-17', NULL, 'GB: 15', 7, 'ended'),
  ('932810ab-deee-568e-8f28-cf20f1fa721d'::UUID, 1293313, 'Gà Lavabo', 'Gà Lavabo', 'The 1968 USAID foreign exchange group of South Vietnamese students attempt to adjust to life in a turbulent United States.', 'The 1968 USAID foreign exchange group of South Vietnamese students attempt to adjust to life in a turbulent United States.', 'https://image.tmdb.org/t/p/w780/frLUxIleUIQtVXZsx1kdFtky9zS.jpg', NULL, NULL, 'Duy Đỗ', ARRAY['Duy Đỗ', 'Nana La', 'Trung To', 'Phúc Nguyễn', 'Jonathan Ly', 'Leslie Mai', 'Travis Hui', 'Thanh Đỗ']::TEXT[], ARRAY['Hài', 'Chính Kịch', 'Lịch Sử']::TEXT[], 100, '2027-03-04', NULL, 'US: NR', 0, 'coming_soon'),
  ('eba41201-655e-50bb-9237-19c4cf887c1a'::UUID, 637997, 'Ròm', 'Ròm', 'Lấy bối cảnh một khu chung cư cũ đang chờ giải tỏa tại Sài Gòn, Ròm kể câu chuyện về cuộc sống của những người dân lao động nơi đây. Họ đều chơi số đề với hy vọng kiếm được một khoản tiền lớn để đổi đời. Ròm là cậu bé làm “cò đề” để kiếm sống qua ngày, chuyên tư vấn cho người dân những con số may mắn để họ có cơ may trúng đề.', NULL, 'https://image.tmdb.org/t/p/w780/ta7x5lTDmzxxz3HScDyGoUucBGH.jpg', 'https://image.tmdb.org/t/p/w1280/usoBlCf6PKEpv9ypUdYfXQGYSB8.jpg', 'https://www.youtube.com/watch?v=AFLHDs1MUGw', 'Trần Thanh Huy', ARRAY['Trần Anh Khoa', 'Cát Phượng', 'Thanh Tú', 'Hải Triều', 'Mai Trần', 'Mai Thế Hiệp', 'Anh Tú Wilson', 'Wowy']::TEXT[], ARRAY['Chính Kịch', 'Hành Động']::TEXT[], 79, '2020-07-31', NULL, 'JP: G', 6.9, 'ended'),
  ('bb15575e-d4c0-586a-a769-e468aa067a96'::UUID, 111058, 'Sài Gòn Yo!', 'Saigon Yo!', 'Ôm ấp ước mơ thành vũ công múa lụa chuyên nghiệp, Mai rời Bạc Liêu lên Sài Gòn để thi vào trường múa nhưng không may thi trượt. Mai đành xin vào làm phụ việc cho một quán ăn và kết thân với Kim, cô bạn cá tính trong nhóm nhảy Hip hop Sai Gon Fresh. Họ quyết tâm đưa nhóm nhảy chiến thắng ở giải Samsung, nhưng vô số trở ngại bắt đầu nảy sinh, nhất là khi Kim gặp rắc rối trong tình yêu và xích mích với trưởng nhóm... Được đánh giá là thể hiện sinh động “những lát cắt” về Sài Gòn trên nền nhạc Hip hop, bộ phim về giới trẻ này đã đoạt giải Cánh Diều Bạc năm 2011 và mang về cho Quỳnh Hoa (vai Kim) giải “Nữ diễn viên chính xuất sắc”.', 'Mai, a ribbon dancer from the countryside arrives in Saigon and befriends Kim, a street dancer. A promise of a better life leads their dance crew to the big competition, but a romance with a rich kid threatens to derail Kim''s plans.', 'https://image.tmdb.org/t/p/w780/6XcFBkLxGjaVfOFWESfXzSivwSq.jpg', 'https://image.tmdb.org/t/p/w1280/5mzmG4u6jBBbISjAUjqRAGBKboH.jpg', 'https://www.youtube.com/watch?v=khEJD0GuXpk', 'Stephane Gauger', ARRAY['Khương Ngọc', 'Quỳnh Hoa', 'Elly Trần', 'Phan Tấn Thi', 'Vân Trang', 'Hà Hiền', 'Kim Xuân']::TEXT[], ARRAY['Âm Nhạc']::TEXT[], 106, '2011-04-22', NULL, NULL, 7, 'ended'),
  ('02060faf-269b-5261-b899-66c6d71e0795'::UUID, 1072055, 'Fanti', 'Fanti', 'Thế giới của cô diễn viên trẻ đảo lộn khi một kẻ ẩn danh đội lốt fan bước ra từ chiếc điện thoại và bắt đầu theo dõi, quấy phá, thậm chí đe doạ cuộc sống của cô.', 'Fanti is the never-ending nightmare of a social network hotgirl who aspires to become a famous actress. The appearance of a mysterious stalker, stalks and makes her life gradually dark. In addition to uncovering the mystery behind the perfectly beautiful face on social networks, the film also depicts the fears and pressures of young people who want to be recognized in front of their families and society.', 'https://image.tmdb.org/t/p/w780/ttwsCne3HemgAKnMR5z3MkNwhZA.jpg', 'https://image.tmdb.org/t/p/w1280/d51iFMkUTpWl9c2tjCXDO7nt8pA.jpg', 'https://www.youtube.com/watch?v=2dDMcGV1_GI', 'Andy Nguyễn', ARRAY['Thảo Tâm', 'Hồ Thu Anh', 'Hoàng Sơn', 'Huỳnh Kiến An', 'Võ Điền Gia Huy', 'Adrian Nguyen', 'Công Dương', 'Lê Khanh']::TEXT[], ARRAY['Chính Kịch', 'Giật Gân']::TEXT[], 111, '2023-07-28', NULL, NULL, 0, 'ended'),
  ('62960040-8867-5289-b9ab-6b92b9624a6f'::UUID, 1364970, 'Little Bird', 'Little Bird', 'Linh, a disillusioned Vietnamese woman carrying out evictions for a landlord, is instructed to evict Vietnamese refugees. She must decide whether to follow through with their eviction or reject it in solidarity.', 'Linh, a disillusioned Vietnamese woman carrying out evictions for a landlord, is instructed to evict Vietnamese refugees. She must decide whether to follow through with their eviction or reject it in solidarity.', 'https://image.tmdb.org/t/p/w780/qCHxPOZSWZVceRcDAUc7nPDeYr8.jpg', 'https://image.tmdb.org/t/p/w1280/hkpCvmfXlSTfqohWQzDFqG1Tbik.jpg', NULL, 'Oanh-Nhi Nguyen', ARRAY['Chantal Thuy', 'Jolie Eden', 'Paul Yen', 'Perry Yung', 'Misha Gonz-Cirkl', 'Ngoc Lee', 'Dale E. Turner', 'Mia-Carina Mollicone']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 16, '2024-10-25', NULL, NULL, 0, 'ended'),
  ('cf96e013-48ab-5218-8af5-0b1be3d607c2'::UUID, 1616792, 'Y-Concert', 'Y-Concert', 'The evening stages from Y-Concert by YeaH1, the 10-hour music festival for 55 artists.', 'The evening stages from Y-Concert by YeaH1, the 10-hour music festival for 55 artists.', 'https://image.tmdb.org/t/p/w780/rJBKleerybEoNqfubWPad2joUjy.jpg', NULL, 'https://www.youtube.com/watch?v=RxHWIcmLm4c', NULL, ARRAY['Tự Long', 'Minh Tuyết', 'Phạm Khánh Hưng', 'Phan Đinh Tùng', 'Tóc Tiên', 'Minh Hằng', 'Đinh Tiến Đạt', 'Phạm Quỳnh Anh']::TEXT[], ARRAY[]::TEXT[], 319, '2026-02-16', NULL, NULL, 0, 'ended'),
  ('7477ae11-63cb-59e6-b477-1699ede1bb93'::UUID, 1607159, 'Nhà Ba Tôi Một Phòng', 'Nhà Ba Tôi Một Phòng', 'Lấy bối cảnh một khu chung cư cũ với căn nhà chỉ vỏn vẹn một phòng, Nhà Ba Tôi Một Phòng khắc họa mối quan hệ “lệch pha” giữa người cha bảo thủ và cô con gái Gen Z đầy mơ ước. Khi những khác biệt thế hệ va chạm trong không gian chật chội, tình thân dần được thử thách và hàn gắn. Bộ phim mang đến một lát cắt gần gũi về gia đình Việt hiện đại, nơi yêu thương đôi khi bắt đầu từ sự thấu hiểu.', NULL, 'https://image.tmdb.org/t/p/w780/aPIQC6RoNpLpqY576CCwluTCaJ1.jpg', 'https://image.tmdb.org/t/p/w1280/4g2YrMhpaNX0k0ExLfAz7oNrR0l.jpg', 'https://www.youtube.com/watch?v=APBB-zfYFGw', 'Trường Giang', ARRAY['Trường Giang', 'Đoàn Minh Anh', 'Anh Tú Atus', 'Kiều Minh Tuấn', 'Lê Dương Bảo Lâm', 'Ngô Kiến Huy', 'Cris Phan', 'Otis']::TEXT[], ARRAY['Gia Đình', 'Hài']::TEXT[], 126, '2026-02-17', NULL, NULL, 0, 'ended'),
  ('f0b76a37-6071-5ae7-a144-7c304a155d88'::UUID, 1376879, 'Địa đạo: Mặt trời trong bóng tối', 'Địa đạo: Mặt trời trong bóng tối', 'Năm 1967, giữa lúc Chiến tranh Việt Nam đang ở đỉnh điểm, đội du kích cách mạng 21 người trở thành mục tiêu “tìm và diệt” số 1 của quân đội Mỹ khi nhận nhiệm vụ bằng mọi giá phải bảo vệ một nhóm thông tin tình báo chiến lược mới đến ẩn náu tại căn cứ.', NULL, 'https://image.tmdb.org/t/p/w780/qLv0HfTCGGnLgoTOoEWlXvjuwpA.jpg', 'https://image.tmdb.org/t/p/w1280/AeIB61nouCdGJr8FAGjPK7Zyd3u.jpg', 'https://www.youtube.com/watch?v=-OGDDtsIBHA', 'Bùi Thạc Chuyên', ARRAY['Thái Hòa', 'Quang Tuấn', 'Hồ Thu Anh', 'Diễm Hằng Lamoon', 'Cao Minh', 'Nhật Ý', 'Khánh Ly', 'Hoàng Minh Triết']::TEXT[], ARRAY['Chiến Tranh', 'Chính Kịch', 'Lịch Sử']::TEXT[], 128, '2025-04-04', NULL, 'KR: 15', 7.7, 'ended'),
  ('b48aa181-c226-5e9f-a2e5-56cd17d58195'::UUID, 1667685, 'Phí Phông: Quỷ Máu Rừng Thiêng', 'Phí Phông: Quỷ Máu Rừng Thiêng', 'Phí Phông, loài quỷ khát máu trong truyền thuyết dân gian của đồng bào miền núi gây ám ảnh bao đời nay. Phim xoay quanh Còn (Kiều Minh Tuấn) và Dương (Minh Anh), hai pháp sư tập sự lên núi cứu người mẹ đang bị lời nguyền Phí Phông đánh gục. Cùng lúc đó, trong bản sâu cũng xảy ra nhiều cái chết ghê rợn. Mọi nghi ngờ đổ dồn về hai mẹ con Mon (Diệp Bảo Ngọc) và Lua (Nina Nutthacha), những người mang đặc tính y hệt Phí Phông. Thế nhưng, vẫn còn những bí mật động trời bị chôn vùi trong chốn rừng thiêng nước độc, cuốn hai anh em Còn và Dương vào cuộc truy lùng “Phí Phông” không hồi kết.', NULL, 'https://image.tmdb.org/t/p/w780/1c5XWuA9ETEUZcMAF1ngk0kBNEh.jpg', 'https://image.tmdb.org/t/p/w1280/dgBVAby8uWwTClrUmbsda9r9rQA.jpg', 'https://www.youtube.com/watch?v=0U27uD4P_U0', 'Đỗ Quốc Trung', ARRAY['Kiều Minh Tuấn', 'ณัฐชา พาโดวัน', 'Diệp Bảo Ngọc', 'Trần Gia Huy', 'Đoàn Minh Anh', 'Hạnh Thúy', 'Cris Phan', 'Minh Coca']::TEXT[], ARRAY['Kinh Dị', 'Bí Ẩn']::TEXT[], 120, '2026-04-16', NULL, 'KR: 15', 6, 'ended'),
  ('8db324b0-f541-5c69-bfd3-87d3c9c0ce41'::UUID, 19552, 'Mùi Đu Đủ Xanh', 'Mùi đu đủ xanh', 'Bộ phim nói về Mùi, một cô bé ôn hòa và luôn tò mò về thế giới xung quanh. Cô đi ở cho một gia đình buôn vải ở Sài Gòn khoảng những năm 1950. Trong gia đình này, người vợ là trụ cột chính, gánh vác công việc, còn ông chồng chỉ biết chơi bời và bà mẹ chồng. Ông bà chủ có ba con trai, một người trưởng thành, tên là Trung, con trai thứ tên là Lãng. Hai con trai còn lại, một đang tuổi vị thành niên ít quan tâm tới Mùi. Đứa thứ hai khoảng tuổi Mùi thường xuyên trêu chọc cô. Khi người chồng bỏ đi lần thứ tư và cuối cùng, ông lấy đi toàn bộ số tiền có trong nhà. Mặc mọi chuyện diễn ra xung quanh, bé Mùi chăm chỉ làm việc và say mê với thế giới riêng của bé.', '1950s Saigon through the eyes of Mui, a Vietnamese servant girl. At 10 years-old, Mui leaves her village to work for an affluent, troubled family. As she comes of age, Mui finds work in the household of a pianist she has admired since childhood, and finds their relationship growing in complexity.', 'https://image.tmdb.org/t/p/w780/wIjKFkJB5GUO80eEEjju7HGf9ue.jpg', 'https://image.tmdb.org/t/p/w1280/7bKppGvuhdF9BCOZWDMUFccoQU1.jpg', 'https://www.youtube.com/watch?v=xe9DorMzpEw', 'Trần Anh Hùng', ARRAY['Tran Nu Yen Khe', 'Man San Lu', 'Thi Loc Truong', 'Ánh Hoa', 'Hoa Hoi Vuong', 'Ngoc Trung Tran', 'Vantha Talisman', 'Keo Souvannavong']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn']::TEXT[], 104, '1993-06-08', NULL, 'US: NR', 7, 'ended'),
  ('867d203d-845d-5c0e-a381-cd79a14287e3'::UUID, 543294, 'Song lang', 'Song lang', 'Sài Gòn thập niên 1980. Dũng “thiên lôi” là một tay anh chị chuyên đòi nợ thuê. Gã sống lặng lẽ tại căn tập thể cũ, không ai thân thích. Một ngày nọ, khi đi đòi nợ tại đoàn cải lương Thiên Lý, Dũng chạm mặt Linh Phụng - kép nam chính của đoàn. Họ mới đến thành phố và bắt đầu những buổi diễn đầu tiên. Cả hai không ngờ rằng sau lần gần gỡ tình cờ đó, sợi dây liên kết vô hình giữa hai con người cùng nặng lòng với cải lương đã hình thành, và khiến số phận của họ thay đổi mãi mãi.', 'Set against a gloriously filmed backdrop of the distinctly jaded charm of mid-90s Saigon, the lives of two men intertwine as they are both bound by traditions and honor. One to his mafia family, the other to the traveling troupe that performs elaborate classic operas. Yet they have much more in common than either wants to admit.', 'https://image.tmdb.org/t/p/w780/88MrQnwHnrX1um9Gv1gaFNmsJxv.jpg', 'https://image.tmdb.org/t/p/w1280/5VQ6YZo4nYY7N2ubJ0StQLkbdxe.jpg', 'https://www.youtube.com/watch?v=wX8nGJFGwaU', 'Leon Lê', ARRAY['Liên Bỉnh Phát', 'Isaac', 'Mã Lập Vỹ', 'Mỹ Phương', 'Thanh Tú', 'Hồng Thanh', 'Rong Vương', 'Trần Phước Tính']::TEXT[], ARRAY['Chính Kịch', 'Âm Nhạc']::TEXT[], 97, '2018-08-17', NULL, NULL, 6.8, 'ended'),
  ('89196ebe-78f0-59e7-a2b3-8b9362f7cfd4'::UUID, 1744848, 'Chị Chị Em Em 3', 'Chị Chị Em Em 3', 'Giữa xã hội Bắc Bộ cũ đầy lễ giáo và những khuôn phép khắt khe, Thị Mầu – tiểu thư nổi tiếng tài sắc nhất vùng – bước vào một thế giới nơi tình yêu chưa bao giờ là chuyện của riêng hai người.  Những rung động bị che giấu, những mối quan hệ chồng chéo và những lựa chọn trái với khuôn phép dần tạo nên một mạng nhện tình cảm rối ren, nơi mỗi người đều có một bí mật, một toan tính và một người không thể gọi tên.  Khi tình yêu và danh dự không thể cùng tồn tại, liệu ai sẽ là người thoát khỏi mạng nhện ấy – và ai sẽ phải trả giá cho thứ tình cảm mình không thể cưỡng lại?', NULL, 'https://image.tmdb.org/t/p/w780/8mR122VqlhcdsTDdtaPsbD7WJO6.jpg', 'https://image.tmdb.org/t/p/w1280/sdNQCnSTZWyn2Y4NEzqAX3dXM9e.jpg', 'https://www.youtube.com/watch?v=T2agdzhXOaY', 'Nguyễn Hữu Hoàng', ARRAY['Ninh Dương Lan Ngọc', 'Quốc Anh', 'Kỳ Duyên', 'Chi Pu', 'Steven Nguyễn', 'Lê Khanh', 'Trọng Trinh', 'Trung Tuấn']::TEXT[], ARRAY['Lãng Mạn', 'Giật Gân', 'Chính Kịch']::TEXT[], 122, '2026-10-30', NULL, NULL, 0, 'ended'),
  ('b1bf60ad-2b7d-5a93-858d-7e0a2911485e'::UUID, 1591972, 'Đại Tiệc Trăng Máu 8', 'Đại Tiệc Trăng Máu 8', 'Đại Tiệc Trăng Máu 8 theo chân một vị đạo diễn hay bị coi thường (Vân Sơn đóng) trong dự án thử thách nhất đời ông: thực hiện một bộ phim dài 35 phút chỉ với một cú máy. Hàng loạt tình huống dở khóc dở cười xảy ra khi các diễn viên liên tục gây chuyện “khó đỡ”. Thế nhưng, việc hoàn thành tác phẩm là cơ hội cuối cùng để ông giành lại sự tôn trọng từ cô con gái đam mê nghệ thuật.', NULL, 'https://image.tmdb.org/t/p/w780/vrm3pGNR9ww5luHFssA50roqQoz.jpg', 'https://image.tmdb.org/t/p/w1280/AvARLfS089zGSLvfLcOhIqJzUeF.jpg', 'https://www.youtube.com/watch?v=Nb3agyeJkAo', 'Phan Gia Nhật Linh', ARRAY['Vân Sơn', 'Lê Khánh', 'Miu Lê', 'Liên Bỉnh Phát', 'Quốc Khánh', 'Quỳnh Lý', 'Lâm Thanh Mỹ', 'Quang Minh']::TEXT[], ARRAY['Hài']::TEXT[], 130, '2026-04-23', NULL, 'KR: 12', 7.5, 'ended'),
  ('98c30857-0826-5c7e-8028-b669559f79d4'::UUID, 175966, 'Bao giờ cho đến tháng Mười', 'Bao giờ cho đến tháng Mười', 'Bao giờ cho đến tháng Mười được sản xuất năm 1984 đã được coi là một trong những bộ phim kinh điển của nền điện ảnh Việt Nam. Ngày 15 tháng 9 năm 2008, CNN đánh giá “Bao giờ cho đến tháng Mười” là một trong 18 bộ phim châu Á xuất sắc mọi thời đại. Bao giờ cho đến tháng mười là một bộ phim mang nhiều bản sắc dân tộc khi lấy nhân vật chính là người phụ nữ, đạo diễn Đặng Nhật Minh đã góp phần làm tăng vẻ đẹp thầm kín cao cả trong tâm hồn người phụ nữ Việt Nam.', 'In the final days of the war, Duyên faces a daily struggle to take care of her young son and ailing father-in-law, all the while hiding from them the fact that her husband has recently been killed in battle.', 'https://image.tmdb.org/t/p/w780/ssBVQKAOWGgoBehVOdc11q06ElF.jpg', 'https://image.tmdb.org/t/p/w1280/3fSIrNXoyRKytryeKo4xj0DgpGr.jpg', NULL, 'Đặng Nhật Minh', ARRAY['Lê Vân', 'Hữu Mười', 'Lại Phú Cương', 'Nguyen Minh Vuong', 'Đặng Việt Bảo', 'Trịnh Phong', 'Hoàng Yến', 'Hoàng Long']::TEXT[], ARRAY['Chính Kịch', 'Chiến Tranh']::TEXT[], 85, '1984-04-04', NULL, 'GB: PG', 7.2, 'ended'),
  ('80d630ec-3d77-5cfa-b1e6-271ca3272f31'::UUID, 43565, '므이', '므이', 'A Korean writer travels to Vietnam to do research for her story about a cursed portrait of a Vietnamese girl named Muoi.', 'A Korean writer travels to Vietnam to do research for her story about a cursed portrait of a Vietnamese girl named Muoi.', 'https://image.tmdb.org/t/p/w780/bEDf7nRcDWxs0Qo1jNpcu04qh01.jpg', 'https://image.tmdb.org/t/p/w1280/lrdqHcDTe7Sb8Pi3wn8Y9H7jCxi.jpg', 'https://www.youtube.com/watch?v=Oq_0b6E2L9E', '김태경', ARRAY['조안', '차예련', '이준', 'Hong So-hee', 'Anh Thư', 'Bình Minh', 'Hồng Ánh', 'Thành Lũy']::TEXT[], ARRAY['Chính Kịch', 'Kinh Dị', 'Bí Ẩn', 'Giật Gân']::TEXT[], 95, '2007-07-25', NULL, 'KR: 15', 5.4, 'ended'),
  ('eaf67479-b312-53c7-80b4-c70de4f77220'::UUID, 1448353, 'Thám Tử Kiên: Kỳ Án Không Đầu', 'Thám Tử Kiên: Kỳ Án Không Đầu', 'Một chuỗi án mạng kinh hoàng tại một ngôi làng hẻo lánh – nơi liên tiếp xảy ra tám vụ giết người với cùng một đặc điểm rợn người: tất cả nạn nhân đều không còn đầu. Thám Tử Kiên phải đối mặt với vụ án khủng khiếp gây hoang mang tột độ cho dân làng. Ai sẽ là nạn nhân tiếp theo trong chuỗi án mạng rùng rợn? Kiên có tìm ra mấu chốt để lần theo dấu vết hung thủ?', NULL, 'https://image.tmdb.org/t/p/w780/zHMrhNFgmvLE3rYBQYwFXuUBQMX.jpg', 'https://image.tmdb.org/t/p/w1280/rmhmfqVVUWV4xjoC0uBnelARFmT.jpg', 'https://www.youtube.com/watch?v=QiXNbEKF3U0', 'Victor Vũ', ARRAY['Quốc Huy', 'Ngọc Diệp', 'Đoàn Minh Anh', 'Quốc Anh', 'Tín Nguyễn', 'Anh Phạm', 'Quốc Cường', 'Mỹ Uyên']::TEXT[], ARRAY['Kinh Dị', 'Tội Phạm', 'Lịch Sử']::TEXT[], 131, '2025-04-25', NULL, 'GB: 15', 7.8, 'ended'),
  ('47b1be89-f1bd-548b-a17a-d7e76362c9bb'::UUID, 795757, 'Vị', 'Vị', 'Bassley, một cầu thủ bóng đá người Nigeria sống tại Việt Nam, không thể kiếm sống kể từ khi anh bị gãy chân. Anh và bốn người phụ nữ trung niên mà anh đôi khi làm việc cùng quyết định trốn thoát khỏi nỗi thất vọng trong cuộc sống hàng ngày của họ. Họ đến một ngôi nhà cũ, nơi họ cùng nhau tạo ra một thế giới đặc biệt cho riêng mình. Nhưng thế giới lý tưởng thân mật này không thể tồn tại mãi mãi.', 'Bassley, a Nigerian footballer living in Vietnam, has been unable to make a living since he broke his leg. He and four middle-aged women he sometimes works for decide to escape the disappointment of their daily lives. They go to an old house where together they create a special world for themselves. But this intimate utopia cannot last forever.', 'https://image.tmdb.org/t/p/w780/yXynG3oMtYu7pNGzRBf4W9LnmAJ.jpg', 'https://image.tmdb.org/t/p/w1280/yNpKzFDYdsig0A2YQfMCiD22BqO.jpg', 'https://www.youtube.com/watch?v=Pw3PPCQI8lA', 'Bao Le', ARRAY['Olegunleko Ezekiel Gbenga', 'Khuong Thi Minh Nga', 'Vu Thi Tham Thin', 'Le Thi Dung', 'Nguyen Thi Cam Xuan']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 97, '2021-04-22', NULL, NULL, 4.7, 'ended'),
  ('ab8ec648-3476-519b-b9cf-11b3ba773b12'::UUID, 730501, 'Giòng sông không nhìn thấy', 'Giòng sông không nhìn thấy', 'Stories told along the river: a woman reunites with her ex-lover at a hydroelectric plant; meanwhile, a young man travels downstream to a temple in search of a cure for his insomnia.', 'Stories told along the river: a woman reunites with her ex-lover at a hydroelectric plant; meanwhile, a young man travels downstream to a temple in search of a cure for his insomnia.', 'https://image.tmdb.org/t/p/w780/slIUVJMB2GQxknNiOaby9jbkEBh.jpg', 'https://image.tmdb.org/t/p/w1280/pFCuDfj8BmWg0qRxDxTOmXSThu1.jpg', 'https://www.youtube.com/watch?v=ZMKtU5RFDZY', 'Phạm Ngọc Lân', ARRAY['Minh Châu', 'Wean Lê', 'Nguyễn Hà Phong', 'Naomi', 'Mạc Can', 'Hoàng Hà']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 23, '2020-08-06', NULL, NULL, 6.3, 'ended'),
  ('465eb4f6-0c34-5d7c-bccf-fb92f815448b'::UUID, 623897, 'Thưa mẹ con đi', 'Thưa mẹ con đi', 'Cậu con trai sống ở nước ngoài quay về nhà cùng người bạn đồng giới để thú nhận về mối quan hệ của họ. Thế nhưng anh lại bị choáng ngợp bởi bổn phận làm con.', 'Văn comes back to Ho Chi Minh City from the US with his boyfriend Ian to visit his mother. Being the male heir of the family, everyone expects him to take a wife soon. And to top it all, his grandmother, who has Alzheimer, mistakes Ian for her grandson.', 'https://image.tmdb.org/t/p/w780/jbhdKSIwZ2S2DwPs1nWFNJzK8e7.jpg', 'https://image.tmdb.org/t/p/w1280/pOYcG9URkRGLbMuFGqdh57DAdh9.jpg', 'https://www.youtube.com/watch?v=DkrxQbFwto0', 'Trịnh Đình Lê Minh', ARRAY['Hồng Đào', 'Lãnh Thanh', 'Võ Điền Gia Huy', 'Lê Thiện', 'Hồng Ánh', 'Kiều Trinh', 'Hà Linh', 'Thanh Tú']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn', 'Gia Đình']::TEXT[], 100, '2019-08-16', NULL, NULL, 6.8, 'ended'),
  ('18d8e81b-31f8-5ad0-bf0c-4246586dbb28'::UUID, 320000, 'Cha và con và…', 'Cha và con và…', 'Vào cuối thập niên 1990, những năm đầu thập niên 2000 ở Sài Gòn, một chàng sinh viên ngành nhiếp ảnh tên Vũ (Lê Công Hoàng) lên thành phố ở trọ. Với chiếc máy ảnh được cha tặng, Vũ bắt đầu khám phá cuộc sống xung quanh mình. Vũ bị cuốn hút bởi người bạn cùng phòng điển trai tên Thăng (Trương Thế Vinh), một tay chơi thường xuyên dính líu tới ma túy, cờ bạc và mại dâm ở Sài Gòn. Thăng giới thiệu Vũ với Vân (Đỗ Thị Hải Yến), một vũ nữ tại hộp đêm và cả hai đã ân ái với nhau, cho dù Vũ cảm mến bởi anh bạn của mình hơn.  Một ngày nọ, một người bạn cùng phòng bị mất trộm. Khi Vũ và Thăng chạy trốn tới làng của Vũ ở đồng bằng sông Cửu Long, cha của Vũ đã giới thiệu cả hai với cô gái mà ông chọn làm vợ tương lai của Vũ. Tại đây, mọi chuyện trở nên phức tạp khi Thăng tán tỉnh "vợ tương lai” của Vũ và khiến chàng nhiếp ảnh trẻ ghen tuông...', 'Saigon, early 2000s.  Photography student Vu has just arrived from Vietnam''s backwaters and is immediately attracted to his handsome roommate Thang, who works odd jobs as a bouncer and low-level drug dealer.  Entranced by the nocturnal rhythms of Thang''s world, Vu follows him around the city where he meets Van, a ballet-cum-exotic dancer and Thang''s sometimes-girlfriend.', 'https://image.tmdb.org/t/p/w780/qtlEbbXBZMaXlhMyEHtTpE504ZO.jpg', 'https://image.tmdb.org/t/p/w1280/qBzAoT9E3QEZewH7JE40XxbEkMr.jpg', 'https://www.youtube.com/watch?v=wCXH95HCrss', 'Phan Đăng Di', ARRAY['Đỗ Thị Hải Yến', 'Nguyễn Hà Phong', 'Lê Công Hoàng', 'Trương Thế Vinh', 'Mai Quoc Viet', 'Mai Thế Hiệp', 'Kiều Trinh']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 100, '2015-01-20', NULL, NULL, 5.1, 'ended'),
  ('3c93658e-ba0f-53c4-bd57-7651e29e9812'::UUID, 224896, 'Ngôi Nhà Trong Hẻm', 'Ngôi Nhà Trong Hẻm', 'Bộ phim mang đến cho khán giả về câu chuyện của hai vợ chồng trẻ phải đối đầu với những mất mát vô cùng to lớn. Rồi từ đó, từ một căn nhà hạnh phúc, nơi ấy dần trở thành địa ngục khi người vợ không vượt qua nỗi đau và chìm trong cơn điên loạn. Còn điều gì đau khổ hơn một người mẹ mang nặng đẻ đau 9 tháng 10 ngày nhưng không thể làm gì khi đưa bé chết non. Nhưng đó thật sự chỉ là cơn điên loạn hay ẩn chứa những bí mật gì nữa tại ngôi nhà trong hẻm ấy.', 'Until they lose their baby to a miscarriage, a young couple were happily settling into their new life in their spacious home. After the tragedy, Thao is inconsolable and won''t let her baby''s body leave the house. Normal life eludes her as terrifying visions undermine her sanity. Her husband, Thanh, experiences strange phenomena around their home and when his wife turns on him, he must race to uncover the secrets of the house in the alley before they lose their sanity and their lives.', 'https://image.tmdb.org/t/p/w780/qok4WtqFuuSVay5ubVXvANykvDU.jpg', NULL, 'https://www.youtube.com/watch?v=t-3vh170fHk', 'Lê Văn Kiệt', ARRAY['Ngô Thanh Vân', 'Trần Bảo Sơn', 'Bùi Văn Hải']::TEXT[], ARRAY['Kinh Dị']::TEXT[], 93, '2013-10-25', NULL, NULL, 6.5, 'ended'),
  ('b77bf854-f6ae-5d54-b508-cd1374d4baa9'::UUID, 87147, 'Hot Boy Nổi Loạn', 'Hot Boy Nổi Loạn', 'Hot Boy Nổi Loạn và Câu Chuyện Về Chằng Cười, Cô Gái Điếm và Con Vịt lấy bối cảnh ở thành phố Hồ Chí Minh và kể lại hai câu chuyện khác nhau. Câu chuyện thứ nhất kể về tam giác tình giữa ba chàng trai tên Khôi, Lam và Đông; trong đó Lam và Đông làm nghề mại dâm. Câu chuyện thứ hai kể về một chàng khờ tên Cười và tình bạn giữa anh với một cô gái mại dâm tên Hạnh.', 'Khoi, a naive twenty-year-old, travels to Ho Chi Minh City from the countryside to begin a new life. It''s his first time in the big city and he''s looking for a place to live. He befriends Dong, a handsome extrovert who offers to share his apartment. When Khoi goes to check the place out, he meets Lam, who also appears to be living there. Khoi decides to stay, but while he showers, Dong and Lam - who turn out to be boyfriends - run off with all his cash and belongings.', 'https://image.tmdb.org/t/p/w780/yEiJS1t9wiRAJWUCAmFvmpM2Y3S.jpg', 'https://image.tmdb.org/t/p/w1280/4P6dcu4prUl3vEhujMgtgF74ANR.jpg', 'https://www.youtube.com/watch?v=HxeFx_CdhUs', 'Vũ Ngọc Đãng', ARRAY['Lương Mạnh Hải', 'Hồ Vĩnh Khoa', 'Linh Sơn', 'Phương Thanh', 'Hiếu Hiền']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 103, '2011-09-01', NULL, 'DE: 16', 5.1, 'ended'),
  ('809586b3-a770-54da-b718-e65ae9c672bd'::UUID, 1479953, 'Tử chiến trên không', 'Tử chiến trên không', 'Một chuyến bay đang khởi hành từ Đà Nẵng đến Buôn Ma Thuột thì bị một băng không tặc do Long tấn công và khống chế, nhằm cướp máy bay để tẩu thoát ra nước ngoài. Trong tình thế nguy cấp, phi hành đoàn buộc phải ra tay hành động để chống trả và đảm bảo an toàn cho hành khách.', 'When a group of ruthless hijackers take control of a flight and try to force their way into the cockpit, an aviation security officer must find a way to fight back while still safely protect the passengers.', 'https://image.tmdb.org/t/p/w780/elhC01GA3etoh6X9zj5QwZq20Js.jpg', 'https://image.tmdb.org/t/p/w1280/vs5E55pBnmXLGi2IPPL5H8GvPaM.jpg', 'https://www.youtube.com/watch?v=uiuyBol83HE', 'Hàm Trần', ARRAY['Thái Hòa', 'Kaity Nguyễn', 'Thanh Sơn', 'Ma Ran Đô', 'Lợi Trần', 'Bảo Định', 'Ray Nguyễn', 'Trần Ngọc Vàng']::TEXT[], ARRAY['Giật Gân', 'Hành Động', 'Tội Phạm']::TEXT[], 118, '2025-09-19', NULL, 'KR: 15', 7.2, 'ended'),
  ('057deb97-0202-5e3c-9583-ef7a93440cdc'::UUID, 699361, 'Tiệc Trăng Máu', 'Tiệc Trăng Máu', 'Trong buổi họp mặt của nhóm bạn thân, một thành viên bất ngờ đề xuất trò chơi chia sẻ điện thoại nhằm tăng tinh thần “đoàn kết”. Từ đó, những góc khuất của từng người dần hé lộ và khiến cho mối quan hệ vốn khắng khít của họ bắt đầu lay chuyển.', NULL, 'https://image.tmdb.org/t/p/w780/1gtr8Js6yS7gWrQylbIK4sGQGih.jpg', 'https://image.tmdb.org/t/p/w1280/lQlzgffotUtjyOb6GutId99N00M.jpg', 'https://www.youtube.com/watch?v=PqNGHKLyPD0', 'Nguyễn Quang Dũng', ARRAY['Thái Hòa', 'Hồng Ánh', 'Hứa Vĩ Văn', 'Thu Trang', 'Kiều Minh Tuấn', 'Kaity Nguyễn', 'Đức Thịnh', 'Việt Linh']::TEXT[], ARRAY['Hài', 'Chính Kịch', 'Giật Gân']::TEXT[], 118, '2020-10-23', NULL, NULL, 7.2, 'ended'),
  ('9ee0e3dc-a34b-5001-ab24-d79b68ea8e26'::UUID, 496243, 'Ký Sinh Trùng', '기생충', 'Bộ phim xoay quanh hai gia đình hoàn toàn trái ngược: một bên vô cùng giàu có, còn một bên luôn sống trong cảnh nghèo túng. Họ tình cờ gặp gỡ và quen biết nhau sau một biến cố không ngờ.', NULL, 'https://image.tmdb.org/t/p/w780/zZydO1LhMhqDAMM86JUi241wT7X.jpg', 'https://image.tmdb.org/t/p/w1280/TU9NIjwzjoKPwQHoHshkFcQUCG.jpg', 'https://www.youtube.com/watch?v=o3ESQWArU2w', 'Bong Joon Ho', ARRAY['송강호', '이선균', '조여정', 'Choi Woo-shik', '박소담', 'Lee Jung-eun', 'Jang Hye-jin', '박명훈']::TEXT[], ARRAY['Hài', 'Giật Gân', 'Chính Kịch']::TEXT[], 132, '2019-05-30', 'T18', 'KR: 15', 8.5, 'ended'),
  ('ac6a8a7c-abce-5969-a98c-93dafca793cd'::UUID, 110415, 'Chuyến Tàu Băng Giá', '설국열차', 'Lấy bối cảnh năm 2031, sau thất bại của nỗ lực khắc phục sự nóng lên của toàn cầu, Trái Đất trở về với Kỷ Băng Hà khi hoàn toàn bị bao phủ bởi băng tuyết và thế giới loài người đứng trước nguy cơ bị xóa sổ. Tất cả những người may mắn sống sót đều ở trên con tàu mang tên Snowpiercer. Con tàu đi tới khắp nơi trên Trái Đất và giống như một xã hội thu nhỏ, chứa đựng những mâu thuẫn và phân biệt giàu nghèo, giai cấp giữa những người đang phải cùng nhau đương đầu với cái chết. Quá mệt mỏi trước sự áp bức, bất công, dưới sự lãnh đạo của Curtis (Chris Evans thủ vai), những người nghèo sống ở những toa sau của con tàu đã nổi dậy tiến hành cuộc cách mạng lật đổ tầng lớp thượng lưu ở những toa trước. Tuy nhiên, cuộc nổi dậy của họ đối mặt với rất nhiều nhiều khó khăn, thử thách...', 'In a future where a failed global-warming experiment kills off most life on the planet, a class system evolves aboard the Snowpiercer; a train that travels around the globe via a perpetual-motion engine.', 'https://image.tmdb.org/t/p/w780/fC6Ipo5o45DQO4xM7Lfq4MppTDT.jpg', 'https://image.tmdb.org/t/p/w1280/55vkNtb83bSwbdWrQTVZTGLBcLx.jpg', 'https://www.youtube.com/watch?v=3Np3v7xnNJk', 'Bong Joon Ho', ARRAY['Chris Evans', '송강호', 'Ed Harris', 'John Hurt', 'Tilda Swinton', 'Jamie Bell', 'Octavia Spencer', 'Ewen Bremner']::TEXT[], ARRAY['Hành Động', 'Khoa Học Viễn Tưởng', 'Chính Kịch']::TEXT[], 127, '2013-08-01', NULL, 'KR: 15', 6.9, 'ended'),
  ('6f58c6eb-a43e-5e0c-bdef-a031bf500fa1'::UUID, 670, 'Báo Thù', '올드보이', 'Oldboy được chuyển thể từ bộ truyện tranh nổi tiếng cùng tên của hai tác giả Nhật Bản là Minegishi Nobuaki và Tsuchiya Garon. Oldboy là bộ phim thứ hai trong bộ ba phim The Vengeance. Bộ phim kể về câu chuyện của Oh Dae-Su, người bị bắt nhốt trong một căn phòng khách sạn suốt 15 năm mà không hề biết rõ mục đích của kẻ bắt cóc. Khi được giải thoát, Dae Su rơi vào những cái bẫy của âm mưu và bạo lực. Trong cuộc hành trình tìm kiếm nhằm trả thù kẻ đã gây ra đau khổ cho mình, Dae-Su rơi vào vòng xoáy tình cảm với một đầu bếp sushi. Bất ngờ nối tiếp bất ngờ từ đây...', 'With no clue how he came to be imprisoned, drugged and tortured for 15 years, a desperate man seeks revenge on his captors.', 'https://image.tmdb.org/t/p/w780/xpa9ybm6tYGna5LseqSXvKpSSJn.jpg', 'https://image.tmdb.org/t/p/w1280/rwf5SUTiEsmfkXAgy15R0UtJUtv.jpg', 'https://www.youtube.com/watch?v=tAaBkFChaRg', 'Park Chan-wook', ARRAY['최민식', '유지태', '강혜정', '김병옥', '지대한', '오달수', '이승신', '윤진서']::TEXT[], ARRAY['Giật Gân', 'Bí Ẩn']::TEXT[], 120, '2003-11-21', NULL, 'KR: 19', 8.2, 'ended'),
  ('42e34fd3-14b5-5df3-b21f-df9875dd4f70'::UUID, 396535, 'Chuyến Tàu Sinh Tử', '부산행', 'Chuyến Tàu Sinh Tử lấy bối cảnh đất nước Hàn bị tấn công bởi một loại virus bí ẩn, biến con người thành những xác sống hung hăng, khát máu. Có mặt trên chuyến tàu từ Seoul tới Busan là một người cha cùng con gái, hai vợ chồng chuẩn bị đón đứa con đầu lòng và một số cô cậu học sinh cấp 3. Khi đại dịch xác sống bất ngờ bùng phát, họ không còn cách nào khác ngoài đương đầu với nó để bảo vệ những người thân yêu của mình. Hành trình 453km từ Seoul tới vùng an toàn Busan bỗng trở thành cuộc chiến khốc liệt để sinh tồn...', 'When a zombie virus pushes Korea into a state of emergency, those trapped on an express train to Busan must fight for their own survival.', 'https://image.tmdb.org/t/p/w780/xMAMpuKpqXI3tfWow59oInjfoPA.jpg', 'https://image.tmdb.org/t/p/w1280/brnfCYyz8EMbBrHgmh8sCwBi5i1.jpg', 'https://www.youtube.com/watch?v=4qm59Rcq1Fw', '연상호', ARRAY['공유', '김수안', '정유미', 'Ma Dong-seok', 'Choi Woo-shik', '안소희', '김의성', '예수정']::TEXT[], ARRAY['Hành Động', 'Kinh Dị', 'Giật Gân', 'Phiêu Lưu']::TEXT[], 118, '2016-07-20', NULL, 'KR: 15', 7.8, 'ended'),
  ('daa5cdf4-d0e4-5266-8260-62cb26b4fc74'::UUID, 11423, 'Hồi Ức Kẻ Sát Nhân', '살인의 추억', 'Bộ phim mở đầu bằng cảnh một cánh đồng lúa vàng – hình ảnh đặc trưng của thôn quê Hàn Quốc thập niên 80. Nhưng đằng sau cảnh yên bình ấy lại là một câu chuyện giật gân, đáng sợ. Người dân làng bỗng phát hiện ra thi thể bị xâm hại của một phụ nữ tại bờ sông. Khi cuộc điều tra của thám tử địa phương Park Doo Man (Song Kang Ho) vẫn đang đi vào bế tắc và dân làng còn chưa kịp định thần thì xác nạn nhân tiếp theo lại được tìm thấy. Sự việc đã gieo rắc một nỗi ám ảnh kinh hoàng tới những người dân trong toàn Hàn Quốc. Phía Seoul đã cử Seo Tae Yoon, một thám tử điều tra được đào tạo bài bản tới xử lý vụ việc. Tuy nhiên, càng tìm ra được nhiều dấu vết của thủ phạm, các vụ án giết người lại càng xảy ra nhiều hơn với mức độ đáng sợ hơn. Phía cảnh sát rơi vào bế tắc vì kẻ sát nhân luôn đi trước họ một bước...', 'A sadistic serial rapist and murderer of young women terrorizes a small province in 1980s South Korea. To prevent further crimes, three increasingly desperate detectives with conflicting methods race against time to unravel the violent mind of the killer in a futile effort to solve the case.', 'https://image.tmdb.org/t/p/w780/wrsf1ebQ6S4gVhjR9FJElfdxAjj.jpg', 'https://image.tmdb.org/t/p/w1280/6Kn6qW3an3DkPl3MahWemTzrjCt.jpg', 'https://www.youtube.com/watch?v=0n_HQwQU8ls', 'Bong Joon Ho', ARRAY['송강호', '김상경', '김뢰하', '송재호', '변희봉', '고서희', '류태호', '박노식']::TEXT[], ARRAY['Tội Phạm', 'Chính Kịch', 'Giật Gân']::TEXT[], 131, '2003-04-25', NULL, 'KR: 15', 8.1, 'ended'),
  ('a2548d20-fa44-524f-8734-1f6f6b340542'::UUID, 290098, 'Người Hầu Gái', '아가씨', 'Những năm 1930, Hàn Quốc, trong thời kỳ bị Nhật Bản chiếm đóng, một phụ nữ trẻ được thuê làm hầu gái cho phu nhân Nhật Bản thừa kế tài sản lớn, sống cuộc sống ẩn dật trên một khu đất nông thôn rộng lớn với người chú độc đoán của cô. Nhưng, cô hầu gái có một bí mật: cô là một kẻ móc túi được tuyển dụng bởi một kẻ lừa đảo giả dạng một thống kê Nhật Bản để giúp anh ta dụ dỗ người thừa kế bỏ trốn với anh ta, cướp tài sản của cô và nhốt cô vào nhà thương điên. Kế hoạch dường như sẽ tiến hành theo đúng kế hoạch cho đến khi các chị em phát hiện ra một số cảm xúc bất ngờ.', '1930s Korea, in the period of Japanese occupation, a new girl, Sook-hee, is hired as a handmaiden to a Japanese heiress, Hideko, who lives a secluded life on a large countryside estate with her domineering Uncle Kouzuki. But the maid has a secret. She is a pickpocket recruited by a swindler posing as a Japanese Count to help him seduce the Lady to steal her fortune.', 'https://image.tmdb.org/t/p/w780/ieyWGqRGHoiKYUadq3yoeSZ4Q3D.jpg', 'https://image.tmdb.org/t/p/w1280/2b3RNXF7ca9bgX8FrjRBYfLnNQC.jpg', 'https://www.youtube.com/watch?v=wYsdzNIcJNc', 'Park Chan-wook', ARRAY['김민희', '김태리', '하정우', '조진웅', '김해숙', '문소리', '이용녀', '곽은진']::TEXT[], ARRAY['Giật Gân', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 145, '2016-06-01', NULL, 'KR: 19', 8.2, 'ended'),
  ('ed2d4461-36e0-5bca-af8b-a9aec0d52d7f'::UUID, 1255, 'Quái Vật Sông Hàn', '괴물', 'Trước bom tấn Parasite, đạo diễn Bong Joon Ho đã từng thành công với dòng phim quái vật với The Host (tựa Việt: Quái Vật Sông Hàn).phim kể về cuộc chiến đấu của gia đình Hee Bong với một con quái vật ở bờ sông Han. Mọi sự việc đều do những chất thải hóa học của một nhà máy bên dòng sông Hàn đã tạo ra một con quái vật khổng lồ.Ban đầu, con quái vật chỉ ăn những động vật nhỏ dưới lòng sông nhưng rồi một ngày, nó bắt đầu tấn công và ăn thịt con người. Chứng kiến cô con gái bé bỏng bị bắt đi, Hee Bong – một chàng trai sống bên bờ sông Hàn đã cùng những người thân của mình lên đường tìm kiếm con quái vật… Một cuộc chiến không cân sức giữa những con người nhỏ bé với một con quái vật to lớn, nhanh nhẹn và nó thích ăn thịt người . Liệu họ có cứu được cô bé và tiêu diệu được con quái vật , chúng ta cùng theo dõi.', 'A teenage girl is captured by a giant mutated squid-like creature that appears from Seoul''s Han River after toxic waste was dumped in it, prompting her family into a frantic search for her.', 'https://image.tmdb.org/t/p/w780/a5mWihsS2Vg7m1C5Cjw81m645M9.jpg', 'https://image.tmdb.org/t/p/w1280/m0wczZyNfWpu5q9wNuhFUGGiLxG.jpg', 'https://www.youtube.com/watch?v=0Zq5fL6BQjw', 'Bong Joon Ho', ARRAY['송강호', '변희봉', '박해일', '배두나', '고아성', '오달수', '이재응', 'Lee Dong-ho']::TEXT[], ARRAY['Kinh Dị', 'Chính Kịch', 'Khoa Học Viễn Tưởng']::TEXT[], 120, '2006-07-27', NULL, 'KR: 12', 7, 'ended'),
  ('39071bae-f3e8-5972-909f-33a72d47011f'::UUID, 49797, 'Gặp Phải Ác Quỷ', '악마를 보았다', 'Jang Kyung Cheol là 1 kẻ tâm thần xem giết người như 1 thú vui. Hắn đã thực hiện hàng loạt những vụ giết người theo 1 cách ma quỷ mà con người không thể tưởng tượng nổi và nạn nhân của hắn bao gồm cả phụ nữ lẫn trẻ em. Cảnh sát đã lần theo hắn trong suốt 1 thời gian dài những cũng không tóm được hắn.  Một ngày, con gái của 1 cảnh sát trưởng về hưu đã trở thành con mồi của hắn và được tìm thấy đã chết trong tình trạng khủng khiếp. Hôn phu của cô, Kim Soo Hyun, một mật vụ hàng đầu, quyết định tự mình săn đuổi hắn. Anh đã thề với lòng sẽ trả thù đẫm máu kẻ giết người, cho dù điều đó có nghĩa là chính anh phải trở thành một con quỷ.', 'Kyung-chul is a dangerous psychopath who kills for pleasure. Soo-hyeon, a top-secret agent, decides to track down the murderer himself. He promises himself that he will do everything in his power to take vengeance against the killer, even if it means that he must become a monster himself.', 'https://image.tmdb.org/t/p/w780/dFGrIdZGJtxm1GG4X1liYbxyjgd.jpg', 'https://image.tmdb.org/t/p/w1280/dXDFWWxiEb6tg4ojMWQJrSI0Tun.jpg', 'https://www.youtube.com/watch?v=xwWgp1bqVwE', '김지운', ARRAY['Lee Byung-hun', '최민식', '전국환', '천호진', '오산하', '김윤서', '남보라', '이준혁']::TEXT[], ARRAY['Giật Gân', 'Kinh Dị']::TEXT[], 144, '2010-08-12', NULL, 'KR: 19', 7.8, 'ended'),
  ('e75d2141-800d-54e4-a725-6bb48f7a259c'::UUID, 581392, 'Bán Đảo Peninsula', '반도', 'Quyết định đâm đầu vào chỗ chết, cựu quân nhân Jung Seok trở lại bán đảo vì số tiền hậu hĩnh lên đến 2,5 triệu USD. Tuy nhiên, anh và đồng đội bất ngờ bị phục kích bởi lữ đoàn biến chất 631 cùng bầy đàn zombie khát máu. Được gia đình Min Jung giải cứu, Jung Seok phải tìm cách đào thoát khỏi nơi đây trước khi quá trễ - Luật lệ duy nhất là sống sót', NULL, 'https://image.tmdb.org/t/p/w780/9hLmHGY1qIdCI5fJ4JvAXWQQORk.jpg', 'https://image.tmdb.org/t/p/w1280/gEjNlhZhyHeto6Fy5wWy5Uk3A9D.jpg', 'https://www.youtube.com/watch?v=DbDdy3j1jBU', '연상호', ARRAY['강동원', '이정현', '이레', '권해효', '김민재', '구교환', '김도윤', '이예원']::TEXT[], ARRAY['Kinh Dị', 'Hành Động', 'Giật Gân', 'Phiêu Lưu']::TEXT[], 116, '2020-07-15', NULL, 'KR: 15', 6.7, 'ended'),
  ('c7157c9e-b0aa-5b26-8aa0-8c456ee89259'::UUID, 293670, 'Tiếng Than', '곡성', 'Tại một ngôi làng heo hút, mọi chuyện mở đầu bằng một vụ thảm sát dã man trong một gia đình. Người vợ bị cứa cổ còn người chồng như tê dại, thẫn thờ bất động với cơ thể nổi đầy lở loét. Anh nhân viên cảnh sát miền quê Jong Goo vốn chỉ quen với chuyện ngồi bàn giấy, đọc truyện tranh lần đầu tiên phải chứng kiến những hiện trường giết người cực kỳ rùng rợn. Đỉnh điểm là khi cô con gái nhỏ của anh bắt đầu có những biểu hiện lạ, trở nên hung hăn, thèm ăn và cứ chực chờ gào thét. Mọi nghi ngờ đều đổ dồn vào một người đàn ông Nhật Bản bí ẩn sống trong rừng với lời đồn đại rằng đó là một kẻ hút máu. Gây sợ hãi nhưng đặc biệt, phim gần như không sử dụng jump-scare. Toàn bộ nỗi sợ được hình thành từ cái không khí u ám, buồn tẻ cùa vùng quê miền núi mưa dầm triền miên. Cùng với đó là sự đa nghi của con người vào những kẻ bí ẩn và cả... ma quỷ. Với The Wailing, nỗi sợ lớn nhất chính là nỗi sợ vào thứ mà ta không thể "điểm mặt gọi tên".', 'A stranger arrives in a little village and soon after a mysterious sickness starts spreading. A policeman is drawn into the incident and is forced to solve the mystery in order to save his daughter.', 'https://image.tmdb.org/t/p/w780/k9AKtgRErXjz14lFHL2IJVCgwOT.jpg', 'https://image.tmdb.org/t/p/w1280/9qxBNfI1QFbiZS62fsgaUd563t2.jpg', 'https://www.youtube.com/watch?v=VUWAgbXSJ4Y', '나홍진', ARRAY['곽도원', '황정민', '천우희', '國村隼', '김환희', '허진', '장소연', '김도윤']::TEXT[], ARRAY['Kinh Dị', 'Bí Ẩn']::TEXT[], 156, '2016-05-12', NULL, 'KR: 15', 7.4, 'ended'),
  ('f03d0855-5e34-5a75-a474-79eba1011a64'::UUID, 614696, 'Sống Sót', '#살아있다', 'Bộ phim kể về câu chuyện liên quan đến những người sống sót bị cô lập của một thành phố đang bị phong tỏa, cách ly do hậu quả của sự lây nhiễm bất ngờ của một dịch bệnh không rõ nguồn gốc. Yoo Ah-in sẽ vào vai Joon Woon, một game thủ sống sót và bị ngắt kết nối với phần còn lại của thế giới. Park Shin-hye đảm nhận vai Yoo Bin, một người sống sót khác dựa vào kỹ năng sinh tồn của chính cô trong tình huống vô cùng khó khăn trong thành phố.', 'As a grisly virus rampages a city, a lone man stays locked inside his apartment, digitally cut off from seeking help and desperate to find a way out.', 'https://image.tmdb.org/t/p/w780/knzAQBHVDzJ3lPg690663TCIeOM.jpg', 'https://image.tmdb.org/t/p/w1280/k2SY15W9QXH9qL8f4a4BbytV1BE.jpg', 'https://www.youtube.com/watch?v=jQ8CCg1tOqc', 'Cho Il', ARRAY['유아인', '박신혜', '이현욱', '진소연', '김학선', '소희정', '주보비', '전배수']::TEXT[], ARRAY['Hành Động', 'Kinh Dị', 'Khoa Học Viễn Tưởng']::TEXT[], 98, '2020-06-24', NULL, 'KR: 15', 7.2, 'ended'),
  ('99923242-3162-57f1-9e0d-1e10334f2fdf'::UUID, 4550, 'Người Đẹp Báo Thù', '친절한 금자씨', 'Sau 13 năm tù vì tội bắt cóc và giết hại cậu bé 6 tuổi, Lee Guem-ja xinh đẹp bắt đầu tìm cách trả thù người đàn ông thực sự chịu trách nhiệm cho cái chết của cậu bé. Với sự giúp đỡ của những người bạn tù và đoàn tụ với con gái, cô ngày càng tiến gần hơn đến mục tiêu của mình. Nhưng liệu hành động của cô ấy có dẫn đến sự nhẹ nhõm mà cô ấy đang tìm kiếm?', 'Released after being wrongfully convicted and imprisoned for 13 years, a woman begins executing her elaborate plan of retribution.', 'https://image.tmdb.org/t/p/w780/1TCQnCIIiTXROsCPKwYvnqll8Ta.jpg', 'https://image.tmdb.org/t/p/w1280/1N45Z1UQY3LMNJEHuyHj6NygOYq.jpg', 'https://www.youtube.com/watch?v=deSJEDUi4rQ', 'Park Chan-wook', ARRAY['이영애', '최민식', '권예영', '김시후', '남일우', '김병옥', '오달수', '이승신']::TEXT[], ARRAY['Chính Kịch', 'Giật Gân']::TEXT[], 115, '2005-07-29', NULL, 'KR: 19', 7.5, 'ended'),
  ('c9c77fe6-6626-5087-ad23-adacbf266870'::UUID, 22832, 'Ninja Sát Thủ', 'Ninja Assassin', 'Bộ phim tập trung vào nhân vật Raizo (Rain), một trong những ninja sát thủ nguy hiểm nhất trên thế giới. Raiza thuở nhỏ là một đứa trẻ đường phố, được tổ chức Ozunu Clan, một tổ chức bí mật mà sự tồn tại của nó dường như vẫn là huyền thoại, nhận về nuôi và huấn luyện để trở thành sát thủ chuyên nghiệp. Nhưng Raizo bị ám ảnh bởi cách đối xử tàn nhẫn của tổ chức đối với bạn mình, Raizo quyết định trốn chạy và biến mất khỏi tổ chức. Raizo chờ đợi, và chuẩn bị thời cơ để trả thù.Tại Berlin, điệp vụ Mika Coretti chộp được manh mối về đường dây chuyển tiền giữa các sát thủ chuyên ám sát chính trị gia và một tổ chức sát thủ bí ẩn từ Viễn Đông. Thừa lệnh của cấp trên, Mika xâm nhập vào hệ thống tối ...', 'Ninja Assassin follows Raizo, one of the deadliest assassins in the world. Taken from the streets as a child, he was transformed into a trained killer by the Ozunu Clan, a secret society whose very existence is considered a myth. But haunted by the merciless execution of his friend by the Clan, Raizo breaks free from them and vanishes. Now he waits, preparing to exact his revenge.', 'https://image.tmdb.org/t/p/w780/mq9LDE2OYRaZcUjHHifFrpQLRoq.jpg', 'https://image.tmdb.org/t/p/w1280/44Yi72Ut3NchXewQzx814ViE2dy.jpg', 'https://www.youtube.com/watch?v=H6tg0YwLJQQ', 'James McTeigue', ARRAY['비', 'Naomie Harris', 'Ben Miles', 'Rick Yune', 'Sho Kosugi', 'Randall Duk Kim', 'Sung Kang', '이준']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Giật Gân']::TEXT[], 99, '2009-09-29', NULL, 'US: R', 6.8, 'ended'),
  ('be2e4c1c-942f-5255-8954-d6d451752653'::UUID, 491584, 'Thiêu Đốt', '버닝', 'Burning được xây dựng dựa trên truyện ngắn của nhà văn Nhật Bản Haruki Murakami "Barn Burning" và được thay đổi bối cảnh từ Nhật Bản thành Hàn Quốc. Jong Soo (Yoo Ah In) là một người giao thức ăn nhanh. Một ngày nọ, anh tình cờ va phải Haemi (Jeon Jong Seo), một cô gái anh quen hồi nhỏ, và nhanh chóng bị cái tính thất thường nhưng bí ẩn của cô gái ấy mê hoặc.', 'Deliveryman Jong-su is out on a job when he runs into Hae-mi, a girl who once lived in his neighborhood. She asks if he''d mind looking after her cat while she''s away on a trip to Africa. On her return, she introduces to Jong-su an enigmatic young man named Ben, who she met during her trip. One day Ben tells Jong-su about his most unusual hobby.', 'https://image.tmdb.org/t/p/w780/8zD2FdArQm23xpPpoVFxInGxw8u.jpg', 'https://image.tmdb.org/t/p/w1280/qQEt2FqF8McryFBNX30dyDJKiEK.jpg', 'https://www.youtube.com/watch?v=irBLY-Ev9vo', 'Lee Chang-dong', ARRAY['유아인', 'Steven Yeun', '전종서', '김수경', '최승호', '문성근', '민복기', '이수정']::TEXT[], ARRAY['Bí Ẩn', 'Chính Kịch', 'Giật Gân']::TEXT[], 148, '2018-05-17', NULL, 'KR: 19', 7.4, 'ended'),
  ('6c3482a5-976a-50d7-ba1e-cbefd4cb20cb'::UUID, 4689, 'Quý Ông Báo Thù', '복수는 나의 것', 'Đây là câu chuyện về Ryu, một người đàn ông bị điếc và em gái của anh ta, người cần ghép thận. Để có tiền cấy ghép, Ryu và bạn gái lên kế hoạch bắt cóc con gái của Park. Mọi thứ trở nên tồi tệ một cách khủng khiếp, và tình hình nhanh chóng trở thành một vòng xoáy bạo lực và trả thù.', 'A deaf man and his girlfriend resort to desperate measures in order to fund a kidney transplant for his sister. Things go horribly wrong, and the situation spirals rapidly into a cycle of violence and revenge.', 'https://image.tmdb.org/t/p/w780/zrz5mJuXIhYGHBQndduUoT2JHvm.jpg', 'https://image.tmdb.org/t/p/w1280/b6elu2cz2Be9PqgX0MzggMCH4fk.jpg', 'https://www.youtube.com/watch?v=6D0cjs2NW9w', 'Park Chan-wook', ARRAY['송강호', '신하균', '배두나', '임지은', '한보배', '이대연', '기주봉', '김세동']::TEXT[], ARRAY['Hành Động', 'Chính Kịch', 'Giật Gân']::TEXT[], 129, '2002-03-29', NULL, 'KR: 19', 7.5, 'ended'),
  ('cb4cd3ea-6c8b-5971-a493-1f33bf009304'::UUID, 30018, 'Người Mẹ', '마더', 'Phim kể về câu chuyện của một người mẹ có đứa con mắc bệnh ngại tiếp xúc với xã hội bị vu oan cho một tội ác khủng khiếp. Với tình yêu thương mãnh liệt và nghị lực kiên cường, mẹ của anh quyết tâm tìm cho ra tên thủ ác nhằm giải oan cho con mình. Phim gây ấn tượng sâu sắc bởi diễn xuất tuyệt vời của nữ diễn viên chính Kim Hye-ja trong vai nhân vật người mẹ.', 'A mother lives quietly with her son. One day, a girl is brutally killed, and the boy is charged with the murder. Now, it''s his mother''s mission to prove him innocent.', 'https://image.tmdb.org/t/p/w780/lhxVHEkaOH51oazowpdCHJNLIBE.jpg', 'https://image.tmdb.org/t/p/w1280/mjtocjdhqJNnppHIgBesT3BBIOi.jpg', 'https://www.youtube.com/watch?v=0oBwQHWeYxo', 'Bong Joon Ho', ARRAY['김혜자', '원빈', '진구', '윤제문', '전미선', '송새벽', '이영석', '문희라']::TEXT[], ARRAY['Tội Phạm', 'Chính Kịch', 'Bí Ẩn']::TEXT[], 129, '2009-05-28', NULL, 'KR: 19', 7.7, 'ended'),
  ('cd971a3f-5fad-5bbf-b425-40e9c91656f0'::UUID, 13855, 'Kẻ Săn Đuổi', '추격자', 'Joong-ho is a dirty detective turned pimp, who''s in financial trouble as several of his girls have recently disappeared without clearing their debts. While trying to track them down, he finds a clue that the vanished girls were all called up by the same client, whom one of his girls is meeting with right now.', 'Joong-ho is a dirty detective turned pimp, who''s in financial trouble as several of his girls have recently disappeared without clearing their debts. While trying to track them down, he finds a clue that the vanished girls were all called up by the same client, whom one of his girls is meeting with right now.', 'https://image.tmdb.org/t/p/w780/574WioDX9AC6VwbmhPGpwsH8waN.jpg', 'https://image.tmdb.org/t/p/w1280/urBBFQrrVxy7T8uytrn7dOoHqZn.jpg', 'https://www.youtube.com/watch?v=akiHkFxV24w', '나홍진', ARRAY['김윤석', '하정우', '서영희', '김유정', 'Trịnh Nhân Cơ', '최정우', '민경진', '박효주']::TEXT[], ARRAY['Tội Phạm', 'Giật Gân', 'Hành Động']::TEXT[], 125, '2008-02-14', NULL, 'KR: 19', 7.8, 'ended'),
  ('97750c37-f406-56d5-9d1b-30525f41c1df'::UUID, 705996, 'Quyết Tâm Chia Tay', '헤어질 결심', 'Thám tử Hae Joon được phân công nhiệm vụ điều tra nguyên nhân xung quanh cái chết của một người đàn ông khi leo núi. Cuộc truy tìm dẫn anh đến gặp Seo Rae - vợ của nạn nhân. Tuy nhiên, từ việc nghi ngờ, Hae Joon dần có tình cảm với người phụ nữ bí ẩn với cuộc sống khép kín này. Mối quan hệ rắc rối và tình cảm nhập nhằng khiến anh ngày càng lún sâu vào vụ án.', 'From a mountain peak in South Korea, a man plummets to his death. Did he jump, or was he pushed? When detective Hae-joon arrives on the scene, he begins to suspect the dead man’s wife Seo-rae. But as he digs deeper into the investigation, he finds himself trapped in a web of deception and desire.', 'https://image.tmdb.org/t/p/w780/dq6TekHutTlX2104iOJSAEbUquV.jpg', 'https://image.tmdb.org/t/p/w1280/y7efrL5RlIRsGfrhcaiP35V1x2g.jpg', 'https://www.youtube.com/watch?v=xL5bU-M_qEg', 'Park Chan-wook', ARRAY['Thang Duy', '박해일', '이정현', '고경표', '박용우', '김신영', '유승목', '정이서']::TEXT[], ARRAY['Giật Gân', 'Bí Ẩn', 'Lãng Mạn']::TEXT[], 139, '2022-06-29', NULL, 'KR: 15', 7.3, 'ended'),
  ('ac77c83b-7ab6-5c64-bfca-64f276eea437'::UUID, 581528, 'Trùm, Cớm và Ác Quỷ', '악인전', 'Có ai ngờ được rằng Jang Dong Su - một tay trùm khét tiếng cũng có lúc trở thành nạn nhân của một kẻ giết người máu lạnh?! Chính sự kiện này đã mở ra một cuộc hợp tác bất đắc dĩ giữa ông trùm và gã cớm để truy bắt hung thủ. Tất nhiên, mặc dù phối hợp với nhau nhưng hai bên vẫn ngấm ngầm sử dụng những luật lệ và giữa cho mình những bí mật riêng. Liệu cuộc vây bắt này sẽ diễn ra như thế nào? Ai sẽ người dành được chiến thắng cuối cùng?', 'After barely surviving a brutal attack by a sadistic serial killer, crime boss Jang Dong-su is left humiliated. Determined to catch the killer known as K, he forms an uneasy alliance with Jung Tae-seok, a relentless and incorruptible detective who often disrupts his illegal business. However, while Jang Dong-su wants K dead, Jung Tae-suk is determined to bring him to justice. With a deal in place—whoever finds K first will decide his fate—the hunt begins, blurring the lines between crime and law.', 'https://image.tmdb.org/t/p/w780/1rGVBjZVX1ehI9i3C8BUUScKsro.jpg', 'https://image.tmdb.org/t/p/w1280/jJJQ1PPXUEchqyZ9YyWzgSNU39Z.jpg', 'https://www.youtube.com/watch?v=D1XANQUYSvk', '이원태', ARRAY['Ma Dong-seok', '김무열', '김성규', '허동원', '유재명', '이서환', '오희준', '김규리']::TEXT[], ARRAY['Hành Động', 'Tội Phạm', 'Giật Gân']::TEXT[], 110, '2019-05-15', NULL, 'KR: 19', 7.9, 'ended'),
  ('c2207ad0-9717-54f2-9b8a-2f2483da9a59'::UUID, 51608, 'Sát Thủ Vô Danh', '아저씨', 'Sau một bi kịch, sát thủ chuyên nghiệp Cha Tae Shik rửa tay gác kiếm, lui về ở ẩn. Người duy nhất trò chuyện với anh là cô bé hàng xóm So Mi. Tuy nhiên, mẹ của So Mi lại dính dáng đến 1 đường dây buôn ma túy, cô bé bị bắt cóc. Cha Tae Shik buộc phải lao vào nguy hiểm giải cứu So Mi. Nhưng liệu Cha Tae Shik có cứu được cô bé? Những nguy hiểm nào đang chờ đợi anh?', 'A reclusive pawnshop owner goes on a brutal rampage to rescue a young girl kidnapped by a criminal organization.', 'https://image.tmdb.org/t/p/w780/1f25Iz9h8q6muit4ctCe4ygGr7i.jpg', 'https://image.tmdb.org/t/p/w1280/uEqrGVBELVFaNVMOE4ExjLCMV3j.jpg', 'https://www.youtube.com/watch?v=38rPoGSr19U', '이정범', ARRAY['원빈', 'Kim Sae-ron', '김태훈', '김희원', '김성오', '이종필', 'ธนายง ว่องตระกูล', 'Kim Hyo-seo']::TEXT[], ARRAY['Hành Động', 'Giật Gân', 'Tội Phạm']::TEXT[], 119, '2010-08-04', NULL, 'KR: 19', 7.7, 'ended'),
  ('7d5924b4-f50e-5203-a5a1-52109eb0c48b'::UUID, 1375646, 'Bầy Xác Sống', '군체', 'Giáo sư Se Jeong tham dự một hội nghị công nghệ sinh học, nhưng lại chứng kiến ​​nó biến thành thảm họa khi một loại virus đột biến nhanh chóng được giải phóng. Khi dịch bệnh lan rộng và những người nhiễm bệnh bắt đầu biến đổi, chính quyền đã phong tỏa toàn bộ cơ sở.', 'Professor Se-jeong is thrust into a bloody nightmare when a rapidly mutating virus is released during a biotech conference causing authorities to seal the facility. Trapped inside with no escape, Se-jeong along with a small group of survivors must fight to stay alive while the infected undergo horrific transformations.', 'https://image.tmdb.org/t/p/w780/lzI70txBtLH5kCUixYMJQffKkL9.jpg', 'https://image.tmdb.org/t/p/w1280/iGViga8sDCET1S6GfwOlAbuhSGQ.jpg', 'https://www.youtube.com/watch?v=LW6dpj1uCK8', '연상호', ARRAY['전지현', '구교환', '지창욱', '김신록', '신현빈', '고수', '이중옥', '김종태']::TEXT[], ARRAY['Kinh Dị', 'Hành Động', 'Khoa Học Viễn Tưởng']::TEXT[], 123, '2026-05-21', NULL, 'KR: 15', 8.2, 'ended'),
  ('c9c69493-83a2-5a6d-b335-8df48b7b0300'::UUID, 4552, 'Câu Chuyện Hai Chị Em', '장화, 홍련', 'Trong phim Câu Chuyện Hai Chị Em, sau quá trình điều trị chứng bệnh tâm lý từ khi mẹ mất, hai chị em Su Mi và Su Yeon trở về ngôi nhà nhỏ xinh đẹp của mình. Đón họ là cha đẻ và mẹ kế Iun Joo. Từ đây, những hiện tượng kì quái liên tiếp xảy ra. Tất cả dường như có liên quan tới cái chết đầy khuất tất của người mẹ quá cố, sự thật cuối cùng cũng được phơi bày.  Trong một thập kỷ qua, không một bộ phim kinh dị nào của Hàn Quốc có thể vượt mặt ''A Tale of Two Sisters'' (Câu chuyện hai chị em)', 'Two sisters return home after a stay in a mental institution, only to face disturbing events and a strained relationship with their stepmother. As eerie occurrences unfold, dark family secrets begin to surface, blurring the line between reality and nightmare.', 'https://image.tmdb.org/t/p/w780/xsbh58JyVh7jTuSgFRiHMjVfiVy.jpg', 'https://image.tmdb.org/t/p/w1280/syKbZiHVdXw0NcH6NdXWEKZaECv.jpg', 'https://www.youtube.com/watch?v=Ln0gWJE7SAU', '김지운', ARRAY['임수정', '문근영', '염정아', '김갑수', '박미현', '이승비', '우기홍', '이대연']::TEXT[], ARRAY['Chính Kịch', 'Kinh Dị', 'Bí Ẩn']::TEXT[], 115, '2003-06-13', NULL, 'KR: 12', 7.1, 'ended'),
  ('151e0463-ef07-5b4b-b8d7-1d6bb68c97b8'::UUID, 488623, 'Đêm Ký Ức', '기억의 밤', 'Khi người anh trai bị bắt cóc trở về, mất hết ký ức của 19 ngày trước đó và bắt đầu hành xử kỳ quặc, Jin-seok quyết tâm đi tìm sự thật đằng sau vụ bắt cóc.', 'Jin-seok, 21-year-old, moves into a new house with his family. He suffers from a slight schizophrenia but he carries an ordinary life under the warm care of the family. His older brother Yu-seok is a decent college student, a mentor, and role model for Jin-seok.  One night, his beloved brother is kidnapped by unidentified assailants before Jin-seok''s eye. Jin-seok can’t recognize their faces, but can remember only the VIN that matches with no car. After long silence of 19 days, suddenly Yu-seok returns home, but remembers nothing which had happened in the meantime. And soon Jin-seok feels Yu-seok is a total stranger.', 'https://image.tmdb.org/t/p/w780/pXHLaA2dvIfJ3NbslufKqvS48dt.jpg', 'https://image.tmdb.org/t/p/w1280/tGFII2hY0O0qXPAPGE1fBDOONQJ.jpg', 'https://www.youtube.com/watch?v=i5fAD6PqBMQ', '장항준', ARRAY['강하늘', '김무열', '문성근', '나영희', '남명렬', '이나라', '정택현', '정찬비']::TEXT[], ARRAY['Giật Gân', 'Bí Ẩn', 'Tội Phạm']::TEXT[], 108, '2017-11-29', NULL, 'KR: 15', 7.9, 'ended'),
  ('691bce81-b622-5f15-bd89-01891bf83df5'::UUID, 639988, 'Không Còn Lựa Chọn', '어쩔수가없다', 'Man Soo (Lee Byung Hun), một nhân viên văn phòng bỗng chốc bị sa thải khỏi một công ty mà anh đã gắn bó 25 năm, cuộc sống êm ấm vừa mới có được lại bị đảo ngược. Để chu toàn cho gia đình là vợ Mi Ri (Son Ye Jin) và hai con, người đàn ông này nhất quyết phải sinh tồn đến cùng, bao gồm cả việc nhận những nghề cực đoan nhất.', 'After being laid off and humiliated by a ruthless job market, a veteran paper mill manager descends into violence in a desperate bid to reclaim his dignity.', 'https://image.tmdb.org/t/p/w780/1mwjRFBCabJmfX4jkgiYlnGwHlC.jpg', 'https://image.tmdb.org/t/p/w1280/1eM6Ey1FzpgJigrxRiSYtntSWq7.jpg', 'https://www.youtube.com/watch?v=qlAusp5epFA', 'Park Chan-wook', ARRAY['Lee Byung-hun', 'Son Ye-jin', '박희순', '이성민', '염혜란', '차승원', '오달수', '김우승']::TEXT[], ARRAY['Hài', 'Tội Phạm', 'Giật Gân']::TEXT[], 139, '2025-09-24', NULL, 'KR: 15', 7.5, 'ended'),
  ('c8889e65-609b-58cb-ad2d-c13ccd2ced85'::UUID, 1280, 'Kẻ Ở Nhờ Kỳ Dị', '빈집', 'Tae Soek ngày thường làm nghề phát truyền đơn, còn dán cả lên ở khoá cửa nhà người ta, buổi tối anh đi kiểm tra nếu tờ đơn không bị bỏ xuống thì lẻn vào nhà và xem đó như là nhà của mình. Một ngày, anh đến ngôi nhà của Seon Hwa, chồng của cô luôn ngược đãi và hành hạ cô còn không cho Seon Hwa đi ra khỏi nhà. Tae Soek nhìn thấy tờ đơn vẫn còn trên khoá cửa nên đã đột nhập vào mà không biết Seon Hwa bị nhốt bên trong. Seon Hwa phát hiện có người, còn Tae Soek bỏ đi rồi quay lại thì thấy hình ảnh chồng Seon Hwa hành hạ cô. Tae Soek bèn dùng gậy đáng gold dạy cho chồng Seon Hwa một trận rồi dắt Seon Hwa bỏ trốn. Cả hai cùng trải qua những tháng ngày lén lút sống trong căn nhà của người khác...', 'A drifter lives in people''s houses while they are away and repays them by doing chores for them. His life changes when he meets a beautiful woman who wants to escape her unhappy marriage.', 'https://image.tmdb.org/t/p/w780/oTuOzkKT3gkqvEbB6BrN8cv1gto.jpg', 'https://image.tmdb.org/t/p/w1280/nqY8yuxLU4K9cSCQpsW4PGyotlN.jpg', 'https://www.youtube.com/watch?v=S-S5n0JniDw', '김기덕', ARRAY['이승연', '재희', '권혁호', '주진모', '최정호', '이주석', '이미례', '문성혁']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn', 'Tội Phạm']::TEXT[], 88, '2004-10-15', NULL, 'KR: 15', 7.8, 'ended'),
  ('97d3cf93-4ae2-5082-bf7d-9584cddbabd7'::UUID, 200085, 'Đại Dịch Cúm', '감기', 'Chuyến tàu chở những người vượt biên trái phép sang Hàn quốc không ngờ đang mang trong mình mầm mống hiểm họa khôn lường khi trong số người vượt biên có một người đang mang mầm bệnh dịch. Và điều gì đến đã đến! Những người trốn trong chiếc container trên tàu đều bị nhiễm bệnh mà chết, chỉ còn lại một người...  Kang Ji-Koo là nhân viên cứu hỏa cùng bác sĩ Kim In-Hae phải nhanh chóng cấp cứu và tìm ra chủng loại virus có khả năng gây chết người chỉ sau 36 giờ nhiễm bệnh cùng với cách điều trị.  Và thời gian trở thành vấn đề cực đại khi Kim In Hae phát hiện ra chính con gái mình cũng đang mắc phải loại virus này.', NULL, 'https://image.tmdb.org/t/p/w780/eBGUYZv68bzyoGkqv16yRUfuMEO.jpg', 'https://image.tmdb.org/t/p/w1280/tLxj077KKhBMjnwJkW322VAIbbk.jpg', 'https://www.youtube.com/watch?v=_J8F5sEVsQ4', '김성수', ARRAY['장혁', '수애', '박민하', '유해진', 'Ma Dong-seok', '이희준', '이상엽', '차인표']::TEXT[], ARRAY['Hành Động', 'Khoa Học Viễn Tưởng', 'Giật Gân']::TEXT[], 122, '2013-08-14', NULL, 'KR: 15', 7.5, 'ended'),
  ('2d687e40-5980-5204-8601-7c2deaf8ca46'::UUID, 397567, 'Thử Thách Thần Chết: Giữa Hai Thế Giới', '신과함께-죄와 벌', 'Phim kể về hành trình phiêu lưu sau cái chết của một người đàn ông bình thường tên Ja Hong. Sứ giả được giao nhiệm vụ đến dẫn dắt Ja Hong về với Thế giới ngầm của Thần Chết Yeomra là Kang Rim, chính anh sẽ là người đưa Ja Hong đến 7 thử thách trong vòng 49 ngày trước khi đến gặp mặt đức vua Yeomra của mình. Cuộc hành trình sau cái chết này chính là bài khảo sát chính xác nhất cho Thần Chết Yeomra thấy được bản chất linh hồn của Ja Hong này và sẽ đưa ra quyết định “phán xét” cuối cùng cho anh.', 'Having died unexpectedly, firefighter Ja-hong is taken to the afterlife by 3 afterlife guardians. Only when he passes 7 trials over 49 days and proves he was innocent in human life, he’s able to reincarnate, and his 3 afterlife guardians are by his side to defend him in trial.', 'https://image.tmdb.org/t/p/w780/z0q3qYekotKgZZhSgnBxQkyQVw.jpg', 'https://image.tmdb.org/t/p/w1280/wyv2Y9vXYJwJzF6cNVuVwVOsOUj.jpg', 'https://www.youtube.com/watch?v=dyh_OY1DgqU', '김용화', ARRAY['하정우', '차태현', '주지훈', '김향기', '이정재', '김동욱', '예수정', '오달수']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Chính Kịch', 'Giả Tưởng', 'Giật Gân']::TEXT[], 139, '2017-12-20', NULL, 'KR: 12', 8.1, 'ended'),
  ('97c683d4-aa38-5965-8c86-6f90ac4b7f78'::UUID, 113, 'Xuân, Hạ, Thu, Đông... Rồi Lại Xuân', '봄 여름 가을 겨울 그리고 봄', 'Tại cái hồ cách biệt với thế giới bên ngoài, nơi đó có vị sư già sống trên một thủy am nhỏ. Vị sư nuôi một cậu trai trẻ và dạy dỗ cậu để trở thành một vị hòa thượng. 5 mùa trôi qua, mỗi mùa tượng trưng cho một giai đoạn của cuộc đời vị tiểu hòa thượng này. Phim đem đến những điều thú vị về thân phận, về mâu thuẫn giữa tình yêu trần tục và thánh thiện, giữa sự vô tâm và bản tính tốt đẹp của con người.', 'An isolated lake, where an old monk lives in a small floating temple. The monk has a young boy living with him, learning to become a monk. We watch as seasons and years pass by.', 'https://image.tmdb.org/t/p/w780/kxldBREskmn4QKJyGzl7L5hDxdc.jpg', 'https://image.tmdb.org/t/p/w1280/dgjR7X6WjgjuwJ02idEOxvMyFjP.jpg', 'https://www.youtube.com/watch?v=3rIgudJbHek', '김기덕', ARRAY['오영수', '김기덕', 'Kim Young-min', '서재경', 'Kim Jong-ho', 'Ha Yeo-jin', '김정영', '지대한']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 103, '2003-09-19', NULL, 'KR: 15', 7.8, 'ended'),
  ('1f71f2a2-69a7-5c77-a262-c5b44f0ddab3'::UUID, 437068, 'Tài Xế Taxi', '택시운전사', 'Dựa theo câu chuyện có thật của Phóng viên người Đức Jürgen Hinzpeter và lái xe taxi người Hàn Quốc Kim Sa-Bok. Bối cảnh của A taxi drive được lấy vào tháng 5 của năm 1980, lúc này phóng viên người Đức tên là Peter (Thomas Kretschmann) đang làm việc tại Tokyo, nhưng ở đó tin tức được cập nhật rất chậm. Anh nghe tin từ một đồng nghiệp rằng có một điều gì đó đáng ngại xảy ra ở Gwangju, Hàn Quốc. Các đường dây điện thoại đã bị cắt hoàn toàn trong phạm vi toàn thành phố. Vì thế mà Peter quyết định đến đó để tìm hiểu sự việc.', 'May, 1980. Man-seob is a taxi driver in Seoul who lives from hand to mouth, raising his young daughter alone. One day, he hears that there is a foreigner who will pay big money for a drive down to Gwangju city. Not knowing that he’s a German journalist with a hidden agenda, Man-seob takes the job.', 'https://image.tmdb.org/t/p/w780/pCdx7X5JLaSJZLNVtpryGSdjvvB.jpg', 'https://image.tmdb.org/t/p/w1280/dbXjTu5J00kCggPnQlDpVZmDBil.jpg', 'https://www.youtube.com/watch?v=bB7z4Xn5oNA', '장훈', ARRAY['송강호', 'Thomas Kretschmann', '유해진', '류준열', '박혁권', '최귀화', '차순배', '신담수']::TEXT[], ARRAY['Hành Động', 'Chính Kịch', 'Lịch Sử']::TEXT[], 138, '2017-08-02', NULL, 'KR: 15', 8, 'ended'),
  ('122d53b4-0b0d-5c84-ac93-bdeb763f6ae2'::UUID, 581389, 'Con Tàu Chiến Thắng', '승리호', 'Bám đuổi rác thải ngoài vũ trụ và những giấc mơ xa vời ở năm 2092, bốn kẻ lạc loài phát hiện những bí mật động trời trong khi tìm cách bán robot hình người ngây thơ.', 'When the crew of a space junk collector ship called The Victory discovers a humanoid robot named Dorothy that''s known to be a weapon of mass destruction, they get involved in a risky business deal which puts their lives at stake.', 'https://image.tmdb.org/t/p/w780/lWwgXs8dalqN4BMgEUoJ0HPGp3d.jpg', 'https://image.tmdb.org/t/p/w1280/drulhSX7P5TQlEMQZ3JoXKSDEfz.jpg', 'https://www.youtube.com/watch?v=H1WYnJF1Pwo', '조성희', ARRAY['Song Joong-ki', '김태리', '유해진', '진선규', 'Richard Armitage', '김무열', '박예린', 'Oh Ji-yul']::TEXT[], ARRAY['Chính Kịch', 'Giả Tưởng', 'Khoa Học Viễn Tưởng']::TEXT[], 136, '2021-02-05', NULL, 'KR: 12', 7, 'ended'),
  ('4fe75611-6a88-5f57-b602-306a99d003ad'::UUID, 486589, 'Hài Đỏ & Bảy Chú Lùn', '레드슈즈', '7 chàng hoàng tử vì bị phù phép mà biến thành 7 chú lùn da xanh. Muốn hóa giải lời nguyền ác độc này, họ phải có được tình yêu chân thành từ cô gái mang đôi hài đỏ xinh đẹp nhất trần đời. Đến một ngày, nàng Hài Đỏ đã tìm đến ngôi nhà của 7 chú lùn, nhưng việc hóa giải lời nguyền lại không đơn giản đến thế…', 'Princes who have been turned into Dwarfs seek the red shoes of a lady in order to break the spell, although it will not be easy.', 'https://image.tmdb.org/t/p/w780/fV7ehJEjFiQlljrDhfknEDxELCU.jpg', 'https://image.tmdb.org/t/p/w1280/nN4Gs3vZAOJ1D6FRtrwbU9VGYwU.jpg', 'https://www.youtube.com/watch?v=NB3mZMyxcM0', '홍성호', ARRAY['안소이', '신용우', '전진아', '정재헌', '최한', 'Kwon Sung-hyuk', '윤세웅', '유호한']::TEXT[], ARRAY['Hoạt Hình', 'Giả Tưởng', 'Gia Đình', 'Hài', 'Lãng Mạn', 'Phiêu Lưu']::TEXT[], 92, '2019-07-25', NULL, 'KR: ALL', 7.7, 'ended'),
  ('80aae468-7a69-5115-bb17-51b95fae644e'::UUID, 22536, 'Người Tình Ma Cà Rồng', '박쥐', 'Thirst là một bộ phim nói về tình yêu không lối thoát giữa một vị linh mục và vợ của bạn ông. Ông trở thành ma ca rồng sau khi bị nhiễm máu từ một nơi không rõ nguồn gốc. (phim tình cảm kinh dị, không phù hợp với trẻ em)', 'A respected priest volunteers for an experimental procedure that may lead to a cure for a deadly virus. He gets infected and dies, but a blood transfusion of unknown origin brings him back to life. Now, he’s torn between faith and bloodlust, and has a newfound desire for the wife of a childhood friend.', 'https://image.tmdb.org/t/p/w780/2CoIYuNwGmdhsV5CM8jRJ2sAZKe.jpg', 'https://image.tmdb.org/t/p/w1280/9IMZqBKbALO7d2bwr6ECKP4igoe.jpg', 'https://www.youtube.com/watch?v=j9XMJJ5DZso', 'Park Chan-wook', ARRAY['송강호', '김옥빈', '김해숙', '신하균', '박인환', '송영창', '오달수', 'Ériq Ebouaney']::TEXT[], ARRAY['Chính Kịch', 'Kinh Dị', 'Giật Gân']::TEXT[], 134, '2009-04-30', NULL, 'KR: 19', 7.1, 'ended'),
  ('dd944a60-9a4a-5a02-850e-9710f6122002'::UUID, 11344, 'Ngọt Đắng Cuộc Đời', '달콤한 인생', 'Sunwoo là một trong những tay chân được ông chủ khách sạn Crown tin cậy nhất, vì lẽ đó mà khi ông rời Hàn Quốc sang Thượng Hải để bàn công việc thì anh được ông giao cho nhiệm vụ chăm sóc cô người yêu trẻ tuổi của mình. Chỉ gặp gỡ cô chưa đến ba ngày nhưng Sunwoo đã có tình cảm đặc biệt với Heesoo và điều đó đã dẫn dắt đưa anh tới những hoàn cảnh rất trớ trêu...', 'Kim Sun-woo is an enforcer and manager for a hotel owned by a cold, calculative crime boss, Kang who assigns Sun-woo to a simple errand while he is away on a business trip; to shadow his young mistress, Hee-soo, for fear that she may be cheating on him with a younger man with the mandate that he must kill them both if he discovers their affair.', 'https://image.tmdb.org/t/p/w780/bo5882JREd8LjbziR8F0h7HuOLs.jpg', 'https://image.tmdb.org/t/p/w1280/t8EDE4bkYZBaSCo7Gq8uIWtW4pV.jpg', 'https://www.youtube.com/watch?v=q5O2tfiaTxU', '김지운', ARRAY['Lee Byung-hun', '김영철', '신민아', '김뢰하', '이기영', '황정민', '에릭', '오달수']::TEXT[], ARRAY['Hành Động', 'Chính Kịch', 'Tội Phạm']::TEXT[], 119, '2005-04-01', NULL, 'KR: 19', 7.4, 'ended'),
  ('5fca354e-731b-538c-ba46-f87f9fb4f49c'::UUID, 575604, 'Cuộc Gọi', '콜', 'Kết nối qua điện thoại ở cùng một căn nhà nhưng cách nhau 20 năm, kẻ sát nhân hàng loạt đe dọa quá khứ - và tính mạng - của một phụ nữ khác để thay đổi số phận bản thân.', 'Connected by phone in the same home but 20 years apart, a caller puts a woman’s past — and life — on the line to change her own fate.', 'https://image.tmdb.org/t/p/w780/HKr6HSGZyZBcI38rR1NjwsIcc0.jpg', 'https://image.tmdb.org/t/p/w1280/iDw6J49rf7Xlu9QZBWpvmrMqSzI.jpg', 'https://www.youtube.com/watch?v=hxkKeniT-0Q', '이충현', ARRAY['박신혜', '전종서', '김성령', '이엘', '박호산', '오정세', '이동휘', 'Um Chae-young']::TEXT[], ARRAY['Giật Gân', 'Bí Ẩn', 'Khoa Học Viễn Tưởng']::TEXT[], 112, '2020-11-23', NULL, 'KR: 15', 7.5, 'ended'),
  ('7aa3b5f1-db94-5914-a0f7-3caf0b93de5c'::UUID, 508642, 'Gonjiam: Bệnh Viện Ma Ám', '곤지암', 'Một đài truyền hình internet tuyển một số ít người cho chương trình ''trải nghiệm kinh dị'' của họ tại Bệnh viện Tâm thần Gonjiam, nơi được chọn là một trong ''7 nơi tự do nhất trên hành tinh''. Họ phải khám phá trại tị nạn ma ám và phát trực tiếp nó trên chương trình trực tuyến của họ.', 'The crew of a horror web series travels to an abandoned asylum for a live broadcast, but they encounter much more than expected as they move deeper inside the nightmarish old building.', 'https://image.tmdb.org/t/p/w780/llj8dIkLSHOG1X7aFXims2IaCU5.jpg', 'https://image.tmdb.org/t/p/w1280/dMvDaoT9RGFL8ld5YFb451JY1X9.jpg', 'https://www.youtube.com/watch?v=NWKl_9B09O0', '정범식', ARRAY['위하준', '박지현', '오아연', '문예원', '박성훈', '이승욱', '유제윤', '박지아']::TEXT[], ARRAY['Kinh Dị', 'Bí Ẩn']::TEXT[], 95, '2018-03-28', NULL, 'KR: 15', 7.3, 'ended'),
  ('94f16525-0db0-5829-8ef0-d0fcd493f927'::UUID, 255709, 'Hy Vọng', '소원', 'Dựa trên câu chuyện có thật. Phim Hy Vọng - Hope, còn được gọi là Wish, là câu chuyện về bi kịch xảy đến với cô con gái bé nhỏ So-won trong một lần đi học từ trường về nhà. Cha cô bé – Dong-hoon – nhận được điện thoại từ bệnh viện thông báo So-won đang bị chấn thương cả về thể xác lẫn tinh thần. Liệu gia đình của họ có vượt qua được quá khứ và trở về là một mái ấm như ngày xưa... Là một bộ phim Hàn Quốc năm 2013 của đạo diễn Lee Joon-ik, với sự tham gia của Sol Kyung-gu, Uhm Ji-won và Lee Re. Phim đã giành giải Phim hay nhất tại Giải thưởng Phim Rồng Xanh lần thứ 34.', 'After 8-year-old So-won narrowly survives a brutal sexual assault, her family labors to help her heal while coping with their own rage and grief.', 'https://image.tmdb.org/t/p/w780/1e2I2Ys9V2Jx3CDl8VdoUtpg5tt.jpg', 'https://image.tmdb.org/t/p/w1280/cri20wZDTl1X5QpxlWCSJ4HSpTF.jpg', NULL, '이준익', ARRAY['설경구', '엄지원', '이레', '김상호', '김해숙', '라미란', '권태원', '강신철']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 123, '2013-10-02', NULL, 'KR: 12', 8.4, 'ended'),
  ('5ed78a04-cda7-504f-966d-1b4e42602407'::UUID, 2440, 'Khu Vực An Ninh Chung', '공동경비구역 JSA', 'Phim về quân đội giữa Bắc và Nam Hàn Quốc cũng như về JSA, nơi mà được căn giữ bởi 2 đất nước . Hai người lính của Bắc Hàn bị bắn chết cũng là khi mà mọi việc bắt đầu trớ nên nghiêm trọng có thể gây chiến tranh giữa hai nước 1 lần nữa ....', 'Two North Korean soldiers are killed in the border area between North and South Korea, prompting an investigation by a neutral body. The lead investigator (Lee Young-ae) receives differing accounts from the two sides.', 'https://image.tmdb.org/t/p/w780/sXhPjXEuCm4oVXTdcW67QFfDpqz.jpg', 'https://image.tmdb.org/t/p/w1280/z7w6ACQJTeGYASr1plSwfRe6Ytk.jpg', 'https://www.youtube.com/watch?v=9SyVl0SDpjg', 'Park Chan-wook', ARRAY['이영애', 'Lee Byung-hun', '송강호', '김태우', '신하균', 'Herbert Ulrich', 'Christoph Hofrichter', '이한위']::TEXT[], ARRAY['Chính Kịch', 'Giật Gân', 'Bí Ẩn']::TEXT[], 108, '2000-09-09', NULL, 'KR: 15', 7.8, 'ended'),
  ('6e2c3a35-53dc-5581-82c6-5884042beb3e'::UUID, 626412, 'Alienoid 2: Đa Chiều Hỗn Chiến', '외계+인 2부', 'Ean (KIM Tae-ri) bị mắc kẹt ở quá khứ trong khi cố ngăn chặn sự trốn thoát của những tù nhân ngoài hành tinh bị nhốt trong cơ thể con người. Cô cuối cùng đã tìm thấy Gươm Thần, có thể mở ra cánh cổng xuyên thời gian, và giờ phải tìm Thunder (KIM Woo-bin) để trở về hiện tại. Trong khi đó, Muruk (RYU Jun-yeol), người giúp Ean thoát khỏi những tình huống nguy hiểm, bắt đầu cảm thấy bất an khi anh nhận thấy sự hiện diện của một sinh vật lạ trong cơ thể mình. Trở lại hiện tại, sự phát tán của khí haava bởi Thủ Lĩnh, kẻ lãnh đạo những tù nhân ngoài hành tinh đã khiến hàng ngàn người chết. Min Gaelin (LEE Ha-nee) người tình cờ chứng kiến điều này đã nhận ra rằng đây chỉ là khởi đầu...', 'Ean has a critical mission to return to the future to save everyone. However, she becomes trapped in the distant past while trying to prevent the escape of alien prisoners who are locked up in the bodies of humans. Meanwhile, Muruk, who helps Ean escape various predicaments, is unnerved when he begins sensing the presence of a strange being in his body. Traveling through the centuries, they are trying to prevent the explosion of the haava.', 'https://image.tmdb.org/t/p/w780/hBQhm2nHUTeKmtecGL5GpJNz2oI.jpg', 'https://image.tmdb.org/t/p/w1280/wG2WlIxdYDTdFrHm4WUj6oOjjQS.jpg', 'https://www.youtube.com/watch?v=s3MawvrYNH4', '최동훈', ARRAY['류준열', '김태리', 'Kim Woo-bin', '이하늬', '염정아', '조우진', '김의성', '진선규']::TEXT[], ARRAY['Hành Động', 'Giả Tưởng', 'Phiêu Lưu', 'Khoa Học Viễn Tưởng']::TEXT[], 122, '2024-01-10', NULL, 'KR: 12', 6.7, 'ended'),
  ('245da4e7-68e9-515b-bcf2-dc901611574a'::UUID, 851644, 'Cô Gái Thế Kỷ 20', '20세기 소녀', 'Cô Gái Thế Kỷ 20 kể về năm 1999, một cô nàng tuổi teen theo dõi sát sao một nam sinh trong trường thay cho cô bạn thân si tình. Nhưng rồi, chính cô lại bị cuốn vào câu chuyện tình của riêng mình', 'In 1999, a teen girl keeps close tabs on a boy in school on behalf of her deeply smitten best friend – then she gets swept up in a love story of her own.', 'https://image.tmdb.org/t/p/w780/48HN7KUTQIH6pdGLZeXkCt6LHQY.jpg', 'https://image.tmdb.org/t/p/w1280/37y53Jt8K6MvN6s4zJVFa61luO2.jpg', 'https://www.youtube.com/watch?v=KFS4_qevE7M', 'Bang Woo-ri', ARRAY['김유정', 'Biến Hựu Tích', '박정우', '노윤서', '김성경', '정석용', '윤이레', '전혜원']::TEXT[], ARRAY['Lãng Mạn', 'Chính Kịch']::TEXT[], 119, '2022-10-06', NULL, 'KR: 12', 8.2, 'ended'),
  ('e57a68ee-b3f3-50bd-8622-d9e6ce480817'::UUID, 15067, 'Thiện, Ác, Quái', '좋은 놈, 나쁜 놈, 이상한 놈', 'Vượt qua mọi kỷ lục trong nước về kinh phí sản xuất, “The Good, The Bad, The Weird” là phim có kinh phí sản xuất lớn nhất trong lịch sử điện ảnh Hàn Quốc (17 triệu USD ). “The Good, The Bad, The Weird” tái hiện lại Mãn Châu những năm 30 của thế kỷ trước, khi thế giới đang trong cảnh hỗn loạn. Lúc đó ở châu Á, Triều Tiên rơi vào bàn tay của phát xít Nhật. Nhiều người dân Triều Tiên đã tới vùng thảo nguyên hoang dã Manchuria, giáp ranh giữa Mông Cổ và Trung Quốc để lánh nạn. Và để tồn tại trong môi trường đầy khó khăn, một số người trở thành những tên cướp trên lưng ngựa để kiếm sống tại vùng đất hoang sơ cằn cỗi này. Bộ phim xoay quanh 3 nhân vật: The Good – Thiện (Jung Woo Sung), The Bad – Ác (Lee Byung Hun) và The Weird – Quái ...', 'The story of three Korean outlaws in 1930s Manchuria and their dealings with the Japanese army and Chinese and Russian bandits. The Good (a bounty hunter), the Bad (a hitman), and the Weird (a thief) battle the army and the bandits in a race to use a treasure map to uncover the riches of legend.', 'https://image.tmdb.org/t/p/w780/inPPsMpQBKfDORKqemLZn8kQDTp.jpg', 'https://image.tmdb.org/t/p/w1280/gec3e76TRGUBx1Ut0c6yuSahVDp.jpg', 'https://www.youtube.com/watch?v=HSBKqPbZz0Y', '김지운', ARRAY['송강호', 'Lee Byung-hun', '정우성', '윤제문', '류승수', '송영창', '손병호', '오달수']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Hài', 'Miền Tây']::TEXT[], 130, '2008-07-16', NULL, 'KR: 15', 7.2, 'ended'),
  ('e4a3617d-0e7f-5adf-83d6-a48817c2d8e6'::UUID, 838209, 'Exhuma: Quật mộ trùng ma', '파묘', 'Hai pháp sư, một thầy phong thuỷ và một chuyên gia khâm liệm cùng hợp lực khai quật ngôi mộ bị nguyền rủa của một gia đình giàu có, nhằm cứu lấy sinh mạng hậu duệ cuối cùng trong dòng tộc. Bí mật hắc ám của tổ tiên được đánh thức.', 'After tracing the origin of a disturbing supernatural affliction to a wealthy family''s ancestral gravesite, a team of paranormal experts relocates the remains—and soon discovers what happens to those who dare to mess with the wrong grave.', 'https://image.tmdb.org/t/p/w780/enAODUiL6eMpKaYPH2BEStVafQ2.jpg', 'https://image.tmdb.org/t/p/w1280/kYWk8TW5TkpCWkB0mkUm72N0lb8.jpg', 'https://www.youtube.com/watch?v=j_6_wLF1pDg', '장재현', ARRAY['최민식', '김고은', '유해진', '이도현', '김재철', '전진기', '김선영', '김지안']::TEXT[], ARRAY['Bí Ẩn', 'Kinh Dị', 'Giật Gân']::TEXT[], 134, '2024-02-22', NULL, 'KR: 15', 7.6, 'ended'),
  ('e8986c69-1af5-50d9-9a85-563c409cd2a6'::UUID, 933131, 'Thợ săn hoang mạc', '황야', 'Sau trận động đất đầy chết chóc biến Seoul thành vùng đất hoang vô pháp, người thợ săn dũng cảm nọ gấp rút hành động để giải cứu cô thiếu nữ bị tay bác sĩ điên bắt cóc.', 'After a deadly earthquake turns Seoul into a lawless badland, a fearless huntsman springs into action to rescue a teenager abducted by a mad doctor.', 'https://image.tmdb.org/t/p/w780/9BeUxFjlaXHwjqS1ODeAbYdK27X.jpg', 'https://image.tmdb.org/t/p/w1280/qLQiQXe8tHk8mokDH0LoKudPDH3.jpg', 'https://www.youtube.com/watch?v=7u3zBVAxx_w', '허명행', ARRAY['Ma Dong-seok', '이준영', '이희준', '노정의', '안지혜', '박지훈', '강성욱', '이성우']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Giật Gân']::TEXT[], 107, '2024-01-26', NULL, 'KR: 19', 6.7, 'ended'),
  ('ea11060d-8b9b-5d2e-b804-44c4bb805cc6'::UUID, 81481, 'Sự Im Lặng', '도가니', 'Kang In Ho - một giáo viên mới được bổ nhiệm tại một trường khiếm thính ở thành phố Mujin. Trên đường đến công việc mới của mình, In Ho tình cờ gặp Yoo Jin, một nhân viên tại Trung tâm Nhân quyền Mujin. Tại ngôi trường mới, In Ho và Yoo Jin khám phá ra những điều không tưởng do các giáo viên ở trường làm với chính học sinh của mình. Liệu In Ho có tiếp tục im lặng, câm điếc như những đứa trẻ nơi đây? Hoặc anh ấy có thể gạt những khó khăn về tài chính của gia đình sang một bên để dũng cảm phá bỏ sự im lặng trong ngôi trường này. Quyết định của Kang In Ho là gì? Và sự thật đó là gì?', 'Based on actual events that took place at Gwangju Inhwa School for the hearing-impaired, where young deaf students were the victims of repeated sexual assaults by faculty members over a period of five years in the early 2000s.', 'https://image.tmdb.org/t/p/w780/DTlXHKuL0gOoZ0tIXYlV1j7e8X.jpg', 'https://image.tmdb.org/t/p/w1280/3xTS1lDlbpwg63slWSMeHdamOS1.jpg', 'https://www.youtube.com/watch?v=SSZh4qb8ybs', '황동혁', ARRAY['공유', '정유미', '김현수', '정인서', '백승환', '장광', '김주령', '김민상']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 125, '2011-09-22', NULL, 'KR: 19', 8.2, 'ended'),
  ('b0c28f7a-664b-5097-bacd-415544c4d400'::UUID, 530254, 'Sát Thủ Nhân Tạo', '마녀', 'Sát Thủ Nhân Tạo là bộ phim hành động li kì kể về Koo Ja-yoon – một cô bé được nuôi dưỡng trong một tổ chức đáng sợ - nơi diễn ra các cuộc thí nghiệm y học được thực hiện trên chính cơ thể con người nhằm biến họ thành những cỗ máy giết người. Sau khi chạy trốn khỏi tổ chức, Ja-yoon bị mất trí nhớ và được một cặp vợ chồng già nhận nuôi.  10 năm sau, khi đã trở thành một nữ sinh trung học, Ja-yoon đăng ký tham gia một cuộc thi âm nhạc với mong muốn giúp gia đình vượt qua khó khăn tài chính. Nhưng cô không ngờ rằng, ngay từ khi hình ảnh của mình xuất hiện trên truyền hình, cuộc sống của cô bị đảo lộn hoàn toàn bởi sự truy đuổi của những kẻ lạ mặt.', NULL, 'https://image.tmdb.org/t/p/w780/8rDtW3xN074V8QoRpkt1Hocq5VX.jpg', 'https://image.tmdb.org/t/p/w1280/f8ng3EDMLkuTMupe4TjgiJS1r0S.jpg', 'https://www.youtube.com/watch?v=X8s2zX1gOHk', '박훈정', ARRAY['김다미', '조민수', '박희순', 'Choi Woo-shik', '고민시', '최정우', '오미희', '김병옥']::TEXT[], ARRAY['Hành Động', 'Chính Kịch', 'Khoa Học Viễn Tưởng']::TEXT[], 125, '2018-06-27', NULL, 'KR: 15', 7.9, 'ended'),
  ('defa4250-662a-57a2-969b-f825af5aaf48'::UUID, 437109, 'Ác Nữ Báo Thù', '악녀', 'Sook Hee – một cô gái có số phận vô cùng nghiệt ngã, sau khi chứng kiến cha mình bị giết, đã được Lee Joong Sang giải cứu và huấn luyện trở thành sát thủ, hòng trở về Hàn Quốc trả thù. Sau vụ trả thù đẫm máu, Soo Hee bị Cục Tình báo Hàn Quốc bắt giữ. Nhận thấy năng lực của cô, họ đã đề nghị Sook Hee trở thành mật vụ ngầm trong vòng 10 năm. “Làm việc cho chúng tôi 10 năm, cô sẽ được tự do. Nhưng nếu thân phận của cô bị lộ, chúng tôi sẽ trừ khử cô.”', 'Honed from childhood into a merciless killing machine by a criminal organization, assassin Sook-hee is recruited with the promise of freedom after ten years of service. However, secrets from her past destroy everything she’s worked for and now she embarks on a roaring rampage of revenge.', 'https://image.tmdb.org/t/p/w780/2arvz5fsrE1BmlbjbBHSiLltlLq.jpg', 'https://image.tmdb.org/t/p/w1280/labMpUVoAqNlHTKiu7KsoZT0v9d.jpg', 'https://www.youtube.com/watch?v=ettsG15TD2Q', '정병길', ARRAY['김옥빈', '신하균', '성준', '김서형', '조은지', 'Lee Seung-joo', '정해균', '박철민']::TEXT[], ARRAY['Hành Động', 'Giật Gân']::TEXT[], 129, '2017-06-08', NULL, 'KR: 19', 6.9, 'ended'),
  ('72076d9d-7a13-5068-af5a-126df6ce6450'::UUID, 129, 'Vùng Đất Linh Hồn', '千と千尋の神隠し', 'Câu chuyện kể về cô bé bướng bỉnh Chihiro. Gia đình của Chihiro chuyển từ thành phố về quê sinh sống, và Chihiro chẳng thích thú tí nào với sự thay đổi này.  Bố của Chihiro là một tay lái xe tệ hại và có một trí nhớ "quá tồi", ông đã lái xe lạc đường đến một thành phố bị bỏ hoang, không bóng người. Bị cuốn hút bởi mùi vị thơm ngon của thức ăn, bố mẹ của Chihiro bắt đầu "thưởng thức", nhưng kết quả họ bị biến thành những con heo mập. Còn thành phố không người kia, sau khi trời tối, tất cả sống dậy, những bóng ma bắt đầu xuất hiện và hoạt động. Cô bé bướng bỉnh phải làm gì để cứu bố mẹ mình và thoát khỏi đây?', 'A young girl, Chihiro, becomes trapped in a strange new world of spirits. When her parents undergo a mysterious transformation, she must call upon the courage she never knew she had to free her family.', 'https://image.tmdb.org/t/p/w780/pNHppsjxGBcRUCFlXQh0briymTN.jpg', 'https://image.tmdb.org/t/p/w1280/m4TUa2ciEWSlk37rOsjiSIvZDXE.jpg', 'https://www.youtube.com/watch?v=GAp2_0JJskk', '宮崎駿', ARRAY['柊瑠美', 'Irino Miyu', '夏木マリ', '内藤剛志', '沢口靖子', '我修院達也', 'Kamiki Ryunosuke', '玉井夕海']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Giả Tưởng']::TEXT[], 135, '2001-07-20', NULL, 'JP: G', 8.5, 'ended'),
  ('6cecea45-0d6f-51da-baa0-b1a35b55a04b'::UUID, 372058, 'Tên Cậu Là Gì?', '君の名は。', 'Bộ phim là câu chuyện hoán đổi cơ thể của 2 cô cậu Mitsuha - nữ sinh trung học sống ở một thị trấn nhỏ của vùng Itomori và Taki – nam sinh tại thủ đô Tokyo đầy sôi động. Mitsuha luôn chán chường với cuộc sống tẻ nhạt của mình và mơ ước được làm anh chàng đẹp trai sống tại thủ đô. Trong khi đó, Taki hằng đêm lại nhìn thấy mình trong hình hài cô gái vùng miền quê. Ước mơ của cả 2 đã thành sự thật khi sao chổi nghìn năm xuất hiện trên trái đất và rồi cứ cách ngày lại được hoán đổi cơ thể cho nhau.', 'High schoolers Mitsuha and Taki are complete strangers living separate lives. But one night, they suddenly switch places. Mitsuha wakes up in Taki’s body, and he in hers. This bizarre occurrence continues to happen randomly, and the two must adjust their lives around each other.', 'https://image.tmdb.org/t/p/w780/yV8ARrvpWaWd509QM4LwMScNDvZ.jpg', 'https://image.tmdb.org/t/p/w1280/mMtUybQ6hL24FXo0F3Z4j2KG7kZ.jpg', 'https://www.youtube.com/watch?v=TYku4P7MHdo', '新海誠', ARRAY['Kamiki Ryunosuke', 'Kamishiraishi Mone', 'Narita Ryo', '悠木碧', '島﨑信長', 'Ishikawa Kaito', '谷花音', 'てらそままさき']::TEXT[], ARRAY['Hoạt Hình', 'Lãng Mạn', 'Chính Kịch']::TEXT[], 106, '2016-07-01', NULL, 'JP: G', 8.5, 'ended'),
  ('1aff329d-160a-5362-99a5-f6738d75824b'::UUID, 4935, 'Lâu Đài Bay Của Pháp Sư Howl', 'ハウルの動く城', 'Sophie vốn dĩ làm việc tại cửa hàng mũ do người cha quá cố để lại. Cuộc sống nơi thị trấn buồn tẻ cứ thế trôi qua trong lặng lẽ... cho đến ngày cô bỗng biến thành bà lão.', 'Sophie, a young milliner, is turned into an elderly woman by a witch who enters her shop and curses her. She encounters a wizard named Howl and gets caught up in his resistance to fighting for the king.', 'https://image.tmdb.org/t/p/w780/jEa7VIZvKYr3iACvcfNqGWDUIun.jpg', 'https://image.tmdb.org/t/p/w1280/nv5wwZou159v5OC61i4ElR7OqyY.jpg', 'https://www.youtube.com/watch?v=ARCQf2CEr8k', '宮崎駿', ARRAY['倍賞千恵子', '木村拓哉', '美輪明宏', '我修院達也', 'Kamiki Ryunosuke', '伊崎充則', '大泉洋', '大塚明夫']::TEXT[], ARRAY['Giả Tưởng', 'Hoạt Hình', 'Phiêu Lưu']::TEXT[], 119, '2004-09-09', NULL, 'US: PG', 8.4, 'ended'),
  ('7245d403-b6db-5718-b3d5-916c270d1a10'::UUID, 128, 'Công Chúa Sói Mononoke', 'もののけ姫', 'Bị trúng lời nguyền chết chóc, vị hoàng tử lên đường tìm cách hóa giải, để rồi rơi vào cuộc chiến giữa một thị trấn khai thác mỏ và các loài động vật trong rừng.', 'Ashitaka, a prince of the disappearing Emishi people, is cursed by a demonized boar god and must journey to the west to find a cure. Along the way, he encounters San, a young human woman fighting to protect the forest, and Lady Eboshi, who is trying to destroy it. Ashitaka must find a way to bring balance to this conflict.', 'https://image.tmdb.org/t/p/w780/aULj23Vb5koGiWn4GGapdFIQFCn.jpg', 'https://image.tmdb.org/t/p/w1280/gl0jzn4BupSbL2qMVeqrjKkF9Js.jpg', 'https://www.youtube.com/watch?v=I1dHzoRl0sQ', '宮崎駿', ARRAY['松田洋治', '石田ゆり子', '田中裕子', 'Kobayashi Kaoru', '西村雅彥', '上條恒彦', '美輪明宏', '森光子']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Hoạt Hình']::TEXT[], 134, '1997-07-12', NULL, 'JP: G', 8.3, 'ended'),
  ('bad993ac-8c59-5194-8945-790e30392616'::UUID, 8392, 'Hàng Xóm Của Tôi Là Totoro', 'となりのトトロ', 'Những ngày cùng cha nghỉ hè tại miền quê thuộc đất nước Nhật Bản, hai chị em bé nhỏ đã kết bạn với những sinh vật huyền bí sống trong khu rừng gần đó.', 'Two sisters move to the country with their father in order to be closer to their hospitalized mother, and discover the surrounding trees are inhabited by Totoros, magical spirits of the forest. When the youngest runs away from home, the older sister seeks help from the spirits to find her.', 'https://image.tmdb.org/t/p/w780/cogogd1s0xSafd9PE6dtwEry4Oz.jpg', 'https://image.tmdb.org/t/p/w1280/zkThiZAaAie8Lw7RAc5yPTOewBV.jpg', 'https://www.youtube.com/watch?v=_nv94fL_IA8', '宮崎駿', ARRAY['日髙のり子', '坂本千夏', '高木均', '糸井重里', '島本須美', '北林谷栄', '雨笠利幸', '丸山優子']::TEXT[], ARRAY['Giả Tưởng', 'Hoạt Hình', 'Gia Đình']::TEXT[], 86, '1988-04-16', NULL, 'US: G', 8.1, 'ended'),
  ('ded67758-ae48-53c8-b3a5-a743f81338bc'::UUID, 12477, 'Mộ Đom Đóm', '火垂るの墓', 'Bộ phim được đặt trong bối cảnh giai đoạn cuối chiến tranh thế giới thứ 2 ở Nhật, kể về câu chuyện cảm động về tình anh em của hai đứa trẻ mồ côi là Seita và Setsuko. Hai anh em mất mẹ trong một trận bom dữ dội của không quân Mỹ khi cha của chúng đang chiến đấu cho Hải quân Nhật. Hai đứa bé phải vật lộn giữa nạn đói, giữa sự thờ ơ của những người xung quanh (trong đó có cả người cô họ của mình)...', 'In the final months of World War II, 14-year-old Seita and his sister Setsuko are orphaned when their mother is killed during an air raid in Kobe, Japan. After a falling out with their aunt, they move into an abandoned bomb shelter. With no surviving relatives and their emergency rations depleted, Seita and Setsuko struggle to survive.', 'https://image.tmdb.org/t/p/w780/LMLFDXvYrHpdPCbqwGmGIXygdD.jpg', 'https://image.tmdb.org/t/p/w1280/aHaqZpOL7UyVu0nKqp3SMz0o2E1.jpg', 'https://www.youtube.com/watch?v=QZbcx0WNrMU', 'Takahata Isao', ARRAY['辰巳努', '白石綾乃', '志乃原良子', '山口朱美', 'Masayo Sakai', 'Kozo Hashida', 'Kazumi Nozaki', 'Yoshio Matsuoka']::TEXT[], ARRAY['Hoạt Hình', 'Chính Kịch', 'Chiến Tranh']::TEXT[], 89, '1988-04-16', NULL, 'US: NR', 8.5, 'ended'),
  ('2426745e-4120-57d6-8a0a-2be7e39f8e36'::UUID, 149, 'Chúa Tể Akira', 'AKIRA', 'Akira (Chúa tể Akira) Tháng bảy năm 1988, một vụ nổ bí ẩn nhấn chìm Tokyo vào biển lửa, đồng thời châm ngòi cho đại chiến thế giới lần ba. Ba mươi mốt năm sau, chiến tranh kết thúc. Tokyo vực dậy từ đống tro tàn và dần phát triển thành một trong những thành phố thịnh vượng nhất thế giới, kéo theo đó là tình trạng đạo đạo đức và nhân tính suy tàn do sự lên ngôi của tiền bạc, vật chất trong xã hội. Kaneda và Tetsuo là bạn chí cốt và cũng là thành viên của băng đua xe Capsule. Trong cái đêm định mệnh khi giao đấu với băng đảng đối địch, Tetsuo tình cờ chạm trán với một mẫu vật trốn thoát khỏi phòng thí nghiệm. Cuộc chạm trán nhanh chóng biến thành thảm họa khi cả mẫu vật lẫn Tetsuo đều bị chính phủ bắt giữ. Nhiệm vụ của Kaneda bây giờ là phải tìm mọi cách cứu Tetsuo. Thế nhưng số phận sớm đẩy cả Kaneda lẫn Tetsuo vào vòng xoáy bạo lực khi những bí mật từ hơn ba mươi năm trước dần được hé lộ.', 'A secret military project endangers Neo-Tokyo when it turns a biker gang member into a rampaging psychic psychopath that only two teenagers and a group of psychics can stop.', 'https://image.tmdb.org/t/p/w780/zQwWFbQf2zAXExdCDASdKbXNkLb.jpg', 'https://image.tmdb.org/t/p/w1280/fK40VGYIm7hmKrLJ26fgPQU0qRG.jpg', 'https://www.youtube.com/watch?v=Jq4ER-P6NCQ', '大友克洋', ARRAY['岩田光央', '佐々木望', '小山茉美', '石田太郎', '鈴木瑞穂', '玄田哲章', '北村弘一', '渕崎ゆり子']::TEXT[], ARRAY['Hoạt Hình', 'Khoa Học Viễn Tưởng', 'Hành Động']::TEXT[], 124, '1988-07-16', NULL, 'US: R', 7.9, 'ended'),
  ('40de093b-51dd-562c-a503-86e52398258c'::UUID, 12429, 'Cô Bé Ponyo', '崖の上のポニョ', 'Cậu bé năm tuổi Sosuke làm bạn với Ponyo – cô công chúa cá vàng tha thiết muốn trở thành con người.', 'When Sosuke, a young boy who lives on a clifftop overlooking the sea, rescues a stranded goldfish named Ponyo, he discovers more than he bargained for. Ponyo is a curious, energetic young creature who yearns to be human, but even as she causes chaos around the house, her father, a powerful sorcerer, schemes to return Ponyo to the sea.', 'https://image.tmdb.org/t/p/w780/lOKW7Z6HkY2iVNq5kTvAIlhOWN1.jpg', 'https://image.tmdb.org/t/p/w1280/1QmEcK0w2Ub4Hm094fHbZT8vA7o.jpg', 'https://www.youtube.com/watch?v=h6XP82TyFWw', '宮崎駿', ARRAY['神月柚莉愛', '土井洋輝', '所ジョージ', '山口智子', 'Amami Yuki', '長嶋一茂', '矢野顕子', '羽鳥慎一']::TEXT[], ARRAY['Hoạt Hình', 'Giả Tưởng', 'Gia Đình']::TEXT[], 100, '2008-07-19', NULL, 'US: G', 7.8, 'ended'),
  ('660b0988-6104-54ed-b545-7762107411d0'::UUID, 10515, 'Laputa: Lâu Đài Trên Không', '天空の城ラピュタ', 'Bộ phim hoạt hình phiêu lưu cho trẻ em kể về cậu bé thợ mỏ và cô bé bí ẩn. Hai em khao khát tìm kiếm hòn đảo mất tích đã lâu mà mọi người đồn rằng có rất nhiều của cải.', 'A young boy and a girl with a magic crystal must race against pirates and foreign agents in a search for a legendary floating castle.', 'https://image.tmdb.org/t/p/w780/l15RDgdYu62b3xHDPOodlWdMCnz.jpg', 'https://image.tmdb.org/t/p/w1280/3cyjYtLWCBE1uvWINHFsFnE8LUK.jpg', 'https://www.youtube.com/watch?v=6s_wR3uuWec', '宮崎駿', ARRAY['よこざわけい子', '田中真弓', '寺田農', '初井言榮', '常田富士男', '永井一郎', '糸博', '鷲尾真知子']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Hoạt Hình', 'Hành Động', 'Gia Đình']::TEXT[], 125, '1986-08-02', NULL, 'US: PG', 8, 'ended'),
  ('b5961217-f3ef-5b73-ab0f-4c872ea72484'::UUID, 16859, 'Dịch Vụ Giao Hàng của Phù Thủy Kiki', '魔女の宅急便', 'Bộ phim bắt đầu ngay thời điểm Kiki - một cô bé phù thuỷ thực tập - đủ tuổi để rời gia đình và đến một nơi khác, nơi cô phải sống một mình trong vòng một năm để cô có thể trở thành một phù thủy thực thụ. Kiki khởi hành vào buổi tối cùng với sự cổ vũ của mọi người, sử dụng chiếc chổi của mẹ cô, và mang theo chú mèo Jiji cùng một số thứ cần thiết. Kiki chọn thành phố Koriko, một nơi mà cô có thể nhìn thấy biển, một thành phố có chiếc tháp đồng hồ cổ kính. Nhưng với một cô bé 13 tuổi cùng với chiếc chổi bay khắp thành phố thì khó mà có thể tìm được một chỗ để trú thân. Nhờ một lần vô tình giúp đỡ bà chủ tiệm bánh, Kiki đã bắt đầu công việc chuyển phát bằng chiếc chổi bay của mình.', 'A young witch, on her mandatory year of independent life, finds fitting into a new community difficult while she supports herself by running an air courier service.', 'https://image.tmdb.org/t/p/w780/9FEyx8Ra0PiRB0CoUiuOXEBVgOe.jpg', 'https://image.tmdb.org/t/p/w1280/ooGaNXI2OYszAajCFdIXLr73E1S.jpg', 'https://www.youtube.com/watch?v=nu4OX6RKeLY', '宮崎駿', ARRAY['高山みなみ', '佐久間レイ', '山口勝平', '戸田恵子', '信澤三惠子', '三浦浩一', '加藤治子', '関弘子']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Giả Tưởng']::TEXT[], 103, '1989-07-29', NULL, 'JP: G', 7.8, 'ended'),
  ('8ae2df81-61e0-5e8e-99a6-6e61cbe5924a'::UUID, 378064, 'Dáng Hình Thanh Âm', '映画 聲の形', 'Nishimiya Shouko, một cô bé bị điếc từ nhỏ, đã chuyển trường vào lớp của cậu bé Ishida Shouya. Để thỏa mãn sự tò mò của mình, cậu bé Shouya đã khơi mào trò bắt nạt Shouko vì tật khiếm thính. Trong một lần bắt nạt quá đà, Shouko đã bị chảy máu tai, và sau đó cô bé phải tiếp tục chuyển trường. Shouya, thay cho Shouko, bị cả lớp tẩy chay và bắt nạt. Mãi cho tới khi bước vào cao trung, Shouya, bị hành hạ và ân hận bởi những gì mình đã làm trong quá khứ, quyết định rằng cậu phải gặp lại Shouko một lần nữa. Shouya muốn bù đắp lại những tổn thương mà cậu đã gây ra cho Shouko và thực lòng muốn làm bạn với cô bé.', 'Shouya Ishida starts bullying the new girl in class, Shouko Nishimiya, because she is deaf. But as the teasing continues, the rest of the class starts to turn on Shouya for his lack of compassion. When they leave elementary school, Shouko and Shouya do not speak to each other again... until an older, wiser Shouya, tormented by his past behaviour, decides he must see Shouko once more. He wants to atone for his sins, but is it already too late...?', 'https://image.tmdb.org/t/p/w780/aqri8up06zMaCn0oyYcZporiwj3.jpg', 'https://image.tmdb.org/t/p/w1280/5lAMQMWpXMsirvtLLvW7cJgEPkU.jpg', 'https://www.youtube.com/watch?v=TQK9By9qQiw', '山田尚子', ARRAY['Irino Miyu', '早見沙織', '悠木碧', '小野賢章', '金子有希', '石川由依', '潘めぐみ', '豊永利行']::TEXT[], ARRAY['Hoạt Hình', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 130, '2016-09-17', NULL, 'US: NR', 8.4, 'ended'),
  ('ac11abbf-a3c5-503a-ae68-fd4b7b37ffee'::UUID, 635302, 'Thanh Gươm Diệt Quỷ: Chuyến Tàu Vô Tận', '劇場版「鬼滅の刃」無限列車編', 'Trên đường điều tra sự mất tích của các Kiếm Sĩ thuộc Đội Diệt Quỷ, Tanjiro và các đồng đội cùng Viêm Trụ Rengoku rơi vào Huyết Quỷ Thuật ảo mộng của Quỷ Hạ Huyền Enmu. Cả bọn phải hiệp lực để bảo toàn tính mạng cho 200 hành khách trên chuyến tàu Vô Tận. Nhờ sự hi sinh của Viêm Trụ Rengoku, Quỷ Hạ Huyền đã bị đánh bại và mọi người được sống sót', 'Tanjiro Kamado, joined with Inosuke Hashibira, a boy raised by boars who wears a boar''s head, and Zenitsu Agatsuma, a scared boy who reveals his true power when he sleeps, boards the Infinity Train on a new mission with the Fire Hashira, Kyojuro Rengoku, to defeat a demon who has been tormenting the people and killing the demon slayers who oppose it!', 'https://image.tmdb.org/t/p/w780/2MJz10b6ItzpKm3vb95S3X5Vcna.jpg', 'https://image.tmdb.org/t/p/w1280/qjGrUmKW78MCFG8PTLDBp67S27p.jpg', 'https://www.youtube.com/watch?v=v30H0qj_b9E', '外崎春雄', ARRAY['Hanae Natsuki', '鬼頭明里', '下野紘', '松岡禎丞', 'Hino Satoshi', '櫻井孝宏', '小西克幸', '早見沙織']::TEXT[], ARRAY['Hoạt Hình', 'Hành Động', 'Giả Tưởng']::TEXT[], 117, '2020-10-16', NULL, 'JP: PG12', 8.2, 'ended'),
  ('859e8587-dc19-5714-a763-dbdd0fe31ef7'::UUID, 81, 'Nàng Công Chúa Ở Thung Lũng Gió', '風の谷のナウシカ', 'Khi tài nguyên thiên nhiên của hành tinh bị hủy hoại, công chúa chiến binh Nausicaa tập hợp thần dân của mình chống lại đội quân hung tàn của nữ hoàng độc ác.', 'After a global war, the seaside kingdom known as the Valley of the Wind remains one of the last strongholds on Earth untouched by a poisonous jungle and the powerful insects that guard it. Led by the courageous Princess Nausicaä, the people of the Valley engage in an epic struggle to restore the bond between humanity and Earth.', 'https://image.tmdb.org/t/p/w780/dOprmiS3RX06ruz6qUMdnoDUkuD.jpg', 'https://image.tmdb.org/t/p/w1280/z2jsAbXWGdJvadhovznjGg33VND.jpg', 'https://www.youtube.com/watch?v=zaskbIZtfxQ', '宮崎駿', ARRAY['島本須美', '永井一郎', '納谷悟朗', '松田洋治', '榊原良子', '家弓家正', '京田尚子', '辻村真人']::TEXT[], ARRAY['Phiêu Lưu', 'Hoạt Hình', 'Giả Tưởng']::TEXT[], 95, '1984-03-11', NULL, 'US: PG', 7.9, 'ended'),
  ('dbb77b23-e65e-5752-ac7b-e1a52610ea9f'::UUID, 9323, 'Vỏ Bọc Ma', 'GHOST IN THE SHELL / 攻殻機動隊', 'Vào năm 2029, các rào cản của thế giới chúng ta đã bị phá vỡ bởi mạng và điều khiển học, nhưng điều này lại mang đến lỗ hổng mới cho con người dưới hình thức hack não. Khi một hacker được truy nã gắt gao được gọi là ''The Puppetmaster'' bắt đầu lôi kéo họ vào chính trị, Phần 9, một nhóm cảnh sát được tăng cường điều khiển học, được gọi đến để điều tra và ngăn chặn Puppetmaster.', 'In the year 2029, the barriers of our world have been broken down by the net and by cybernetics, but this brings new vulnerability to humans in the form of brain-hacking. When a highly-wanted hacker known as ''The Puppetmaster'' begins involving them in politics, Section 9, a group of cybernetically enhanced cops, are called in to investigate and stop the Puppetmaster.', 'https://image.tmdb.org/t/p/w780/z9S9V4vtVJqyHxFfI8HFWCobdrH.jpg', 'https://image.tmdb.org/t/p/w1280/jIpagj2Dud9g3ZVJFvaWikEWsYz.jpg', 'https://www.youtube.com/watch?v=R1K__7QhLaA', '押井守', ARRAY['田中敦子', '大塚明夫', '家弓家正', '山寺宏一', '仲野裕', '大木民夫', '玄田哲章', '生木政壽']::TEXT[], ARRAY['Hành Động', 'Hoạt Hình', 'Khoa Học Viễn Tưởng']::TEXT[], 83, '1995-11-18', NULL, 'US: NR', 7.9, 'ended'),
  ('277d96fa-e25c-5867-b6d4-620b09405c66'::UUID, 11621, 'Chú Heo Màu Đỏ', '紅の豚', 'Không tặc hoành hành khắp vùng biển Adriatic và chỉ có tay phi công người Ý này mới đủ can trường để đương đầu với chúng. Có điều, ông ta là phi công nửa người nửa heo.', 'In Italy in the 1930s, sky pirates in biplanes terrorize wealthy cruise ships as they sail the Adriatic Sea. The only pilot brave enough to stop the scourge is the mysterious Porco Rosso, a former World War I flying ace who was somehow turned into a pig during the war. As he prepares to battle the pirate crew''s American ace, Porco Rosso enlists the help of spunky girl mechanic Fio Piccolo and his longtime friend Madame Gina.', 'https://image.tmdb.org/t/p/w780/kIB9M1smkCSQ12he2cMlwe0meft.jpg', 'https://image.tmdb.org/t/p/w1280/ec4m0EvVlEtVl5aySdw6ab9uG0b.jpg', 'https://www.youtube.com/watch?v=3LRyNwYg1f8', '宮崎駿', ARRAY['森山周一郎', '加藤登紀子', '桂文枝 (6代目)', '上條恒彦', '岡村明美', '大塚明夫', '関弘子', '稲垣雅之']::TEXT[], ARRAY['Hoạt Hình', 'Phiêu Lưu', 'Giả Tưởng']::TEXT[], 93, '1992-07-18', NULL, 'US: PG', 7.8, 'ended'),
  ('38d303ae-3bda-5ef3-bacd-fb02bbc25b33'::UUID, 149870, 'Gió Vẫn Thổi', '風立ちぬ', 'Nhà làm phim hoạt hình Miyazaki Hayao dệt lên câu chuyện kéo dài nhiều thập kỉ lấy cảm hứng từ cuộc đời Horikoshi Jirô – cha đẻ của máy bay chiến đấu Zero ở Thế chiến II.', 'A lifelong love of flight inspires Japanese aviation engineer Jiro Horikoshi, whose storied career includes the creation of the A-6M World War II fighter plane.', 'https://image.tmdb.org/t/p/w780/b6DNmz3sZCPv18s2uzvpmFFvMS8.jpg', 'https://image.tmdb.org/t/p/w1280/zZiflZpuaZerugtfdyXcg6dcylD.jpg', 'https://www.youtube.com/watch?v=q3kdZpeVbLM', '宮崎駿', ARRAY['庵野秀明', '西島秀俊', '瀧本美織', '西村雅彥', 'Stephen Alpert', 'Nomura Mansai', '國村隼', 'Shida Mirai']::TEXT[], ARRAY['Hoạt Hình', 'Chính Kịch', 'Lịch Sử', 'Lãng Mạn']::TEXT[], 126, '2013-07-20', NULL, 'JP: G', 7.8, 'ended'),
  ('484ff734-29a5-500f-96d9-3bf885a90ba8'::UUID, 10494, 'Màu Xanh Ảo Giác', 'PERFECT BLUE', 'Một ca sĩ từ bỏ ban nhạc để trở thành diễn viên và rũ bỏ hình tượng "gái ngoan" để vươn xa hơn trong sự nghiệp.', 'Rising pop star Mima Kirigoe quits singing to pursue a career as an actress. After she takes up a role on a popular detective show, her handlers and collaborators begin turning up murdered. Harboring feelings of guilt and haunted by visions of her former self, Mima''s reality and fantasy meld into a frenzied paranoia.', 'https://image.tmdb.org/t/p/w780/rfxmLMjSSD709PbsoRbge3K79DO.jpg', 'https://image.tmdb.org/t/p/w1280/mHG7dpLb0ZScSY3LpP443IHRmjy.jpg', 'https://www.youtube.com/watch?v=RrWausp8zDQ', '今敏', ARRAY['岩男潤子', '松本梨香', '辻親八', '大倉正章', '秋元羊介', '塩屋翼', '堀秀行', '篠原恵美']::TEXT[], ARRAY['Hoạt Hình', 'Giật Gân']::TEXT[], 81, '1998-02-28', NULL, 'JP: R15+', 8.3, 'ended'),
  ('27a0f273-f381-571c-a3bb-e1d93073d1ae'::UUID, 51739, 'Thế Giới Bí Mật Của Arrietty', '借りぐらしのアリエッティ', 'Khi "người vay mượn" nhỏ bé tên Arrietty kết bạn với cậu nhóc to lớn hơn cô gấp nhiều lần, cô cũng phải bảo vệ gia đình mình trước những người khổng lồ cao chót vót.', '14-year-old Arrietty and the rest of the Clock family live in peaceful anonymity as they make their own home from items "borrowed" from the house''s human inhabitants. However, life changes for the Clocks when a human boy discovers Arrietty.', 'https://image.tmdb.org/t/p/w780/dLQKL4jQN8jA11RgLVebZAVHVWF.jpg', 'https://image.tmdb.org/t/p/w1280/7Z7WVzJsSReG8B0CaPk0bvWD7tK.jpg', 'https://www.youtube.com/watch?v=S75QfDA3rDA', '米林宏昌', ARRAY['Shida Mirai', 'Kamiki Ryunosuke', '三浦友和', '竹下景子', '樹木希林', '大竹しのぶ', 'Fujiwara Tatsuya', '羽鳥慎一']::TEXT[], ARRAY['Giả Tưởng', 'Hoạt Hình', 'Gia Đình']::TEXT[], 95, '2010-07-16', NULL, 'JP: G', 7.7, 'ended'),
  ('52418100-085b-5f21-9d67-4548efb855e8'::UUID, 503314, 'Bảy Viên Ngọc Rồng Siêu Cấp: Huyền Thoại Broly', 'ドラゴンボール超 ブロリー', 'Bảy Viên Ngọc Rồng Siêu Cấp: Broly lấy bối cảnh khi đế chế Frieza đàn áp, đặt ách thống trị, bắt người Saiyan phải phải phục vụ làm việc dưới quyền của chúng. Khi đó 3 đứa trẻ Saiyan đã được sinh ra cùng một lúc, nhưng số phận của chúng lại hoàn toàn khác nhau: Vegeta là hoàng tử của tộc người Saiyan, Kakalot (Goku) là con trai của tướng quân Bardock, và Broly là con của Paragus.', 'Earth is peaceful following the Tournament of Power. Realizing that the universes still hold many more strong people yet to see, Goku spends all his days training to reach even greater heights. Then one day, Goku and Vegeta are faced by a Saiyan called ''Broly'' who they''ve never seen before. The Saiyans were supposed to have been almost completely wiped out in the destruction of Planet Vegeta, so what''s this one doing on Earth? This encounter between the three Saiyans who have followed completely different destinies turns into a stupendous battle, with even Frieza (back from Hell) getting caught up in the mix.', 'https://image.tmdb.org/t/p/w780/tviumel4bhjuPki15Jl3hdGoa8K.jpg', 'https://image.tmdb.org/t/p/w1280/6OTRuxpwUUGbmCX3MKP25dOmo59.jpg', 'https://www.youtube.com/watch?v=1GtIJsvIFAQ', '長峯達也', ARRAY['野沢雅子', '久川綾', '堀川りょう', '古川登志夫', '草尾毅', '中尾隆聖', '山寺宏一', '森田成一']::TEXT[], ARRAY['Hành Động', 'Khoa Học Viễn Tưởng', 'Hoạt Hình']::TEXT[], 101, '2018-12-14', NULL, 'JP: G', 8, 'ended'),
  ('30e086a8-e6fb-582f-9519-c800fbffb191'::UUID, 610150, 'Bảy Viên Ngọc Rồng Siêu Cấp: Siêu Anh Hùng', 'ドラゴンボール超 スーパーヒーロー', 'Red Ribbon Army, một tổ chức độc ác từng bị Goku tiêu diệt trong quá khứ, đã được cải tổ bởi một nhóm người đã tạo ra các Android mới và mạnh hơn, Gamma 1 và Gamma 2, đồng thời tìm cách trả thù Goku và gia đình của anh ta.', 'The Red Ribbon Army, an evil organization that was once destroyed by Goku in the past, has been reformed by a group of people who have created new and mightier Androids, Gamma 1 and Gamma 2, and seek vengeance against Goku and his family.', 'https://image.tmdb.org/t/p/w780/1TIl7hssPbhfUXqAL3geaiE4gNT.jpg', 'https://image.tmdb.org/t/p/w1280/uR0FopHrAjDlG5q6PZB07a1JOva.jpg', 'https://www.youtube.com/watch?v=6_fXQSobiHs', '児玉徹郎', ARRAY['野沢雅子', '古川登志夫', '皆口裕子', '神谷浩史', '宮野真守', 'Irino Miyu', '竹内良太', '久川綾']::TEXT[], ARRAY['Hoạt Hình', 'Khoa Học Viễn Tưởng', 'Hành Động']::TEXT[], 100, '2022-06-11', NULL, 'US: PG-13', 7.9, 'ended'),
  ('257bb3f8-c10f-58ff-90e2-31a9c7307447'::UUID, 1153576, 'Chiến Binh Đường Phố', 'Street Fighter', 'Lấy bối cảnh năm 1993, Ryu và Ken, hai đấu sĩ từng xa cách bị kéo trở lại chiến đấu khi Chun-Li chiêu mộ họ tham gia giải Chiến Binh Thế Giới đầy khốc liệt. Nhưng đằng sau đó là một âm mưu chết chóc, buộc họ phải đối đầu với nhau và quá khứ của chính mình, nếu không tất cả sẽ CHẤM HẾT! Dưới sự chỉ đạo của đạo diễn Kitao Sakurai, Street Fighter mang những trận chiến game thùng lên màn ảnh rộng với các đòn thế quen thuộc cùng dàn nhân vật được yêu thích.', 'In 1993, estranged Street Fighters Ryu and Ken Masters are thrown back into combat when the mysterious Chun-Li recruits them for the next World Warrior Tournament: a brutal clash of fists, fate, and fury. But behind this battle royale lies a deadly conspiracy that forces them to face off against each other and the demons of their past. And if they don''t, it''s GAME OVER!', 'https://image.tmdb.org/t/p/w780/lnaGK9y2Dw1cwRz8e7X5plvYVdI.jpg', 'https://image.tmdb.org/t/p/w1280/qRN8eqYwG6HPSy0i3fKzuLrUOhp.jpg', 'https://www.youtube.com/watch?v=U6sbm1OaJb8', 'Kitao Sakurai', ARRAY['Andrew Koji', 'Noah Centineo', 'Callina Liang', 'David Dastmalchian', 'Andrew Schulz', 'Joe Anoa''i', 'Cody Rhodes', 'Jason Momoa']::TEXT[], ARRAY['Hành Động', 'Giả Tưởng']::TEXT[], 120, '2026-10-13', NULL, 'US: PG-13', 6.3, 'ended'),
  ('82fc09ad-4c8c-56f8-9847-fbfdbc116e0f'::UUID, 1311031, 'Thanh Gươm Diệt Quỷ: Vô Hạn Thành', '劇場版「鬼滅の刃」無限城編 第一章 猗窩座再来', 'Khi các thành viên của Sát Quỷ Đoàn và Trụ Cột tham gia vào chương trình đặc huấn để chuẩn bị cho trận chiến sắp với lũ quỷ, Kibutsuji Muzan xuất hiện tại Dinh thự Ubuyashiki. Khi thủ lĩnh của Sát Quỷ Đoàn gặp nguy hiểm, Tanjiro và các Trụ Cột trở về trụ sở Thế nhưng, Muzan bất ngờ kéo toàn bộ Sát Quỷ Đoàn đến hang ổ cuối cùng của lũ quỷ là Vô Hạn Thành, mở màn cho trận đánh cuối cùng của cả hai phe.', 'The Demon Slayer Corps are drawn into the Infinity Castle, where Tanjiro, Nezuko, and the Hashira face terrifying Upper Rank demons in a desperate fight as the final battle against Muzan Kibutsuji begins.', 'https://image.tmdb.org/t/p/w780/nV99ACeAa8fFFso0tQZ3HktEf5X.jpg', 'https://image.tmdb.org/t/p/w1280/1RgPyOhN4DRs225BGTlHJqCudII.jpg', 'https://www.youtube.com/watch?v=EpAlHmuA2YM', '外崎春雄', ARRAY['Hanae Natsuki', '櫻井孝宏', '石田彰', '下野紘', '細谷佳正', '早見沙織', '宮野真守', '上田麗奈']::TEXT[], ARRAY['Hoạt Hình', 'Hành Động', 'Giả Tưởng']::TEXT[], 155, '2025-07-18', NULL, 'JP: PG12', 8.8, 'ended'),
  ('a716b1b7-dbd1-57bf-a80e-6c60f7afa255'::UUID, 1218925, 'Chainsaw Man - The Movie: Chương Reze', '劇場版 チェンソーマン レゼ篇', 'Tiếp nối series anime chuyển thể đình đám, Chainsaw Man lần đầu tiên oanh tạc màn ảnh rộng trong một cuộc phiêu lưu hoành tráng, ngập tràn các phân cảnh hành động. Ở phần trước, ta đã biết Denji từng làm Thợ Săn Quỷ cho yakuza để trả món nợ của cha mẹ nhưng bị họ phản bội và trừ khử. Trong khoảnh khắc hấp hối, chú chó quỷ cưa máy Pochita (người bạn đồng hành trung thành của Denji) đã đưa ra một khế ước, cứu sống cậu và hợp thể cùng cậu. Từ đó, một Quỷ Cưa bất khả chiến bại ra đời. Giờ đây ở Chainsaw Man – The Movie: Chương Reze, trong cuộc chiến tàn khốc giữa quỷ dữ, thợ săn quỷ và những kẻ thù trong bóng tối, một cô gái bí ẩn tên Reze xuất hiện trong thế giới của Denji. Denji buộc phải đối mặt với trận chiến sinh tử khốc liệt nhất của mình, một trận chiến được tiếp sức bởi tình yêu trong một thế giới nơi mọi người phải sinh tồn mà không biết bất kỳ luật lệ nào.', 'In a brutal war between devils, hunters, and secret enemies, a mysterious girl named Reze has stepped into Denji''s world, and he faces his deadliest battle yet, fueled by love in a world where survival knows no rules.', 'https://image.tmdb.org/t/p/w780/kywH6s7qTa64i0drx3pNvpQufWR.jpg', 'https://image.tmdb.org/t/p/w1280/gqTz24ZRsCP6AKjARmEivY7m0cK.jpg', 'https://www.youtube.com/watch?v=GJ1jrCnm-t8', '吉原達矢', ARRAY['戸谷菊之介', '井澤詩織', '楠木ともり', '上田麗奈', '坂田将吾', 'ファイルーズあい', '高橋花林', 'Hanae Natsuki']::TEXT[], ARRAY['Hoạt Hình', 'Hành Động', 'Lãng Mạn', 'Giả Tưởng']::TEXT[], 100, '2025-09-19', NULL, 'JP: PG12', 8.5, 'ended'),
  ('320b7222-c4cd-5d99-8cd0-2f9f280ef70d'::UUID, 940721, 'Godzilla Minus One', 'ゴジラ-1.0', 'Ở Nhật Bản thời hậu chiến, một cựu phi công chiến đấu bị sang chấn cùng người dân chiến đấu với con quái vật khổng lồ có thêm sức mạnh hạt nhân đang tấn công bờ biển của họ.', 'In postwar Japan, Godzilla brings new devastation to an already scorched landscape. With no military intervention or government help in sight, the survivors must join together in the face of despair and fight back against an unrelenting horror.', 'https://image.tmdb.org/t/p/w780/9TxEMYb893YGcTPDSkFdtdqzhcn.jpg', 'https://image.tmdb.org/t/p/w1280/oHBhHoNe59VH6bUMazDtJmWOFSS.jpg', 'https://www.youtube.com/watch?v=MSp68m8OJus', 'Takashi Yamazaki', ARRAY['Kamiki Ryunosuke', 'Hamabe Minami', 'Yamada Yuki', '青木崇高', '吉岡秀隆', 'Ando Sakura', '佐々木蔵之介', '永谷咲笑']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Kinh Dị', 'Hành Động']::TEXT[], 125, '2023-11-03', NULL, 'JP: G', 7.6, 'ended'),
  ('625f5158-3fdd-585e-81ae-67e3829ffaff'::UUID, 346, 'Bảy Võ Sĩ Đạo', '七人の侍', 'Bảy võ sĩ đạo (1954) là kiệt tác điện ảnh kinh điển của cố đạo diễn Kurosawa Akira, lấy bối cảnh nước Nhật thời Chiến Quốc loạn lạc, xoay quanh một ngôi làng nông dân nghèo quyết định thuê bảy võ sĩ tài ba để bảo vệ mùa màng và tính mạng của họ khỏi lũ cướp hung bạo chuyên cướp bóc dân đen. Bằng nghệ thuật kể chuyện bậc thầy với kết cấu chặt chẽ, bộ phim không chỉ khắc họa những trận chiến hoành tráng, khốc liệt dưới mưa đầy tính cách mạng về mặt kỹ thuật quay phim, mà còn là bản hùng ca nhân văn sâu sắc về sự xung đột giai cấp, danh dự của người võ sĩ và tinh thần đoàn kết kiên cường của những con người dưới đáy xã hội...', 'A samurai answers a village''s request for protection after he falls on hard times. The town needs protection from bandits, so the samurai gathers six others to help him teach the people how to defend themselves, and the villagers provide the soldiers with food.', 'https://image.tmdb.org/t/p/w780/3jPTUo0JmxlYnqcyLK9OAWazkiq.jpg', 'https://image.tmdb.org/t/p/w1280/qvZ91FwMq6O47VViAr8vZNQz3WI.jpg', 'https://www.youtube.com/watch?v=RsRN65PlaIM', 'Kurosawa Akira', ARRAY['Mifune Toshiro', 'Shimura Takashi', 'Inaba Yoshio', 'Miyaguchi Seiji', 'Chiaki Minoru', 'Kato Daisuke', 'Kimura Isao', 'Tsushima Keiko']::TEXT[], ARRAY['Hành Động', 'Chính Kịch']::TEXT[], 207, '1954-04-26', NULL, 'US: NR', 8.5, 'ended'),
  ('589c5fd4-f1a9-596f-bf4f-cea29d8339c8'::UUID, 976893, 'Những Ngày Hoàn Hảo', 'PERFECT DAYS', 'Perfect Days là một bộ phim điện ảnh của đạo diễn Wim Wenders, kể về cuộc sống của một người lau dọn nhà vệ sinh ở Tokyo, người có niềm đam mê với âm nhạc và sách. Bộ phim được dựa trên bốn truyện ngắn và có sự tham gia của diễn viên Kōji Yakusho. Bộ phim được công chiếu tại Liên hoan phim Cannes năm 2023 và nhận được nhiều đánh giá tích cực từ giới phê bình.', 'Hirayama is content with his life as a toilet cleaner in Tokyo. Outside of his structured routine, he cherishes music on cassette tapes, books, and taking photos of trees. Through unexpected encounters, he reflects on finding beauty in the world.', 'https://image.tmdb.org/t/p/w780/dENgZn7CD6GkPvmxaBAsk8eZDnI.jpg', 'https://image.tmdb.org/t/p/w1280/7WBIaphEm09Z8WFBo85kWGxYYkk.jpg', 'https://www.youtube.com/watch?v=Iv8YO5BXCAQ', 'Wim Wenders', ARRAY['役所広司', '柄本時生', 'Arisa Nakano', '山田 葵', '麻生祐未', '石川さゆり', '三浦友和', 'Tanaka Min']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 124, '2023-11-10', NULL, 'JP: G', 7.8, 'ended'),
  ('59727937-eec9-54b4-a362-b2e456d0fbce'::UUID, 12493, 'Thiên Đàng và Địa Ngục', '天国と地獄', 'Không chỉ là một cuộc đấu trí phá án đỉnh cao, "Thiên Đàng và Địa Ngục" còn là một tấm gương sắc lạnh phản chiếu sự phân hóa xã hội, nơi ranh giới giữa đỉnh cao giàu sang và vực thẳm nghèo đói được mổ xẻ qua một vụ bắt cóc tống tiền đầy lôi cuốn.', 'A Yokohama shoe executive faces a wrenching choice when kidnappers mistakenly seize his chauffeur’s son but demand the ransom anyway.', 'https://image.tmdb.org/t/p/w780/zMOOlH4Uav6kqE44BSRbA5eS1Jh.jpg', 'https://image.tmdb.org/t/p/w1280/i1NjlccZcuqbgDCS92RHdhEnx59.jpg', 'https://www.youtube.com/watch?v=ELsgPvgDBoY', 'Kurosawa Akira', ARRAY['Mifune Toshiro', 'Nakadai Tatsuya', 'Kagawa Kyōko', 'Mihashi Tatsuya', 'Kimura Isao', 'Ishiyama Kenjiro', 'Kato Takeshi', 'Shimura Takashi']::TEXT[], ARRAY['Chính Kịch', 'Tội Phạm', 'Giật Gân', 'Bí Ẩn']::TEXT[], 142, '1963-03-01', NULL, 'US: NR', 8.4, 'ended'),
  ('dd8bc447-9edb-535d-ac59-217452ecf0da'::UUID, 810693, 'Chú Thuật Hồi Chiến 0', '劇場版 呪術廻戦 0', 'Học sinh trung học nhút nhát Yuta Okkotsu mang lời nguyền từ người bạn thơ ấu Rika, nay đã trở thành một chú linh bám theo cậu không rời; tình cảnh của Yuta thu hút sự chú ý của thầy Satoru Gojo tại Trường Chuyên Chú thuật, người thuyết phục cậu nhập học để học cách đối đầu với lời nguyền.', 'Yuta Okkotsu is a nervous high school student who is suffering from a serious problem—his childhood friend Rika has turned into a curse and won''t leave him alone. Since Rika is no ordinary curse, his plight is noticed by Satoru Gojo, a teacher at Jujutsu High, a school where fledgling exorcists learn how to combat curses. Gojo convinces Yuta to enroll, but can he learn enough in time to confront the curse that haunts him?', 'https://image.tmdb.org/t/p/w780/2ndvx03fmREMxEgaZ1vWt756TOQ.jpg', 'https://image.tmdb.org/t/p/w1280/rcEDPOOOUTLFxLLQJggfLffbofe.jpg', 'https://www.youtube.com/watch?v=2docezZl574', '박성후', ARRAY['緒方恵美', '花澤香菜', 'Nakamura Yuichi', '櫻井孝宏', '小松未可子', 'Uchiyama Koki', '関智一', '岩田光央']::TEXT[], ARRAY['Hoạt Hình', 'Hành Động', 'Giả Tưởng']::TEXT[], 105, '2021-12-24', NULL, 'JP: G', 8.1, 'ended'),
  ('508fc97c-b1ba-52f3-b627-85295ea34466'::UUID, 1408208, 'Exit 8: Ga Tàu Vô Tận', '８番出口', 'Bộ phim xoay quanh một chàng trai trẻ bị mắc kẹt trong một hành lang tàu điện ngầm vô tận và lạnh lẽo. Tại đây, anh chàng bất đắc dĩ phải tham gia vào một trò chơi tìm kiếm “lối ra số 8”. Vòng đầu tiên sẽ bắt đầu từ “lối ra số 0”, luật chơi tưởng chừng rất đơn giản: Đừng bỏ qua bất kỳ điều gì bất thường ở hành lang của mỗi lối ra. Nếu phát hiện điều gì sai, hãy lập tức quay đầu. Nếu không thấy gì thay đổi, cứ đi tiếp. Nhưng chỉ một lần lơ là, người chơi lập tức trở về điểm xuất phát. Giữa mê cung vô tận với những cơn ảo giác ập đến, liệu anh chàng có thể giành chiến thắng và trở về với thực tại?', 'A man trapped in an endless sterile subway passageway sets out to find Exit 8. The rules of his quest are simple: do not overlook anything out of the ordinary. If you discover an anomaly, turn back immediately. If you don’t, carry on. Then leave from Exit 8. But even a single oversight will send him back to the beginning. Will he ever reach his goal and escape this infinite corridor?', 'https://image.tmdb.org/t/p/w780/hq1rqaKBjG6VCMOgYxkI3zXoZhQ.jpg', 'https://image.tmdb.org/t/p/w1280/3cVrg7tzSf5AgEecYWDOSAzXAeX.jpg', 'https://www.youtube.com/watch?v=zzEDWwhtAHc', '川村元気', ARRAY['Ninomiya Kazunari', '河内大和', '浅沼成', '花瀬琴音', '小松菜奈', '大塚ヒロタ', '中島多羅', '曽田怜央']::TEXT[], ARRAY['Bí Ẩn', 'Giật Gân', 'Kinh Dị']::TEXT[], 95, '2025-08-03', NULL, 'JP: G', 7, 'ended'),
  ('935ce0d8-59d0-5b14-97f2-3012eae5a452'::UUID, 4977, 'Kẻ Trộm Giấc Mơ', 'パプリカ', 'Tiến sĩ Atsuko Chiba làm việc như một nhà khoa học vào ban ngày và với mật danh "Paprika", là một thám tử giấc mơ vào ban đêm. Atsuko và các đồng nghiệp của cô đang làm việc trên một thiết bị có tên là DC Mini, nhằm mục đích giúp đỡ những bệnh nhân tâm thần, nhưng khi vào tay kẻ xấu, nó có thể phá hủy tâm trí của mọi người. Khi một mẫu thử nghiệm bị đánh cắp, Atsuko / Paprika bắt đầu hoạt động để phục hồi nó trước khi thiệt hại xảy ra.', 'Dr. Atsuko Chiba is a research psychologist who uses a device called the DC Mini to enter her patients'' dreams, wherein she adopts the alter-ego "Paprika". When the device is stolen, she must stop rogue elements from merging the dream and waking worlds.', 'https://image.tmdb.org/t/p/w780/a7r2jDONMLbwuKjLjjq03Q1n0zr.jpg', 'https://image.tmdb.org/t/p/w1280/3fgcEjBNrhstYgPlG1c8WT7UpIN.jpg', 'https://www.youtube.com/watch?v=a6avI9oPgnw', '今敏', ARRAY['林原めぐみ', '江守徹', '堀勝之祐', '古谷徹', '大塚明夫', '山寺宏一', '田中秀幸', '今敏']::TEXT[], ARRAY['Hoạt Hình', 'Khoa Học Viễn Tưởng', 'Giật Gân']::TEXT[], 90, '2006-10-01', NULL, 'JP: G', 7.8, 'ended'),
  ('557177a1-fa19-51fa-89ba-70708b9330b7'::UUID, 508883, 'Thiếu Niên Và Chim Diệc', '君たちはどう生きるか', 'Đến từ Studio Ghibli và đạo diễn Miyazaki Hayao, bộ phim là câu chuyện về hành trình kỳ diệu của cậu thiếu niên Mahito trong một thế giới hoàn toàn mới lạ. Trải qua nỗi đau mất mẹ cùng mối quan hệ chẳng mấy vui vẻ với gia đình cũng như bạn học, Mahito dần cô lập bản thân... cho đến khi cậu gặp một chú chim diệc biết nói kỳ lạ. Mahito cùng chim diệc bước vào một tòa tháp bí ẩn, nơi một thế giới thần kỳ mở ra, đưa cậu gặp gỡ những người mình yêu thương... trong một nhân dạng hoàn toàn khác.', 'While the Second World War rages, the teenage Mahito, haunted by his mother''s tragic death, is relocated from Tokyo to the serene rural home of his new stepmother Natsuko, a woman who bears a striking resemblance to the boy''s mother.  As he tries to adjust, this strange new world grows even stranger following the appearance of a persistent gray heron, who perplexes and bedevils Mahito, dubbing him the "long-awaited one."', 'https://image.tmdb.org/t/p/w780/zC2AoYyY5JGHAT5Y5IidtqEkyVB.jpg', 'https://image.tmdb.org/t/p/w1280/75nSb1fbWooipwcSU5bUttiOriI.jpg', 'https://www.youtube.com/watch?v=A002-b7IH2M', '宮崎駿', ARRAY['山時聡真', 'Suda Masaki', '柴咲コウ', 'あいみょん', '木村佳乃', '木村拓哉', '竹下景子', '風吹ジュン']::TEXT[], ARRAY['Hoạt Hình', 'Giả Tưởng', 'Chính Kịch']::TEXT[], 124, '2023-07-14', NULL, 'JP: G', 7.4, 'ended'),
  ('1a5bbff2-be95-5dc2-9542-999f3a865ad6'::UUID, 568160, 'Đứa Con Của Thời Tiết', '天気の子', 'Xoay quanh cuộc sống của cậu thiếu niên Morishima Hodaka, ở độ tuổi “trẻ trâu” 16 mùa bánh trưng, sau khi đã quá chán cuộc sống tại vùng đảo xa nên cậu có ý định lên thành phố Tokyo để tìm kiếm thử thách của riêng mình. Thế nhưng, mọi việc dần trở nên không giống như cậu mong tưởng, cuộc sống trở nên túng thiếu giữa thành thị đắt đỏ để rồi cậu co mình lại cùn nỗi cô đơn nhớ nhà. Để có tiền trang trải, Hodaka viết bài cho một tờ tạp chí chuyên tin tức về những hiện tượng lạ thường.  Nhưng đúng lúc mới đi làm thì trời cứ mưa mãi khiến cuộc sống xung quanh trở nên ảm đạm và càng não nề. Và rồi như một định mệnh ông trời sắp đặt, trong một con hẻm của thành phố đông đúc và bận rộn, Hodaka gặp một cô gái trẻ tên Hina Amano, một cô gái có khả năng kỳ lạ có thể làm ánh sáng trên bầu trời bừng sáng thông qua những lời nguyện cầu đặc biệt.', 'The summer of his high school freshman year, Hodaka runs away from his remote island home to Tokyo, and quickly finds himself pushed to his financial and personal limits. The weather is unusually gloomy and rainy every day, as if taking its cue from his life. After many days of solitude, he finally finds work as a freelance writer for a mysterious occult magazine. Then, one day, Hodaka meets Hina on a busy street corner. This bright and strong-willed girl possesses a strange and wonderful ability: the power to stop the rain and clear the sky.', 'https://image.tmdb.org/t/p/w780/3agCPmRZg0G9nS2Go0uzftE9gmr.jpg', 'https://image.tmdb.org/t/p/w1280/ize3ZieqSy0TCWljmVoEiy8fSFS.jpg', 'https://www.youtube.com/watch?v=gVFDCLSSQVM', '新海誠', ARRAY['Daigo Kotaro', 'Mori Nana', '本田翼', '吉柳咲良', '平泉成', '倍賞千恵子', 'Oguri Shun', 'Kaji Yuki']::TEXT[], ARRAY['Hoạt Hình', 'Chính Kịch', 'Giả Tưởng', 'Lãng Mạn']::TEXT[], 112, '2019-07-19', NULL, 'JP: G', 8, 'ended'),
  ('a61ab781-021e-5099-95cd-32dfe96e7e31'::UUID, 110420, 'Những Đứa Con Của Sói Ame và Yuki', 'おおかみこどもの雨と雪', 'Hai chị em Yuki và Ame có một bí mật. Hai cô cậu nhóc là ‘người sói’, chính xác hơn là ‘nửa người nửa sói’. Mẹ chúng – Hana đã gặp và yêu một anh chàng người sói. Cả gia đình họ có một cuộc sống bình dị lặng thầm nơi nơi đô thành, giữ kín những bí mật của mình. Bỗng một ngày, cha họ qua đời. Mẹ Hana quyết định mang Yuki và Ame về một làng quê, sống vui vầy cùng thiên nhiên.', 'After her werewolf lover unexpectedly dies in an accident, a woman must find a way to raise the son and daughter that she had with him. However, their inheritance of their father''s traits prove to be a challenge for her.', 'https://image.tmdb.org/t/p/w780/gP9LE3KXJPfqSad6TZuJFcYua2k.jpg', 'https://image.tmdb.org/t/p/w1280/oMqgJMCaNIqeJtilc71D4nRqdmt.jpg', 'https://www.youtube.com/watch?v=SmhtOXCmTSY', '細田守', ARRAY['Miyazaki Aoi', '大沢たかお', 'Kuroki Haru', '西井幸人', '大野百花', '加部亜門', '平岡拓真', '林原めぐみ']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Chính Kịch', 'Giả Tưởng']::TEXT[], 117, '2012-07-21', NULL, 'JP: G', 8.2, 'ended'),
  ('71dadb71-a27a-50fd-ae95-aabbcebeeff8'::UUID, 15370, 'Loài Mèo Trả Ơn', '猫の恩返し', 'Haru, một nữ sinh buồn chán với thói quen bình thường của mình, đã cứu mạng một con mèo khác thường và đột nhiên thế giới của cô bị biến đổi ngoài những gì cô từng tưởng tượng. Vua Mèo thưởng cho hành động tốt của cô bằng một loạt quà, trong đó có một màn cầu hôn vô cùng sốc với con trai mình! Haru bắt đầu một cuộc hành trình bất ngờ đến Vương quốc Mèo, nơi đôi mắt của cô được mở ra với một thế giới hoàn toàn khác.', 'Young Haru rescues a cat from being run over, but soon learns it''s no ordinary feline; it happens to be the Prince of the Cats.', 'https://image.tmdb.org/t/p/w780/mFwLe3X6CvSxYFuWtijh6frTakM.jpg', 'https://image.tmdb.org/t/p/w1280/uIF0sIkLTc7BHB0WZ6Cl0dDwd5z.jpg', 'https://www.youtube.com/watch?v=yVnlvaxFQ6E', '森田宏幸', ARRAY['池脇千鶴', '袴田吉彦', '前田亜季', '渡辺哲', '斉藤洋介', 'Yamada Takayuki', '佐藤仁美', '佐戸井けん太']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Hoạt Hình', 'Chính Kịch', 'Gia Đình']::TEXT[], 75, '2002-07-19', NULL, 'US: G', 7.1, 'ended'),
  ('98050177-409a-590a-917e-4a315e961536'::UUID, 317442, 'Naruto Shippuden Movie 7: Trận Chiến Cuối Cùng', 'THE LAST -NARUTO THE MOVIE-', 'Hai năm sau khi các sự kiện của cuộc Chiến tranh Thế giới Thứ tư Shinobi, mặt trăng bắt đầu đi xuống về phía Trái đất. Với trăng bây giờ là một ngôi sao băng đó sẽ phá hủy tất cả mọi thứ về tác động, Naruto phải đối phó với mối đe dọa này. Trong khi đó, Toneri Ōtsutsuki, một hậu duệ của Hamura Ōtsutsuki xác định thực hiện về di sản tổ tiên mình, xuất hiện và bắt cóc Hanabi Hyuga sau khi thất bại trong việc bắt lấy Hinata. Naruto, Hinata, Sakura, Sai, và Shikamaru được triển khai để đi giải cứu Hanabi.', 'Two years after the events of the Fourth Great Ninja War, the moon that Hagoromo Otsutsuki created long ago to seal away the Gedo Statue begins to descend towards the world, threatening to become a meteor that would destroy everything on impact. Amidst this crisis, a direct descendant of Kaguya Otsutsuki named Toneri Otsutsuki attempts to kidnap Hinata Hyuga but ends up abducting her younger sister Hanabi. Naruto and his allies now mount a rescue mission before finding themselves embroiled in a final battle to decide the fate of everything.', 'https://image.tmdb.org/t/p/w780/x0CwUdcWWQgOb9tO8cW6jxyo9Zx.jpg', 'https://image.tmdb.org/t/p/w1280/l8ubUlfzlB5R2j9cJ3CN7tj0gmd.jpg', 'https://www.youtube.com/watch?v=SDIvvapG0sE', '小林常夫', ARRAY['竹内順子', '水樹奈々', '福山潤', '中村千絵', '森久保祥太郎', '井上和彦', '石田彰', '手塚秀彰']::TEXT[], ARRAY['Hành Động', 'Lãng Mạn', 'Hoạt Hình']::TEXT[], 114, '2014-12-06', NULL, 'JP: G', 7.5, 'ended'),
  ('692d0e40-2483-58e3-a946-4c8bd8e741a7'::UUID, 37797, 'Lời Thì Thầm Của Trái Tim', '耳をすませば', 'Phát hiện mọi cuốn sách cô mượn từ thư viện đều được mượn bởi cùng một người trước đó, nữ sinh Shizuku tìm cách gặp cậu bạn ấy và theo đuổi giấc mơ của mình.', 'Shizuku lives a simple life, dominated by her love for stories and writing. One day she notices that all the library books she has have been previously checked out by the same person: "Seiji Amasawa."', 'https://image.tmdb.org/t/p/w780/aW5oFWGcWA2cInbrkipCbuYu9Na.jpg', 'https://image.tmdb.org/t/p/w1280/rphor0XQcYO4CQoQ6auaQm3UPap.jpg', 'https://www.youtube.com/watch?v=J4lXUZTPAXg', '近藤喜文', ARRAY['本名陽子', 'Takahashi Issei', '立花隆', '室井滋', '高山みなみ', '飯塚雅弓', '山下容莉枝', 'Kobayashi Keiju']::TEXT[], ARRAY['Hoạt Hình', 'Chính Kịch', 'Gia Đình']::TEXT[], 111, '1995-07-15', NULL, 'JP: G', 7.9, 'ended'),
  ('35ec647c-f882-5b11-8321-473274d021e3'::UUID, 14069, 'Cô gái vượt thời gian', '時をかける少女', 'Khi cô gái Makoto Konno 17 tuổi nhận ra mình có khả năng nhảy vượt thời gian, cô đã dành điều kì diệu này để sửa lại thành tích học tập cũng như những tai nạn ngớ ngẩn cô hay gặp phải. Tuy nhiên cô dần nhận ra việc thay đổi quá khứ không hề đơn giản như vậy, và tương lai của cô và bạn bè mình phụ thuộc vào chính khả năng nguy hiểm này.', 'When 17-year-old Makoto Konno gains the ability to ''leap'' backwards through time, she immediately sets about improving her grades and preventing personal mishaps. However, she soon realises that changing the past isn''t as simple as it seems, and eventually, will have to rely on her new powers to shape the future of herself and her friends.', 'https://image.tmdb.org/t/p/w780/1pItbzMnPgT5SLbiMJ9gw7vkAnk.jpg', 'https://image.tmdb.org/t/p/w1280/6m2qbAqSMJTX4HUwRvVEQI6ioiO.jpg', 'https://www.youtube.com/watch?v=boZINHGDxMw', '細田守', ARRAY['Naka Riisa', '石田卓也', '板倉光隆', '垣内彩未', '谷村美月', '関戸優希', '桂歌若', '安藤みどり']::TEXT[], ARRAY['Giả Tưởng', 'Hoạt Hình', 'Chính Kịch', 'Khoa Học Viễn Tưởng']::TEXT[], 98, '2006-07-15', NULL, 'US: NR', 7.8, 'ended'),
  ('1aa38169-4399-52f6-ad89-54b8f4c6cb65'::UUID, 198375, 'Khu Vườn Ngôn Từ', '言の葉の庭', 'Một buổi sáng mùa mưa, trên đường đến trường, cậu đã cúp tiết lang thang đến một khu vườn để phác thảo mẫu giày và bắt gặp một cô gái quyến rũ tên Yukino Yukari đang ngồi uống bia ngắm mưa rơi. Họ không nói nhau lời nào, nhưng khi trời tạnh mưa, cô gái từ biệt cậu bằng một bài tanka khiến cậu bối rối. Tiếp tục những buổi sáng trời mưa tiếp theo, họ lại gặp nhau và...?', 'Takao, who is training to become a shoemaker, skipped school and is sketching shoes in a Japanese-style garden. He meets a mysterious woman, Yukino, who is older than him. Then, without arranging the times, the two start to see each other again and again, but only on rainy days. They deepen their relationship and open up to each other. But the end of the rainy season soon approaches.', 'https://image.tmdb.org/t/p/w780/vOVQY2otrYGXfFpQ2FT2N2GlAgO.jpg', 'https://image.tmdb.org/t/p/w1280/qMNmdJG0WFNXcI6hfZMQH0geHc5.jpg', 'https://www.youtube.com/watch?v=FMabhvDoolc', '新海誠', ARRAY['Irino Miyu', '花澤香菜', '平野文', '前田剛', '寺崎裕香', '星野貴紀', '井上優', '潘めぐみ']::TEXT[], ARRAY['Hoạt Hình', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 46, '2013-05-31', NULL, 'JP: G', 7.6, 'ended'),
  ('51093556-0b93-5dba-b83c-84469ac8494b'::UUID, 38142, '5 Centimet Trên Giây', '秒速5センチメートル', 'Ba khoảnh khắc trong cuộc sống của Takaki: mối quan hệ của anh với Akari và sự tách biệt cưỡng bức của họ; Tình bạn của anh với Kanae, người thầm yêu anh; Những yêu cầu và sự thất vọng của trưởng thành, một cuộc sống bất hạnh ở một thành phố lạnh lẽo.', 'Three moments in Takaki''s life: his relationship with Akari and their forced separation; his friendship with Kanae, who is secretly in love with him; the demands and disappointments of adulthood, an unhappy life in a cold city.', 'https://image.tmdb.org/t/p/w780/7NhKe7yaadEmS0w6LVQdBdTgeux.jpg', 'https://image.tmdb.org/t/p/w1280/kTdmdPxl1gVPObxsffaOex6n3Vt.jpg', 'https://www.youtube.com/watch?v=iPsu_sk-e7Q', '新海誠', ARRAY['水橋研二', '近藤好美', '花村怜美', '水野理紗', '尾上綾華', '寺崎裕香', '中村優子', '岩崎征実']::TEXT[], ARRAY['Hoạt Hình', 'Lãng Mạn', 'Chính Kịch']::TEXT[], 63, '2007-03-03', NULL, 'JP: G', 7.3, 'ended'),
  ('b7bea7c3-4591-5004-a89d-9f389dececa8'::UUID, 303857, 'Dragon Ball Z: Frieza Hồi Sinh', 'ドラゴンボールZ 復活の「F」', 'Sự xuất hiện của Frieza là một nỗi lo lớn cho toàn bộ hành tinh. Khi chính hành tinh của người Saiyan đã bị chính hắn làm cho nổ tung và biến mất, nhưng may mắn người Saiyan đã đưa được đứa trẻ xuống hành tinh khác có tên gọi là Son Goku, sau khi lớn lên một lần nữa Goku phải đối mặt với kẻ đã hũy diệt hành tinh của mình, bằng sức mạnh, ý chí cùng tấm lòng trong sáng của mình Goku đã đánh bại tên Frieza tàn ác.  Vào một ngày đẹp trời nọ, hai tên tàn dư của quân đội Freeza là Sorbet và Tagoma đã tìm kiếm những viên ngọc rồng với mục đích hồi sinh Freeza. Họ đã thành công. Freeza sau khi hồi sinh đã tìm cách trả thù những người Saiyans. Frieza trở lại cùng với một đạo quân hùng hậu ( 1000 tên ). Không những thế, nhân vật phản diện được xem là ác nhất DBZ này còn có thêm sức mạnh mới với một hình hài sáng chói lấp lánh ánh vàng báo hiệu một cuộc chiến không hề dễ dàng cho những Goku, Vegeta, Gohan….lần này.', 'One peaceful day on Earth, two remnants of Frieza''s army named Sorbet and Tagoma arrive searching for the Dragon Balls with the aim of reviving Frieza. They succeed, and Frieza subsequently seeks revenge on the Saiyans.', 'https://image.tmdb.org/t/p/w780/ySHbvH5BjIqqEPbPF7CfyTnQV5c.jpg', 'https://image.tmdb.org/t/p/w1280/usrUizny0dLNJTrrJSxsvu5V0z0.jpg', 'https://www.youtube.com/watch?v=uRlSMA1XKYA', '山室直儀', ARRAY['野沢雅子', '堀川りょう', '中尾隆聖', '山寺宏一', '森田成一', '鶴ひろみ', '田中真弓', '佐藤正治']::TEXT[], ARRAY['Hành Động', 'Hoạt Hình', 'Khoa Học Viễn Tưởng']::TEXT[], 93, '2015-04-18', NULL, 'US: NR', 6.9, 'ended'),
  ('739123d3-feb5-5d98-b1d6-f678aa454572'::UUID, 125521, 'スレイヤーズ RETURN', 'スレイヤーズ RETURN', 'Lina Inverse and Naga the White Serpent are back! What begins as a routine bandit-stomping turns into the adventure of a lifetime involving magical golems, an ancient Elven weapon and even someone bent on destroying the world. It''s a predicament only Lina and Naga could get themselves in to.', 'Lina Inverse and Naga the White Serpent are back! What begins as a routine bandit-stomping turns into the adventure of a lifetime involving magical golems, an ancient Elven weapon and even someone bent on destroying the world. It''s a predicament only Lina and Naga could get themselves in to.', 'https://image.tmdb.org/t/p/w780/gPdqgPra6orgEvkFwdkGMKiIwzk.jpg', 'https://image.tmdb.org/t/p/w1280/1SeydkGlChbUrYJeV95TNSLQsFt.jpg', 'https://www.youtube.com/watch?v=2Wt_thxCX2w', 'わたなべひろし', ARRAY['林原めぐみ', '川村万梨阿', '平松晶子', '大塚明夫', '茶風林', '稲葉実', '岡本麻弥', '内海賢二']::TEXT[], ARRAY['Hoạt Hình', 'Hài', 'Giả Tưởng']::TEXT[], 60, '1996-08-03', NULL, 'JP: PG', 6.5, 'ended'),
  ('0d94dd9f-6b30-553e-b5f9-ace8d13cbcba'::UUID, 149871, 'Chuyện Nàng Công Chúa Kaguya', 'かぐや姫の物語', 'Câu chuyện bắt đầu khi một ông lão đốn tre (do Takeo Chii lồng tiếng) tìm thấy một cô bé tí hon lấp lánh bên trong một thân cây tre phát sáng. Tin rằng đây là một món quà từ trời, ông và vợ (do Nobuko Miyamoto lồng tiếng) quyết định nuôi dưỡng cô bé, đặt tên là Kaguya. Kaguya lớn lên nhanh chóng một cách phi thường, trở thành một thiếu nữ xinh đẹp tuyệt trần với vẻ duyên dáng tự nhiên.', 'Found inside a shining stalk of bamboo by an old bamboo cutter and his wife, a tiny girl grows rapidly into an exquisite young lady. The mysterious young princess enthrals all who encounter her. But, ultimately, she must confront her fate.', 'https://image.tmdb.org/t/p/w780/5EM4TE9wlLfvA9yQaQZdKR5RwrR.jpg', 'https://image.tmdb.org/t/p/w1280/lMaWlYThCSnsmW3usxWTpSuyZp1.jpg', 'https://www.youtube.com/watch?v=iPm7HfO3mis', 'Takahata Isao', ARRAY['朝倉あき', '地井武男', '宮本信子', 'Kora Kengo', 'Takahata Atsuko', '田畑智子', '立川志の輔', '上川隆也']::TEXT[], ARRAY['Hoạt Hình', 'Chính Kịch', 'Giả Tưởng']::TEXT[], 137, '2013-11-23', NULL, 'JP: G', 8.1, 'ended'),
  ('5d57feb8-4b07-513b-8ab7-f2ca923274bc'::UUID, 242828, 'Marnie Yêu Dấu', '思い出のマーニー', 'Phải nghỉ hè tại thị trấn ven biển buồn tẻ, cô bé ốm yếu Anna kết bạn với bé gái tò mò sống trong căn biệt thự hiu quạnh. Nhưng tình bạn ấy có phải là thật?', 'Upon being sent to live with relatives in the countryside due to an illness, an emotionally distant adolescent girl becomes obsessed with an abandoned mansion and infatuated with a girl who lives there - a girl who may or may not be real.', 'https://image.tmdb.org/t/p/w780/vM6ZHg10Y180JsQc8wpgCkrDxtQ.jpg', 'https://image.tmdb.org/t/p/w1280/rVDOeOccg0K9tXuw6b9uOG6q4mf.jpg', 'https://www.youtube.com/watch?v=YBIfz76BYiY', '米林宏昌', ARRAY['高月彩良', 'Arimura Kasumi', 'Matsushima Nanako', '寺島進', '根岸季衣', '森山良子', '吉行和子', '黒木瞳']::TEXT[], ARRAY['Hoạt Hình', 'Chính Kịch', 'Gia Đình']::TEXT[], 103, '2014-07-19', NULL, 'JP: G', 7.9, 'ended'),
  ('13baf1f3-2d4d-55bd-80f8-380d0d52994d'::UUID, 83389, 'Ngọn Đồi Hoa Hồng Anh', 'コクリコ坂から', 'Bộ phim lấy bối cảnh Nhật Bản những năm 1960, nói về một cô gái tên Matsuzaki Umi sống cùng với gia đình trên đỉnh một ngọn đồi ở sát biển, cây Ngu Mỹ Nhân mọc rất nhiều trên ngọn đồi này và hằng ngày cô thường kéo cờ hiệu trong sân nhà vốn là đỉnh của ngọn đồi đó, cha của cô đã mất tích trong chiến tranh và những lá cờ hiệu cô kéo lên hằng ngày là dấu hiệu để nếu cha cô trở về từ biển có thể nhận ra nhà của mình. Cô đã gặp một nam sinh cùng học trong ngôi trường trung học với mình người muốn giữ và sửa chữa lại ngôi trường cũ thay vì phá bỏ và xây ngôi trường mới. Cô cũng có tình cảm với anh ta nhưng sau đó họ đã phát hiện ra 2 người có chung huyết thống..', 'Yokohama, 1963. Japan is picking itself up from the devastation of World War II and preparing to host the 1964 Olympics—and the mood is one of both optimism and conflict as the young generation struggles to throw off the shackles of a troubled past. Against this backdrop of hope and change, a friendship begins to blossom between high school students Umi and Shun—but a buried secret from their past emerges to cast a shadow on the future and pull them apart.', 'https://image.tmdb.org/t/p/w780/4tw1Q0Hpvvac55jwz213DCI4LUQ.jpg', 'https://image.tmdb.org/t/p/w1280/mazqYfDUreT2KE6ZsaWT59JARHZ.jpg', 'https://www.youtube.com/watch?v=a0DIxdy8CZA', '宮崎吾朗', ARRAY['Nagasawa Masami', 'Okada Junichi', '竹下景子', '石田ゆり子', '柊瑠美', '風吹ジュン', '内藤剛志', '風間俊介']::TEXT[], ARRAY['Hoạt Hình', 'Chính Kịch']::TEXT[], 91, '2011-07-16', NULL, 'JP: G', 7.5, 'ended'),
  ('76dcad55-f6db-58d0-9bcc-b428d7ad5f53'::UUID, 18491, '新世紀エヴァンゲリオン劇場版 Air／まごころを、君に', '新世紀エヴァンゲリオン劇場版 Air／まごころを、君に', 'SEELE orders an all-out attack on NERV, aiming to destroy the Evas before Gendo can advance his own plans for the Human Instrumentality Project. Shinji is pushed to the limits of his sanity as he is forced to decide the fate of humanity.', 'SEELE orders an all-out attack on NERV, aiming to destroy the Evas before Gendo can advance his own plans for the Human Instrumentality Project. Shinji is pushed to the limits of his sanity as he is forced to decide the fate of humanity.', 'https://image.tmdb.org/t/p/w780/yBanOpNIccxjZlH4QH7ag4ojWOI.jpg', 'https://image.tmdb.org/t/p/w1280/AfyuI3glMCBDFmNPj9PY6DwbgGp.jpg', 'https://www.youtube.com/watch?v=J8t48KMGCo4', '鶴巻和哉', ARRAY['緒方恵美', '林原めぐみ', '三石琴乃', '宮村優子', '立木文彦', '長沢美樹', '子安武人', '優希比呂']::TEXT[], ARRAY['Hoạt Hình', 'Khoa Học Viễn Tưởng', 'Chính Kịch', 'Giả Tưởng', 'Hành Động']::TEXT[], 87, '1997-07-19', NULL, 'US: NR', 8.3, 'ended'),
  ('3b14f911-1ca6-52e2-a291-63196a78849d'::UUID, 369885, 'Liên Minh Sát Thủ', 'Allied', 'Khi sĩ quan tình báo Max Vatan nghe tin có thể vợ mình tiếp tay cho kẻ thù, anh chỉ có 72 giờ để chứng minh cô vô tội và cứu gia đình mình trước khi anh bị buộc phải làm một việc khủng khiếp.', 'In 1942, an intelligence officer in North Africa encounters a female French Resistance fighter on a deadly mission behind enemy lines. When they reunite in London, their relationship is tested by the pressures of war.', 'https://image.tmdb.org/t/p/w780/fPZZbzbmmXLUkSFhqWunSaqezYZ.jpg', 'https://image.tmdb.org/t/p/w1280/cdR0qwyaMfuZRfTYEixUmRnmdop.jpg', 'https://www.youtube.com/watch?v=-hQGiozwHiI', 'Robert Zemeckis', ARRAY['Brad Pitt', 'Marion Cotillard', 'Jared Harris', 'Simon McBurney', 'Lizzy Caplan', 'Daniel Betts', 'Matthew Goode', 'Camille Cottin']::TEXT[], ARRAY['Hành Động', 'Chính Kịch', 'Chiến Tranh', 'Lãng Mạn', 'Giật Gân']::TEXT[], 125, '2016-11-23', NULL, 'US: R', 6.8, 'ended'),
  ('bccfea53-a006-5673-b570-b44ddc1ba8a3'::UUID, 14756, 'Diệp Vấn', '葉問', 'Vào năm 1937, chiến tranh bùng nổ, và quân Nhật nhanh chóng chiếm đóng Phật Sơn. Diệp gia bị niêm phong, Diệp Vấn cũng vợ con phải chuyển đến một căn nhà lụp xụp; anh phải đi xúc than để kiếm miếng ăn cho gia đình. Tên tướng Nhật là Miura bị ám ảnh bởi võ thuật, và dùng lương thực để thưởng cho những trận đấu võ giữa người dân và quân lính của hắn. Vài người bạn của Diệp Vấn không kiềm chế được và xin tham gia. Lam võ khùng vốn có lòng tự tôn dân tộc rất cao, không hề sợ hãi lao lên thách thức Miura nhưng đã phải trả giá bằng tính mạng của mình. Ngày hôm sau, chứng kiến thêm cái chết của Lưu sư phụ, Diệp Vấn nổi cơn thịnh nộ và hạ gục 10 tên lính nhật trong một lượt đấu.', 'A semi-biographical account of Yip Man, the first martial arts master to teach the Chinese martial art of Wing Chun. The film focuses on events surrounding Ip that took place in the city of Foshan between the 1930s to 1940s during the Second Sino-Japanese War. Directed by Wilson Yip, the film stars Donnie Yen in the lead role, and features fight choreography by Sammo Hung.', 'https://image.tmdb.org/t/p/w780/AfxBQohIVHJ2V63DM5BIf8X6Jj7.jpg', 'https://image.tmdb.org/t/p/w1280/69QJSMkm5Hh0x9fLElZ8hjv5N4P.jpg', 'https://www.youtube.com/watch?v=3IUR6P5VwGo', '葉偉信', ARRAY['Chân Tử Đan', 'Nhậm Đạt Hoa', 'Hùng Đại Lâm', 'Ikeuchi Hiroyuki', 'Lâm Gia Đống', 'Phàn Thiếu Hoàng', 'Thích Ngạn Năng', '黃又南']::TEXT[], ARRAY['Chính Kịch', 'Hành Động', 'Lịch Sử']::TEXT[], 106, '2008-12-12', NULL, 'US: R', 7.8, 'ended'),
  ('af410b7a-6a3c-5eb1-b22e-0a52dbebc158'::UUID, 146, 'Ngọa Hổ Tàng Long', '卧虎藏龍', 'Câu chuyện bắt đầu từ thanh bảo kiếm Lục Mệnh đã có hơn 400 năm tung hoành giang hồ, mà chủ nhân gần đây của nó là Lý Mộ Bạch (Châu Nhuận Phát) – một cao thủ phái Võ Đang có thể xem là thiên hạ vô địch hiện nay. Dự định rút lui giang hồ, Lý Mộ Bạch đã trao tặng Lục Mệnh kiếm cho Tề lão gia ở kinh thành, tuy nhiên thanh kiếm đã bị một kẻ võ công cao siêu đánh cắp. Có mặt ở hiện trường lúc đó, và đã từng giao đấu với kẻ trộm là nữ hiệp Du Tú Liên (Dương Tử Quỳnh) – chủ nhân của Thái Dương Tiêu Cục. Tên trộm nhờ đồng bọn trợ giúp, Du Tú Liên đã không thể bắt được hắn. Đối tượng mà Du Tú Liên nghi ngờ nhất là tiểu thư của tuần phủ đại nhân – Ngọc Kiều Long.', 'Two warriors in pursuit of a stolen sword and a notorious fugitive are led to an impetuous, physically-skilled, teenage nobleman''s daughter, who is at a crossroads in her life.', 'https://image.tmdb.org/t/p/w780/mX7OWBMp7qYUa0m9HbqpXuIshCq.jpg', 'https://image.tmdb.org/t/p/w1280/nSm9cij9VRrGDoZoS16CPnX0FqK.jpg', 'https://www.youtube.com/watch?v=q-HrIQLdaNE', '李安', ARRAY['Châu Nhuận Phát', 'Dương Tử Quỳnh', 'Chương Tử Di', 'Trương Chấn', '郎雄', 'Trình Phối Phối', '李法曾', '高西安']::TEXT[], ARRAY['Lãng Mạn', 'Chính Kịch', 'Hành Động']::TEXT[], 120, '2000-07-06', NULL, 'HK: IIA', 7.4, 'ended'),
  ('e125dbaf-1f49-5430-9b2d-fd2b130bc51c'::UUID, 458576, 'Thợ Săn Quái Vật', 'Monster Hunter', 'Monster Hunter được chuyển thể từ series game nổi tiếng cùng tên của Capcom. Trong phim, đội trưởng Artemis của nữ diễn viên Milla Jovovich (Resident Evil) và đồng đội đã vô tình bước qua một cánh cửa bí ẩn dẫn tới thế giới khác. Tại đây, họ phải chiến đấu với nhiều loài quái vật khổng lồ trong hành trình trở về thế giới. Đồng hành với họ trong trận chiến là nhân vật “Thợ săn” của nam diễn viên Tony Jaa (Ong Bak). Monster Hunter hứa hẹn sẽ là bom tấn hành động với những màn săn quái vật khổng lồ hoành tráng nhất năm 2020.', NULL, 'https://image.tmdb.org/t/p/w780/1TUwqrNAUOJVCch3OlTIjXRfYl2.jpg', 'https://image.tmdb.org/t/p/w1280/8tNX8s3j1O0eqilOQkuroRLyOZA.jpg', 'https://www.youtube.com/watch?v=puQyZsaTtqY', 'Paul W. S. Anderson', ARRAY['Milla Jovovich', 'Tony Jaa', 'Ron Perlman', 'T.I.', 'Diego Boneta', 'Meagan Good', 'Josh Helman', '歐陽靖']::TEXT[], ARRAY['Hành Động', 'Giả Tưởng']::TEXT[], 103, '2020-12-03', NULL, 'US: PG-13', 6.5, 'ended'),
  ('d20e46ff-dde3-5891-b663-28bda9672677'::UUID, 843, 'Tâm Trạng Khi Yêu', '花樣年華', 'Dù ở nơi đất khách quê người nhưng Châu Mộ Vân vẫn không thể nào quên được mối tình giữa anh và Tô Lệ Trân, nếu năm xưa cô quyết định theo anh ra đi thì giờ đây họ sẽ là một đôi tình nhân hạnh phúc hay vẫn phải chia cách? Có lẽ sẽ có người nói rằng từ ngày đầu tiên khi hai người họ cùng trong một ngày cùng dọn vào một căn nhà trọ và trở thành hàng xóm của nhau thì vận mệnh đã dần đưa hai người họ xích lại gần nhau hơn, và rồi ngẫu nhiên phát sinh những mối quan hệ không thể cho ai biết được.', 'In 1960s Hong Kong, two neighbors form an intimate bond after making a discovery about their spouses in this visually stunning tale of unrequited love.', 'https://image.tmdb.org/t/p/w780/bGaKExFOJb64BHIQON2pgURpfyP.jpg', 'https://image.tmdb.org/t/p/w1280/ffQFnAUm2Uu4RU0nijpjPRf9TBT.jpg', 'https://www.youtube.com/watch?v=rc3QleuaQMw', 'Vương Gia Vệ', ARRAY['Trương Mạn Ngọc', 'Lương Triều Vỹ', '萧炳林', '潘迪华', '雷震', '張同祖', '陳萬雷', '顧錦華']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn']::TEXT[], 99, '2000-09-29', NULL, 'US: PG', 8.1, 'ended'),
  ('d8dd9c3b-3221-5114-a74a-d8685c1e12d6'::UUID, 9470, 'Tuyệt Đỉnh Kung Fu', '功夫', 'Trong xã hội hỗn loạn tại Thượng Hải những năm 1940, đây là giai đoạn nơi các băng đảng giang hồ hoành hành. Trong phim, đáng sợ nhất phải kể đến Đảng Lưỡi Búa mà kẻ đứng đầu là Sâm. Đảng của Sâm đi đến đâu, nỗi kinh hoàng theo tới đó. Người dân thành phố thì lo lắng, đám cảnh sát thì sợ sệt. Chỉ duy có khu ổ chuột Chuồng Heo là không bị đám côn đồ nhũng nhiễu vì người dân nơi đây quá nghèo. Một ngày nọ, đột nhiên có hai tên lang thang giả dạng lưu manh Tinh và Bài Cốt xuất hiện và định moi tiền của một anh thợ hớt tóc. Xung đột xảy ra và bọn chúng được một phen hú vía khi toàn bộ dân khu này ai cũng có võ công cao cường. Đảng Lưỡi Búa lại kéo tới chi viện. Chúng bị các cao thủ đánh cho một trận tơi bời hoa lá. Mâu thuẫn trở nên sâu sắc, Sâm phái A Tinh đi mời đại cao thủ Hoả Vân Tà Thần bất bại về làm gỏi khu Chuồng Heo…', 'It''s the 1940s, and the notorious Axe Gang terrorizes Shanghai. Small-time criminals Sing and Bone hope to join, but they only manage to make lots of very dangerous enemies. Fortunately for them, kung fu masters and hidden strength can be found in unlikely places. Now they just have to take on the entire Axe Gang.', 'https://image.tmdb.org/t/p/w780/ovf1rxwez1ORpHxZ0fNmF5fLi2C.jpg', 'https://image.tmdb.org/t/p/w1280/9XhZhoSnFJ3AjpfzdIiZVHLQIS4.jpg', 'https://www.youtube.com/watch?v=-m3IB7N_PRk', 'Châu Tinh Trì', ARRAY['Châu Tinh Trì', 'Nguyên Thu', 'Nguyên Hoa', '林子聰', 'Lương Tiểu Long', 'Huỳnh Thánh Y', 'Trần Quốc Khôn', 'Triệu Chí Lăng']::TEXT[], ARRAY['Hành Động', 'Hài', 'Tội Phạm', 'Giả Tưởng']::TEXT[], 99, '2004-02-10', NULL, 'US: R', 7.5, 'ended'),
  ('ab338a05-b9ef-5a28-886b-9602f702b3c3'::UUID, 375588, 'Robin Hood: Siêu Trộm Lừng Danh', 'Robin Hood', 'Lãnh chúa Robin xứ Loxley (Taron Egerton), chàng chiến binh mạnh mẽ cùng chỉ huy người Moor khởi đầu cuộc nổi dậy táo bạo chống lại Vương triều Anh đã thối nát lấy danh Thập tự chinh bóc lột dân chúng. Một cuộc phiêu lưu hành động ly kỳ mở ra những chiến trường khốc liệt, những trận chiến đấu hùng tráng và một mối tình vượt thời gian. Do Robin Hood là hình ảnh có thể tự do khai thác nên bất cứ hãng phim nào cũng có thể đưa nhân vật thảo khấu rừng xanh này lên màn ảnh. Năm nay, Lionsgate là cái tên tiếp theo thử sức với nhiệm vụ đó khi chọn Taron Egerton - ngôi sao của loạt phim điệp viên Kingsman - cho vai chính Robin Hood ...', 'A war-hardened Crusader and his Moorish commander mount an audacious revolt against the corrupt English crown.', 'https://image.tmdb.org/t/p/w780/7kr16tE3rKrNrOTngcevPbQjdsU.jpg', 'https://image.tmdb.org/t/p/w1280/9KKT8qPAII0VJMpviThOTMLN0Wt.jpg', 'https://www.youtube.com/watch?v=ne7eStct3Fc', 'Otto Bathurst', ARRAY['Taron Egerton', 'Jamie Foxx', 'Ben Mendelsohn', 'Eve Hewson', 'Jamie Dornan', 'Tim Minchin', 'Paul Anderson', 'F. Murray Abraham']::TEXT[], ARRAY['Phiêu Lưu', 'Hành Động', 'Giật Gân', 'Giả Tưởng']::TEXT[], 116, '2018-11-03', NULL, 'US: PG-13', 5.9, 'ended'),
  ('656bb8fb-8a2a-5a84-bb54-f8b7d6092b2d'::UUID, 379149, 'Kẻ Ngoại Tộc', 'The Foreigner', 'Trong phim Kẻ Ngoại Tộc, Quan – người đàn ông châu Á hiền lành, là chủ một tiệm cơm ở khu phố Tàu (London). Buổi sáng nọ như bao ngày, anh đưa đón cô con gái cưng đi học mà không ngờ rằng mình sắp mất cô bé vĩnh viễn vì một vụ đánh bom của quân khủng bố Ai-len. Tất cả những gì anh hy vọng sau đó là những kẻ thủ ác sẽ bị đưa ra ánh sáng, nhưng không, chính phủ từ chối công khai danh tính của chúng. Uất ức, tuyệt vọng, anh quyết định tự mình trả thù nhóm khủng bố trên. Đúng thời điểm đó, một nhân vật quan trọng là Liam Hennessy  xuất hiện và tiết lộ âm mưu phức tạp đằng sau vụ việc.', 'Quan is a humble London businessman whose long-buried past erupts in a revenge-fueled vendetta when the only person left for him to love – his teenage daughter – dies in an Irish Republican Army car bombing. His relentless search to find the terrorists leads to a cat-and-mouse conflict with a British government official whose own past may hold the clues to the identities of the elusive killers.', 'https://image.tmdb.org/t/p/w780/xlFPT0ZXo8xQ8wLpnFDsFF0pLLH.jpg', 'https://image.tmdb.org/t/p/w1280/sDiGcjWhSu42dCw0jQmBInAkDZ9.jpg', 'https://www.youtube.com/watch?v=r_rSAbYyIq0', 'Martin Campbell', ARRAY['Pierce Brosnan', 'Thành Long', 'Rory Fleck-Byrne', 'Ray Fearon', 'Charlie Murphy', 'Orla Brady', 'Michael McElhatton', 'Lia Williams']::TEXT[], ARRAY['Hành Động', 'Giật Gân', 'Tội Phạm']::TEXT[], 114, '2017-09-28', 'T18', 'US: R', 7, 'ended'),
  ('fb55926a-2de8-5041-b965-55a3275f43e6'::UUID, 8584, 'Trưa Thượng Hải', 'Shanghai Noon', 'Công chúa Pei Pei bị bắt cóc khỏi Tử Cấm Thành đưa đến nước Mỹ xa xôi. Chon Wang tuy không được chọn vẫn xung phong gia nhập đội quân đi giải cứu vì chàng đã trót thương thầm nàng công chúa. Trải qua bao sóng gió và những giây phút nguy hiểm đến tính mạng, anh đã bảo vệ công chúa an toàn, nhưng nàng không muốn trở về với cương vị công chúa cao quý...', 'Chon Wang, a clumsy imperial guard, trails Princess Pei Pei when she''s kidnapped from the Forbidden City and transported to America. Wang follows her captors to Nevada, where he teams up with an unlikely partner, outcast outlaw Roy O''Bannon, and tries to spring the princess from her imprisonment.', 'https://image.tmdb.org/t/p/w780/b0WwWRcDiDahkah5vZ0KjB4N9ZZ.jpg', 'https://image.tmdb.org/t/p/w1280/xuwPmDMHslcx71T7zHc9YqF2Ny3.jpg', 'https://www.youtube.com/watch?v=FqHg5fc_0_U', 'Tom Dey', ARRAY['Thành Long', 'Owen Wilson', 'Lucy Liu', 'Xander Berkeley', 'Roger Yuan', 'Vu Vinh Quang', 'Walton Goggins', 'Brandon Merrill']::TEXT[], ARRAY['Phiêu Lưu', 'Hài', 'Miền Tây']::TEXT[], 110, '2000-05-26', NULL, 'US: PG-13', 6.4, 'ended'),
  ('1c0d2990-b18e-5c1f-a503-2bdc5a2a410a'::UUID, 11770, 'Đội Bóng Thiếu Lâm', '少林足球', 'Vì bán rẻ tài năng mà Thiết Cước, cầu thủ danh tiếng một thời, trở thành lão huấn luyện viên nát rượu. Ông gặp Tinh, chàng võ sư muốn truyền bá kungfu ra toàn thế giới. Cả hai bắt tay lập đội bóng và kêu gọi các huynh đệ Thiếu lâm xưa gia nhập. Đội bóng kỳ lạ bắt đầu gia nhập làng túc cầu.', 'A young Shaolin follower reunites with his discouraged brothers to form a soccer team using their martial art skills to their advantage.', 'https://image.tmdb.org/t/p/w780/1aOnEAg3FSIg8DncA9JvMBuARTZ.jpg', 'https://image.tmdb.org/t/p/w1280/lMRX4cLx4hxYth3iQ96c0E1RHGB.jpg', 'https://www.youtube.com/watch?v=KEWUDWYDdYs', 'Châu Tinh Trì', ARRAY['Châu Tinh Trì', 'Ngô Mạnh Đạt', 'Triệu Vy', 'Tạ Hiền', 'Mạc Văn Uý', 'Huỳnh Nhất Phi', '莫美林', '田啟文']::TEXT[], ARRAY['Hành Động', 'Hài', 'Giả Tưởng']::TEXT[], 113, '2001-07-05', NULL, 'US: PG', 7.2, 'ended'),
  ('97b21d0d-83a5-5f73-a2ef-42aa4105aa2e'::UUID, 79, 'Anh Hùng', '英雄', 'Phim Anh Hùng lấy bối cảnh trong thời Trung Quốc cổ đại, trước khi triều đại của hoàng đế đầu tiên, chiến tranh phe phái suốt Sáu Quốc âm mưu ám sát nhà lãnh đạo mạnh mẽ nhất, Tần. Khi một quan chức nhỏ đánh bại ba kẻ thù chính Qin, anh được triệu tập vào cung điện để nói với Tần câu chuyện của chiến thắng đáng ngạc nhiên của mình.', 'During China''s Warring States period, a district prefect arrives at the palace of Qin Shi Huang, claiming to have killed the three assassins who had made an attempt on the king''s life three years ago.', 'https://image.tmdb.org/t/p/w780/1CxIB5G9ChPnCJ1r04SebpTyR5B.jpg', 'https://image.tmdb.org/t/p/w1280/jDz6RYN3nKYtlo7J9IMvGoJit7B.jpg', 'https://www.youtube.com/watch?v=MgsddFEe9Oc', 'Trương Nghệ Mưu', ARRAY['Lý Liên Kiệt', 'Lương Triều Vỹ', 'Trương Mạn Ngọc', 'Chân Tử Đan', 'Chương Tử Di', 'Trần Đạo Minh', '刘仲元', '郑天庸']::TEXT[], ARRAY['Chính Kịch', 'Phiêu Lưu', 'Hành Động', 'Lịch Sử']::TEXT[], 99, '2002-12-19', NULL, 'HK: IIA', 7.5, 'ended'),
  ('6fe07396-baac-5725-9bb4-a43d7e6b5b9f'::UUID, 37472, 'Diệp Vấn 2: Tôn Sư Truyền Kỳ', '葉問2', 'Diệp Vấn 2 tiếp nối kết thúc của phần 1, tập trung vào những sóng gió trong cuộc đời của Diệp Vấn tại Hong Kong. Diệp Vấn là bậc thầy của môn phái Vịnh Xuân và chính những năm tháng sống tại Hong Kong đã giúp ông sáng tạo nhiều thế võ đặc sắc riêng của mình. Ngoài ra, ông còn chính sư phụ của huyền thoại võ thuật Lý Tiểu Long. Với cốt truyện li kì hấp dẫn, cộng với đạo diễn và dàn diễn viên nổi tiếng, tài năng Chân Tử Đan và Hùng Đại còn có nhiều diễn viên tên tuổi khác như Hồng Kim Bảo, Huỳnh Hiểu Minh, Thích Tiểu Long...., Diệp Vấn 2 đã tạo ra cơn sốt khi công chiếu rộng rãi tại các rạp Trung Quốc.', 'Having defeated the best fighters of the Imperial Japanese army in occupied Shanghai, Ip Man and his family settle in post-war Hong Kong. Struggling to make a living, Master Ip opens a kung fu school to bring his celebrated art of Wing Chun to the troubled youth of Hong Kong. His growing reputation soon brings challenges from powerful enemies, including pre-eminent Hung Gar master, Hung Quan.', 'https://image.tmdb.org/t/p/w780/ipXpgtgbdxwVg5vMrlkUmC0uPh1.jpg', 'https://image.tmdb.org/t/p/w1280/lFhTEHBphkHw5hDsuRLYAXZB3u4.jpg', 'https://www.youtube.com/watch?v=4ynwOQX1A7k', '葉偉信', ARRAY['Chân Tử Đan', 'Hồng Kim Bảo', 'Huỳnh Hiểu Minh', 'Hùng Đại Lâm', 'Trịnh Tắc Sĩ', 'Ngao Gia Niên', 'Nhậm Đạt Hoa', 'Trịnh Gia Tinh']::TEXT[], ARRAY['Hành Động', 'Lịch Sử', 'Chính Kịch']::TEXT[], 108, '2010-04-29', NULL, 'US: R', 7.5, 'ended'),
  ('8a7b8ba7-223f-5ac1-b313-a7955c4728dd'::UUID, 11104, 'Trùng Khánh Sâm Lâm', '重慶森林', 'Mỗi ngày, Cảnh sát 223 (Takeshi Kaneshiro) mua một lon dứa có hạn sử dụng là ngày 1 tháng 5, tượng trưng cho ngày anh ấy vượt qua tình yêu đã mất. Anh ta cũng để mắt đến một người phụ nữ bí ẩn đội tóc giả vàng hoe (Brigitte Lin), không hề biết rằng cô ta là một tay buôn ma túy. Cảnh sát 663 (Tony Leung Chiu Wai) đau buồn vì chia tay. Nhưng khi người yêu cũ đánh rơi chùm chìa khóa dự phòng tại một quán cà phê địa phương, một cô hầu bàn (Faye Wong) đã tự cho mình vào căn hộ của anh ta và cải thiện cuộc sống của anh ta.', 'Two melancholic Hong Kong policemen fall in love: one with a mysterious underworld figure, the other with a beautiful and ethereal server at a late-night restaurant.', 'https://image.tmdb.org/t/p/w780/oCgYpvVi9C1SaeSJmcF0QlaRQT6.jpg', 'https://image.tmdb.org/t/p/w1280/8e6avmXiqurj5LHkmdHBq6rc5jm.jpg', 'https://www.youtube.com/watch?v=P9Mxf_6pVA0', 'Vương Gia Vệ', ARRAY['Lâm Thanh Hà', 'Kim Thành Vũ', 'Lương Triều Vỹ', 'Faye Wong', '周嘉玲', '陳錦泉', 'Kwan Lee-na', 'Leung San']::TEXT[], ARRAY['Chính Kịch', 'Hài', 'Lãng Mạn']::TEXT[], 102, '1994-07-14', NULL, 'US: PG-13', 8, 'ended'),
  ('b1edf282-37f2-567a-b660-2ea0f0e0ffa0'::UUID, 10027, 'Mắt Xích Tử Thần', 'Unleashed', 'Raised as a slave, Danny is used to fighting for his survival. In fact, his "master," Bart, thinks of him as a pet and goes as far as leashing him with a collar so they can make money in fight clubs, where Danny is the main contender. When Bart''s crew is in a car accident, Danny escapes and meets a blind, kindhearted piano tuner who takes him in and uses music to free the fighter''s long-buried heart.', 'Raised as a slave, Danny is used to fighting for his survival. In fact, his "master," Bart, thinks of him as a pet and goes as far as leashing him with a collar so they can make money in fight clubs, where Danny is the main contender. When Bart''s crew is in a car accident, Danny escapes and meets a blind, kindhearted piano tuner who takes him in and uses music to free the fighter''s long-buried heart.', 'https://image.tmdb.org/t/p/w780/gghvmS3UxtOw1UHIgYjpeZNxHil.jpg', 'https://image.tmdb.org/t/p/w1280/leukkAoRu9rsa3s8oaLm8C10EWw.jpg', 'https://www.youtube.com/watch?v=AoBkHA7-I84', 'Louis Leterrier', ARRAY['Lý Liên Kiệt', 'Morgan Freeman', 'Bob Hoskins', 'Kerry Condon', 'Vincent Regan', 'Dylan Brown', 'Tamer Hassan', 'Phyllida Law']::TEXT[], ARRAY['Hành Động', 'Tội Phạm']::TEXT[], 103, '2005-02-02', NULL, 'US: R', 7, 'ended'),
  ('ab4c70f4-6a77-5094-b0f1-7487fdfd859a'::UUID, 431580, 'Everest: Người Tuyết Bé Nhỏ', 'Abominable', 'Khi cô gái tuổi teen Yi chạm trán với một Người Tuyết trên mái nhà của căn hộ cô sống tại Thượng Hải, cô và hội bạn tinh nghịch gồm Jin và Peng đã đặt cho nó cái tên “Everest”. Và cả hội đã cùng lên đường trên một hành trình vĩ đại, giúp sinh vật kỳ diệu đó trở về bên gia đình trên nóc nhà Trái Đất. Nhưng việc hội 3 người bạn cần phải làm là phải hành động trước một bước để tránh khỏi Burnish – một người đàn ông giàu có đang nung nấu ý đồ bắt cóc Người Tuyết, và nhà động vật học - giáo sư Zara để giúp Everest trở về nhà.', 'A group of misfits encounter a young Yeti named Everest, and they set off to reunite the magical creature with his family on the mountain of his namesake.', 'https://image.tmdb.org/t/p/w780/sTcfHSlnfK4ktRk24881Bd6P6CQ.jpg', 'https://image.tmdb.org/t/p/w1280/jXk3ZMq7n4ugOqKYq0CtMn3gia8.jpg', 'https://www.youtube.com/watch?v=Ap0NRJD-2ts', 'Jill Culton', ARRAY['Chloe Bennet', 'Albert Tsai', 'Suzy Eddie Izzard', 'Tenzing Norgay Trainor', 'Joseph Izzo', 'Sarah Paulson', 'Tsai Chin', 'Michelle Wong']::TEXT[], ARRAY['Gia Đình', 'Hoạt Hình', 'Phiêu Lưu', 'Hài', 'Giả Tưởng']::TEXT[], 97, '2019-09-19', NULL, 'US: PG', 7.5, 'ended'),
  ('e7192976-54a0-50d4-b910-66ec39878810'::UUID, 449924, 'Diệp Vấn 4: Hồi Cuối', '葉問4', 'Kết thúc phần 3, Diệp Vấn trở thành "gà trống nuôi con" khi vợ mất vì bệnh ung thư. Phần 4 tiếp tục mạch truyện trước nhưng mốc thời gian là vào năm 1964, lúc này Diệp Vấn đã hơn 70 tuổi. Phát hiện mình bị ung thư thanh quản do nhiều năm hút thuốc, chưởng môn họ Diệp sau đó đã quyết định sang San Francisco (Mỹ) để kiếm trường cho con và dạy võ. Thế nhưng người Mỹ lại không hiểu được võ thuật Trung Hoa. Đồng thời chính Diệp Vấn lại bị thử thách nhiều lần ngay trên đất Mỹ, nơi cộng đồng Hoa kiều bị dân Mỹ nhìn với ánh mắt phân biệt.', 'Following the death of his wife, Ip Man travels to San Francisco to ease tensions between the local kung fu masters and his star student, Bruce Lee, while searching for a better future for his son.', 'https://image.tmdb.org/t/p/w780/mAWBfTDAmfpvQGMVFuzuVl49N1P.jpg', 'https://image.tmdb.org/t/p/w1280/jZDudPPIV4lSxEVgzfK9Z6nHdhi.jpg', 'https://www.youtube.com/watch?v=f40JahDi1Uc', '葉偉信', ARRAY['Chân Tử Đan', 'Ngô Việt', 'Ngô Kiến Hào', 'Scott Adkins', 'Trịnh Tắc Sĩ', 'Trần Quốc Khôn', 'Ngao Gia Niên', 'Chris Collins']::TEXT[], ARRAY['Hành Động', 'Lịch Sử', 'Chính Kịch']::TEXT[], 105, '2019-12-19', NULL, 'US: NR', 7.3, 'ended'),
  ('554220fd-6097-5982-9979-da268734467d'::UUID, 9461, 'Long Tranh Hổ Đấu', 'Enter the Dragon', 'Đệ tử tinh hoa của Thiếu Lâm được sư phụ giao nhiệm vụ trừng phạt kẻ phản bội sư môn. Biết được chị gái của mình bị đệ tử của tay họ Hàn hại chết, với sự giúp sức của một tổ chức an ninh, Lý quyết định tham gia giải thi đấu võ nhằm đột nhập sào huyệt của bọn chúng trên một hòn đảo. Cùng đi với anh còn có hai người bạn Roper và William. Tại sào huyệt của chúng Lý vừa tham gia cuộc tỉ thí võ thuật vừa tìm cách đột nhập vào sào huyệt của lũ kẻ gian, với sự giúp đỡ của nữ gián điệp Mỹ Linh.', 'A martial artist agrees to spy on a reclusive crime lord using his invitation to a tournament there as cover.', 'https://image.tmdb.org/t/p/w780/fyrh2ULEcmLpGTVLPQqFW45hqr5.jpg', 'https://image.tmdb.org/t/p/w1280/jakcWheJ40mXjSgZnoDZtJxLl0u.jpg', 'https://www.youtube.com/watch?v=CDUw0ruKzNY', 'Robert Clouse', ARRAY['Lý Tiểu Long', 'John Saxon', 'Jim Kelly', '石堅', 'Ahna Capri', 'Robert Wall', 'Angela Mao Ying', 'Betty Chung']::TEXT[], ARRAY['Hành Động']::TEXT[], 102, '1973-08-17', NULL, 'US: R', 7.4, 'ended'),
  ('d0c582f8-4f0d-5d4a-bb24-bc6f4ea5a68b'::UUID, 1729, 'Vua Kung Fu', 'The Forbidden Kingdom', 'Jason anh chàng người Mỹ ham mê võ thuật Trung Hoa tới cực điểm trái ngược với suy nghĩ của mọi người Jason lại thường xuyên bị bạn bè bắt nạt nhưng mọi chuyện đã thay đổi khi Jason tới tiệm cho thuê phim kiêm cầm đồ của ông lão người Tàu tên Hop. Cậu ngỡ ngàng khi ngó thấy một cây gậy sắt màu vàng nằm trong căn phòng lâu nay vẫn kín cửa. Ông lão đã trao cho cậu cây gậy và sau 500 năm cậu chính là người được chọn để giải cứu Tôn Ngộ Không. The Forbidden Kingdom được coi là phim bom tấn của Châu Á vào thời điểm nó ra đời. The Forbidden Kingdom quy tụ dàn sao hùng hậu với Lý Liên Kiệt, Thành Long, Lưu Diệc Phi khán giả chắc chắn sẽ mãn nhãn khi xem phim.', 'An American teenager who is obsessed with Hong Kong cinema and kung-fu classics makes an extraordinary discovery in a Chinatown pawnshop: the legendary stick weapon of the Chinese sage and warrior, the Monkey King. With the lost relic in hand, the teenager unexpectedly finds himself travelling back to ancient China to join a crew of warriors from martial arts lore on a dangerous quest to free the imprisoned Monkey King.', 'https://image.tmdb.org/t/p/w780/sgW6xkpfaMY1raV03zyWADBsbNP.jpg', 'https://image.tmdb.org/t/p/w1280/9a59H9qoAzMcj1NWurMgvg9iLaT.jpg', 'https://www.youtube.com/watch?v=KPtXwW-Erww', 'Rob Minkoff', ARRAY['Thành Long', 'Lý Liên Kiệt', 'Michael Angarano', 'Lưu Diệc Phi', 'Lý Băng Băng', 'Trâu Triệu Long', 'Morgan Benoit', 'Jack Posobiec']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Giả Tưởng']::TEXT[], 104, '2008-04-17', NULL, 'US: PG-13', 6.7, 'ended'),
  ('d8f50fa0-21c7-51c3-87b8-ad40cbf5422b'::UUID, 365222, 'Diệp Vấn 3', '葉問3', '"Diệp Vấn 3" là phần cuối cùng trong series phim "Diệp Vấn", bộ phim xoay quanh cuộc đời lúc về già của Diệp Vấn, khắc họa một thế hệ tông sư võ học "chiến đấu vì tính mạng"', 'When a band of brutal gangsters led by a crooked property developer make a play to take over the city, Master Ip is forced to take a stand.', 'https://image.tmdb.org/t/p/w780/bDaeLlpmuvsVuinCG9IyB1cpuH1.jpg', 'https://image.tmdb.org/t/p/w1280/19Shb0Xn0PeLXA4CkT2TIIvxaR6.jpg', 'https://www.youtube.com/watch?v=klg-nxejrp8', '葉偉信', ARRAY['Chân Tử Đan', 'Trương Tấn', 'Hùng Đại Lâm', 'Đàm Diệu Văn', 'Mike Tyson', 'Ngô Thiên Ngữ', 'Trịnh Tắc Sĩ', 'Lương Gia Nhân']::TEXT[], ARRAY['Hành Động', 'Chính Kịch', 'Lịch Sử']::TEXT[], 105, '2015-12-24', NULL, 'US: PG-13', 7, 'ended'),
  ('aab949f3-bab1-5455-b8f2-11e48ec6650e'::UUID, 10775, 'Vô Gian Đạo', '無間道', 'Trong phim Vô Gian Đạo, Lưu Kiến Minh là trợ thủ đắc lực cho Sâm, một ông trùm mafia, hoạt động bí mật bằng cách trà trộn vào Cục Điều tra hình sự Hong Kong. Ở bên kia chiến tuyến nhưng giống hệt trường hợp của Lưu Kiến Minh, Trần Vĩnh Nhân là cảnh sát nằm vùng. Anh "đội lốt" một tên mafia trong băng đảng của Sam một cách hoàn hảo. Cuộc đấu trí căng thẳng giữa hai kỳ phùng địch thủ của hai phe thiện và ác sẽ diễn ra như thế nào? Với sự tham gia của các ngôi sao như Lương Triều Vỹ, Lưu Đức Hoa và Trịnh Tú Văn, "Vô gian đạo" khai thác đề tài cũ, nhưng theo một cách hoàn toàn mới. Cả hai đạo diễn rất khéo léo khi dẫn dắt các tình tiết và nhân vật, khiến bộ phim trở thành hiện tượng của điện ảnh thành công ngay khi mới ra đời.', 'Chan Wing Yan, a young police officer, has been sent undercover as a mole in the local mafia. Lau Kin Ming, a young mafia member, infiltrates the police force. Years later, their older counterparts, Chen Wing Yan and Inspector Lau Kin Ming, respectively, race against time to expose the mole within their midst.', 'https://image.tmdb.org/t/p/w780/rIwfBMQP2eOUZVDkZ7496Z0TwDZ.jpg', 'https://image.tmdb.org/t/p/w1280/4Mm5l3TcKGynSNto0eyRJgBrkJ7.jpg', 'https://www.youtube.com/watch?v=GqdXakBnmsE', 'Mạch Triệu Huy', ARRAY['Lưu Đức Hoa', 'Lương Triều Vỹ', 'Huỳnh Thu Sinh', 'Tăng Chí Vĩ', 'Trần Tuệ Lâm', 'Trịnh Tú Văn', '蕭亞軒', 'Đỗ Vấn Trạch']::TEXT[], ARRAY['Chính Kịch', 'Giật Gân', 'Tội Phạm']::TEXT[], 100, '2002-12-12', NULL, 'US: R', 7.8, 'ended'),
  ('974e379e-053c-59cf-abf0-576619ef9371'::UUID, 9550, 'Thập Diện Mai Phục', '十面埋伏', 'Thập diện Mai Phục lấy bối cảnh năm 859 sau Công nguyên tại Trung Hoa.Tổ chức Phi Đao Môn chống lại triều đình bệ rạc đã cài được kiếm khách Lưu bộ đầu làm nội gián trong hàng ngũ binh lính triều đình, giữ chức đội trưởng cùng với Kim bộ đầu. Theo kế hoạch của Lưu, Kim chấp nhận giả làm người giải cứu cho kỹ nữ mù Tiểu Muội để tìm cách tiêu diệt Phi đao môn. Chàng không ngờ cô gái mù mà mình trót đem lòng yêu, thực ra chỉ là con mồi nhằm đưa Kim và cả triều đình vào bẫy…', 'In 9th century China, a corrupt government wages war against a rebel army called the Flying Daggers. A romantic warrior breaks a beautiful rebel out of prison to help her rejoin her fellows, but things are not what they seem.', 'https://image.tmdb.org/t/p/w780/eqjJEweedNts5AlkdUa8IzwlDNy.jpg', 'https://image.tmdb.org/t/p/w1280/qODx2OuPQNDxXUoqHBmTNww2iC3.jpg', 'https://www.youtube.com/watch?v=AaOO2oork7A', 'Trương Nghệ Mưu', ARRAY['Kim Thành Vũ', 'Lưu Đức Hoa', 'Chương Tử Di', '宋丹丹', '赵鸿飞', 'Quách Quân', '张澍', 'Jiusheng Wang']::TEXT[], ARRAY['Phiêu Lưu', 'Chính Kịch', 'Hành Động']::TEXT[], 119, '2004-07-16', NULL, 'HK: IIA', 7.3, 'ended'),
  ('5c9ebf07-826a-5719-8b1d-eda2d854f77f'::UUID, 16577, 'Siêu Nhí Astro', 'Astro Boy', 'Siêu nhí Astro, một người máy trẻ có siêu năng lực, dấn thân vào cuộc phiêu lưu nguy hiểm nhằm tìm kiếm mục tiêu trước khi trở về nhà để cứu người thân của mình.', 'Set in the futuristic Metro City, Astro Boy (Atom) is a young robot with incredible powers created by a brilliant scientist in the image of the son he had lost. Unable to fulfill his creator''s expectations, Astro embarks on a journey in search of acceptance, experiencing betrayal and a netherworld of robot gladiators, before returning to save Metro City and reconcile with the father who rejected him.', 'https://image.tmdb.org/t/p/w780/6LX0oXFOhoMgjFGkhVEq2vDuLXk.jpg', 'https://image.tmdb.org/t/p/w1280/t39jaNSYMVNecNPQSVVlW6I4opm.jpg', 'https://www.youtube.com/watch?v=HIzvNSXXQWg', 'David Bowers', ARRAY['Freddie Highmore', 'Kristen Bell', 'Nathan Lane', 'Eugene Levy', 'Matt Lucas', 'Bill Nighy', 'Donald Sutherland', 'Charlize Theron']::TEXT[], ARRAY['Hoạt Hình', 'Hành Động', 'Gia Đình', 'Khoa Học Viễn Tưởng']::TEXT[], 94, '2009-10-15', NULL, 'US: PG', 6.3, 'ended'),
  ('d9f484d9-6610-5e16-8724-de9d3d253f8f'::UUID, 440471, 'Kế Hoạch Đào Tẩu: Địa Ngục', 'Escape Plan 2: Hades', 'Sau phần 1 được ra mắt năm 2013 nhận được sự chú ý của khán giả và giới chuyên môn, phần 2 của Escape Plan tiếp tục có nội dung xoay quanh chuyên gia bảo mật Ray Breslin. Anh là một bậc thầy trong việc cài đặt hệ thống an ninh cho các nhà tù liên bang và cũng là người “thử vượt ngục” tại các nhà tù cũ kỹ, nơi mà các nhà chức trách luôn tự hào là chốn không thể xâm phạm.', 'Ray Breslin manages an elite team of security specialists trained in the art of breaking people out of the world''s most impenetrable prisons. When his most trusted operative, Shu Ren, is kidnapped and disappears inside the most elaborate prison ever built, Ray must track him down with the help of some of his former friends.', 'https://image.tmdb.org/t/p/w780/umO714IeAKBti0rvuIJ2fpgssxl.jpg', 'https://image.tmdb.org/t/p/w1280/xIAaN3AQqaJiN5RJ0WsmBady8Hq.jpg', 'https://www.youtube.com/watch?v=6Q7vVt-MeXk', 'Steven C. Miller', ARRAY['Sylvester Stallone', 'Dave Bautista', 'Jesse Metcalfe', '50 Cent', 'Huỳnh Hiểu Minh', 'Wes Chatham', 'Titus Welliver', 'Tyron Woodley']::TEXT[], ARRAY['Hành Động', 'Giật Gân', 'Tội Phạm', 'Bí Ẩn', 'Khoa Học Viễn Tưởng']::TEXT[], 93, '2018-06-05', NULL, 'US: R', 5.2, 'ended'),
  ('371e2e16-0f15-52c9-b4f1-6fb39e415664'::UUID, 1419406, 'Bổ Phong Truy Ảnh', '捕风追影', 'Wong Tak-Chung, một cựu chuyên gia giám sát được biết đến với khả năng phân tích dữ liệu và truy vết bậc thầy, bị cảnh sát Ma Cao mời trở lại hợp tác điều tra sau khi xuất hiện hàng loạt vụ cướp quy mô lớn do một tổ chức tội phạm công nghệ cao thực hiện.', 'Macau Police brings the tracking expert police officer out of retirement to help catch a dangerous group of professional thieves.', 'https://image.tmdb.org/t/p/w780/5LGUvRBXoXHsMZsZrCGBOVmwOVd.jpg', 'https://image.tmdb.org/t/p/w1280/4BtL2vvEufDXDP4u6xQjjQ1Y2aT.jpg', 'https://www.youtube.com/watch?v=HZXVnn6GnVM', '杨子', ARRAY['Thành Long', 'Trương Tử Phong', 'Lương Gia Huy', 'Thử Sa', '文俊辉', '周政杰', 'Vương Tử Dị', 'Lang Nguyệt Đình']::TEXT[], ARRAY['Hành Động', 'Tội Phạm', 'Chính Kịch', 'Giật Gân']::TEXT[], 142, '2025-08-16', NULL, 'HK: IIB', 8.4, 'ended'),
  ('ff133c1c-57b2-5f6b-bdd0-90a42c3f64e2'::UUID, 550205, 'Ước Nguyện Thần Long', 'Wish Dragon', 'Thiếu niên đầy quyết tâm Din đang mong tìm lại người bạn thân hồi nhỏ thì gặp một chú rồng có thể ban điều ước – nhân vật cho cậu thấy sự kỳ diệu của các khả năng.', 'Determined teen Din is longing to reconnect with his childhood best friend when he meets a wish-granting dragon who shows him the magic of possibilities.', 'https://image.tmdb.org/t/p/w780/mK0T40aykthZaP5yw1EX3zey7gc.jpg', 'https://image.tmdb.org/t/p/w1280/4kIRrW1AlHP5Idne8CPHeQt8nR5.jpg', 'https://www.youtube.com/watch?v=uWIRyU5fuzU', 'Chris Appelhans', ARRAY['Jimmy Wong', 'John Cho', 'Constance Wu', 'Natasha Liu Bordizzo', 'Jimmy O. Yang', 'Aaron Yoo', 'Will Yun Lee', 'Bobby Lee']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Hài', 'Giả Tưởng', 'Lãng Mạn', 'Phiêu Lưu']::TEXT[], 99, '2021-01-15', NULL, 'US: PG', 7.8, 'ended'),
  ('5b4ae54e-f0d2-5c43-b238-febebd8e6af3'::UUID, 7549, 'Hoắc Nguyên Giáp', '霍元甲', 'Hoắc Nguyên Giáp từ bé đã có ước mơ được nối tiếp cha mình trở thành cao thủ võ thuật Trung Hoa. Trải qua khó khăn và thử thách, cuối cùng Nguyên Giáp cũng đạt được ước nguyện đó. Nhưng rồi một số biến cố xảy đến khiến cho anh phải vắng mặt một thời gian. Tài năng của anh tỏa sáng trở lại khi một cuộc thi võ thuật được diễn ra và anh mang vinh dự đại diện cho đất nước mình để tham gia.', 'After going through a series of tragic events in his life, martial arts master Huo Yuanjia returns to Tianjin and must fight four international soldiers, in order to safeguard his nation''s pride.', 'https://image.tmdb.org/t/p/w780/hYx3OBShyRe4YnSkf80CdniosHk.jpg', 'https://image.tmdb.org/t/p/w1280/sumVr8uduhPwx4H3cWjrP76i3AB.jpg', 'https://www.youtube.com/watch?v=4I3oUkBnFG0', '于仁泰', ARRAY['Lý Liên Kiệt', 'Tôn Lệ', '董勇', '中村獅童', 'Bào Khởi Tịnh', '陈之辉', '丁亮', 'Yun Qu']::TEXT[], ARRAY['Chính Kịch', 'Hành Động']::TEXT[], 103, '2006-01-26', NULL, 'HK: IIB', 7.5, 'ended'),
  ('deb1d03d-4435-58f0-a776-d5adbb113724'::UUID, 11220, 'Đọa lạc thiên sứ', '墮落天使', 'Bộ phim giới thiệu về những tay sát thủ và thế giới ngầm của Hồng Kông, được Vương Gia Vệ phát triển từ những tình tiết của Trùng Khánh Sâm Lâm, tác phẩm thành công trước đó của ông. Một tay sát thủ bỏ lại sau lưng những tội lỗi để sống một cuộc sống mới trong khi người nữ trợ tá lại nảy sinh tình cảm với anh. Ngoài ra bộ phim còn kể về một tay intertwined, chuyên sống bằng cách quản lý các công việc của người khác khi họ đã đóng cửa và đang tìm kiếm đồng sự.', 'An indifferent hitman, his infatuated business partner and an ex-convict search for love and meaning as their lives cross paths in Hong Kong.', 'https://image.tmdb.org/t/p/w780/3BQrmnZq9OWDWjHe15GB6XFMaEN.jpg', 'https://image.tmdb.org/t/p/w1280/lInQVVbPjKFGX7GDcxNMXALy2Y4.jpg', 'https://www.youtube.com/watch?v=uxaT19BlH0M', 'Vương Gia Vệ', ARRAY['Lê Minh', 'Lý Gia Hân', 'Kim Thành Vũ', 'Dương Thái Ni', 'Mạc Văn Uý', '陳萬雷', 'Toru Saito', '江道海']::TEXT[], ARRAY['Hành Động', 'Lãng Mạn', 'Tội Phạm']::TEXT[], 98, '1995-09-06', NULL, 'US: NR', 7.7, 'ended'),
  ('5148ffb2-a0b1-57d9-8f57-e8837c515bd2'::UUID, 9462, 'Mãnh Long Quá Giang', '猛龍過江', 'Đường Long (Lý Tiểu Long) đến tận nước Ý xa xôi để giúp đỡ một người bạn đang mở quán ăn. Tại đây anh đã chặn đứng âm mưu muốn thôn tính tất cả các quán ăn của một ông trùm. Cảnh quyết đấu cuối cùng giữa 2 cao thủ Lý Tiểu Long với Chuck Norris – 7 lần vô địch Karate thế giới, lần đầu tiên đóng phim – tại đấu trường La Mã cổ đại Colosseum gây ấn tượng nhất đối với người xem. Khán giả chưa bao giờ được xem một cặp đấu võ thuật đỉnh cao như vậy trước đây.', 'After a Chinese restaurant in Rome is threatened by the mafia, who will stop at nothing to acquire the property, the owner recruits a family friend in Hong Kong, kung fu expert Tang Lung, to help them defend their business.', 'https://image.tmdb.org/t/p/w780/m7AIITQ624sfldI4SsX4htXPH1f.jpg', 'https://image.tmdb.org/t/p/w1280/nqcpVS8tL4GrM6NAoIrPepnF1Mp.jpg', 'https://www.youtube.com/watch?v=72giNDkKhSE', 'Lý Tiểu Long', ARRAY['Lý Tiểu Long', '苗可秀', 'Chuck Norris', '魏平澳', '黃宗迅', 'Robert Wall', '黃仁植', '金帝']::TEXT[], ARRAY['Hành Động', 'Tội Phạm']::TEXT[], 100, '1972-12-30', NULL, 'DE: 18', 7.4, 'ended'),
  ('492a77fa-fcf7-53a1-8b71-c82d0ca82c0e'::UUID, 10610, 'The Medallion', 'The Medallion', 'A Hong Kong detective suffers a fatal accident involving a mysterious medallion and is transformed into an immortal warrior with superhuman powers.', 'A Hong Kong detective suffers a fatal accident involving a mysterious medallion and is transformed into an immortal warrior with superhuman powers.', 'https://image.tmdb.org/t/p/w780/lbjFWKfe8WdS8Pj6WVPlyEKeVEo.jpg', 'https://image.tmdb.org/t/p/w1280/533o6HpRqtdCCOiCitICyUSFJCj.jpg', 'https://www.youtube.com/watch?v=n8JP2Zh7Www', 'Trần Gia Thượng', ARRAY['Thành Long', 'Lee Evans', 'Claire Forlani', 'Chung Lệ Đề', 'Julian Sands', 'Huỳnh Thu Sinh', 'Johann Myers', 'John Rhys-Davies']::TEXT[], ARRAY['Giật Gân', 'Giả Tưởng', 'Hành Động', 'Hài']::TEXT[], 88, '2003-08-15', NULL, 'US: PG-13', 5.7, 'ended'),
  ('c582fbbd-f2b3-5885-aaa8-d301693d9503'::UUID, 97430, 'Tay Đấm Sắt', 'The Man with the Iron Fists', 'Phim lấy bối cảnh triều nhà Thanh. Dù vậy, nó lại không phụ thuộc nhiều vào văn hóa và võ thuật Trung Hoa mà có những biến tấu riêng đậm chất phương Tây. Vào thời nhà Thanh vốn vẫn phụ thuộc nhiều vào chế độ phong kiến, một người thợ rèn thấp hèn (RZA) có khả năng chế tạo những món vũ khí đặc biệt cho các bộ tộc khác nhau.  Anh dành dụm số tiền thu được để chuộc lại sự tự do cho người con gái anh yêu là nàng Lụa (Jamie Chung). Một ngày nọ có tin đồn về chuyến hàng chở vàng của hoàng đế sẽ ghé ngang vùng đất này, lãnh đạo của các bộ tộc mưu đồ sẽ giết nhau để giành giật số vàng này. Trong số đó, bộ tộc sư tử là tàn bạo nhất. Chúng được lãnh đạo bởi Sư Tử Bạc (Bryon Mann) và Sư tử Đồng (Cung Le).', 'In feudal China, a blacksmith who makes weapons for a small village is put in the position where he must defend himself and his fellow villagers.', 'https://image.tmdb.org/t/p/w780/zWj5bRJlVJDtBA138JDFhvDA82D.jpg', 'https://image.tmdb.org/t/p/w1280/bTeyNpG9PczQbgeQuSndkMuLlna.jpg', 'https://www.youtube.com/watch?v=ZBUpXKzmJww', 'RZA', ARRAY['RZA', 'Russell Crowe', 'Pam Grier', 'Dave Bautista', 'Lucy Liu', 'Jamie Chung', 'Cung Le', 'Chu Châu']::TEXT[], ARRAY['Hành Động']::TEXT[], 96, '2012-11-02', NULL, 'US: R', 5.5, 'ended'),
  ('a1005bcc-b32e-5083-8e93-f6f563e20c46'::UUID, 33542, 'Vụ Huyên Náo Phố Bronx', '紅番區', 'Cường từ Hồng Kông đến New York để chuẩn bị cho đám cưới người chú của anh ta và khám phá ra được sự nguy hiểm ở khu Bronx. Trong khi trông nom cửa hàng mà chú của Cường vừa bán cho gã nhà giàu Elaine, anh tìm hiểu ra rằng hắn là một tên buôn lậu kim cương và có một nhóm những gã côn đồ theo sau...', 'Keung comes from Hong Kong to visit New York for his uncle''s wedding. His uncle runs a market in the Bronx and Keung offers to help out while Uncle is on his honeymoon. During his stay in the Bronx, Keung befriends a neighbour kid and beats up some neighbourhood thugs who cause problems at the market. One of those petty thugs in the local gang stumbles into a criminal situation way over his head.', 'https://image.tmdb.org/t/p/w780/yZCoKUArS2mlESqvY1NVal4pnq4.jpg', 'https://image.tmdb.org/t/p/w1280/upETXObL782G3OyjBcOw83oizHT.jpg', 'https://www.youtube.com/watch?v=8PT49TzAV7I', '唐季禮', ARRAY['Thành Long', 'Mai Diễm Phương', 'Diệp Phương Hoa', 'Đổng Phiếu', 'Marc Akerstream', 'Garvin Cross', 'Morgan Lam', 'Ailen Sit Chun-Wai']::TEXT[], ARRAY['Tội Phạm', 'Hành Động', 'Hài', 'Giật Gân']::TEXT[], 106, '1995-01-21', NULL, 'US: R', 6.9, 'ended'),
  ('98d3ed85-684c-5c2a-8a6f-6dae3219c072'::UUID, 535167, 'Địa Cầu Lưu Lạc', '流浪地球', 'Mặt trời tiến đến giai đoạn Red Giant, đe dọa thiêu đốt Trái đất. Lúc khí hậu thay đổi, nhân loại chế tạo các động cơ khổng lồ để đẩy Trái đất khỏi hệ Mặt trời, đến vùng mới trong vũ trụ. Trong hành trình di chuyển kéo dài 2.500 năm, con người xuống ẩn náu ở các thành phố ngầm, và các phi hành gia du hành vũ trụ có nhiệm vụ giải cứu thế giới.', 'When the Sun begins to expand in such a way that it will inevitably engulf and destroy the Earth in a hundred years, united mankind finds a way to avoid extinction by propelling the planet out of the Solar System using gigantic engines, moving it to a new home located four light years away, an epic journey that will last thousands of years.', 'https://image.tmdb.org/t/p/w780/tXuQCgx69DxVgeTsU0TkruR3i9O.jpg', 'https://image.tmdb.org/t/p/w1280/wIrqeoJHYtZmneqIufPtcOHMjOg.jpg', 'https://www.youtube.com/watch?v=0TDII5IkI3Y', '郭帆', ARRAY['Ngô Kinh', 'Khuất Sở Tiêu', 'Lý Quang Khiết', 'Ngô Mạnh Đạt', 'Triệu Kim Mạch', '隋凯', 'Khúc Tĩnh Tĩnh', 'Zhang Yichi']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Hành Động', 'Chính Kịch']::TEXT[], 126, '2019-02-05', NULL, 'US: PG-13', 6.6, 'ended'),
  ('3d91277d-afaa-5aab-a1d7-0d1ecd7b514e'::UUID, 508763, 'Đường Về Nhà Của Cún Con', 'A Dog''s Way Home', 'Phim chính là hành trình đầy gian nan và vô cùng cảm động nhằm tìm về với chủ của một chú cún đi lạc. Bella là một cô cún được Lucas nhận nuôi từ bé. Có thể nói, cả hai có mối quan hệ rất thân thiết. Cho đến một ngày, vì mải mê đuổi theo một chú sóc mà Bella đã đi lạc. Lo rằng Lucas không thấy mình sẽ cô đơn và buồn bã, Bella bất chấp mọi hiểm nguy, khó khăn để tìm đường về nhà bằng được.', 'The adventure of Bella, a dog who embarks on an epic 400-mile journey home after she is separated from her beloved human.', 'https://image.tmdb.org/t/p/w780/5idR3OoQ92vQtFRzd3R0JCfJMrT.jpg', 'https://image.tmdb.org/t/p/w1280/w7MsyOpP003FYhsiTgVHa3rNsrz.jpg', 'https://www.youtube.com/watch?v=1pKdCHvH310', 'Charles Martin Smith', ARRAY['Bryce Dallas Howard', 'Jonah Hauer-King', 'Alexandra Shipp', 'Ashley Judd', 'Edward James Olmos', 'Wes Studi', 'Chris Bauer', 'Barry Watson']::TEXT[], ARRAY['Chính Kịch', 'Phiêu Lưu', 'Gia Đình']::TEXT[], 96, '2019-01-10', NULL, 'US: PG', 7.4, 'ended'),
  ('a7558933-6654-5d5f-871d-a3a4c7a45750'::UUID, 11230, 'Túy quyền I', '醉拳', 'Hoàng Phi Hồng (Thành Long) vì quá nghịch ngợm nên bị cha gửi tới thọ giáo cùng Tô Khất Di, vị sư phụ tính tình quái gở nổi tiếng hay đánh què đồ đệ. Anh bị hành hạ đến cùng cực mà không nhận ra là vị sư phụ đang luyện công cho mình theo một cách thức riêng. Những ngày rèn luyện gian khổ cũng qua, Hoàng Phi Hồng mình mang tuyệt học trở về nhà đúng lúc người cha Hoàng Kỳ Anh đang bị kẻ tử thù truy sát.', 'After getting into trouble, a mischievous young man is sent to train under a brutal, but slovenly old beggar, who teaches him the secret of the Drunken Fist.', 'https://image.tmdb.org/t/p/w780/cf43J2SH8tECZVl9N5n0Q6Ckche.jpg', 'https://image.tmdb.org/t/p/w1280/oxQJT3CCwxRRDgnPUZvT6xmts61.jpg', 'https://www.youtube.com/watch?v=WSu-9X8NF9k', '袁和平', ARRAY['Thành Long', '袁小田', '황정리', '石天', '徐蝦', 'Linda Lin Ying', 'Lam Kau', '李超俊']::TEXT[], ARRAY['Hành Động', 'Hài']::TEXT[], 111, '1978-10-05', NULL, 'US: PG-13', 7.4, 'ended'),
  ('7cf958a1-ac63-5f19-ba4f-a05caf6ea5dc'::UUID, 844, '2046', '2046', 'Năm 1966, Châu từ Singapore trở lại Hồng Kông. Anh viết bài cho một tờ báo để kiếm sống. Buổi tối Giáng Sinh 24 tháng 12 năm 1966, Châu gặp lại một người bạn cũ - Lulu, trong một hộp đêm. Lulu uống quá say và Châu đưa cô ta về nhà, căn phòng cô trọ số 2046. Hôm sau khi Châu trở lại khách sạn để trả chìa khóa thì ông chủ nói rằng không có ai tên Lulu ở đó. Châu quyết định trọ lại khách sạn và lấy căn phòng 2047. Anh biết rằng hôm trước người bạn trai của Lulu đã giết cô ta trong phòng 2046 vì ghen tuông.', 'Women enter and exit a science fiction author''s life over the course of a few years after the author loses the woman he considers his one true love.', 'https://image.tmdb.org/t/p/w780/8isHlc8ZCRN3Eyx0xmAML7FMZvd.jpg', 'https://image.tmdb.org/t/p/w1280/8ASGDbVRdK0UX71fV7oknkquS7k.jpg', 'https://www.youtube.com/watch?v=xjmvuBY3560', 'Vương Gia Vệ', ARRAY['Lương Triều Vỹ', 'Củng Lợi', 'Faye Wong', '木村拓哉', 'Chương Tử Di', 'Đổng Khiết', 'Lưu Gia Linh', 'Trương Chấn']::TEXT[], ARRAY['Chính Kịch', 'Khoa Học Viễn Tưởng', 'Lãng Mạn']::TEXT[], 128, '2004-09-29', NULL, 'HK: IIB', 7.3, 'ended'),
  ('1090197f-ac45-5541-a1fe-f1344b69c8a3'::UUID, 12207, 'Túy quyền II', '醉拳二', 'Cùng cha trở về nhà, Hoàng Phi Hồng mắc kẹt vào giữa hai trận tuyến, một bên là bọn buôn lậu đồ cổ người phương Tây, bên kia là những người bảo vệ cổ vật. Lúc này Phi Hồng đã là một cao thủ túy quyền nhưng người cha luôn tìm cách cấm cản vì sợ anh dấn sâu vào giang hồ hiểm ác lắm chuyện thị phi. Hoàng Phi Hồng sẽ không chỉ phải tìm cách chặn tay bọn buôn lậu nước ngoài, mà còn phải vượt qua được định kiến và sự cấm đoán của người cha vô cùng nghiêm khắc', 'Returning home with his father after a shopping expedition, Wong Fei-hung is unwittingly caught up in the battle between foreigners who wish to export ancient Chinese artifacts and loyalists who don''t want the pieces to leave the country. Fei-hung must fight against the foreigners using his Drunken Boxing style, and overcome his father''s antagonism as well.', 'https://image.tmdb.org/t/p/w780/uB4KW0xqDz6Y67we4319Hvae0wK.jpg', 'https://image.tmdb.org/t/p/w1280/zo14UuFDTVy91cBNWHplHCqHCPt.jpg', 'https://www.youtube.com/watch?v=p4X2naY_2-k', 'Lưu Gia Lương', ARRAY['Thành Long', 'Địch Long', 'Mai Diễm Phương', 'Tưởng Chí Quang', 'Lưu Gia Lương', 'Lô Huệ Quang', 'Pak Ho-sung', 'Huỳnh Nhật Hoa']::TEXT[], ARRAY['Hành Động', 'Hài']::TEXT[], 102, '1994-02-03', NULL, 'US: R', 7.5, 'ended'),
  ('5bb02d55-eaad-5677-a778-2e8755961986'::UUID, 11713, 'Tinh Võ Môn', '精武門', 'Tinh Võ Môn là một bộ phim điện ảnh võ thuật,nói về Trần Chân,một đồ đệ của danh sư Hoắc Nguyên Giáp.Chuyện phim kể về lúc sau khi Hoắc Nguyên Giáp qua đời,Trần Chân hiện đang ở nước ngoài và anh lập tức về nước sau khi nghe tin dữ.Trần Chân phát hiện ra cái chết của sư phụ mình là vô vàn bí ẩn vì người hạ gục sư phụ anh có võ công hết sức tầm thường.Sau đó bí mật dần hé lộ,Trần Chân vạch mặt kẻ gian tế trong môn phái và sau đó tiêu diệt từng tên từng tên một.', 'During the Japanese occupation of Shanghai, Chen Zhen, the star pupil of a recently-deceased martial arts teacher battles a Japanese dojo which seeks the demise of his fighting school.', 'https://image.tmdb.org/t/p/w780/xWMfzwgrlg17vOzyHsWk93xhSaH.jpg', 'https://image.tmdb.org/t/p/w1280/lgk1ptAoo8L5sMtVSadkBcnEUqs.jpg', 'https://www.youtube.com/watch?v=oO9PVJdgu4M', '羅維', ARRAY['Lý Tiểu Long', '苗可秀', 'Maria Yi', '田俊', 'Điền Phong', '黃宗迅', '韩英杰', '魏平澳']::TEXT[], ARRAY['Chính Kịch', 'Hành Động', 'Giật Gân']::TEXT[], 108, '1972-03-22', NULL, 'HK: IIB', 7.2, 'ended'),
  ('bbea278c-48e9-521f-ba38-c9acc2531b57'::UUID, 9056, 'Câu Chuyện Cảnh Sát', '警察故事', 'Nội dung của phim Câu Chuyện Cảnh Sát bắt đầu từ việc Thanh tra cảnh sát Trần Gia Câu được lệnh bảo vệ một nhân chứng quan trọng là Salina, thư kí của tay trùm ma túy Chu Thao, trong một vụ kiện tố cáo y. Tuy nhiên Trần Gia Câu không ngờ rằng anh đã bị Chu Thao gài bẫy vào một vụ giết người. Để giải oan cho mình Trần Gia Câu buộc phải một mình đi tìm bằng chứng và đối đầu với toàn bộ băng đảng của Chu Thao.Trong Phim, Trần Gia Câu phải một mình chống lại cả băng đảng, chúng ta sẽ thấy được những pha hành động hết sức mạo hiểm của nam diễn viên, những màn đấu võ, rượt đuổi đậm chất Hollywood xen lẫn vào đó là những tình tiết hài hước đúng chất của Thành Long.', 'Officer Chan Ka Kui manages to put a major Hong Kong drug dealer behind the bars practically alone, after a shooting and an impressive chase inside a slum. Now, he must protect the boss'' secretary, Selina, who will testify against the gangster in court.', 'https://image.tmdb.org/t/p/w780/1eFB0Iy1TMU4VO5hMcoCE064JAT.jpg', 'https://image.tmdb.org/t/p/w1280/eYDAnSidN4rIEuneS5gEJkTyk3l.jpg', 'https://www.youtube.com/watch?v=ccRgWRcKb9w', 'Thành Long', ARRAY['Thành Long', 'Lâm Thanh Hà', 'Trương Mạn Ngọc', 'Đổng Phiếu', 'Sở Nguyên', '曹查理', '林國雄', 'Kim Hưng Hiền']::TEXT[], ARRAY['Hành Động', 'Tội Phạm', 'Hài']::TEXT[], 100, '1985-12-14', NULL, 'US: PG-13', 7.6, 'ended'),
  ('2396310f-8972-5d6c-a8a7-ece59469941d'::UUID, 27205, 'Kẻ Cắp Giấc Mơ', 'Inception', 'Cobb đánh cắp thông tin từ các mục tiêu của mình bằng cách đi vào giấc mơ của họ. Saito đề nghị xóa sạch tiền án của Cobb như một khoản thanh toán cho việc thực hiện hành vi đầu tiên đối với con trai của đối thủ cạnh tranh ốm yếu của mình.', 'Cobb, a skilled thief who commits corporate espionage by infiltrating the subconscious of his targets is offered a chance to regain his old life as payment for a task considered to be impossible: "inception", the implantation of another person''s idea into a target''s subconscious.', 'https://image.tmdb.org/t/p/w780/eBtqGWtR5KUiNl6OXHLR3ri6nVm.jpg', 'https://image.tmdb.org/t/p/w1280/8ZTVqvKDQ8emSGUEMjsS4yHAwrp.jpg', 'https://www.youtube.com/watch?v=JE9z-gy4De4', 'Christopher Nolan', ARRAY['Leonardo DiCaprio', 'Joseph Gordon-Levitt', 'Watanabe Ken', 'Tom Hardy', 'Elliot Page', 'Dileep Rao', 'Cillian Murphy', 'Tom Berenger']::TEXT[], ARRAY['Hành Động', 'Khoa Học Viễn Tưởng', 'Tội Phạm']::TEXT[], 148, '2010-07-15', NULL, 'US: PG-13', 8.4, 'ended'),
  ('c2118343-8494-5092-bf1e-81fb24d8df6c'::UUID, 24428, 'Avengers: Biệt Đội Siêu Anh Hùng', 'The Avengers', 'The Avengers là bộ phim giả tưởng kể về một nhóm siêu anh hùng với những khả năng đặc biệt, họ bao gồm: Người Sắt, Thor, Đội trưởng Mỹ, và Người Khổng Lồ Xanh Hulk cùng tham gia với tổ chức bảo vệ thế giới SHIELD. Mục đích của SHIELD là nhằm bảo vệ Trái Đất khỏi âm mưu hủy hoại của những thế lực xấu từ ngoài địa cầu mà kẻ cầm đầu là Loki.', 'When an unexpected enemy emerges and threatens global safety and security, Nick Fury, director of the international peacekeeping agency known as S.H.I.E.L.D., finds himself in need of a team to pull the world back from the brink of disaster. Spanning the globe, a daring recruitment effort begins!', 'https://image.tmdb.org/t/p/w780/rX46P5ZwcHOvrkhtYDYhnNf46Bo.jpg', 'https://image.tmdb.org/t/p/w1280/gHLs7Fy3DzLmLsD4lmfqL55KGcl.jpg', 'https://www.youtube.com/watch?v=hIR8Ar-Z4hw', 'Joss Whedon', ARRAY['Robert Downey Jr.', 'Chris Evans', 'Mark Ruffalo', 'Chris Hemsworth', 'Scarlett Johansson', 'Jeremy Renner', 'Tom Hiddleston', 'Clark Gregg']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Hành Động', 'Phiêu Lưu']::TEXT[], 143, '2012-04-25', NULL, 'US: PG-13', 8.1, 'ended'),
  ('32167b2f-1182-5383-aefe-4a7a185cdff6'::UUID, 19995, 'Avatar', 'Avatar', 'Avatar là câu chuyện về người anh hùng “bất đắc dĩ” Jake Sully – một cựu sĩ quan thủy quân lục chiến bị liệt nửa thân. Người anh em sinh đôi của anh được chọn để tham gia vào chương trình cấy gien với người ngoài hành tinh Na’vi nhằm tạo ra một giống loài mới có thể hít thở không khí tại hành tinh Pandora. Giống người mới này được gọi là Avatar. Sau khi anh của Jake bị giết, Jake được chọn để thay thế anh mình và đã trở thành một Avatar, Jake có nhiệm vụ đi tìm hiểu và nghiên cứu hành tinh Pandora. Những thông tin mà anh thu thập được rất có giá trị cho chiến dịch xâm chiếm hành tinh xanh thứ hai này của loài người.', NULL, 'https://image.tmdb.org/t/p/w780/bxp5IUY05jLGeZ5bW85W2NF6Rgi.jpg', 'https://image.tmdb.org/t/p/w1280/vL5LR6WdxWPjLPFRLe133jXWsh5.jpg', 'https://www.youtube.com/watch?v=01PsgBXFuqA', 'James Cameron', ARRAY['Sam Worthington', 'Zoe Saldaña', 'Sigourney Weaver', 'Stephen Lang', 'Michelle Rodriguez', 'Giovanni Ribisi', 'Joel David Moore', 'CCH Pounder']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Hành Động', 'Phiêu Lưu']::TEXT[], 162, '2009-12-16', NULL, 'US: PG-13', 7.6, 'ended'),
  ('ec9c3219-2aa9-5c2c-9409-d97204171d48'::UUID, 299536, 'Avengers: Cuộc Chiến Vô Cực', 'Avengers: Infinity War', 'Sau chuyến hành trình độc nhất vô nhị không ngừng mở rộng và phát triển vụ trũ điện ảnh Marvel, bộ phim Avengers: Cuộc Chiến Vô Cực sẽ mang đến màn ảnh trận chiến cuối cùng khốc liệt nhất mọi thời đại. Biệt đội Avengers và các đồng minh siêu anh hùng của họ phải chấp nhận hy sinh tất cả để có thể chống lại kẻ thù hùng mạnh Thanos trước tham vọng hủy diệt toàn bộ vũ trụ của hắn.', NULL, 'https://image.tmdb.org/t/p/w780/8gHc1cthgTOkmMiOREodCVZgJ7P.jpg', 'https://image.tmdb.org/t/p/w1280/mDfJG3LC3Dqb67AZ52x3Z0jU0uB.jpg', 'https://www.youtube.com/watch?v=DKqu9qc-5f4', 'Joe Russo', ARRAY['Robert Downey Jr.', 'Chris Evans', 'Chris Hemsworth', 'Josh Brolin', 'Mark Ruffalo', 'Scarlett Johansson', 'Don Cheadle', 'Benedict Cumberbatch']::TEXT[], ARRAY['Phiêu Lưu', 'Hành Động', 'Khoa Học Viễn Tưởng']::TEXT[], 149, '2018-04-25', NULL, 'US: PG-13', 8.2, 'ended'),
  ('ec72323d-227e-5f73-b101-07aaeaa5688d'::UUID, 118340, 'Vệ Binh Dải Ngân Hà', 'Guardians of the Galaxy', 'Phim nói về một phi công phản lực được bị mắc kẹt trong không gian, và anh phải đoàn kết một nhóm người ngoài hành tinh để tạo thành một đội quân đủ khả năng đánh bại các mối đe dọa từ vũ trụ. Phim có sự tham gia diễn xuất của Karen Gillan, Bradley Cooper, Zoe Saldana… và sự chỉ đạo của đạo diễn James Gunn.', 'Light years from Earth, 26 years after being abducted, Peter Quill finds himself the prime target of a manhunt after discovering an orb wanted by Ronan the Accuser.', 'https://image.tmdb.org/t/p/w780/h3rZmbdQNzruZTjtuvVG7NYQuya.jpg', 'https://image.tmdb.org/t/p/w1280/uLtVbjvS1O7gXL8lUOwsFOH4man.jpg', 'https://www.youtube.com/watch?v=3CqymRQ1uUU', 'James Gunn', ARRAY['Chris Pratt', 'Zoe Saldaña', 'Dave Bautista', 'Vin Diesel', 'Bradley Cooper', 'Lee Pace', 'Michael Rooker', 'Karen Gillan']::TEXT[], ARRAY['Hành Động', 'Khoa Học Viễn Tưởng', 'Phiêu Lưu']::TEXT[], 121, '2014-07-30', NULL, 'US: PG-13', 7.9, 'ended'),
  ('d50a1495-3781-5d8a-a377-0fd5abd44ad8'::UUID, 299534, 'Avengers: Hồi Kết', 'Avengers: Endgame', 'Sau sự kiện hủy diệt tàn khốc, vũ trụ chìm trong cảnh hoang tàn. Với sự trợ giúp của những đồng minh còn sống sót, biệt đội siêu anh hùng Avengers tập hợp một lần nữa để đảo ngược hành động của Thanos và khôi phục lại trật tự của vũ trụ.', NULL, 'https://image.tmdb.org/t/p/w780/8go3YE9sBMQaCXEx23j6BAfeuxd.jpg', 'https://image.tmdb.org/t/p/w1280/7RyHsO4yDXtBv1zUU3mTpHeQ0d5.jpg', 'https://www.youtube.com/watch?v=4sZj4aeYUCA', 'Joe Russo', ARRAY['Robert Downey Jr.', 'Chris Evans', 'Mark Ruffalo', 'Chris Hemsworth', 'Scarlett Johansson', 'Jeremy Renner', 'Josh Brolin', 'Don Cheadle']::TEXT[], ARRAY['Phiêu Lưu', 'Khoa Học Viễn Tưởng', 'Hành Động']::TEXT[], 180, '2019-04-24', 'T13', 'US: PG-13', 8.2, 'ended'),
  ('376ef29c-a27c-5db9-82b7-221e6db4ccf7'::UUID, 603, 'Ma Trận', 'The Matrix', 'The Matrix (MaTrận) là bộ phim khoa học giả tưởng về tương lai. Trong tương lai đó, Thomas, biệt danh Neo, là một hacker luôn có cảm giác khác thường về thế giới thực. Cho tới khi người đàn ông tự xưng là Morpheus tìm đến anh. Người đàn ông này nói cho anh biết, thế giới mà mọi người coi là thực chỉ là một chương trình giả lập để máy móc cai trị con người. Chỉ có một người có thể phá được Ma trận. Những người thật sống sót còn lại cuối cùng và những nhân viên Ma trận đều cùng đi tìm người đó. Và người đó chính là anh – Neo…', 'Set in the 22nd century, The Matrix tells the story of a computer hacker who joins a group of underground insurgents fighting the vast and powerful computers who now rule the earth.', 'https://image.tmdb.org/t/p/w780/fE7S6EwaBgRQeqKoDVFoImMmAF4.jpg', 'https://image.tmdb.org/t/p/w1280/tlm8UkiQsitc8rSuIAscQDCnP8d.jpg', 'https://www.youtube.com/watch?v=FVI84Dfx2-I', 'Lana Wachowski', ARRAY['Keanu Reeves', 'Laurence Fishburne', 'Carrie-Anne Moss', 'Hugo Weaving', 'Gloria Foster', 'Joe Pantoliano', 'Marcus Chong', 'Julian Arahanga']::TEXT[], ARRAY['Hành Động', 'Khoa Học Viễn Tưởng']::TEXT[], 136, '1999-03-31', NULL, 'US: R', 8.3, 'ended'),
  ('8959a48e-fd79-534b-b6c6-01e3b86807f7'::UUID, 1726, 'Người Sắt', 'Iron Man', 'Tony Stark vừa là chủ tập đoàn công nghệ, vừa là một tay chơi kỳ dị. Trong chuyến thị sát Afghanistan, ông bị nhóm khủng bố bắt cóc. Chúng đòi Tony chế tạo thứ vũ khí hủy diệt để tấn công nước Mỹ.  Nhận ra sự thật phũ phàng rằng, những vũ khí do mình chế tạo đang quay ngược lại tấn công chính mình, Tony bắt tay chế tạo bộ giáp công nghệ cao. Tẩu thoát khỏi nơi giam cầm, Tony trở thành đại diện công lý dưới biệt danh Người sắt. Trong khi đó, người đồng sự trong tập đoàn Stark âm mưu lật đổ Tony.  Bộ phim mở ra câu chuyện trong tương lai về nhóm siêu anh hùng Avenger khi tổ chức bí mật SHIELD bắt đầu lộ diện.', 'After being held captive in an Afghan cave, billionaire engineer Tony Stark creates a unique weaponized suit of armor to fight evil.', 'https://image.tmdb.org/t/p/w780/qwZiKSoWFevkPSjt21zi3Mgcity.jpg', 'https://image.tmdb.org/t/p/w1280/cKvDv2LpwVEqbdXWoQl4XgGN6le.jpg', 'https://www.youtube.com/watch?v=8ugaeA-nMTc', 'Jon Favreau', ARRAY['Robert Downey Jr.', 'Terrence Howard', 'Jeff Bridges', 'Gwyneth Paltrow', 'Leslie Bibb', 'Shaun Toub', 'Faran Tahir', 'Clark Gregg']::TEXT[], ARRAY['Hành Động', 'Khoa Học Viễn Tưởng', 'Phiêu Lưu']::TEXT[], 126, '2008-04-30', 'T13', 'US: PG-13', 7.7, 'ended'),
  ('da2afb07-f0d9-5792-ade8-3068c0b9057e'::UUID, 99861, 'Avengers: Đế Chế Ultron', 'Avengers: Age of Ultron', 'Avengers: Age of Ultron tiếp nối các sự kiện xảy ra trong Captain America: The Winter Soldier ra mắt hè 2014. Kẻ thù của Biệt đội siêu anh hùng lần này là Ultron – một robot với trí tuệ nhân tạo, những năng lực siêu nhiên mạnh hơn bất kỳ ai trong The Avenger và có dã tâm chia rẽ nội bộ biệt đội nhằm thôn tính Trái Đất. Hắn được tạo ra từ phòng thí nghiệm của Tony Stark với mụ đích ban đầu là một hệ thống đặc biệt với mục đích gìn giữ hòa bình thế giới nhưng do Người Sắt sơ suất đã để mọi thứ vượt ra khỏi tầm kiểm soát, đẩy số phận của loài người lâm vào tình cảnh ngàn cân treo sợi tóc. Một lần nữa, những siêu anh hùng quả cảm - Iron Man, Captain America, Thor, The Incredible Hulk, Black Widow và Hawkeye - tiếp tục hợp tác để ngăn chặn kẻ thù. Trong hành trình bảo vệ hòa bình, nhóm kết nạp thêm hai thành viên: Wanda Maxioff và Pietro Maxioff – cặp song sinh bí hiểm và sở hữu một nguồn sức mạnh lớn lao, cũng như gặp lại một người bạn cũ trong hình dạng hoàn toàn mới có tên The Vision.', NULL, 'https://image.tmdb.org/t/p/w780/8j5ARDxYgeyuPjkwQIkcmMU8x7I.jpg', 'https://image.tmdb.org/t/p/w1280/kIBK5SKwgqIIuRKhhWrJn3XkbPq.jpg', 'https://www.youtube.com/watch?v=zDfYcNMpYjA', 'Joss Whedon', ARRAY['Robert Downey Jr.', 'Chris Hemsworth', 'Mark Ruffalo', 'Chris Evans', 'Scarlett Johansson', 'Jeremy Renner', 'James Spader', 'Samuel L. Jackson']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Khoa Học Viễn Tưởng']::TEXT[], 141, '2015-04-22', NULL, 'US: PG-13', 7.3, 'ended'),
  ('31fc6e51-056c-5664-928a-93bc01ff2f51'::UUID, 76341, 'Max Điên: Con Đường Tử Thần', 'Mad Max: Fury Road', 'Mad Max: Fury Road đưa người xem đến với một thế giới hậu tận thế điêu tàn, chỉ còn lại sa mạc và những cuộc đụng độ giữa các phiến quân. Max đang trên đường chạy trốn quá khứ đau thương vì mất vợ và con. Tình cờ, anh gặp một cô gái trẻ Furiosa với mong muốn trở về nhà. Max quyết định giúp đỡ cô, đồng nghĩa với việc trở thành kẻ thù của một băng cướp khét tiếng. Mad Max thực chất là phần 4 của loạt phim được đánh giá cao vào những năm 80, cũng được đạo diễn bởi George Miller ...', 'An apocalyptic story set in the furthest reaches of our planet, in a stark desert landscape where humanity is broken, and most everyone is crazed fighting for the necessities of life. Within this world exist two rebels on the run who just might be able to restore order.', 'https://image.tmdb.org/t/p/w780/uiNPl4ONkYC1a0hGzIFLZSGST3O.jpg', 'https://image.tmdb.org/t/p/w1280/gqrnQA6Xppdl8vIb2eJc58VC1tW.jpg', 'https://www.youtube.com/watch?v=MonFNCgK4WE', 'George Miller', ARRAY['Tom Hardy', 'Charlize Theron', 'Nicholas Hoult', 'Hugh Keays-Byrne', 'Josh Helman', 'Nathan Jones', 'Zoë Kravitz', 'Rosie Huntington-Whiteley']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Khoa Học Viễn Tưởng']::TEXT[], 120, '2015-05-13', 'T16', 'US: R', 7.6, 'ended'),
  ('3b195742-113b-5058-8ba6-41e010515043'::UUID, 271110, 'Captain America: Nội Chiến Siêu Anh Hùng', 'Captain America: Civil War', 'Captain America: Civil War (Nội Chiến Siêu Anh Hùng) xoay quanh việc Steve Rogers (Captain America) dẫn đầu một nhóm siêu anh hùng với các thành viên của Avengers với mục tiêu tiếp tục nỗ lực để bảo vệ nhân loại. Nhưng sau nhiều vụ việc xảy ra do biệt đội Avengers làm thiệt hại tài sản, chính phủ đã thiết lập cơ quan quản lý và giám sát nhóm. Điều này gây ra sự chia rẽ trong nội bộ nhóm Avengers, tạo nên hai phe đối đầu nhau. Một bên được lãnh đạo bởi Steve Rogers (Captain America) với mong muốn duy trì nhóm để thực hiện mục tiêu bảo vệ nhân loại mà không có sự can thiệp của chính phủ. Phe còn lại là của Tony Stark (Iron Man) luôn hỗ trợ giám sát và có trách nhiệm giải trình mọi việc làm với chính phủ.', 'Following the events of Age of Ultron, the collective governments of the world pass an act designed to regulate all superhuman activity. This polarizes opinion amongst the Avengers, causing two factions to side with Iron Man or Captain America, which causes an epic battle between former allies.', 'https://image.tmdb.org/t/p/w780/hDTVGIG8jsa1ZwO3wV0ccvDN4ZH.jpg', 'https://image.tmdb.org/t/p/w1280/7FWlcZq3r6525LWOcvO9kNWurN1.jpg', 'https://www.youtube.com/watch?v=dKrVegVI0Us', 'Joe Russo', ARRAY['Chris Evans', 'Robert Downey Jr.', 'Scarlett Johansson', 'Sebastian Stan', 'Anthony Mackie', 'Don Cheadle', 'Jeremy Renner', 'Chadwick Boseman']::TEXT[], ARRAY['Phiêu Lưu', 'Hành Động', 'Khoa Học Viễn Tưởng']::TEXT[], 147, '2016-04-27', NULL, 'US: PG-13', 7.5, 'ended'),
  ('84b762bb-6334-5da3-a95d-258722c83680'::UUID, 284054, 'Chiến Binh Báo Đen', 'Black Panther', 'Vương quốc Wakanda, quê hương của Black Panther/ T''Challa hiện ra qua lời kể của một nhân chứng sống sót trở về. Đây là quốc gia khá khép kín và sở hữu lượng Vibranium lớn nhất trên thế giới. Black Panther - người cầm quyền của Wakanda sở hữu bộ áo giáp chống đạn và móng vuốt sắc nhọn, anh được miêu tả là “người tốt với trái tim nhân hậu”.  Nhưng cũng chính vì những đức tính tốt này mà Black Panther gặp khó khăn khi kế thừa ngai vàng sau khi vua cha băng hà. Đối mặt với sự phản bội và hiểm nguy, vị vua trẻ phải tập hợp các đồng minh và phát huy toàn bộ sức mạnh của Black Panther để đánh bại kẻ thù, đem lại an bình cho nhân dân của mình.', NULL, 'https://image.tmdb.org/t/p/w780/9ZXDxPBesqJeQPbaA7xj0dZtClV.jpg', 'https://image.tmdb.org/t/p/w1280/b6ZJZHUdMEFECvGiDpJjlfUWela.jpg', 'https://www.youtube.com/watch?v=9OEU1LM2wtA', 'Ryan Coogler', ARRAY['Chadwick Boseman', 'Michael B. Jordan', 'Lupita Nyong''o', 'Danai Gurira', 'Martin Freeman', 'Daniel Kaluuya', 'Letitia Wright', 'Winston Duke']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Khoa Học Viễn Tưởng']::TEXT[], 135, '2018-02-13', NULL, 'US: PG-13', 7.4, 'ended'),
  ('64a082ce-6d12-587e-8442-b71c64fea2c6'::UUID, 315635, 'Người Nhện: Trở Về Nhà', 'Spider-Man: Homecoming', 'Tạm biệt hai franchise về thời sinh viên, Spider-Man: Homecoming sẽ lần đầu tiên đưa các khán giả đến với cuộc sống trung học của Peter Paker – siêu anh hùng Người Nhện. Liệu một cậu bé chưa trưởng thành sẽ làm thế nào để cân bằng cuộc sống bình thường và trách nhiệm của một anh hùng giải cứu thế giới. Đây cũng là lần đầu tiên, series Người Nhện có sự tham gia sản xuất của Marvel Studio và sự xuất hiện của Iron Man – Robert Downey Jr.', NULL, 'https://image.tmdb.org/t/p/w780/tNm6pNf9Xe1gPKu4xqPEWj0issu.jpg', 'https://image.tmdb.org/t/p/w1280/lAsr1ytUq0ATWdCbcjf59pupPFy.jpg', 'https://www.youtube.com/watch?v=O6E_45lsxBE', 'Jon Watts', ARRAY['Tom Holland', 'Michael Keaton', 'Robert Downey Jr.', 'Marisa Tomei', 'Jon Favreau', 'Gwyneth Paltrow', 'Zendaya', 'Donald Glover']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Khoa Học Viễn Tưởng']::TEXT[], 133, '2017-07-05', NULL, 'US: PG-13', 7.3, 'ended'),
  ('5897e9bf-9955-59fb-9c58-77822e0bda00'::UUID, 68721, 'Người Sắt 3', 'Iron Man 3', 'Từ sau những sự kiện và những trận chiến đầy ám ảnh trong The Avengers, Tony Stark quay về ở ẩn trong căn biệt thự sang trọng của mình, tạm thời chờ đợi trong tư cách một tỷ phú giàu có được yêu mến và gác danh phận siêu anh hùng sang một bên.  Tuy nhiên, những hiểm họa mới lại tiếp tục xuất hiện dưới bóng ma bao trùm của một quái nhân, đồng thời cũng là một thiên tài về công nghệ - The Mandarin. Người bạn thân trong lực lượng quân đội Hoa Kỳ của Tony - James Rhodes cần tới sự giúp đỡ của anh và những bộ giáp siêu việt.  Mọi chuyện không hề dễ dàng như Tony và James tưởng tượng: dưới sức mạnh thần bí của mười chiếc nhẫn vũ trụ, The Mandarin đã đánh bại "Người Sắt", đồng thời khiến siêu anh hùng - tỷ phú trở thành kẻ mất trí nhớ...', NULL, 'https://image.tmdb.org/t/p/w780/o0dmWIrF63lBPQVFdvqaWUxQ7xz.jpg', 'https://image.tmdb.org/t/p/w1280/4TSqtluelcWByj8YZdqwzQVjI0O.jpg', 'https://www.youtube.com/watch?v=AtLrrYk4JmQ', 'Shane Black', ARRAY['Robert Downey Jr.', 'Gwyneth Paltrow', 'Don Cheadle', 'Guy Pearce', 'Rebecca Hall', 'Jon Favreau', 'Ben Kingsley', 'James Badge Dale']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Khoa Học Viễn Tưởng']::TEXT[], 130, '2013-04-18', NULL, 'US: PG-13', 6.9, 'ended'),
  ('351ff629-2a8e-5dbd-bd9f-beac67c892f2'::UUID, 70160, 'Đấu Trường Sinh Tử', 'The Hunger Games', 'Phim đặt trong bối cảnh khu vực Bắc Mỹ bị hủy hoại do thiên tai và chiến tranh, cả khu vực trở thành một Panem với Capitol và 13 huyện. Mỗi năm sẽ có 24 thanh niên của 12 huyện được lựa chọn để tham gia Đấu trường sinh tử được tường thuật cho cả đất nước xem, trong đó chỉ có một người gan dạ và mưu trí nhất mới có thể sống và chiến thắng. Đây là tác phẩm hấp dẫn mang đậm triết lý “ai mạnh thì sống”, bên cạnh đó phim ca ngợi khát vọng sống, tình yêu của những người trẻ tuổi. Được giới phê bình phim đánh giá khá cao, Đấu Trường Sinh Tử đã tạo ra một cơn sốt khắp các phòng chiếu Bắc Mỹ.', 'In a dystopian society where the Capitol forces each district to send two young tributes to fight to the death in a televised spectacle, a girl volunteers to take her sister’s place, setting the stage for a struggle of survival and defiance.', 'https://image.tmdb.org/t/p/w780/tjyjVDEjFtlxsqAppVPPa6ZQ4Ye.jpg', 'https://image.tmdb.org/t/p/w1280/eVYChqJavS1DCXFeJE2lzVUMLKp.jpg', 'https://www.youtube.com/watch?v=wLGOaKY5STw', 'Gary Ross', ARRAY['Jennifer Lawrence', 'Josh Hutcherson', 'Liam Hemsworth', 'Woody Harrelson', 'Elizabeth Banks', 'Lenny Kravitz', 'Stanley Tucci', 'Donald Sutherland']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Phiêu Lưu', 'Hành Động', 'Giật Gân']::TEXT[], 142, '2012-03-12', NULL, 'US: PG-13', 7.2, 'ended'),
  ('5f941707-e434-5e85-90ad-3f6e319dd6d8'::UUID, 283995, 'Vệ Binh Dải Ngân Hà 2', 'Guardians of the Galaxy Vol. 2', 'Guardians Of The Galaxy - Vệ binh dải ngân hà Phần 2 tiếp tục câu chuyện về bộ tứ huyền thoại của thiên hà. Lần này, cả nhóm sẽ bắt đầu cuộc phiêu lưu mới nhằm tìm ra bí ẩn thân thế của Star Lord – Peter Quill và viên Power Infinity Gem sở hữu sức mạnh vô song. Nhân vật anti-hero Yondu sẽ có vai trò quan trọng hơn nữa trong phần này, bên cạnh đó cô em gái Nebula của Gamora cũng sẽ trở lại.', NULL, 'https://image.tmdb.org/t/p/w780/bqemb9J8lAfYWdNXOPoK1JkHt3x.jpg', 'https://image.tmdb.org/t/p/w1280/aJn9XeesqsrSLKcHfHP4u5985hn.jpg', 'https://www.youtube.com/watch?v=TgkvytwAO2I', 'James Gunn', ARRAY['Chris Pratt', 'Zoe Saldaña', 'Dave Bautista', 'Vin Diesel', 'Bradley Cooper', 'Kurt Russell', 'Michael Rooker', 'Karen Gillan']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Phiêu Lưu', 'Hành Động']::TEXT[], 137, '2017-04-25', NULL, 'US: PG-13', 7.6, 'ended'),
  ('fd075e55-a8de-5dd7-a62c-c949144b16f2'::UUID, 634649, 'Người Nhện: Không Còn Nhà', 'Spider-Man: No Way Home', 'Peter Parker đã bị lộ mặt và không còn có thể tách biệt cuộc sống bình thường của mình với những yêu cầu cao của việc trở thành một Siêu anh hùng. Khi anh ta yêu cầu sự giúp đỡ từ Doctor Strange, mọi thứ càng trở nên nguy hiểm hơn, buộc anh ta phải khám phá ra ý nghĩa thực sự của việc trở thành Người Nhện.', NULL, 'https://image.tmdb.org/t/p/w780/y4SQ2dJ1y2LBUnxTH7hCe8sr29c.jpg', 'https://image.tmdb.org/t/p/w1280/iQFcwSGbZXMkeyKrxbPnwnRo5fl.jpg', 'https://www.youtube.com/watch?v=o4NzWTNqSto', 'Jon Watts', ARRAY['Tom Holland', 'Zendaya', 'Benedict Cumberbatch', 'Jacob Batalon', 'Jon Favreau', 'Jamie Foxx', 'Willem Dafoe', 'Alfred Molina']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Khoa Học Viễn Tưởng']::TEXT[], 148, '2021-12-15', NULL, 'US: PG-13', 7.9, 'ended'),
  ('00c8e2f8-0ca1-55e4-9327-b61a77638fd2'::UUID, 1771, 'Captain America: Kẻ Báo Thù Đầu Tiên', 'Captain America: The First Avenger', 'Phim lấy bối cảnh từ đầu năm 1942, khi Mỹ đang tham gia Thế chiến thứ II và cần tới những chiến binh can trường. Chàng trai Steve Rogers (Chris Evans) là một người như vậy, nhưng thể hình quá thấp bé khiến anh không thể đạt được ước mơ tòng quân. Cơ may đến với Rogers khi anh được chọn tham gia một thí nghiệm của chính phủ, giúp biến người thường trở thành siêu chiến binh.  Mọi việc diễn ra suôn sẻ, biến Rogers thành một người cao to vạm vỡ, đầu óc tiếp thu mọi kỹ năng chiến đấu nhanh và vẫn giữ được trái tim nhân hậu. Anh trở thành Đội trưởng Mỹ, biểu tượng của nước Mỹ kể từ đó. Đối thủ của anh là phe Phát-xít, với quái nhân Red Skull, kẻ không chỉ quyền năng mà còn rất tàn ác.', 'During World War II, Steve Rogers is a sickly man from Brooklyn who''s transformed into super-soldier Captain America to aid in the war effort. Rogers must stop the Red Skull – Adolf Hitler''s ruthless head of weaponry, and the leader of an organization that intends to use a mysterious device of untold powers for world domination.', 'https://image.tmdb.org/t/p/w780/kky7t6NqAWmuIzuRgSldaOHgNMm.jpg', 'https://image.tmdb.org/t/p/w1280/yFuKvT4Vm3sKHdFY4eG6I4ldAnn.jpg', 'https://www.youtube.com/watch?v=W4DlMggBPvc', 'Joe Johnston', ARRAY['Chris Evans', 'Hayley Atwell', 'Sebastian Stan', 'Tommy Lee Jones', 'Hugo Weaving', 'Dominic Cooper', 'Richard Armitage', 'Stanley Tucci']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Khoa Học Viễn Tưởng']::TEXT[], 124, '2011-07-22', NULL, 'US: PG-13', 7, 'ended'),
  ('551898c1-d209-55a4-8df9-006de36ee5bf'::UUID, 10138, 'Người Sắt 2', 'Iron Man 2', 'Tony Stark tự hé lộ thân phận Người sắt của mình cho công chúng và chìm trong hào quang danh vọng. Một kẻ lạ mặt xuất hiện tấn công anh trên đường đua Monte Carlo. Tony bị hiện tượng nhiễm trùng máu đe dọa mạng sống, còn tên sát thủ kia bắt tay với đối thủ của tập đoàn Stark hòng thôn tính Tony.  Phần 2 của Người sắt là lần đầu tiên trợ thủ Warmachine xuất hiện. Phim cũng tiết lộ những bí mật về cha của Tony, Howard Stark, trước khi dẫn dắt câu chuyện sang nhân vật Captain America, đồng đội tương lai của Người sắt tại tổ chức SHIELD.', 'With the world now aware of his dual life as the armored superhero Iron Man, billionaire inventor Tony Stark faces pressure from the government, the press and the public to share his technology with the military. Unwilling to let go of his invention, Stark, with Pepper Potts and James ''Rhodey'' Rhodes at his side, must forge new alliances – and confront powerful enemies.', 'https://image.tmdb.org/t/p/w780/q9L8fMYW4dBQOdDAfbbxte7gciJ.jpg', 'https://image.tmdb.org/t/p/w1280/7lmBufEG7P7Y1HClYK3gCxYrkgS.jpg', 'https://www.youtube.com/watch?v=5fUQkLdJ2kE', 'Jon Favreau', ARRAY['Robert Downey Jr.', 'Gwyneth Paltrow', 'Don Cheadle', 'Scarlett Johansson', 'Sam Rockwell', 'Mickey Rourke', 'Samuel L. Jackson', 'Clark Gregg']::TEXT[], ARRAY['Phiêu Lưu', 'Hành Động', 'Khoa Học Viễn Tưởng']::TEXT[], 124, '2010-04-28', NULL, 'US: PG-13', 6.9, 'ended'),
  ('e612241c-66aa-5f3b-b1ca-16ab0b95a53f'::UUID, 11, 'Chiến Tranh Giữa Các Vì Sao: Phần IV - Niềm Hy Vọng Mới', 'Star Wars', 'Luke Skywalker sống trên một trang trại ở hành tinh Tatooine bụi bặm cùng với cô và chú của anh. Luke là một thanh niên gan dạ và rất nóng lòng được trở thành một chiến binh nổi lọan. Lúc này, tên Darth Vader tàn bạo đã thôn tính cả thiên hà và đang hoàn thành một vũ khí hủy diệt khủng khiếp, Death Star. Công chúa Leia, người dẫn đầu phong trào nổi lọan, biết được kế họach này và tìm cách báo cho Obi-Wan Kenobi, một nhà tu hành già nua sống ẩn dật có sức mạnh phi thường. Vô tình tìm thấy mẩu tin báo nguy của công chúa dấu trong người máy R2D2, Luke lên đường tìm kiếm Obi-Wan Kenobi để hợp sức cùng nhau cứu công chúa cũng như giải thóat cả thiên hà...', 'Princess Leia is captured and held hostage by the evil Imperial forces in their effort to take over the galactic Empire. Venturesome Luke Skywalker and dashing captain Han Solo team together with the loveable robot duo R2-D2 and C-3PO to rescue the beautiful princess and restore peace and justice in the Empire.', 'https://image.tmdb.org/t/p/w780/fai0rspsNeJCS69wHNjOdWxcI7P.jpg', 'https://image.tmdb.org/t/p/w1280/zqkmTXzjkAgXmEWLRsY4UpTWCeo.jpg', 'https://www.youtube.com/watch?v=i-vsILeJ8_8', 'George Lucas', ARRAY['Mark Hamill', 'Harrison Ford', 'Carrie Fisher', 'Peter Cushing', 'Alec Guinness', 'Anthony Daniels', 'Kenny Baker', 'Peter Mayhew']::TEXT[], ARRAY['Phiêu Lưu', 'Hành Động', 'Khoa Học Viễn Tưởng']::TEXT[], 121, '1977-05-25', NULL, 'US: PG', 8.2, 'ended'),
  ('6d7fa5ff-d50b-5599-a734-c49be2de8fb6'::UUID, 284053, 'Thor: Tận Thế Ragnarok', 'Thor: Ragnarok', 'Ở bên kia vũ trụ, Thor (Chris Hemsworth) phải bước vào một cuộc chiến đầy khốc liệt với đối thủ mà anh sẽ gặp là một đồng đội cũ đến từ biệt đội Avenger – Hulk. Cuộc tìm kiếm sự sống còn của Thor khiến anh phải chạy đua với thời gian để ngăn chặn Hela (Cate Blanchett) tiêu diệt cả thế giới anh đang sống cùng nền văn minh Asgard.', NULL, 'https://image.tmdb.org/t/p/w780/3qkUzHe7MdNXfInMRtIogP8K82e.jpg', 'https://image.tmdb.org/t/p/w1280/vLmHH8jAy8Jq8uBsLucd3592WGh.jpg', 'https://www.youtube.com/watch?v=MW6oP4M9OuA', 'Taika Waititi', ARRAY['Chris Hemsworth', 'Mark Ruffalo', 'Tom Hiddleston', 'Cate Blanchett', 'Idris Elba', 'Jeff Goldblum', 'Tessa Thompson', 'Karl Urban']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Hài', 'Khoa Học Viễn Tưởng']::TEXT[], 131, '2017-10-24', NULL, 'US: PG-13', 7.6, 'ended'),
  ('888f7666-939e-5eb4-9b04-ba63f62c24ad'::UUID, 105, 'Trở Về Tương Lai', 'Back to the Future', 'Nhà phát minh lập dị Tiến sĩ Brown biến chiếc DeLorean thành cỗ máy thời gian. Cỗ máy này vô tình đưa người bạn trẻ của ông – Marty McFly – trở về quá khứ 30 năm trước.', 'Eighties teenager Marty McFly is accidentally sent back in time to 1955, inadvertently disrupting his parents'' first meeting and attracting his mother''s romantic interest. Marty must repair the damage to history by rekindling his parents'' romance and - with the help of his eccentric inventor friend Doc Brown - return to 1985.', 'https://image.tmdb.org/t/p/w780/d8O1txQtDobdenlyL7uArsRezdj.jpg', 'https://image.tmdb.org/t/p/w1280/5bzPWQ2dFUl2aZKkp7ILJVVkRed.jpg', 'https://www.youtube.com/watch?v=ez6WQ7IX72U', 'Robert Zemeckis', ARRAY['Michael J. Fox', 'Christopher Lloyd', 'Crispin Glover', 'Lea Thompson', 'Claudia Wells', 'Thomas F. Wilson', 'Marc McClure', 'Wendie Jo Sperber']::TEXT[], ARRAY['Phiêu Lưu', 'Hài', 'Khoa Học Viễn Tưởng']::TEXT[], 116, '1985-07-03', NULL, 'US: PG', 8.3, 'ended'),
  ('d8da1138-1122-5334-a0f8-91387404efce'::UUID, 135397, 'Thế Giới Khủng Long', 'Jurassic World', 'Trong Jurassic World (Thế giới khủng long), lấy bối cảnh 22 năm sau sự kiện ở Công viên kỷ Jura phần 3. Công viên kỷ Jura ngày nào giờ đã trở thành công viên Khủng long thật sự. Tuy nhiên, khu tham quan này lại rất vắng khách, vì người dân không còn chuộng những con quái vật cổ đại nữa. Để thu hút khách trở lại, tập đoàn sở hữu Masrani quyết định lai tạo ra một loài khủng long mới, nhưng điều đó nhanh chóng dẫn đến thảm họa. Jurassic World sẽ là bộ phim bom tấn đầy hứa hẹn tiếp theo của “Star Lord” Chris Pratt, nam diễn viên đã ghi dấu ấn đậm nét trong Guardian of Galaxy vào năm ngoái.', 'Twenty-two years after the events of Jurassic Park, Isla Nublar now features a fully functioning dinosaur theme park, Jurassic World, as originally envisioned by John Hammond.', 'https://image.tmdb.org/t/p/w780/g1ZJCfuSCWaCzgiUtGXkyCmvHpM.jpg', 'https://image.tmdb.org/t/p/w1280/dF6FjTZzRTENfB4R17HDN20jLT2.jpg', 'https://www.youtube.com/watch?v=aJJrkyHas78', 'Colin Trevorrow', ARRAY['Chris Pratt', 'Bryce Dallas Howard', 'Irrfan Khan', 'Vincent D''Onofrio', 'Ty Simpkins', 'Nick Robinson', 'Jake Johnson', 'Omar Sy']::TEXT[], ARRAY['Phiêu Lưu', 'Khoa Học Viễn Tưởng', 'Giật Gân']::TEXT[], 195, '2015-06-06', NULL, 'US: PG-13', 6.7, 'ended'),
  ('4483e5de-175c-5497-83e9-69ac03cdc12f'::UUID, 286217, 'Người Về Từ Sao Hỏa', 'The Martian', 'The Martian xoay quanh hành trình trở về đầy phi thường của phi hành gia Mark Watney. Trong quá trình thực hiện nhiệm vụ trên sao Hỏa, Mark Watney (Matt Damon) được cho rằng đã tử nạn sau một trận bão lớn và bị mọi người bỏ lại phía sau.  Tuy nhiên, Watney may mắn sống sót và bị mắc kẹt một mình trên hành tinh cằn cỗi. Anh sẽ phải sử dụng tất cả kinh nghiệm và kiến thức của mình để tiếp tục tồn tại trên một hành tinh không có sự sống và hi vọng một ngày sẽ được cứu thoát. Quan trọng hơn cả, Watney luôn giữ cho mình một nghị lực kiên cường và tinh thần thật lạc quan. Mặc dù cách xa đến hàng triệu dặm, NASA và các nhà khoa học quốc tế vẫn làm việc không mệt mỏi để có thể đưa Watney trở về an toàn.', 'During a manned mission to Mars, Astronaut Mark Watney is presumed dead after a fierce storm and left behind by his crew. But Watney has survived and finds himself stranded and alone on the hostile planet. With only meager supplies, he must draw upon his ingenuity, wit and spirit to subsist and find a way to signal to Earth that he is alive.', 'https://image.tmdb.org/t/p/w780/73WiP7qwfrBWEcFsarDSe6S692q.jpg', 'https://image.tmdb.org/t/p/w1280/lzMS0CI3FLQYC5EgJoWeIaEt0lm.jpg', 'https://www.youtube.com/watch?v=ej3ioOneTy8', 'Ridley Scott', ARRAY['Matt Damon', 'Jessica Chastain', 'Kristen Wiig', 'Jeff Daniels', 'Michael Peña', 'Sean Bean', 'Kate Mara', 'Sebastian Stan']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Chính Kịch', 'Phiêu Lưu']::TEXT[], 141, '2015-09-30', NULL, 'US: PG-13', 7.7, 'ended'),
  ('68cfd40e-1384-5777-ad85-9dcc46f58981'::UUID, 557, 'Người Nhện', 'Spider-Man', 'Peter Parker là một sinh viên trẻ và nhút nhát, đã sống với dì May và chú Ben kể từ khi cha mẹ anh ta mất khi anh ta còn rất nhỏ. Peter yêu người hàng xóm xinh đẹp của mình, nhưng sự thiếu lôi cuốn của anh ta không khiến anh ta trở nên nổi tiếng ở trường trung học. Một ngày nọ, anh ta bị cắn bởi một con nhện đã bị biến đổi gen, phát hiện ra ngày hôm sau anh ta sở hữu sức mạnh khác thường: anh ta có sức mạnh và sự nhanh nhẹn của một con nhện. Cuộc phiêu lưu của Người Nhện, dựa trên truyện tranh nổi tiếng Stan Lee và Steve Ditko, đã càn quét phòng vé Mỹ và phá vỡ kỷ lục phá vỡ kỷ lục vào cuối tuần đầu tiên của anh: 114 triệu đô la, lần đầu tiên trong lịch sử, anh tìm cách phá vỡ Rào cản 100 triệu đô la vào một ngày cuối tuần bình thường.', 'After being bitten by a genetically altered spider at Oscorp, nerdy but endearing high school student Peter Parker is endowed with amazing powers to become the superhero known as Spider-Man.', 'https://image.tmdb.org/t/p/w780/w55KSeyhH3nXjzx7AhbNq0DO3zt.jpg', 'https://image.tmdb.org/t/p/w1280/zQ8AxTPiCiS5nnwXpwTBPBHSaa5.jpg', 'https://www.youtube.com/watch?v=t06RUxPbp_c', 'Sam Raimi', ARRAY['Tobey Maguire', 'Willem Dafoe', 'Kirsten Dunst', 'James Franco', 'Cliff Robertson', 'Rosemary Harris', 'J.K. Simmons', 'Joe Manganiello']::TEXT[], ARRAY['Hành Động', 'Khoa Học Viễn Tưởng']::TEXT[], 193, '2002-05-01', NULL, 'US: PG-13', 7.4, 'ended'),
  ('aff41044-f418-592f-b44a-d3167eefb107'::UUID, 102899, 'Ant-Man: Người Kiến', 'Ant-Man', 'Câu chuyện bắt đầu từ giáo sư Hank Pym (Michael Douglas thủ vai), Người Kiến đầu tiên với phát minh vĩ đại là bộ giáp biến đổi kích cỡ con người. Không chỉ thu nhỏ cơ thể để chiến đấu linh hoạt, bộ giáp siêu hạng còn đem lại những năng lực đặc biệt như trò chuyện với kiến, di chuyển với tốc độ nhanh. Nhưng thật không may, công nghệ tạo ra bộ giáp đã bị Darren Cross (Yellowjacket) chiếm đoạt và đưa vào sản xuất hàng loạt. Tất nhiên, “nếu trao quyền năng của Thượng đế cho tất cả mọi người thì thế giới này sẽ trở nên hỗn loạn”. Để ngăn chặn mối nguy hại đến từ Yellowjacket, giáo sư Hank Pym cùng trợ thủ Hope van Dyne (Evangeline Lilly thủ vai) đã tìm đến Scott Lang – một tên trộm vặt lừng danh từng vào tù ra tội, để nhờ anh lấy lại công nghệ đặc biệt và ngăn chặn Yellowjacket. Scott đã trở thành Người Kiến tiếp theo, bắt đầu làm quen với việc điều khiển bộ giáp và sử dụng các siêu năng lực đặc biệt.', 'Armed with the astonishing ability to shrink in scale but increase in strength, master thief Scott Lang must embrace his inner-hero and help his mentor, Doctor Hank Pym, protect the secret behind his spectacular Ant-Man suit from a new generation of towering threats. Against seemingly insurmountable obstacles, Pym and Lang must plan and pull off a heist that will save the world.', 'https://image.tmdb.org/t/p/w780/oVZIVwOXZuZ28xLhsGlY0LlfP41.jpg', 'https://image.tmdb.org/t/p/w1280/1K3JmSNUN8OpjYsCjc0Hy0SYxAb.jpg', 'https://www.youtube.com/watch?v=cx3joJnXydc', 'Peyton Reed', ARRAY['Paul Rudd', 'Michael Douglas', 'Evangeline Lilly', 'Corey Stoll', 'Bobby Cannavale', 'Anthony Mackie', 'Judy Greer', 'Abby Ryder Fortson']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Phiêu Lưu', 'Hành Động']::TEXT[], 117, '2015-07-14', NULL, 'US: PG-13', 7.1, 'ended'),
  ('c3bb5489-5a5e-5123-9eab-1161a1ab4425'::UUID, 10681, 'Robot Biết Yêu', 'WALL·E', 'Trong tương lai, trái đất bị bao phủ bởi rác thải, loài người buộc phải rời khỏi trái đất và thay thế vào đó là hàng triệu con rô-bốt nhỏ bé với nhiệm vụ thu dọn rác thải cho đến khi trái đất có thể ở được.  Nhưng chương trình đó thất bại chỉ trừ một chú robot nhỏ bé vẫn chăm chỉ làm công việc của mình, đó chính là WALL-E – robot duy nhất bị bỏ lại trên trái đất bắt đầu có một lỗi nhỏ trong hệ thống: phát triển tính cách của con người. WALL-E lãng mạn mơ ước rằng một ngày cậu sẽ kết giao được với ai đó, và cuộc đời này hẳn còn nhiều điều thú vị hơn công việc buồn tẻ mà cậu làm hàng ngày.  Thế rồi EVE xuất hiện. EVE là cô người máy thăm dò có kiểu dáng đẹp, nhanh nhẹn, có thể bay và được trang bị súng laser. EVE thuộc hạm đội người máy được Phi trưởng của tàu Axiom cử xuống trái đất để làm nhiệm vụ kiểm tra bí mật. Theo đuổi EVE, WALL-E không thể ngờ rằng cậu sẽ vượt qua dải ngân hà và bước vào một chuyến phiêu lưu kỳ thú vượt xa sự tưởng tượng của chính mình.', 'After hundreds of years doing what he was built for, WALL•E— a robot designed to clean up the earth—discovers a new purpose in life when he meets a sleek search robot named EVE. EVE comes to realize that WALL•E has inadvertently stumbled upon the key to the planet''s future, and races back to space to report to the humans. Meanwhile, WALL•E chases EVE across the galaxy and sets into motion one of the most imaginative adventures ever brought to the big screen.', 'https://image.tmdb.org/t/p/w780/jNPu8FFumN2gTdUn4Np4kFVobtU.jpg', 'https://image.tmdb.org/t/p/w1280/nYs4ZwnJBK4AgljhvzwNz7fpr3E.jpg', 'https://www.youtube.com/watch?v=geplBr2fcZc', 'Andrew Stanton', ARRAY['Ben Burtt', 'Elissa Knight', 'Jeff Garlin', 'Fred Willard', 'John Ratzenberger', 'Kathy Najimy', 'Sigourney Weaver', 'Lori Alan']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Khoa Học Viễn Tưởng']::TEXT[], 98, '2008-06-26', NULL, 'US: G', 8.1, 'ended'),
  ('60aab505-c018-51fa-b0ae-b571936f1021'::UUID, 140607, 'Chiến Tranh Giữa Các Vì Sao: Phần VII - Thần Lực Thức Tỉnh', 'Star Wars: The Force Awakens', '“Chiến tranh giữa các vì sao: Thần lực thức tỉnh” tiếp tục cho câu chuyện của 30 năm sau khi đánh bại Darth Vader và Empire. Cô nàng Rey – một người nhặt rác từ hành tinh Jakku- tìm thấy một droid BB-8, cô giữ BB-8 như thể nó là của mình. Rey vô tình phát hiện ra cỗ máy cất giữ bản đồ nơi ở của Luke Skywalker – chiến binh cuối cùng đã mất tích từ lâu.  Finn – một stormtrooper FN-2187 may mắn sống sót sau một cuộc tấn công- đã đến gặp Rey và BB-8 với ý định giúp đỡ họ. Tuy nhiên, ba người bị tấn công bất ngờ bởi Tổ chức thứ nhất, buộc phải chạy trốn khỏi hành tinh bằng một chiếc phi đang đậu gần đó. Họ không hay biết chiếc phi thuyền mà mình đang sử dụng có ý nghĩa vô cùng đặc biệt. Đương nhiên họ cũng không hoàn toàn hay biết, có một người anh hùng đang ở trong bóng tối hỗ trợ họ.', 'Thirty years after defeating the Galactic Empire, Han Solo and his allies face a new threat from the evil Kylo Ren and his army of Stormtroopers.', 'https://image.tmdb.org/t/p/w780/gXd5rJFOjMY8z7fyTU6dDqthKlw.jpg', 'https://image.tmdb.org/t/p/w1280/8BTsTfln4jlQrLXUBquXJ0ASQy9.jpg', 'https://www.youtube.com/watch?v=sGbxmsDFVnE', 'J.J. Abrams', ARRAY['Daisy Ridley', 'John Boyega', 'Oscar Isaac', 'Adam Driver', 'Carrie Fisher', 'Harrison Ford', 'Mark Hamill', 'Lupita Nyong''o']::TEXT[], ARRAY['Phiêu Lưu', 'Hành Động', 'Khoa Học Viễn Tưởng']::TEXT[], 136, '2015-12-15', NULL, 'US: PG-13', 7.2, 'ended'),
  ('215a4613-a1dc-5e1a-b998-febec6265ef7'::UUID, 263115, 'X-Men:  Logan - Trận Chiến Cuối Cùng', 'Logan', 'Lấy bối cảnh năm 2029, giống loài dị nhân gần như bị tuyệt diệt. Wolverine lúc này phải đối mặt với sự lão hóa cả về thể chất lẫn khả năng phục hồi. Anh cùng với Giáo sư X, người lúc này đang mắc chứng bệnh Alzheimer, phải hợp sức để bảo vệ cô bé dị nhân Laura Kinney. Đối chọi với một đội quân ác nhân mạnh mẽ do Donald Pierce dẫn đầu và một tổ chức khổng lồ bí ẩn ở phía sau, liệu họ có bảo toàn được tính mạng và viết tiếp câu chuyện của mình ...', NULL, 'https://image.tmdb.org/t/p/w780/rDu3wdpvK6oUr1qDr63FlvQt3Nb.jpg', 'https://image.tmdb.org/t/p/w1280/4DZxWNSAyksN6N3JkvpJ53Yq6zU.jpg', 'https://www.youtube.com/watch?v=KXLWiQ_UEH4', 'James Mangold', ARRAY['Hugh Jackman', 'Dafne Keen', 'Patrick Stewart', 'Elizabeth Rodriguez', 'Boyd Holbrook', 'Stephen Merchant', 'Richard E. Grant', 'Stephen Dunlevy']::TEXT[], ARRAY['Hành Động', 'Chính Kịch', 'Khoa Học Viễn Tưởng']::TEXT[], 137, '2017-02-28', NULL, 'US: R', 7.8, 'ended'),
  ('e90b3d89-1eff-57ed-9723-40d772325954'::UUID, 100402, 'Captain America: Chiến Binh Mùa Đông', 'Captain America: The Winter Soldier', 'Nội dung phim Captain America: Chiến Binh Mùa Đông là câu chuyện tiếp nối bộ phim The Avengers, khi Steve Rogers phải tìm cách hòa nhập vào thế giới hiện đại và kết hợp với Natasha Romanoff/Black Widow để chiến đấu chống lại một kẻ thù nguy hiểm ở Washington, D.C. Sau cuộc chiến cùng đội The Avengers tại New York, Captain America (hay còn gọi là Steve Rogers) có một cuộc sống khá thầm lặng tại Washington và anh phải vật lộn để thích nghi với cuộc sống ở thế giới hiện đại. Tuy nhiên, khi một người bạn trong SHIELD bị rơi vào vòng nguy hiểm, anh đã bị kéo vào một âm mưu đen tối có thể phá hủy cả nhân loại. Trong phim này, cùng với Black Widow, anh phải ngăn cản âm mưu này đồng thời chiến đấu chống lại nhừng sát thủ chuyên nghiệp được cử tới để thủ tiêu mình. Cặp đôi Captain, Black Widow còn tranh thủ sự giúp đỡ từ người bạn mới, Falcon. Tuy nhiên, một kẻ thù vô cùng nguy hiểm và bí ẩn lúc này lại xuất hiện.', 'After the cataclysmic events in New York with The Avengers, Steve Rogers, aka Captain America is living quietly in Washington, D.C. and trying to adjust to the modern world. But when a S.H.I.E.L.D. colleague comes under attack, Steve becomes embroiled in a web of intrigue that threatens to put the world at risk. Joining forces with the Black Widow, Captain America struggles to expose the ever-widening conspiracy while fighting off professional assassins sent to silence him at every turn. When the full scope of the villainous plot is revealed, Captain America and the Black Widow enlist the help of a new ally, the Falcon. However, they soon find themselves up against an unexpected and formidable enemy—the Winter Soldier.', 'https://image.tmdb.org/t/p/w780/tJYTF29bziPwmjjBVHWsvqvcehb.jpg', 'https://image.tmdb.org/t/p/w1280/jJvrPQAHFKmz4pVano4UtWTsRgA.jpg', 'https://www.youtube.com/watch?v=7SlILk2WMTI', 'Joe Russo', ARRAY['Chris Evans', 'Samuel L. Jackson', 'Scarlett Johansson', 'Robert Redford', 'Sebastian Stan', 'Anthony Mackie', 'Cobie Smulders', 'Frank Grillo']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Khoa Học Viễn Tưởng']::TEXT[], 136, '2014-03-20', NULL, 'US: PG-13', 7.7, 'ended'),
  ('a1f69056-b065-56a9-9176-7e57ab222262'::UUID, 329865, 'Cuộc Đổ Bộ Bí Ẩn', 'Arrival', 'Khi một phi thuyền bí ẩn đáp xuống trái đất, một biệt đội tinh anh dưới sự dẫn dắt của chuyên gia ngôn ngữ học kiệt xuất Louise Banks được đưa đến để điều tra. Louise và các đồng đội phải chạy đua với thời gian để tìm câu trả lời cho nhiều bí ẩn. Để rồi, trong quá trình tìm kiếm, cô phát hiện những điều có thể đe dọa cuộc sống của cô và sự tồn tại của cả nhân loại.', 'Taking place after alien crafts land around the world, an expert linguist is recruited by the military to determine whether they come in peace or are a threat.', 'https://image.tmdb.org/t/p/w780/fNfK7FuicJdRou0ac5jfVEFA0dd.jpg', 'https://image.tmdb.org/t/p/w1280/8MUZz7oPXQftFTslZpRP3CVMOoq.jpg', 'https://www.youtube.com/watch?v=7W1m5ER3I1Y', 'Denis Villeneuve', ARRAY['Amy Adams', 'Jeremy Renner', 'Forest Whitaker', 'Michael Stuhlbarg', 'Mark O''Brien', 'Mã Thái', 'Abigail Pniowsky', 'Julia Scarlett Dan']::TEXT[], ARRAY['Chính Kịch', 'Khoa Học Viễn Tưởng', 'Bí Ẩn']::TEXT[], 116, '2016-11-10', NULL, 'US: PG-13', 7.6, 'ended'),
  ('4c6fe5a6-ac9b-5b9f-b49a-87d3868d2918'::UUID, 1930, 'Người Nhện Siêu Đẳng', 'The Amazing Spider-Man', 'Amazing Spider-Man hay Siêu Nhện Tái Xuất có khá nhiều khác biệt so với các phần trước tập trung ở sự khác biệt ở tính cách của các nhân vật, Peter không còn là cậu bé nhút nhát mà khá nghịch ngợm, bên cạnh đó đạo diễn Marc Webb cũng mạnh dạn đưa ra thêm nhiều thay đổi về cốt truyện để Amazing Spider-Man thực sự mới lạ so với các phiên bản cũ.  Cha mẹ Peter biến mất bí ấn và để cậu cho cô chú nuôi nấng. Sự tò mò về thân phận của bản thân lẫn những điều chưa biết về cha mẹ luôn thôi thúc cậu.  Peter tìm thấy tập tài liệu mà cha để lại. Từ đây, những manh mối dẫn cậu tới tập đoàn Oscorp và người cộng sự của ông. Một tai nạn tại Oscorp khiến Peter có những siêu năng lực của loài nhện, Người nhện xuất hiện bí ẩn trong lòng New York.', 'A teenage Peter Parker grapples with both high school and amazing super-human crises as his alter-ego Spider-Man.', 'https://image.tmdb.org/t/p/w780/5ObdzkfZBV3b9fcF5IISMPPknxv.jpg', 'https://image.tmdb.org/t/p/w1280/sxskOU71CO8LaNX2LOtjYFUtKv7.jpg', 'https://www.youtube.com/watch?v=WLxul0Vzuhk', 'Marc Webb', ARRAY['Andrew Garfield', 'Emma Stone', 'Rhys Ifans', 'Denis Leary', 'Martin Sheen', 'Sally Field', 'Irrfan Khan', 'Campbell Scott']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Khoa Học Viễn Tưởng']::TEXT[], 136, '2012-06-23', NULL, 'US: PG-13', 6.8, 'ended'),
  ('8e3a8ca6-fec5-5887-97c3-8a0c33113974'::UUID, 1891, 'Chiến Tranh Giữa Các Vì Sao: Phần V - Đế Chế Phản Công', 'The Empire Strikes Back', 'Trước sự truy đuổi gắt gao của quân đội đế quốc, lực lượng nổi loạn phải đến lánh nạn ở hành tinh Hoth băng giá. Nhưng ngay cả ở nơi hẻo lánh này, họ vẫn không thoát khỏi nanh vuốt của tên Dath Vader tàn ác. Hắn tổ chức những đợt tấn công dồn dập vào căn cứ của phe nổi loạn với những vũ khí tối tân nhất. Phá được vòng vây, Han Solo, Công chúa Leia và Chewbacca chạy trốn đến hành tinh Bespin...', 'The epic saga continues as Luke Skywalker, in hopes of defeating the evil Galactic Empire, learns the ways of the Jedi from aging master Yoda. But Darth Vader is more determined than ever to capture Luke. Meanwhile, rebel leader Princess Leia, cocky Han Solo, Chewbacca, and droids C-3PO and R2-D2 are thrown into various stages of capture, betrayal and despair.', 'https://image.tmdb.org/t/p/w780/nNAeTmF4CtdSgMDplXTDPOpYzsX.jpg', 'https://image.tmdb.org/t/p/w1280/k9pshruhCpJAdH9RaGJO6jaWQ4X.jpg', 'https://www.youtube.com/watch?v=vU6L3jXt2r8', 'Irvin Kershner', ARRAY['Mark Hamill', 'Harrison Ford', 'Carrie Fisher', 'Billy Dee Williams', 'Anthony Daniels', 'David Prowse', 'Peter Mayhew', 'Kenny Baker']::TEXT[], ARRAY['Phiêu Lưu', 'Hành Động', 'Khoa Học Viễn Tưởng']::TEXT[], 124, '1980-05-20', NULL, 'US: PG', 8.4, 'ended'),
  ('faf07ccb-021f-5885-a48d-ff02c9725cc9'::UUID, 101299, 'Đấu Trường Sinh Tử: Bắt Lửa', 'The Hunger Games: Catching Fire', 'Đấu Trường Sinh Tử: Bắt Lửa là tập phim thứ hai trong loạt phim với những sự kiện nối tiếp các diễn biến trong phần một. Chiến thắng Katniss Everdeen và Peeta Mellark tại Đấu trường sinh tử lần 74 thổi bùng lên cuộc nổi loạn tại các quận của Panem. Điều đó khiến họ trở thành mục tiêu săn đuổi của Capitol. Phim lấy bối cảnh tương lai không xa khi Bắc Mỹ bị đe dọa bởi hạn hán, hỏa hoạn, đói kém và đặt ra giả thuyết khi đó chiến tranh được thay thế bằng một trò chơi săn người. Mỗi năm, các quận cử ra đại diện tham dự cuộc đấu một mất một còn để làm trò giải khuây cho các thế lực giàu có. Trò chơi khát máu này được xây dựng như một show truyền hình thực tế truyền đi khắp nơi.', 'After surviving the Hunger Games, Katniss and Peeta struggle with the consequences of their victory as unrest spreads across Panem. Forced back into the spotlight, they become symbols of hope and resistance while the Capitol prepares a new and deadly challenge that will change the future of the nation forever.', 'https://image.tmdb.org/t/p/w780/x2LjrOo76gA1HWd4NlSd9nOeB1t.jpg', 'https://image.tmdb.org/t/p/w1280/eHaazLxM5LRMh0ySkVy7SK6wUWt.jpg', 'https://www.youtube.com/watch?v=zoKj7TdJk98', 'Francis Lawrence', ARRAY['Jennifer Lawrence', 'Josh Hutcherson', 'Liam Hemsworth', 'Woody Harrelson', 'Elizabeth Banks', 'Donald Sutherland', 'Lenny Kravitz', 'Philip Seymour Hoffman']::TEXT[], ARRAY['Phiêu Lưu', 'Hành Động', 'Khoa Học Viễn Tưởng']::TEXT[], 146, '2013-11-15', NULL, 'US: PG-13', 7.4, 'ended'),
  ('71dffb21-2bc9-5fb8-8734-1d245e63052a'::UUID, 198663, 'Giải Mã Mê Cung', 'The Maze Runner', 'The Maze Runner là bộ phim được chuyển thể từ bộ truyện cùng tên có nội dung giả tưởng về nhóm bạn trẻ bị giam giữ trong ''Trảng'' với một trí nhớ không rõ ràng, và cuộc vật lộn tìm lối thoát. Làm thế nào họ sống sót được giữa một mê cung khổng lồ đầy những sinh vật nguy hiểm và thay đổi lời giải hằng đêm? Ai sẽ là người sống sót cuối cùng sau những bí mật chết người kia?', NULL, 'https://image.tmdb.org/t/p/w780/xSPITZs1i89L2DzHjOxp311Mxr9.jpg', 'https://image.tmdb.org/t/p/w1280/eTlcNXGv32zkVI7ZDHhfeaKHXKQ.jpg', 'https://www.youtube.com/watch?v=VSTVtW5yncM', 'Wes Ball', ARRAY['Dylan O''Brien', 'Kaya Scodelario', 'Thomas Brodie-Sangster', 'Ki Hong Lee', 'Will Poulter', 'Aml Ameen', 'Patricia Clarkson', 'Blake Cooper']::TEXT[], ARRAY['Hành Động', 'Bí Ẩn', 'Khoa Học Viễn Tưởng', 'Giật Gân']::TEXT[], 113, '2014-09-10', NULL, 'US: PG-13', 7.2, 'ended'),
  ('61b5e6ba-91b8-52a0-a9f8-08d40977ec12'::UUID, 329, 'Công Viên Kỷ Jura', 'Jurassic Park', 'Mong muốn tái sinh những loài Khủng Long, nhà tài phiệt John Hammond đã xây dựng trung tâm nghiên cứu trên một hòn đảo bí mật và những chú Khủng Long lần lượt ra đời. Vui mừng trước thành quả đạt được, John mời nhóm các nhà khoa học tới chiêm ngưỡng thành quả của mình nhưng thật không may trong đêm mưa bão hệ thống bảo vệ gặp trục trặc, hàng trăm con Khủng Long đã thoát ra ngoài...', 'A wealthy entrepreneur secretly creates a theme park featuring living dinosaurs drawn from prehistoric DNA. Before opening day, he invites a team of experts and his two eager grandchildren to experience the park and help calm anxious investors. However, the park is anything but amusing as the security systems go off-line and the dinosaurs escape.', 'https://image.tmdb.org/t/p/w780/jzHYQ7bAWQswOEBRfkKwPg03QFP.jpg', 'https://image.tmdb.org/t/p/w1280/4SyDTF02R5BepqSdQmOaNCHObzF.jpg', 'https://www.youtube.com/watch?v=Rz_FvTXa_qY', 'Steven Spielberg', ARRAY['Sam Neill', 'Laura Dern', 'Jeff Goldblum', 'Richard Attenborough', 'Bob Peck', 'Martin Ferrero', 'BD Wong', 'Joseph Mazzello']::TEXT[], ARRAY['Phiêu Lưu', 'Khoa Học Viễn Tưởng']::TEXT[], 127, '1993-06-11', NULL, 'US: PG-13', 8, 'ended'),
  ('7265e6a5-eb61-58d8-ac2f-d3218327aa7f'::UUID, 1124, 'Ảo Thuật Gia Đấu Trí', 'The Prestige', 'The Prestige xoay quanh hai ảo thuật gia đại tài là Robert Angier (Hugh Jackman) và Alfred Borden (Christian Bale). Ban đầu họ là những người bạn, thế nhưng bởi giấc mơ tạo ra tiết mục hấp dẫn nhất quá lớn, khiến họ đã bị cuốn vào một cuộc cạnh tranh một mất một còn với kết cục bi thảm.  Cũng mang đậm dấu ấn như bao phim khác của Christopher Nolan, The Prestige có kết cấu tương đối phức tạp. Cách kể chuyện không theo trình tự thời gian dẫn đến có đôi chỗ người xem sẽ cảm thấy mơ hồ, khó nắm bắt.', 'A mysterious story of two magicians whose intense rivalry leads them on a life-long battle for supremacy -- full of obsession, deceit and jealousy with dangerous and deadly consequences.', 'https://image.tmdb.org/t/p/w780/fAT5JUet2JDcsukQI1fNZXJ20KK.jpg', 'https://image.tmdb.org/t/p/w1280/yaExZh6qE2cfyK3o4kAMEq0mkgy.jpg', 'https://www.youtube.com/watch?v=ijXruSzfGEc', 'Christopher Nolan', ARRAY['Hugh Jackman', 'Christian Bale', 'Michael Caine', 'Piper Perabo', 'Rebecca Hall', 'Scarlett Johansson', 'Samantha Mahurin', 'David Bowie']::TEXT[], ARRAY['Chính Kịch', 'Bí Ẩn', 'Khoa Học Viễn Tưởng']::TEXT[], 131, '2006-10-19', NULL, 'US: PG-13', 8.2, 'ended'),
  ('58820118-220c-5d04-a798-915fd7b3ef1d'::UUID, 324857, 'Người Nhện: Vũ Trụ Mới', 'Spider-Man: Into the Spider-Verse', 'Sau khi bị một con nhện nhiễm xạ cắn, Miles Morales, chàng thiếu niên từ Brooklyn đã nhận được một khóa học nhanh về cách giăng tơ từ những người ở chiều không gian khác.', 'Struggling to find his place in the world while juggling school and family, Brooklyn teenager Miles Morales is unexpectedly bitten by a radioactive spider and develops unfathomable powers just like the one and only Spider-Man. While wrestling with the implications of his new abilities, Miles discovers a super collider created by the madman Wilson "Kingpin" Fisk, causing others from across the Spider-Verse to be inadvertently transported to his dimension.', 'https://image.tmdb.org/t/p/w780/kahw25SAqedXIruUGIuSUiq7t98.jpg', 'https://image.tmdb.org/t/p/w1280/1ntePsIqeklfmrQJqZPncCydsqY.jpg', 'https://www.youtube.com/watch?v=tg52up16eq0', 'Bob Persichetti', ARRAY['Shameik Moore', 'Jake Johnson', 'Hailee Steinfeld', 'Mahershala Ali', 'Brian Tyree Henry', 'Lily Tomlin', 'Luna Lauren Vélez', 'Zoë Kravitz']::TEXT[], ARRAY['Hoạt Hình', 'Hành Động', 'Phiêu Lưu', 'Khoa Học Viễn Tưởng']::TEXT[], 117, '2018-12-06', NULL, 'US: PG', 8.4, 'ended'),
  ('c70972a7-e0aa-52a1-a486-defd8585420b'::UUID, 429617, 'Người Nhện: Xa Nhà', 'Spider-Man: Far From Home', 'Bạn biết vì sao Avengers: Endgame không có after-credit không? Bởi vì ngay sau câu chuyện đó chính là sự ra mắt của Spider-Man: Far From Home đấy. Trở lại sau sự ra đi của người chú Tony – Iron Man, có vẻ như cậu bé Peter đã không còn đủ động lực, niềm tin để tiếp tục theo đuổi giấc mơ làm siêu anh hùng. Nhưng đời đâu phải lúc nào cũng như ý ta mong muốn! Nhất là khi ở ngoài kia, vẫn còn vô vàn kẻ xấu khác cần tiêu diệt. Trong chuyến du lịch đến châu Âu, Peter Parker và những người bạn của mình rơi vào rắc rối mới. Không những vậy, cậu còn được diện kiến Nick Fury. Liệu thử thách mới của Spider-Man sẽ khó khăn đến mức độ nào? Dù "gan to" cúp điện thoại của Nick Fury Peter vẫn phải hợp tác cùng ông để tiếp tục hành trình bảo vệ thế giới của chú Tony. Bên cạnh Nick Fury, Spider-Man: Far From Home còn có sự xuất hiện của một gương mặt mới là Mysterio. Liệu đây sẽ là nhân vật phản diện hay chính diện?', NULL, 'https://image.tmdb.org/t/p/w780/pkUEHB1CYfPj5K8Td484TT9mBF1.jpg', 'https://image.tmdb.org/t/p/w1280/wqBW5ltBJu0gs26yCc8shQQV82d.jpg', 'https://www.youtube.com/watch?v=sMxUb1A59MI', 'Jon Watts', ARRAY['Tom Holland', 'Jake Gyllenhaal', 'Samuel L. Jackson', 'Marisa Tomei', 'Jon Favreau', 'Zendaya', 'Jacob Batalon', 'Tony Revolori']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Khoa Học Viễn Tưởng']::TEXT[], 212, '2019-06-28', NULL, 'US: PG-13', 7.4, 'ended'),
  ('b564b2c6-af75-5b3a-9445-0fe236408501'::UUID, 335983, 'Venom', 'Venom', 'Quái Vật Venom là một kẻ thù nguy hiểm và nặng ký của Người nhện trong loạt series của Marvel. Chàng phóng viên Eddie Brock bí mật theo dõi âm mưu xấu xa của một tổ chức và đã không may mắn khi nhiễm phải loại cộng sinh trùng ngoài hành tinh (Symbiote) và từ đó đã không còn làm chủ bản thân về thể chất lẫn tinh thần. Điều này đã dần biến anh thành quái vật đen tối và nguy hiểm nhất chống lại người Nhện - Venom ...', 'Investigative journalist Eddie Brock attempts a comeback following a scandal, but accidentally becomes the host of Venom, a violent, super powerful alien symbiote. Soon, he must rely on his newfound powers to protect the world from a shadowy organization looking for a symbiote of their own.', 'https://image.tmdb.org/t/p/w780/fEdXAanbnFl4uoRUAKckJkZ64Xq.jpg', 'https://image.tmdb.org/t/p/w1280/VuukZLgaCrho2Ar8Scl9HtV3yD.jpg', 'https://www.youtube.com/watch?v=xLCn88bfW1o', 'Ruben Fleischer', ARRAY['Tom Hardy', 'Michelle Williams', 'Riz Ahmed', 'Scott Haze', 'Reid Scott', 'Jenny Slate', 'Melora Walters', 'Woody Harrelson']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Hành Động']::TEXT[], 112, '2018-09-28', NULL, 'US: PG-13', 6.8, 'ended'),
  ('f49fa212-8b27-59e5-8690-07bc0635c789'::UUID, 333339, 'Đấu Trường Ảo', 'Ready Player One', 'Phim kể về bối cảnh năm 2044, khi con người có thể trốn tránh thế giới thực ảm đạm bằng việc hòa mình vào không giản ảo mang tên OASIS. Từ đây, xuất hiện anh chàng Wade Watts. Anh đã tới với OASIS và lấy tên cho nhân vật của mình là Parzival. Một ngày nọ, người sáng lập ra Oasis đã thách thức tất cả những người chơi đi tìm Easter Eggs – Trứng phục sinh. Phần thưởng dành cho người chiến thắng là những tài sản vô cùng quý báu mà ông để lại. Wade Watts đã tìm ra được những gợi ý đầu tiên trong cuộc tìm kiếm và bắt đầu hành trình của mình. Tuy nhiên, chàng trai Wade Watts sớm thấy mình bị xoáy sâu vào vòng luẩn quẩn của những bí ẩn, những sự kiện điên rồ giật dây dưới tay tổ chức Innovative Online Industries.', 'When the creator of a popular video game system dies, a virtual contest is created to compete for his fortune.', 'https://image.tmdb.org/t/p/w780/9tIbrhcqVyPeAIosoXbdWYXhNA8.jpg', 'https://image.tmdb.org/t/p/w1280/5a7lMDn3nAj2ByO0X1fg6BhUphR.jpg', 'https://www.youtube.com/watch?v=1hrwbc5qCZ4', 'Steven Spielberg', ARRAY['Tye Sheridan', 'Olivia Cooke', 'Ben Mendelsohn', 'Lena Waithe', 'T.J. Miller', 'Simon Pegg', 'Mark Rylance', 'Philip Zhao']::TEXT[], ARRAY['Phiêu Lưu', 'Hành Động', 'Khoa Học Viễn Tưởng']::TEXT[], 140, '2018-03-28', NULL, 'US: PG-13', 7.6, 'ended'),
  ('29741958-413b-5b96-b0c6-bf6c243f1167'::UUID, 240832, 'Lucy Siêu Phàm', 'Lucy', 'Lucy là một cô gái trẻ bị bắt cóc bởi một nhóm tội phạm và bị đưa vào cơ thể một loại thuốc lạ. Thứ thuốc ấy vô tình rỉ ra và làm cho cô có siêu năng lực đặc biệt. Một người bình thường chỉ có thể sử dụng 10% trí não nhưng bây giờ cô có thể sử dụng 100% trí não của mình, cô có thể điều khiển mọi thứ bằng tâm trí hay thu nạp kiến thức một cách nhanh chóng... Lucy bắt đầu lên đường và tìm ra nguồn gốc của vấn đề.', 'A woman, accidentally caught in a dark deal, turns the tables on her captors and transforms into a merciless warrior evolved beyond human logic.', 'https://image.tmdb.org/t/p/w780/tiFde0VZytNRvpIhnnxTX4omZEG.jpg', 'https://image.tmdb.org/t/p/w1280/ozVwXlfxqNsariipatGwa5px3Pm.jpg', 'https://www.youtube.com/watch?v=l7zAV_MDC68', 'Luc Besson', ARRAY['Scarlett Johansson', 'Morgan Freeman', '최민식', 'عمرو واكد', 'Julian Rhind-Tutt', 'Pilou Asbæk', 'Lio Tipton', '신유람']::TEXT[], ARRAY['Hành Động', 'Khoa Học Viễn Tưởng']::TEXT[], 89, '2014-07-25', NULL, 'US: R', 6.5, 'ended'),
  ('04889fab-7838-5ca9-bfcc-4837700e2214'::UUID, 6479, 'Tôi Là Huyền Thoại', 'I Am Legend', 'Năm 2012 thành phố New York đầy những tòa nhà chọc trời, những tấm biển quảng cáo màu sắc đã trở thành một thành phố chết. Không có một bóng người, chỉ có cỏ dại mọc trên các xa lộ và những chiếc ô tô rỉ sét nằm ngổn ngang. Cách đó 3 năm, một chủng virus khủng khiếp đã càn quét khắp Trái Đất, tiêu diệt gần như toàn bộ nhân loại. Những người còn sống thì bị biến thành các sinh vật gớm ghiếc, hung tợn, thèm thịt tươi và sợ ánh mặt trời. Chỉ trừ, có lẽ không nhiều hơn một người, nhà khoa học Robert Neville (Will Smith).', 'Robert Neville is a scientist who was unable to stop the spread of the terrible virus that was incurable and man-made. Immune, Neville is now the last human survivor in what is left of New York City and perhaps the world. For three years, Neville has faithfully sent out daily radio messages, desperate to find any other survivors who might be out there. But he is not alone.', 'https://image.tmdb.org/t/p/w780/5ZHPCotfGWui6m1X4nkoB0tdKHs.jpg', 'https://image.tmdb.org/t/p/w1280/ePgD1cwmklyrFBjl6z96IuixuSY.jpg', 'https://www.youtube.com/watch?v=4uDU6SUpr8k', 'Francis Lawrence', ARRAY['Will Smith', 'Alice Braga', 'Charlie Tahan', 'Dash Mihok', 'Salli Richardson-Whitfield', 'Willow Smith', 'Emma Thompson', 'Darrell Foster']::TEXT[], ARRAY['Chính Kịch', 'Khoa Học Viễn Tưởng', 'Giật Gân']::TEXT[], 101, '2007-12-12', NULL, 'US: PG-13', 7.2, 'ended'),
  ('c30b318a-61e4-572b-9c4d-3d791865a770'::UUID, 1892, 'Chiến Tranh Giữa Các Vì Sao: Phần VI- Sự Trở Lại Của Jedi', 'Return of the Jedi', 'Câu chuyện với trận đụng độ giữa Luke và kẻ thù không đội trời chung Darth Vader. Với vũ khí hủy diệt Death Star được khôi phục lại, đạo quân khát máu của Đế chế trực chỉ hành tinh của nữ hoàng Leia. Luke nay đã trở thành một Jedi thực thụ được sự giúp đỡ của đạo quân Ewoks gồm những sinh vật kỳ lạ sẵn sàng đương đầu thử thách...', 'Luke Skywalker leads a mission to rescue his friend Han Solo from the clutches of Jabba the Hutt, the Emperor prepares to crush the Rebellion with a more powerful Death Star, and the Rebel fleet mounts a massive attack on the space station. Luke Skywalker confronts Darth Vader in a final climactic duel before the evil Emperor.', 'https://image.tmdb.org/t/p/w780/jQYlydvHm3kUix1f8prMucrplhm.jpg', 'https://image.tmdb.org/t/p/w1280/ziECpBRIyclmBNaFSWlvCfsKbMD.jpg', 'https://www.youtube.com/watch?v=MAW1E3JIQZE', 'Richard Marquand', ARRAY['Mark Hamill', 'Harrison Ford', 'Carrie Fisher', 'Billy Dee Williams', 'Anthony Daniels', 'Peter Mayhew', 'Sebastian Shaw', 'Ian McDiarmid']::TEXT[], ARRAY['Phiêu Lưu', 'Hành Động', 'Khoa Học Viễn Tưởng']::TEXT[], 132, '1983-05-25', NULL, 'US: PG', 7.9, 'ended'),
  ('4b2b7db9-8098-56cb-a23c-4ff65b404f04'::UUID, 155, 'Kỵ Sĩ Bóng Đêm', 'The Dark Knight', 'Người Dơi bước vào giai đoạn cam go nhất trong cuộc chiến chống lại cái ác khi tên tội phạm bậc thầy The Joker xuất hiện. Các tay trùm thuê The Joker giết Người Dơi để trả thù cho chỗ tài sản phi pháp bị anh lật tẩy. Tiếp tay cho The Joker là toàn bộ tội phạm ở thành phố Gotham, những kẻ đang bị bộ ba Người Dơi - Trung úy Gordon - Luật sư Harvey Dent thu hẹp đất sống. Hàng loạt vụ tấn công xảy ra khiến Người Dơi lúng túng. Các quan chức bị sát hại, người dân không dám ra đường buổi tối vì sợ bị giết, mọi lối ra vào thành phố Gotham bị phong tỏa. Tất cả đều do một tay The Joker sắp đặt.', NULL, 'https://image.tmdb.org/t/p/w780/7EfSqviKvXwbiGhUjHyUBGVdoiW.jpg', 'https://image.tmdb.org/t/p/w1280/9FE5eD92WfVCiivM9Pq9GVSrlWk.jpg', 'https://www.youtube.com/watch?v=zHEQs2KB25s', 'Christopher Nolan', ARRAY['Christian Bale', 'Heath Ledger', 'Aaron Eckhart', 'Michael Caine', 'Maggie Gyllenhaal', 'Gary Oldman', 'Morgan Freeman', 'Monique Gabriela Curnen']::TEXT[], ARRAY['Hành Động', 'Giật Gân', 'Tội Phạm']::TEXT[], 152, '2008-07-16', NULL, 'US: PG-13', 8.5, 'ended'),
  ('909cf44f-ea3e-5cbb-9925-27e20054c9cc'::UUID, 293660, 'Deadpool', 'Deadpool', 'Lấy cảm hứng từ nhân vật "phản anh hùng" tiếng tăm bậc nhất trong tuyển tập truyện tranh Marvel, Deadpool xoay quanh câu chuyện về Wade Wilson - kẻ ban đầu nằm trong Lực Lượng Đặc Biệt sau đó trở thành một lính đánh thuê. Sau khi trải qua một cuộc thử nghiệm tàn khốc, anh có được năng lực tự phục hồi phi thường, từ đó lấy biệt danh Deadpool. Mang trong mình khả năng mới và khiếu hài hước dị thường, Deadpool quyết săn lùng người đàn ông đã hủy hoại cả cuộc đời mình.', NULL, 'https://image.tmdb.org/t/p/w780/cFi3j0Njdoe4Ty8xiqw3BKMnzRv.jpg', 'https://image.tmdb.org/t/p/w1280/rFj9IKlL75B2pXhZA60jkNWvxeW.jpg', 'https://www.youtube.com/watch?v=GlmY-u3d4TI', 'Tim Miller', ARRAY['Ryan Reynolds', 'Morena Baccarin', 'Ed Skrein', 'T.J. Miller', 'Gina Carano', 'Leslie Uggams', 'Brianna Hildebrand', 'Stefan Kapičić']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Hài']::TEXT[], 108, '2016-02-09', NULL, 'US: R', 7.6, 'ended'),
  ('aab88a3c-3ca1-5a2c-a276-0ed704936617'::UUID, 120, 'Chúa Tể Của Những Chiếc Nhẫn: Hiệp Hội Nhẫn Thần', 'The Lord of the Rings: The Fellowship of the Ring', 'Chiếc nhẫn chúa mang sức mạnh bá chủ vô tình được số phận đưa vào tay chàng hobbit trẻ tuổi Frodo. Khi thày phù thủy Gandalf phát hiện ra chiếc nhẫn này đã từng thuộc về bạo chúa Sauron, Frodo phải nhận nhiệm vụ mang nhẫn tới khe núi Hủy diệt để tiêu hủy nó.  Không đơn độc trong hành trình gian khó, Frodo còn tiếp nhận những người đồng hành thuộc các tộc khác nhau: Legolas tộc Elf; Gimli tộc Dwarf; Aragon, Boromir và ba người bạn Hobbit trung thành...', 'Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.', 'https://image.tmdb.org/t/p/w780/2gayIj5yIrvk7BVXUCXHHIomXgR.jpg', 'https://image.tmdb.org/t/p/w1280/oiwc338EoBgS4sEI2ixAny4KQKg.jpg', 'https://www.youtube.com/watch?v=_nZdmwHrcnw', 'Peter Jackson', ARRAY['Elijah Wood', 'Ian McKellen', 'Viggo Mortensen', 'Sean Astin', 'Ian Holm', 'Liv Tyler', 'Christopher Lee', 'Sean Bean']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Hành Động']::TEXT[], 179, '2001-12-18', NULL, 'US: PG-13', 8.4, 'ended'),
  ('25374e72-aa6d-518c-adeb-c612dc59db57'::UUID, 122, 'Chúa Tể Của Những Chiếc Nhẫn: Sự Trở Lại Của Nhà Vua', 'The Lord of the Rings: The Return of the King', 'Sauron huy động toàn lực cho trận chiến khốc liệt cuối cùng, tấn công vào Gondor – vùng đất huyết mạch của loài người. Gondor dưới sự lãnh đạo của vị vua nhu nhược trở nên quá mong manh và nguy ngập. Đó chính là lúc những người anh hùng phát huy hết khả năng của mình. Cùng với sự hỗ trợ của các chiến binh Rohan, lực lượng những hồn ma bị nguyền rủa trong khe núi, Aragorn đã thống lĩnh những người Gondor chống lại Sauron, anh đã thực hiện sứ mệnh mà số phận giao phó cho mình, Aragorn sinh ra để trở thành Vua của Gondor, anh đã chứng minh điều đó. Cùng lúc đó, Frodo và Sam tiếp tục dấn sâu vào vùng đất ma quỷ đầy hiểm nguy để thực thi sứ mạng của mình, sứ mạng tiêu hủy Chiếc Nhẫn Quyền Lực. Có thể nói Sự Trở Lại Của Nhà Vua Phim là phần có nội dung hấp dẫn cùng những màn chiến đấu cực hay, cực kỳ hoành tráng.', 'As armies mass for a final battle that will decide the fate of the world--and powerful, ancient forces of Light and Dark compete to determine the outcome--one member of the Fellowship of the Ring is revealed as the noble heir to the throne of the Kings of Men. Yet, the sole hope for triumph over evil lies with a brave hobbit, Frodo, who, accompanied by his loyal friend Sam and the hideous, wretched Gollum, ventures deep into the very dark heart of Mordor on his seemingly impossible quest to destroy the Ring of Power.​', 'https://image.tmdb.org/t/p/w780/3Y6eymGHCfQkDKU6rev2WiqXMci.jpg', 'https://image.tmdb.org/t/p/w1280/ctiw6FZK4N36LmkjSklWEbuvlq9.jpg', 'https://www.youtube.com/watch?v=zckJCxYxn1g', 'Peter Jackson', ARRAY['Elijah Wood', 'Ian McKellen', 'Viggo Mortensen', 'Sean Astin', 'Andy Serkis', 'Dominic Monaghan', 'Billy Boyd', 'John Noble']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Hành Động']::TEXT[], 201, '2003-12-17', NULL, 'US: PG-13', 8.5, 'ended'),
  ('0f293349-b91b-5026-b37e-c104a2dc472e'::UUID, 49026, 'Kỵ Sĩ Bóng Đêm Trỗi Dậy', 'The Dark Knight Rises', 'Sau 8 năm kể từ ngày người dơi nhận trách nhiệm giết người thay cho Dent, Bane - một kẻ cầm đầu khủng bố mới xuất hiện và đàn áp Gotham. Và một lần nữa Hiệp sĩ bóng đêm đã trở lại để bảo vệ thành phố từng săn lùng anh như kẻ thù.', 'Following the death of District Attorney Harvey Dent, Batman assumes responsibility for Dent''s crimes to protect the late attorney''s reputation and is subsequently hunted by the Gotham City Police Department. Eight years later, Batman encounters the mysterious Selina Kyle and the villainous Bane, a new terrorist leader who overwhelms Gotham''s finest. The Dark Knight resurfaces to protect a city that has branded him an enemy.', 'https://image.tmdb.org/t/p/w780/5WFuvfiHRghbepz3I6zc1KeHIly.jpg', 'https://image.tmdb.org/t/p/w1280/c3OHQncTAnKFhdOTX7D3LTW6son.jpg', 'https://www.youtube.com/watch?v=GAjBzu8ggi0', 'Christopher Nolan', ARRAY['Christian Bale', 'Gary Oldman', 'Tom Hardy', 'Joseph Gordon-Levitt', 'Anne Hathaway', 'Marion Cotillard', 'Morgan Freeman', 'Michael Caine']::TEXT[], ARRAY['Hành Động', 'Tội Phạm', 'Giật Gân']::TEXT[], 165, '2012-07-17', NULL, 'US: PG-13', 7.8, 'ended'),
  ('2179ca0e-8073-5fdd-9d3a-a81e95ac6216'::UUID, 121, 'Chúa Tể Của Những Chiếc Nhẫn: Hai Tòa Tháp', 'The Lord of the Rings: The Two Towers', 'Cuộc hành trình đi hủy diệt chiếc nhẫn tiếp tục với bao nguy hiểm chờ đợi Frodo ở phía trước. Lần này, anh và Sam có một bạn đồng hành mới là Gollum. Trong khi đó, Gandalf may mắn thoát chết, hơn nữa sức mạnh của ông còn vượt xa hơn rất nhiều. Ông cùng Aragon, Legolas và Gimli cùng những thần rừng tìm cách phá hủy âm mưu của Saruman. Tiếp nối thành công của phần 1 The Lord Of The Ring 2 kế thừa và đan xen giữa hai hệ thống nhân vật cũ và mới làm cho nội dung phim càng thêm lôi cuốn người xem. The Lord Of The Ring 2 cũng mang về 2 Giải Oscar cho hạng mục âm thanh và kĩ xảo.', 'Frodo Baggins and the other members of the Fellowship continue on their sacred quest to destroy the One Ring--but on separate paths. Their destinies lie at two towers - Orthanc Tower in Isengard, where the corrupt wizard Saruman awaits, and Sauron''s fortress at Barad-dur, deep within the dark lands of Mordor.', 'https://image.tmdb.org/t/p/w780/jmwZrMZE6bEuG6JWeu8Udb8B69d.jpg', 'https://image.tmdb.org/t/p/w1280/6G73mNyooWAEQTpckPSnFxFoNmc.jpg', 'https://www.youtube.com/watch?v=nuTU5XcZTLA', 'Peter Jackson', ARRAY['Elijah Wood', 'Ian McKellen', 'Viggo Mortensen', 'Sean Astin', 'Andy Serkis', 'John Rhys-Davies', 'Orlando Bloom', 'Bernard Hill']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Hành Động']::TEXT[], 179, '2002-12-18', NULL, 'US: PG-13', 8.4, 'ended'),
  ('da3a7c13-6ac8-5984-b12e-5bac2e3ca000'::UUID, 284052, 'Phù Thuỷ Tối Thượng', 'Doctor Strange', 'DOCTOR STRANGE là câu chuyện về bác sĩ Giải Phẫu Thần Kinh tên Stephen Vincent Strange. Cuộc đời anh thay đổi từ sau một tai nạn xe hơi khủng khiếp. Sau tai nạn đó, Stephen nhận ra mình có những năng lực bí ẩn cũng như biết thêm về thế giới ma thuật huyền bí. Từ một vị bác sĩ bình thường, Stephen Strange dần nhận được nhiều siêu năng lực để cứu trái đất khỏi những tai họa.', NULL, 'https://image.tmdb.org/t/p/w780/rkklqyyUzYrJoo3iDYiTjGbhbaw.jpg', 'https://image.tmdb.org/t/p/w1280/kkoiH8ZWxJ9WSAjOadGtuHUQxbm.jpg', 'https://www.youtube.com/watch?v=EhZdDbLtjR4', 'Scott Derrickson', ARRAY['Benedict Cumberbatch', 'Chiwetel Ejiofor', 'Rachel McAdams', 'Benedict Wong', 'Mads Mikkelsen', 'Tilda Swinton', 'Michael Stuhlbarg', 'Benjamin Bratt']::TEXT[], ARRAY['Giả Tưởng', 'Phiêu Lưu', 'Hành Động']::TEXT[], 115, '2016-10-25', NULL, 'US: PG-13', 7.4, 'ended'),
  ('994221b2-72a3-50b3-9001-012a968e5a16'::UUID, 272, 'Người Dơi Bắt Đầu', 'Batman Begins', 'Bruce Wayne thuở nhỏ là một cậu bé mắc chứng sợ dơi và có bố mẹ bị giết bởi tên cướp tên Joe Chill. Lớn lên, nung nấu ý định trả thù, Bruce Wayne rời khỏi thành phố và gặp được Henri Ducard, người truyền dạy cho anh những bí kíp võ thuật. Từ đây, với bản chất lương thiện, Bruce Wayne trở thành người hùng trừ gian diệt ác của thành phố… Với sự tham gia của dàn diễn viên nổi tiếng Christian Bale, Katie Holmes, Gary Oldman và được dàn dựng bởi đạo diễn tài ba Christopher Nolan, chỉ vài tháng sau khi ra mắt, Batman Begins đã được độc giả của tạp chí Empire bầu chọn đứng thứ 36 trong các phim hay nhất mọi thời đại, trở thành một trong những huyền thoại của dòng phim siêu anh hùng.', NULL, 'https://image.tmdb.org/t/p/w780/ziFjqY3ABYTJZ2kHMzjr3eeyMQZ.jpg', 'https://image.tmdb.org/t/p/w1280/9IIBboV7MCT0bTxzXHmWK1Hq558.jpg', 'https://www.youtube.com/watch?v=I57S1DZMjRo', 'Christopher Nolan', ARRAY['Christian Bale', 'Michael Caine', 'Liam Neeson', 'Katie Holmes', 'Gary Oldman', 'Cillian Murphy', 'Tom Wilkinson', 'Rutger Hauer']::TEXT[], ARRAY['Chính Kịch', 'Tội Phạm', 'Hành Động']::TEXT[], 140, '2005-06-10', NULL, 'US: PG-13', 7.7, 'ended'),
  ('42664ad3-2277-51c2-a005-33f93cfaca82'::UUID, 22, 'Cướp Biển Vùng Caribbean: Lời Nguyền Tàu Ngọc Trai Đen', 'Pirates of the Caribbean: The Curse of the Black Pearl', 'Khi chiếc thuyền của gia đình cô bé Elizabeth đi qua vùng biển Caribe nhiều cướp biển họ đã cứu được cậu bé Will Turner. Cả gia đình Elizabeth không hề biết rằng Will là William Turner, con trai của một tên trùm cướp biển khét tiếng.  Nhiều năm sau, mọi chuyện dần dần được hé lộ khi Elizabeth bị ngã xuống biển do một tai nạn và được thuyền trưởng Jack Sparrow cứu thoát.', 'When wily pirate Captain Barbossa seizes Jack Sparrow’s beloved ship, the Black Pearl, and kidnaps the governor’s daughter, Elizabeth Swann, blacksmith Will Turner reluctantly teams up with the unpredictable pirate Jack to rescue her—only to uncover a terrifying curse that turns Barbossa’s crew into the undead.', 'https://image.tmdb.org/t/p/w780/hQjENbYuhkjcr8c8O8tpQxw0XOD.jpg', 'https://image.tmdb.org/t/p/w1280/uRNgkJSkNBFbbn9fPsEjDIy8Sh3.jpg', 'https://www.youtube.com/watch?v=-9HT0l9HV4c', 'Gore Verbinski', ARRAY['Johnny Depp', 'Geoffrey Rush', 'Orlando Bloom', 'Keira Knightley', 'Jack Davenport', 'Jonathan Pryce', 'Lee Arenberg', 'Mackenzie Crook']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Hành Động']::TEXT[], 143, '2003-07-09', NULL, 'US: PG-13', 7.8, 'ended'),
  ('e24d8012-0403-5644-aa90-758345b91502'::UUID, 10195, 'Thor', 'Thor', 'Thor, thái tử ngạo mạn và hiếu chiến của vương quốc Asgard, đã vi phạm thỏa ước hòa bình cổ xưa khi tự ý kéo quân tấn công Jotunheim – xứ sở của Người khổng lồ Băng. Nhận thấy sự kiêu ngạo và thiếu tư cách trị vì của con trai, vua cha Odin tước bỏ toàn bộ thần lực, phong ấn chiếc búa quyền năng Mjolnir bằng bùa chú "chỉ kẻ xứng đáng mới nhấc được", rồi trục xuất anh xuống Trái Đất (Midgard) dưới hình hài một người phàm trần. Rơi xuống vùng sa mạc New Mexico, Thor được nhà vật lý thiên văn Jane Foster cùng nhóm nghiên cứu cứu giúp và bắt đầu học cách sống khi không còn sức mạnh. Cùng lúc đó tại Asgard, Loki phát hiện ra nguồn gốc thật sự của mình và lợi dụng lúc Odin rơi vào giấc ngủ "Odinsleep" để chiếm đoạt ngai vàng, đồng thời phái cỗ máy hủy diệt Destroyer xuống Trái Đất nhằm trừ khử anh trai.', 'Against his father Odin''s will, The Mighty Thor - a powerful but arrogant warrior god - recklessly reignites an ancient war. Thor is cast down to Earth and forced to live among humans as punishment. Once here, Thor learns what it takes to be a true hero when the most dangerous villain of his world sends the darkest forces of Asgard to invade Earth.', 'https://image.tmdb.org/t/p/w780/lBXpsvbXUxgim1m5cb56rxDWmAT.jpg', 'https://image.tmdb.org/t/p/w1280/cDJ61O1STtbWNBwefuqVrRe3d7l.jpg', 'https://www.youtube.com/watch?v=uHBnrJowBZE', 'Kenneth Branagh', ARRAY['Chris Hemsworth', 'Natalie Portman', 'Tom Hiddleston', 'Anthony Hopkins', 'Stellan Skarsgård', 'Kat Dennings', 'Clark Gregg', 'Colm Feore']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Hành Động']::TEXT[], 115, '2011-04-27', NULL, 'US: PG-13', 6.8, 'ended'),
  ('aec9bf85-2935-5810-851a-246338e338c6'::UUID, 297761, 'Biệt Đội Cảm Tử', 'Suicide Squad', 'Suicide Squad xoay quanh nhóm ác nhân mang tên Biệt đội Cảm tử. Đây là tổ chức đánh thuê gồm toàn những kẻ thù của Batman, được chính phủ tập hợp lại để chuyên thực hiện các nhiệm vụ tối mật. Điều gây tò mò nhất cho công chúng về Suicide Squad hẳn là nhân vật Joker.  Mọi chuyện bắt đầu từ trò đùa tai quái của Joker, khi hắn gửi tới Harley một lá thư tình rất đẹp chứa trong chiếc hộp đen cùng một con chuột-còn-sống-nhăn trong đó. Và rồi cậu ấy gửi cho Will Smith một băng đạn thật có kèm tâm thư. Hắn còn gửi cho các đồng đội một món quà dưới dạng... một con heo chết, kèm với đó là cuốn băng ghi lại lời của Leto trong hình dạng của Joker: "Mấy người, tôi không thể ở đó cùng các bạn nhưng tôi muốn mấy người biết là tôi cũng đang tập luyện vất vả y như mấy người vậy".', 'From DC Comics comes the Suicide Squad, an antihero team of incarcerated supervillains who act as deniable assets for the United States government, undertaking high-risk black ops missions in exchange for commuted prison sentences.', 'https://image.tmdb.org/t/p/w780/xvym7QbQPhoMC0Mw18KRfXN1guW.jpg', 'https://image.tmdb.org/t/p/w1280/wAk0yKrhAmvsoMvlKs4QImhvK5X.jpg', 'https://www.youtube.com/watch?v=m0Xb9BhfVjY', 'David Ayer', ARRAY['Will Smith', 'Jared Leto', 'Margot Robbie', 'Joel Kinnaman', 'Viola Davis', 'Jai Courtney', 'Jay Hernandez', 'Adewale Akinnuoye-Agbaje']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Giả Tưởng']::TEXT[], 122, '2016-08-03', NULL, 'US: PG-13', 5.9, 'ended'),
  ('0200a875-1bc8-52c2-9051-d840e79c1c8c'::UUID, 98, 'Võ Sĩ Giác Đấu', 'Gladiator', 'Hoàng đế Marcus quyết định chọn vị tướng tin cẩn là Maximus làm người kế vị ngai vàng. Ðiều đó làm Commodus, con trai Marcus, nổi giận. Hắn đã giết cha để chiếm ngôi rồi hãm hại gia đình Maximus. Bản thân Maximus bị trở thành nô lệ, phải tham gia vào các cuộc thi giác đấu... Cuối cùng Maximus cũng về đến Rome và trả thù cho gia đình... Cuộc đời Maximus thay đổi từ ấy, từ một vị tướng oai dũng trở thành một kẻ nô lệ phải trải qua bao thử thách...', 'After the death of Emperor Marcus Aurelius, his devious son takes power and demotes Maximus, one of Rome''s most capable generals who Marcus preferred. Eventually, Maximus is forced to become a gladiator and battle to the death against other men for the amusement of paying audiences.', 'https://image.tmdb.org/t/p/w780/usBP3JEXW7iyDfpSfgYFCncg1NA.jpg', 'https://image.tmdb.org/t/p/w1280/Ar7QuJ7sJEiC0oP3I8fKBKIQD9u.jpg', 'https://www.youtube.com/watch?v=P5ieIbInFpg', 'Ridley Scott', ARRAY['Russell Crowe', 'Joaquin Phoenix', 'Connie Nielsen', 'Oliver Reed', 'Richard Harris', 'Derek Jacobi', 'Djimon Hounsou', 'David Schofield']::TEXT[], ARRAY['Hành Động', 'Chính Kịch', 'Phiêu Lưu']::TEXT[], 155, '2000-05-04', NULL, 'US: R', 8.2, 'ended'),
  ('e6036faa-5e7f-5fbb-b355-975555747018'::UUID, 245891, 'Sát Thủ John Wick', 'John Wick', 'John Wick xuất sắc như một tân binh hiện đại. Về cơ bản phim có một tiền đề vô cùng đặc sắc: một tay súng đã nghỉ hưu trở về với một cuộc đời tội phạm, thoạt đầu ta tưởng đó là một tên xã hội đen đã đánh cắp chiếc xe Mustang giết chết con chó của anh ta. Nhưng nếu nhìn nhận kỹ hơn, thực chất John phải vật lộn với một cuộc khủng hoảng hiện hữu sau cái chết của vợ mình. Có thể tất cả là sự phát tiết điên cuồng của John đè nén bấy lâu. Ngay cả kẻ thù của John cũng hiểu điều đó, và họ sợ đến chết khi thấy anh nổi dậy sau ngừng ấy năm.', 'Ex-hitman John Wick comes out of retirement to track down the gangsters that took everything from him.', 'https://image.tmdb.org/t/p/w780/ayCZtAXj0ir7Fim57176pNeaLNZ.jpg', 'https://image.tmdb.org/t/p/w1280/ff2ti5DkA9UYLzyqhQfI2kZqEuh.jpg', 'https://www.youtube.com/watch?v=6r0s41Ju5XA', 'Chad Stahelski', ARRAY['Keanu Reeves', 'Michael Nyqvist', 'Alfie Allen', 'Willem Dafoe', 'Dean Winters', 'Adrianne Palicki', 'עומר ברנע', 'Toby Leonard Moore']::TEXT[], ARRAY['Hành Động', 'Giật Gân']::TEXT[], 101, '2014-10-16', NULL, 'US: R', 7.5, 'ended'),
  ('eab9b550-ee3b-5338-8f88-18092b3e6dc3'::UUID, 297762, 'Wonder Woman: Nữ Thần Chiến Binh', 'Wonder Woman', 'Trước khi trở thành Wonder Woman, Diana là công chúa chiến binh Amazon của hòn đảo Themyscira. Khi chàng phi công Steve Trevor trôi dạt vào đảo và kể về cuộc đại chiến đang diễn ra tại thế giới bên ngoài, Diana quyết định rời khỏi quê nhà để giải cứu nhân loại. Từ đó cô khám phá ra quyền năng và sứ mệnh thật sự của mình.', 'An Amazon princess comes to the world of Man in the grips of the First World War to confront the forces of evil and bring an end to human conflict.', 'https://image.tmdb.org/t/p/w780/bzspyi8QqQQyztBhP2XwOAzWOSG.jpg', 'https://image.tmdb.org/t/p/w1280/AaABt75ZzfMGrscUR2seabz4PEX.jpg', 'https://www.youtube.com/watch?v=VSB4wGIdDwo', 'Patty Jenkins', ARRAY['Gal Gadot', 'Chris Pine', 'Connie Nielsen', 'Robin Wright', 'Danny Huston', 'David Thewlis', 'Saïd Taghmaoui', 'Ewen Bremner']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Giả Tưởng']::TEXT[], 141, '2017-05-30', NULL, 'US: PG-13', 7.2, 'ended'),
  ('f79762b3-99aa-5d6b-b8cf-65de493b0643'::UUID, 49051, 'Người Hobbit: Hành Trình Vô Định', 'The Hobbit: An Unexpected Journey', 'The Hobbit: Hành Trình Vô Định đưa người xem trở về với thế giới Trung Địa huyền ảo và tham gia vào cuộc hành trình vô định của Bilbo Baggins - chú của nhân vật Frodo. Lấy mốc thời gian trước những sự kiện xảy ra trong ba phần Chúa Nhẫn, phim xoay quanh nhân vật Bilbo Baggins, người bị cuốn vào một chuyến phiêu lưu phi thường để đoạt lại xứ sở Người Lùn đang bị chiếm giữ bởi con rồng khổng lồ Smaug. Cùng đi của Bilbo là Pháp sư Gandalf Áo Xám và 13 thành viên tộc Người Lùn mà dẫn đầu là hoàng tử Thorin Oakensheild. Cuộc hành trình đưa họ tới những vùng đất kỳ lạ của Trung Địa - nơi có những vị tiên lộng lẫy, những con yêu tinh khổng lồ, những phù thủy bí hiểm và cả những linh hồn giấu mặt đang theo dõi nhất cử nhất động của họ.', 'Bilbo Baggins, a hobbit enjoying his quiet life, is swept into an epic quest by Gandalf the Grey and thirteen dwarves who seek to reclaim their mountain home from Smaug, the dragon.', 'https://image.tmdb.org/t/p/w780/25tb9ZgOyfgabJPZhW3Vfz6L92K.jpg', 'https://image.tmdb.org/t/p/w1280/xyXmtuvsoM5J3yNad0nvcetpBdY.jpg', 'https://www.youtube.com/watch?v=CXqZK-nbZ74', 'Peter Jackson', ARRAY['Martin Freeman', 'Ian McKellen', 'Richard Armitage', 'James Nesbitt', 'Ken Stott', 'Sylvester McCoy', 'Barry Humphries', 'Dean O''Gorman']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Hành Động']::TEXT[], 169, '2012-12-12', NULL, 'US: PG-13', 7.4, 'ended'),
  ('3e97e319-3fdc-5b5b-ad3a-21f642fedd6a'::UUID, 383498, 'Deadpool 2', 'Deadpool 2', 'Trong phần 2 Deadpool sẽ đối đầu với sát nhân Cable, một kẻ đến từ tương lai với âm mưu giết hại một đứa bé – Người mà theo hắn sau này sẽ trở thành một dị nhân đầy quyền năng. Với nỗ lực đảm bảo sự an toàn cho đứa bé, Deadpool sẽ nhận được sự giúp đỡ từ cả những người bạn mới và cũ, và đặc biệt là các thành viên từ một đội quân mới thành lập có tên X-Force', NULL, 'https://image.tmdb.org/t/p/w780/l0OdqQ9z12GGckRP8cmCcVfoflF.jpg', 'https://image.tmdb.org/t/p/w1280/3P52oz9HPQWxcwHOwxtyrVV1LKi.jpg', 'https://www.youtube.com/watch?v=R4212XlLX_g', 'David Leitch', ARRAY['Ryan Reynolds', 'Josh Brolin', 'Morena Baccarin', 'Julian Dennison', 'Zazie Beetz', 'T.J. Miller', 'Leslie Uggams', 'Karan Soni']::TEXT[], ARRAY['Hành Động', 'Hài', 'Phiêu Lưu']::TEXT[], 120, '2018-05-15', NULL, 'US: R', 7.5, 'ended'),
  ('bacad568-3832-5059-a2c2-514cdb08a318'::UUID, 24, 'Cô Dâu Báo Thù 1', 'Kill Bill: Vol. 1', 'Nhân vật chính của bộ phim được gọi là "Cô Dâu" (Uma Thurman), là một thành viên của Tổ chức Ám Sát Vipe, dẫn đầu bởi Bill, người yêu của cô. Khi nhận ra mình mang thai đứa con của Bill, "Cô Dâu" đã quyết định rời bỏ cuộc sống của một kẻ ám sát, giết người. Cô đến Texas, gặp một người đàn ông trẻ, và quyết định sống cuộc sống mới. Nhưng vào ngày cưới, Bill đã xuất hiện cùng với 4 sát thủ còn lại giết hết tất cả mọi người. Nhưng họ đã sơ sót, "Cô Dâu" vẫn còn sống và chìm trong hôn mê suốt 4 năm trời. Tỉnh dậy, nhớ lại tất cả những gì đã xảy ra, đứa bé trong bụng không còn nữa. Đau đớn tột cùng, cô quyết định trả thù năm người đã phá hủy cuộc sống của cô và giết chết con cô. Và hành trình giết Bill bắt đầu...', 'An assassin is shot by her ruthless employer, Bill, and other members of their assassination circle – but she lives to plot her vengeance.', 'https://image.tmdb.org/t/p/w780/oupHpNSZwKWlq7fCdA1KEhapliV.jpg', 'https://image.tmdb.org/t/p/w1280/iffzIhuLAO38Po6sh1s6ZEVwlNL.jpg', 'https://www.youtube.com/watch?v=sXwXk3jcrfU', 'Quentin Tarantino', ARRAY['Uma Thurman', 'Lucy Liu', 'Vivica A. Fox', 'Daryl Hannah', 'David Carradine', 'Michael Madsen', 'Julie Dreyfus', '栗山千明']::TEXT[], ARRAY['Hành Động', 'Tội Phạm']::TEXT[], 111, '2003-10-10', NULL, 'US: R', 8, 'ended'),
  ('6eafb5ab-24b3-51df-9982-6c1fac72e5b6'::UUID, 209112, 'Batman Đại Chiến Superman: Ánh Sáng Công Lý', 'Batman v Superman: Dawn of Justice', 'Nội dung bộ phim sẽ xoay quanh cuộc đối đầu có 1-0-2 của vị hiệp sĩ mạnh mẽ, đáng gờm nhất của thành phố Gotham với biểu tượng được tôn sùng nhất của thành phố Metropolis. Nguyên nhân của “cuộc chiến” này bắt nguồn từ việc họ đang lo lắng vì không thể kiểm soát được siêu anh hùng mới có sức mạnh thần thánh. Tuy nhiên, trong lúc họ “mải miết” chiến đấu với nhau thì có một mối đe dọa khác đã nổi lên và đẩy nhân loại vào tình thế nguy hiểm hơn bao giờ hết.', NULL, 'https://image.tmdb.org/t/p/w780/aOqrz5D9Kl0ZRWoDjUj025o2os9.jpg', 'https://image.tmdb.org/t/p/w1280/5fX1oSGuYdKgwWmUTAN5MNSQGzr.jpg', 'https://www.youtube.com/watch?v=b6im-6pbmis', 'Zack Snyder', ARRAY['Ben Affleck', 'Henry Cavill', 'Jesse Eisenberg', 'Gal Gadot', 'Amy Adams', 'Diane Lane', 'Laurence Fishburne', 'Jeremy Irons']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Giả Tưởng']::TEXT[], 152, '2016-03-23', NULL, 'US: PG-13', 6, 'ended'),
  ('b86bf642-8f5d-5bf2-9260-bc5dca211434'::UUID, 9806, 'Gia Đình Siêu Nhân', 'The Incredibles', 'Một gia đình gồm các siêu anh hùng gần như đã nghỉ hưu, hơi thừa cân và cố gắng sống sót trong cuộc sống hàng ngày khắc nghiệt, bị buộc phải hành động ... chỉ đơn giản là để cứu thế giới. Bob Paar từng là một trong những siêu anh hùng vĩ đại nhất thế giới (anh ta còn được gọi là "Mr. Incredible"), cứu mạng và chiến đấu với những kẻ ác hàng ngày. Mười lăm năm đã trôi qua, và Bob và vợ (một cựu siêu anh hùng nổi tiếng ở bên phải) đã nhận được một bản sắc dân sự và lui về ngoại vi để sống một cuộc sống bình thường với ba đứa con của họ. Bob kiểm tra thời hạn yêu cầu bảo hiểm và chống lại sự nhàm chán và tình yêu. Anh ta háo hức muốn trở lại hành động, vì vậy khi nhận được một liên lạc bí ẩn ra lệnh cho anh ta đến một hòn đảo xa xôi để thực hiện một nhiệm vụ tối mật, anh ta đã không nghĩ hai lần.', 'Bob Parr has given up his superhero days to log in time as an insurance adjuster and raise his three children with his formerly heroic wife in suburbia. But when he receives a mysterious assignment, it''s time to get back into costume.', 'https://image.tmdb.org/t/p/w780/jr49gG4vTULgWU6gsyWsso5PEap.jpg', 'https://image.tmdb.org/t/p/w1280/lxwzY9vNwjDgxWKt3zZ6zcU6rEJ.jpg', 'https://www.youtube.com/watch?v=sJCjKQQOqT0', 'Brad Bird', ARRAY['Craig T. Nelson', 'Holly Hunter', 'Sarah Vowell', 'Spencer Fox', 'Jason Lee', 'Samuel L. Jackson', 'Elizabeth Peña', 'Eli Fucile']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Hoạt Hình', 'Gia Đình']::TEXT[], 115, '2004-10-27', NULL, 'US: PG', 7.7, 'ended'),
  ('1d3d15bc-827d-5734-8f8b-2db64f901ffc'::UUID, 76338, 'Thor: Thế Giới Bóng Tối', 'Thor: The Dark World', 'Thor: Thần Sấm phải chiến đấu để cứu trái đất và tất cả Cửu Giới từ một kẻ thù trong bóng tối. Trong khi Thor chiến đấu để lập lại trật tự trên vũ trụ thì một chủng tộc cổ xưa Malekith vì lợi nhuận đã làm mọi cách để kéo vũ trụ trở lại vào bóng tối. Phải đối mặt với một kẻ thù mà ngay cả Odin và Asgard không thể chịu được, Thor phải bắt tay vào hành trình nguy hiểm nhất. Đặc biệt, Thor lại cơ hội tái hợp lại với Jane Foster nhưng anh buộc phải hy sinh mọi thứ để cứu tất cả chúng ta. Liệu Thor sẽ chọn Jane Foster hay chấp nhận đánh đổi vì sứ mạng của mình? Là rồi Thần Sấm có giải cứu được trái đất?', 'Thor fights to restore order across the cosmos… but an ancient race led by the vengeful Malekith returns to plunge the universe back into darkness. Faced with an enemy that even Odin and Asgard cannot withstand, Thor must embark on his most perilous and personal journey yet, one that will reunite him with Jane Foster and force him to sacrifice everything to save us all.', 'https://image.tmdb.org/t/p/w780/zwFRrj1CF3YbfCzjhxPvzrQojor.jpg', 'https://image.tmdb.org/t/p/w1280/5o88bbqcV5STn56jqOeovaaWbAE.jpg', 'https://www.youtube.com/watch?v=npvJ9FTgZbM', 'Alan Taylor', ARRAY['Chris Hemsworth', 'Natalie Portman', 'Tom Hiddleston', 'Christopher Eccleston', 'Anthony Hopkins', 'Jaimie Alexander', 'Zachary Levi', 'Ray Stevenson']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Giả Tưởng']::TEXT[], 195, '2013-10-30', NULL, 'US: PG-13', 6.5, 'ended'),
  ('1c98722c-f24b-5923-8ceb-559d7f045a5e'::UUID, 207703, 'Mật Vụ Kingsman', 'Kingsman: The Secret Service', 'Bộ phim kể về một tổ chức điệp viên siêu đẳng sử dụng vũ khí công nghệ cao để chống lại ác nhân Richmond Valentine, một tỷ phú thiên tài với âm mưu xóa sổ phần lớn dân cư trên trái đất để thanh lọc thành một thế giới mới theo ý của mình.', NULL, 'https://image.tmdb.org/t/p/w780/jbyzyYucBh1OOb0o88U57GjdGCq.jpg', 'https://image.tmdb.org/t/p/w1280/qzUIOTk0E3F1zjvYjcBRTKUTgf9.jpg', 'https://www.youtube.com/watch?v=OR57HmOmb_c', 'Matthew Vaughn', ARRAY['Taron Egerton', 'Colin Firth', 'Samuel L. Jackson', 'Mark Strong', 'Sophie Cookson', 'Sofia Boutella', 'Michael Caine', 'Edward Holcroft']::TEXT[], ARRAY['Tội Phạm', 'Hài', 'Hành Động']::TEXT[], 129, '2015-01-24', NULL, 'US: R', 7.6, 'ended'),
  ('aa69641f-fa26-5932-b289-325e5cae054b'::UUID, 374720, 'Cuộc Di Tản Dunkirk', 'Dunkirk', 'Năm 1940, nước Anh và các đồng minh đối diện với một thảm họa quân sự khổng lồ. 400.000 quân của họ sập bẫy trong tuyệt vọng tại Dunkirk, Pháp. Họ đứng trước nguy cơ bị phát xít Đức xóa sổ hoàn toàn… Lúc này, thủ tướng Anh - Winston Churchill đã phát động chiến dịch Dynamo lịch sử kéo dài từ 26/5 đến 4/6/1940. Khi những người lính “Họ không thể về nhà. Quê nhà sẽ đến tìm họ.” Hơn 68.000 quân viễn chinh Anh đã chết hoặc bị bắt làm tù binh nhưng đã có 218.000 lính Anh, 120.000 lính Pháp và Bỉ được giải cứu trong chiến dịch này.', 'The story of the miraculous evacuation of Allied soldiers from Belgium, Britain, Canada and France, who were cut off and surrounded by the German army from the beaches and harbour of Dunkirk between May 26th and June 4th 1940 during World War II.', 'https://image.tmdb.org/t/p/w780/qRtqlnvcoWIL0Uma3HA15Ll84I6.jpg', 'https://image.tmdb.org/t/p/w1280/pTwF9hLkqAtuOqXMdOyPwz4AgnI.jpg', 'https://www.youtube.com/watch?v=T7O7BtBnsG4', 'Christopher Nolan', ARRAY['Fionn Whitehead', 'Tom Hardy', 'Mark Rylance', 'Kenneth Branagh', 'Cillian Murphy', 'Barry Keoghan', 'Harry Styles', 'Aneurin Barnard']::TEXT[], ARRAY['Chiến Tranh', 'Hành Động', 'Lịch Sử']::TEXT[], 106, '2017-07-19', 'T16', 'US: PG-13', 7.5, 'ended'),
  ('3400debf-32f0-5ed3-ba71-1d7c5aba05f5'::UUID, 58, 'Cướp Biển Vùng Caribbean: Chiếc Rương Tử Thần', 'Pirates of the Caribbean: Dead Man''s Chest', 'Cuối cùng sau nhiều nỗ lực Jack Sparrow đã chiếm lại đuợc con tàu huyền thoại Ngọc Trai Đen. Tuy nhiên, để giành được Ngọc Trai Đen, Jack đã gây thù kết oán với Davy Jones (thuyền trưởng con tàu ma Flying Dutchman). Để chiến thắng Davy chỉ còn cách tìm được chiếc rương tử thần và Jack – Will – Elizabeth lại dấn thân vào cuộc phiêu lưu mới… Hình ảnh kì dị nhưng khá vui nhộn đã trở thành thương hiệu cho các phim do Walt Disney sản xuất. So với phần I phần II được lồng ghép thêm nhiều tình huống hài hước hơn. Các đại cảnh lớn được thiết kế công phu hoành tráng mang tới dấu ấn riêng.', 'Captain Jack Sparrow’s got a blood debt to pay: he owes his soul to the legendary Davy Jones, ghastly Ruler of the Ocean Depths. To escape eternal servitude aboard the Flying Dutchman, ever-crafty Jack must track down the still-beating heart of Jones. But he won’t do it alone: Will Turner and Elizabeth Swann are drawn back into another one of his perilous quests—assuming they can evade execution for aiding a pirate.', 'https://image.tmdb.org/t/p/w780/6Ax7A0ngybY5LhG0M5gSfyjZV0I.jpg', 'https://image.tmdb.org/t/p/w1280/vr6n6ZFUZvedvIlhfYcbCWcaKyW.jpg', 'https://www.youtube.com/watch?v=elqO-GNfStM', 'Gore Verbinski', ARRAY['Johnny Depp', 'Orlando Bloom', 'Keira Knightley', 'Jack Davenport', 'Bill Nighy', 'Jonathan Pryce', 'Lee Arenberg', 'Mackenzie Crook']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Hành Động']::TEXT[], 151, '2006-07-06', NULL, 'US: PG-13', 7.4, 'ended'),
  ('f968611c-d7cb-574f-9ef4-63a2566303ef'::UUID, 339403, 'Quái Xế Baby', 'Baby Driver', 'Baby Driver là một 2017 hành động phim tội phạm được viết kịch bản và đạo diễn bởi Edgar Wright. Bộ phim có sự tham gia Ansel Elgort, Kevin Spacey, Lily James, Jon Bernthal, Eiza González, Jon Hamm và Jamie Foxx . Bộ phim kể về vụ cướp của Baby do Ansel Elgort thủ vai.', 'After being coerced into working for a crime boss, a young getaway driver finds himself taking part in a heist doomed to fail.', 'https://image.tmdb.org/t/p/w780/TwJyztaR7VsUmSOmPrrgvS0GNu.jpg', 'https://image.tmdb.org/t/p/w1280/yir5430WblZSZuIMd9C6pIZerfA.jpg', 'https://www.youtube.com/watch?v=jGGptGEAo2U', 'Edgar Wright', ARRAY['Ansel Elgort', 'Kevin Spacey', 'Lily James', 'Jon Hamm', 'Jamie Foxx', 'Jon Bernthal', 'Eiza González', 'Flea']::TEXT[], ARRAY['Hành Động', 'Tội Phạm']::TEXT[], 113, '2017-06-28', NULL, 'US: R', 7.4, 'ended'),
  ('55a4d593-4f42-56e5-83b7-6fb5c2f89fe0'::UUID, 177572, 'Biệt Đội Big Hero 6', 'Big Hero 6', 'Câu chuyện diễn ra tại một thành phố hư cấu có tên là San Fransokyo (tên viết tắt của 2 thành phố San Francisco của Mỹ và Tokyo của Nhật Bản). Đó là nơi ở của cậu bé thần đồng Hiro Hamada cùng với một người bạn hết sức đặc biệt là Baymax. Baymax trông giống như một người tuyết màu trắng, đây là phát minh của Tadashi – anh trai Hiro. Baymax được tạo ra nhằm mục đích phục vụ cho sức khỏe của con người. Với sự thông minh của Hiro, cậu nhóc đã chế tạo ra các công cụ chiến đấu cho biệt đội siêu anh hùng với sự đồng hành của 5 thành viên còn lại là Baymax, Wasabi, Go Go, Fred và Honey Lemon. Họ cùng điều tra về kẻ giấu mặt “kabuki” đã đánh cắp phát minh “bọ siêu nhỏ” của Hiro và ngăn chặn 1 thảm họa đối với thành phố.', 'A special bond develops between plus-sized inflatable robot Baymax, and prodigy Hiro Hamada, who team up with a group of friends to form a band of high-tech heroes.', 'https://image.tmdb.org/t/p/w780/nqq1B0c5ylhJZ0m5CdkonHNE2zZ.jpg', 'https://image.tmdb.org/t/p/w1280/4s2d3xdyqotiVNHTlTlJjrr3q0H.jpg', 'https://www.youtube.com/watch?v=8IdMPpKMdcc', 'Don Hall', ARRAY['Scott Adsit', 'Ryan Potter', 'Daniel Henney', 'T.J. Miller', 'Jamie Chung', 'Damon Wayans Jr.', 'Genesis Rodriguez', 'James Cromwell']::TEXT[], ARRAY['Phiêu Lưu', 'Gia Đình', 'Hoạt Hình', 'Hành Động', 'Hài']::TEXT[], 102, '2014-10-24', NULL, 'US: PG', 7.7, 'ended'),
  ('cee6f3b9-7403-5249-b2a1-abc1c42327e3'::UUID, 101, 'Sát Thủ Chuyên Nghiệp', 'Léon', 'Cô bé Mathilda có hoàn cảnh đặc biệt. Cả nhà buôn ma tuý, cha và chị gái không hề quan tâm gì đến mình, chỉ có cậu em trai là người mà Mathilda yêu thương nhất. Cuộc sống cứ tiếp diễn trôi và trong một bầu không khí đầy khủng hoảng của người chị mất nết cùng người cha buôn ma tuý, tưởng như tương lai Mathilda cũng trở thành một cô bé hư. Mãi cho đến một ngày, khi một cảnh sát tha hoá vì cạnh tranh làm ăn mà giết cả nhà Mathilda, cuộc sống của cô bé mới bắt đầu thay đổi. Cô chạy trốn và được Leon (Jean Reno), một tên giết thuê bảo bọc. Cô học bắn súng để trả thù, và đã được Leon giúp đỡ.', 'Léon, the top hit man in New York, has earned a rep as an effective "cleaner". But when his next-door neighbors are wiped out by a loose-cannon DEA agent, he becomes the unwilling custodian of 12-year-old Mathilda. Before long, Mathilda''s thoughts turn to revenge, and she considers following in Léon''s footsteps.', 'https://image.tmdb.org/t/p/w780/2ZJuVYpUoau4QfftPsrhhmWbIn5.jpg', 'https://image.tmdb.org/t/p/w1280/fj0hwDJEOOHllRim2BMt5L7tbjf.jpg', 'https://www.youtube.com/watch?v=DD-6bmOY__g', 'Luc Besson', ARRAY['Jean Reno', 'Natalie Portman', 'Gary Oldman', 'Danny Aiello', 'Peter Appel', 'Michael Badalucco', 'Ellen Greene', 'Frank Senger']::TEXT[], ARRAY['Tội Phạm', 'Chính Kịch', 'Hành Động']::TEXT[], 111, '1994-09-14', NULL, 'FR: 12', 8.3, 'ended'),
  ('8ece430d-4b17-5167-aed8-7756e404de9c'::UUID, 37724, 'Điệp Viên 007: Tử Địa Skyfall', 'Skyfall', 'Trong tập phim lần này, toàn bộ hồ sơ tuyệt mật về các điệp viên nằm vùng mà MI6 cài đặt khắp thế giới bị phát tán. Sinh mệnh tổ chức tình báo này bị đe dọa nặng nề. M - người đứng đầu MI6 - phải vận dụng mọi khả năng ứng biến để cứu vãn tình hình. 007 là niềm hy vọng duy nhất của M. Tuy nhiên, kẻ thù nguy hiểm nhất từ trước tới nay là Silva đã lật tẩy nhiều bí mật đáng sợ trong quá khứ của M. Điều này thử thách lòng trung thành của James Bond cũng như tương lai của MI6…', 'When Bond''s latest assignment goes gravely wrong, agents around the world are exposed and MI6 headquarters is attacked. While M faces challenges to her authority and position from Gareth Mallory, the new Chairman of the Intelligence and Security Committee, it''s up to Bond, aided only by field agent Eve, to locate the mastermind behind the attack.', 'https://image.tmdb.org/t/p/w780/rdBrhE4IcEosQ5tL5BQHFFcdNRg.jpg', 'https://image.tmdb.org/t/p/w1280/wkA622CCN2X0uwpgqYEOnUYEDf5.jpg', 'https://www.youtube.com/watch?v=YvV3g8hLlyU', 'Sam Mendes', ARRAY['Daniel Craig', 'Judi Dench', 'Javier Bardem', 'Ralph Fiennes', 'Naomie Harris', 'Bérénice Marlohe', 'Albert Finney', 'Ben Whishaw']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Giật Gân']::TEXT[], 143, '2012-10-24', NULL, 'US: PG-13', 7.3, 'ended'),
  ('d7e90d29-3be7-54e1-9a93-033085046bdf'::UUID, 285, 'Cướp Biển Vùng Caribbean: Nơi Tận Cùng Thế Giới', 'Pirates of the Caribbean: At World''s End', 'Để cứu nguy cho cướp biển toàn thế giới khỏi nguy cơ bị xóa sổ hoàn toàn bởi Davy Jones cùng chiếc Flying Dutchman (lúc này đã trở thành tay sai của công ty Đông Ấn), Will Turner, Elizabeth Swann và thuyền trưởng Barbossa cùng nhau đi tìm đủ chín tên trùm cướp biển cùng đi tới tận cùng thế giới để giải cứu cho Jack và chống lại Davy Jones… Nổi bật lên trong phần 3 là cuộc chiến gay gắt giữa cái thiện và cái ác những phút sinh tử cận kề của các nhân vật góp phần tăng kịch tính cho phim. Nổi bật trong phần này là sự xuất hiện của hàng loạt nhân vật với quốc tịch khác nhau nổi bật trong đó là Châu Nhuận Phát đại diện của châu á. Cuối cùng là đại cảnh nơi tận cùng thế giới được xây dựng vô cùng đặc sắc.', 'After losing Captain Jack Sparrow to the locker of Davy Jones, Will Turner, Elizabeth Swann, and Captain Barbossa journey to the ends of the earth to rescue him. And as the East India Trading Company tightens its grip on the seas under Lord Cutler Beckett—now in control of Davy Jones—the fate of piracy hangs by a thread. Now, they must unite the pirate lords for one final stand. But as loyalties are tested and alliances shift, each must ultimately choose where they stand in the battle for freedom on the high seas.', 'https://image.tmdb.org/t/p/w780/7emxhn8tUIa3xaEDiFLrl7xORHN.jpg', 'https://image.tmdb.org/t/p/w1280/1jHxkVXMI5s3vRiyiZooUy1shB5.jpg', 'https://www.youtube.com/watch?v=HKSZtp_OGHY', 'Gore Verbinski', ARRAY['Johnny Depp', 'Geoffrey Rush', 'Orlando Bloom', 'Keira Knightley', 'Jack Davenport', 'Bill Nighy', 'Jonathan Pryce', 'Lee Arenberg']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Hành Động']::TEXT[], 169, '2007-05-19', NULL, 'US: PG-13', 7.3, 'ended'),
  ('eb3c8dc9-b7c4-5941-81bb-fa4c003e1d54'::UUID, 122917, 'Người Hobbit: Đại Chiến Năm Cánh Quân', 'The Hobbit: The Battle of the Five Armies', 'Tiếp nối ngay sau đoạn kết của phần hai, rồng Smaug bị thức tỉnh bởi nhóm phiêu lưu của Thorin và nổi giận bay tới tàn phá thị trấn bên hồ. Tuy nhiên, Smaug mau chóng bị cung thủ Bard tiêu diệt và Thorin nhờ đó giành lại được quê hương Erebor. Những tưởng mọi chuyện sẽ yên bình từ đây nhưng sự thất hứa của Thorin với người dân bên hồ và sự thù địch với tộc Tiên rừng mau chóng đẩy họ đến một trận chiến mới. Cùng lúc đó, liên minh Orc và sói ma Warg của tên Azog lầm lũi kéo đến ngọn Cô Sơn với toan tính chiếm lấy vị trí đắc địa và số vàng bên trong Erebor. Một trận giao tranh không khoan nhượng giữa năm đạo binh là điều không thể tránh khỏi.', 'Following Smaug''s attack on Laketown, Bilbo and the dwarves try to defend Erebor''s mountain of treasure from others who claim it: the men of the ruined Laketown and the elves of Mirkwood. Meanwhile an army of Orcs led by Azog the Defiler is marching on Erebor, fueled by the rise of the dark lord Sauron. Dwarves, elves and men must unite, and the hope for Middle-Earth falls into Bilbo''s hands.', 'https://image.tmdb.org/t/p/w780/nfMe2gv6jmUDoEL42TJvjwlvMPP.jpg', 'https://image.tmdb.org/t/p/w1280/3UbaCMmqOd7mca4Y5DOzY2ZVTyX.jpg', 'https://www.youtube.com/watch?v=Y6Fv5StfAxA', 'Peter Jackson', ARRAY['Ian McKellen', 'Martin Freeman', 'Richard Armitage', 'Orlando Bloom', 'Evangeline Lilly', 'Luke Evans', 'Lee Pace', 'Benedict Cumberbatch']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Giả Tưởng']::TEXT[], 144, '2014-12-10', NULL, 'US: PG-13', 7.3, 'ended'),
  ('6332ab17-718b-5c03-b154-1b3999085452'::UUID, 393, 'Cô Dâu Báo Thù 2', 'Kill Bill: Vol. 2', 'Phần 2 mở đầu với những sự kiện xảy ra trước vụ thảm sát tại thánh đường Two Pines, thành phố El Paso, bang Texas. Hôm đó, một đôi uyên ương tập dượt để chuẩn bị cho hôn lễ chính thức. Chú rể, Tommy, sở hữu một cửa hàng trong thành phố, còn cô dâu tên Arleen. Một người đàn ông trạc ngũ tuần tên Bill (David Carradine) xuất hiện trước mặt quan khách. Với phong thái lịch thiệp, vui vẻ, ông ta tự giới thiệu là cha của cô dâu. Arleen kéo Bill ra một chỗ khuất, cầu xin ông ta để cô yên trong ngày cưới và Bill tỏ vẻ đồng ý.', 'The Bride unwaveringly continues on her roaring rampage of revenge against the band of assassins who had tried to kill her and her unborn child. She visits each of her former associates one-by-one, checking off the victims on her Death List Five until there''s nothing left to do … but kill Bill.', 'https://image.tmdb.org/t/p/w780/yTgMqlQz13PC8PoXvDB3269FGhC.jpg', 'https://image.tmdb.org/t/p/w1280/pgG6tzJzC8mjGqhaT8IWwEk00xf.jpg', 'https://www.youtube.com/watch?v=q2h6EFk36kI', 'Quentin Tarantino', ARRAY['Uma Thurman', 'David Carradine', 'Daryl Hannah', 'Michael Madsen', 'Lưu Gia Huy', 'Michael Parks', 'Perla Haney-Jardine', 'Vivica A. Fox']::TEXT[], ARRAY['Hành Động', 'Tội Phạm', 'Giật Gân']::TEXT[], 136, '2004-04-16', NULL, 'US: R', 7.9, 'ended'),
  ('3589a798-e2d5-57e4-9a81-b3ec82035d9a'::UUID, 1865, 'Cướp Biển Vùng Caribbean: Suối Nguồn Tươi Trẻ', 'Pirates of the Caribbean: On Stranger Tides', 'Câu chuyện phim bắt đầu khi Jack Sparrow, đang tâp hợp thủy thủ đoàn để lên đường tìm tới Suối nguồn tươi trẻ, dòng suối đem lại sự sống cho người nào may mắn uống được. Chính tại nơi đây, Jack đã gặp lại Angelica, một nữ cướp biển vô cùng xinh đẹp mà anh đã từng gặp trong quá khứ. Jack bị Angelica ép đưa lên con tàu Revenge Queen Anne dưới sự điều khiển của cha cô - tên cướp biển dữ dằn Blackbeard. Sự thành công của cướp biển vùng Caribe đã mang tới thành công ngoài mong đợi cho Johnny Dept, anh đã từng được đề cử giải Oscar cho vai diễn của mình và trong phần 4 này Jack lại 1 lần nữa tái xuất tiếp tục mê hoặc khan giả bằng những hành động mạo hiểm nhưng đầy ngộ nghĩnh. Ngoài ra việc lựa chọn cảnh quay đẹp gần như nguyên sinh của Hawai khiến người xem không khỏi thán phục trước vẻ đẹp thơ mộng nơi đây.', 'When Jack crosses paths with a woman from his past, he''s not sure if it''s love...or if she''s a ruthless con artist using him to find the fabled Fountain of Youth.', 'https://image.tmdb.org/t/p/w780/nJonDNmaxQdQ961Yn5jZm4tdklU.jpg', 'https://image.tmdb.org/t/p/w1280/uzIGtyS6bbnJzGsPL93WCF1FWm8.jpg', 'https://www.youtube.com/watch?v=Ax6md6HoZ2o', 'Rob Marshall', ARRAY['Johnny Depp', 'Penélope Cruz', 'Geoffrey Rush', 'Ian McShane', 'Kevin McNally', 'Sam Claflin', 'Astrid Bergès-Frisbey', 'Stephen Graham']::TEXT[], ARRAY['Phiêu Lưu', 'Hành Động', 'Giả Tưởng']::TEXT[], 137, '2011-05-15', NULL, 'US: PG-13', 6.6, 'ended'),
  ('15cc9554-fb0c-5152-b03d-6b8c3049878b'::UUID, 150540, 'Những Mảnh Ghép Cảm Xúc', 'Inside Out', 'Phim Inside Out là bộ phim dài thứ 15 của Disney và Pixar kể về cô bé tuổi teen bình thường Riley. Như bao bạn bè đồng trang lứa khác, bước vào tuổi dậy thì là một quá trình gian nan với Riley, và cô bé còn bị thử thách bởi một biến cố bất ngờ khi buộc phải chia tay bạn bè, và cuộc sống hiện tại để cùng bố mẹ đến sống tại một thành phố hoàn toàn xa lạ.  Cũng như tất cả chúng ta, Riley chịu sự điều khiển của cảm xúc bên trong tâm trí mình, và với Inside Out, những cảm xúc đó đã được nhân cách hóa thành những nhân vật trên màn ảnh, đó là: Joy (Vui vẻ), Fear (Sợ sệt), Anger (Giận dữ), Sadness (Buồn bã) và Disgust (Chán ghét).', 'When 11-year-old Riley moves to a new city, her Emotions team up to help her through the transition. Joy, Fear, Anger, Disgust and Sadness work together, but when Joy and Sadness get lost, they must journey through unfamiliar places to get back home.', 'https://image.tmdb.org/t/p/w780/iSPYSsRnDVyLyWhoGOQA5V4vux4.jpg', 'https://image.tmdb.org/t/p/w1280/jJKZaTBNenlFclQyjrnvzkRmvWE.jpg', 'https://www.youtube.com/watch?v=1HFv47QHWJU', 'Pete Docter', ARRAY['Amy Poehler', 'Phyllis Smith', 'Richard Kind', 'Bill Hader', 'Lewis Black', 'Mindy Kaling', 'Kaitlyn Dias', 'Diane Lane']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Phiêu Lưu', 'Chính Kịch', 'Hài']::TEXT[], 95, '2015-06-17', NULL, 'US: PG', 7.9, 'ended'),
  ('5ff5af63-2e7d-51d6-9b17-359884aaa26a'::UUID, 14160, 'Vút Bay', 'Up', 'Ông già Carl quyết hoàn thành chuyến đi ấp ủ cả đời tới Thác thiên đường bằng ngôi nhà kết hàng nghìn quả bóng bay. Ngay khi vừa "cất cánh", ông phát hiện ra người đồng hành bất đắc dĩ: Cậu bé hướng đạo sinh Russell lắm mồm. Kể từ đây, cuộc phiêu lưu kì thú của 2 ông cháu diễn ra với biết bao bất ngờ cùng nguy hiểm rình rập...', 'Carl Fredricksen spent his entire life dreaming of exploring the globe and experiencing life to its fullest. But at age 78, life seems to have passed him by, until a twist of fate (and a persistent 8-year old Wilderness Explorer named Russell) gives him a new lease on life.', 'https://image.tmdb.org/t/p/w780/y8zhQBzsNt7cyLdYkOdPnzOL9Ez.jpg', 'https://image.tmdb.org/t/p/w1280/hGGC9gKo7CFE3fW07RA587e5kol.jpg', 'https://www.youtube.com/watch?v=Ajcdb4FAL7A', 'Pete Docter', ARRAY['Ed Asner', 'Christopher Plummer', 'Jordan Nagai', 'Bob Peterson', 'Delroy Lindo', 'Jerome Ranft', 'John Ratzenberger', 'David Kaye']::TEXT[], ARRAY['Hoạt Hình', 'Hài', 'Gia Đình', 'Phiêu Lưu']::TEXT[], 96, '2009-05-28', NULL, 'US: PG', 8, 'ended'),
  ('1af61c3c-91e9-5e93-b6dc-86f428f58a84'::UUID, 354912, 'Coco: Hội Ngộ Diệu Kỳ', 'Coco', 'Coco sẽ kể về hành trình của Miguel, một cậu bé say mê những giai điệu nhưng lại sinh trưởng trong một gia đình cấm đoán sự xuất hiện của âm nhạc. Miguel luôn nung nấu giấc mơ trở thành một nhạc sĩ nổi tiếng giống như thần tượng Ernesto de la Cruz. Tuy nhiên, truyền thống ngang trái của gia đình đã khiến cậu không thể chứng minh tài năng của mình.  Rũ bỏ thực tế phũ phàng, Miguel tìm thấy chính mình ở Vùng Đất Linh Hồn (Land of the Dead) tuyệt đẹp và đầy sắc màu sau một chuỗi sự kiện huyền bí. Trong hành trình khám phá vùng đất mới, Miguel gặp gỡ “chuyên gia xảo quyệt” Hector. Cả hai cùng tạo nên chuyến phiêu lưu kỳ diệu để lật mở những bí mật chưa được tiết lộ về lịch sử của gia đình Miguel.', 'Despite his family’s baffling generations-old ban on music, Miguel dreams of becoming an accomplished musician like his idol, Ernesto de la Cruz. Desperate to prove his talent, Miguel finds himself in the stunning and colorful Land of the Dead following a mysterious chain of events. Along the way, he meets charming trickster Hector, and together, they set off on an extraordinary journey to unlock the real story behind Miguel''s family history.', 'https://image.tmdb.org/t/p/w780/tKd5zI6gLBwrqqyicHyRD3IyosW.jpg', 'https://image.tmdb.org/t/p/w1280/g7CHF8gTLGooTbP4GznIGwaqAGL.jpg', 'https://www.youtube.com/watch?v=Rvr68u6k5sI', 'Lee Unkrich', ARRAY['Anthony Gonzalez', 'Gael García Bernal', 'Benjamin Bratt', 'Alanna Ubach', 'Renée Victor', 'Jaime Camil', 'Alfonso Arau', 'Herbert Siguenza']::TEXT[], ARRAY['Gia Đình', 'Hoạt Hình', 'Âm Nhạc', 'Phiêu Lưu']::TEXT[], 105, '2017-10-27', NULL, 'US: PG', 8.2, 'ended'),
  ('0c91b713-80c7-5c00-9802-d180c4524095'::UUID, 12, 'Đi Tìm Nemo', 'Finding Nemo', 'Nemo, một chú cá hề trẻ thích phiêu lưu, bất ngờ được đưa từ nhà Great Barrier Reef của mình đến một bể cá văn phòng của nha sĩ. Cha Marlin lo lắng và một chú cá thân thiện nhưng hay quên Dory mang Nemo về nhà - gặp gỡ cá mập ăn chay, lướt rùa rùa, sứa thôi miên, hải âu đói, và nhiều thứ khác trên đường đi.', 'Nemo, an adventurous young clownfish, is unexpectedly taken from his Great Barrier Reef home to a dentist''s office aquarium. It''s up to his worrisome father Marlin and a friendly but forgetful fish Dory to bring Nemo home -- meeting vegetarian sharks, surfer dude turtles, hypnotic jellyfish, hungry seagulls, and more along the way.', 'https://image.tmdb.org/t/p/w780/scAcBk4q6g8DWt8yryWlnc006ad.jpg', 'https://image.tmdb.org/t/p/w1280/eCynaAOgYYiw5yN5lBwz3IxqvaW.jpg', 'https://www.youtube.com/watch?v=SPHfeNgogVs', 'Andrew Stanton', ARRAY['Albert Brooks', 'Ellen DeGeneres', 'Alexander Gould', 'Willem Dafoe', 'Geoffrey Rush', 'Brad Garrett', 'Allison Janney', 'Austin Pendleton']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Phiêu Lưu']::TEXT[], 100, '2003-05-30', NULL, 'US: G', 7.8, 'ended'),
  ('c3ded3d2-069c-5706-9e6d-17ac75183a34'::UUID, 862, 'Câu Chuyện Đồ Chơi', 'Toy Story', 'Thế giới đồ chơi của cậu bé Andy bị xáo trộn khi có sự xuất hiện của cảnh sát vũ trụ Buzz Lightyear. Cảm thấy mình bị “thất sủng”, anh chàng cao bồi gỗ Woody xô xát với Buzz và cả hai bị rơi vào một cuộc phiêu lưu đầy mạo hiểm. Câu chuyện nói về thế giới đồ chơi của cậu bé...', 'Led by Woody, Andy''s toys live happily in his room until Andy''s birthday brings Buzz Lightyear onto the scene. Afraid of losing his place in Andy''s heart, Woody plots against Buzz. But when circumstances separate Buzz and Woody from their owner, the duo eventually learns to put aside their differences.', 'https://image.tmdb.org/t/p/w780/2k5424igOcC1rjJoME8WNREEOgy.jpg', 'https://image.tmdb.org/t/p/w1280/3Rfvhy1Nl6sSGJwyjb0QiZzZYlB.jpg', 'https://www.youtube.com/watch?v=CxwTLktovTU', 'John Lasseter', ARRAY['Tom Hanks', 'Tim Allen', 'Don Rickles', 'Jim Varney', 'Wallace Shawn', 'John Ratzenberger', 'Annie Potts', 'John Morris']::TEXT[], ARRAY['Gia Đình', 'Hài', 'Hoạt Hình', 'Phiêu Lưu']::TEXT[], 81, '1995-11-22', NULL, 'US: G', 8, 'ended'),
  ('52eb0fb2-26be-5926-9f79-37797396f1c2'::UUID, 585, 'Công Ty Quái Vật', 'Monsters, Inc.', 'Bộ phim nói về một ngôi làng chỉ toàn là Monsters sinh sống. Và trong ngôi làng đó có một xưởng sản xuất mang tên gọi là Monster, Inc. là một xưởng sản xuất điện cho cả thành phố. Còn điện thì đến từ... "tiếng thét" của các em bé bị các Monsters nhát ma. Và trong số những anh chàng Monsters thuộc hàng sao của hãng , chuyên thu thập nhiều điện nhất là Sulley và anh chàng một mắt bé xíu, một trợ lý đắc lực Mike... Thành phố này có cuộc sống bình thường cho đến một ngày... hai chàng gặp đối thủ của mình.... Và từ những tranh chấp đó, một cô bé con đã tình cờ lạc vào xứ sở Monster, gây nên nỗi kinh hoàng cho tất cả mọi người. Nhưng điều lý thú là cô bé này lại lạc vào tay anh chàng Monster nổi tiếng dữ dằn nhất...', 'Lovable Sulley and his wisecracking sidekick Mike Wazowski are the top scare team at Monsters, Inc., the scream-processing factory in Monstropolis. When a little girl named Boo wanders into their world, it''s the monsters who are scared silly, and it''s up to Sulley and Mike to keep her out of sight and get her back home.', 'https://image.tmdb.org/t/p/w780/6GR1pSdLBa2ktKizMogoW73n3US.jpg', 'https://image.tmdb.org/t/p/w1280/c7VbRPlev1bRfKvTxr98erw5T7B.jpg', 'https://www.youtube.com/watch?v=6tCxnHCqqxg', 'Pete Docter', ARRAY['John Goodman', 'Billy Crystal', 'Mary Gibbs', 'Steve Buscemi', 'James Coburn', 'Jennifer Tilly', 'Bob Peterson', 'John Ratzenberger']::TEXT[], ARRAY['Hoạt Hình', 'Hài', 'Gia Đình', 'Giả Tưởng']::TEXT[], 92, '2001-11-01', NULL, 'US: G', 7.9, 'ended'),
  ('c985bde6-a76f-5bf6-b34f-517020a0d837'::UUID, 8587, 'Vua Sư Tử', 'The Lion King', 'Lấy bối cảnh là khu vực rừng hoang Phi Châu, bộ phim đã xây dựng nên cả một xã hội có tổ chức của thế giới loài vật. Trong xã hội ấy cũng có những mâu thuẫn, cũng có tranh chấp và có cả tình yêu như thế giới loài người. Nhân vật chính của Vua sư tử là chú sư tử con Simba, con trai của Mufasa vị vua đang thống trị thế giới hoang dã ở đây. Cuộc sống hạnh phúc yêu đời bên cạnh cha mẹ và cô bạn Nala của cậu sớm chấm dứt khi người chú ruột Scar có âm mưu cướp ngai vàng của cha cậu....', 'Young lion prince Simba, eager to one day become king of the Pride Lands, grows up under the watchful eye of his father Mufasa; all the while his villainous uncle Scar conspires to take the throne for himself. Amid betrayal and tragedy, Simba must confront his past and find his rightful place in the Circle of Life.', 'https://image.tmdb.org/t/p/w780/AsGpIREstvwExc3UqczmIPP4pay.jpg', 'https://image.tmdb.org/t/p/w1280/wXsQvli6tWqja51pYxXNG1LFIGV.jpg', 'https://www.youtube.com/watch?v=lFzVJEksoDY', 'Roger Allers', ARRAY['Matthew Broderick', 'Moira Kelly', 'Jeremy Irons', 'Nathan Lane', 'Ernie Sabella', 'James Earl Jones', 'Robert Guillaume', 'Rowan Atkinson']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Chính Kịch']::TEXT[], 89, '1994-06-15', NULL, 'US: G', 8.3, 'ended'),
  ('f49e36db-dd77-545d-941a-6f1b316cad22'::UUID, 808, 'Shrek', 'Shrek', 'Vương quốc Xa thật xa là nơi các nhân vật cổ tích sinh sống. Shrek, gã chằn xanh đang sống yên bình tại đầm lầy của mình. Bỗng nhiên, khu đầm trở thành nơi "tị nạn" của các nhân vật cổ tích đang bị lãnh chúa Farquaad săn đuổi. Để khỏi phải "chung đụng" với đám dân ở nhờ ồn ào, Shrek ký giao kèo cùng Farquaad. Gã sẽ đi cứu công chúa Fiona, đang bị giam giữ trong tòa tháp cao vợi, và được rồng canh giữ. Farquaad có được cô dâu trong mộng thì Farquaad phải để các nhân vật cổ tích kia được yên.', 'It ain''t easy bein'' green -- especially if you''re a likable (albeit smelly) ogre named Shrek. On a mission to retrieve a gorgeous princess from the clutches of a fire-breathing dragon, Shrek teams up with an unlikely compatriot -- a wisecracking donkey.', 'https://image.tmdb.org/t/p/w780/iB64vpL3dIObOtMZgX3RqdVdQDc.jpg', 'https://image.tmdb.org/t/p/w1280/w0eKUOEog2ImtktCHAMUZws8qif.jpg', 'https://www.youtube.com/watch?v=ppDwfm6e498', 'Andrew Adamson', ARRAY['Mike Myers', 'Eddie Murphy', 'Cameron Diaz', 'John Lithgow', 'Vincent Cassel', 'Peter Dennis', 'Clive Pearse', 'Jim Cummings']::TEXT[], ARRAY['Hoạt Hình', 'Hài', 'Giả Tưởng', 'Phiêu Lưu', 'Gia Đình']::TEXT[], 90, '2001-05-18', NULL, 'US: PG', 7.8, 'ended'),
  ('5e9e0536-e97e-5603-aff4-242812752b5e'::UUID, 2062, 'Chú Chuột Đầu Bếp', 'Ratatouille', 'Remy là một chú chuột có lòng yêu thích ẩm thực và mong muốn được đến Paris để thực hiện ước mơ trở thành đầu bếp nổi tiếng. Tuy bị gia đình ngăn cản nhưng cuối cùng Remy cũng đặt chân được đến kinh đô ánh sáng và bắt đầu cuộc phiêu lưu của mình.  Tại đây, Remy quen Linguini - cậu con trai của thần tượng đồng thời là bếp trưởng nổi tiếng của nhà hàng Gusteau. Remy và Linguini trở thành cặp bài trùng trong việc chế biến các món ăn mới lạ, đồng thời chứng mình quan niệm của Gusteau: "Ai cũng có thể nấu ăn ngon".', 'In one of Paris''s finest restaurants, Remy, a determined young rat, dreams of becoming a renowned French chef. Torn between his family''s wishes and his true calling, Remy and his pal Linguini set in motion a hilarious chain of events that turns the City of Lights upside down.', 'https://image.tmdb.org/t/p/w780/rkrU5jFUJ02NAxoU2GVdWsd1Hh6.jpg', 'https://image.tmdb.org/t/p/w1280/zeoaHdXRDd5IoUiMVsNhwTZm78B.jpg', 'https://www.youtube.com/watch?v=NgsQ8mVkN8w', 'Brad Bird', ARRAY['Patton Oswalt', 'Lou Romano', 'Ian Holm', 'Brian Dennehy', 'Peter Sohn', 'Peter O''Toole', 'Brad Garrett', 'Janeane Garofalo']::TEXT[], ARRAY['Hoạt Hình', 'Hài', 'Gia Đình', 'Giả Tưởng']::TEXT[], 111, '2007-06-28', NULL, 'US: G', 7.9, 'ended'),
  ('f702057d-ed34-5a4a-b894-3ed0d8e65ea7'::UUID, 269149, 'Phi Vụ Động Trời', 'Zootopia', 'Trong phim này, Zootopia là một thành phố kì lạ không giống bất kì thành phố nào trước đây của hãng Walt Disney sáng chế. Đây là khu đô thị vui vẻ của các loài động vật, từ voi, tê giác, cho đến những loài nhỏ bé như chuột, thỏ, cún. Cho đến một ngày cô cảnh sát thỏ Judy Hopps xuất hiện, thành phố Zootopia đã có những thay đổi rất là khác. Cô cùng người bạn đồng hành là chú cáo đầy “tiểu xảo” Nick Widle, đã cùng nhau phiêu lưu trong một vụ kỳ án, với mong muốn thiết lập lại trật tự cho thành phố zootopia.', NULL, 'https://image.tmdb.org/t/p/w780/oy5mQVAmswPFwLGsDFclJvlZRkc.jpg', 'https://image.tmdb.org/t/p/w1280/9tOkjBEiiGcaClgJFtwocStZvIT.jpg', 'https://www.youtube.com/watch?v=UWZMTg84inA', 'Byron Howard', ARRAY['Ginnifer Goodwin', 'Jason Bateman', 'Idris Elba', 'Jenny Slate', 'Nate Torrence', 'Bonnie Hunt', 'Don Lake', 'Tommy Chong']::TEXT[], ARRAY['Hoạt Hình', 'Phiêu Lưu', 'Gia Đình', 'Hài']::TEXT[], 109, '2016-02-11', NULL, 'US: PG', 7.8, 'ended'),
  ('c0ef2ddb-5fed-5702-ada1-231267ddef4e'::UUID, 109445, 'Nữ Hoàng Băng Giá', 'Frozen', 'Có thể nhiều người sẽ ao ước sở hữu phép thuật, song đó chắc chắn không phải nàng công chúa Elsa. Ngay từ nhỏ, cô đã có khả năng kỳ diệu là tạo ra băng tuyết cũng như điều khiển những con gió. Nhưng chính khả năng ấy đã vô tình gây thương tích cho em gái Anna. Anna được các quỷ lùn chữa trị và cái giá phải trả là cô bé hoàn toàn quên mất việc chị mình có năng lực đặc biệt. Không những thế, đức vua và hoàng hậu còn phải cách ly Elsa trong căn phòng kín để phép thuật của cô không phát tác, khiến tuổi thơ hai chị em Elsa và Anna bị tách rời.', 'Young princess Anna of Arendelle dreams about finding true love at her sister Elsa’s coronation. Fate takes her on a dangerous journey in an attempt to end the eternal winter that has fallen over the kingdom. She''s accompanied by ice delivery man Kristoff, his reindeer Sven, and snowman Olaf. On an adventure where she will find out what friendship, courage, family, and true love really means.', 'https://image.tmdb.org/t/p/w780/9uo216MV8xtYTKLQbXewbV3MsJP.jpg', 'https://image.tmdb.org/t/p/w1280/rj58WQ9ImI0mYDptXdM7euX1Wjt.jpg', 'https://www.youtube.com/watch?v=TbQm5doF_Uc', 'Chris Buck', ARRAY['Kristen Bell', 'Idina Menzel', 'Jonathan Groff', 'Josh Gad', 'Santino Fontana', 'Alan Tudyk', 'Ciarán Hinds', 'Chris Williams']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Phiêu Lưu', 'Giả Tưởng']::TEXT[], 102, '2013-11-20', NULL, 'US: PG', 7.2, 'ended'),
  ('999b50b2-2c17-5f02-a827-e5a3ebca4839'::UUID, 10193, 'Câu Chuyện Đồ Chơi 3', 'Toy Story 3', 'Cậu bé Andy ngày nào nay đã trở thành người lớn sắp sửa phải bước vào ngưỡng cửa đại học. Đống đồ chơi của cậu, bao gồm cả Woody và Buzz Lightyear, bị đưa vào nhà kho. Và trước khi chúng bị tống lên gác mái, bố mẹ cậu vô tình ném chúng đi. Kết quả là một người dọn rác đã đem những món đồ chơi đó đến Sunnyside, một trung tâm vui chơi dành cho trẻ em, và khi tiếng hô “Đồ chơi mới!” được cất lên là lũ trẻ xông vào tranh giành nhau Ken, Barbie, ông Đầu khoai tây và Buzz Lightyear… Vừa cố gắng tồn tại ở trường tiểu học đáng sợ đó, những nhân vật đồ chơi của chúng ta vừa tìm cách quay trở lại ngôi nhà thân thương nơi có cậu chủ Andy vẫn đang chờ đợi chúng. Trải qua rất nhiều chuyến phiêu lưu, cuối cùng họ cũng được trở về nhà, một đoạn kết thực sự cảm động khiến mọi người không cầm được nước mắt trước tình cảm gắn bó của Andy và những món đồ chơi…', 'Woody, Buzz, and the rest of Andy''s toys haven''t been played with in years. With Andy about to go to college, the gang find themselves accidentally left at a nefarious day care center. The toys must band together to escape and return home to Andy.', 'https://image.tmdb.org/t/p/w780/1X96GIP5RAErgDXjH0ZP1anv0m1.jpg', 'https://image.tmdb.org/t/p/w1280/wE5JGzujfvDPMIfFjJyrhXFjZLc.jpg', 'https://www.youtube.com/watch?v=6c3K7LhA9Yc', 'Lee Unkrich', ARRAY['Tom Hanks', 'Tim Allen', 'Joan Cusack', 'Don Rickles', 'Wallace Shawn', 'John Ratzenberger', 'Estelle Harris', 'Blake Clark']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Hài']::TEXT[], 103, '2010-06-16', NULL, 'US: G', 7.8, 'ended'),
  ('75673168-6e95-52e2-9941-c2b488d87c6f'::UUID, 920, 'Vương Quốc Xe Hơi', 'Cars', 'McQueen Tia chớp khoác trên mình lớp sơn đỏ rực, rất sung sức, tự mãn và thường trực nụ cười mỉa mai. Lao vun vút trên đường 66 tới California để tranh cúp Piston, cậu đã đâm sầm vào thị trấn Radiator Springs buồn tẻ, phá nát đường đi và suýt bị ngồi tù. Chỉ vài ngày nữa, anh chàng phải tham gia cuộc đua, mong được đại gia Dinoco tài trợ để trở thành "sao". Nhờ sáng kiến của cô nàng luật sư Sally - một chiếc Porsche bóng bẩy đời 2002 - McQueen phải đem thân hình công tử ra kéo chiếc xe rải nhựa khổng lồ để làm lại đường. Cậu làm quen với bác sĩ Hudson, một chiếc Hudson Hornet đời 1951 từng là huyền thoại của đường đua Piston. Ngoài ra còn có Mater chiếc xe tải cũ mèm, gỉ sét và vui tính. Từ thị trấn nhỏ bé này, McQueen đã nhận ra nhiều điều ý nghĩa trong cuộc sống.', 'Lightning McQueen, a hotshot rookie race car driven to succeed, discovers that life is about the journey, not the finish line, when he finds himself unexpectedly detoured in the sleepy Route 66 town of Radiator Springs. On route across the country to the big Piston Cup Championship in California to compete against two seasoned pros, McQueen gets to know the town''s offbeat characters.', 'https://image.tmdb.org/t/p/w780/6VIxYR9dYeSgBqoR95fk1jnccRy.jpg', 'https://image.tmdb.org/t/p/w1280/sd4xN5xi8tKRPrJOWwNiZEile7f.jpg', 'https://www.youtube.com/watch?v=XszNWHhpaTc', 'John Lasseter', ARRAY['Owen Wilson', 'Paul Newman', 'Bonnie Hunt', 'Larry the Cable Guy', 'Cheech Marin', 'Tony Shalhoub', 'Guido Quaroni', 'Jenifer Lewis']::TEXT[], ARRAY['Hoạt Hình', 'Phiêu Lưu', 'Hài', 'Gia Đình']::TEXT[], 117, '2006-06-08', NULL, 'US: G', 7.1, 'ended'),
  ('6fd9f849-889b-5b38-9c89-8057ef707cb1'::UUID, 863, 'Câu Chuyện Đồ Chơi 2', 'Toy Story 2', 'Câu Chuyện Đồ Chơi 2 là cuộc phiêu lưu của Woody (Tom Hanks lồng tiếng) và Buzz Lightyear (Tim Allen) lại tiếp tục khi chủ nhân của chúng Andy (John Morris) đi tham dự trại hè và để mặc chúng ở nhà tự lo liệu. Woody không may bị một tay buôn bán đồ chơi đánh cắp. Buzz cùng các bạn đồ chơi bèn tìm cách giải cứu Woody. Mọi chuyện tưởng chừng thuận lợi nhưng trong khi bị giam giữ, Woody quen được Jessy - một tay "cowgirl". Thế là cả nhóm quyết định đưa luôn Jessy trở về nhà... sau khi trải qua bao khó khăn.', 'Andy heads off to Cowboy Camp, leaving his toys to their own devices. Things shift into high gear when an obsessive toy collector named Al McWhiggen, owner of Al''s Toy Barn kidnaps Woody. Andy''s toys mount a daring rescue mission, Buzz Lightyear meets his match and Woody has to decide where he and his heart truly belong.', 'https://image.tmdb.org/t/p/w780/9bd3PHt2hZ3DDMRjn28Pmd6ZHqt.jpg', 'https://image.tmdb.org/t/p/w1280/nsfVr4QbbunUrHINN9N7JdVAMTf.jpg', 'https://www.youtube.com/watch?v=xNWSGRD5CzU', 'John Lasseter', ARRAY['Tom Hanks', 'Tim Allen', 'Joan Cusack', 'Kelsey Grammer', 'Don Rickles', 'Jim Varney', 'Wallace Shawn', 'John Ratzenberger']::TEXT[], ARRAY['Hoạt Hình', 'Hài', 'Gia Đình']::TEXT[], 92, '1999-10-30', NULL, 'US: G', 7.6, 'ended'),
  ('3eaa6e6b-e2c5-5a55-8e70-9b6e28b89ae0'::UUID, 10191, 'Bí Kíp Luyện Rồng', 'How to Train Your Dragon', 'Thiếu niên nhút nhát Hiccup phải chứng minh với bố và làng của mình rằng cậu vẫn có thể là chiến binh Viking – ngay cả khi cậu muốn kết bạn với rồng hơn là giết rồng.', 'As the son of a Viking leader on the cusp of manhood, shy Hiccup Horrendous Haddock III faces a rite of passage: he must kill a dragon to prove his warrior mettle. But after downing a feared dragon, he realizes that he no longer wants to destroy it, and instead befriends the beast – which he names Toothless – much to the chagrin of his warrior father.', 'https://image.tmdb.org/t/p/w780/300DPr2twGhwhcKbL6aYkhOUYFs.jpg', 'https://image.tmdb.org/t/p/w1280/59vDC1BuEQvti24OMr0ZvtAK6R1.jpg', 'https://www.youtube.com/watch?v=KZtbJ_I9IFM', 'Chris Sanders', ARRAY['Jay Baruchel', 'Gerard Butler', 'Craig Ferguson', 'America Ferrera', 'Jonah Hill', 'Christopher Mintz-Plasse', 'T.J. Miller', 'Kristen Wiig']::TEXT[], ARRAY['Giả Tưởng', 'Phiêu Lưu', 'Hoạt Hình', 'Gia Đình']::TEXT[], 98, '2010-03-18', NULL, 'US: PG', 7.9, 'ended'),
  ('92d9cac4-5908-59c8-8b8d-06d238977bc0'::UUID, 425, 'Kỷ Băng Hà', 'Ice Age', 'Giữa thời điểm sắp chuyển sang chuyển sang kỷ băng giá, mọi con vật đều đi kiếm nơi ấm áp để sống. Manny, Sid, Diego phải theo bước chân con người để đưa 1 cậu bé bị lạc trở về với gia đình...nhưng Diego lại có một âm mưu khác để bắt chú bé đi vì Diego là 1 chú cọp nhận nhiệm vụ bắt sống đứa bé về cho Soto... Nhưng suốt quá trình trải qua những khó khăn cùng nhau 3 người bạn đã có được những tình cảm thật thân thiết để rồi cùng nhau chống lại đàn cọp gian ác.', 'Manny the mammoth, Sid the loquacious sloth, and Diego the sabre-toothed tiger go on a comical quest to return a human baby back to his father, across a world on the brink of an ice age.', 'https://image.tmdb.org/t/p/w780/kFpRkrxfHzQmO4cJaS7PrQEnFRo.jpg', 'https://image.tmdb.org/t/p/w1280/tyVAGH1vw9JDgxPyTUQPn91nIYc.jpg', 'https://www.youtube.com/watch?v=i4noiCRJRoE', 'Chris Wedge', ARRAY['Ray Romano', 'John Leguizamo', 'Denis Leary', 'Goran Višnjić', 'Jack Black', 'Cedric the Entertainer', 'Stephen Root', 'Diedrich Bader']::TEXT[], ARRAY['Hoạt Hình', 'Hài', 'Gia Đình', 'Phiêu Lưu']::TEXT[], 81, '2002-03-14', NULL, 'US: PG', 7.4, 'ended'),
  ('e77333fa-964f-5e76-a5a1-dd3e972f5bd9'::UUID, 62177, 'Công Chúa Tóc Xù', 'Brave', 'Công Chúa Tóc Xù xoay quanh nhân vật chính công chúa Merida. Từ nhỏ cô đã tỏ ra là người ngang bướng không thích những nề nếp chốn cung đình. Một ngày, hoàng hậu tổ chức kén phò mã cho Merida. Không chấp nhận sự sắp đặt Merida đã bỏ vương quốc ra đi. Trên đường đi cuộc gặp gỡ định mệnh với mụ phù thủy già đã đưa cô vào những cuộc phiêu lưu đầy hiểm nguy. Trong phim, Brave được đánh giá cao ở khía cạnh nhân văn, đề cao tình cảm gia đình, lòng quả cảm. Thông qua hình ảnh cô công chúa Merida bướng bỉnh người xem liên tưởng tới những cô bé, cậu bé tuổi teen bướng bỉnh mà mình đã gặp đâu đó, với tạo hình nhân vật khá đặc sắc ngộ nghĩnh Brave đã làm thỏa mãn sự háo hức của các Fan nhí. Bên cạnh đó những nhạc khúc Scotlen đã tạo ra điểm nhấn đặc biệt cho phim.', 'In the mystical Scottish Highlands, Merida is the princess of a kingdom ruled by King Fergus and Queen Elinor. An unruly daughter and an accomplished archer, Merida one day defies a sacred custom of the land and inadvertently brings turmoil to the kingdom. In an attempt to set things right, Merida seeks out an eccentric old Wise Woman and is granted an ill-fated wish.', 'https://image.tmdb.org/t/p/w780/iexNj6uxbTG0zz6TLuzwKetFxr7.jpg', 'https://image.tmdb.org/t/p/w1280/qx9ts2hBYJrkIQxhryitxnLlm2u.jpg', 'https://www.youtube.com/watch?v=OKdLpBLp3nM', 'Brenda Chapman', ARRAY['Kelly Macdonald', 'Emma Thompson', 'Billy Connolly', 'Julie Walters', 'Robbie Coltrane', 'Kevin McKidd', 'Craig Ferguson', 'Peigi Barker']::TEXT[], ARRAY['Phiêu Lưu', 'Hoạt Hình', 'Gia Đình', 'Giả Tưởng']::TEXT[], 90, '2012-06-21', NULL, 'US: PG', 7, 'ended'),
  ('caf4ed74-53d8-56a9-bc91-bf2a3d925f41'::UUID, 277834, 'Hành Trình Của Moana', 'Moana', 'Ở một ngôi làng giữa biển khơi - có một cô bé đầy dũng mãnh, gan dạ, khao khát tự do và luôn tìm đến miền biển khơi, nhưng lại bị người làng ngăn cản - chính là Moana. Thế nhưng rồi, bóng tối hiện về, hòn đảo chết dần, cô được biển khơi trao tặng sứ mệnh vượt đại dương, trả lại trái tim cho Te Fiti, để cứu lấy nhân loại. Xuyên suốt đồng hành trên chuyến đi là Á Thần Maui - kẻ đã gây ra sai lầm trong quá khứ và chú gà HeiHei ngốc nghếch. Hành trình đầy giông bão và khó khăn, Moana và Maui sẽ vượt qua như thế nào ?!', NULL, 'https://image.tmdb.org/t/p/w780/q5WGt3Uz76NDcWoWM8bU69lVkc5.jpg', 'https://image.tmdb.org/t/p/w1280/qLVNZFHYUR6Li64He67SWl6BHQe.jpg', 'https://www.youtube.com/watch?v=qXmzjzS7H64', 'John Musker', ARRAY['Auliʻi Cravalho', 'Dwayne Johnson', 'Rachel House', 'Temuera Morrison', 'Jemaine Clement', 'Nicole Scherzinger', 'Alan Tudyk', 'Louise Bush']::TEXT[], ARRAY['Phiêu Lưu', 'Hài', 'Gia Đình', 'Hoạt Hình']::TEXT[], 107, '2016-10-13', NULL, 'US: PG', 7.6, 'ended'),
  ('04b2a837-5254-5ce2-a6fe-7ff648dd5dfc'::UUID, 260513, 'Gia Đình Siêu Nhân 2', 'Incredibles 2', 'Gia đình siêu nhân 2 kể về những cuộc phiêu lưu của gia đình siêu nhân Incredible khi họ tiếp tục đối đầu với những xáo trộn mới trong cuộc sống. Người vợ Helen sẽ ra ngoài giải cứu thế giới còn Mr. Incredible phải ở nhà trông con. Phải xử lý bài tập toán của con trai, giải quyết chuyện hẹn hò cho con gái và nhất là chăm sóc cậu con út có siêu năng lực mạnh nhất nhà, quý ngài siêu anh hùng phải giải quyết sao đây?', 'Elastigirl springs into action to save the day, while Mr. Incredible faces his greatest challenge yet – taking care of the problems of his three children.', 'https://image.tmdb.org/t/p/w780/cpieGMvmBOvjfMX69PkAM4PuW2X.jpg', 'https://image.tmdb.org/t/p/w1280/mabuNsGJgRuCTuGqjFkWe1xdu19.jpg', 'https://www.youtube.com/watch?v=i5qOzqD9Rms', 'Brad Bird', ARRAY['Craig T. Nelson', 'Holly Hunter', 'Sarah Vowell', 'Huck Milner', 'Catherine Keener', 'Eli Fucile', 'Bob Odenkirk', 'Samuel L. Jackson']::TEXT[], ARRAY['Hành Động', 'Phiêu Lưu', 'Hoạt Hình', 'Gia Đình']::TEXT[], 118, '2018-06-14', NULL, 'US: PG', 7.5, 'ended'),
  ('421688c2-6c93-5dd8-b93f-f2c5fb8f6223'::UUID, 809, 'Shrek 2', 'Shrek 2', 'Sau khi đánh bại con rồng lửa và lãnh chúa Farquaad để giành lấy trái tim của công chúa Fiona; gã chằn tinh Shrek giờ sống cuộc sống yên bình. Cả hai trải qua kỳ nghỉ trăng mật đầy lãng mạn. Cơn ác mộng thực sự đến khi quốc vương và hoàng hậu xứ Xa thật xa vời hai con về gặp mặt. Cùng với Lừa lắm mồm, đôi vợ chồng trẻ quay về kinh thành náo nhiệt. Kinh thành thân quen chào đón công chúa Fiona, xong không ai ngờ chàng phò mã là... chằn tinh. Còn cô công chúa yểu điệu ngày nào giờ cũng trong bộ dạng phục phịch xanh lét như chồng. Chàng rể trái ý quốc vương đã khiến Bà tiên đỡ đầu, Hoàng tử quyến rũ và tên sát thủ Mèo đi hia vào cuộc nhằm... thủ tiêu Shrek để lập phò mã mới!', 'Happily ever after never seemed so far far away when a trip to meet the in-laws turns into a hilariously twisted adventure for Shrek and Fiona. With the help of ever-faithful Donkey, Shrek takes on the potion-brewing Fairy Godmother, pompous Prince Charming, and infamous ogre-killer Puss In Boots.', 'https://image.tmdb.org/t/p/w780/2yYP0PQjG8zVqturh1BAqu2Tixl.jpg', 'https://image.tmdb.org/t/p/w1280/8ohobj5lAIbl5XWw11FywS3IRrS.jpg', 'https://www.youtube.com/watch?v=iuNghO1XsHI', 'Conrad Vernon', ARRAY['Mike Myers', 'Eddie Murphy', 'Cameron Diaz', 'Julie Andrews', 'Antonio Banderas', 'John Cleese', 'Rupert Everett', 'Jennifer Saunders']::TEXT[], ARRAY['Hoạt Hình', 'Hài', 'Gia Đình', 'Giả Tưởng', 'Lãng Mạn']::TEXT[], 92, '2004-05-19', NULL, 'US: PG', 7.3, 'ended'),
  ('d1111dbd-a942-5f93-90af-0d11d39b9810'::UUID, 82690, 'Ralph Đập Phá', 'Wreck-It Ralph', 'Ralph – anh chàng chuyên đóng vai kẻ ác trong trò chơi Fix - It Felix nổi tiếng, sau hàng thập kỷ lặp lại những công việc nhàm chán và phải làm nền cho Felix, Ralph quyết định rời bỏ trò chơi đã gắn bó 30 năm vào dấn thân vào cuộc phiêu lưu trong thế giới game, đi tìm chiếc huy chương vàng để chứng tỏ mình có những tố chất của một người hùng…  Thông qua câu chuyện của Ralph, phim đã mang đến một chân lý giản đơn dành cho tất cả mọi người: “Quan trọng không phải bạn tốt hay xấu, không phải bạn là ai, mà bạn sẽ làm gì cho cuộc sống”. Đặc biệt, với những ai từng say mê trò chơi điện tử , Wreck-It-Ralph sẽ giúp khán giả sống lại thời kỳ hoàng kim của những trò chơi điện tử bốn nút, máy chơi game bằng xèng có đồ họa đơn sơ năm xưa.', NULL, 'https://image.tmdb.org/t/p/w780/phSig3M0vtzNPmnZQI9umtbMk0c.jpg', 'https://image.tmdb.org/t/p/w1280/3IFRjBDwtk0DlIsDfJ2zEzLjUBi.jpg', 'https://www.youtube.com/watch?v=Wx9UHpMCoJk', 'Rich Moore', ARRAY['John C. Reilly', 'Sarah Silverman', 'Jack McBrayer', 'Jane Lynch', 'Alan Tudyk', 'Rich Moore', 'Raymond S. Persi', 'Mindy Kaling']::TEXT[], ARRAY['Gia Đình', 'Hoạt Hình', 'Hài', 'Phiêu Lưu']::TEXT[], 101, '2012-11-01', NULL, 'US: PG', 7.4, 'ended'),
  ('6ac37f1b-2dd2-52a1-8e3b-48df40ed334d'::UUID, 9502, 'Kung Fu Gấu Trúc', 'Kung Fu Panda', 'Khi kẻ xấu hùng mạnh phá hoại sự bình yên ở thung lũng của cậu, chú gấu trúc lười nhác đón nhận thử thách để đi theo định mệnh của mình – trở thành một võ hiệp.', 'Chosen by prophecy but doubted by all, Po is an unlikely choice for the mystical title of the Dragon Warrior—a clumsy panda thrust into the world of kung fu as a deadly enemy threatens the Valley of Peace. Under reluctant guidance by Master Shifu and the Furious Five, Po must embrace who he is to unlock the power that no scroll can teach.', 'https://image.tmdb.org/t/p/w780/tfdrBWUU9geZULfRYty5J9EINvw.jpg', 'https://image.tmdb.org/t/p/w1280/qdthf9WrRDSaIkGVQGhhJ9pz1hn.jpg', 'https://www.youtube.com/watch?v=NRc-ze7Wrxw', 'Mark Osborne', ARRAY['Jack Black', 'Dustin Hoffman', 'Angelina Jolie', 'Ian McShane', 'Seth Rogen', 'Lucy Liu', 'David Cross', 'Randall Duk Kim']::TEXT[], ARRAY['Hành Động', 'Hoạt Hình', 'Hài', 'Gia Đình']::TEXT[], 90, '2008-06-04', NULL, 'US: PG', 7.3, 'ended'),
  ('acf1c50c-b489-554f-9919-56d6280aa921'::UUID, 127380, 'Đi Tìm Dory', 'Finding Dory', '13 năm trước, Finding Nemo từng cuốn hút khán giả với một câu chuyện cuốn hút và đầy cảm xúc. Bộ phim này từng gắn liền với tuổi thơ của một thế hệ khán giả. 13 năm sau, bộ ba Marlin, Nemo và Dory tiếp tục đưa người xem vào một chuyến đi thú vị không kém và chắc chắn nó sẽ lại gắn liền với một thế hệ khán giả mới.  Nhân vật chính của câu chuyện lần này không phải bố con Marlin & Nemo nữa mà là cô nàng Dory. Những mảnh ghép kí ức vụn vặt chợt này ra trong đầu Dory đã thôi thúc cô đi tìm gia đình của mình. Chính điều này đã đưa Dory lạc tới một viện hải dương học ở bên kia đại dương khiến bố con Nemo phải lên đường giải cứu người bạn của mình.', 'Dory is reunited with her friends Nemo and Marlin in the search for answers about her past. What can she remember? Who are her parents? And where did she learn to speak Whale?', 'https://image.tmdb.org/t/p/w780/anGL2m23t2rxDL4upd3mSPY5br5.jpg', 'https://image.tmdb.org/t/p/w1280/wijltj1toRcicHlCn8Cpsp4yPXe.jpg', 'https://www.youtube.com/watch?v=NQu-153MnGQ', 'Andrew Stanton', ARRAY['Ellen DeGeneres', 'Albert Brooks', 'Ed O''Neill', 'Hayden Rolence', 'Diane Keaton', 'Eugene Levy', 'Ty Burrell', 'Kaitlin Olson']::TEXT[], ARRAY['Phiêu Lưu', 'Hoạt Hình', 'Gia Đình']::TEXT[], 97, '2016-06-16', NULL, 'US: PG', 7, 'ended'),
  ('648c011c-5140-56d4-86d9-357099245513'::UUID, 38757, 'Công Chúa Tóc Mây', 'Tangled', 'Rapunzel - nàng công chúa có mái tóc dài thần kì bị nhốt suốt 18 năm trời trên ngọn tháp cao chót vót bởi một mụ phù thủy. Mọi chuyện trở nên kịch tính khi tên trộm tinh quái và quyến rũ nhất vương quốc - Flynn Rider - trong cuộc chạy trốn khỏi binh lính triều đình, tình cờ rơi vào ngọn tháp của Rapunzel. Từ đây cô công chúa thơ dại đã bắt đầu chuyến phiêu lưu trốn chạy khỏi ngọn tháp u tối để tìm lại cuộc sống đích thực của chính mình.', 'Feisty teenager Rapunzel, who has long and magical hair, wants to go and see sky lanterns on her eighteenth birthday, but she''s bound to a tower by her overprotective mother. She strikes a deal with Flynn Rider, a charming wanted thief, and the duo set off on an action-packed escapade.', 'https://image.tmdb.org/t/p/w780/9Dk3NpFxRY47kbQMrMBzS4oIH68.jpg', 'https://image.tmdb.org/t/p/w1280/cWczNud8Y8i8ab0Z4bxos4myWYO.jpg', 'https://www.youtube.com/watch?v=gsYKF8ecC8g', 'Nathan Greno', ARRAY['Mandy Moore', 'Zachary Levi', 'Donna Murphy', 'Ron Perlman', 'M.C. Gainey', 'Jeffrey Tambor', 'Brad Garrett', 'Paul F. Tompkins']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Phiêu Lưu']::TEXT[], 100, '2010-11-24', NULL, 'US: PG', 7.6, 'ended'),
  ('af1c3a3e-980b-5bab-8003-b99bc9f44f50'::UUID, 812, 'Aladdin và Cây Đèn Thần', 'Aladdin', 'Aladdin là bộ phim hoạt hình dựa theo câu chuyện trong Ngàn lẻ một đêm. Bộ phim kể về Aladdin, một thanh niên vô gia cư sống lang thang bên đường phố Agrabah. vô tình có được cây đèn thần kỳ diệu. Nhờ có vị thần đèn vui tính, Aladdin từ một kẻ mồ côi, lang thang đã có tất cả nhưng gì anh mơ ước như của cải và cô công chúa xinh đẹp. Nhưng một tên phù thủy gian ác đang âm mưu phá hoại cuộc sống của Aladdin bằng cách chiếm đoạt lại cây đèn thần này, và bắt công chúa người nah yêu đi. Aladdin sẽ phải làm gì đây?', 'In the boorish city of Agrabah, kind-hearted street urchin Aladdin and Princess Jasmine fall in love, although she can only marry a prince. He and power-hungry Grand Vizier Jafar vie for a magic lamp that can fulfill their wishes.', 'https://image.tmdb.org/t/p/w780/eLFfl7vS8dkeG1hKp5mwbm37V83.jpg', 'https://image.tmdb.org/t/p/w1280/nenJjvfe2Eq8uBMXFJnWj5mw4bi.jpg', 'https://www.youtube.com/watch?v=XBrfbWtmvWs', 'Ron Clements', ARRAY['Scott Weinger', 'Robin Williams', 'Linda Larkin', 'Jonathan Freeman', 'Gilbert Gottfried', 'Douglas Seale', 'Frank Welker', 'Brad Caleb Kane']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Phiêu Lưu', 'Giả Tưởng', 'Lãng Mạn']::TEXT[], 91, '1992-11-25', NULL, 'US: G', 7.7, 'ended'),
  ('f812acd2-195b-55c2-8427-ddb5e64e2da5'::UUID, 93456, 'Kẻ Trộm Mặt Trăng 2', 'Despicable Me 2', 'Trong Despicable Me 2, nhân vật Gru rũ bỏ quá khứ là một tên trộm tinh quái để toàn tâm nuôi dạy 3 cô con gái là Margo, Edith và Agnes. Thế nhưng ngay khi Gru quyết định lui về với gia đình và trở thành một người cha mẫu mực thì một tổ chức bí mật với quy mô toàn cầu đến gõ cửa. Gru cùng với cộng sự mới của anh - Lucy cùng bắt tay tham gia vào cuộc truy tìm xem ai là kẻ đứng sau chuỗi những phi vụ âm mưu đình đám đang diễn ra. Và thế là, quái kiệt Gru một thời lại trở lại với thế giới để khẳng định vị trí bất khả chiến bại của mình.', NULL, 'https://image.tmdb.org/t/p/w780/6hZYQICnpjHSIYA4Nvy7nqTG4GM.jpg', 'https://image.tmdb.org/t/p/w1280/uD267eSiACfWLxp47t3gYymOQRj.jpg', 'https://www.youtube.com/watch?v=amamg7Smpao', 'Pierre Coffin', ARRAY['Steve Carell', 'Kristen Wiig', 'Benjamin Bratt', 'Miranda Cosgrove', 'Dana Gaier Ellis', 'Elsie Fisher', 'Russell Brand', 'Ken Jeong']::TEXT[], ARRAY['Hoạt Hình', 'Hài', 'Gia Đình', 'Khoa Học Viễn Tưởng']::TEXT[], 98, '2013-06-26', NULL, 'US: PG', 7, 'ended'),
  ('f2273841-8d57-50ea-b053-e034709f40db'::UUID, 953, 'Cuộc Phiêu Lưu Đến Madagascar', 'Madagascar', 'Tại sở thú trung tâm New York, một con sư tử, con ngựa vằn, một hươu cao cổ và một con hà mã kết bạn với nhau và chúng cũng là "sao" của các sô diễn. Rồi đến khi một con thú bị biến mất trong chuồng, thì ba con khác cũng thoát ra để tìm con thú bị lạc đã đi theo chiếc thuyền đến tận một hòn đảo của Madagascar - Châu Phi. Chiếc tàu bị lật ngoài biển, tất cả các con thú bị giam cầm đã nếm trải thế nào là môi trường hoang dã…', 'Four animal friends get a taste of the wild life when they break out of captivity at the Central Park Zoo and wash ashore on the island of Madagascar.', 'https://image.tmdb.org/t/p/w780/zMpJY5CJKUufG9OTw0In4eAFqPX.jpg', 'https://image.tmdb.org/t/p/w1280/tPaurpIUskVji5vwV0dhy9pq4Vs.jpg', 'https://www.youtube.com/watch?v=fq5zU9T_Hl4', 'Eric Darnell', ARRAY['Ben Stiller', 'Chris Rock', 'David Schwimmer', 'Jada Pinkett Smith', 'Sacha Baron Cohen', 'Cedric the Entertainer', 'Andy Richter', 'Tom McGrath']::TEXT[], ARRAY['Phiêu Lưu', 'Hoạt Hình', 'Hài', 'Gia Đình']::TEXT[], 86, '2005-05-25', NULL, 'US: PG', 6.9, 'ended'),
  ('4f5bf747-a30f-590a-a2b1-71b46a620422'::UUID, 508442, 'Cuộc Sống Nhiệm Màu', 'Soul', 'Điều gì khiến bạn là chính bạn? Cuối năm nay, hãng phim hoạt hình danh tiếng Pixar sẽ trình làng một tác phẩm mới mang tên SOUL – CUỘC SỐNG NHIỆM MÀU với nhân vật chính là Joe Gardner (Jamie Foxx lồng tiếng) một giáo viên dạy nhạc ở trường trung học. Anh vừa nhận được một cơ hội duy nhất trong đời khi có thể được tham gia chơi Jazz cho một ban nhạc nổi nhất thành phố. Nhưng một bước chân sai lầm đã đưa anh từ thành phố New York hoa lệ đến Cõi Trước – một nơi kỳ diệu mà ở đó các linh hồn được nhận tính cách, sở thích trước khi họ đi đến Trái Đất. Quyết tâm trở về cuộc đời của chính mình, Joe hợp tác với một linh hồn bất hảo mang tên 22 (lồng tiếng bởi Tina Fey) - người chưa bao giờ hiểu được sự hấp dẫn của cuộc sống loài người. Joe cố gắng hết mình để cho 22 thấy cuộc sống này nhiệm màu như thế nào, đồng thời anh ấy cũng khám phá ra câu trả lời quan trọng cho đời người.', NULL, 'https://image.tmdb.org/t/p/w780/7UZo67RI5hINBk6UfZoBZZRsDIa.jpg', 'https://image.tmdb.org/t/p/w1280/rQaHA74pevnGsxcKGaoZVGWe9TC.jpg', 'https://www.youtube.com/watch?v=0hNOkUXPRqs', 'Pete Docter', ARRAY['Jamie Foxx', 'Tina Fey', 'Graham Norton', 'Rachel House', 'Alice Braga', 'Richard Ayoade', 'Phylicia Rashād', 'Donnell Rawlings']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Chính Kịch', 'Âm Nhạc', 'Giả Tưởng']::TEXT[], 101, '2020-12-25', NULL, 'US: PG', 8.1, 'ended'),
  ('107eafd5-0a0a-5c17-a246-7e8706260ea8'::UUID, 62211, 'Lò Đào Tạo Quái Vật', 'Monsters University', 'Ngay từ lúc vào trường đại học đào tạo cách dọa nạt trẻ con, Mike và Sully được xếp cùng phòng nhau. “Cặp đũa lệch” không thể chịu nổi nhau và hay gây gổ, tuy nhiên trải qua nhiều biến cố, cả hai đã thay đổi cách nhìn về người bạn quái vật của mình.', 'A look at the relationship between Mike and Sulley during their days at Monsters University — when they weren''t necessarily the best of friends.', 'https://image.tmdb.org/t/p/w780/cx8HiWvDTDeH1BVOU1kNWDPWZ2E.jpg', 'https://image.tmdb.org/t/p/w1280/mIpCxBWNz6SHCQBe2K2PFr5MB7f.jpg', 'https://www.youtube.com/watch?v=xBzPioph8CI', 'Dan Scanlon', ARRAY['Billy Crystal', 'John Goodman', 'Steve Buscemi', 'Helen Mirren', 'Peter Sohn', 'Joel Murray', 'Sean Hayes', 'Dave Foley']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Hài', 'Giả Tưởng']::TEXT[], 104, '2013-06-19', NULL, 'US: G', 7.1, 'ended'),
  ('130f9687-3aa2-57d3-b653-2e44d47e9a6a'::UUID, 211672, 'Minions', 'Minions', 'Câu chuyện kể về các Minion trước khi gặp chủ nhân Gru (xuất hiện ở 2 phần Kẻ Cắp Mặt Trăng trước), bắt đầu từ buổi bình minh của nhân loại, xuất phát điểm là những sinh vật đơn bào màu vàng, Minion dần tiến hóa qua các thời đại và luôn trung thành phụng sự những kẻ xấu xa, tàn ác nhất. Nhưng chủ nhân của chúng cứ lần lượt biến mất – từ loài khủng long bạo chúa tới Napoleon.', 'Minions Stuart, Kevin and Bob are recruited by Scarlet Overkill, a super-villain who, alongside her inventor husband Herb, hatches a plot to take over the world.', 'https://image.tmdb.org/t/p/w780/k124rCDBZAQK1zjCGqSCUF2Bytb.jpg', 'https://image.tmdb.org/t/p/w1280/wKrxeY6lbu7KFBsWVcMH6M8avwr.jpg', 'https://www.youtube.com/watch?v=Wfql_DoHRKc', 'Kyle Balda', ARRAY['Pierre Coffin', 'Sandra Bullock', 'Jon Hamm', 'Michael Keaton', 'Allison Janney', 'Steve Coogan', 'Jennifer Saunders', 'Geoffrey Rush']::TEXT[], ARRAY['Gia Đình', 'Hoạt Hình', 'Phiêu Lưu', 'Hài']::TEXT[], 91, '2015-06-17', NULL, 'US: PG', 6.4, 'ended'),
  ('8f2a7dc8-136b-5694-ae8f-7c75f34727d0'::UUID, 502356, 'Anh Em Super Mario movie', 'The Super Mario Bros. Movie', 'The Super Mario Bros. Movie xoay quanh cuộc phiêu lưu ở thế giới Vương quốc Nấm của anh em thợ sửa ống nước Mario và Luigi. Sau khi tình cờ bước tới vùng đất lạ từ một ống nước, Luigi đã bị chia tách với Mario và rơi vào tay quái vật rùa xấu xa Bowser, hắn đang âm mưu độc chiếm thế giới. Trong lúc cố gắng tìm kiếm người anh em của mình, Mario đã chạm mặt anh bạn nấm Toad và công chúa Peach. Từ đây họ sát cánh bên nhau trên hành trình ngăn chặn thế lực hắc ám.', NULL, 'https://image.tmdb.org/t/p/w780/gRlfFcpPdjREQ3lgeuAuB10gfbR.jpg', 'https://image.tmdb.org/t/p/w1280/9n2tJBplPbgR2ca05hS5CKXwP2c.jpg', 'https://www.youtube.com/watch?v=UGO_i2tf1BM', 'Aaron Horvath', ARRAY['Chris Pratt', 'Anya Taylor-Joy', 'Charlie Day', 'Jack Black', 'Keegan-Michael Key', 'Seth Rogen', 'Fred Armisen', 'Sebastian Maniscalco']::TEXT[], ARRAY['Gia Đình', 'Hài', 'Phiêu Lưu', 'Giả Tưởng', 'Hoạt Hình']::TEXT[], 93, '2023-04-05', NULL, 'US: PG', 7.6, 'ended'),
  ('684458f5-2787-5fd5-a68b-36f895767d23'::UUID, 301528, 'Câu Chuyện Đồ Chơi 4', 'Toy Story 4', 'Woody luôn tự tin vào vị trí của bản thân mình, và luôn cho rằng sứ mệnh của anh ấy là chăm sóc cho những đứa trẻ, cho dù đó là Andy hay Bonnie. Vậy nên khi đồ chơi mới của Bonnie, Forky khẳng định bản thân là đồ bỏ đi, Woody đã cố gắng cho Forky thấy rằng cậu ấy sinh ra để thuộc về thế giới đồ chơi. Nhưng khi những món đồ chơi tham gia chuyến đi dã ngoại của Bonnie và gia đình cô, Woody đã vô tình có cuộc gặp mặt với người bạn lâu năm mất tích Bo Peep. Sau nhiều năm sống một mình, Bo Peep tin rằng mình có thể có một cuộc sống phiêu lưu thú vị hơn là làm một món đồ chơi bằng sứ. Khi Woody và Bo Peep nhận ra họ là những món đồ chơi thuộc về hai thế giới khác nhau, họ đã sớm cảm nhận được những mối lo lắng của mình.', 'Woody has always been confident about his place in the world, devoted to taking care of his kid—whether that''s Andy or Bonnie. But after Bonnie creates a reluctant new toy called "Forky", a road trip adventure alongside old and new friends challenges everything Woody believes about loyalty, purpose, and what it truly means to be a toy.', 'https://image.tmdb.org/t/p/w780/ezIOA7SqfxoMSOUsnLtArWd6JPv.jpg', 'https://image.tmdb.org/t/p/w1280/q62bpQ67qaXY0u6b2wFEnQYIbPd.jpg', 'https://www.youtube.com/watch?v=Pl9JS8-gnWQ', 'Josh Cooley', ARRAY['Tom Hanks', 'Tim Allen', 'Annie Potts', 'Tony Hale', 'Keegan-Michael Key', 'Madeleine McGraw', 'Christina Hendricks', 'Jordan Peele']::TEXT[], ARRAY['Gia Đình', 'Hài', 'Hoạt Hình', 'Phiêu Lưu']::TEXT[], 100, '2019-06-19', NULL, 'US: G', 7.5, 'ended'),
  ('df8f3a8e-0dcd-5aeb-9322-ed86c5f2d0e3'::UUID, 10020, 'Người Đẹp và Quái Vật', 'Beauty and the Beast', 'Một chàng hoàng tử trẻ sống trong một tòa lâu đài nguy nga tráng lệ. Chàng có tất cả nhưng kiêu ngạo, tàn nhẫn và không biết đến tình yêu thương...  Chàng sẽ sống ra sao khi bị biến thành một con quái vật xấu xí?  Lời nguyền chỉ được hóa giải, khi chàng học được cách yêu ai đó, và cũng được người đó đáp lại trước khi cánh hoa hồng cuối cùng rơi xuống!', 'Follow the adventures of Belle, a bright young woman who finds herself in the castle of a prince who''s been turned into a mysterious beast. With the help of the castle''s enchanted staff, Belle soon learns the most important lesson of all -- that true beauty comes from within.', 'https://image.tmdb.org/t/p/w780/hUJ0UvQ5tgE2Z9WpfuduVSdiCiU.jpg', 'https://image.tmdb.org/t/p/w1280/fW4ZCoEZRBqLAJGFQ2g5AdAfPQR.jpg', 'https://www.youtube.com/watch?v=UUVpyeS_fVw', 'Gary Trousdale', ARRAY['Paige O''Hara', 'Robby Benson', 'Richard White', 'Jerry Orbach', 'David Ogden Stiers', 'Angela Lansbury', 'Rex Everhart', 'Jesse Corti']::TEXT[], ARRAY['Lãng Mạn', 'Gia Đình', 'Hoạt Hình', 'Giả Tưởng']::TEXT[], 90, '1991-10-22', NULL, 'US: G', 7.7, 'ended'),
  ('e6c68c68-6ad8-5061-88b5-3a3e52d39157'::UUID, 420818, 'Vua Sư Tử', 'The Lion King', 'Bộ phim Vua Sư Tử được đạo diễn bởi Jon Favreau sẽ đưa khán giả đến với xavan Châu Phi rộng lớn nơi vị vua tương lai Simba được sinh ra. Tuy là người kế vị ngai vàng chính thức nhưng Simba phải đương đầu với những âm mưu của Scar, người chú ruột luôn toan tính chiếm lấy ngôi báu.  Cuộc chiến ở Pride Rock trở nên khốc liệt hơn bao giờ hết và đỉnh điểm là việc chú sư tử Simba bị lưu đày khỏi quê hương. Với sự giúp đỡ của 2 người bạn mới Timon và Pumbaa, Simba dần học cách trưởng thành và quay trở về để giành lại những gì vốn dĩ thuộc về cậu. Bằng kĩ xảo đồ họa ấn tượng và âm nhạc sống động, Vua Sư Tử sẽ tái hiện lại những nhân vật mà khán giả yêu mến theo một cách hoàn toàn mới.', 'Simba idolizes his father, King Mufasa, and takes to heart his own royal destiny. But not everyone in the kingdom celebrates the new cub''s arrival. Scar, Mufasa''s brother—and former heir to the throne—has plans of his own. The battle for Pride Rock is ravaged with betrayal, tragedy and drama, ultimately resulting in Simba''s exile. With help from a curious pair of newfound friends, Simba will have to figure out how to grow up and take back what is rightfully his.', 'https://image.tmdb.org/t/p/w780/hNltEgOaOIONA6peqiIb9WR1lTG.jpg', 'https://image.tmdb.org/t/p/w1280/1TUg5pO1VZ4B0Q1amk3OlXvlpXV.jpg', 'https://www.youtube.com/watch?v=7TavVZMewpY', 'Jon Favreau', ARRAY['Chiwetel Ejiofor', 'John Oliver', 'Donald Glover', 'James Earl Jones', 'John Kani', 'Alfre Woodard', 'Beyoncé', 'JD McCrary']::TEXT[], ARRAY['Phiêu Lưu', 'Chính Kịch', 'Gia Đình', 'Hoạt Hình']::TEXT[], 118, '2019-07-12', NULL, 'US: PG', 7.1, 'ended'),
  ('0ebe3583-b2c5-561e-8aad-2a87777bcaae'::UUID, 9479, 'Đêm Kinh Hoàng Trước Giáng Sinh', 'The Nightmare Before Christmas', 'Mỗi một ngày lễ có một thế giới riêng của nó. Ngày Halloween có thế giới của Halloween, nơi mà những con ma không sợ ánh mặt trời vì đó là mặt trời Halloween. Chúng ta yêu thích lễ hội Halloween vì mỗi năm chỉ diễn ra một lần nhưng Jack Skellington - ông hoàng của lễ hội Halloween đã chán cái cảnh một năm chỉ được làm việc một lần để rồi lại ngồi chờ đến lễ hội Halloween năm sau. Hơn thế nữa, thế giới Halloween đã trở nên nhàm chán với cư dân nơi đó. Một hôm sau khi đi lạc vào Christmas Town, Jack lập tức bị cuốn hút bởi thế giới lộng lẫy của Christmas. Cậu trở về Halloween Town và thuyết phục mọi người rằng Halloween Town từ nay sẽ đảm nhận cả lễ Giáng sinh nữa. Và thế là họ tấp nập chuẩn bị những món quà Giáng sinh theo phong cách...Halloween, với Jack trong vai trò Ông già Noel. Liệu ngày lễ Giáng Sinh có thể ăn mừng theo phong cách Halloween được hay không hay nó sẽ trở thành "Cơn ác mộng trước Giáng Sinh"', 'Tired of scaring humans every October 31 with the same old bag of tricks, Jack Skellington, the spindly king of Halloween Town, kidnaps Santa Claus and plans to deliver shrunken heads and other ghoulish gifts to children on Christmas morning. But as Christmas approaches, Jack''s rag-doll girlfriend, Sally, tries to foil his misguided plans.', 'https://image.tmdb.org/t/p/w780/aVQMxLZUv5AOJYMr2jL4zX2tO9B.jpg', 'https://image.tmdb.org/t/p/w1280/dSfrsjhqC6lYe7LYDYnzWeXZmEl.jpg', 'https://www.youtube.com/watch?v=IoYahD_xNR0', 'Henry Selick', ARRAY['Danny Elfman', 'Chris Sarandon', 'Catherine O''Hara', 'William Hickey', 'Glenn Shadix', 'Paul Reubens', 'Ken Page', 'Edward Ivory']::TEXT[], ARRAY['Giả Tưởng', 'Hoạt Hình', 'Gia Đình']::TEXT[], 76, '1993-10-09', NULL, 'US: PG', 7.9, 'ended'),
  ('169ab8a2-a8ed-540e-ac4a-f33c787b6660'::UUID, 10674, 'Hoa Mộc Lan', 'Mulan', 'Nội dung bộ phim hoạt hình dựa theo một câu chuyện dân gian nổi tiếng của Trung Quốc kể về cô gái giả trai ra trận thường được biết đến dưới cái tên Hoa Mộc Lan. Tuyệt phẩm này của Walt Disney được đề cử một giải Oscar cho “Nhạc phim hay nhất” năm 1999. Mulan (Ming-Na Wen lồng tiếng) là người con duy nhất trong gia đình danh giá. Mặc dù luôn cố gắng làm vừa lòng mẹ cha nhưng dường như cô luôn khiến họ phải thất vọng. Khi quân giặc tới xâm chiếm bờ cõi Trung Hoa, thanh niên trai tráng đều hăng hái ghi tên đi lính. Fa Zhou (Soon-Tek Oh) người cha già của Mulan vốn bị thương và không thể đi vững nhưng vẫn muốn ra trận chiến đấu vì đất nước và vì danh dự của dòng họ. Quá thương cha già phải đi tòng quân, Mulan liền lấy áo giáp và ngựa cải trang thành một người đàn ông, đứng trước bàn thờ tổ tiên khấn vái mong được phù hộ rồi thay cha ra trận. Mushu (Eddie Murphy) một con rồng nhỏ đã được phái đi để bảo vệ Mulan trong khi chiến đấu.', 'When Imperial China calls one man from every family to defend the empire from invading Huns, a young woman disguises herself as a soldier to take her ailing father’s place. Facing ruthless invaders, brutal training, and the risk of execution if discovered, she must decide who she truly is—and what she’s willing to fight for.', 'https://image.tmdb.org/t/p/w780/zvxWfpIC3u3wBmtcKetImogx2xx.jpg', 'https://image.tmdb.org/t/p/w1280/mUYV0ZdsDEliGaQahcQH1F3grsP.jpg', 'https://www.youtube.com/watch?v=2z2KsFZs-8I', 'Tony Bancroft', ARRAY['Ming-Na Wen', 'Eddie Murphy', 'BD Wong', 'Miguel Ferrer', 'Harvey Fierstein', 'Freda Foh Shen', 'June Foray', 'James Hong']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Phiêu Lưu']::TEXT[], 88, '1998-06-18', NULL, 'US: G', 7.9, 'ended'),
  ('bf4b6240-2f59-5824-89e7-9563a4e5b595'::UUID, 82702, 'Bí Kíp Luyện Rồng 2', 'How to Train Your Dragon 2', 'Hiccup, Răng Sún và một kỵ sĩ rồng bí ẩn hợp lực để bảo vệ đảo Berk khỏi một chiến binh thèm khát quyền lực cùng đội quân rồng của riêng hắn.', 'Five years after uniting the dragons and Vikings of Berk, Hiccup and Toothless soar beyond their homeland, charting the vast unknown. During one of their adventures, the pair discover a secret cave that houses hundreds of wild dragons—and a mysterious dragon rider with a startling connection to Hiccup. And as the ruthless conqueror Drago Bludvist rises to seize control of both dragons and people alike, Hiccup must step into his role as a true leader and, alongside his friends and Toothless, protect Berk from a devastating war.', 'https://image.tmdb.org/t/p/w780/433Vg3WvfNuoMZNp35g1xsYSHbo.jpg', 'https://image.tmdb.org/t/p/w1280/8AAuJtCzaibYkbE0QVHc8EBsELB.jpg', 'https://www.youtube.com/watch?v=1Y0erVF9cLI', 'Dean DeBlois', ARRAY['Jay Baruchel', 'Cate Blanchett', 'Gerard Butler', 'Craig Ferguson', 'America Ferrera', 'Jonah Hill', 'Christopher Mintz-Plasse', 'T.J. Miller']::TEXT[], ARRAY['Giả Tưởng', 'Hành Động', 'Phiêu Lưu', 'Hoạt Hình', 'Gia Đình']::TEXT[], 102, '2014-06-05', NULL, 'US: PG', 7.7, 'ended'),
  ('ec772555-cd85-559c-9d77-6a6edb83e26a'::UUID, 950, 'Kỷ Băng Hà: Băng Tan', 'Ice Age: The Meltdown', 'Sau thành công của Ice Age phần 1, trong Ice Age 2: The Meltdown, nhóm bạn Diego, Manny và Sid lại tái ngộ với khán giả khi khối băng chuẩn bị tan chảy ra và nó sẽ tàn phá cả thung lũng. Tình thế trở nên nguy hiểm hơn khi câu chuyện giờ đây xuất hiện thêm 2 sinh vật biển lúc nào cũng rình rập dưới làn nước lạnh lẽo. Ba người bạn của chúng ta phải hợp sức với nhau để giúp mọi người tránh khỏi thảm họa này. Liệu những người anh hùng của chúng ta có tới đích an toàn? Liệu Manny và Ellie có tìm được tình yêu đích thực với nhau? Liệu chú sóc Scrat có giành được quả đầu cho mình? Liệu Diego có chiến thắng nỗi sợ hãi của một chú hổ không biết bơi? Liệu Sid có được tôn trọng đúng mực?', 'Diego, Manny and Sid return in this sequel to the hit animated movie Ice Age. This time around, the deep freeze is over, and the ice-covered earth is starting to melt, which will destroy the trio''s cherished valley. The impending disaster prompts them to reunite and warn all the other beasts about the desperate situation.', 'https://image.tmdb.org/t/p/w780/zDduhCHasKQ9YOTvlOreHem7Wbi.jpg', 'https://image.tmdb.org/t/p/w1280/o1jr0UqVjxIZ1JnFzuVLN4ulWey.jpg', 'https://www.youtube.com/watch?v=SNMXO74bw9M', 'Carlos Saldanha', ARRAY['Ray Romano', 'John Leguizamo', 'Denis Leary', 'Queen Latifah', 'Seann William Scott', 'Josh Peck', 'Jay Leno', 'Will Arnett']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Hài', 'Phiêu Lưu']::TEXT[], 91, '2006-03-29', NULL, 'US: PG', 6.7, 'ended'),
  ('29c70cd3-0240-5215-a7d8-7aee67d35624'::UUID, 330457, 'Nữ Hoàng Băng Giá 2', 'Frozen II', 'Cùng dấn thân vào một cuộc phiêu lưu xa xôi thú vị, hai chị em Anna và Elsa đi đến chốn rừng sâu để tìm kiếm sự thật về bí ẩn cổ xưa của vương quốc mình. Tất cả những gì Anna và Elsa biết về bản thân, lịch sử và gia đình của họ đều bị thử thách khi họ bị cuốn vào một chuyến đi đầy quả cảm đến với vùng đất phía bắc bí ẩn ngoài Arendelle được báo trước.', NULL, 'https://image.tmdb.org/t/p/w780/tXjHSZFS87uJ433dbeOSV3jBEBl.jpg', 'https://image.tmdb.org/t/p/w1280/AoSZyb37ljMAxw0RdeQEBHKtgcc.jpg', 'https://www.youtube.com/watch?v=DwTls2hIOrA', 'Jennifer Lee', ARRAY['Kristen Bell', 'Idina Menzel', 'Josh Gad', 'Evan Rachel Wood', 'Jonathan Groff', 'Sterling K. Brown', 'Alfred Molina', 'Rachel Matthews']::TEXT[], ARRAY['Gia Đình', 'Hoạt Hình', 'Phiêu Lưu', 'Hài', 'Giả Tưởng']::TEXT[], 103, '2019-11-20', NULL, 'US: PG', 7.2, 'ended'),
  ('966af8de-fcd1-51fe-86fe-ac006d990348'::UUID, 568124, 'Encanto: Vùng Đất Thần Kỳ', 'Encanto', 'Câu chuyện về một gia đình phi thường, nhà Madrigals, sống ẩn mình trong vùng núi Colombia, trong một ngôi nhà ma thuật, trong một thị trấn sôi động, ở một nơi kỳ diệu, quyến rũ được gọi là Encanto. Phép thuật của Encanto đã ban phước cho mọi đứa trẻ trong gia đình món quà độc nhất vô nhị từ siêu sức mạnh đến sức mạnh chữa lành — mọi đứa trẻ, trừ Mirabel. Nhưng khi cô phát hiện ra rằng phép thuật xung quanh Encanto đang gặp nguy hiểm, Mirabel quyết định rằng cô, người nhà Madrigal bình thường duy nhất, có thể là hy vọng cuối cùng của gia đình cô.', NULL, 'https://image.tmdb.org/t/p/w780/wWL205mZBcOP4GNtdhztAvqTgUG.jpg', 'https://image.tmdb.org/t/p/w1280/3G1Q5xF40HkUBJXxt2DQgQzKTp5.jpg', 'https://www.youtube.com/watch?v=hEQWILdb5yg', 'Byron Howard', ARRAY['Stephanie Beatriz', 'María Cecilia Botero', 'John Leguizamo', 'Mauro Castillo', 'Jess Darrow', 'Angie Cepeda', 'Carolina Gaitán', 'Diane Guerrero']::TEXT[], ARRAY['Hoạt Hình', 'Hài', 'Gia Đình', 'Giả Tưởng']::TEXT[], 102, '2021-11-24', NULL, 'US: PG', 7.6, 'ended'),
  ('dff7241d-b6b0-5ce3-9dad-6f06c99e94c1'::UUID, 810, 'Shrek 3', 'Shrek the Third', 'Nội dung “Shrek 3” nói về Shrek sau khi đã yên vị phò mã bên nàng công chúa Fiona (đã không còn xinh đẹp). Anh nghiêm túc nhận ra và gánh vác những trách nhiệm mới mà cuộc sống mang lại: trách nhiệm của một vị vua trong tương lai và trách nhiệm của người chồng chăm lo cho cuộc sống gia đình. Đức vua Harold, trong lốt một chú ếch, lâm trọng bệnh và qua đời, để lại cho Shrek trọng trách gánh vác giang sơn, Shrek tự nhận thấy mình không thể làm được một vị vua tài giỏi, đã một mực từ chối trách nhiệm. Nhưng sự đời thật khó biết đến chữ “ngờ”… Tiếp nối nội dung của câu chuyện ở phần 1 và 2, Shrek 3 đưa khán giả theo chân những nhân vật cổ tích tham gia một chuyến phiêu lưu mới không ít những tình huống dở khóc dở cười. Bộ phim đã đạt được nhiều đề cử danh giá cho phim hoạt hình xuất sắc nhất ở các giải thưởng lớn như Kid’s Choice Award hay BAFTA Award.', 'After the King of Far Far Away dies, Shrek and Fiona are to succede. However, Shrek wants to return to his cozy swamp and live in peace and quiet, so when he finds out there is another heir to the throne, he and Donkey set off to bring him back to rule the kingdom.', 'https://image.tmdb.org/t/p/w780/n4SexGGQzI26E269tfpa80MZaGV.jpg', 'https://image.tmdb.org/t/p/w1280/wvXxKpFGXvQJRB0nvvfURhRD3C0.jpg', 'https://www.youtube.com/watch?v=InR865IDDjU', 'Chris Miller', ARRAY['Mike Myers', 'Eddie Murphy', 'Cameron Diaz', 'Antonio Banderas', 'Julie Andrews', 'Justin Timberlake', 'John Cleese', 'Larry King']::TEXT[], ARRAY['Giả Tưởng', 'Phiêu Lưu', 'Hoạt Hình', 'Hài', 'Gia Đình']::TEXT[], 93, '2007-05-17', NULL, 'US: PG', 6.3, 'ended'),
  ('ec617b6d-a538-5fd2-9dcf-4c613bf6c95e'::UUID, 9487, 'Thế Giới Côn Trùng', 'A Bug''s Life', 'Một xóm kiến nọ bị những con châu chấu to xác, đứng đầu là Hopper (Kevin Spacey lồng tiếng) đô hộ. Đàn kiến tội nghiệp phải cống nạp thức ăn cho quân xâm lược hàng năm và coi đây là một nghi lễ bắt buộc phải thực thi nếu muốn sống yên ổn. Một ngày mùa xuân, khi đồ cúng lễ đã được chuẩn bị sẵn sàng, một anh chàng kiến ưa phát minh ra những đồ quái dị tên là Flik (Dave Foley) đã vô tình làm đổ toàn bộ số hạt và rau quả xuống sông. Đàn châu chấu hung hăng xuất hiện và hết sức tức giận khi không thấy thức ăn được dâng lên như mọi khi. Bọn chúng định tấn công đàn kiến nhưng khi rõ sự tình, chúng cho họ một cơ hội chuộc lỗi, gia hạn đến mùa thu phải gom nhặt đủ số đồ lễ. Nhưng Flik lại nghĩ khác, anh ta muốn đàn ...', 'On behalf of "oppressed bugs everywhere," an inventive ant named Flik hires a troupe of warrior bugs to defend his bustling colony from a horde of freeloading grasshoppers led by the evil-minded Hopper.', 'https://image.tmdb.org/t/p/w780/g4fjvdBOGhLHJ4uI2dlhx0MHOgJ.jpg', 'https://image.tmdb.org/t/p/w1280/hwwFyowfcbLRVmRBOkvnABBNIOs.jpg', 'https://www.youtube.com/watch?v=mE35XQFxbeo', 'John Lasseter', ARRAY['Dave Foley', 'Kevin Spacey', 'Julia Louis-Dreyfus', 'Hayden Panettiere', 'Phyllis Diller', 'Richard Kind', 'David Hyde Pierce', 'Joe Ranft']::TEXT[], ARRAY['Phiêu Lưu', 'Hoạt Hình', 'Hài', 'Gia Đình']::TEXT[], 95, '1998-11-25', NULL, 'US: G', 7, 'ended'),
  ('edc98712-8fd0-573b-9558-9bc302c20cdf'::UUID, 14836, 'Cô Bé Coraline', 'Coraline', 'Khi Coraline chuyển đến một ngôi nhà cũ, cô cảm thấy buồn chán và bị cha mẹ bỏ rơi. Cô tìm thấy một cánh cửa ẩn với một lối đi bằng gạch. Trong đêm, cô băng qua hành lang và tìm thấy một thế giới song song, nơi mọi người đều có nút thay vì mắt, với cha mẹ chăm sóc và tất cả ước mơ của cô đều trở thành sự thật. Khi Người Mẹ khác mời Coraline ở lại thế giới của mình mãi mãi, cô gái từ chối và thấy rằng thực tế thay thế nơi cô bị mắc kẹt chỉ là một thủ thuật để thu hút cô.', 'Wandering her rambling old house in her boring new town, 11-year-old Coraline discovers a hidden door to a strangely idealized version of her life. In order to stay in the fantasy, she must make a frighteningly real sacrifice.', 'https://image.tmdb.org/t/p/w780/p8YSnUyQGZQkW1NSgVvn7ubWWCn.jpg', 'https://image.tmdb.org/t/p/w1280/hofnlIyF6bePkgQOpcuRWLvzf15.jpg', 'https://www.youtube.com/watch?v=T6iQnnHNF50', 'Henry Selick', ARRAY['Dakota Fanning', 'Teri Hatcher', 'Jennifer Saunders', 'Dawn French', 'Keith David', 'John Hodgman', 'Robert Bailey Jr.', 'Ian McShane']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Giả Tưởng', 'Kinh Dị']::TEXT[], 100, '2009-02-05', NULL, 'US: PG', 7.9, 'ended'),
  ('d6a4483f-bfb6-5b3b-a0f7-6bc58b1d28c8'::UUID, 76492, 'Khách Sạn Huyền Bí', 'Hotel Transylvania', 'Chủ khách sạn Transylvania – Dracula – trở nên bảo bọc thái quá đối với cô con gái tuổi teen của mình sau khi xuất hiện một cậu thanh niên quan tâm đến cô bé.', 'Welcome to Hotel Transylvania, Dracula''s lavish five-stake resort, where monsters and their families can live it up and no humans are allowed. One special weekend, Dracula has invited all his best friends to celebrate his beloved daughter Mavis''s 118th birthday. For Dracula catering to all of these legendary monsters is no problem but the party really starts when one ordinary guy stumbles into the hotel and changes everything!', 'https://image.tmdb.org/t/p/w780/nkNTjeVrY8Dd4GOLQQjRMEDZvQb.jpg', 'https://image.tmdb.org/t/p/w1280/5rARlA8beRAVXPYzSaF2NoS8Ry5.jpg', 'https://www.youtube.com/watch?v=q4RK3jY7AVk', 'Genndy Tartakovsky', ARRAY['Adam Sandler', 'Selena Gomez', 'Andy Samberg', 'Kevin James', 'Fran Drescher', 'Steve Buscemi', 'Molly Shannon', 'David Spade']::TEXT[], ARRAY['Hoạt Hình', 'Hài', 'Gia Đình', 'Giả Tưởng']::TEXT[], 91, '2012-09-20', NULL, 'US: PG', 7, 'ended'),
  ('70f5eed0-5517-57da-af0c-0a26d78c79e7'::UUID, 315162, 'Mèo Đi Hia: Điều Ước Cuối Cùng', 'Puss in Boots: The Last Wish', 'Puss phát hiện ra rằng niềm đam mê phiêu lưu mạo hiểm của anh đã gây ra hậu quả: Anh đã đốt cháy 8 trong số 9 mạng sống của mình, bây giờ chỉ còn lại đúng một mạng. Anh ta bắt đầu một cuộc hành trình để tìm Điều ước cuối cùng thần thoại trong Rừng Đen nhằm khôi phục lại chín mạng sống của mình. Chỉ còn một mạng sống, đây có lẽ sẽ là cuộc hành trình nguy hiểm nhất của Puss.', NULL, 'https://image.tmdb.org/t/p/w780/dKjjVuPawiREBYjREb3U5SCtfrt.jpg', 'https://image.tmdb.org/t/p/w1280/jr8tSoJGj33XLgFBy6lmZhpGQNu.jpg', 'https://www.youtube.com/watch?v=5ZdgiQBi3NM', 'Joel Crawford', ARRAY['Antonio Banderas', 'Salma Hayek Pinault', 'Harvey Guillén', 'Wagner Moura', 'Florence Pugh', 'Olivia Colman', 'Ray Winstone', 'Samson Kayo']::TEXT[], ARRAY['Hoạt Hình', 'Phiêu Lưu', 'Giả Tưởng', 'Hài', 'Gia Đình']::TEXT[], 103, '2022-12-07', NULL, 'US: PG', 8.2, 'ended'),
  ('92d40b9d-a3b4-5ff8-b4f3-282e4bcf90f6'::UUID, 346364, 'Gã Hề Ma Quái', 'It', 'It 2017 được thực hiện dựa trên cuốn tiểu thuyết nổi tiếng cùng tên của nhà văn Stephen King, It dự kiến kéo dài hai tập. Tác phẩm xoay quanh cuộc chiến giữa một nhóm bạn thân với Pennywise - con quỷ đội lốt hình dạng hề, chuyên đi giết hại trẻ em. Họ có hai lần đụng độ nó, với khoảng cách thời gian lên tới 30 năm. Hồi năm 1990, It từng được chuyển thể lên sóng truyền hình.', 'In a small town in Maine, seven children known as The Losers Club come face to face with life problems, bullies and a monster that takes the shape of a clown called Pennywise.', 'https://image.tmdb.org/t/p/w780/2gACwaTbjI36P4888wIGbC4bz3Y.jpg', 'https://image.tmdb.org/t/p/w1280/qVGpxnjrGlHaSTCqTQI6viBDSfp.jpg', 'https://www.youtube.com/watch?v=xKJmEC5ieOk', 'Andy Muschietti', ARRAY['Jaeden Martell', 'Jeremy Ray Taylor', 'Sophia Lillis', 'Finn Wolfhard', 'Chosen Jacobs', 'Jack Dylan Grazer', 'Wyatt Oleff', 'Bill Skarsgård']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân', 'Chính Kịch']::TEXT[], 135, '2017-09-06', NULL, 'US: R', 7.2, 'ended'),
  ('95932894-7a83-559a-88f5-f338324b5da1'::UUID, 694, 'Thị Kiến', 'The Shining', 'Jack Torrance tìm việc trông coi khách sạn Overlook trên dãy núi Colorado, và cả gia đình anh đã chuyển tới sống ở đây. Do nơi này bị đóng cửa trong suốt mùa đông, vì thế chỉ có gia đình của Jack Torrance sống ở đây trong một thời gian dài. Sau đó, một cơn bão tuyết ập xuống và khiến gia đình ông bị kẹt lại bên trong khách sạn. Danny - con trai của Torrance, một cậu bé có năng lực ngoại cảm tên "Thị Kiến" (Shining) và có thể nhìn thấy những việc trong quá khứ cũng như trong tương lai. Cậu bé phát hiện ra rằng khách sạn này đang bị ma ám và hồn ma đó đang dần biến cha của cậu thành một kẻ hung ác...', 'Jack Torrance accepts a caretaker job at the Overlook Hotel, where he, along with his wife Wendy and their son Danny, must live isolated from the rest of the world for the winter. But they aren''t prepared for the madness that lurks within.', 'https://image.tmdb.org/t/p/w780/mlk6A3jYkbBRJDY3AMGbKcBun3i.jpg', 'https://image.tmdb.org/t/p/w1280/AdKA2F1SzYPhSZdEbjH1Zh75UVQ.jpg', 'https://www.youtube.com/watch?v=jAE7dNurHR4', 'Stanley Kubrick', ARRAY['Jack Nicholson', 'Shelley Duvall', 'Danny Lloyd', 'Scatman Crothers', 'Barry Nelson', 'Philip Stone', 'Joe Turkel', 'Anne Jackson']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân']::TEXT[], 144, '1980-05-23', NULL, 'US: R', 8.2, 'ended'),
  ('e027c36b-0987-5d84-b721-c9e650ec07b6'::UUID, 419430, 'Trốn Thoát', 'Get Out', 'Chris và bạn gái của anh, Rose, lên vùng nông thôn để thăm bố mẹ cô vào cuối tuần. Ban đầu, Chris coi sự hiếu khách của gia đình là nỗ lực để vượt qua vấn đề khác màu da giữa anh và con gái họ. Tuy nhiên, vào cuối tuần, một loạt những phát hiện ngày càng đáng lo ngại dẫn anh đến một sự thật mà anh không bao giờ có thể tưởng tượng được.', 'Chris and his girlfriend Rose go upstate to visit her parents for the weekend. At first, Chris reads the family''s overly accommodating behavior as nervous attempts to deal with their daughter''s interracial relationship, but as the weekend progresses, a series of increasingly disturbing discoveries lead him to a truth that he never could have imagined.', 'https://image.tmdb.org/t/p/w780/A1nsaaR2rneUakmFwcSXe2MV2KT.jpg', 'https://image.tmdb.org/t/p/w1280/bBQHALHRAaaORlPNXv7fNcRXYdx.jpg', 'https://www.youtube.com/watch?v=gsB70ZRY-hI', 'Jordan Peele', ARRAY['Daniel Kaluuya', 'Allison Williams', 'Catherine Keener', 'Bradley Whitford', 'Caleb Landry Jones', 'Marcus Henderson', 'Betty Gabriel', 'LaKeith Stanfield']::TEXT[], ARRAY['Bí Ẩn', 'Giật Gân', 'Kinh Dị']::TEXT[], 104, '2017-02-24', NULL, 'US: R', 7.6, 'ended'),
  ('4c4627d9-dd91-596c-9eff-f854363a7121'::UUID, 381288, 'Tách Biệt', 'Split', 'Kevin, một người đàn ông có 23 nhân cách khác nhau trong một cơ thể, bên trong Kevin tồn tại một nhân cách ác quỷ luôn muốn điều khiển và thống trị những nhân cách còn lại. Sau khi bắt cóc ba cô gái trẻ, Kevin đã phải đấu tranh với các mặt tâm lý bên trong hắn và với cả những người xung quanh, khi bức tường ngăn cách giữa các mảng tâm trí đã sụp đổ. Nhân cách xấu xa vốn ẩn giấu lâu nay đang dần hiện hữu và thao túng các nhân cách còn lại.', 'Though Kevin has evidenced 23 personalities to his trusted psychiatrist, Dr. Fletcher, there remains one still submerged who is set to materialize and dominate all the others. Compelled to abduct three teenage girls led by the willful, observant Casey, Kevin reaches a war for survival among all of those contained within him — as well as everyone around him — as the walls between his compartments shatter apart.', 'https://image.tmdb.org/t/p/w780/kAqpYVwtReMDU75Arv5QrQ3tJpD.jpg', 'https://image.tmdb.org/t/p/w1280/9pkZesKMnblFfKxEhQx45YQ2kIe.jpg', 'https://www.youtube.com/watch?v=6bfooooTKyM', 'M. Night Shyamalan', ARRAY['James McAvoy', 'Anya Taylor-Joy', 'Haley Lu Richardson', 'Jessica Sula', 'Betty Buckley', 'Izzie Coffey', 'Brad William Henke', 'Sebastian Arcelus']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân']::TEXT[], 117, '2017-01-19', NULL, 'US: PG-13', 7.3, 'ended'),
  ('99303c72-81ec-5d4b-a96a-2d882b3f07ca'::UUID, 44214, 'Thiên Nga Đen', 'Black Swan', 'Một nữ diễn viên ballet sống thu mình phải rèn luyện cho vai diễn quan trọng nhất trong sự nghiệp, đồng thời đối mặt với sự cạnh tranh khốc liệt từ cô diễn viên đóng thế tài năng nhưng nguy hiểm.', 'A committed dancer struggles to maintain her sanity after winning the lead role in a production of Tchaikovsky''s "Swan Lake."', 'https://image.tmdb.org/t/p/w780/2C5WuZANl6UCP7UB4tZ4jFji1DX.jpg', 'https://image.tmdb.org/t/p/w1280/eDLp4uFdqP1gpy9oMrutwH6Q64I.jpg', 'https://www.youtube.com/watch?v=2Pxc_5f27Kg', 'Darren Aronofsky', ARRAY['Natalie Portman', 'Mila Kunis', 'Vincent Cassel', 'Barbara Hershey', 'Winona Ryder', 'Benjamin Millepied', 'Ksenia Solo', 'Kristina Anapau']::TEXT[], ARRAY['Chính Kịch', 'Giật Gân', 'Kinh Dị']::TEXT[], 108, '2010-12-03', NULL, 'US: R', 7.7, 'ended'),
  ('d728d731-12a1-5317-9999-6be75c0eb020'::UUID, 70981, 'Hành Trình Đến Hành Tinh Chết', 'Prometheus', 'Nội dung phim nói về các nhà khảo cổ phát hiện ra những manh mối về nguồn gốc của loài người. Những manh mối này dẫn họ tìm tới những góc tối tăm nhất, tận cùng của vũ trụ. Tại đó, họ phải đối mặt với một cuộc chiến đầy khiếp sợ để cứu tương lai của nhân loại. Prometheus 3D có sự tham gia của dàn diễn viên tài năng: Michael Fassbender, Charlize Theron, Idris Elba, Logan Marshall-Green và Guy Pearce. Cùng chờ đợi đến ngày 8.6.2012 để trải nghiệm và tự cảm  nhận bộ phim thú vị này như thế nào.', 'A team of explorers discover a clue to the origins of mankind on Earth, leading them on a journey to the darkest corners of the universe. There, they must fight a terrifying battle to save the future of the human race.', 'https://image.tmdb.org/t/p/w780/3zdmtn8eIsGNv3wfAIsXXGTSRUp.jpg', 'https://image.tmdb.org/t/p/w1280/qDG5SlGkWNsjSJWiGTBMFI8DpzA.jpg', 'https://www.youtube.com/watch?v=cJMIzdf1eo8', 'Ridley Scott', ARRAY['Noomi Rapace', 'Michael Fassbender', 'Charlize Theron', 'Idris Elba', 'Guy Pearce', 'Logan Marshall-Green', 'Sean Harris', 'Rafe Spall']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Bí Ẩn', 'Kinh Dị']::TEXT[], 124, '2012-05-30', NULL, 'US: R', 6.6, 'ended'),
  ('645eced1-5bc7-5b31-9899-f5a1ccae0b22'::UUID, 19908, 'Vùng Đất Thây Ma', 'Zombieland', 'Zombieland là bộ phim ma - kinh dị nhưng mang yếu tố hài hước xoay quanh hai người đàn ông tìm cách xoay sở để sống sót trong một thế giới đầy thây ma. Đó là Columbus, một người đàn ông yếu đuối và Tallahassee, một anh hùng diệt thay ma, người có quyết tâm giết đến cái thây ma cuối cùng trên trái đất. Rồi một ngày họ nhận ra họ không phải là những người duy nhất sống sót, họ sẽ phải cùng nhau xác định cách nào thì ít đau đớn hơn: đoàn kết với nhau hay nạp mạng cho đám thây ma kia?', 'Columbus has made a habit of running from what scares him. Tallahassee doesn''t have fears. If he did, he''d kick their ever-living ass. In a world overrun by zombies, these two are perfectly evolved survivors. But now, they''re about to stare down the most terrifying prospect of all: each other.', 'https://image.tmdb.org/t/p/w780/yRWpmwV02VbA6KbFeXIdOMYFlPm.jpg', 'https://image.tmdb.org/t/p/w1280/oihWVx3imvRKujnGmSDYhfG1gI5.jpg', 'https://www.youtube.com/watch?v=8m9EVP8X7N8', 'Ruben Fleischer', ARRAY['Jesse Eisenberg', 'Woody Harrelson', 'Emma Stone', 'Abigail Breslin', 'Amber Heard', 'Bill Murray', 'Derek Graf', 'Elle Alexander']::TEXT[], ARRAY['Hài', 'Kinh Dị']::TEXT[], 87, '2009-10-02', NULL, 'US: R', 7.3, 'ended'),
  ('f4f4a910-e7e1-5765-ae86-598ef50b5490'::UUID, 138843, 'Ám Ảnh Kinh Hoàng', 'The Conjuring', 'Ed và Lorraine Warren, là những nhà điều tra các hiện tượng siêu nhiên xảy ra trên nước Mỹ. Những báo cáo của họ còn truyền cảm hứng cho cuốn tiểu thuyết Amityville Horror. Trong phim hai vợ chồng Warren là những người điều tra các hiện tượng siêu nhiên, họ đến để hỗ trợ gia đình Perron đang trải qua các sự kiện ngày càng đáng lo ngại trong trang trại của họ ở Harrisville, Rhode Island vào năm 1971.', 'Paranormal investigators Ed and Lorraine Warren work to help a family terrorized by a dark presence in their farmhouse. Forced to confront a powerful entity, the Warrens find themselves caught in the most terrifying case of their lives.', 'https://image.tmdb.org/t/p/w780/qic7Xa1fnwLyEsjvjapDTEMYXsR.jpg', 'https://image.tmdb.org/t/p/w1280/ecKQlAEG95k62SMGhvX83oEqANK.jpg', 'https://www.youtube.com/watch?v=k10ETZ41q5o', 'James Wan', ARRAY['Vera Farmiga', 'Patrick Wilson', 'Lili Taylor', 'Ron Livingston', 'Hayley McFarland', 'Sterling Jerins', 'Shanley Caswell', 'Mackenzie Foy']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân']::TEXT[], 112, '2013-07-18', NULL, 'US: R', 7.5, 'ended'),
  ('781e893e-ee1b-56b7-98e7-94224e7a3716'::UUID, 578, 'Hàm Cá Mập', 'Jaws', 'Bộ phim là câu chuyện về cuộc chiến giữa cảnh sát trưởng Brody, nhà hải dương học Matt Hooper với con “quỷ biển” – cá mập khổng lồ ăn thịt người. "Jaws" cuốn hút người xem bởi những cảnh quay cận cảnh hàm răng nhọn sáng loáng của con quái vật trong cú táp bất ngờ được đạo diễn tài ba Steven Spielberg khéo léo cài vào, trên nền nhạc rùng rợn và ám ảnh! Hàm cá mập - Jaws Lần đầu tiên trên màn ảnh, khán giả được trải nghiệm một nỗi sợ hãi đến từ đại dương.', 'When the seaside community of Amity finds itself under attack by a dangerous great white shark, the town''s chief of police, a young marine biologist, and a grizzled shark hunter embark on a desperate quest to kill the beast before it strikes again.', 'https://image.tmdb.org/t/p/w780/nMhdKk4hsjLvYZHUB3ws2AqPH3X.jpg', 'https://image.tmdb.org/t/p/w1280/i1yf91svRHX45l9BXL8rVFzLoPH.jpg', 'https://www.youtube.com/watch?v=N9hzLQUGr34', 'Steven Spielberg', ARRAY['Roy Scheider', 'Robert Shaw', 'Richard Dreyfuss', 'Lorraine Gary', 'Murray Hamilton', 'Carl Gottlieb', 'Jeffrey Kramer', 'Susan Backlinie']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân', 'Phiêu Lưu']::TEXT[], 124, '1975-06-20', NULL, 'US: PG', 7.7, 'ended'),
  ('21eeaff9-05ec-5714-b841-345604770ce5'::UUID, 539, 'Tâm Thần Hoảng Loạn', 'Psycho', 'Tâm Thần Hoảng Loạn: 1 người đàn bà trẻ, Marion Crane , đánh cắp 1 chiếc valise chứa 40 ngàn dollars mà chủ của cô yêu cầu phải gửi nhà băng. Trong lúc bỏ trốn, đêm đó nàng ta nghỉ chân tại 1 motel ít người lui tới và được tiếp đón bởi Norman Bates (Antony Perkins). Theo lời anh ta kể thì anh đang sống tại 1 ngôi nhà gần bên với bà mẹ già tàn phế có tính cách rất khó chịu. Tối hôm ấy, trong lúc tắm để chuẩn bị lên giường ngủ, Marion bất thình lình bị bà già đó túm lấy và đâm điên loạn vào người cô nàng.Norman xuất hiện, giấu xác Marion cùng với chiếc xe hơi (với cả 40 ngàn dollars trong rương) dưới 1 cái hồ gần motel. Cô em gái Marion, Leila và Sam(tình nhân của Marion), cùng với 1 viên thám tử của 1 hãng bảo hiểm lên đường tìm kiếm cô nàng, hy vọng lấy ...', 'When larcenous real estate clerk Marion Crane goes on the lam with a wad of cash and hopes of starting a new life, she ends up at the notorious Bates Motel, where manager Norman Bates cares for his housebound mother.', 'https://image.tmdb.org/t/p/w780/2ykxn5iCpv9RUr94dhTrCUNvIx4.jpg', 'https://image.tmdb.org/t/p/w1280/mufF1aYvwdpKerhq5R1YrVcbJLY.jpg', 'https://www.youtube.com/watch?v=D90QhegiVvo', 'Alfred Hitchcock', ARRAY['Anthony Perkins', 'Janet Leigh', 'Vera Miles', 'John Gavin', 'Martin Balsam', 'John McIntire', 'Simon Oakland', 'Frank Albertson']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân', 'Bí Ẩn']::TEXT[], 109, '1960-06-22', NULL, 'US: R', 8.4, 'ended'),
  ('c6b4d8a6-01e5-5318-acc8-ce3817df7108'::UUID, 405774, 'Lồng Chim', 'Bird Box', 'Chuyện gì sẽ xảy ra nếu cả thế giới rơi vào nguy kịch trước sự tấn công bởi những con quái vật mà chưa một ai từng thấy hình dạng? Sẽ đáng sợ ra sao nếu chúng sơ sẩy một tích tắc nhìn vào chúng, và rồi chúng ta phát điên lên, tự huỷ sự sống của bản thân? Với cách duy nhất để sống sót là bịt mắt và trốn chạy, Malorie (Sandra Bullock) phải làm mọi cách để giữ hai con an toàn giữa cuộc chiến trong bóng tối. Không chỉ phải chiến đấu với những con quái vật vô hình, cô còn phải đấu tranh với bản thân khi chỉ cần một lần hé nhìn là có thể mất đi ánh sáng mãi mãi.', 'Five years after an ominous unseen presence drives most of society to suicide, a survivor and her two children make a desperate bid to reach safety.', 'https://image.tmdb.org/t/p/w780/bgfZZPh8bBXxBHIiUfeBh186le0.jpg', 'https://image.tmdb.org/t/p/w1280/pDKFL1zcHzEpmz4MJA5JJnRbJeD.jpg', 'https://www.youtube.com/watch?v=INJ2bPFy108', 'Susanne Bier', ARRAY['Sandra Bullock', 'Trevante Rhodes', 'John Malkovich', 'Sarah Paulson', 'Jacki Weaver', 'Rosa Salazar', 'Danielle Macdonald', 'Lil Rel Howery']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân', 'Chính Kịch']::TEXT[], 124, '2018-12-13', 'T18', 'US: R', 6.8, 'ended'),
  ('2fbbe344-52b1-5e44-be47-2fb41121bd41'::UUID, 176, 'Lưỡi Cưa', 'Saw', 'Bạn có giết người để được sống không? Đó là điều mà hai người đàn ông tự hỏi khi họ bị một tên sát nhân hàng loạt bắt cóc và phải hợp sức trong một tình huống chết chóc.', 'Two men wake up to find themselves shackled in a grimy, abandoned bathroom. As they struggle to comprehend their predicament, they discover a disturbing tape left behind by the sadistic mastermind known as Jigsaw. With a chilling voice and cryptic instructions, Jigsaw informs them that they must partake in a gruesome game in order to secure their freedom.', 'https://image.tmdb.org/t/p/w780/sj7KBQSpeCvBQXhCbfhKPN7XcEB.jpg', 'https://image.tmdb.org/t/p/w1280/ok4ot3YbfDYZcINXf91JUfq3maB.jpg', 'https://www.youtube.com/watch?v=0bHDblokwv0', 'James Wan', ARRAY['Leigh Whannell', 'Cary Elwes', 'Tobin Bell', 'Danny Glover', 'Ken Leung', 'Dina Meyer', 'Mike Butters', 'Paul Gutrecht']::TEXT[], ARRAY['Kinh Dị', 'Bí Ẩn', 'Tội Phạm']::TEXT[], 103, '2004-10-01', NULL, 'US: R', 7.4, 'ended'),
  ('db9c02f0-2681-5cc5-ad20-79427a092b66'::UUID, 474350, 'Gã Hề Ma Quái 2', 'It Chapter Two', 'It Chapter Two (Gã Hề Ma Quái 2) vẫn là câu chuyện về những cô cậu bé của nhóm The Losers Club, lúc này đã trưởng thành và đối mặt với vô số vấn đề trong cuộc sống. Chưa dừng lại ở đó, ám ảnh ma hề Pennywise cứ 27 năm lại xuất hiện một lần tại thị trấn Derry buộc 7 cô cậu bé ngày nào phải tiếp tục cuốn vào cuộc chạm trán tiếp theo giữa hai bên thiện và ác.  Mặc dù có thể cả nhóm đã trưởng thành và khôn ngoan hơn, cuộc chiến của họ với Pennywise vẫn còn đó những hậu quả bất ngờ, thậm chí khiến một số thành viên phải trải qua đau đớn đến tột cùng.', '27 years after overcoming the malevolent supernatural entity Pennywise, the former members of the Losers'' Club, who have grown up and moved away from Derry, are brought back together by a devastating phone call.', 'https://image.tmdb.org/t/p/w780/ccCusWCSi5EhVTrxVLmkTwH11aZ.jpg', 'https://image.tmdb.org/t/p/w1280/6LVSrgm83UYWlrLTCVGmWhFKYO0.jpg', 'https://www.youtube.com/watch?v=xhJ5P7Up3jA', 'Andy Muschietti', ARRAY['Jessica Chastain', 'James McAvoy', 'Bill Hader', 'Isaiah Mustafa', 'Jay Ryan', 'James Ransone', 'Andy Bean', 'Bill Skarsgård']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân', 'Chính Kịch']::TEXT[], 169, '2019-09-04', NULL, 'US: R', 6.8, 'ended'),
  ('ad3c4612-39a5-5c42-b92b-611107da0ec5'::UUID, 126889, 'Quái Vật Không Gian: Khế Ước', 'Alien: Covenant', 'Alien: Covenant 2017 (Quái Vật Không Gian: Khế Ước) nói về Ridley Scott đã quay lại với vũ trụ của Alien với phần tiếp nối mang tên Covenant này. Đây là chương 2 của một bộ 3 phim được bắt đầu bằng Prometheus (Bí Ẩn Hành Tinh Chết) và có liên quan đến các bản phim khoa học viễn tưởng nổi tiếng năm 1979. Nội dung phần này kể về con tàu thám hiểm Convenant đáp đến một hành tinh xa xôi nằm ở rìa thiên hà. Đoàn phi hành gia trên tàu cứ ngỡ tìm được một thiên đường cho chuyến thám hiểm vũ trụ, không ai ngờ rằng đó là một thế giới tối tăm đầy rẫy nguy hiểm mà cư dân duy nhất là “người tổng hợp” David_người sống sót từ chuyến thám hiểm kinh hoàng của Prometheus.', NULL, 'https://image.tmdb.org/t/p/w780/koFC4PoXdRTfYH0y0IvZ7wYMVCx.jpg', 'https://image.tmdb.org/t/p/w1280/iXXPaQPfQowpQ5UvhsHLj9BgFhe.jpg', 'https://www.youtube.com/watch?v=YV4gDSBRVoA', 'Ridley Scott', ARRAY['Michael Fassbender', 'Katherine Waterston', 'Billy Crudup', 'Danny McBride', 'Demián Bichir', 'Carmen Ejogo', 'Jussie Smollett', 'Callie Hernandez']::TEXT[], ARRAY['Kinh Dị', 'Khoa Học Viễn Tưởng']::TEXT[], 122, '2017-05-09', NULL, 'US: R', 6.2, 'ended'),
  ('58ff312a-fee5-5d07-9ede-eabe512cf477'::UUID, 747, 'Giữa Bầy Xác Sống', 'Shaun of the Dead', 'Shaun, 29 tuổi, là một nhân viên của công ty bán hàng, sống với 2 người bạn thân, Ed và Pete. Một ngày nọ, như bao ngày bình thường khác, anh dậy, anh ngồi nói chuyện với Ed, ra cửa hàng tạp hóa gần nhà mua nước ngọt và kem....thế nhưng, anh không hề để ý những việc xung quanh, anh chỉ biết đi, và làm việc của mình. Và rồi, khi Ed nói với anh có một người phụ nữ ở ngoài vườn của mình....anh và Ed dường như không sợ...mà còn đùa giỡn , anh đã phát hiện ra rằng mọi người trong thành phố dường như có những hành động rất lạ, rất kì quặc....Và anh đã biết điều gì đã xảy ra khi anh nghe tin tức trên TV...', 'Shaun lives a supremely uneventful life, which revolves around his girlfriend, his mother, and, above all, his local pub. This gentle routine is threatened when the dead return to life and make strenuous attempts to snack on ordinary Londoners.', 'https://image.tmdb.org/t/p/w780/kL959UjDxn0ujlW0VsLoqmQW131.jpg', 'https://image.tmdb.org/t/p/w1280/wb34q3VgzHgL8frVMywrN3wXmqx.jpg', 'https://www.youtube.com/watch?v=_QuY93B2FS0', 'Edgar Wright', ARRAY['Simon Pegg', 'Nick Frost', 'Kate Ashfield', 'Lucy Davis', 'Dylan Moran', 'Jessica Hynes', 'Penelope Wilton', 'Bill Nighy']::TEXT[], ARRAY['Kinh Dị', 'Hài']::TEXT[], 99, '2004-04-09', NULL, 'US: R', 7.5, 'ended'),
  ('796ae7fa-3858-5e99-9f57-7d439da40d0b'::UUID, 300668, 'Vùng Hủy Diệt', 'Annihilation', 'Phim xoay quanh hành trình của nhà sinh học do người đẹp Natalie Portman thủ vai. Thành viên trong đoàn thám hiểm 5 nhà khoa học có nhiệm vụ thăm dò một khu vực bí ẩn nhằm tìm ra lời giải đáp cho căn bệnh kỳ quái mà chồng cô mắc phải sau khi trở về từ nơi đây. Sau khi chồng cô thám hiểm khu rừng này thì hiện tượng kỳ lạ bắt đầu xuất hiện. một căn bệnh không có lời giải, khiến cho anh trở thành một cái xác không hồn. Để tìm hiều căn bệnh cũng là con đường duy nhất để cứu chồng mình, cô cùng 4 cộng sự cùng nhau xâm nhập vào vùng đất kỳ ảo này. Một vùng đất bên trên phủ kín mây mù và khi bước qua bức tường plasma, họ sẽ tới một thế giới mới hoàn toàn lạ lẫm, những hiện tượng kỳ bí và những sinh vật, cây cối khác biệt hoàn toàn.', 'A biologist signs up for a dangerous, secret expedition into a mysterious zone where the laws of nature don''t apply.', 'https://image.tmdb.org/t/p/w780/nQcYr0EIoKdVYz1bN0pVZoXnruA.jpg', 'https://image.tmdb.org/t/p/w1280/9trZvBr44UGedUOiGo3jgSUw13e.jpg', 'https://www.youtube.com/watch?v=89OP78l9oF0', 'Alex Garland', ARRAY['Natalie Portman', 'Jennifer Jason Leigh', 'Gina Rodriguez', 'Tessa Thompson', 'Tuva Novotny', 'Oscar Isaac', 'Benedict Wong', 'Sonoya Mizuno']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Kinh Dị']::TEXT[], 115, '2018-02-22', NULL, 'US: R', 6.5, 'ended'),
  ('26df7b9f-f4f1-5054-ba95-b9424f1983d8'::UUID, 259693, 'Ám Ảnh Kinh Hoàng 2', 'The Conjuring 2', 'Đây là phần hai của phim năm 2013, The Conjuring, với Patrick Wilson và Vera Farmiga tiếp tục thủ vai hai thám tử săn ma Ed và Lorraine Warren. Phim theo chân họ sang Anh quốc để giúp đỡ gia đình Hodgson khi họ bị tấn công bởi hàng loạt các hiện tượng ma ám được biết đến về sau dưới tên Enfield Poltergeist (hiện tượng ma ám Enfield) tại chính căn nhà của họ vào năm 1977. Phim sáng tạo dựa trên các ghi chép và tư liệu có thật.', 'Lorraine and Ed Warren travel to north London to help a single mother raising four children alone in a house plagued by malicious spirits.', 'https://image.tmdb.org/t/p/w780/n4nwXzvE9LU6X0rUSdHn6wPnkim.jpg', 'https://image.tmdb.org/t/p/w1280/hD9zZYKYb1xBgcm8XIfyvclSkjs.jpg', 'https://www.youtube.com/watch?v=VFsmuRPClr4', 'James Wan', ARRAY['Vera Farmiga', 'Patrick Wilson', 'Madison Wolfe', 'Frances O''Connor', 'Lauren Esposito', 'Benjamin Haigh', 'Patrick McAuley', 'Sterling Jerins']::TEXT[], ARRAY['Kinh Dị']::TEXT[], 134, '2016-06-08', NULL, 'US: R', 7.3, 'ended'),
  ('4d70f20a-c378-57e3-9ed1-a869ccea27b5'::UUID, 158015, 'Ngày Thanh Trừng', 'The Purge', 'The Purge lấy bối cảnh thế giới tương lai vào năm 2022, khi Mỹ trở thành “quốc gia mới tái sinh”, với tội phạm và tỷ lệ thất nghiệp ở mức rất thấp. Để giữ mức ổn định này, chính phủ hàng năm đều có một chiến dịch có tên gọi “12 giờ thanh trừng” để con người có thể tự do giải thoát mọi cảm xúc tiêu cực của họ. Trong 12 tiếng này, các hành vi phạm tội (bao gồm cả giết người) đều không bị truy xét trước pháp luật. Bi kịch xảy đến khi một gia đình bị bắt làm con tin và một câu chuyện rùng rợn bắt đầu...', 'Given the country''s overcrowded prisons, the U.S. government begins to allow 12-hour periods of time in which all illegal activity is legal. During one of these free-for-alls, a family must protect themselves from a home invasion.', 'https://image.tmdb.org/t/p/w780/8KHm2zKkIyPf3tWyNeSgrRYMHl1.jpg', 'https://image.tmdb.org/t/p/w1280/anFRs7Xi7u2nqqBpmhqvXINAPix.jpg', 'https://www.youtube.com/watch?v=aDLGd42PXls', 'James DeMonaco', ARRAY['Ethan Hawke', 'Lena Headey', 'Max Burkholder', 'Adelaide Kane', 'Edwin Hodge', 'Rhys Wakefield', 'Tony Oller', 'Arija Bareikis']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Kinh Dị', 'Giật Gân']::TEXT[], 85, '2013-05-31', NULL, 'US: R', 6.2, 'ended'),
  ('948a1b68-5821-50e9-9f81-da497a1fcba7'::UUID, 493922, 'Di Truyền', 'Hereditary', 'Sau khi Ellen – gia chủ nhà Graham qua đời, con cháu của bà bắt đầu khám phá ra hàng loạt bí mật khó hiểu và ngày một đáng sợ về tổ tiên họ.', 'When the matriarch of the Graham family passes away, her daughter begins to unravel cryptic and increasingly terrifying secrets about her ancestry.', 'https://image.tmdb.org/t/p/w780/a3Lf8D4r6wzk4pJrnuBpvyuYsXi.jpg', 'https://image.tmdb.org/t/p/w1280/pS9Aub8MPyQbENblGD8mHeaqMuv.jpg', 'https://www.youtube.com/watch?v=MJNR58zaStE', 'Ari Aster', ARRAY['Toni Collette', 'Alex Wolff', 'Gabriel Byrne', 'Milly Shapiro', 'Ann Dowd', 'Mallory Bechtel', 'Brock McKinney', 'Jake Brown']::TEXT[], ARRAY['Kinh Dị', 'Bí Ẩn', 'Giật Gân']::TEXT[], 128, '2018-06-07', NULL, 'US: R', 7.3, 'ended'),
  ('189670a7-8fb2-575d-94ff-c7e9376011be'::UUID, 333371, 'Căn Hầm', '10 Cloverfield Lane', 'Câu chuyện bắt đầu bằng vụ tai nạn khốc liệt xảy đến với Michelle khiến cô lịm đi trong xe ô tô. Khi tỉnh dậy, Michelle phát hiện mình đang được điều trị vết thương và bị giam trong một căn hầm cùng với hai người đàn ông. Howard – một trong số họ - nói với cô rằng thế giới bên ngoài đang chịu một thảm họa kinh hoàng, và rằng lựa chọn ở lại căn hầm sẽ giúp bảo toàn tính mạng. Không tin những lời Howard nói, Michelle tìm mọi cách trốn thoát để tìm ra sự thật.', NULL, 'https://image.tmdb.org/t/p/w780/53N10u7lEv7po9EEn7ai1TIGnzu.jpg', 'https://image.tmdb.org/t/p/w1280/dMERTVrObB7TkRVIFmcndR2sZFH.jpg', 'https://www.youtube.com/watch?v=nuYd0FOL6Ms', 'Dan Trachtenberg', ARRAY['John Goodman', 'Mary Elizabeth Winstead', 'John Gallagher Jr.', 'Douglas M. Griffin', 'Suzanne Cryer', 'Bradley Cooper', 'Sumalee Montano', 'Frank Mottek']::TEXT[], ARRAY['Giật Gân', 'Khoa Học Viễn Tưởng', 'Chính Kịch', 'Kinh Dị']::TEXT[], 104, '2016-03-10', NULL, 'US: PG-13', 7, 'ended'),
  ('a65170ea-fb69-501c-b284-24ecd3f05abe'::UUID, 170, '28 Ngày Sau', '28 Days Later', 'Một căn bệnh truyền nhiễm nguy hiểm bùng phát thành đại dịch trên khắp nước Anh, đẩy nền văn minh nhân loại vào nguy cơ tuyệt diệt. Những người sống sót chạy về một căn cứ quân sự để tập hợp lực lượng chống lại những con bệnh...', 'Twenty-eight days after a killer virus was accidentally unleashed from a British research facility, a small group of London survivors are caught in a desperate struggle to protect themselves from the infected. Carried by animals and humans, the virus turns those it infects into homicidal maniacs -- and it''s absolutely impossible to contain.', 'https://image.tmdb.org/t/p/w780/sQckQRt17VaWbo39GIu0TMOiszq.jpg', 'https://image.tmdb.org/t/p/w1280/aJFwk1clMal1prxAvKAgHxKPAf.jpg', 'https://www.youtube.com/watch?v=mWEhfF27O0c', 'Danny Boyle', ARRAY['Cillian Murphy', 'Naomie Harris', 'Brendan Gleeson', 'Megan Burns', 'Christopher Eccleston', 'Noah Huntley', 'Luke Mably', 'Stuart McQuarrie']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân', 'Khoa Học Viễn Tưởng']::TEXT[], 113, '2002-10-31', NULL, 'US: R', 7.2, 'ended'),
  ('0d1a44b7-7bd6-5fa9-b7dc-ef5f80514c1d'::UUID, 9552, 'Quỷ Ám', 'The Exorcist', 'Một thiếu nữ trẻ bị thực thể tà ác chiếm hữu thân xác và dày vò khiến mẹ của cô bé phải tìm đến hai vị linh mục nhằm giải thoát người thiếu nữ khỏi bàn tay của ác quỷ.', 'When a mysterious entity possesses a young girl, her mother seeks the help of two Catholic priests to save her life.', 'https://image.tmdb.org/t/p/w780/2HZRznGYUnynp1lMVyhYZSuT1Oy.jpg', 'https://image.tmdb.org/t/p/w1280/xcjJ5khg2yzOa282mza39Lbrm7j.jpg', 'https://www.youtube.com/watch?v=BU2eYAO31Cc', 'William Friedkin', ARRAY['Ellen Burstyn', 'Linda Blair', 'Jason Miller', 'Max von Sydow', 'Lee J. Cobb', 'William O''Malley', 'Kitty Winn', 'Barton Heyman']::TEXT[], ARRAY['Kinh Dị']::TEXT[], 122, '1973-12-26', NULL, 'US: R', 7.8, 'ended'),
  ('4808267f-1868-58ad-802b-f9ea4b8c77d1'::UUID, 22970, 'Căn Nhà Gỗ Trong Rừng', 'The Cabin in the Woods', 'The Cabin in the Woods kể về câu chuyện của một nhóm 5 sinh viên đại học Jules, Kurt, Jesse, Marty và Dana đến một ngôi nhà gỗ trong rừng để nghỉ cuối tuần. Thế nhưng, họ không hề biết về mối nguy hiểm được lập trình sẵn trong căn nhà ấy đang chờ đợi họ. Căn nhà trong khu rừng đó thực chất là một phòng thí nghiệm nằm tách biệt với những camera giấu kín. Và điều kinh khủng hơn, bên dưới đó là con quái vật được tạo ra để giết họ. Thực chất nó là một tổ chức có công nghệ cao và bí mật tạo ra những ngôi nhà ma ám để giết những nhóm sinh viên "xấu số" vô tình chọn nơi đây để nghỉ ngơi. Căn nhà chỉ như phần nổi của tảng băng chìm, che giấu một khối lượng âm mưu, tội ác xấu xa khổng lồ bên dưới nó. Và đây chính là một kế hoạch được lập ra để sắp xếp thứ tự chết cho bọn trẻ với 5 hình tượng khác nhau...', 'Five friends set out for a weekend at a remote cabin in the woods, expecting nothing more than fun and relaxation. As night falls, they discover that something far more unsettling is at work and that nothing about their getaway is what it seems.', 'https://image.tmdb.org/t/p/w780/A3a2oxgpfI8JO5RkZcOp08yEyY8.jpg', 'https://image.tmdb.org/t/p/w1280/wJffMiCnrszaNclKggGixYWB7D7.jpg', 'https://www.youtube.com/watch?v=7NiAWF7VIFY', 'Drew Goddard', ARRAY['Kristen Connolly', 'Fran Kranz', 'Chris Hemsworth', 'Jesse Williams', 'Anna Hutchison', 'Richard Jenkins', 'Bradley Whitford', 'Amy Acker']::TEXT[], ARRAY['Kinh Dị', 'Bí Ẩn']::TEXT[], 95, '2012-04-12', NULL, 'US: R', 6.7, 'ended'),
  ('8af18b06-4098-5a41-995b-24e7f3855408'::UUID, 561, 'Người Đến Từ Địa Ngục', 'Constantine', 'John Constantine, người được tạo hóa ban tặng một món quà mà anh hoàn toàn không muốn, đó là khả năng nhận diện bản thể của thiên thần và ác quỷ tồn tại trong mỗi con người, chuyên điều tra những vụ án đầy huyền bí và siêu nhiên. Anh hợp tác với nữ thám tử Los Angeles là Angela Dodson điều tra cái chết bí ẩn của chị gái sinh đôi bị tâm thần Isabel Dodson. Khi còn sống, Isabel thường nhắc đến những điều quái dị mà người thường không thấy được. Lúc này trên vùng sa mạc Mexico, mầm mống của cái ác và bóng tối đang chờ cơ hội để trỗi dậy.', 'John Constantine has literally been to Hell and back. When he teams up with a policewoman to solve the mysterious suicide of her twin sister, their investigation takes them through the world of demons and angels that exists beneath the landscape of contemporary Los Angeles.', 'https://image.tmdb.org/t/p/w780/vPYgvd2MwHlxTamAOjwVQp4qs1W.jpg', 'https://image.tmdb.org/t/p/w1280/x3YFn10ehQKMRIJwIfiDAX8S9Xt.jpg', 'https://www.youtube.com/watch?v=819JCbGfZpg', 'Francis Lawrence', ARRAY['Keanu Reeves', 'Rachel Weisz', 'Shia LaBeouf', 'Djimon Hounsou', 'Max Baker', 'Pruitt Taylor Vince', 'Gavin Rossdale', 'Tilda Swinton']::TEXT[], ARRAY['Giả Tưởng', 'Hành Động', 'Kinh Dị']::TEXT[], 121, '2005-02-08', NULL, 'US: R', 7.2, 'ended'),
  ('7e82dca1-ac60-520e-adf5-4a21e861592f'::UUID, 530385, 'Midsommar: Lễ Hội Hạ Chí', 'Midsommar', 'Lễ Hội Đẫm Máu lấy câu chuyện xoay quanh cô gái Dani cùng bạn trai và 3 người bạn khác đi du lịch tới ngôi làng Hårga tại Thụy Điển. Chuyến đi của họ trùng vào dịp làng Hårga tổ chức lễ hội mừng ngày hạ chí. Tưởng rằng tất cả sẽ có một quãng thời gian vui vẻ bên nhau nhưng rồi mọi thứ bắt đầu trở nên không như ý muốn của mình và thậm chí còn đáng sợ gấp nhiều lần.', 'Several friends travel to Sweden to study as anthropologists a summer festival that is held every ninety years in the remote hometown of one of them. What begins as a dream vacation in a place where the sun never sets, gradually turns into a dark nightmare as the mysterious inhabitants invite them to participate in their disturbing festive activities.', 'https://image.tmdb.org/t/p/w780/7LEI8ulZzO5gy9Ww2NVCrKmHeDZ.jpg', 'https://image.tmdb.org/t/p/w1280/aAM3cQmYGjjLQ24m0F0RWfjKQ57.jpg', 'https://www.youtube.com/watch?v=1Vnghdsjmd0', 'Ari Aster', ARRAY['Florence Pugh', 'Jack Reynor', 'William Jackson Harper', 'Will Poulter', 'Vilhelm Blomgren', 'Isabelle Grill', 'Gunnel Fred', 'Ellora Torchia']::TEXT[], ARRAY['Kinh Dị', 'Chính Kịch', 'Bí Ẩn']::TEXT[], 147, '2019-07-03', NULL, 'US: R', 7.1, 'ended'),
  ('5df8295d-d3a2-56d4-99d9-3f4a9b08dd34'::UUID, 345940, 'Cá Mập Siêu Bạo Chúa', 'The Meg', 'Một chiếc tàu ngầm dưới lòng biển sâu bị tấn công bởi một sinh vật khổng lồ và đầy nguy hiểm được cho là đã tuyệt chủng từ lâu. Hậu quả là khiến cả đoàn người bị mắc kẹt dưới đáy Thái Bình Dương và bị đe dọa tính mạng. Thời gian trôi qua, một đội chuyên gia thợ lặn mà đứng đầu là Jonas Taylor, nhà đại dương học người Trung Quốc, cháu gái ông là Suyin đã đến để giải cứu đoàn tàu. Nhưng không ai ngờ rằng, kẻ thù của họ lại chính là kẻ săn mồi to lớn và vĩ đại nhất lịch sử – một con cá mập thời tiền sử dài 75 foot thường được biết đến với cái tên Megalodon.', 'A deep sea submersible pilot revisits his past fears in the Mariana Trench, and accidentally unleashes the seventy foot ancestor of the Great White Shark believed to be extinct.', 'https://image.tmdb.org/t/p/w780/xNVLc2ZoKVaXOPWG4zKoTb5nPI0.jpg', 'https://image.tmdb.org/t/p/w1280/ibKeXahq4JD63z6uWQphqoJLvNw.jpg', 'https://www.youtube.com/watch?v=b_4uXy2Y1SQ', 'Jon Turteltaub', ARRAY['Jason Statham', 'Lý Băng Băng', 'Rainn Wilson', 'Cliff Curtis', 'Ruby Rose', 'Jessica McNamee', 'Masi Oka', '趙文瑄']::TEXT[], ARRAY['Hành Động', 'Khoa Học Viễn Tưởng', 'Kinh Dị']::TEXT[], 113, '2018-08-08', NULL, 'US: PG-13', 6.2, 'ended'),
  ('5277863c-2eab-5a46-bc79-5805eb2d50d7'::UUID, 1091, 'Quái Vật Biến Hình', 'The Thing', 'Một nhóm nhà khoa học đang nghiên cứu tại Nam cực bị một loài sinh vật lạ đến từ ngoài không gian tấn công. Sinh vật này không chỉ xảo quyệt, thông minh, có trí tuệ của một nền văn minh đi trước ta hàng triệu năm mà còn có khả năng nhân bản cực nhanh, chỉ với vài tế bào xâm nhiễm là chúng có thể khống chế và đội lốt con người. Nhận thức rõ nguy cơ loài người có thể bị diệt vong nếu để sinh vật này thoát khỏi Nam cực lạnh giá và đến được khu dân cư, một nhà khoa học đã quyết định phá hủy toàn bộ phương tiện di chuyển và liên lạc nhằm cô lập sinh vật này. Họ bắt đầu cuộc chiến sinh tồn chống lại loài sinh vật hiểm ác đội lốt người. Nhưng trước hết, họ phải xác định được: ai là kẻ giả mạo…', 'A research team in Antarctica is hunted by a shape-shifting alien that assumes the appearance of its victims.', 'https://image.tmdb.org/t/p/w780/tzGY49kseSE9QAKk47uuDGwnSCu.jpg', 'https://image.tmdb.org/t/p/w1280/r9leYNa8nTRCceZrZhP1DXkgKVb.jpg', 'https://www.youtube.com/watch?v=ySvzHdtCiWE', 'John Carpenter', ARRAY['Kurt Russell', 'Wilford Brimley', 'T.K. Carter', 'David Clennon', 'Keith David', 'Richard Dysart', 'Charles Hallahan', 'Peter Maloney']::TEXT[], ARRAY['Kinh Dị', 'Bí Ẩn', 'Khoa Học Viễn Tưởng']::TEXT[], 109, '1982-06-25', NULL, 'US: R', 8.1, 'ended'),
  ('24ed83dc-4d2a-5a01-b952-80b6a146379b'::UUID, 458723, 'Chúng Ta', 'Us', 'Một gia đình gốc Phi 4 người cùng nhau đến một căn nhà ở bãi biển để thư giãn sau những ngày làm việc căng thẳng. Tuy nhiên, mọi thứ không hề đơn giản, khi mỗi lần màn đêm dần dần buông xuống, cuộc sống của gia đình này dần trở nên hỗn loạn khi có sự xuất hiện của những vị khách không mời mà tới.', 'Husband and wife Gabe and Adelaide Wilson take their kids to their beach house expecting to unplug and unwind with friends. But as night descends, their serenity turns to tension and chaos when some shocking visitors arrive uninvited.', 'https://image.tmdb.org/t/p/w780/7TmhC8BTAgYqg76YFbFHh53QyDh.jpg', 'https://image.tmdb.org/t/p/w1280/sC0b8iPUHfZdD8kseLiHw3N8gkp.jpg', 'https://www.youtube.com/watch?v=hNCmb-4oXJA', 'Jordan Peele', ARRAY['Lupita Nyong''o', 'Winston Duke', 'Elisabeth Moss', 'Tim Heidecker', 'Shahadi Wright Joseph', 'Evan Alex', 'Yahya Abdul-Mateen II', 'Anna Diop']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân']::TEXT[], 116, '2019-03-14', NULL, 'US: R', 6.9, 'ended'),
  ('71f71e0a-8f70-5fb1-b94d-874ab5b79041'::UUID, 4232, 'Tiếng Thét', 'Scream', 'Sidney và nhóm bạn của cô bị một tên sát nhân trong mặt nạt trằng đe doạ. Mọi nghi ngờ đổ về người yêu của cô. Cô nghĩ chuyện này có liên quan đến cái chết của mẹ cô cách đây một năm. Rồi từng người bạn của cô bị giết một cách bí ẩn.', 'A year after the murder of her mother, a teenage girl is terrorized by a masked killer who targets her and her friends by using scary movies as part of a deadly game.', 'https://image.tmdb.org/t/p/w780/26MzHQ8yoGWBk9NdLEQyzhMSm6z.jpg', 'https://image.tmdb.org/t/p/w1280/4w6nQYAY0eb7B0VVRDXilXcgAUV.jpg', 'https://www.youtube.com/watch?v=U0LETmDvuXc', 'Wes Craven', ARRAY['Neve Campbell', 'Skeet Ulrich', 'Rose McGowan', 'Matthew Lillard', 'David Arquette', 'Courteney Cox', 'Jamie Kennedy', 'Drew Barrymore']::TEXT[], ARRAY['Tội Phạm', 'Kinh Dị', 'Bí Ẩn']::TEXT[], 112, '1996-12-20', NULL, 'US: R', 7.4, 'ended'),
  ('d53d8cbd-cda7-5123-8199-bb8b6eb99cc9'::UUID, 300669, 'Sát Nhân Trong Bóng Tối', 'Don''t Breathe', 'Một người đàn ông mù và giàu có... mục tiêu hoàn hảo cho phường trộm cắp. Nhưng tình thế lại lật ngược khi ba tên trộm thiếu niên bị rơi vào trò mèo vờn chuột chết người.', 'A group of teens break into a blind man''s home thinking they''ll get away with the perfect crime. They''re wrong.', 'https://image.tmdb.org/t/p/w780/bJPSMFHGo6DdwE8xzegkuqJcZ5r.jpg', 'https://image.tmdb.org/t/p/w1280/3mIVOqDbYeucnw09TpjgHvSjXfu.jpg', 'https://www.youtube.com/watch?v=7koudwTqe0Q', 'Fede Álvarez', ARRAY['Stephen Lang', 'Jane Levy', 'Dylan Minnette', 'Daniel Zovatto', 'Emma Bercovici', 'Törőcsik Franciska', 'Christian Zagia', 'Katia Bokor']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân']::TEXT[], 89, '2016-06-08', NULL, 'US: R', 7, 'ended'),
  ('37a776ba-63bf-5308-8edb-4586be0cb799'::UUID, 395992, 'Mầm Sống Hiểm Họa', 'Life', 'Bộ sáu thành viên của phi hành đoàn trạm không gian quốc tế được giao nhiệm vụ nghiên cứu một mẫu từ sao Hỏa có thể là bằng chứng đầu tiên về sự sống ngoài Trái Đất nhưng hóa ra nó lại thông minh hơn những gì bao giờ được mong đợi.', 'The six-member crew of the International Space Station is tasked with studying a sample from Mars that may be the first proof of extra-terrestrial life, which proves more intelligent than ever expected.', 'https://image.tmdb.org/t/p/w780/82cU75ab9B4v8vszmOUoFfBhGwa.jpg', 'https://image.tmdb.org/t/p/w1280/nNh7vHHISVAaziJEqAq0P9iL52w.jpg', 'https://www.youtube.com/watch?v=cuA-xqBw4jE', 'Daniel Espinosa', ARRAY['Jake Gyllenhaal', 'Ryan Reynolds', 'Rebecca Ferguson', 'Hiroyuki Sanada', 'Ольга Дыховичная', 'Ariyon Bakare', 'Naoko Mori', 'Haruka Kuroda']::TEXT[], ARRAY['Kinh Dị', 'Khoa Học Viễn Tưởng', 'Bí Ẩn']::TEXT[], 104, '2017-03-22', NULL, 'US: R', 6.5, 'ended'),
  ('2a6d03b5-1d2b-5102-bf37-4874fc08bd15'::UUID, 310131, 'Phù Thủy', 'The Witch', 'Phim Phù Thủy Bóng Tối nói về một gia đình trong năm 1630 New England đang bị xâu xé bởi các lực lượng của phù thủy, ma thuật đen và sự sở hữu.', 'In 1630, a farmer relocates his family to a remote plot of land on the edge of a forest where strange, unsettling things happen. With suspicion and paranoia mounting, each family member''s faith, loyalty and love are tested in shocking ways.', 'https://image.tmdb.org/t/p/w780/up9WYWGkyJDruSvzc6hrf6JOiH1.jpg', 'https://image.tmdb.org/t/p/w1280/zi2oYYNSSv7t44iSt5YrxHX9PYs.jpg', 'https://www.youtube.com/watch?v=97OQ7MQC5Ck', 'Robert Eggers', ARRAY['Anya Taylor-Joy', 'Ralph Ineson', 'Kate Dickie', 'Harvey Scrimshaw', 'Ellie Grainger', 'Lucas Dawson', 'Julian Richings', 'Bathsheba Garnett']::TEXT[], ARRAY['Kinh Dị', 'Giả Tưởng', 'Bí Ẩn']::TEXT[], 92, '2016-02-19', NULL, 'US: R', 7, 'ended'),
  ('bca44e9e-5c91-58cc-9c2c-989153857d58'::UUID, 282035, 'Xác Ướp 4', 'The Mummy', 'The Mummy là một bộ phim phiêu lưu, hành động, kinh dị do Mỹ sản xuất được đạo diễn bởi Alex Kurtzman với Jon Spaihts và Christopher McQuarrie chấm bút kịch bản. Đây là phiên bản tái khởi động của loạt phim The Mummy nổi tiếng và là bộ phim thứ hai trong Vũ trụ điện ảnh Quái vật chung của Universal sau bộ phim Dracula Untold.  Phim có sự tham gia của dàn diễn viên tên tuổi như: Tom Cruise, Annabelle Wallis, Sofia Boutella, Jake Johnson, Marwan Kenzari, Courtney B. Vance, Russell Crowe và dự kiến được ra mắt vào ngày 9 tháng 6 năm 2017 bởi hãng phim Universal Pictures.', 'Though safely entombed in a crypt deep beneath the unforgiving desert, an ancient queen whose destiny was unjustly taken from her is awakened in our current day, bringing with her malevolence grown over millennia, and terrors that defy human comprehension.', 'https://image.tmdb.org/t/p/w780/3OrgICQFsnPE5a62nnMajoTUwru.jpg', 'https://image.tmdb.org/t/p/w1280/i4ZougHEyBAboDpi6jsaTUDTjUl.jpg', 'https://www.youtube.com/watch?v=s4C1gnqdrew', 'Alex Kurtzman', ARRAY['Tom Cruise', 'Annabelle Wallis', 'Sofia Boutella', 'Jake Johnson', 'Courtney B. Vance', 'Russell Crowe', 'Marwan Kenzari', 'Neil Maskell']::TEXT[], ARRAY['Giả Tưởng', 'Giật Gân', 'Hành Động', 'Phiêu Lưu', 'Kinh Dị']::TEXT[], 110, '2017-06-06', NULL, 'US: PG-13', 5.5, 'ended'),
  ('d10505f8-fda7-5a10-956d-5f8f99d533c9'::UUID, 520763, 'Vùng Đất Câm Lặng: Phần II', 'A Quiet Place Part II', 'Buộc phải rời khỏi nhà, gia đình Abbott phải dấn thân vào thế giới của những sinh vật chết chóc bị âm thanh thu hút cũng như các mối đe dọa khác mà họ không ngờ tới.', NULL, 'https://image.tmdb.org/t/p/w780/oZheHNTZvHZGQLy7Pd1ORjtaiKv.jpg', 'https://image.tmdb.org/t/p/w1280/uuBYYlbfiYD7ny5VNj46NG14ykR.jpg', 'https://www.youtube.com/watch?v=OObI02klU6E', 'John Krasinski', ARRAY['Emily Blunt', 'John Krasinski', 'Millicent Simmonds', 'Noah Jupe', 'Cillian Murphy', 'Djimon Hounsou', 'Okieriete Onaodowan', 'Scoot McNairy']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Giật Gân', 'Kinh Dị']::TEXT[], 97, '2021-05-21', NULL, 'US: PG-13', 7.4, 'ended'),
  ('2f9afff3-4458-56b4-8cc1-4f5244695241'::UUID, 49018, 'Quỷ Quyệt I', 'Insidious', 'Đây là phần phim đầu tiên (theo thứ tự thời gian, lần thứ ba) trong loạt phim Insidious. Câu chuyện xoay quanh cặp vợ chồng có con trai không hiểu sao đi vào tình trạng hôn mê và trở thành một vật chứa cho hồn ma trong một không gian tâm linh muốn cư ngụ cơ thể của mình, để sống một lần nữa. Bộ phim đã được phát hành tại rạp vào ngày 1 tháng 4 năm 2011 và FilmDistrict phát hành đầu tiên. Bộ phim được nối tiếp theo một phần sau, Quỷ quyệt 2 (2013) và hai phần sau, Quỷ quyệt 3 (2015) và Quỷ quyệt: Chìa khóa quỷ dữ (2018).', 'A family discovers that dark spirits have invaded their home after their son inexplicably falls into an endless sleep. When they reach out to a professional for help, they learn things are a lot more personal than they thought.', 'https://image.tmdb.org/t/p/w780/v2njyKwcd32saE9mnl5YR8bDIdr.jpg', 'https://image.tmdb.org/t/p/w1280/aXOUc4dkzp9wmJG5lC2iAE6VUdt.jpg', 'https://www.youtube.com/watch?v=62rpZcMYa0A', 'James Wan', ARRAY['Patrick Wilson', 'Rose Byrne', 'Lin Shaye', 'Ty Simpkins', 'Barbara Hershey', 'Leigh Whannell', 'Angus Sampson', 'Andrew Astor']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân']::TEXT[], 102, '2011-03-31', NULL, 'US: PG-13', 7, 'ended'),
  ('4fbd1831-eeb3-5686-ae22-99160edca6e7'::UUID, 2668, 'Kỵ Sỹ Không Đầu', 'Sleepy Hollow', 'Ichabod Crane là một nhà đầu tư ở New York được giao điều tra các vụ án mạng xảy ra liên tục tại một thung lũng hẻo lánh nọ mà các nạn nhân đều bị chặt đầu đem đi mất. Những người dân địa phương cho rằng đó là việc làm của bóng ma kỵ sĩ không đầu, nhưng Crane không tin. Và dường như anh ta sẽ tìm ra sự thật... và những cái đầu sẽ rơi xuống....', 'Skeptical young detective Ichabod Crane gets transferred to the hamlet of Sleepy Hollow, New York, where he is tasked with investigating the decapitations of three people – murders the townsfolk attribute to a legendary specter, The Headless Horseman.', 'https://image.tmdb.org/t/p/w780/1GuK965FLJxqUw9fd1pmvjbFAlv.jpg', 'https://image.tmdb.org/t/p/w1280/m8t7K3LcAY7bpyQ7iQ5kGsrcjnh.jpg', 'https://www.youtube.com/watch?v=XB-y10r77V8', 'Tim Burton', ARRAY['Johnny Depp', 'Christina Ricci', 'Miranda Richardson', 'Michael Gambon', 'Casper Van Dien', 'Jeffrey Jones', 'Richard Griffiths', 'Ian McDiarmid']::TEXT[], ARRAY['Giả Tưởng', 'Giật Gân', 'Bí Ẩn', 'Kinh Dị']::TEXT[], 105, '1999-11-19', NULL, 'US: R', 7.2, 'ended'),
  ('be50af6a-79d6-5805-a7c2-c3c3ccde4f23'::UUID, 1933, 'Ngôi Nhà Toàn Ma', 'The Others', 'Lấy bối cảnh vào thời điểm hậu Chiến tranh thế giới thứ hai, tại một tòa lâu đài cổ nằm sâu trong một khu rừng quanh năm bao phủ bởi sương mù, nội dung xoay quanh câu chuyện về Grace Stewart (Nicole Kidman), một bà mẹ đơn thân một mình nuôi hai đứa con mắc chứng bệnh sợ ánh sáng. Bà mẹ là một người rất nghiêm khắc và có những quy tắc nhất định trong tòa lâu đài như là rèm cửa phải luôn được che kín, tất cả phòng đều phải được khóa kỹ. Cuộc sống của họ cứ trôi đi cho tới một ngày, có ba người gia nhân tới sống. Mọi chuyện kỳ lạ bắt đầu xảy ra trong tòa lâu đài: tiếng động kinh hoàng trong một căn phòng bí ẩn, cuốn album chụp ảnh những người chết, cô con gái tự nói chuyện một mình...', 'Grace is a religious woman who lives in an old house kept dark because her two children, Anne and Nicholas, have a rare sensitivity to light. When the family begins to suspect the house is haunted, Grace fights to protect her children at any cost in the face of strange events and disturbing visions.', 'https://image.tmdb.org/t/p/w780/p8g1vlTvpM6nr2hMMiZ1fUlKF0D.jpg', 'https://image.tmdb.org/t/p/w1280/FY0NvzWMeCZeF3xdHIu0GtFHj7.jpg', 'https://www.youtube.com/watch?v=8upnnx2onik', 'Alejandro Amenábar', ARRAY['Nicole Kidman', 'Alakina Mann', 'James Bentley', 'Fionnula Flanagan', 'Christopher Eccleston', 'Eric Sykes', 'Elaine Cassidy', 'Keith Allen']::TEXT[], ARRAY['Kinh Dị', 'Bí Ẩn', 'Giật Gân']::TEXT[], 101, '2001-08-02', NULL, 'US: PG-13', 7.6, 'ended'),
  ('dfbcfd87-3f9a-5077-bc31-5d1707b73b99'::UUID, 439079, 'Ác Quỷ Ma Sơ', 'The Nun', 'Bộ phim lấy bối cảnh vào năm 1952 tại Romania, hai nữ tu Công giáo La Mã sống tại Tu viện Carța đi vào một đường hầm tăm tối, họ cầm theo một chiếc chìa khóa với mục đích lấy lại một di tích Thiên Chúa giáo cổ đại, họ đã bị tấn công bởi một thế lực vô hình. Nữ tu Victoria may mắn sống sót đã cầm theo chiếc chìa khóa và chạy trốn khỏi kẻ tấn công, đó là một con ác quỷ xuất hiện với hình dạng một nữ tu, sau đó sơ Victoria đã tự treo cổ mình khi trong tay vẫn còn cầm chặt chiếc chìa khóa. Thi thể của cô được phát hiện bởi Frenchie, một người Pháp gốc Canada sinh sống tại Romania, anh là một dân làng chở vật tư cho các nữ tu tại tu viện Carta...', 'A priest with a dark past and a novice nearing her final vows are sent by the Vatican to Romania to investigate a nun''s death and face a demonic force.', 'https://image.tmdb.org/t/p/w780/8G99H6bZ7oqUiZinOzwUppFxQKT.jpg', 'https://image.tmdb.org/t/p/w1280/cMnVmutb5mVgIBeiMOncAbwNjvG.jpg', 'https://www.youtube.com/watch?v=UvMVjwwZOF4', 'Corin Hardy', ARRAY['Taissa Farmiga', 'Demián Bichir', 'Bonnie Aarons', 'Jonas Bloquet', 'Ingrid Bisu', 'Patrick Wilson', 'Vera Farmiga', 'Lili Taylor']::TEXT[], ARRAY['Kinh Dị']::TEXT[], 96, '2018-09-05', NULL, 'US: R', 5.9, 'ended'),
  ('c30a1ae7-1b1f-553b-a0da-02f3c2895af7'::UUID, 381283, 'mẹ!', 'mother!', 'Câu chuyện của Mother! xoay quanh cuộc sống của hai vợ chồng Jennifer Lawrence (Mother) và Javier Bardem (Him) tại một vùng quê hẻo lánh. Javier vào vai một nhà thơ đang bế tắc trong sự nghiệp, trong khi đó, Jennifer Lawrence là một người vợ luôn chăm chỉ lo lắng chuyện bếp núc trong nhà. Cuộc sống của họ bị đảo lộn khi có sự ghé thăm của hai kẻ lạ mặt, đảm nhiệm bởi Michelle Pfeiffer và Ed Harris.', 'A couple''s relationship is tested when uninvited guests arrive at their home, disrupting their tranquil existence.', 'https://image.tmdb.org/t/p/w780/mwdSdvJ3VCIlHToDlsAgmSo6AZs.jpg', 'https://image.tmdb.org/t/p/w1280/2wS8pMZgvzq7kaZb5LHX54poQnA.jpg', 'https://www.youtube.com/watch?v=I26TtPhtqqY', 'Darren Aronofsky', ARRAY['Jennifer Lawrence', 'Javier Bardem', 'Ed Harris', 'Michelle Pfeiffer', 'Brian Gleeson', 'Domhnall Gleeson', 'Jovan Adepo', 'Amanda Chiu']::TEXT[], ARRAY['Kinh Dị', 'Chính Kịch', 'Giật Gân']::TEXT[], 121, '2017-09-13', NULL, 'US: R', 6.9, 'ended'),
  ('ffd92fd9-992c-5b78-bb48-5f527bec1761'::UUID, 1576, 'Vùng Đất Quỷ Dữ', 'Resident Evil', 'Khu thí nghiệm bí mật mang mật danh Tổ ong trở thành hang ổ của những con người đột biến khát máu. Đội đặc nhiệm được điều đến giải quyết vụ việc vừa phải nhanh chóng tắt chiếc máy chủ của phòng thí nghiệm, vừa phải chiến đấu với hàng loạt sinh vật đột biến kỳ quái.  Sau khi gặp cô gái với hành tung bí ẩn mang tên Alice, mọi người trong nhóm đặc nhiệm mới phát hiện ra sự thật kinh hoàng về mối liên quan giữa tập đoàn sinh học Umbrella và cơn đại dịch zombie nơi đây.', 'When a virus leaks from a top-secret facility, turning all resident researchers into ravenous zombies and their lab animals into mutated hounds from hell, the government sends in an elite military task force to contain the outbreak.', 'https://image.tmdb.org/t/p/w780/1UKNef590A0ZaMnxsscIcWuK1Em.jpg', 'https://image.tmdb.org/t/p/w1280/8J7J7CBmapmcMaxsn9KMiaHzOU2.jpg', 'https://www.youtube.com/watch?v=HhBAIDHvRTc', 'Paul W. S. Anderson', ARRAY['Milla Jovovich', 'Michelle Rodriguez', 'Eric Mabius', 'James Purefoy', 'Martin Crewes', 'Colin Salmon', 'Pasquale Aleardi', 'Heike Makatsch']::TEXT[], ARRAY['Kinh Dị', 'Hành Động', 'Khoa Học Viễn Tưởng']::TEXT[], 100, '2002-03-15', NULL, 'US: R', 6.7, 'ended'),
  ('1cf1bb74-5430-5534-9a8a-d19c05190ec6'::UUID, 13, 'Forrest Gump', 'Forrest Gump', 'Forrest Gump là một đứa trẻ bất hạnh khi sinh ra đã không có cha, hơn nữa Forrest còn bị thiểu năng. Forrest luôn bị bạn bè cùng trang lứa trêu trọc, bắt nạt. Người bạn duy nhất của Forrest là Jenny, chính Jenny đã phát hiện ra những khả năng đặc biệt của anh. Tốt nghiệp đại học Forrest nhập ngũ và tham chiến ở Việt Nam, Bubba trở thành bạn thân thứ 2 của anh. Forrest rời chiến trường với vết thương và khả năng chơi bóng bàn xuất sắc. Những biến cố nối tiếp nhau xuất hiện làm thay đổi hoàn toàn cuộc đời Forrest.', 'A man with a low IQ has accomplished great things in his life and been present during significant historic events—in each case, far exceeding what anyone imagined he could do. But despite all he has achieved, his one true love eludes him.', 'https://image.tmdb.org/t/p/w780/yvEDqdIQnYUahG6oY9bKHMubqp8.jpg', 'https://image.tmdb.org/t/p/w1280/66Kn4XWhkuPkJxOJyPEx4U2CUfN.jpg', 'https://www.youtube.com/watch?v=Mj9IA9tTfio', 'Robert Zemeckis', ARRAY['Tom Hanks', 'Robin Wright', 'Gary Sinise', 'Sally Field', 'Mykelti Williamson', 'Michael Conner Humphreys', 'Hanna Hall', 'Haley Joel Osment']::TEXT[], ARRAY['Hài', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 142, '1994-06-23', NULL, 'US: PG-13', 8.5, 'ended'),
  ('20688ae5-b637-5751-bf71-b28d772575e9'::UUID, 597, 'Titanic', 'Titanic', 'Rose DeWitt Bukater, 101 tuổi, hồi nhớ về khoảng thời gian của bà trên tàu Titanic vào 84 năm trước . Khi bà còn là một cô gái trẻ lên tàu Titanic cùng mẹ và chồng sắp cưới. Định mệnh cho cô gặp Jack Dawson, một chàng họa sĩ trẻ tài năng. Rose kể toàn bộ câu chuyện của họ trên chuyến hành trình định mệnh đầu tiên và cuối cùng  của Titanic vào ngày 15 tháng 4 năm 1912.', NULL, 'https://image.tmdb.org/t/p/w780/yC2waNaokYeCRHSsYMB8DJK7rGS.jpg', 'https://image.tmdb.org/t/p/w1280/sCzcYW9h55WcesOqA12cgEr9Exw.jpg', 'https://www.youtube.com/watch?v=gs5GwXOgumc', 'James Cameron', ARRAY['Leonardo DiCaprio', 'Kate Winslet', 'Billy Zane', 'Kathy Bates', 'Frances Fisher', 'Gloria Stuart', 'Bill Paxton', 'Bernard Hill']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn']::TEXT[], 194, '1997-12-18', NULL, 'US: PG-13', 7.9, 'ended'),
  ('0b9d57a9-0565-5c69-96d7-4d8c260de1c6'::UUID, 313369, 'Những Kẻ Khờ Mộng Mơ', 'La La Land', 'La La Land là câu chuyện tình yêu tuyệt đẹp thời hiện đại giữa chàng nhạc công piano tài hoa chuyên diễn tại các quán bar Sebastian và cô diễn viên mới nổi xinh đẹp Mia Dolan. Thế nhưng, ở thiên đường điện ảnh Hollywood, tình yêu và sự thành công dường như không thể song hành. Khi thành công và sự nổi tiếng đến, họ sẽ phải đối mặt ra sao ...', 'Mia, an aspiring actress, serves lattes to movie stars in between auditions and Sebastian, a jazz musician, scrapes by playing cocktail party gigs in dingy bars, but as success mounts they are faced with decisions that begin to fray the fragile fabric of their love affair, and the dreams they worked so hard to maintain in each other threaten to rip them apart.', 'https://image.tmdb.org/t/p/w780/gN1VfkONPYb7frEKfpCFTHRMxj3.jpg', 'https://image.tmdb.org/t/p/w1280/nlPCdZlHtRNcF6C9hzUH4ebmV1w.jpg', 'https://www.youtube.com/watch?v=Zfy4rGzZDes', 'Damien Chazelle', ARRAY['Ryan Gosling', 'Emma Stone', 'John Legend', 'Rosemarie DeWitt', 'Finn Wittrock', 'Callie Hernandez', 'Sonoya Mizuno', 'Jessica Rothe']::TEXT[], ARRAY['Hài', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 129, '2016-12-01', NULL, 'US: PG-13', 7.9, 'ended'),
  ('c9a9d171-06a8-589e-ad08-5c5765222037'::UUID, 321612, 'Người Đẹp và Quái Vật', 'Beauty and the Beast', 'Một chàng hoàng tử trẻ sống trong một tòa lâu đài nguy nga tráng lệ. Chàng có tất cả nhưng kiêu ngạo, tàn nhẫn và không biết đến tình yêu thương...  Chàng sẽ sống ra sao khi bị biến thành một con quái vật xấu xí?  Lời nguyền chỉ được hóa giải, khi chàng học được cách yêu ai đó, và cũng được người đó đáp lại trước khi cánh hoa hồng cuối cùng rơi xuống!', 'A live-action adaptation of Disney''s version of the classic tale of a cursed prince and a beautiful young woman who helps him break the spell.', 'https://image.tmdb.org/t/p/w780/sGgWciqgbiKxmhBAJmhP9wegmCO.jpg', 'https://image.tmdb.org/t/p/w1280/uU1Mt4JWhDvl4vKb3AfxNsorkoM.jpg', 'https://www.youtube.com/watch?v=hYO2Ga4WDk4', 'Bill Condon', ARRAY['Emma Watson', 'Dan Stevens', 'Luke Evans', 'Josh Gad', 'Kevin Kline', 'Hattie Morahan', 'Haydn Gwynne', 'Gerard Horan']::TEXT[], ARRAY['Gia Đình', 'Giả Tưởng', 'Lãng Mạn']::TEXT[], 129, '2017-03-16', NULL, 'US: PG', 7, 'ended'),
  ('5b79b775-a85b-5ede-9ddd-ae651be05ef2'::UUID, 8966, 'Chạng Vạng', 'Twilight', 'Nội dung Twilight xoay quanh câu chuyện tình giữa một cô gái trẻ và một chàng trai ma cà rồng. Isabella Swan, 17 tuổi, thường gọi là Bella, từ Phoenix chuyển đến thị trấn nhỏ Forks, Washington sinh sống cùng cha Charlie Swan. Sự có mặt của cô ở đây đã làm các học sinh nam điêu đứng.Trong số các chàng trai xếp hàng theo đuổi mình, Bella đặc biệt để ý đến một chàng trai đầy vẻ bí ẩn và ma quái - Edward Cullen.', 'When Bella Swan moves to a small town in the Pacific Northwest, she falls in love with Edward Cullen, a mysterious classmate who reveals himself to be a 108-year-old vampire. Despite Edward''s repeated cautions, Bella can''t stay away from him, a fatal move that endangers her own life.', 'https://image.tmdb.org/t/p/w780/tfUvWB5jVJCckS0rAkJT1GwFxSL.jpg', 'https://image.tmdb.org/t/p/w1280/weAYfu6FfrNxEDJ3xH1XpgQcqUv.jpg', 'https://www.youtube.com/watch?v=uxjNDE2fMjI', 'Catherine Hardwicke', ARRAY['Kristen Stewart', 'Robert Pattinson', 'Billy Burke', 'Peter Facinelli', 'Ashley Greene', 'Jackson Rathbone', 'Nikki Reed', 'Kellan Lutz']::TEXT[], ARRAY['Giả Tưởng', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 121, '2008-11-20', NULL, 'US: PG-13', 6.3, 'ended'),
  ('ed417df5-d101-5984-bbcc-74dc6b05d9d5'::UUID, 4922, 'Cuộc Đời Kỳ Lạ Của Benjamin Button', 'The Curious Case of Benjamin Button', 'Phim kể về Benjamin Button, một người sinh ra đã không được bình thường như những đứa trẻ khác khi dáng vẻ bề ngoài của anh là một ông già 80 tuổi. Bị bỏ rơi tại trước cửa viện dưỡng lão bởi người cha Thomas Button, Benjamin trải qua những tháng ngày đầu đời cơ cực và đau đớn tại đây, trước khi anh dần dần trẻ lại từng ngày. Anh yêu một nữ diễn viên ballet tên Daisy, và vấn đề bắt đầu rắc rối khi anh thì cứ trẻ ra, còn cô thì ngày một già đi. Hình ảnh một đôi tình nhân đang yêu nhau say đắm bỗng chốc trở thành một đứa trẻ bi bô và một người già nhăn nheo gầy yếu đã gợi nhiều cảm xúc thương yêu, khiến ta phải ngẫm nghĩ nhiều hơn về tình yêu và những giá trị vượt khỏi quy luật thời gian của cuộc đời mình. Người xem sẽ cùng dõi theo cuộc phiêu lưu của Benjamin trong quá trình tìm hiểu cuộc sống, chiến tranh, cảm nhận tình yêu và đối mặt với những nỗi buồn chia ly...', 'Born under unusual circumstances, Benjamin Button springs into being as an elderly man in a New Orleans nursing home and ages in reverse. Twelve years after his birth, he meets Daisy, a child who flits in and out of his life as she grows up to be a dancer. Though he has all sorts of unusual adventures over the course of his life, it is his relationship with Daisy, and the hope that they will come together at the right time, that drives Benjamin forward.', 'https://image.tmdb.org/t/p/w780/26wEWZYt6yJkwRVkjcbwJEFh9IS.jpg', 'https://image.tmdb.org/t/p/w1280/2fswjyrY3GEzeoVn6mF8pNeNcgf.jpg', 'https://www.youtube.com/watch?v=lqijVXvw7_E', 'David Fincher', ARRAY['Brad Pitt', 'Cate Blanchett', 'Taraji P. Henson', 'Julia Ormond', 'Jason Flemyng', 'Tilda Swinton', 'Mahershala Ali', 'Jared Harris']::TEXT[], ARRAY['Chính Kịch', 'Giả Tưởng', 'Lãng Mạn']::TEXT[], 166, '2008-12-25', NULL, 'US: PG-13', 7.6, 'ended'),
  ('bae11c52-bfee-5f50-b663-230385957268'::UUID, 162, 'Người Kéo Học Yêu', 'Edward Scissorhands', 'Phim kể về Edward Scissorhands (Johnny Depp) - một "sản phẩm" có bàn tay gắn đầy kéo được tạo ra bởi nhà khoa học điên loạn. Anh rơi vào tình yêu với Kim Boggs (do Winona Ryder thủ vai) dù cô đã có bạn trai. Kể từ đó, Edward bắt đầu hành trình chinh phục trái tim người đẹp và nhờ đó hiểu hơn về chính mình.', 'A small suburban town receives a visit from a castaway unfinished science experiment named Edward.', 'https://image.tmdb.org/t/p/w780/e0FqKFvGPdQNWG8tF9cZBtev9Em.jpg', 'https://image.tmdb.org/t/p/w1280/uNLIMPxknsV4n3IAEDpS1iqF5dm.jpg', 'https://www.youtube.com/watch?v=S8bBjpUBbro', 'Tim Burton', ARRAY['Johnny Depp', 'Winona Ryder', 'Dianne Wiest', 'Anthony Michael Hall', 'Kathy Baker', 'Robert Oliveri', 'Conchata Ferrell', 'Caroline Aaron']::TEXT[], ARRAY['Giả Tưởng', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 105, '1990-12-07', NULL, 'US: PG-13', 7.7, 'ended'),
  ('3621659f-f9dd-5464-9c0c-f95990902688'::UUID, 102651, 'Tiên Hắc Ám', 'Maleficent', 'Maleficent kể câu chuyện chưa từng công bố về nhân vật phản diện ghi dấu ấn của Disney trong phim Người đẹp ngủ trong rừng và mối thù vì bị phản bội đã khiến cho trái tim trong sáng của cô phải hóa đá. Do trả thù và mong muốn mãnh liệt bảo vệ khu rừng phép thuật của mình, Nữ hoàng Maleficent (Angelina Jolie) tàn nhẫn đặt một lời nguyền hắc ám mà mụ lấy cắp được từ bà chị của mụ( Nữ hoàng Băng giá Elsa) lên cô công chúa mới lọt lòng Aurora mà ngay cả chính mụ và 3 đứa em họ của mụ (Rumplestiltskin, Ravenna, Zelena) cũng không thể phá bỏ được nhưng chỉ có nụ hôn của tình yêu đích thực mới đủ sức mạnh để phá vỡ được lời nguyền này. Khi đứa trẻ lớn lên, Aurora (Elle Fanning) mắc kẹt giữa cuộc xung đột sôi sục giữa các vương quốc trong rừng sâu nơi cô đã dần yêu mến và vương quốc của con người nơi cô thuộc về. Maleficent nhận ra Aurora chính là chía khóa dẫn tới hòa bình và buộc phải tiến hành những hành động quyết liệt để thay đổi hai thế giới mãi mãi." …', 'A beautiful, pure-hearted young woman, Maleficent has an idyllic life growing up in a peaceable forest kingdom, until one day when an invading army threatens the harmony of the land. She rises to be the land''s fiercest protector, but she ultimately suffers a ruthless betrayal – an act that begins to turn her heart into stone. Bent on revenge, Maleficent faces an epic battle with the invading King''s successor and, as a result, places a curse upon his newborn infant Aurora. As the child grows, Maleficent realizes that Aurora holds the key to peace in the kingdom – and to Maleficent''s true happiness as well.', 'https://image.tmdb.org/t/p/w780/5FByPAe0x94MMqoNzAYIHKZ28O7.jpg', 'https://image.tmdb.org/t/p/w1280/xjotE7aFdZ0D8aGriYjFOtDayct.jpg', 'https://www.youtube.com/watch?v=28U4LxdkNWI', 'Robert Stromberg', ARRAY['Angelina Jolie', 'Elle Fanning', 'Imelda Staunton', 'Sharlto Copley', 'Lesley Manville', 'Juno Temple', 'Sam Riley', 'Brenton Thwaites']::TEXT[], ARRAY['Giả Tưởng', 'Phiêu Lưu', 'Hành Động', 'Gia Đình', 'Lãng Mạn']::TEXT[], 97, '2014-05-28', NULL, 'US: PG', 7.1, 'ended'),
  ('a55d4bfa-6ab8-55d5-a003-aa8e72e2dba9'::UUID, 296096, 'Trước Ngày Em Đến', 'Me Before You', 'Chuyện tình của cô gái 26 tuổi Louisa Clark sống ở một thị trấn cổ miền quê nước Anh. Lou là cô gái có phong cách ăn mặc màu mè khác biệt, không có phương hướng và ước mơ cá nhân cụ thể nào cả, dù rất vui vẻ lạc quan nhưng Lou lại phải vất vả làm việc để giúp đỡ gia đình khó khăn của mình. Công việc mới của Lou làm chăm sóc cho Will Traynor, một chủ nhà băng trẻ tuổi giàu có bị liệt nửa người và phải gắn chặt đời mình trên chiếc xe lăn. Tai nạn thảm khốc 2 năm trước đã biến Will từ một chàng trai mạnh mẽ phóng khoáng trở thành một người cố chấp, đầu hàng số phận. Cuộc gặp gỡ đã trở thành bước ngoặt làm thay đổi cuộc đời và trái tim của cả hai nhân vật.', 'Lou Clark, a directionless 26-year-old from the English countryside, takes a job at the local castle as a caregiver and companion to a wealthy young banker, Will Traynor. Wheelchair-bound from an accident two years prior, the once adventurous Will has all but given up — that is until Lou determines to show him that life is worth living.', 'https://image.tmdb.org/t/p/w780/tpCmU9kKJbd02RKGQxq1pCLTB2G.jpg', 'https://image.tmdb.org/t/p/w1280/3WK7p9EdZmmvB1IbB2Vw9Rf4lXH.jpg', 'https://www.youtube.com/watch?v=T0MmkG_nG1U', 'Thea Sharrock', ARRAY['Emilia Clarke', 'Sam Claflin', 'Janet McTeer', 'Charles Dance', 'Brendan Coyle', 'Jenna Coleman', 'Matthew Lewis', 'Samantha Spiro']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn']::TEXT[], 110, '2016-06-01', NULL, 'US: PG-13', 7.9, 'ended'),
  ('b76194e2-6551-5df1-a06c-7a35470490c5'::UUID, 64682, 'Gatsby Vĩ Đại', 'The Great Gatsby', 'Giữa thành phố Long Island năm 1922, Nick Carraway bị cuốn hút bởi lối sống bí ẩn và xa hoa của người hàng xóm Jay Gatsby. Nick bị hút vào vòng xoáy của cuộc sống thượng lưu quanh Gatsby, nhưng chẳng bao lâu sau, qua các vết nứt của sự giàu có, xa hoa của Gatsby, Nick Carraway cảm nhận được nỗi ám ảnh, điên rồ, và cả những bi kịch đang chờ đợi.', 'Nick Carraway arrives in New York in 1922, an era of loose morals, glittering jazz and bootleg kings. Chasing his own American Dream, Nick encounters the mysterious millionaire Gatsby and his bewitching cousin Daisy. Soon, Nick is drawn into the captivating world of the super-rich, their illusions, loves and deceits. Bearing witness to this new world, Nick pens a tale of impossible love, incorruptible dreams and unforgettable tragedy -- mirroring our own times and struggles.​', 'https://image.tmdb.org/t/p/w780/umEB3YPzoboFVLzn4ViBQ5AyroM.jpg', 'https://image.tmdb.org/t/p/w1280/cf4YmtSnNhdG7s9ERmXyaDEznEw.jpg', 'https://www.youtube.com/watch?v=l6yANES3TMM', 'Baz Luhrmann', ARRAY['Leonardo DiCaprio', 'Tobey Maguire', 'Carey Mulligan', 'Joel Edgerton', 'Elizabeth Debicki', 'Isla Fisher', 'Jason Clarke', 'Amitabh Bachchan']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn']::TEXT[], 143, '2013-05-09', NULL, 'US: PG-13', 7.3, 'ended'),
  ('9e22f6ec-5f46-5a5a-8369-494992760379'::UUID, 399055, 'Người Đẹp và Thủy Quái', 'The Shape of Water', 'Người Đẹp & Thủy Quái là một chuyện tình không tưởng lấy bối cảnh trong thời kỳ Chiến Tranh Lạnh 1962. Làm việc cho viện nghiên cứu bí mật được bảo vệ nghiêm ngặt của chính phủ, Elisa cảm thấy trống vắng, cô đơn. Rồi cuộc đời cô gái thay đổi mãi mãi khi cô và cộng sự Zelda khám phá ra một vụ thí nghiệm kinh hoàng - tạo ra thủy quái lốt người!', 'An other-worldly story, set against the backdrop of Cold War era America circa 1962, where a mute janitor working at a lab falls in love with an amphibious man being held captive there and devises a plan to help him escape.', 'https://image.tmdb.org/t/p/w780/x2Q4QkzGn0A9SWRk72ENCH7echZ.jpg', 'https://image.tmdb.org/t/p/w1280/abirSHwWgKajV3hXhaIR5lcCIXe.jpg', 'https://www.youtube.com/watch?v=oRKnlUanptY', 'Guillermo del Toro', ARRAY['Sally Hawkins', 'Michael Shannon', 'Richard Jenkins', 'Octavia Spencer', 'Michael Stuhlbarg', 'Doug Jones', 'David Hewlett', 'Nick Searcy']::TEXT[], ARRAY['Chính Kịch', 'Giả Tưởng', 'Lãng Mạn']::TEXT[], 123, '2017-12-01', NULL, 'US: R', 7.2, 'ended'),
  ('a467526e-d3e2-5f4d-9324-18f727cd0182'::UUID, 398818, 'Gọi Em Bằng Tên Anh', 'Call Me by Your Name', 'Gọi Em Bằng Tên Anh được chuyển thể từ tiểu thuyết cùng tên của nhà văn André Aciman, lấy bối cảnh những năm 80. Nội dung tập trung vào mối quan hệ đầy cảm hứng giữa cậu bé 17 tuổi Elio (Timothée Chalamet) và chàng sinh viên 24 tuổi Oliver (Armie Hammer).  Oliver là sinh viên khảo cổ học người Mỹ đến ở trong biệt thự nhà Elio và theo học giáo sư là bố của cậu bé. Hai chàng trai trẻ đã bị cuốn vào một mối tình lãng mạn giữa khung hình tuyệt đẹp của miền quê nước Ý trong một mùa hè rực rỡ năm 1983.', 'In the summer of 1983, a 17-year-old Elio spends his days in his family''s villa in Italy. One day Oliver, a graduate student, arrives to assist Elio''s father, a professor of Greco-Roman culture. Soon, Elio and Oliver discover a summer that will alter their lives forever.', 'https://image.tmdb.org/t/p/w780/kuEhheNKMnJVqMs6UH8hhucyURd.jpg', 'https://image.tmdb.org/t/p/w1280/4Xh2a1WeTp6b8Ksvug0pAMbX3dT.jpg', 'https://www.youtube.com/watch?v=Z9AYPxH5NTM', 'Luca Guadagnino', ARRAY['Timothée Chalamet', 'Armie Hammer', 'Michael Stuhlbarg', 'Amira Casar', 'Esther Garrel', 'Victoire du Bois', 'Vanda Capriolo', 'Antonio Rimoldi']::TEXT[], ARRAY['Lãng Mạn', 'Chính Kịch']::TEXT[], 132, '2017-10-01', NULL, 'US: R', 8.1, 'ended'),
  ('f3f7ac00-1418-5f43-b832-b1792ed9b2b4'::UUID, 11036, 'Nhật Ký Tình Yêu', 'The Notebook', 'Dựa trên cuốn tiểu thuyết của nhà văn Nicholas Sparks xuất bản năm 1996, bộ phim là câu chuyện tình giữa Noah và Allie kể từ lần đầu họ gặp nhau tại North Carolina vào thập niên 40. Như mọi mối tình ngang trái khác, tình cảm giữa Noah và Allie gặp phải rào cản, xa cách trong nhiều năm liền trước khi đoàn tụ mãi mãi về sau.', 'An epic love story centered around an older man who reads aloud to a woman with Alzheimer''s. From a faded notebook, the old man''s words bring to life the story about a couple who is separated by World War II, and is then passionately reunited, seven years later, after they have taken different paths.', 'https://image.tmdb.org/t/p/w780/jSM8ufnkCpdf5sVHu9ESFQDowRF.jpg', 'https://image.tmdb.org/t/p/w1280/zdXnJqBaGFVtLoPNuMeKfEYUViZ.jpg', 'https://www.youtube.com/watch?v=FC6biTjEyZw', 'Nick Cassavetes', ARRAY['Ryan Gosling', 'Rachel McAdams', 'Gena Rowlands', 'James Garner', 'Joan Allen', 'David Thornton', 'James Marsden', 'Kevin Connolly']::TEXT[], ARRAY['Lãng Mạn', 'Chính Kịch']::TEXT[], 123, '2004-06-25', NULL, 'US: PG-13', 7.9, 'ended'),
  ('4ada9891-e720-57d2-9074-7ef3ba114327'::UUID, 82693, 'Tình Yêu Tìm Lại', 'Silver Linings Playbook', 'Được chuyển thể từ cuốn tiểu thuyết của nhà văn Matthew Quick, "Silver Linings Playbook" kể về quá trình bình phục và đoàn tụ với gia đình của một giáo viên thất nghiệp sau 8 tháng điều trị tại bệnh viện tâm thần. Tham gia diễn xuất chính trong bộ phim này là nam diễn viên Bradley Cooper và minh tinh màn bạc Jennifer Lawrence.', 'After losing his job and wife, and spending time in an institution, a former teacher winds up living with his parents. He wants to rebuild his life and reconcile with his wife, but his father would be happy if he shared his obsession with the Philadelphia Eagles. Things get complicated when he meets Tiffany Maxwell who offers to help him reconnect with his wife if he will do something very important for her in exchange.', 'https://image.tmdb.org/t/p/w780/6Hn7clMmfgW2If1E1EjAR0JfMNz.jpg', 'https://image.tmdb.org/t/p/w1280/12GpsUm9nVVKFlcjDTflKLClFVA.jpg', 'https://www.youtube.com/watch?v=EI_3ywJLQio', 'David O. Russell', ARRAY['Bradley Cooper', 'Jennifer Lawrence', 'Robert De Niro', 'Jacki Weaver', 'अनुपम खेर', 'Chris Tucker', 'Julia Stiles', 'Shea Whigham']::TEXT[], ARRAY['Chính Kịch', 'Hài', 'Lãng Mạn']::TEXT[], 122, '2012-11-16', NULL, 'US: R', 7.2, 'ended'),
  ('bb979363-71ef-5431-97b0-19a8a4d1918c'::UUID, 194, 'Cuộc Đời Của Amelie Poulain', 'Le Fabuleux Destin d''Amélie Poulain', 'Cuộc Đời Của Amelie Poulain: Làm hầu bàn trong quán cà phê Hai Cối Xay Gió ở Paris, Amelie Poulain (Audrey Tatou) là một trong nhiều cô gái trẻ độc thân, nhút nhát, ít bạn và không phải người mẫu mà các đạo diễn tìm kiếm. Nhưng tiềm ẩn trong cô gái 23 tuổi này là lòng kính Chúa, sự cần cù siêng năng, thông minh và một người tình tuyệt vời. Khi còn là một cô bé ngây thơ, Amelie có một cuộc sống thanh bình nếu không muốn nói là khá tẻ nhạt ở thủ đô Paris. Ngày bé do bố cô chuẩn đoán nhầm cô bị bệnh tim nên cô không được đến trường, chỉ quanh quẩn tự học ở nhà và chơi cùng mấy con rối nhỏ. Lớn lên giữa môi trường không có bạn bè, Amelie có phần cô độc và nhút nhát với thế giới bên ngoài. Thế rồi một ngày kia, Amelie khám phá ra chiếc hộp đồng nhỏ ẩn ...', 'At a tiny Parisian café, the adorable yet painfully shy Amélie accidentally discovers a gift for helping others. Soon Amelie is spending her days as a matchmaker, guardian angel, and all-around do-gooder. But when she bumps into a handsome stranger, will she find the courage to become the star of her very own love story?', 'https://image.tmdb.org/t/p/w780/tdXtLG6L1QMwrv0MNdW6B9IwC8B.jpg', 'https://image.tmdb.org/t/p/w1280/6n53UI4mX9QMfe2S0Pgt8mGebY1.jpg', 'https://www.youtube.com/watch?v=555A7T_kmIc', 'Jean-Pierre Jeunet', ARRAY['Audrey Tautou', 'Mathieu Kassovitz', 'Rufus', 'Serge Merlin', 'Jamel Debbouze', 'Clotilde Mollet', 'Claire Maurier', 'Isabelle Nanty']::TEXT[], ARRAY['Hài', 'Lãng Mạn']::TEXT[], 122, '2001-04-25', NULL, 'FR: TP', 7.9, 'ended'),
  ('af5b8cd1-4c3c-5088-a98b-2ea11fc53525'::UUID, 216015, 'Năm Mươi Sắc Thái', 'Fifty Shades of Grey', 'Câu chuyện bắt đầu khi cô sinh viên Anastasia Steele (Dakota Johnson thủ vai) tới phỏng vấn triệu phú trẻ tuổi Christian Grey (Jamie Dornan) cho tờ tạp chí của trường. Ana đơn giản, trong sáng đã lọt vào mắt xanh của kẻ luôn thích kiểm soát mọi việc là Christian. Anh bắt đầu tiếp cận Ana và cuốn cô vào vòng xoáy của tình ái và nhục cảm. Nhưng đây không phải câu chuyện tình đơn thuần giữa chàng hoàng tử giàu sang lịch lãm và cô gái ngây thơ chân chất.', 'When college senior Anastasia Steele steps in for her sick roommate to interview prominent businessman Christian Grey for their campus paper, little does she realize the path her life will take. Christian, as enigmatic as he is rich and powerful, finds himself strangely drawn to Ana, and she to him. Though sexually inexperienced, Ana plunges headlong into an affair -- and learns that Christian''s true sexual proclivities push the boundaries of pain and pleasure.', 'https://image.tmdb.org/t/p/w780/rtMfrW81vdFw245Md7NqoQ90MtA.jpg', 'https://image.tmdb.org/t/p/w1280/7IGKrY1f1KfwMipx9wZC4NRgIdF.jpg', 'https://www.youtube.com/watch?v=6FDTMRK7-24', 'Sam Taylor-Johnson', ARRAY['Dakota Johnson', 'Jamie Dornan', 'Jennifer Ehle', 'Eloise Mumford', 'Victor Rasuk', 'Luke Grimes', 'Marcia Gay Harden', 'Rita Ora']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn', 'Giật Gân']::TEXT[], 125, '2015-02-11', NULL, 'US: R', 5.9, 'ended'),
  ('b8be8cc5-e4fc-59d3-bee6-a031dc97505c'::UUID, 332562, 'Vì Sao Vụt Sáng', 'A Star Is Born', 'Chàng nghệ sỹ nhạc đồng quê Jackson Maine và ca sỹ vô danh Ally sẽ khiến bạn đắm chìm trong thế giới âm nhạc rực rỡ và rung động đến từng phút giây. Liệu định mệnh sẽ viết nên cái kết nào cho cả hai khi đứng giữa tình yêu và sự nghiệp?', NULL, 'https://image.tmdb.org/t/p/w780/5UAaiQwCLca8MwCHgXPQQZO0SAO.jpg', 'https://image.tmdb.org/t/p/w1280/dDYpjrwh1wNVQk0rEpc9P81wQt4.jpg', 'https://www.youtube.com/watch?v=hIbMYWyn7hQ', 'Bradley Cooper', ARRAY['Lady Gaga', 'Bradley Cooper', 'Sam Elliott', 'Andrew Dice Clay', 'Rafi Gavron', 'Anthony Ramos', 'Dave Chappelle', 'Alec Baldwin']::TEXT[], ARRAY['Âm Nhạc', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 136, '2018-10-03', NULL, 'US: R', 7.5, 'ended'),
  ('194fa450-b16d-5007-b76f-2208a6d4a02f'::UUID, 222935, 'Khi Lỗi Thuộc Về Những Vì Sao', 'The Fault in Our Stars', 'Được chuyển thể từ tiểu thuyết cùng tên rất ăn khách của nhà văn John Green, The Fault in Our Stars là bộ phim tình cảm, lãng mạn được chờ đợi nhất mùa phim hè năm nay. Phim nói về tình yêu của Hazel, cô gái mắc bệnh ung thư giai đoạn cuối, và chàng trai trẻ Gus. Có đề tài là tình yêu trong cơn bạo bệnh nhưng tiểu thuyết The Fault in Our Stars từng gây sốt bởi sự nhẹ nhàng, hài hước và tính lạc quan trong câu chuyện. Thể hiện vai chính, Hazel, là kiều nữ đang lên của Hollywood - Shailene Woodley. Cô sẽ đóng cặp với nam diễn viên Ansel Elgort - người đóng vai anh trai mình trong Divergent vừa ra mắt hồi tháng ba. The Fault in Our Stars được quay tại Pittsburgh (Mỹ) và Amsterdam (Hà Lan).', 'Despite the tumor-shrinking medical miracle that has bought her a few years, Hazel has never been anything but terminal, her final chapter inscribed upon diagnosis. But when a patient named Augustus Waters suddenly appears at Cancer Kid Support Group, Hazel''s story is about to be completely rewritten.', 'https://image.tmdb.org/t/p/w780/pZvgLZ2SaLlZMuKdCSJ5TWGXXPN.jpg', 'https://image.tmdb.org/t/p/w1280/oQaVV7p916HO5MDI820zzs1pin9.jpg', 'https://www.youtube.com/watch?v=3Ixw15DE-xY', 'Josh Boone', ARRAY['Shailene Woodley', 'Ansel Elgort', 'Nat Wolff', 'Laura Dern', 'Sam Trammell', 'Willem Dafoe', 'Lotte Verbeek', 'Ana Dela Cruz']::TEXT[], ARRAY['Lãng Mạn', 'Chính Kịch']::TEXT[], 126, '2014-06-03', NULL, 'US: PG-13', 7.6, 'ended'),
  ('c8bb7940-981b-5f27-b2b4-47eed0117dea'::UUID, 854, 'Mặt Nạ Xanh', 'The Mask', 'Câu chuyện vui nhộn về anh chàng nhân viên ngân hàng Stanley Ipkiss nhút nhát, vụng về. Kể từ khi tình cờ tìm thấy chiếc mặt nạ của Chúa tể bóng đêm Loki, cuộc đời Ipkiss thay đổi hoàn toàn. Anh chàng có những khả năng siêu tưởng điên rồ như biến đổi cơ thể, bay nhảy lung tung, dọa nạt mọi người và nhiều câu chuyện hài hước khác…', 'Timid bank clerk Stanley Ipkiss discovers a magical mask infused with the spirit of the Norse god Loki. Donning it transforms him into an unrestrained, green-faced, cartoon-like wild man. While the mask grants him the confidence to woo a local singer, it also makes him the target of a ruthless mobster.', 'https://image.tmdb.org/t/p/w780/jPC2eYub74zwf2tPGVtzSlBW6Oy.jpg', 'https://image.tmdb.org/t/p/w1280/bQlw59HncOXX9alFlOYKHAvSnm.jpg', 'https://www.youtube.com/watch?v=uPrUiKgQVQk', 'Chuck Russell', ARRAY['Jim Carrey', 'Peter Riegert', 'Peter Greene', 'Amy Yasbeck', 'Richard Jeni', 'Orestes Matacena', 'Tim Bagley', 'Nancy Fish']::TEXT[], ARRAY['Hài', 'Giả Tưởng', 'Tội Phạm', 'Lãng Mạn']::TEXT[], 101, '1994-07-29', NULL, 'US: PG-13', 7, 'ended'),
  ('b52fbfbc-eeb3-52a8-b6c4-f4bdd6aeef00'::UUID, 12405, 'Triệu Phú Ổ Chuột', 'Slumdog Millionaire', 'Phim lấy bối cảnh cuộc thi “Ai Là Triệu Phú” phiên bản Ấn Độ Jamal Malik, một thanh niên bất hạnh không nhà cửa, không cha mẹ đăng kí tham dự chương trình với lý do thật đặc biệt nhưng đã xuất sắc vượt qua câu hỏi 10 triệu Rupee đúng lúc đó thời lượng của chương trình hết. Jamal bị cảnh sát bắt vì nghi ngờ anh gian lận trong cuộc thi cuối cùng họ đã phải thả Jamal để anh tiếp tục cuộc thi khi biết lý do giúp Jamal có thể trả lời tất cả câu hỏi ở nhiều lĩnh vực mà người dẫn chương trình đưa ra. Lý do đó là gì? Jamal có chiến thắng ở phần còn lại của chương trình? Slumdog Millionaire là bức tranh về cuộc sống của hàng chục triệu người thuộc tầng lớp dưới của xã hội Ấn Độ những người đang hàng ngày giành giật miếng cơm manh áo để tồn tại trong hoàn cảnh vô cùng khắc nghiệt nhưng dường như khao khát vươn lên không bao giờ tắt trong họ. Slumdog Millionaire đã giành tới 8 giải Oscar và hàng chục danh hiệu danh giá khác.', 'A teenager reflects on his life after being accused of cheating on the Indian version of "Who Wants to be a Millionaire?".', 'https://image.tmdb.org/t/p/w780/p1S0drWocOJ5ePeqnJaccGHD6CR.jpg', 'https://image.tmdb.org/t/p/w1280/1wZoVT9RJsZmNjg8CecXqSgFUd9.jpg', 'https://www.youtube.com/watch?v=AIzbwV7on6Q', 'Danny Boyle', ARRAY['Dev Patel', 'Freida Pinto', 'Madhur Mittal', 'अनिल कपूर', 'महेश मांजरेकर', 'Saurabh Shukla', 'Irrfan Khan', 'Ankur Vikal']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn']::TEXT[], 121, '2008-11-12', NULL, 'US: R', 7.7, 'ended'),
  ('56825427-322e-5a2d-bb3b-d91ef240c033'::UUID, 453, 'Một Tâm Hồn Đẹp', 'A Beautiful Mind', 'Một Tâm Hồn Đẹp (A Beautiful Mind) là một bộ phim tiểu sử kể về cuộc đời của nhà kinh tế học John Nash, giáo sư thuộc viện Toán học trường Princeton từng đoạt giải Nobel kinh tế 1994. Nguyên tác là cuốn tiểu thuyết thể loại truyện ký được Sylvia Nasar dựa trên tư liệu về cuộc đời của Nash viết thành, được tặng giải thưởng Sách Quốc gia 1998 và nhận một để cử giải Pulitzer. Câu chuyện bắt đầu với những năm đầu đời của một thần đồng trẻ tuổi tên John Nash. Tuy nhiên anh sớm bị mắc căn bệnh Tâm thần phân liệt hoang tưởng và phải đấu tranh với nó trong sự gánh nặng đầy đau đớn, chịu đựng của người vợ Alicia và bạn bè. Những khi tâm thần ổn định, anh vẫn tiếp tục nghiên cứu và đạt được những thành tựu lớn, trở thành một trong những nhà toán học có tầm ảnh hưởng nhất của nước Mỹ. A Beautiful Mind thắng 4 giải Oscar, bao gồm Phim hay nhất, Đạo diễn xuất sắc nhất, Kịch bản chuyển thể xuất sắc nhất và Nữ diễn viên phụ xuất sắc nhất.', 'From the heights of notoriety to the depths of depravity, John Forbes Nash Jr. experiences it all. As a brilliant but socially awkward mathematician, he made a groundbreaking discovery early in his career and stands on the brink of international acclaim. But as the handsome and arrogant Nash accepts secret work in cryptography, he becomes entangled in a mysterious conspiracy. His life takes a nightmarish turn and he soon finds himself on a painful and harrowing journey of self-discovery.', 'https://image.tmdb.org/t/p/w780/rEIg5yJdNOt9fmX4P8gU9LeNoTQ.jpg', 'https://image.tmdb.org/t/p/w1280/hCJFWTPghXCwwSpvPpAoIB8318Q.jpg', 'https://www.youtube.com/watch?v=WFJgUm7iOKw', 'Ron Howard', ARRAY['Russell Crowe', 'Jennifer Connelly', 'Ed Harris', 'Paul Bettany', 'Christopher Plummer', 'Adam Goldberg', 'Josh Lucas', 'Anthony Rapp']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn']::TEXT[], 135, '2001-12-14', NULL, 'US: PG-13', 7.9, 'ended'),
  ('a012be1a-ec68-5ca3-bbbf-81302f6012a1'::UUID, 19913, '(500) Ngày Yêu', '(500) Days of Summer', 'Là một bộ phim tình cảm xoay quanh câu chuyện tình yêu của Summer Finn - một cô gái xinh xắn với mái tóc đen tự nhiên kiểu cổ điển, sau cú sốc đau buồn của gia đình đã không còn tin vào tình yêu. Tom Hansen đang làm công việc viết bưu thiếp cho một công ty nhỏ dù mơ ước của anh là trở thành một kiến trúc sư. Ngay từ ánh mắt đầu tiên, Tom đã phải lòng Summer. Cả hai trở thành một cặp lý tưởng. 500 ngày ở bên cô là khoảng thời gian anh thấy mình hạnh phúc nhất. Những tưởng rằng mình sẽ là người sưởi ấm trái tim cô nhưng cuối cùng, anh nhận ra đó chỉ là một giấc mơ ngọt ngào. Cô nói lời chia tay anh mà không có một lý do… Đây là một câu chuyện nói về tình yêu những cảm xúc chân thực, những khoảnh khắc mà mỗi chúng ta rồi sẽ có lúc phải trải qua và cả những quan niệm mới mẻ về tình yêu.', 'Tom, greeting-card writer and hopeless romantic, is caught completely off-guard when his girlfriend, Summer, suddenly dumps him. He reflects on their 500 days together to try to figure out where their love affair went sour, and in doing so, Tom rediscovers his true passions in life.', 'https://image.tmdb.org/t/p/w780/yAFxBD0csJJYuQgXFcGlO6Tbz9e.jpg', 'https://image.tmdb.org/t/p/w1280/1M2i4Mxd03elGOTmEkIvqrHfmyS.jpg', 'https://www.youtube.com/watch?v=oBxR8cEt2xM', 'Marc Webb', ARRAY['Joseph Gordon-Levitt', 'Zooey Deschanel', 'Geoffrey Arend', 'Chloë Grace Moretz', 'Matthew Gray Gubler', 'Clark Gregg', 'Patricia Belcher', 'Rachel Boston']::TEXT[], ARRAY['Hài', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 95, '2009-07-17', NULL, 'US: PG-13', 7.3, 'ended'),
  ('d94a9b26-fc99-5eae-bbb9-0dd937c4b044'::UUID, 266856, 'Thuyết Yêu Thương', 'The Theory of Everything', 'Dựa trên cuốn hồi ký của bà Jane Hawking, bộ phim tâm lý tình cảm được 5 đề cử Oscar 2015 là một trong những tác phẩm hút nước mắt khán giả nhất năm qua.Năm 2002, A Beautiful Mind - bộ phim về cuộc đời nhà bác học John Nash của thế kỷ 20 - chiến thắng thuyết phục với 4 tượng vàng Oscar. Trong niềm ngưỡng mộ dành cho một trí tuệ siêu phàm, một tâm hồn cao đẹp cùng tâm huyết của đoàn làm phim, không ít người đã tiên đoán, sẽ có ngày Hollywood vinh danh Stephen Hawking - người khổng lồ của khoa học thế kỷ 21 như thế. The Theory of Everything, ra đời hơn một thập kỷ sau, đã biến những lời dự đoán cũng như niềm mong mỏi của khán giả yêu điện ảnh thành hiện thực.Đây không phải là bộ phim đầu tiên lấy cảm hứng về Stephen Hawking. ...', 'Once a healthy, active young man, Hawking received an earth-shattering diagnosis at 21 years of age. With Jane fighting tirelessly by his side, Stephen embarks on his most ambitious scientific work, studying the very thing he now has precious little of – time.', 'https://image.tmdb.org/t/p/w780/9AezJlUCSUuUCWifwdQaz1taTeL.jpg', 'https://image.tmdb.org/t/p/w1280/dh2QT3TPtAQf057yeLpNMuaJlmp.jpg', 'https://www.youtube.com/watch?v=_EnhOKk7BxM', 'James Marsh', ARRAY['Eddie Redmayne', 'Felicity Jones', 'Charlie Cox', 'Emily Watson', 'Simon McBurney', 'David Thewlis', 'Maxine Peake', 'Harry Lloyd']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn']::TEXT[], 123, '2014-11-07', NULL, 'US: PG-13', 7.8, 'ended'),
  ('0e230089-6f47-5212-a7a8-eb94401c51bb'::UUID, 420817, 'Aladdin', 'Aladdin', 'Aladdin là một phiên bản live action đầy màu sắc sống động và không kém phần hồi hộp, được chuyển thể từ bộ phim hoạt hình kinh điển cả hãng phim Disney. Câu chuyện xoay quanh chàng hoàng tử khu ổ chuột Aladdin – một thanh niên trẻ tuổi dũng cảm và nàng công chúa Jasmine mạnh mẽ, đương nhiên phải kể đến thần đèn Genie – người nắm giữ chìa khóa thay đổi tương lại sau này của họ.', 'A kindhearted street urchin named Aladdin embarks on a magical adventure after finding a lamp that releases a wisecracking genie while a power-hungry Grand Vizier vies for the same lamp that has the power to make their deepest wishes come true.', 'https://image.tmdb.org/t/p/w780/sywGy6zWN6bl7NRNZhRs8dFqzUz.jpg', 'https://image.tmdb.org/t/p/w1280/rVqY0Bo4Npf6EIONUROxjYAJfmD.jpg', 'https://www.youtube.com/watch?v=h44kpghglWw', 'Guy Ritchie', ARRAY['Mena Massoud', 'Will Smith', 'Naomi Scott', 'Marwan Kenzari', 'Navid Negahban', 'Nasim Pedrad', 'Billy Magnussen', 'Numan Acar']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Lãng Mạn', 'Gia Đình']::TEXT[], 127, '2019-05-22', NULL, 'US: PG', 7.1, 'ended'),
  ('eabb17a2-2fb7-5dea-beab-b411af686db9'::UUID, 3933, 'Cô Dâu Ma', 'Corpse Bride', 'Câu chuyện là bộ phim hoạt hình lãng mạn hài hước: Victor – con trai một gia đình bán cá sắp làm đám cưới với Victoria – con gái của một gia đình quý tộc danh giá đang đến hồi khánh kiệt. Sau buổi “thực tập” cử hành hôn lễ bất thành, Victor đã một mình đi ra cánh rừng hoang vắng để tập dợt vai trò chú rể. Sau khi đọc xong lời nguyền, anh chàng Victor đã vô tình đeo chiếc nhẫn cưới vào một cành cây có hình dạng ngón tay ở một bìa rừng và đọc to lời thề vợ chồng. Không ngờ cành cây đó lại chính là ngón tay của một xác cô gái bị mưu sát đã lâu. Và như một câu chuyện cười có thật, bây giờ xác chết đó nhờ lời thề của Victor mà trở thành người vợ chính thức của anh chàng. Liệu người và ma, trần thế và địa ngục, ở đâu Victor sẽ tìm được tình yêu?', 'In a 19th-century European village, a young man about to be married is whisked away to the underworld and wed to a mysterious corpse bride, while his real bride waits bereft in the land of the living.', 'https://image.tmdb.org/t/p/w780/joxBiYlVBe6FzlwkqCCKOnTkmYF.jpg', 'https://image.tmdb.org/t/p/w1280/v23fWgJUEt8EMmvn19btIacxP8E.jpg', 'https://www.youtube.com/watch?v=BgwJEpmPKk8', 'Mike Johnson', ARRAY['Johnny Depp', 'Helena Bonham Carter', 'Emily Watson', 'Tracey Ullman', 'Paul Whitehouse', 'Joanna Lumley', 'Albert Finney', 'Richard E. Grant']::TEXT[], ARRAY['Lãng Mạn', 'Giả Tưởng', 'Hoạt Hình']::TEXT[], 77, '2005-09-12', NULL, 'US: PG', 7.6, 'ended'),
  ('8a9444dd-a069-5720-8979-4c8962cac8b9'::UUID, 744, 'Phi Công Siêu Đẳng', 'Top Gun', 'Tom Cruise vào vai một phi công tài ba phải vật lộn để cân bằng cuộc sống, trách nhiệm và tình cảm trong lúc đua tranh tại trường huấn luyện máy bay chiến đấu Hải Quân.', 'For Lieutenant Pete ''Maverick'' Mitchell and his friend and co-pilot Nick ''Goose'' Bradshaw, being accepted into an elite training school for fighter pilots is a dream come true. But a tragedy, as well as personal demons, will threaten Pete''s dreams of becoming an ace pilot.', 'https://image.tmdb.org/t/p/w780/uT0QszlFkBTBYJMG1raRMQHrF6x.jpg', 'https://image.tmdb.org/t/p/w1280/dBgxEkWe17R0AJDAvAhpeVELQx2.jpg', 'https://www.youtube.com/watch?v=Klc__shdj88', 'Tony Scott', ARRAY['Tom Cruise', 'Kelly McGillis', 'Val Kilmer', 'Anthony Edwards', 'Tom Skerritt', 'Michael Ironside', 'John Stockwell', 'Barry Tubb']::TEXT[], ARRAY['Hành Động', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 110, '1986-05-16', NULL, 'US: PG', 7.1, 'ended'),
  ('b132111a-f892-51aa-889a-871f72ff7cfb'::UUID, 18239, 'Chạng Vạng: Trăng Non', 'The Twilight Saga: New Moon', 'Trong The Twilight Saga: New Moon, chương thứ hai trong series thành công ngoài mong đợi và là hội chứng văn hóa toàn cầu của Stephenie Meyer, mối tình lãng mạn giữa người và ma cà rồng được nâng lên một tầm cao mới khi Bella Swan (Kristen Stewart) thử thách định mệnh của mình chỉ để chớp lấy một khoảnh khắc ngắn ngủi được nhìn thấy người yêu Edward Cullen (Robert Pattinson). Khi cô tiến thẳng đến tận cùng bí mật của thế giới siêu nhiên mà cô hằng mong ước sẽ được trở thành một phần của nó, cô khám phá ra hai bí mật cổ đại có khả năng đe dọa cuộc sống của mình lớn nhất từ trước đến nay. Ngay sau sinh nhật lần thứ 18 của Bella, Edward quyết định rời bỏ cô để bảo vệ cô khỏi nguy hiểm.', 'Forks, Washington resident Bella Swan is reeling from the departure of her vampire love, Edward Cullen, and finds comfort in her friendship with Jacob Black, a werewolf. But before she knows it, she''s thrust into a centuries-old conflict, and her desire to be with Edward at any cost leads her to take greater and greater risks.', 'https://image.tmdb.org/t/p/w780/1eDlOEEvPxxf9NFox8FZkjezJBl.jpg', 'https://image.tmdb.org/t/p/w1280/dF2c20sRDgySZLaLS2OUerL07sz.jpg', 'https://www.youtube.com/watch?v=q58iQSHhZGg', 'Chris Weitz', ARRAY['Kristen Stewart', 'Robert Pattinson', 'Taylor Lautner', 'Dakota Fanning', 'Michael Sheen', 'Ashley Greene', 'Rachelle Lefevre', 'Billy Burke']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 138, '2009-11-18', NULL, 'US: PG-13', 6, 'ended'),
  ('59596b16-a38d-552f-ba5f-961701f14a78'::UUID, 50646, 'Yêu Điên Dại', 'Crazy, Stupid, Love.', 'Cal Weaver quá chán nản với những vấn đề không thể tháo gỡ trong cuộc hôn nhân 25 năm của mình. Sau khi được một anh chàng đẹp trai sát gái tư vấn, Cal đã biến mình thành một tay chơi phong độ khác hẳn với mình lúc trước.', 'Cal Weaver is living the American dream. He has a good job, a beautiful house, great children and a beautiful wife, named Emily. Cal''s seemingly perfect life unravels, however, when he learns that Emily has been unfaithful and wants a divorce. Over 40 and suddenly single, Cal is adrift in the fickle world of dating. Enter, Jacob Palmer, a self-styled player who takes Cal under his wing and teaches him how to be a hit with the ladies.', 'https://image.tmdb.org/t/p/w780/p4RafgAPk558muOjnBMHhMArjS2.jpg', 'https://image.tmdb.org/t/p/w1280/vyrCniZsrXZAW08eECKIp1BMLPh.jpg', 'https://www.youtube.com/watch?v=W7U03cW7k-Y', 'Glenn Ficarra', ARRAY['Steve Carell', 'Ryan Gosling', 'Julianne Moore', 'Emma Stone', 'Lio Tipton', 'Jonah Bobo', 'Joey King', 'Marisa Tomei']::TEXT[], ARRAY['Hài', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 118, '2011-07-28', NULL, 'US: PG-13', 7.3, 'ended'),
  ('cf3ea4e0-9d71-5423-bc54-7b47cc7210f7'::UUID, 122906, 'Đã Đến Lúc', 'About Time', 'Vào bữa tiệc trước thềm năm mới, Tim được chính cha mình “giới thiệu” về khả năng “truyền thống” của gia đình: có thể đi xuyên qua thời gian trở về quá khứ. Ngỡ ngàng và thích thú, Tim quyết định phải thay đổi cuộc đời mình khiến nó tốt đẹp hơn bằng việc đi tìm cho bản thân một cô bạn gái… Kết quả là, cậu đã thấy mục tiêu nhưng liệu rằng, những khả năng thiên phú của Tim có thể giúp cậu dễ dàng chinh phục được nàng hay không?', NULL, 'https://image.tmdb.org/t/p/w780/zJz1RFjvo1WPX8yZ1S6qtyye5D.jpg', 'https://image.tmdb.org/t/p/w1280/einbto9qLXFx9QXxEHylaxDbKPx.jpg', 'https://www.youtube.com/watch?v=cjZCj81d8tQ', 'Richard Curtis', ARRAY['Domhnall Gleeson', 'Rachel McAdams', 'Bill Nighy', 'Tom Hollander', 'Margot Robbie', 'Lydia Wilson', 'Lindsay Duncan', 'Richard Cordery']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn', 'Giả Tưởng']::TEXT[], 123, '2013-06-27', NULL, 'US: R', 7.9, 'ended'),
  ('86c0b693-3b25-5e60-ac84-d508be5105f5'::UUID, 664413, '365 Ngày', '365 dni', 'Nội dung phim xoay quanh câu chuyện tình kỳ lạ và cũng rất lãng mạn giữa cô nàng chuyên viên kinh doanh Laura Biel và ông chủ trẻ tuổi Massimo Torricelli.Sau khi cha anh bất ngờ bị ám sát, Massimo bất đắc dĩ phải tiếp quản vị trí của cha mình. Còn Laura là cô gái tài năng, có một cuộc sống ổn định, sự nghiệp thành công nhưng thiếu đi niềm đam mê. Sau khi đến Sicily với đối tác và bạn bè của mình, Laura bất ngờ bị Massimo bắt cóc và cô không hề biết rằng anh ta là người đàn ông quyền lực nhất tại đây. Sau đó, Massimo cho cô 365 ngày để yêu anh, liệu mọi chuyện rồi sẽ đi về đâu.', 'A woman falls victim to a dominant mafia boss, who imprisons her and gives her one year to fall in love with him.', 'https://image.tmdb.org/t/p/w780/ibaDBJBAvWd4J5lzfbpq1PJ6ZU1.jpg', 'https://image.tmdb.org/t/p/w1280/29mZ5bR5m2w3xuvwJH7BHMFQQwH.jpg', NULL, 'Barbara Białowąs', ARRAY['Anna-Maria Sieklucka', 'Michele Morrone', 'Bronisław Wrocławski', 'Otar Saralidze', 'Magdalena Lamparska', 'Natasza Urbańska', 'Grażyna Szapołowska', 'Tomasz Stockinger']::TEXT[], ARRAY['Lãng Mạn', 'Chính Kịch', 'Tội Phạm']::TEXT[], 114, '2020-02-07', NULL, 'US: R', 7, 'ended'),
  ('39ef0b75-a693-5ba3-9634-785e2fc3f88b'::UUID, 50620, 'Chạng Vạng: Hừng Đông - Phần 2', 'The Twilight Saga: Breaking Dawn - Part 2', 'Sau sự ra đời của Renesmee – con gái của Bella và Edward, nhà Cullens thu thập các gia tộc ma cà rồng khác để bảo vệ cô bé khỏi một cáo buộc sai lầm đang đẩy cả gia đình đối đầu gia tộc Volturi.  Bella khi này đã hoàn toàn khống chế được bản năng Ma Cà Rồng trong mình và trở thành người có sức mạnh lớn nhất của nhà Cullen. Một cuộc chiến cuối cùng và duy nhất sẽ diễn ra...', 'After the birth of Renesmee, the Cullens gather other vampire clans in order to protect the child from a false allegation that puts the family in front of the Volturi.', 'https://image.tmdb.org/t/p/w780/xQ2X9Kc2W0kBGaSDhLT3CXHzYus.jpg', 'https://image.tmdb.org/t/p/w1280/qkl57wzSFrpi2sRpoc2mZJbMuLP.jpg', 'https://www.youtube.com/watch?v=bUXjqQ4GKRg', 'Bill Condon', ARRAY['Kristen Stewart', 'Robert Pattinson', 'Taylor Lautner', 'Peter Facinelli', 'Elizabeth Reaser', 'Ashley Greene', 'Jackson Rathbone', 'Kellan Lutz']::TEXT[], ARRAY['Giả Tưởng', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 115, '2012-11-13', NULL, 'US: PG-13', 6.5, 'ended'),
  ('f5cfb8eb-9129-5dfc-96ca-26ecb02d6eff'::UUID, 50619, 'Chạng Vạng: Hừng Đông - Phần 1', 'The Twilight Saga: Breaking Dawn - Part 1', 'Hừng Đông Phần 1 mở đầu khi sau nhiều khó khăn cách trở cuối cùng Bella và Edward cũng đến được với nhau bằng một đám cưới hạnh phúc nhưng "ngày vui ngắn chẳng tày gang" khi Bella có thai, sinh mạng mang nửa dòng máu người và nửa dòng máu Ma cà rồng. Đặc biệt cái thai này còn gây nguy hiểm tới tính mạng của Bella và cả gia tộc Ma cà rồng.', 'Bella Swan and Edward Cullen''s honeymoon phase is abruptly disrupted by betrayals and unforeseen tragedies that endanger their world.', 'https://image.tmdb.org/t/p/w780/qzfWlrVAC59EsMwQ71Ke8c62Qn4.jpg', 'https://image.tmdb.org/t/p/w1280/iPqoeXEfByDN399PQQ42IJHV2kN.jpg', 'https://www.youtube.com/watch?v=PQNLfo-SOR4', 'Bill Condon', ARRAY['Kristen Stewart', 'Robert Pattinson', 'Taylor Lautner', 'Billy Burke', 'Peter Facinelli', 'Michael Sheen', 'Elizabeth Reaser', 'Kellan Lutz']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Lãng Mạn']::TEXT[], 117, '2011-11-16', NULL, 'US: PG-13', 6.2, 'ended'),
  ('8c86c55f-f7bd-557f-b441-a2d423f84e2a'::UUID, 24021, 'Chạng Vạng: Nhật Thực', 'The Twilight Saga: Eclipse', 'Đưa tính hành động, tình yêu, tình bạn, sự ghen tuông, niềm đam mê - những gì đã đưa Twilight và The Twilight Saga: New Moon trở thành bom tấn trên toàn thế giới - lên một tầm cao mới, The Twilight Saga: Eclipse được đốt cháy bởi những âm mưu báo thù và câu chuyện tình yêu ngang trái.', 'Bella once again finds herself surrounded by danger as Seattle is ravaged by a string of mysterious killings and a malicious vampire continues her quest for revenge. In the midst of it all, she is forced to choose between her love for Edward and her friendship with Jacob, knowing that her decision has the potential to ignite the ageless struggle between vampire and werewolf. With her graduation quickly approaching, Bella is confronted with the most important decision of her life.', 'https://image.tmdb.org/t/p/w780/mlzCkWbwDKXCVC6Nyj05rOIIDts.jpg', 'https://image.tmdb.org/t/p/w1280/yiWfT2Bl1Nul3Xie39Ahs3FqSjA.jpg', 'https://www.youtube.com/watch?v=hZxJzhIPTTg', 'David Slade', ARRAY['Kristen Stewart', 'Robert Pattinson', 'Taylor Lautner', 'Bryce Dallas Howard', 'Dakota Fanning', 'Billy Burke', 'Peter Facinelli', 'Elizabeth Reaser']::TEXT[], ARRAY['Phiêu Lưu', 'Giả Tưởng', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 124, '2010-06-23', NULL, 'US: PG-13', 6.2, 'ended'),
  ('2f29f499-72e4-5c08-a6cb-5ce8bb5b3574'::UUID, 137, 'Ngày Đầu Xuân', 'Groundhog Day', 'Groundhog Day (Ngày Đầu Xuân) là một bộ phim hài sản xuất năm 1993 được Harold Ramis đạo diễn, kịch bản của Danny Rubin và Harold Ramis. Khi mới ra mắt, Groundhog Day không phải là một tác phẩm được đánh giá cao, mà chỉ được nhìn nhận là một bộ phim hài giải trí không tồi. Tuy nhiên, càng về sau, khi được nghiên cứu và nghiền ngẫm, bộ phim đã chứng minh giá trị của mình. Với một cốt truyện thông minh và những triết lý đắt giá, Groundhog Day xứng đáng vị trí 65 trong danh sách 100 tác phẩm điện ảnh xuất sắc nhất mọi thời đại do Hollywood bình chọn. Hội Biên kịch phim nước Mỹ (WGA) bình chọn ra 101 kịch bản hài hước nhất lịch sử, trong đó Groundhog Day đứng thứ 3, ngay sau hai tác phẩm hài kinh điển Annie Hall (1977) và Some Like It Hot (1959). Và cho đến nay bộ phim vẫn nằm trong Top 250 phim hay nhất của IMDb.', 'A cynical TV weatherman, along with his idealistic producer and his sardonic cameraman, is sent to report on Groundhog Day in the small town of Punxsutawney, where he finds himself repeating the same day over and over.', 'https://image.tmdb.org/t/p/w780/gCgt1WARPZaXnq523ySQEUKinCs.jpg', 'https://image.tmdb.org/t/p/w1280/4W6RYDNe4OByNryOCvJprrutm9h.jpg', 'https://www.youtube.com/watch?v=_ADlbEQG_VA', 'Harold Ramis', ARRAY['Bill Murray', 'Andie MacDowell', 'Chris Elliott', 'Stephen Tobolowsky', 'Brian Doyle-Murray', 'Marita Geraghty', 'Angela Paton', 'Rick Ducommun']::TEXT[], ARRAY['Lãng Mạn', 'Giả Tưởng', 'Hài']::TEXT[], 101, '1993-02-11', NULL, 'US: PG', 7.6, 'ended'),
  ('9140f020-6f55-5a73-95f6-92e24686e327'::UUID, 114, 'Người Đàn Bà Đẹp', 'Pretty Woman', 'Trong bộ phim hài kịch lãng mạn này, nhà triệu phú Edward kí một hợp đồng kinh doanh với cô gái điếm Vivian ở Hollywood rồi đem lòng yêu cô lúc nào không hay.', 'Vivian is a carefree, streetwise diamond in the rough when she meets sophisticated billionaire Edward in a chance encounter that turns into a week-long business arrangement. But Vivian''s energetic spirit challenges Edward''s no-nonsense approach to life, and soon they are teaching each other – and falling in love!', 'https://image.tmdb.org/t/p/w780/oVKX1Pt1q7jXTkTk51mu2S0sAB0.jpg', 'https://image.tmdb.org/t/p/w1280/rleTwPqymtOpeD2bR7asJGEmldV.jpg', 'https://www.youtube.com/watch?v=2EBAVoN8L_U', 'Garry Marshall', ARRAY['Julia Roberts', 'Richard Gere', 'Ralph Bellamy', 'Jason Alexander', 'Laura San Giacomo', 'Héctor Elizondo', 'Alex Hyde-White', 'Amy Yasbeck']::TEXT[], ARRAY['Lãng Mạn', 'Hài']::TEXT[], 120, '1990-03-23', NULL, 'US: R', 7.4, 'ended'),
  ('7ac9636b-02d2-5011-9723-bc60ed18ea33'::UUID, 4951, '10 Điều Em Ghét Anh', '10 Things I Hate About You', 'Vừa chuyển tới trường mới, anh chàng Cameron đã phải lòng Bianca - cô nàng hot nhất trường. Tuy nhiên, Bianca chỉ được phép hẹn hò khi cô chị gái mọt sách khó tính Kat có người rủ đi chơi trước. Và Patrick - một tay "anh chị" đầu gấu trong trường đã được thuê nhằm mục đích "quyến rũ" Kat để Bianca có cơ hội được hẹn hò. Mọi chuyện trở nên phức tạp hơn khi cả Patrick lẫn Kat đều nảy sinh tình cảm với nhau.', 'On the first day at his new school, Cameron instantly falls for Bianca, the gorgeous girl of his dreams. The only problem is that Bianca is forbidden to date until her ill-tempered, completely un-dateable older sister Kat goes out, too. In an attempt to solve his problem, Cameron singles out the only guy who could possibly be a match for Kat: a mysterious bad boy with a nasty reputation of his own.', 'https://image.tmdb.org/t/p/w780/ujERk3aKABXU3NDXOAxEQYTHe9A.jpg', 'https://image.tmdb.org/t/p/w1280/yvPbncYhMu9FfTjDhq0N5lgnVkO.jpg', 'https://www.youtube.com/watch?v=GbWQ_VXek6A', 'Gil Junger', ARRAY['Heath Ledger', 'Julia Stiles', 'Joseph Gordon-Levitt', 'Larisa Oleynik', 'David Krumholtz', 'Andrew Keegan', 'Susan May Pratt', 'Gabrielle Union']::TEXT[], ARRAY['Hài', 'Lãng Mạn', 'Chính Kịch']::TEXT[], 97, '1999-03-30', NULL, 'US: PG-13', 7.6, 'ended'),
  ('5bca78cb-0c1c-5a47-8caa-04243ff9ed4f'::UUID, 4348, 'Kiêu Hãnh và Định Kiến', 'Pride & Prejudice', 'Elizabeth Bennet cứng đầu (Keira Knightley) và quý ngài Darcy kiêu hãnh (Matthew Macfadyen) xoay xở với cảm xúc của họ trong bản chuyển thể đầy mê hoặc từ tác phẩm của Jane Austen.', 'A story of love and life among the landed English gentry during the Georgian era. Mr. Bennet is a gentleman living in Hertfordshire with his overbearing wife and five daughters, but if he dies their house will be inherited by a distant cousin whom they have never met, so the family''s future happiness and security is dependent on the daughters making good marriages.', 'https://image.tmdb.org/t/p/w780/ixcFIzqXIWbSOnxDLKYI8MIoRY6.jpg', 'https://image.tmdb.org/t/p/w1280/1Onam6oWyFAUCcoxtdWkACtEiNr.jpg', 'https://www.youtube.com/watch?v=tbW-pmLT5UU', 'Joe Wright', ARRAY['Keira Knightley', 'Matthew Macfadyen', 'Brenda Blethyn', 'Rosamund Pike', 'Carey Mulligan', 'Jena Malone', 'Talulah Riley', 'Donald Sutherland']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn']::TEXT[], 128, '2005-09-16', NULL, 'US: PG', 8.1, 'ended'),
  ('7af425a8-ec10-55db-96c6-2bf752f344ce'::UUID, 22538, 'Scott Pilgrim Chống Lại Cả Thế Giới', 'Scott Pilgrim vs. the World', 'Bộ phim là câu chuyện về tay guitar bass 23 tuổi tên là Scott Pilmgrim của ban nhạc Sex Bob-omb. Scott vừa gặp được người con gái trong mộng của mình - Ramona Flowers. Quyết tâm có được trái tim của Ramona, Scott phát hiện ra anh phải chiến đấu với 7 “đối thủ” – vốn là người yêu cũ của cô bạn lạ lùng này. Những kẻ đó cũng đang nung nấu ý định giết Scott. Scott Pilgrim vs. the World được chuyển thể từ tập truyện tranh Scott Pilgrim của tác giả Bryan Lee O’ Malley. Với sự góp mặt của hai diễn viên tuổi teen Michael Cera và Mary Elizabeth Winstead chắc chắn sẽ không khỏi bất ngờ với cuộc chiến vì người đẹp của Scott.', 'As bass guitarist for a garage-rock band, Scott Pilgrim has never had trouble getting a girlfriend; usually, the problem is getting rid of them. But when Ramona Flowers skates into his heart, he finds she has the most troublesome baggage of all: an army of ex-boyfriends who will stop at nothing to eliminate him from her list of suitors.', 'https://image.tmdb.org/t/p/w780/jJqApNNmUjRB92nuhpi6OfDY5Ns.jpg', 'https://image.tmdb.org/t/p/w1280/6R9nT6m8wmzayV5XOQq3TRA6yZw.jpg', 'https://www.youtube.com/watch?v=j66qP9Larlg', 'Edgar Wright', ARRAY['Michael Cera', 'Mary Elizabeth Winstead', 'Ellen Wong', 'Kieran Culkin', 'Alison Pill', 'Mark Webber', 'Johnny Simmons', 'Jason Schwartzman']::TEXT[], ARRAY['Hành Động', 'Hài', 'Lãng Mạn']::TEXT[], 113, '2010-08-12', NULL, 'US: PG-13', 7.5, 'ended'),
  ('956e6edc-dcbe-5cf8-98e4-d8428ae20b63'::UUID, 2105, 'Đoàn Tụ Kiểu Mỹ', 'American Pie', 'Kẻ mê bánh giờ thành người đã có vợ con, Jim gặp lại hội bạn một thời chỉ nghĩ đến "chuyện ấy" tại buổi họp lớp cấp 3 đã lâu chưa tổ chức.', 'At a high-school party, four friends find that losing their collective virginity isn''t as easy as they had thought. But they still believe that they need to do so before college. To motivate themselves, they enter a pact to all "score" by their senior prom.', 'https://image.tmdb.org/t/p/w780/5P68by2Thn8wHAziyWGEw2O7hco.jpg', 'https://image.tmdb.org/t/p/w1280/cvH1gNIMRITdLzoWv1HNAbRyH3n.jpg', 'https://www.youtube.com/watch?v=YXd7ruWo9Gg', 'Paul Weitz', ARRAY['Jason Biggs', 'Chris Klein', 'Thomas Ian Nicholas', 'Alyson Hannigan', 'Shannon Elizabeth', 'Tara Reid', 'Eddie Kaye Thomas', 'Seann William Scott']::TEXT[], ARRAY['Hài', 'Lãng Mạn']::TEXT[], 95, '1999-07-09', NULL, 'US: R', 6.7, 'ended'),
  ('129a44bb-746b-5bec-91a4-e70af22f993a'::UUID, 466282, 'Những Chàng Trai Năm Ấy', 'To All the Boys I''ve Loved Before', 'Những lá thư tình bí mật của Lara Jean bỗng đến tay năm anh chàng cô thầm mến, cuộc sống trung học trầm lặng của cô cũng bị đảo lộn từ đây.', 'Lara Jean''s love life goes from imaginary to out of control when her secret letters to every boy she''s ever fallen for are mysteriously mailed out.', 'https://image.tmdb.org/t/p/w780/hKHZhUbIyUAjcSrqJThFGYIR6kI.jpg', 'https://image.tmdb.org/t/p/w1280/xXhta1NIKn09IXy0mfp68cabdWS.jpg', 'https://www.youtube.com/watch?v=555oiY9RWM4', 'Susan Johnson', ARRAY['Trần Đồng Lan', 'Noah Centineo', 'Israel Broussard', 'Janel Parrish', 'Anna Cathcart', 'Andrew Bachelor', 'Trezzo Mahoro', 'Emilija Baranac']::TEXT[], ARRAY['Hài', 'Lãng Mạn']::TEXT[], 100, '2018-08-17', NULL, 'US: PG-13', 7.6, 'ended'),
  ('b409d093-d0c1-5469-964f-63e6240ae05d'::UUID, 278, 'Nhà Tù Shawshank', 'The Shawshank Redemption', 'Nhà tù Shawshank kể về Andrew, một nhân viên nhà băng, bị kết án chung thân sau khi giết vợ và nhân tình của cô. Anh một mực cho rằng mình bị oan. Andy bị đưa tới nhà tù Shawshank. Tại đây, thế giới ngầm của các phạm nhân, sự hà khắc của hệ thống quản giáo xung đột và giành nhau quyền thống trị. Chỉ có các phạm nhân trung lập là bị kẹt ở giữa và có thể bỏ mạng. Làm quen với tay ‘quản lý chợ đen’ Redding, Andy dần thích nghi với cuộc sống tại Shawshank. Song, kế hoạch lớn hơn việc tồn tại ở nhà tù này đang được anh suy tính. Qua con mắt và lời kể của Redding, cuộc vượt ngục vĩ đại này được kể tuần tự cùng một kết thúc bất ngờ', 'Imprisoned in the 1940s for the double murder of his wife and her lover, upstanding banker Andy Dufresne begins a new life at the Shawshank prison, where he puts his accounting skills to work for an amoral warden. During his long stretch in prison, Dufresne comes to be admired by the other inmates -- including an older prisoner named Red -- for his integrity and unquenchable sense of hope.', 'https://image.tmdb.org/t/p/w780/zLyG4nquaaZKCA3CJdQCEzTwN1R.jpg', 'https://image.tmdb.org/t/p/w1280/pNjh59JSxChQktamG3LMp9ZoQzp.jpg', 'https://www.youtube.com/watch?v=PLl99DlL6b4', 'Frank Darabont', ARRAY['Tim Robbins', 'Morgan Freeman', 'Bob Gunton', 'William Sadler', 'Clancy Brown', 'Gil Bellows', 'James Whitmore', 'Mark Rolston']::TEXT[], ARRAY['Chính Kịch', 'Tội Phạm']::TEXT[], 142, '1994-09-23', NULL, 'US: R', 8.7, 'ended'),
  ('868a1ed8-9048-56b6-8059-e25dd68b7c7e'::UUID, 238, 'Bố Già', 'The Godfather', 'Một câu chuyện kéo dài từ năm 1945 đến năm 1955, một biên niên sử về gia đình tội phạm Corleone người Mỹ gốc Ý. Khi tộc trưởng gia đình tội phạm có tổ chức, Vito Corleone bị ám sát bởi băng nhóm đối thủ, con trai út của ông, Michael đã phải nhúng tay vào tội ác và chống lại đối thủ với việc phát động một chiến dịch trả thù đẫm máu.', 'Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family. When organized crime family patriarch, Vito Corleone barely survives an attempt on his life, his youngest son, Michael steps in to take care of the would-be killers, launching a campaign of bloody revenge.', 'https://image.tmdb.org/t/p/w780/84MHN3JvOV4ORHgELrQM6SBlhdB.jpg', 'https://image.tmdb.org/t/p/w1280/ejdD20cdHNFAYAN2DlqPToXKyzx.jpg', 'https://www.youtube.com/watch?v=Ew9ngL1GZvs', 'Francis Ford Coppola', ARRAY['Marlon Brando', 'Al Pacino', 'James Caan', 'Robert Duvall', 'Richard S. Castellano', 'Diane Keaton', 'Talia Shire', 'Gianni Russo']::TEXT[], ARRAY['Chính Kịch', 'Tội Phạm']::TEXT[], 175, '1972-03-14', NULL, 'US: R', 8.7, 'ended'),
  ('9f7d6396-18da-5d14-a68a-e5f752c6635b'::UUID, 389, '12 Người Đàn Ông Giận Dữ', '12 Angry Men', 'Một thanh niên bị tình nghi giết cha ruột của mình. 12 người của bồi thẩm đoàn bắt đầu phiên làm việc của mình và tất cả hội thẩm viên đều muốn kết thúc nhanh chóng vụ án vì các chứng cứ đã quá rõ ràng. Trừ một người duy nhất. Ông không muốn sinh mạng của một con người lại có thể được quyết định chỉ trong vòng chưa đầy 10 phút.  Ông có một sự nghi ngờ riêng đối với vụ án kỳ lạ này. Và ông quyết định: tìm cách thuyết phục mọi người. Nhưng ông sẽ làm gì để giúp cậu bé kia và thuyết phục những người trong bồi thẩm đoàn đây?', 'The defense and the prosecution have rested and the jury is filing into the jury room to decide if a young Spanish-American is guilty or innocent of murdering his father. What begins as an open and shut case soon becomes a mini-drama of each of the jurors'' prejudices and preconceptions about the trial, the accused, and each other.', 'https://image.tmdb.org/t/p/w780/aa4s7J0ld2UHUooc1H8o1sNuZ2m.jpg', 'https://image.tmdb.org/t/p/w1280/qqHQsStV6exghCM7zbObuYBiYxw.jpg', 'https://www.youtube.com/watch?v=TEN-2uTi2c0', 'Sidney Lumet', ARRAY['Martin Balsam', 'John Fiedler', 'Lee J. Cobb', 'E.G. Marshall', 'Jack Klugman', 'Edward Binns', 'Jack Warden', 'Henry Fonda']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 97, '1957-04-10', NULL, 'US: NR', 8.6, 'ended'),
  ('04a74f36-80ae-5054-a98b-0e35c5722120'::UUID, 240, 'Bố Già 2', 'The Godfather Part II', 'The Godfather II là phần tiếp theo của tác phẩm nổi tiếng Bố già sản xuất năm 1972. Trong phần thứ hai này sẽ có hai câu chuyện, hai tuyến nhân vật, hai tuyến thời gian song hành nhau. Một là câu chuyện về gia đình mafia Corleone tiếp tục khi Michael lên làm ông trùm và âm mưu mở rộng địa bàn sang Las Vegas lẫn Cuba, xen lẫn với những hồi ức về Bố già khi mới đặt chân đến New York... Bố già phần II được đánh giá là phần tiếp theo thành công nhất trong lịch sử điện ảnh, nhiều người cho rằng bộ phim hay tương đương, thậm chí là hay hơn phần đầu. Cùng với phần đầu tiên, Bố già II được coi là một trong những bộ phim hay nhất mọi thời đại.', 'In the continuing saga of the Corleone crime family, a young Vito Corleone grows up in Sicily and in 1910s New York. In the 1950s, Michael Corleone attempts to expand the family business into Las Vegas, Hollywood and Cuba.', 'https://image.tmdb.org/t/p/w780/flUbm9ZaZ7itOwCzHtx6lnhLMQ4.jpg', 'https://image.tmdb.org/t/p/w1280/pGzqRKrYeK4LogoysNro0vG8d8N.jpg', 'https://www.youtube.com/watch?v=9O1Iy9od7-A', 'Francis Ford Coppola', ARRAY['Al Pacino', 'Robert Duvall', 'Diane Keaton', 'Robert De Niro', 'John Cazale', 'Talia Shire', 'Lee Strasberg', 'Michael V. Gazzo']::TEXT[], ARRAY['Chính Kịch', 'Tội Phạm']::TEXT[], 202, '1974-12-20', NULL, 'US: R', 8.6, 'ended'),
  ('9bff33bc-b684-5606-8c69-1f9f8a468654'::UUID, 424, 'Bản Danh Sách Của Schindler', 'Schindler''s List', 'Bản danh sách của Schindler (Schindler`s List) là một bộ phim truyện sản xuất năm 1993 của Hoa Kỳ về Oskar Schindler, một nhà kinh doanh người Đức. Phim bắt đầu vào năm 1939 với sự tập trung người Ba Lan gốc Do Thái của chính quyền Đức Quốc Xã sau khi xâm lược Ba Lan, từ việc bao vây, giam lỏng trong vùng tới xây dựng những khu tập trung Kraków Ghetto không lâu sau khi Đệ nhị thế chiến bắt đầu. Trong lúc đó, Oskar Schindler (Liam Neeson), một doanh nhân thất bại, đến thành phố từ Sudetenland với những hy vọng làm giàu.', 'The true story of how businessman Oskar Schindler saved over a thousand Jewish lives from the Nazis while they worked as slaves in his factory during World War II.', 'https://image.tmdb.org/t/p/w780/sF1U4EUQS8YHUYjNl3pMGNIQyr0.jpg', 'https://image.tmdb.org/t/p/w1280/zb6fM1CX41D9rF9hdgclu0peUmy.jpg', 'https://www.youtube.com/watch?v=v0RB-3sWbBA', 'Steven Spielberg', ARRAY['Liam Neeson', 'Ben Kingsley', 'Ralph Fiennes', 'Caroline Goodall', 'יהונתן סגל', 'Embeth Davidtz', 'Malgorzata Gebel', 'שמוליק לוי']::TEXT[], ARRAY['Chính Kịch', 'Lịch Sử', 'Chiến Tranh']::TEXT[], 195, '1993-12-15', NULL, 'US: R', 8.6, 'ended'),
  ('f4a24deb-179f-58fe-9d71-53649fcc57ea'::UUID, 497, 'Dặm Xanh', 'The Green Mile', 'Bộ phim là câu chuyện hồi tưởng của một viên coi ngục cai quản những tên tử tù bất trị đang chờ ngày ngồi lên ghế điện trả giá cho những tội ác mà chúng gây ra. Cuộc sống của ông thay đổi hoàn toàn kể từ khi một người tù da đen có khả năng kì lạ xuất hiện trong ngục của ông...', 'A supernatural tale set on death row in a Southern prison, where gentle giant John Coffey possesses the mysterious power to heal people''s ailments. When the cell block''s head guard, Paul Edgecomb, recognizes Coffey''s miraculous gift, he tries desperately to help stave off the condemned man''s execution.', 'https://image.tmdb.org/t/p/w780/pTEuy2oti9ITTzzrTRZNeSAXzfC.jpg', 'https://image.tmdb.org/t/p/w1280/amZavErrjrdgDwhsIdpWxHNenIx.jpg', 'https://www.youtube.com/watch?v=Bg7epsq0OIQ', 'Frank Darabont', ARRAY['Tom Hanks', 'David Morse', 'Bonnie Hunt', 'Michael Clarke Duncan', 'James Cromwell', 'Michael Jeter', 'Graham Greene', 'Doug Hutchison']::TEXT[], ARRAY['Giả Tưởng', 'Chính Kịch', 'Tội Phạm']::TEXT[], 189, '1999-12-10', NULL, 'US: R', 8.5, 'ended'),
  ('94d38438-c866-5d35-98e2-08d2963b1c51'::UUID, 19404, 'Dilwale sẽ đón chàng rể', 'दिलवाले दुल्हनिया ले जायेंगे', 'Raj là một NRI thế hệ thứ hai giàu có, vô tư, luôn vui vẻ và may mắn. Simran là con gái của Chaudhary Baldev Singh, người mặc dù là một NRI nhưng rất nghiêm khắc trong việc tuân thủ các giá trị của Ấn Độ. Simran đã rời đến Ấn Độ để kết hôn với vị hôn phu thời thơ ấu của cô. Raj lên đường đến Ấn Độ với một nhiệm vụ trong tay, đòi hỏi tình yêu của người phụ nữ của mình dưới sự săn đón của cả gia đình cô ấy. Như vậy bắt đầu một câu chuyện.', 'Raj is a rich, carefree, happy-go-lucky second generation NRI. Simran is the daughter of Chaudhary Baldev Singh, who in spite of being an NRI is very strict about adherence to Indian values. Simran has left for India to be married to her childhood fiancé. Raj leaves for India with a mission at his hands, to claim his lady love under the noses of her whole family. Thus begins a saga.', 'https://image.tmdb.org/t/p/w780/2CAL2433ZeIihfX1Hb2139CX0pW.jpg', 'https://image.tmdb.org/t/p/w1280/7VDLEHli74eLsYLNcq9djn1Gw76.jpg', 'https://www.youtube.com/watch?v=oIZ4U21DRlM', 'Aditya Chopra', ARRAY['काजोल', 'शाहरुख़ ख़ान', 'Amrish Puri', 'Farida Jalal', 'अनुपम खेर', 'Pooja Ruparel', 'Parmeet Sethi', 'Satish Shah']::TEXT[], ARRAY['Hài', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 190, '1995-10-20', NULL, 'US: PG', 8.5, 'ended'),
  ('368dad9d-ffef-5f02-89ec-581a949700a7'::UUID, 680, 'Chuyện Tào Lao', 'Pulp Fiction', 'Những câu chuyện tưởng chừng tầm phào về 2 gã găng tơ trên đường thực hiện mệnh lệnh của ông chủ với 1 võ sĩ quyền anh giết chết người phải chạy trốn có vẻ không liên quan nhưng khi ghép lại người xem sẽ có 1 bức tranh tổng thể, đặc trưng cho phong cách của đạo diễn Quentin Tarantino: đậm chất bạo lực, máu me.', 'A burger-loving hit man, his philosophical partner, a drug-addled gangster''s moll and a washed-up boxer converge in this sprawling, comedic crime caper. Their adventures unfurl in three stories that ingeniously trip back and forth in time.', 'https://image.tmdb.org/t/p/w780/ihynkOAH6FLNgG1kqM5ep9GSHZS.jpg', 'https://image.tmdb.org/t/p/w1280/suaEOtk1N1sgg2MTM7oZd2cfVp3.jpg', 'https://www.youtube.com/watch?v=tGpTpVyI_OQ', 'Quentin Tarantino', ARRAY['John Travolta', 'Samuel L. Jackson', 'Uma Thurman', 'Bruce Willis', 'Ving Rhames', 'Harvey Keitel', 'Eric Stoltz', 'Tim Roth']::TEXT[], ARRAY['Giật Gân', 'Tội Phạm', 'Hài']::TEXT[], 154, '1994-09-10', NULL, 'US: R', 8.5, 'ended'),
  ('94f26b35-8548-5f54-8ec5-d90e05f4323e'::UUID, 429, 'Thiện, Ác, Tà', 'Il buono, il brutto, il cattivo', 'Thiện, Ác, Tà (The Good, The Bad And The Ugly): Blondie là tay cao bồi chuyên săn tiền thưởng ở miền Tây. Tuco là tên tội phạm đang lẩn trốn sự truy đuổi. Cả hai hợp tác kiếm tiền từ lệnh truy nã của Tuco. Cả hai phát hiện ra một kho vàng khi chạm trán đoàn xe bị cướp và lấy được thông tin từ kẻ sống sót cuối cùng. Tuco đã kịp nghe được tên của nghĩa địa chôn vàng, còn Blondie nhớ được tên ngôi mộ... Giờ đây, cả hai phải giữ mạng sống cho kẻ còn lại nếu muốn tìm được kho vàng. Cũng trong lúc đó, tên sát thủ Angel Eye đang trên đường tới nơi chôn giấu...', 'While the Civil War rages on between the Union and the Confederacy, three men – a quiet loner, a ruthless hitman, and a Mexican bandit – comb the American Southwest in search of a strongbox containing $200,000 in stolen gold.', 'https://image.tmdb.org/t/p/w780/hTPEtEMiYFJ4lHXsay57tZX673Q.jpg', 'https://image.tmdb.org/t/p/w1280/x4biAVdPVCghBlsVIzB6NmbghIz.jpg', 'https://www.youtube.com/watch?v=WCnRSl24FPA', 'Sergio Leone', ARRAY['Clint Eastwood', 'Eli Wallach', 'Lee Van Cleef', 'Aldo Giuffrè', 'Luigi Pistilli', 'Rada Rassimov', 'Enzo Petito', 'Claudio Scarchilli']::TEXT[], ARRAY['Miền Tây']::TEXT[], 161, '1966-12-23', NULL, 'US: R', 8.5, 'ended'),
  ('2e46f66d-184b-57f6-879f-a90e1459cbbc'::UUID, 769, 'Chiến Hữu', 'GoodFellas', 'Câu chuyện có thật về Henry Hill, một cậu bé Brooklyn mang nửa dòng máu Ailen, nửa Sicily, được các băng nhóm xã hội đen hàng xóm nhận nuôi khi còn nhỏ và leo lên hàng ngũ của một gia đình Mafia dưới sự hướng dẫn của Jimmy Conway.', 'The true story of Henry Hill, a half-Irish, half-Sicilian Brooklyn kid who is adopted by neighbourhood gangsters at an early age and climbs the ranks of a Mafia family under the guidance of Jimmy Conway.', 'https://image.tmdb.org/t/p/w780/56yHDzoWZUFLUD2ztsVzSNcHo6f.jpg', 'https://image.tmdb.org/t/p/w1280/gILte6Zd7m1YneIr6MVhh30S9pr.jpg', 'https://www.youtube.com/watch?v=PTBRNXGQR9Q', 'Martin Scorsese', ARRAY['Robert De Niro', 'Ray Liotta', 'Joe Pesci', 'Lorraine Bracco', 'Paul Sorvino', 'Frank Sivero', 'Tony Darrow', 'Mike Starr']::TEXT[], ARRAY['Chính Kịch', 'Tội Phạm']::TEXT[], 145, '1990-09-12', NULL, 'US: R', 8.5, 'ended'),
  ('9ef68b83-3c18-5c56-9984-556721b1a6db'::UUID, 550, 'Sàn Đấu Sinh Tử', 'Fight Club', 'Cuộc gặp gỡ định mệnh của một nhân viên giám định bảo hiểm và một gã lông bông bán xà phòng trên chuyến bay đã mở ra một cuộc phiêu lưu kỳ lạ. Với các "câu lạc bộ chiến đấu" ngầm hình thành ở mọi thị trấn, cuốn theo nhiều diễn biến phức tạp và một cái kết đầy kịch tính.', 'A ticking-time-bomb insomniac and a slippery soap salesman channel primal male aggression into a shocking new form of therapy. Their concept catches on, with underground "fight clubs" forming in every town, until an eccentric gets in the way and ignites an out-of-control spiral toward oblivion.', 'https://image.tmdb.org/t/p/w780/wBxkCbNI8eDRRfUEl8w0G2rfLyu.jpg', 'https://image.tmdb.org/t/p/w1280/c6OLXfKAk5BKeR6broC8pYiCquX.jpg', 'https://www.youtube.com/watch?v=dfeUzm6KF4g', 'David Fincher', ARRAY['Edward Norton', 'Brad Pitt', 'Helena Bonham Carter', 'Meat Loaf', 'Jared Leto', 'Zach Grenier', 'Holt McCallany', 'Eion Bailey']::TEXT[], ARRAY['Chính Kịch', 'Giật Gân']::TEXT[], 139, '1999-10-15', NULL, 'US: R', 8.4, 'ended'),
  ('dc0a8b4f-7974-5c4e-9138-41ad294c7780'::UUID, 637, 'Cuộc Sống Tươi Đẹp', 'La vita è bella', 'Một câu chuyện cổ tích giữa đời thường đầy cảm động về chàng bán sách người Ý gốc Do Thái. Cuộc sống gia đình hạnh phúc của anh bị đảo lộn hoàn toàn do bị trục xuất vào trại tập trung của Đức Quốc Xã. Tuy bị nhốt, nhưng anh đã thuyết phục con trai mình là toàn bộ những gì xảy ra đang là một trò chơi.', 'A touching story of an Italian book seller of Jewish ancestry who lives in his own little fairy tale. His creative and happy life would come to an abrupt halt when his entire family is deported to a concentration camp during World War II. While locked up he tries to convince his son that the whole thing is just a game.', 'https://image.tmdb.org/t/p/w780/uo7voMPpJ4cGvAgUxi0DumaqjBA.jpg', 'https://image.tmdb.org/t/p/w1280/6aNKD81RHR1DqUUa8kOZ1TBY1Lp.jpg', 'https://www.youtube.com/watch?v=pAYEQP8gx3w', 'Roberto Benigni', ARRAY['Roberto Benigni', 'Nicoletta Braschi', 'Giorgio Cantarini', 'Giustino Durano', 'Sergio Bini Bustric', 'Marisa Paredes', 'Horst Buchholz', 'Lidia Alfonsi']::TEXT[], ARRAY['Hài', 'Chính Kịch']::TEXT[], 116, '1997-12-20', NULL, 'US: PG-13', 8.4, 'ended'),
  ('01d07245-026c-56fd-a467-1b93519b286f'::UUID, 11216, 'Rạp Chiếu Bóng Thiên Đường', 'Nuovo Cinema Paradiso', 'Đã mang tiếng là dân mê phim mà chưa xem qua Cinema Paradiso thì quả là một thiếu sót cực lớn! Vì sao ư? Vì đây chính là bộ phim tôn vinh điện ảnh và những fan cuồng của điện ảnh.Với 1 giải Oscar và 1 Golden Globe dành cho phim nói tiếng nước ngoài hay nhất, 1 giải thưởng lớn của BGK tại liên hoan phim Cannes cùng vô số các giải thưởng khác, Cinema Paradiso xứng đáng là một tượng đài trong lòng những người yêu phim. Hãy xem phim để cùng cười, cùng khóc với câu chuyện và những nhân vật. Hãy xem phim để thấy tự hào mình là một người yêu điện ảnh và thêm yêu điện ảnh.Chắc chắn bộ phim sẽ mang lại cho bạn những giây phút cực kỳ vui vẻ nhưng cũng không thiếu đi những khoảng lặng mà cho tới tận lúc ra về bạn vẫn còn cảm thấy xúc ...', 'A filmmaker recalls his childhood, when he fell in love with the movies at his village''s theater and formed a deep friendship with the theater''s projectionist.', 'https://image.tmdb.org/t/p/w780/3hcXpztAe9L6VLpDGwohS01ZSxw.jpg', 'https://image.tmdb.org/t/p/w1280/zoVeIgKzGJzpdG6Gwnr7iOYfIMU.jpg', 'https://www.youtube.com/watch?v=JMyVSD6OvO8', 'Giuseppe Tornatore', ARRAY['Philippe Noiret', 'Jacques Perrin', 'Marco Leonardi', 'Salvatore Cascio', 'Agnese Nano', 'Antonella Attili', 'Pupella Maggio', 'Brigitte Fossey']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn']::TEXT[], 124, '1988-11-17', NULL, 'US: PG', 8.4, 'ended'),
  ('668d0f48-a952-59b3-aa43-d534fc0f9613'::UUID, 598, 'Thành Phố Của Chúa', 'Cidade de Deus', 'City of God - một khu ổ chuột ở thành phố Rio de Janero - có cái tên như vậy với mong muốn điều tốt đẹp hơn đến với người trong vùng. Vậy mà, thực tế thật khắc nghiệt và tàn nhẫn. Trẻ em tiếp xúc súng đạn nhiều hơn là sách vở. Thanh niên thì trộm cắp, cướp bóc. Thế nhưng người dân chẳng ghét những kẻ trộm cắp lặt vặt, thậm chí còn bao che cho họ bởi người họ căm ghét hơn cả là cảnh sát địa phương. Những tên chuyên quyền này thản nhiên móc nối với bọn cầm đầu xã hội đen, ra sức bắn giết bất kì ai chúng cho là nghi phạm. Đến cảnh sát, người thay mặt cho chính quyền, lại làm ngơ trước tội phạm như vậy thì còn biết trông chờ vào ai? Cái vòng tội lỗi, đói nghèo cứ bám lấy thành phố này.', 'In the poverty-stricken favelas of Rio de Janeiro in the 1970s, two young men choose different paths. Rocket is a budding photographer who documents the increasing drug-related violence of his neighborhood, while José “Zé” Pequeno is an ambitious drug dealer diving into a dangerous life of crime.', 'https://image.tmdb.org/t/p/w780/gfnXixcGC060QcG6JPxN6AMdVsq.jpg', 'https://image.tmdb.org/t/p/w1280/uvitbjFU4JqvMwIkMWHp69bmUzG.jpg', 'https://www.youtube.com/watch?v=dcUOO4Itgmw', 'Fernando Meirelles', ARRAY['Alexandre Rodrigues', 'Leandro Firmino', 'Phellipe Haagensen', 'Douglas Silva', 'Jonathan Haagensen', 'Matheus Nachtergaele', 'Seu Jorge', 'Jefechander Suplino']::TEXT[], ARRAY['Chính Kịch', 'Tội Phạm']::TEXT[], 129, '2002-08-30', NULL, 'US: R', 8.4, 'ended'),
  ('9aa6d21d-3867-56cb-830a-2a66b2aec3c5'::UUID, 510, 'Bay Trên Tổ Chim Cúc Cu', 'One Flew Over the Cuckoo''s Nest', 'Trong thời gian bị nhốt ở một bệnh viện tâm thần của bang, Randle Patrick McMurphy, một kẻ cuồng dâm bất trị, đã truyền cảm hứng cho các bệnh nhân của mình nổi dậy chống lại sự cai trị độc đoán của y tá trưởng Mildred Rished.', 'A petty criminal fakes insanity to serve his sentence in a mental ward rather than prison. He soon finds himself as a leader to the other patients—and an enemy to the cruel, domineering nurse who runs the ward.', 'https://image.tmdb.org/t/p/w780/kjWsMh72V6d8KRLV4EOoSJLT1H7.jpg', 'https://image.tmdb.org/t/p/w1280/uA8eSNAUUUyfHNIrG4h0zHxzt9W.jpg', 'https://www.youtube.com/watch?v=F4da9uRIg8c', 'Miloš Forman', ARRAY['Jack Nicholson', 'Brad Dourif', 'Louise Fletcher', 'Danny DeVito', 'William Redfield', 'Scatman Crothers', 'Christopher Lloyd', 'Will Sampson']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 135, '1975-11-19', NULL, 'US: R', 8.4, 'ended'),
  ('56eef3ff-94f8-5e8e-9b6b-7364ddd6bde4'::UUID, 807, 'Thất Đại Tội', 'Se7en', 'Hai viên cảnh sát William Somerset và David Mills phối hợp điều tra một vụ án phức tạp liên quan đến 7 điều cấm trong Kinh thánh. Hung thủ được dự đoán là do trước kia hắn lớn lên trong môi trường đạo nghiêm khắc nên tâm lí bất ổn và rồi lần lượt giết người dựa trên 7 tội lỗi trong Kinh thánh mà hắn gán cho mỗi người.  7 tội lỗi đó là: kiêu hãnh (Pride), ghen tị (Envy), ham ăn (Gluttony), sắc dục (Lust), tức giận (Wrath), tham lam (Greed) và lười biếng (Sloth). Án mạng đầu tiên là một tên béo phì với dòng chữ Gluttony viết bằng máu trên tường. Greed là án mạng xảy ra sau đó ở nơi làm của 1 tên luật sư. Một tên buôn ma túy tên Victor bị giết với tội lười biếng - Sloth. Lust là tội gán cho một cô gái điếm. Cuối cùng, Pride là 1 cô nàng quá mải mê chăm chút bề ngoài của mình.', 'Two homicide detectives are on a desperate hunt for a serial killer whose crimes are based on the "seven deadly sins" in this dark and haunting film that takes viewers from the tortured remains of one victim to the next. The seasoned Det. Somerset researches each sin in an effort to get inside the killer''s mind, while his novice partner, Mills, scoffs at his efforts to unravel the case.', 'https://image.tmdb.org/t/p/w780/vor5v1DDqPVwOQCVKciPqrXmV3S.jpg', 'https://image.tmdb.org/t/p/w1280/i5H7zusQGsysGQ8i6P361Vnr0n2.jpg', 'https://www.youtube.com/watch?v=KPOuJGkpblk', 'David Fincher', ARRAY['Morgan Freeman', 'Brad Pitt', 'Gwyneth Paltrow', 'John Cassini', 'Peter Crombie', 'Reg E. Cathey', 'R. Lee Ermey', 'Daniel Zacapa']::TEXT[], ARRAY['Tội Phạm', 'Bí Ẩn', 'Giật Gân']::TEXT[], 127, '1995-09-22', NULL, 'US: R', 8.4, 'ended'),
  ('812c4035-db53-560c-ad0c-171e8fda74bf'::UUID, 423, 'Nghệ Sĩ Dương Cầm', 'The Pianist', 'Câu chuyện có thật về những trải nghiệm của nghệ sĩ dương cầm Władysław Szpilman ở Warsaw trong thời kỳ Đức Quốc xã chiếm đóng. Khi những người Do Thái của thành phố bị buộc vào một khu ổ chuột, Szpilman tìm việc chơi đàn trong một quán cà phê; và khi gia đình ông bị trục xuất vào năm 1942, ông trốn lại và sinh tồn trong đống đổ nát của thành phố bị chiến tranh tàn phá.', 'The true story of pianist Władysław Szpilman''s experiences in Warsaw during the Nazi occupation. When the Jews of the city find themselves forced into a ghetto, Szpilman finds work playing in a café; and when his family is deported in 1942, he stays behind, works for a while as a laborer, and eventually goes into hiding in the ruins of the war-torn city.', 'https://image.tmdb.org/t/p/w780/2hFvxCCWrTmCYwfy7yum0GKRi3Y.jpg', 'https://image.tmdb.org/t/p/w1280/c0fB9xk7D1aVb3Bg2rk2SVJcGn.jpg', 'https://www.youtube.com/watch?v=og9hFxxdSOg', 'Roman Polanski', ARRAY['Adrien Brody', 'Thomas Kretschmann', 'Frank Finlay', 'Maureen Lipman', 'Emilia Fox', 'Ed Stoppard', 'Julia Rayner', 'Jessica Kate Meyer']::TEXT[], ARRAY['Chính Kịch', 'Chiến Tranh']::TEXT[], 150, '2002-09-17', NULL, 'US: R', 8.4, 'ended'),
  ('937867a7-bb44-51fb-b454-d3bac47a3720'::UUID, 311, 'Nước Mỹ Một Thời', 'Once Upon a Time in America', 'Bộ phim Nước Mỹ một thời với chủ đề hết sức đa dạng từ tình bạn, tình yêu, tình dục, lòng tham, sự phản bội, sự mất mát. Phim chia thành 3 giai đoạn trong lịch sử nước Mỹ: những năm đầu thập niên 20, khoảng năm 1933 và năm 1968. Nhân vật chính trong phim là Noodles một đứa trẻ đường phố ở New York chuyên đi móc túi, cướp giật. Noodles thầm yêu Deborah và thường nhìn trộm Deborah tập múa, Deborah vừa yêu vừa sợ Noodles nên chuyện tình khá thú vị. Tuy nhiên sau lệnh cấm rượu của nước Mỹ, băng nhóm của Noodles đã tham gia kinh doanh bất hợp pháp món hàng này và đụng độ với một băng nhóm khác dẫn đến cái chết của 1 thành viên. Bộ phim với nhiều cảnh bạo lực nhưng phản ánh vô cùng chân thực nước Mỹ thời kỳ này.', 'A former Prohibition-era Jewish gangster returns to the Lower East Side of Manhattan over thirty years later, where he once again must confront the ghosts and regrets of his old life.', 'https://image.tmdb.org/t/p/w780/i0enkzsL5dPeneWnjl1fCWm6L7k.jpg', 'https://image.tmdb.org/t/p/w1280/xlDUjb0Q5Dv6jPQRF5VE4IMjIy.jpg', 'https://www.youtube.com/watch?v=5vrbUpDihxs', 'Sergio Leone', ARRAY['Robert De Niro', 'James Woods', 'Elizabeth McGovern', 'Joe Pesci', 'Burt Young', 'Tuesday Weld', 'Treat Williams', 'Danny Aiello']::TEXT[], ARRAY['Chính Kịch', 'Tội Phạm']::TEXT[], 139, '1984-05-23', NULL, 'US: R', 8.4, 'ended'),
  ('44eec863-cc02-575e-b838-766982a4a953'::UUID, 274, 'Sự Im Lặng Của Bầy Cừu', 'The Silence of the Lambs', 'Một cô gái trẻ mất tích và vụ án này có liên quan đến một kẻ giết người hàng loạt, để thỏa mãn cho những ý nghĩ bệnh hoạn của gã. Người duy nhất có thể làm vụ án sáng tỏ là tên tù nhân tâm thần, chuyên ăn thịt người Hannibal Lecter ( Anthony Hopkins ). Cô nhân viên trẻ Clarice được giao nhiệm vụ khai thác thông tin ở Hannibal. Từ đó, cô dần khám phá ra bí mật của những tiếng kêu kì lạ từ đàn cừu mà mình hằng ám ảnh…Một bộ phim đầy tính nhân bản được thể hiện qua những đoạn đốI thoại của Clarice và Hannibal và ở cái kết khiến người xem phải suy nghĩ rất nhiều…Bộ phim đã đoạt cùng lúc 5 giải Oscar quan trọng: giải phim hay nhất, đạo diễn, biên kịch, nam nữ diễn viên chính xuất sắc nhất. Đây là một thành tích ...', 'Clarice Starling is a top student at the FBI''s training academy.  Jack Crawford wants Clarice to interview Dr. Hannibal Lecter, a brilliant psychiatrist who is also a violent psychopath, serving life behind bars for various acts of murder and cannibalism.  Crawford believes that Lecter may have insight into a case and that Starling, as an attractive young woman, may be just the bait to draw him out.', 'https://image.tmdb.org/t/p/w780/2dfScR0ZhDOVRV2Qco758YgLzXG.jpg', 'https://image.tmdb.org/t/p/w1280/mbOx1wxMLikzwWUO9TKAcFIy6op.jpg', 'https://www.youtube.com/watch?v=6iB21hsprAQ', 'Jonathan Demme', ARRAY['Jodie Foster', 'Anthony Hopkins', 'Scott Glenn', 'Ted Levine', 'Anthony Heald', 'Brooke Smith', 'Diane Baker', 'Kasi Lemmons']::TEXT[], ARRAY['Tội Phạm', 'Giật Gân', 'Chính Kịch']::TEXT[], 119, '1991-02-14', NULL, 'US: R', 8.3, 'ended'),
  ('b1716906-c643-510f-9789-f2d3dee87859'::UUID, 567, 'Vụ Án Mạng Nhà Bên', 'Rear Window', 'Phim xoay quanh cuộc sống của anh chàng L.B. "Jeff" Jefferies sau khi bị một chiếc xe hơi tông phải cân buộc phải ở nằm bất động trong căn hộ ở tầng ba tòa nhà chung cư Greenwich Village. Cảm thấy vô cùng khó chịu vì phải chịu đựng cuộc sống bất động, chàng phóng viên độc thân giết thời gian bằng cách phóng tầm mắt xuống chiếc sân nhỏ của tòa nhà qua chiếc cửa sổ phía sau của căn hộ. Anh cũng theo dõi cuộc sống hàng ngày của tất cả những người hàng xóm, xem họ ăn, ngủ, dọn dẹp phòng và cãi cọ. Một vũ nữ mặc quần áo lót tập nhảy. Một cặp vợ chồng ngủ ngoài ban công để tránh cái nóng. Một nhạc sĩ nghèo chăm chỉ sáng tác bên cây đàn piano cũ kỹ. Một doanh nhân cũng sống ở tầng ba trong tòa nhà đối diện và thường cãi cọ với người vợ ốm yếu. Và 1 ngày anh chứng kiến một chuyện kinh hãi...', 'A wheelchair-bound photographer spies on his neighbors from his apartment window and becomes convinced one of them has committed murder.', 'https://image.tmdb.org/t/p/w780/ILVF0eJxHMddjxeQhswFtpMtqx.jpg', 'https://image.tmdb.org/t/p/w1280/5bN06p5OwRUEqcfrtNs5egV16yb.jpg', 'https://www.youtube.com/watch?v=iZOTTxwzyMU', 'Alfred Hitchcock', ARRAY['James Stewart', 'Grace Kelly', 'Wendell Corey', 'Thelma Ritter', 'Raymond Burr', 'Judith Evelyn', 'Ross Bagdasarian', 'Georgine Darcy']::TEXT[], ARRAY['Giật Gân', 'Bí Ẩn', 'Chính Kịch']::TEXT[], 113, '1954-08-01', NULL, 'US: PG', 8.3, 'ended'),
  ('f05849d4-b5fd-5790-a19a-a573b9fe0178'::UUID, 73, 'Khoảng Tối Lịch Sử Mỹ', 'American History X', 'Derek (Edward Norton) là một thanh niên California trở thành lãnh đạo của một băng nhóm neo-Nazi sau khi cha anh bị sát hại. Em trai nhỏ của anh, Danny, ngưỡng mộ anh và đi theo con đường của sự căm ghét và bạo lực. Khi Derek giết hai tên trộm da đen, anh bị kết án ba năm tù, nơi anh thay đổi cách nghĩ của mình khi gặp những tù nhân khác. Khi ra tù, anh cố gắng kéo Danny ra khỏi chủ nghĩa phân biệt chủng tộc và tội phạm, nhưng anh gặp phải sự kháng cự của những người bạn cũ và hậu quả của quá khứ của mình.', 'Derek Vineyard is paroled after serving 3 years in prison for killing two African-American men. Through his brother, Danny Vineyard''s narration, we learn that before going to prison, Derek was a skinhead and the leader of a violent white supremacist gang that committed acts of racial crime throughout L.A. and his actions greatly influenced Danny. Reformed and fresh out of prison, Derek severs contact with the gang and becomes determined to keep Danny from going down the same violent path as he did.', 'https://image.tmdb.org/t/p/w780/x2drgoXYZ8484lqyDj7L1CEVR4T.jpg', 'https://image.tmdb.org/t/p/w1280/6qHI1IYj7QlLSCwHRzkL62X175s.jpg', 'https://www.youtube.com/watch?v=el6JxnW2Tyg', 'Tony Kaye', ARRAY['Edward Norton', 'Edward Furlong', 'Beverly D''Angelo', 'Jennifer Lien', 'Ethan Suplee', 'Fairuza Balk', 'Avery Brooks', 'Elliott Gould']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 119, '1998-07-01', NULL, 'US: R', 8.3, 'ended'),
  ('9b7708a4-32bd-5279-b742-9a555047548b'::UUID, 207, 'Dead Poets Society', 'Dead Poets Society', 'At an elite, old-fashioned boarding school in New England, a passionate English teacher inspires his students to rebel against convention and seize the potential of every day, courting the disdain of the stern headmaster.', 'At an elite, old-fashioned boarding school in New England, a passionate English teacher inspires his students to rebel against convention and seize the potential of every day, courting the disdain of the stern headmaster.', 'https://image.tmdb.org/t/p/w780/erzbMlcNHOdx24AXOcn2ZKA7R1q.jpg', 'https://image.tmdb.org/t/p/w1280/lFIXZpwwlF9hg8NM3RazaIJDuaj.jpg', 'https://www.youtube.com/watch?v=l8TYfccpdEU', 'Peter Weir', ARRAY['Robin Williams', 'Robert Sean Leonard', 'Ethan Hawke', 'Josh Charles', 'Gale Hansen', 'Dylan Kussman', 'Allelon Ruggiero', 'James Waterston']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 129, '1989-06-02', NULL, 'US: PG', 8.3, 'ended'),
  ('fa6877fe-bdb2-5e93-b848-54ebce07bf9c'::UUID, 3082, 'Thời Đại Tân Kỳ', 'Modern Times', 'The Tramp đấu tranh để sống trong xã hội công nghiệp hiện đại với sự giúp đỡ của một phụ nữ trẻ vô gia cư.', 'A bumbling tramp desires to build a home with a young woman, yet is thwarted time and time again by his lack of experience and habit of being in the wrong place at the wrong time...', 'https://image.tmdb.org/t/p/w780/AthaPakkuCLROdKxtRbKWclkDBK.jpg', 'https://image.tmdb.org/t/p/w1280/kSlO1pHpwQfPQdgVPr7dJiJNtJ8.jpg', 'https://www.youtube.com/watch?v=NNznUyDmSFc', 'Charlie Chaplin', ARRAY['Charlie Chaplin', 'Paulette Goddard', 'Henry Bergman', 'Tiny Sandford', 'Chester Conklin', 'Hank Mann', 'Stanley Blystone', 'Al Ernest Garcia']::TEXT[], ARRAY['Hài', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 87, '1936-02-05', NULL, 'US: G', 8.3, 'ended'),
  ('731970f4-60a4-5000-aefe-08229badeecb'::UUID, 914, 'Kẻ Độc Tài Vĩ Đại', 'The Great Dictator', 'Nhà độc tài Adenoid Hynkel cố gắng mở rộng đế chế của mình trong khi một thợ cắt tóc Do Thái nghèo cố gắng tránh sự đàn áp từ chế độ của Hynkel.', 'Dictator Adenoid Hynkel tries to expand his empire while a poor Jewish barber tries to avoid persecution from Hynkel''s regime.', 'https://image.tmdb.org/t/p/w780/nhMXB8GTdswYMCL9nepDZymJCOr.jpg', 'https://image.tmdb.org/t/p/w1280/c8Pi8F1FzpNebtgXcSjC9nWCdSW.jpg', 'https://www.youtube.com/watch?v=i1C6qZVeFtA', 'Charlie Chaplin', ARRAY['Charlie Chaplin', 'Paulette Goddard', 'Jack Oakie', 'Reginald Gardiner', 'Henry Daniell', 'Billy Gilbert', 'Grace Hayle', 'Carter DeHaven']::TEXT[], ARRAY['Hài', 'Chiến Tranh']::TEXT[], 125, '1940-10-15', NULL, 'US: NR', 8.3, 'ended'),
  ('b57e2c3e-e0fa-5907-897c-ddcbcab651f6'::UUID, 1585, 'Cuộc Sống Tuyệt Diệu', 'It''s a Wonderful Life', 'Phim kể về một thương nhân nghèo khổ nhưng cương trực và tốt bụng tên là George Bailey. Đêm Giáng sinh, đứng trước nguy cơ phá sản và vào tù, George nung nấu ý định tự tử với suy nghĩ biết đâu cái chết của mình sẽ đem lại một khoản tiền bảo hiểm lớn dành cho gia đình. Giữa lúc đó, anh đã gặp thiên thần hộ mệnh Clarence Odbody (Henry Travers), người được phái xuống để giúp đỡ George những lúc anh cần. Phần lớn bộ phim xoay quanh cuộc sống trước đó của George qua sự thuật lại của Franklin và Joseph, thiên thần vô hình đang chuẩn bị cho Clarence thực hiện sứ mệnh cứu rỗi George.', 'George Bailey has spent his entire life giving to the people of Bedford Falls.  All that prevents rich skinflint Mr. Potter from taking over the entire town is George''s modest building and loan company.  But on Christmas Eve the business''s $8,000 is lost and George''s troubles begin.', 'https://image.tmdb.org/t/p/w780/53t1I0hlwIO87gm7yyllaqJmDMf.jpg', 'https://image.tmdb.org/t/p/w1280/ch3lDc4xQ9MpsNEpnRhvR8PIxxK.jpg', 'https://www.youtube.com/watch?v=iLR3gZrU2Xo', 'Frank Capra', ARRAY['James Stewart', 'Donna Reed', 'Lionel Barrymore', 'Thomas Mitchell', 'Henry Travers', 'Beulah Bondi', 'Frank Faylen', 'Ward Bond']::TEXT[], ARRAY['Chính Kịch', 'Gia Đình', 'Giả Tưởng']::TEXT[], 131, '1946-12-20', NULL, 'US: PG', 8.3, 'ended'),
  ('0a752066-0f26-55c8-8085-6c50d8e69083'::UUID, 335, 'Miền Viễn Tây Ngày Ấy', 'C''era una volta il West', 'Một thị trấn nhỏ ở miền Tây bắt đầu trở nên bất ổn khi một ông trùm xe lửa què chân muốn kiểm soát được vùng đất Sweetwater có đường sắt đi qua nên đã thuê các sát thủ xoá sổ gia đình Brett McBain. Cô vợ mới cưới của McBain là Jill trở thành người thừa hưởng toàn bộ gia sản. Cheyenne và một anh chàng Harmonica bí ẩn đã tự nhận nhiệm vụ bảo vệ Jill sau khi McBain bị giết. Nhưng sự việc càng trở nên phức tạp hơn khi anh chàng Harmonica bí ẩn này vô tình dính líu tới vụ tranh chấp đất giữa bà quả phụ Jill và chính nhà tư bản đường sắt tham lam, độc ác…', 'As the railroad builders advance unstoppably through the Arizona desert on their way to the sea, Jill arrives in the small town of Flagstone with the intention of starting a new life.', 'https://image.tmdb.org/t/p/w780/3MPqF2iK6ZBoagnB5H1pjImHpHc.jpg', 'https://image.tmdb.org/t/p/w1280/u5IhDThM1SClL4pkCUp8hOmsDQJ.jpg', 'https://www.youtube.com/watch?v=Yw-Av9BpC-w', 'Sergio Leone', ARRAY['Claudia Cardinale', 'Henry Fonda', 'Jason Robards', 'Charles Bronson', 'Gabriele Ferzetti', 'Paolo Stoppa', 'Woody Strode', 'Jack Elam']::TEXT[], ARRAY['Chính Kịch', 'Miền Tây']::TEXT[], 166, '1968-12-21', NULL, 'US: PG-13', 8.3, 'ended'),
  ('ab6bd22b-e648-53e0-a2e3-651bb925f2b1'::UUID, 28, 'Lời Sấm Truyền', 'Apocalypse Now', 'Lời Sấm Truyền là một kiệt tác thuộc dòng phim phản chiến, được xem là một trong những đỉnh cao sáng tạo nhất của nhà đạo diễn Francis Ford Coppola. Bộ phim tái hiện lại cuộc chiến tàn khốc của quân đội Mỹ tại Việt Nam cùng những nguyên nhân sâu xa đã khiến quân đội Mỹ gục ngã.Đây là một tác phẩm gây ám ảnh, nêu bật lên nhiều vấn đề phản chiến đậm tính nhân loại, về bản chất của loài người, và những nỗi đau ghê sợ đến tột cùng, được gói gọn chỉ trong 2 chữ: "Kinh Hoàng".Dựa một phần vào tác phẩm của Joseph Conrad, "The Heart of Darkness", bộ phim chuyển câu chuyện về thời điểm chiến tranh Việt Nam. Một đại úy lực lượng đặc nhiệm Mỹ được lệnh truy đuổi và ám sát viên đại tá Walter E. Kurtz , người đang dần trở ...', 'At the height of the Vietnam war, Captain Benjamin Willard is sent on a dangerous mission that, officially, "does not exist, nor will it ever exist." His goal is to locate - and eliminate - a mysterious Green Beret Colonel named Walter Kurtz, who has been leading his personal army on illegal guerrilla missions into enemy territory.', 'https://image.tmdb.org/t/p/w780/lPI6DUI1hVOiVuN2NIFnUf4YpDQ.jpg', 'https://image.tmdb.org/t/p/w1280/49fzLedFVKgGgFChLMuulDJBY1c.jpg', 'https://www.youtube.com/watch?v=9l-ViOOFH-s', 'Francis Ford Coppola', ARRAY['Martin Sheen', 'Marlon Brando', 'Frederic Forrest', 'Albert Hall', 'Laurence Fishburne', 'Sam Bottoms', 'Robert Duvall', 'G.D. Spradlin']::TEXT[], ARRAY['Chính Kịch', 'Chiến Tranh']::TEXT[], 147, '1979-05-19', NULL, 'US: R', 8.3, 'ended'),
  ('5ba53edf-9067-5467-b65f-ee23562def78'::UUID, 857, 'Giải Cứu Binh Nhì Ryan', 'Saving Private Ryan', 'Bắt đầu với cuộc xâm lược của quân Đồng minh Normandy vào ngày 6 tháng 6 năm 1944, các thành viên của tiểu đoàn tấn công thứ hai, dưới quyền Đại úy Miller, chiến đấu để giành quyền kiểm soát bãi biển. Trong trận chiến, hai anh em bị giết. Một chút trước đó, ở New Guinea, một người anh em thứ ba cũng bị giết. Mẹ của ông, bà Ryan, sẽ nhận được ba bức điện tử trong cùng một ngày. Người đứng đầu quân đội Mỹ, George C. Marshall, nhìn thấy cơ hội làm giảm bớt nỗi đau khổ của cô khi anh biết được một người anh em thứ tư, Private James Ryan, và quyết định cử tám người (Thuyền trưởng Miller và một nhóm được chọn từ tiểu đoàn của anh ta) đi tìm Anh ta và đưa anh ta trở về nhà của mẹ mình.', 'As U.S. troops storm the beaches of Normandy, three brothers lie dead on the battlefield, with a fourth trapped behind enemy lines. Ranger captain John Miller and seven men are tasked with penetrating German-held territory and bringing the boy home.', 'https://image.tmdb.org/t/p/w780/wz11UlVEmJjmNnRnrWH8MqItj5A.jpg', 'https://image.tmdb.org/t/p/w1280/bdD39MpSVhKjxarTxLSfX6baoMP.jpg', 'https://www.youtube.com/watch?v=RYExstiQlLc', 'Steven Spielberg', ARRAY['Tom Hanks', 'Tom Sizemore', 'Edward Burns', 'Barry Pepper', 'Adam Goldberg', 'Vin Diesel', 'Giovanni Ribisi', 'Jeremy Davies']::TEXT[], ARRAY['Chiến Tranh', 'Chính Kịch', 'Lịch Sử']::TEXT[], 169, '1998-07-24', NULL, 'US: R', 8.2, 'ended'),
  ('cd1d1964-a80b-5c18-87de-61f480cee47b'::UUID, 77, 'Kẻ Mất Trí Nhớ', 'Memento', 'Memento là câu chuyện xoay quanh Leonard Shelby, một người mắc chứng trí nhớ ngắn hạn truy tìm kẻ đã hãm hiếp và giết chết vợ anh. Leonard chỉ có thể nhớ những chuyện xảy ra trước vụ án mạng còn từ sau đó thì anh không thể nhớ điều gì quá 10 phút nên anh luôn phải ghi chép, chụp ảnh và thậm chí xăm mình để ghi nhớ mọi việc. Phim được chia làm 2 mảng truyện đan xen nhau và cứ thế, bức màn bí mật dần dần được hé lộ qua từng thước phim...', 'Leonard Shelby is tracking down the man who raped and murdered his wife. The difficulty of locating his wife''s killer, however, is compounded by the fact that he suffers from a rare, untreatable form of short-term memory loss. Although he can recall details of life before his accident, Leonard cannot remember what happened fifteen minutes ago, where he''s going, or why.', 'https://image.tmdb.org/t/p/w780/vNI7euY6xBJXCUzW4TSmswlSI00.jpg', 'https://image.tmdb.org/t/p/w1280/7Wev9JMo6R5XAfz2KDvXb7oPMmy.jpg', 'https://www.youtube.com/watch?v=Wyc9TpJxf4A', 'Christopher Nolan', ARRAY['Guy Pearce', 'Carrie-Anne Moss', 'Joe Pantoliano', 'Mark Boone Junior', 'Russ Fega', 'Jorja Fox', 'Stephen Tobolowsky', 'Harriet Sansom Harris']::TEXT[], ARRAY['Bí Ẩn', 'Giật Gân']::TEXT[], 113, '2000-10-11', NULL, 'US: R', 8.2, 'ended'),
  ('203dffb3-38dd-56e1-85c4-33ec180d41be'::UUID, 489, 'Chàng Will Tốt Bụng', 'Good Will Hunting', 'Cậu bé Will Hunting bất hạnh lớn lên trong những xó xỉnh của Boston tham gia vào vô số những trò vô bổ: uống rượu, đánh nhau… Nhưng cậu lại là người thông minh và rất yêu khoa học. Cuộc đời Will đã rẽ sang ngả khác khi anh được nhận vào làm bảo vệ cho Học viện Công nghệ Massachusetts. Một lần vì tò mò Will nhìn trộm buổi học của lớp toán ứng dụng. Cậu đặc biệt thích thú với bài toán hóc búa của giáo sư Gerald Lambeau, Will đã giải nó ngay trong đêm.... Good Will Hunting là minh chứng hùng hồn cho quan điểm nhân tài có ở mọi nơi không kể xuất thân, địa vị, hoàn cảnh chỉ cần có cơ hội họ sẽ thể hiện được năng lực của mình. Qua câu chuyện của Will lại một lần nữa vai trò giáo dục của gia đình được nhấn mạnh nếu Will ...', 'Will Hunting is a headstrong, working-class genius who is failing the lessons of life. After one too many run-ins with the law, Will''s last chance is a psychology professor, who might be the only man who can reach him.', 'https://image.tmdb.org/t/p/w780/iRrgGkGg9q9pV6Hgg8fYU0nELJv.jpg', 'https://image.tmdb.org/t/p/w1280/xj1Sv1xm4Y0ydBueGuf10Y9qM0O.jpg', 'https://www.youtube.com/watch?v=ReIJ1lbL-Q8', 'Gus Van Sant', ARRAY['Matt Damon', 'Robin Williams', 'Ben Affleck', 'Stellan Skarsgård', 'Minnie Driver', 'Casey Affleck', 'Cole Hauser', 'Vik Sahay']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 127, '1997-12-05', NULL, 'US: R', 8.2, 'ended'),
  ('7287fb8f-9bb2-57d1-9336-2037c6ea08d1'::UUID, 629, 'Kẻ Chủ Mưu', 'The Usual Suspects', 'Trong một phòng thẩm vấn ở LA, Verbal Kint cố gắng thuyết phục các đặc vụ liên bang rằng một chúa tể tội phạm huyền thoại, Keyser Soze, không chỉ tồn tại mà còn có trách nhiệm lôi kéo anh ta và bốn đối tác của anh ta vào một vụ trộm trị giá hàng triệu đô la và kết thúc bằng một vụ nổ ở cảng San Pedro - chỉ còn lại một số người sống sót. Verbal thu hút những người thẩm vấn của mình bằng một câu chuyện đáng kinh ngạc về năng lực gần như siêu phàm của tên tội phạm.', 'The lone survivor of an explosive heist gone wrong recounts for interrogators the events that began with five disparate criminals assembled for a police lineup - with alleged criminal mastermind Keyser Soze at the center of it all.', 'https://image.tmdb.org/t/p/w780/g59ugx0EbKTj8KfelY3kmTc9S2Y.jpg', 'https://image.tmdb.org/t/p/w1280/hy0Hx9fMPk2fmw26Li60z1S2giU.jpg', 'https://www.youtube.com/watch?v=jM3jrHGAsIE', 'Bryan Singer', ARRAY['Stephen Baldwin', 'Gabriel Byrne', 'Benicio del Toro', 'Kevin Pollak', 'Kevin Spacey', 'Chazz Palminteri', 'Pete Postlethwaite', 'Suzy Amis']::TEXT[], ARRAY['Chính Kịch', 'Tội Phạm', 'Giật Gân']::TEXT[], 106, '1995-07-19', NULL, 'US: R', 8.2, 'ended'),
  ('4a169fb9-5165-500f-bab6-d1b2718d3173'::UUID, 37165, 'Chương Trình Truman', 'The Truman Show', 'Chương trình Truman (The Truman Show) là một bộ phim khoa học viễn tưởng hài kịch Mỹ năm 1998 của đạo diễn Peter Weir và biên kịch Andrew Nicol... Bộ phim kể về Truman Burbank là một người đặc biệt, ngôi sao trong show truyền hình thực tế nổi tiếng: The Truman Show nhưng Truman thực sự lại không biết điều đó. Tất cả những hành động nhỏ nhặt nhất của anh trong cuộc sống hàng ngày đều được một đạo diễn kiêm nhà sản xuất ghi lại. Thành phố nơi anh sống trở thành một studio lớn, những người hàng xóm, đồng nghiệp, bạn bè và cả vợ anh đều là những diễn viên chuyên nghiệp của Hollywood. Rồi một ngày, Truman tỏ ra nghi ngờ một điều gì đó...', 'In a picture-perfect seaside town, an insurance salesman begins to realize that his entire existence may be staged and observed by a vast unseen audience as part of a long-running real-time reality TV show.', 'https://image.tmdb.org/t/p/w780/QcHAlTXFdoBHq2T8wbr5RxxAnH.jpg', 'https://image.tmdb.org/t/p/w1280/rmiG2uwcNoGFmBKMoa1pIcf514L.jpg', 'https://www.youtube.com/watch?v=N1VlDVRiFrk', 'Peter Weir', ARRAY['Jim Carrey', 'Ed Harris', 'Laura Linney', 'Noah Emmerich', 'Natascha McElhone', 'Holland Taylor', 'Paul Giamatti', 'Brian Delate']::TEXT[], ARRAY['Hài', 'Chính Kịch']::TEXT[], 103, '1998-06-04', NULL, 'US: PG', 8.2, 'ended'),
  ('a70fe374-6819-58f7-9be1-00562c738c5a'::UUID, 111, 'Mặt Sẹo', 'Scarface', '125 nghìn người tị nạn ở Cuba được nhập cảnh Mỹ và đoàn tụ với người thân. Trong đám đông đó, Tony Montana lại nuôi tham vọng khác. Từ một gã tay chân cho băng đảng và bắt đầu dấn thân vào con đường tăm tối, Tony ngày càng bị cơn khát quyền lực dằn vặt, ngay cả khi đã trở thành ông trùm.', 'After getting a green card in exchange for assassinating a Cuban government official, Tony Montana stakes a claim on the drug trade in Miami. Viciously murdering anyone who stands in his way, Tony eventually becomes the biggest drug lord in the state, controlling nearly all the cocaine that comes through Miami. But increased pressure from the police, wars with Colombian drug cartels and his own drug-fueled paranoia serve to fuel the flames of his eventual downfall.', 'https://image.tmdb.org/t/p/w780/iQ5ztdjvteGeboxtmRdXEChJOHh.jpg', 'https://image.tmdb.org/t/p/w1280/cCvp5Sni75agCtyJkNOMapORUQV.jpg', 'https://www.youtube.com/watch?v=lZMIrD36MG8', 'Brian De Palma', ARRAY['Al Pacino', 'Steven Bauer', 'Michelle Pfeiffer', 'Mary Elizabeth Mastrantonio', 'Robert Loggia', 'Miriam Colon', 'F. Murray Abraham', 'Paul Shenar']::TEXT[], ARRAY['Hành Động', 'Tội Phạm', 'Chính Kịch']::TEXT[], 170, '1983-12-09', NULL, 'US: R', 8.2, 'ended'),
  ('98e5de6a-5dca-5c90-9f51-8f0f2cb6386f'::UUID, 289, 'Chuyện Tình Thế Chiến', 'Casablanca', 'Câu chuyện trong Casablanca xảy ra tại thành phố cảng cùng tên, thuộc Marốc, lúc này đang chịu sự quản lý của chính quyền Vichy Pháp thân Đức Quốc xã. Bóng đen của Thế chiến II đang lớn dần. Dòng người từ khắp châu Âu đổ về Casablanca ngày càng nhiều. Nơi đây đóng vai trò như một trạm trung chuyển giữa vùng bị phát xít chiếm đóng với nước Mỹ tự do. Nhân vật chính của bộ phim là Rick Blaine, một gã người Mỹ lưu vong, chủ của một quán bar hạng sang kiêm sòng bạc. Rick kiệm lời, khó gần. Phương châm sống của anh là: "Tôi chẳng đưa đầu ra cho ai cả". Trung lập về chính trị, không chõ mũi vào chuyện người khác khiến Rick sống yên ổn ở Casablanca.', 'In Casablanca, Morocco in December 1941, a cynical American expatriate meets a former lover, with unforeseen complications.', 'https://image.tmdb.org/t/p/w780/b2pVw0jnSwiI1VP6U7X1kKd3vGG.jpg', 'https://image.tmdb.org/t/p/w1280/87wqeMeUeMRLjsE1IWNKJcPlpuC.jpg', 'https://www.youtube.com/watch?v=MF7JH_54d8c', 'Michael Curtiz', ARRAY['Humphrey Bogart', 'Ingrid Bergman', 'Paul Henreid', 'Claude Rains', 'Conrad Veidt', 'Sydney Greenstreet', 'Peter Lorre', 'S.Z. Sakall']::TEXT[], ARRAY['Chính Kịch', 'Lãng Mạn']::TEXT[], 102, '1943-01-15', NULL, 'US: PG', 8.1, 'ended'),
  ('580d2c92-aa0c-5204-89d7-e9e7b8eb89c1'::UUID, 490, 'Phong Ấn Thứ Bảy', 'Det sjunde inseglet', 'The Seventh Seal - Det sjunde inseglet (1957) lấy bối cảnh thời Trung cổ trong khung cảnh châu Âu lúc đó đang bị đại dịch hoành hành. Bộ phim xoay quanh câu chuyện của chàng hiệp sĩ người Thụy Điển Antonius Block, trở về sau cuộc Thập tự chinh, người đã được thần Chết viếng thăm và cho phép chơi một ván cờ với thần để giành lấy mạng sống của mình. Block là người hiểu lý lẽ, chàng biết rõ chàng gần như không có cơ hội chiến thắng. Tất cả những gì chàng muốn là có thêm thời gian trì hoãn. Một sự trì hoãn mong manh khỏi một cái tất yếu, đồng thời chàng hy vọng cuộc đánh cờ với vị thần quyền năng sẽ giúp chàng giải đáp những câu hỏi về đức tin, về cái chết, về sự cô độc của con người trong thế giới...', 'When disillusioned Swedish knight Antonius Block returns home from the Crusades to find his country in the grips of the Black Death, he challenges Death to a chess match for his life. Tormented by the belief that God does not exist, Block sets off on a journey, meeting up with traveling players Jof and his wife, Mia, and becoming determined to evade Death long enough to commit one redemptive act while he still lives.', 'https://image.tmdb.org/t/p/w780/cGaEX4XfOWo6JvQjOG01iOHT9UP.jpg', 'https://image.tmdb.org/t/p/w1280/6s2BqtDvp1BMiP70zCDU5OW6hMy.jpg', 'https://www.youtube.com/watch?v=vZucwtdSvJ8', 'Ingmar Bergman', ARRAY['Gunnar Björnstrand', 'Bengt Ekerot', 'Nils Poppe', 'Max von Sydow', 'Bibi Andersson', 'Inga Gill', 'Maud Hansson', 'Inga Landgré']::TEXT[], ARRAY['Giả Tưởng', 'Chính Kịch']::TEXT[], 96, '1957-02-16', NULL, 'US: NR', 8.1, 'ended'),
  ('2ae9637f-6475-513a-be8d-9f5998b6cd77'::UUID, 872, 'Hát Dưới Mưa', 'Singin'' in the Rain', 'Khi quá trình chuyển đổi đang được thực hiện từ phim câm sang phim nói chuyện, mọi người đều gặp khó khăn trong việc thích nghi. Don và Lina đã nhiều lần được chọn vào vai một cặp tình nhân lãng mạn, nhưng khi bộ phim mới nhất của họ được dựng lại thành nhạc kịch, chỉ có Don là người lồng tiếng cho phần hát mới. Sau nhiều lần luyện tập với một huấn luyện viên múa, Lina vẫn nghe rất tệ, và Kathy, một nữ diễn viên trẻ đầy tham vọng, được thuê để thu âm giọng nói của cô ấy.', 'In 1927 Hollywood, a silent film star falls for a chorus girl just as he and his paranoid screen partner struggle to make the difficult transition to talking pictures.', 'https://image.tmdb.org/t/p/w780/zjrpWniKbzu0zFR5sUI1Ptdfl9y.jpg', 'https://image.tmdb.org/t/p/w1280/6qOyw4yfzbzTp5YsCX26C28Do0S.jpg', 'https://www.youtube.com/watch?v=lSE8sl2-PZg', 'Stanley Donen', ARRAY['Gene Kelly', 'Donald O''Connor', 'Debbie Reynolds', 'Jean Hagen', 'Millard Mitchell', 'Cyd Charisse', 'Douglas Fowley', 'Rita Moreno']::TEXT[], ARRAY['Hài', 'Lãng Mạn']::TEXT[], 103, '1952-04-10', NULL, 'US: G', 8.1, 'ended'),
  ('d297abfd-195f-5ed4-932d-27fe92129031'::UUID, 600, 'Áo Giáp Sắt', 'Full Metal Jacket', '"Áo Giáp Sắt" theo chân James. T "Joker" Davis và những tân binh thuộc Thủy quân Lục Chiến Hoa Kỳ từ trại huấn luyện khắc nghiệt, nơi họ bị biến thành những cỗ máy sát nhân vô cảm dưới sự áp bức của Trung sĩ Hartman, cho đến khi trực tiếp đối mặt với nỗi kinh hoàng tột cùng của cuộc tấn công Tết Mậu Thân trên chiến trường đổ nát. Một cái nhìn chân thực, ám ảnh và đầy châm biếm về bản tính hai mặt của con người khi nhân tính bị bào mòn bởi bom đạn.', 'A pragmatic U.S. Marine observes the dehumanizing effects the U.S.-Vietnam War has on his fellow recruits from their brutal boot camp training to the bloody street fighting in Hue.', 'https://image.tmdb.org/t/p/w780/caKIPzSfBhbfQDMT6fxvFQyTE92.jpg', 'https://image.tmdb.org/t/p/w1280/3k2TRmqMjgt7tcwkYwZQdctnty3.jpg', 'https://www.youtube.com/watch?v=n2i917l5RFc', 'Stanley Kubrick', ARRAY['Matthew Modine', 'Adam Baldwin', 'Vincent D''Onofrio', 'R. Lee Ermey', 'Dorian Harewood', 'Kevyn Major Howard', 'Arliss Howard', 'Ed O''Ross']::TEXT[], ARRAY['Chính Kịch', 'Chiến Tranh']::TEXT[], 117, '1987-06-26', NULL, 'US: R', 8.1, 'ended'),
  ('ba622c6d-624c-59ec-bcbd-603db0b17d97'::UUID, 935, 'Tiến Sĩ Strangelove Hay Là: Cách Tôi Học Được Để Chặn Đứng Nỗi Sợ Và Yêu Trái Bom', 'Dr. Strangelove or: How I Learned to Stop Worrying and Love the Bomb', 'Nước Mỹ trong thời kì chiến tranh lạnh. Một ngày đẹp trời, viên tướng Jack D. Ripper (Sterling Hayden) bỗng nảy ra ý định tấn công Liên Xô bằng bom nguyên tử. Lệnh tấn công được phát ra, và các máy bay B52 lập tức lên đường, trực chỉ Liên Xô. Sĩ quan Lionel Mandrake (Peter Sellers) tìm mọi cách làm cho Jack D. Ripper nghĩ lại và thu hồi lệnh tấn công, nhưng đều thất bại. Cùng lúc đó, tại Lầu Năm Góc, một cuộc họp khẩn cấp được triệu tập nhằm ngăn chặn bằng mọi giá vụ tấn công. Họ được Đại sứ Liên Xô thông báo rằng, nếu như vụ tấn công xảy ra, cỗ máy Doomsday Machine của Liên Xô sẽ tự động kích hoạt, và trong vòng 10 tháng tới sẽ không còn bất kì sinh vật nào trên Trái Đất còn sống sót. Nỗi lo về ngày tận thế đến gần, và những nhân vật chóp bu của Mỹ tìm mọi cách ngăn chặn thảm hoạ cho toàn nhân loại...', 'After the insane General Jack D. Ripper initiates a nuclear strike on the Soviet Union, a war room full of politicians, generals and a Russian diplomat all frantically try to stop it.', 'https://image.tmdb.org/t/p/w780/gHm96BRW4GoI339rF1vYoYTB6Qe.jpg', 'https://image.tmdb.org/t/p/w1280/7i0L2ee4Iy0aXV6vR5u1ZmblOrx.jpg', 'https://www.youtube.com/watch?v=XjLsIWZdWmc', 'Stanley Kubrick', ARRAY['Peter Sellers', 'George C. Scott', 'Sterling Hayden', 'Keenan Wynn', 'Slim Pickens', 'Peter Bull', 'James Earl Jones', 'Tracy Reed']::TEXT[], ARRAY['Hài', 'Chiến Tranh']::TEXT[], 95, '1964-01-29', NULL, 'US: PG', 8.1, 'ended'),
  ('70056ba8-1c73-5e9b-827e-10becec2c3de'::UUID, 791523, 'Wildwood', 'Wildwood', 'Hành trình tuyệt vọng của một cô bé nhằm cứu em trai sơ sinh mở ra một cuộc phiêu lưu kỳ ảo đầy hiểm nguy trong khu rừng cấm, nơi có những sinh vật huyền bí, đồng minh đáng mến và kẻ thù đáng gờm, với số phận của cả một vương quốc bí ẩn đang bị đe dọa.', 'After her baby brother is abducted by a murder of crows, headstrong teenager Prue McKeel launches a desperate rescue mission into the Impassable Wilderness, an enchanted forest hidden just beyond Portland, Oregon. Joined by her hapless but loyal classmate Curtis Mehlberg, Prue navigates a world of talking animals, bandits, and powerful figures driven by grief and ambition. As the pair is drawn into a conflict threatening the balance of the forest itself, Prue must discover the strength and belief she never knew she possessed.', 'https://image.tmdb.org/t/p/w780/8g7q6o54WfKWRmUQ0Ye8OskevUY.jpg', 'https://image.tmdb.org/t/p/w1280/sl5NJ1vtyhP9Vr88bB4blULsJYp.jpg', 'https://www.youtube.com/watch?v=bJQGtSeLPII', 'Travis Knight', ARRAY['Peyton Elizabeth Lee', 'Jacob Tremblay', 'Carey Mulligan', 'Mahershala Ali', 'Richard E. Grant', 'Angela Bassett', 'Awkwafina', 'Amandla Stenberg']::TEXT[], ARRAY['Hoạt Hình', 'Phiêu Lưu', 'Giả Tưởng']::TEXT[], 132, '2026-10-19', NULL, 'US: PG-13', 8.7, 'ended'),
  ('f784c21f-aea9-5335-975c-f7f8223b966b'::UUID, 1058424, 'Hope: Vùng Tử Địa', '호프', 'Tại Hope Harbor, một ngôi làng hẻo lánh nằm gần khu vực phi quân sự, cảnh sát trưởng Bum-seok đã nhận được tin báo khẩn cấp từ người dân địa phương về sự xuất hiện của một con hổ. Khi cả ngôi làng chìm trong hoảng loạn, Bum-seok ngỡ ngàng khi phát hiện một sự thật nằm ngoài sức tưởng tượng của con người.', 'In the remote South Korean village of Hope Harbor, police chief Bum-seok and officer Sung-ae are called to investigate a mysterious creature wreaking havoc on the community. But all is not as it seems, and perceptions can be misleading. What begins as ignorance plants the seed of disaster, escalating through human conflict into a tragedy of cosmic proportions.', 'https://image.tmdb.org/t/p/w780/yY5GFSFM4eQknenk2oCoC19EeF5.jpg', 'https://image.tmdb.org/t/p/w1280/j96rurZqmBjyY37Fncl3IB0qJNe.jpg', 'https://www.youtube.com/watch?v=OFaJzL83y0Q', '나홍진', ARRAY['황정민', '조인성', '정호연', 'Alicia Vikander', 'Michael Fassbender', 'Taylor Russell', 'Cameron Britton', '이상희']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Bí Ẩn', 'Hành Động']::TEXT[], 157, '2026-07-15', NULL, 'KR: 15', 6.8, 'ended'),
  ('623154dd-1b06-552c-891d-9f92c3c2a4d7'::UUID, 1596275, 'Drive – The Pretenders', 'Drive – The Pretenders', 'A young mechanic fakes an engagement with racing''s most scandalous star — officially for his reputation, secretly for her own shot behind the wheel. But soon the lie threatens to destroy everything — including what''s already become so much more than just a deal.', 'A young mechanic fakes an engagement with racing''s most scandalous star — officially for his reputation, secretly for her own shot behind the wheel. But soon the lie threatens to destroy everything — including what''s already become so much more than just a deal.', 'https://image.tmdb.org/t/p/w780/o1amTBOej7F2wdrTSKzGE6eG2CT.jpg', 'https://image.tmdb.org/t/p/w1280/hbz4aeVsjnKb2HRoFbbr46Egh8y.jpg', 'https://www.youtube.com/watch?v=-sV69CJwUwU', 'Sergej Moya', ARRAY['Lisa-Marie Koroll', 'Amin Baahmed', 'Gustav Schmidt', 'Mišel Matičević', 'Lucie Heinze', 'Frederic Linkemann', 'Inka Friedrich', 'Jeanette Hain']::TEXT[], ARRAY['Lãng Mạn', 'Giật Gân']::TEXT[], 103, '2026-10-27', NULL, 'US: R', 7.6, 'ended'),
  ('1ccc7471-2cfa-5703-b09e-2555d87b4904'::UUID, 1101412, 'Cú Rơi Tử Thần 2: Điểm Chết', 'Fall 2: Deadpoint', 'Sau cái chết của chị gái Hunter, Jax tìm thấy chút an ủi nơi Luce, người bạn gan dạ từng thân thiết với Hunter. Để đối diện nỗi mất mát, họ cùng thử thách cung đường ván treo khét tiếng trên núi Kwan ở Thái Lan, nhưng một vụ sạt lở bất ngờ khiến Jax mắc kẹt ở độ cao 3,000 feet, nơi chỉ một bước sai cũng có thể là dấu chấm hết.', 'On a perilous climb across Thailand''s Mount Kwan, two climbers become trapped thousands of feet above the ground, where vertigo-inducing heights, sheer exposure, and impossible odds turn every moment into a fight for survival.', 'https://image.tmdb.org/t/p/w780/fgSm5ylwiXbIHn8UbUXDjk9RRu4.jpg', 'https://image.tmdb.org/t/p/w1280/nGau0KBOaRILSK5MqFcuTfv7GMl.jpg', 'https://www.youtube.com/watch?v=Krs0VDIjhmE', 'Michael Spierig', ARRAY['Harriet Slater', 'Arsema Thomas', 'Tom Brittney', 'สหจักร บุญธนกิจ', 'Korakod Yensuk', 'Jordan Coleman', 'Maryna Bennett', 'Noen Perez']::TEXT[], ARRAY['Giật Gân']::TEXT[], 98, '2026-09-01', NULL, 'US: PG-13', 7.3, 'ended'),
  ('7a27209e-f8c0-5865-beea-7eb45ade4852'::UUID, 1283515, 'Verity: Bí Mật Bị Chôn Vùi', 'Verity', 'Lowen Ashleigh được Jeremy Crawford thuê để viết tiếp các tiểu thuyết dang dở cho vợ anh là Verity, một nữ nhà văn nổi tiếng không còn khả năng hoàn thành công việc sau tai nạn. Trong thời gian sống tại nhà Crawford để làm việc, Lowen dần phát hiện những bí mật rùng rợn xoay quanh Verity.', 'Lowen Ashleigh, hired to ghostwrite for best-selling author Verity Crawford, uncovers Verity''s autobiographical notes, and becomes involved in what may prove to be a lethal conspiracy.', 'https://image.tmdb.org/t/p/w780/54MwktkK2i2GJM8fYU9jNXGaHk.jpg', 'https://image.tmdb.org/t/p/w1280/cKetrF2dAnQ0AMV5i4BMOs41I5P.jpg', 'https://www.youtube.com/watch?v=xdPMKhjMSFs', 'Michael Showalter', ARRAY['Dakota Johnson', 'Anne Hathaway', 'Josh Hartnett', 'Brady Wagner', 'Ismael Cruz Cordova', 'Ірина Дворовенко', 'Sienna Kulovitz', 'K.K. Moggie']::TEXT[], ARRAY['Bí Ẩn', 'Giật Gân']::TEXT[], 117, '2026-09-30', NULL, 'US: R', 6.9, 'ended'),
  ('79823037-5046-50a5-b192-0ba25f6cdfea'::UUID, 1507696, 'Khải Huyền Z: Thế Giới Mới', 'Apocalipsis Z: Nuevo mundo', 'Nối tiếp các sự kiện kinh hoàng từ phần trước, virus TSJ đã quét sạch nền văn minh nhân loại, biến phần lớn dân số thế giới thành những sinh vật hung hãn, khát máu. Giữa bối cảnh hoang tàn đó, quần đảo Canary may mắn trở thành tiền đồn an toàn cuối cùng, nuôi dưỡng hy vọng sống sót mong manh của toàn châu Âu. Tuy nhiên, nguồn tài nguyên tại đây đang dần cạn kiệt. Để cứu lấy cộng đồng, Roberto buộc phải dẫn đầu một đội đặc nhiệm tinh nhuệ thực hiện chuyến hành trình tự sát quay trở lại đất liền Tây Ban Nha, hướng thẳng vào tâm dịch Madrid. Nhiệm vụ của họ là tìm kiếm và mang về các nhu yếu phẩm cùng thiết bị y tế cốt lõi. Bước chân vào vùng đất chết, cả nhóm nhanh chóng bị bủa vây bởi hàng vạn xác sống tiến hóa và hung hãn hơn trước. Đáng sợ hơn cả lũ quái vật ngoài kia, những âm mưu đen tối ngầm định, sự nghi kỵ và lòng tham từ chính các thành viên trong đội bắt đầu lộ diện.', 'The Canary Islands have become Europe’s last refuge following the outbreak of the TSJ virus. When a special mission sets out for the mainland in search of vital supplies, Roberto joins the team with questionable intentions. The dangerous operation turns into a desperate race for survival, and Roberto and his companions find themselves caught between hordes of infected and divided loyalties.', 'https://image.tmdb.org/t/p/w780/c5LakPnLfzydW4YFUKfPeiODiWu.jpg', 'https://image.tmdb.org/t/p/w1280/o3XwuDUj0n8qnK91p6q8LKfr6rj.jpg', 'https://www.youtube.com/watch?v=BIEzwpyawtw', 'Carles Torrens', ARRAY['Carlos Alcaide', 'Julia Martínez', 'José María Yázpik', 'Mónica López', 'Tamara Casellas', 'Berta Vázquez', 'Santiago Vaca Narvaja', 'Mario Mayo']::TEXT[], ARRAY['Hành Động', 'Giật Gân', 'Kinh Dị']::TEXT[], 96, '2026-10-09', NULL, 'US: R', 6, 'ended'),
  ('24ab5248-9599-5207-88de-12f18eb33f8e'::UUID, 1657630, 'El despertar', 'El despertar', 'An elite military unit on a mission in the South American jungle encounters a deadly supernatural force revealing an ancient presence that continues to claim anyone who dares enter its domain.', 'An elite military unit on a mission in the South American jungle encounters a deadly supernatural force revealing an ancient presence that continues to claim anyone who dares enter its domain.', 'https://image.tmdb.org/t/p/w780/w3YJx1PPPC6aiVKusxfc9QA0uYS.jpg', 'https://image.tmdb.org/t/p/w1280/4pYKqctQvvdyhuGjiK4szH9jEv9.jpg', 'https://www.youtube.com/watch?v=hj6Cer6bJUI', 'Jaime Osorio Márquez', ARRAY['Claudio Cataño', 'Alejandro Buitrago', 'Hector Sánchez', 'Andrea Olaya', 'Quique Sanmartin', 'Jaisson Jeack', 'Carlos Mariño', 'Andres Londono']::TEXT[], ARRAY['Kinh Dị', 'Hành Động', 'Chiến Tranh', 'Giả Tưởng', 'Giật Gân']::TEXT[], 96, '2026-10-29', NULL, 'US: NR', 6.6, 'ended'),
  ('8a87bb5f-7e0c-5984-ac55-0e1aa4e0603c'::UUID, 1514026, 'Buddy: Sát Nhân Kỳ Lân', 'Buddy', 'Inside the colorful world of "It''s Buddy!", a group of children spend their days singing, dancing, and helping Buddy - bright orange unicorn - spread happiness. But when one child refuses to play along, Buddy is not pleased and cracks begin to appear in this seemingly perfect world.', 'Inside the colorful world of "It''s Buddy!", a group of children spend their days singing, dancing, and helping Buddy - bright orange unicorn - spread happiness. But when one child refuses to play along, Buddy is not pleased and cracks begin to appear in this seemingly perfect world.', 'https://image.tmdb.org/t/p/w780/1BdZbNvl1SfrrX8J9X5tQzN6Ivu.jpg', 'https://image.tmdb.org/t/p/w1280/ytoLEl5yDaxB8AtZ52uKWjaQ9ql.jpg', 'https://www.youtube.com/watch?v=Pc9MbCNYn3k', 'Casper Kelly', ARRAY['Keegan-Michael Key', 'Delaney Quinn', 'Tristan Borders', 'Madison Skyy Polan', 'Caleb Williams', 'Cristin Milioti', 'Topher Grace', 'Patton Oswalt']::TEXT[], ARRAY['Kinh Dị', 'Hài', 'Giả Tưởng']::TEXT[], 96, '2026-08-27', NULL, 'US: R', 7, 'ended'),
  ('4a8247c0-53cf-557c-bb5b-72825765431f'::UUID, 1400940, 'Clayface', 'Clayface', 'Bộ phim theo chân hành trình sa ngã kinh hoàng của một diễn viên triển vọng ở Hollywood khi anh dần biến thành một quái vật bị thôi thúc bởi lòng thù hận, qua đó phơi bày sự đánh mất bản ngã và nhân tính, những tàn phá của tình yêu độc hại và mặt tối của tham vọng khoa học.', 'Matt Hagen''s meteoric rise from Gotham street kid to Hollywood leading man is tragically cut short when a local crime boss''s actions leave him horribly disfigured. Abandoned by his team and with nothing left, Matt seeks out a cutting edge treatment that miraculously returns him to his former self… but also unexpectedly affects his grip on reality, spiraling him down a destructive path of all-consuming revenge.', 'https://image.tmdb.org/t/p/w780/vyQJ8ER4DYKVrCeraQ1VGQf7Olt.jpg', 'https://image.tmdb.org/t/p/w1280/xSDoxv4pHvs4xZjvTb0Iqg1A6ro.jpg', 'https://www.youtube.com/watch?v=f7jlCqdtwdM', 'James Watkins', ARRAY['Tom Rhys Harries', 'Naomi Ackie', 'Eddie Marsan', 'Max Minghella', 'David Dencik', 'Francesca Corney', 'Ruby Sear', 'Wil Coban']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân', 'Khoa Học Viễn Tưởng']::TEXT[], 109, '2026-10-19', NULL, 'US: R', 7.5, 'ended'),
  ('aefd2a9a-7b59-5fe8-8a0b-8aa86a17a320'::UUID, 1232569, 'Pinocchio: Unstrung', 'Pinocchio: Unstrung', 'Influenced by a sinister Cricket and created by Geppetto, Pinocchio launches a violent crusade to carve himself into a real boy like his brother James, one piece at a time.', 'Influenced by a sinister Cricket and created by Geppetto, Pinocchio launches a violent crusade to carve himself into a real boy like his brother James, one piece at a time.', 'https://image.tmdb.org/t/p/w780/hJNdizFlxOW89edX3Rzr6OliSFI.jpg', 'https://image.tmdb.org/t/p/w1280/7RsPdXLDNugDIlwXPVeeprNfMx.jpg', 'https://www.youtube.com/watch?v=Y4lZewE6JMI', 'Rhys Frake-Waterfield', ARRAY['Jude Evan Lloyd', 'Cameron Bell', 'Richard Brake', 'Jessica Balmer', 'Jack Art Gray', 'Robert Englund', 'Emma Tate', 'Toni Olabanji']::TEXT[], ARRAY['Kinh Dị', 'Giả Tưởng', 'Bí Ẩn']::TEXT[], 82, '2026-07-22', NULL, 'US: R', 6.5, 'ended'),
  ('f3781c9b-521c-5b83-bc51-059b7f08a408'::UUID, 1813355, 'A Story of Derry', 'A Story of Derry', 'Hundreds of years before Pennywise, three youngsters venture into the Western Wood...where they encounter a terrifying ancient spirit.', 'Hundreds of years before Pennywise, three youngsters venture into the Western Wood...where they encounter a terrifying ancient spirit.', 'https://image.tmdb.org/t/p/w780/q2XCoT6AqBANz0mKmkgVeo4PyRQ.jpg', 'https://image.tmdb.org/t/p/w1280/z26LxXDMmAIzKr06FPDudCJyvsM.jpg', 'https://www.youtube.com/watch?v=iOjzJsHS0M0', 'Tazbah Chavez', ARRAY['Kiawentiio', 'Isabel DeRoy-Olson', 'Michael Podemski', 'Zahn McClarnon', 'MorningStar Angeline', 'Brandon Oakes', 'Jennifer Podemski', 'Kimberly Guerrero']::TEXT[], ARRAY['Chính Kịch', 'Kinh Dị', 'Bí Ẩn']::TEXT[], 30, '2026-10-31', NULL, 'US: R', 6.8, 'ended'),
  ('bbf3128d-a903-5323-85c5-2e417e6b176f'::UUID, 1571955, 'Colisión', 'Colisión', 'Spain, 2013. After robbing a bank, a getaway crash reveals the hidden side of each thief, exposing betrayals and lies that began long before the heist.', 'Spain, 2013. After robbing a bank, a getaway crash reveals the hidden side of each thief, exposing betrayals and lies that began long before the heist.', 'https://image.tmdb.org/t/p/w780/sMPIiaOoyTr5o6s602KIVMJX3P2.jpg', 'https://image.tmdb.org/t/p/w1280/uI3kWI7kGW5E0F8WduewgQYPt34.jpg', 'https://www.youtube.com/watch?v=8hVLhaK619k', 'Daniel Sánchez Arévalo', ARRAY['Laia Costa', 'Karra Elejalde', 'Luis Zahera', 'Tamar Novas', 'Álvaro Cervantes', 'Lluís Homar', 'Luz Valdenebro', 'Víctor Duplá']::TEXT[], ARRAY['Giật Gân', 'Chính Kịch', 'Tội Phạm']::TEXT[], 122, '2026-10-30', NULL, 'US: R', 6.9, 'ended'),
  ('d34f910e-edc5-5afe-af75-bf831de77e50'::UUID, 1294189, 'Cầy mangut', 'The Mongoose', 'Một anh hùng chiến tranh bị buộc tội sai và không còn gì để mất đã dẫn cảnh sát vào một cuộc rượt đuổi bằng ô tô xuyên quốc gia trên truyền hình hoành tráng, được các thành viên trong tiểu đoàn Quân đội Lực lượng Đặc biệt cũ của anh ta giúp đỡ và được theo dõi chặt chẽ bởi một cộng đồng mê mẩn tìm kiếm nơi nghỉ ngơi an toàn cho anh ta.', 'A falsely accused war hero with nothing to lose leads police on an epic televised cross-country car chase, helped by members of his former Special Forces Army battalion and closely monitored by a fascinated public rooting for his safe getaway.', 'https://image.tmdb.org/t/p/w780/eSS5mvSG84UUuvtbHel5Yu3Wik4.jpg', 'https://image.tmdb.org/t/p/w1280/iRIhPqqoUHiFBxn8oYf3gCQnaKk.jpg', 'https://www.youtube.com/watch?v=aHrMFtt40_Q', 'Mark Vanselow', ARRAY['Liam Neeson', 'Marisa Tomei', 'Ving Rhames', 'Marcus Thomas', 'Michael Chiklis', 'Maurice Marvel Meredith', 'Brett Tucker', 'Ryan Morgan']::TEXT[], ARRAY['Hành Động', 'Giật Gân']::TEXT[], 99, '2026-10-29', NULL, 'US: R', 7.5, 'ended'),
  ('6f257d55-b5ba-5669-ae1a-55d92496cfc7'::UUID, 1148365, 'Matchbox Phim Điện Ảnh - Matchbox the Movie', 'Matchbox the Movie', 'Cuộc hội ngộ của một nhóm bạn thuở nhỏ bỗng rẽ vào một bước ngoặt bất ngờ khi cả bọn rơi vào một âm mưu quốc tế nguy hiểm và phải đứng lên cứu thế giới.', 'When a group of former childhood friends reconnect, their reunion takes a wild turn as they stumble upon a dangerous international plot—and must save the world.', 'https://image.tmdb.org/t/p/w780/l6Pp3m0L3kOaSyjkjUgl93C0IJg.jpg', 'https://image.tmdb.org/t/p/w1280/jdJsnhHfkIi3J7jwfiCFT4gXNx5.jpg', 'https://www.youtube.com/watch?v=7xfqITrMDcI', 'Sam Hargrave', ARRAY['John Cena', 'Jessica Biel', 'Arturo Castro', 'Sam Richardson', 'Teyonah Parris', 'Danai Gurira', 'گلشیفته فراهانی', 'Corey Stoll']::TEXT[], ARRAY['Hành Động', 'Hài', 'Phiêu Lưu']::TEXT[], 127, '2026-10-05', NULL, 'US: PG-13', 7.6, 'ended'),
  ('1c695dad-8a51-513e-8693-5f39c9aeba1d'::UUID, 1228834, 'Phi Vụ Sửa Sai', 'The Fix', 'Sau một nhiệm vụ giải cứu thất bại ở Afghanistan, một nhóm cựu đặc vụ CIA mang trong mình cảm giác tội lỗi và thất bại. Khi người chỉ huy Larry tiết lộ bí mật về 25 triệu USD được cất giấu tại Tehran, Tucker tập hợp cả nhóm trở lại Iran, vừa nhằm kiếm một khoản tiền khổng lồ, vừa tìm cách chuộc lại những sai lầm trong quá khứ. Nhưng nhiệm vụ nhanh chóng biến thành một cuộc giải cứu nguy hiểm với những âm mưu, phản bội và bí mật tình báo bị che giấu suốt nhiều năm.', 'Disillusioned by the end of the war in Afghanistan, a group of disgraced, war-torn ex-CIA operatives set out to Tehran to take down a life-changing score.', 'https://image.tmdb.org/t/p/w780/jlP8XDjZN89GrpM3je5Uf8Grqx8.jpg', 'https://image.tmdb.org/t/p/w1280/dJTWIecL2vxsCRl5G0lRhPsfrhc.jpg', 'https://www.youtube.com/watch?v=l5Luvr9TRRc', 'Guy Moshe', ARRAY['Zachary Levi', 'Liam Neeson', 'Wes Chatham', 'Titus Welliver', 'Navid Negahban', 'Annet Mahendru', 'Grant Harvey', 'Augusto Aguilera']::TEXT[], ARRAY['Hành Động', 'Giật Gân']::TEXT[], 142, '2026-09-10', NULL, 'US: R', 6.1, 'ended'),
  ('4eb5c44e-dcdb-5224-a376-1eaf739da241'::UUID, 1465063, 'Hòn Đảo Quên Lãng', 'Forgotten Island', 'Trong đêm cuối cùng bên nhau, Jo và Raissa tình cờ phát hiện một cánh cổng bí ẩn đưa họ đến hòn đảo kỳ ảo Nakali – nơi tràn ngập những sinh vật thần thoại và phép thuật mà họ từng được nghe kể từ gia đình người Philippines của mình. Tại đây, có những sinh vật trở thành bạn đồng hành, nhưng cũng có những kẻ là mối đe dọa. Đồng hành cùng chú chó sói vụng về nhưng tốt bụng Raww và một nhóm bạn nhỏ nhưng “có võ”, Jo và Raissa phải đối mặt với The Dreaded Manananggal, sinh vật đáng sợ nhất trên đảo. Khi phát hiện rằng cái giá để trở về nhà chính là toàn bộ ký ức về tình bạn của mình, Jo và Raissa buộc phải chạy đua với thời gian để tìm cách rời khỏi hòn đảo trước khi họ quên mất nhau mãi mãi.', 'While celebrating their last night together, high school graduates and best friends Jo and Raissa stumble upon a mysterious portal that transports them to the fantastical island of Nakali. When they discover that the memories of their entire friendship are the price for returning home, Jo and Raissa must race to find a way to leave the island before they forget each other forever.', 'https://image.tmdb.org/t/p/w780/qgWcLlSXt8dWFjX4z01dUzXOkmt.jpg', 'https://image.tmdb.org/t/p/w1280/cNICUho5uiAGkfCAQq1ihyaMla4.jpg', 'https://www.youtube.com/watch?v=PhgY8cOJiQA', 'Januel Mercado', ARRAY['H.E.R.', 'Liza Soberano', 'Dave Franco', 'Jenny Slate', 'Manny Jacinto', 'Lea Salonga', 'Dolly de Leon', 'Jo Koy']::TEXT[], ARRAY['Hoạt Hình', 'Phiêu Lưu', 'Giả Tưởng', 'Hài', 'Gia Đình']::TEXT[], 109, '2026-09-10', NULL, 'US: PG', 8, 'ended'),
  ('add796a6-725b-5e67-8614-fab45b1bc2c2'::UUID, 1376400, 'Crawlers', 'Crawlers', 'Tenants at Paradiso Palms apartments fight a deadly spider invasion while the cunning building manager might be their only hope for survival.', 'Tenants at Paradiso Palms apartments fight a deadly spider invasion while the cunning building manager might be their only hope for survival.', 'https://image.tmdb.org/t/p/w780/lNXeEpg4yLSRwXwOeR5lbPgwbqL.jpg', 'https://image.tmdb.org/t/p/w1280/ayJsUQ4bEG6yY0UB6lMboiaDfYE.jpg', 'https://www.youtube.com/watch?v=4DowjB87tRE', 'Ángel Gómez Hernández', ARRAY['Matilda Lutz', 'Gary Anthony Stennette', 'Elena Sanz', 'Andrea Scott Méndez', 'Isabella Marie Egizi', 'Sam Lucas Smith', 'Gregg Sulkin', 'Melina Matthews']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân']::TEXT[], 80, '2026-09-24', NULL, 'US: R', 6.2, 'ended'),
  ('9005172e-8020-5151-b073-cd0d575f98d2'::UUID, 1727734, 'Ali G: Who Iz I?', 'Ali G: Who Iz I?', 'After twenty years spent "chillin'', tokin'' and bonin''", Ali G is shocked to discover that his long-term girlfriend, Julie, is 8 months pregnant. Faced with an extra mouth to feed, he gets off his batty and heads to America to reclaim his former glory… but soon encounters adversaries who will ultimately threaten his and his child''s very existence.', 'After twenty years spent "chillin'', tokin'' and bonin''", Ali G is shocked to discover that his long-term girlfriend, Julie, is 8 months pregnant. Faced with an extra mouth to feed, he gets off his batty and heads to America to reclaim his former glory… but soon encounters adversaries who will ultimately threaten his and his child''s very existence.', 'https://image.tmdb.org/t/p/w780/uTyVxPeWX8Ai30IQoyDDQONNcq.jpg', 'https://image.tmdb.org/t/p/w1280/hJcGJLi34zE4RhzsiDR6f7pw50K.jpg', 'https://www.youtube.com/watch?v=pV32AcPa-iA', 'Sacha Baron Cohen', ARRAY['Sacha Baron Cohen', 'Morgana Robinson', 'Alpha Miknas', 'Clive Russell', 'A$AP Rocky', 'Rihanna', 'Tiffany Haddish', 'DJ Jazzy Jeff']::TEXT[], ARRAY['Hài']::TEXT[], 89, '2026-10-22', NULL, 'US: R', 5.8, 'ended'),
  ('4af7777e-b154-518e-ad6a-5f843e7564b0'::UUID, 1453407, 'ग़ज़ब रात', 'ग़ज़ब रात', 'A corrupt, troubled cop''s night spirals out of control when a reluctant act of mercy toward an injured girl pulls him into a deadly web of crime.', 'A corrupt, troubled cop''s night spirals out of control when a reluctant act of mercy toward an injured girl pulls him into a deadly web of crime.', 'https://image.tmdb.org/t/p/w780/e4N7M52cBbyi24xLga8yI6yt1u1.jpg', 'https://image.tmdb.org/t/p/w1280/8I4YFWgi9IZW4VUi398A0BqLnm.jpg', 'https://www.youtube.com/watch?v=BwFuJbHNE4o', 'Ritesh Shah', ARRAY['मनोज बाजपेयी', 'Divya Dutta', 'Akshay Oberoi', 'Saqib Saleem', 'Shraddha Das', 'Rajiv Gupta', 'Aditi Sandhya Sharma', 'Nushrratt Bharuccha']::TEXT[], ARRAY['Giật Gân', 'Tội Phạm']::TEXT[], 124, '2026-10-23', NULL, 'US: R', 5.3, 'ended'),
  ('ab012d51-db60-5138-a2b4-d7bee4e0bc9d'::UUID, 1423191, 'Vùng Đất Quỷ Dữ', 'Resident Evil', 'Medical courier Bryan unwittingly finds himself fighting for survival as one fateful, horrifying night collapses around him in chaos.', 'Medical courier Bryan unwittingly finds himself fighting for survival as one fateful, horrifying night collapses around him in chaos.', 'https://image.tmdb.org/t/p/w780/jlFMvLuzjwt7aI1QVtiNVnFHNBe.jpg', 'https://image.tmdb.org/t/p/w1280/3icyRAqgakNcQn6aDVz9libFmBA.jpg', 'https://www.youtube.com/watch?v=2flaT7JNc-U', 'Zach Cregger', ARRAY['Austin Abrams', 'Paul Walter Hauser', 'Kali Reis', 'Zach Cherry', 'Johnno Wilson', 'Shaun W. Loeser', 'Zach Cregger', 'Emily Piggford']::TEXT[], ARRAY['Kinh Dị', 'Khoa Học Viễn Tưởng', 'Phiêu Lưu']::TEXT[], 95, '2026-09-16', NULL, 'US: R', 7.3, 'ended'),
  ('78945ecc-7d47-56cf-8360-b5042280e7e3'::UUID, 1780005, 'Contra el huracán', 'Contra el huracán', 'Two estranged brothers struggle to survive Hurricane Otis in Acapulco, where their bond and courage turn adversity into hope.', 'Two estranged brothers struggle to survive Hurricane Otis in Acapulco, where their bond and courage turn adversity into hope.', 'https://image.tmdb.org/t/p/w780/lFaMt4I8LiQAGW9Rb5gfGFXbvOY.jpg', 'https://image.tmdb.org/t/p/w1280/cpNMIRCrDl0sxDL1tHBzfWi0UZC.jpg', 'https://www.youtube.com/watch?v=qC0HZLUXRXw', 'Jorge Michel Grau', ARRAY['Benny Emmanuel', 'Kristyan Ferrer', 'Mónica del Carmen', 'Mónica Jiménez', 'Andrew Leland Rogers', 'Gonzalo Vega Jr.', 'Daira Mendoza']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 97, '2026-10-23', NULL, 'US: R', 7.6, 'ended'),
  ('eb24edfa-c5c5-5b05-a6e6-2f3ce9f46117'::UUID, 1204680, 'Coyote vs. Acme', 'Coyote vs. Acme', 'Sau quá nhiều lần thất bại vì những món hàng lỗi của công ty Acme trong cuộc săn đuổi không ngừng nghỉ chú chim Roadrunner, Wile E. Coyote quyết định thuê một luật sư… từ biển quảng cáo, để kiện tập đoàn Acme ra tòa.', 'After Acme products fail him one too many times in his dogged pursuit of the Roadrunner, Wile E. Coyote decides to hire a billboard lawyer to sue the Acme Corporation.', 'https://image.tmdb.org/t/p/w780/kYDCl2y0VPvhT5eYWbMRInPoB03.jpg', 'https://image.tmdb.org/t/p/w1280/rueyXwlewVPAP5NkqCUJx4RjhqB.jpg', 'https://www.youtube.com/watch?v=kMsiD1Nky5I', 'Dave Green', ARRAY['Will Forte', 'Trần Đồng Lan', 'John Cena', 'Tone Bell', 'Martha Kelly', 'Luis Guzmán', 'P.J. Byrne', 'John Early']::TEXT[], ARRAY['Hài', 'Phiêu Lưu', 'Gia Đình', 'Hoạt Hình']::TEXT[], 103, '2026-08-20', NULL, 'US: PG', 8.2, 'ended'),
  ('0234edff-4fac-56b5-883e-baedd3e9a0d1'::UUID, 1561726, 'Masterplan', 'Masterplan', 'When a legendary thief sets his sights on the Mona Lisa, he recruits two young strangers to help him before revealing they are long-lost siblings… and oh yes, by the way, he is their father. Thrown into a chaotic reunion they never asked for, this new family must learn to work together — and try not to kill each other — if they want any chance at pulling off the heist of the century.', 'When a legendary thief sets his sights on the Mona Lisa, he recruits two young strangers to help him before revealing they are long-lost siblings… and oh yes, by the way, he is their father. Thrown into a chaotic reunion they never asked for, this new family must learn to work together — and try not to kill each other — if they want any chance at pulling off the heist of the century.', 'https://image.tmdb.org/t/p/w780/5xmXVd7nCK3tAo34XkO58SxUCip.jpg', 'https://image.tmdb.org/t/p/w1280/fAlQZsCOCvxOj0PmFmt4i8IWR2u.jpg', 'https://www.youtube.com/watch?v=gc0t8AfMP6k', 'Thomas Vincent', ARRAY['Stanley Tucci', 'Simona Tabasco', 'Victor Belmondo', 'Eliott Margueron', 'Barbara Lo Gaglio', 'Etienne Guillou-Kervern', 'Srbo Markovic', 'Julia Messina']::TEXT[], ARRAY['Hành Động', 'Giật Gân']::TEXT[], 110, '2026-10-16', NULL, 'US: R', 6.9, 'ended'),
  ('2f06d12c-cead-54b2-9b46-1218cfb863ae'::UUID, 1236045, 'Bản năng thú', 'Animals', 'Khi con trai họ bị bắt cóc, một ứng viên thị trưởng Los Angeles và vợ cuống cuồng xoay xở tiền chuộc, đồng thời phải đưa ra những lựa chọn có thể phá tan thế giới của họ.', 'When the son of an L.A. mayoral candidate is kidnapped, he and his wife have a few hours to come up with the ransom payment. With most of their money spent on his political campaign, they have to get their hands dirty and expose a side of their lives they never intended to see the light of day.', 'https://image.tmdb.org/t/p/w780/iISM36voS1E8gX9BM0DVK0kgi3E.jpg', 'https://image.tmdb.org/t/p/w1280/tzoarEu7TsG959upiELyYPm5kO9.jpg', 'https://www.youtube.com/watch?v=ZkN2M4ODdys', 'Ben Affleck', ARRAY['Ben Affleck', 'Kerry Washington', 'Gillian Anderson', 'Steven Yeun', 'Adriana Paz', 'Luis Gerardo Méndez', 'Christopher Woodley', 'Jacob Estrada']::TEXT[], ARRAY['Giật Gân', 'Chính Kịch', 'Hành Động', 'Tội Phạm']::TEXT[], 109, '2026-10-09', NULL, 'US: R', 7, 'ended'),
  ('81a58106-d5a8-56da-91e7-fbce324dba3c'::UUID, 1290418, 'Vòng Tội Lỗi', 'The Cycle', 'Một người con gái bóc tách những góc khuất đen tối của người cha quá cố, sau khi thi thể của ông – người đã mất tích bí ẩn suốt 36 năm – đột ngột được tìm thấy tại một hiện trường vụ án mạng kinh hoàng.', 'A daughter unravels her father''s dark past after his body, missing for 36 years, is found at a horrific crime scene.', 'https://image.tmdb.org/t/p/w780/n5gSNf55KWfDc9hqP4H1KCCSutE.jpg', 'https://image.tmdb.org/t/p/w1280/bgHW6AJl2SdKzxglvf9tshXbI84.jpg', 'https://www.youtube.com/watch?v=m8vcBN8uza8', 'Jordan Downey', ARRAY['Deborah Ann Woll', 'Jeffrey Donovan', 'Gretchen Corbett', 'Jack Doolan', 'Will Hochman', 'Dana Millican', 'Phillip Andre Botello', 'Don Keith Opper']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân', 'Bí Ẩn']::TEXT[], 111, '2026-09-24', NULL, 'US: R', 6.8, 'ended'),
  ('9ed03c57-e9f1-56da-b277-45903375b398'::UUID, 1288445, 'Tàu Buôn Người', 'Mutiny', 'Sau khi chứng kiến ​​vụ sát hại người chủ tỷ phú của mình và bị gán tội oan, Cole Reed lên một con tàu chở hàng để đơn độc thực hiện hành trình báo thù, nhưng rồi lại phát hiện ra một âm mưu mang tầm quốc tế.', 'After witnessing his billionaire boss'' murder and being framed for the crime, Cole Reed boards a cargo ship on a one-man crusade to avenge his boss'' death only to discover an international conspiracy.', 'https://image.tmdb.org/t/p/w780/nDcgl5K2MCZk3xK3bh383CmIZsS.jpg', 'https://image.tmdb.org/t/p/w1280/e2QAGrEmbpmZpMymDRkDisJkvg9.jpg', 'https://www.youtube.com/watch?v=2Iqvbe98Gb4', 'Jean-François Richet', ARRAY['Jason Statham', 'Annabelle Wallis', 'Roland Møller', 'Ramon Tikaram', 'Arnas Fedaravičius', 'Jason Wong', 'Adrian Lester', 'Chaneil Kular']::TEXT[], ARRAY['Hành Động', 'Giật Gân']::TEXT[], 95, '2026-08-19', NULL, 'US: R', 7.7, 'ended'),
  ('cf803b6d-122e-53b8-a4ec-97869f46b21e'::UUID, 1765072, 'You Can See Everything', 'You Can See Everything', 'Từng được tung hô với tham vọng thay đổi thế giới công nghệ, nữ founder này lại trở thành tâm điểm của một vụ lừa đảo đình đám khiến cả thế giới chấn động. Đằng sau lời hứa táo bạo và hình ảnh hào nhoáng ấy che giấu sự thật gì?', 'Thirty-four days before she''s sent to prison, notorious Silicon Valley founder Elizabeth Holmes invites a skeptical film crew to document her every move. What begins as an intimate portrait of an enigmatic felon becomes a mind-bending three-year journey into the abyss.', 'https://image.tmdb.org/t/p/w780/8xQlSsMpikHi0WINkqNOgx8kuaZ.jpg', 'https://image.tmdb.org/t/p/w1280/nhIL3O4W9h5V5JbNQm7yjoDk3So.jpg', 'https://www.youtube.com/watch?v=IEx8D1Wb__U', 'Nathan Fielder', ARRAY['Elizabeth Holmes', 'Nathan Fielder', 'Billy Evans', 'Amanda Seyfried', 'Christopher Abbott', 'Lance Oppenheim', 'Christian Rasmus Holmes IV', 'Noel Anne']::TEXT[], ARRAY['Phim Tài Liệu']::TEXT[], 174, '2026-10-16', NULL, 'US: R', 8.9, 'ended'),
  ('36ec7634-2ad7-579d-a435-c18b6fe18c1a'::UUID, 1629051, 'ネバーアフターダーク', 'ネバーアフターダーク', 'A traveling psychic who helps lost souls cross over encounters a powerful entity at a remote house. While investigating its origins, she uncovers dark secrets and faces a deadly threat from an unexpected source.', 'A traveling psychic who helps lost souls cross over encounters a powerful entity at a remote house. While investigating its origins, she uncovers dark secrets and faces a deadly threat from an unexpected source.', 'https://image.tmdb.org/t/p/w780/4rDgzOCBREeTaqZvTeFtEcnrju8.jpg', 'https://image.tmdb.org/t/p/w1280/o73vpmtXq89bfSUMcAulLVN4TKP.jpg', 'https://www.youtube.com/watch?v=fu33xTw654A', 'Dave Boyle', ARRAY['穂志もえか', '稲垣来泉', 'Kaku Kento', '木村多江', '吉岡睦雄', '正名僕蔵']::TEXT[], ARRAY['Kinh Dị']::TEXT[], 104, '2026-06-05', NULL, 'GB: 15', 7.5, 'ended'),
  ('3c7ceae7-7ed7-5c8c-9eae-7f3fd5ea5600'::UUID, 1503762, 'Sense and Sensibility', 'Sense and Sensibility', 'A charming, witty, and deeply relatable story of love and sisterhood.', 'A charming, witty, and deeply relatable story of love and sisterhood.', 'https://image.tmdb.org/t/p/w780/czsyPHosFNbh4PPqXfqWu1aBXnA.jpg', 'https://image.tmdb.org/t/p/w1280/tIcONOFK9D3F89ETK8DBS1hIwVF.jpg', 'https://www.youtube.com/watch?v=OFLyW0lxFU0', 'Georgia Oakley', ARRAY['Daisy Edgar-Jones', 'Esmé Creed-Miles', 'Caitríona Balfe', 'Frank Dillane', 'Herbert Nordrum', 'George MacKay', 'Fiona Shaw', 'Bodhi Rae Breathnach']::TEXT[], ARRAY['Lãng Mạn', 'Chính Kịch', 'Lịch Sử']::TEXT[], 132, '2026-09-23', NULL, 'US: PG', 7.3, 'ended'),
  ('d037d1d1-fc69-5dac-ab1f-4490fd3bc8af'::UUID, 1377237, 'Runner', 'Runner', 'A former soldier is thrown into a brutal race against time when a critical medical delivery makes him and his unlikely partner the targets of a ruthless cartel. As the mission spirals into a deadly manhunt, every detour, delay, and bullet pushes them closer to failure. With betrayal closing in from every side, they must survive the chase and deliver their cargo to save the life of a little girl.', 'A former soldier is thrown into a brutal race against time when a critical medical delivery makes him and his unlikely partner the targets of a ruthless cartel. As the mission spirals into a deadly manhunt, every detour, delay, and bullet pushes them closer to failure. With betrayal closing in from every side, they must survive the chase and deliver their cargo to save the life of a little girl.', 'https://image.tmdb.org/t/p/w780/vJk2TW1QZAmBiD7oj9ZF9EPTYY1.jpg', 'https://image.tmdb.org/t/p/w1280/npXZNWjOEYrqdMDPQ11SGBrXqAG.jpg', 'https://www.youtube.com/watch?v=B6Z9MM1LhEA', 'Scott Waugh', ARRAY['Alan Ritchson', 'Owen Wilson', 'Rodrigo Santoro', 'Leila George', 'Kate Box', 'Peta Sergeant', 'Cecilia Toussaint', 'Geraldine Hakewill']::TEXT[], ARRAY['Hành Động', 'Hài']::TEXT[], 97, '2026-09-07', NULL, 'US: PG-13', 8.3, 'ended'),
  ('32aa7e98-eb05-5ba6-9fd4-b0690c92a955'::UUID, 1422041, 'La bola negra', 'La bola negra', 'The intertwined lives of three men in three different eras, three lives intimately linked by sexuality and desire, pain, and legacy.', 'The intertwined lives of three men in three different eras, three lives intimately linked by sexuality and desire, pain, and legacy.', 'https://image.tmdb.org/t/p/w780/t1azKLExwUxKj6v6m2L535evuRa.jpg', 'https://image.tmdb.org/t/p/w1280/bDsmYvrzto7xrEwqDpLC3SPhn9A.jpg', 'https://www.youtube.com/watch?v=lBVxKt0gKDY', 'Javier Ambrossi', ARRAY['Guitarricadelafuente', 'Miguel Bernardeau', 'Carlos González', 'Milo Quifes', 'Lola Dueñas', 'Penélope Cruz', 'Glenn Close', 'Antonio de la Torre']::TEXT[], ARRAY['Chính Kịch', 'Chiến Tranh']::TEXT[], 159, '2026-09-25', NULL, 'US: R', 8.1, 'ended'),
  ('a684d577-0a2a-59af-bfbe-325f5f81eaad'::UUID, 1400837, 'Người Mẹ Khác', 'Other Mommy', 'Một cô bé cùng gia đình và ngôi nhà của mình bị ám bởi một thực thể tà ác, kẻ quyết tâm chiếm lấy thân xác cô để trú ngụ vĩnh viễn. Nhưng trước hết, nó cần thuyết phục cô bé tự nguyện mở cửa — và cho phép nó bước vào.', 'Young Bela forms a relationship with a sinister entity in her home that looks uncannily like her own mother, drawing her into a terrifying and increasingly dark world.', 'https://image.tmdb.org/t/p/w780/nZYi7HeXJVfJmZ0kprb1cJBHN2g.jpg', 'https://image.tmdb.org/t/p/w1280/ncm7djsVTHQQMX2HEbEVxMUFchG.jpg', 'https://www.youtube.com/watch?v=-mnTITqqiT0', 'Rob Savage', ARRAY['Jessica Chastain', 'Jay Duplass', 'Arabella Olivia Clark', 'Karen Allen', 'Arian Moayed', 'Dichen Lachman', 'Sean Kaufman', 'Adam Silver']::TEXT[], ARRAY['Kinh Dị']::TEXT[], 93, '2026-10-07', NULL, 'US: R', 5.8, 'ended'),
  ('e9d0f72d-80fc-5555-a3e3-e52fa499864e'::UUID, 1187326, 'Tadeo Jones y La Lámpara Maravillosa', 'Tadeo Jones y La Lámpara Maravillosa', 'Tadeo, his girlfriend Sara, and his friends Momia, Jeff, and Belzoni embark on an adventure after Tadeo accidentally unleashes an ancient spell.', 'Tadeo, his girlfriend Sara, and his friends Momia, Jeff, and Belzoni embark on an adventure after Tadeo accidentally unleashes an ancient spell.', 'https://image.tmdb.org/t/p/w780/71G1b8bqa7gzP9yU7q2fgNf2t0D.jpg', 'https://image.tmdb.org/t/p/w1280/zbpimMxf6Ms96v3Zypuv8WltMSO.jpg', 'https://www.youtube.com/watch?v=8-Bjo_rXCkM', 'Enrique Gato', ARRAY['Óscar Barberán', 'Michelle Jenner', 'Luis Posada', 'Joseph Balderrama', 'Trevor White']::TEXT[], ARRAY['Hoạt Hình', 'Hài', 'Gia Đình']::TEXT[], 94, '2026-08-26', NULL, 'DE: 6', 8.2, 'ended'),
  ('36480c34-d3eb-54b3-be6c-e2431489cc0b'::UUID, 1275779, 'Thời Khắc Công Bố', 'Disclosure Day', 'Nếu một ngày bạn nhận ra rằng chúng ta chưa bao giờ đơn độc, nếu có ai đó đứng trước mặt bạn và chứng minh điều đó là sự thật, liệu việc đó khiến bạn sợ hãi? Mùa Hè 2026, sự thật nằm trong tay của bảy tỷ con người. Chúng ta đang tiến rất gần đến… Thời Khắc Công Bố.', 'A cybersecurity expert becomes a whistleblower after uncovering secrets about aliens, putting him on the run from a corporation. Meanwhile, a meteorologist experiencing strange phenomena joins forces with him to prove there''s life beyond our understanding.', 'https://image.tmdb.org/t/p/w780/nI4uPl4E3No8674XnyY8zJpceBS.jpg', 'https://image.tmdb.org/t/p/w1280/1e0KDRYKRPHiVNj8yQKYuU2jVyQ.jpg', 'https://www.youtube.com/watch?v=icDuEHSxE-w', 'Steven Spielberg', ARRAY['Emily Blunt', 'Josh O''Connor', 'Colin Firth', 'Eve Hewson', 'Colman Domingo', 'Wyatt Russell', 'Henry Lloyd-Hughes', 'Elizabeth Marvel']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Giật Gân']::TEXT[], 146, '2026-06-10', NULL, 'US: PG-13', 7.4, 'ended'),
  ('b927ea18-971f-564f-b833-5b48a50010ea'::UUID, 1284046, 'Lằn Ranh Tử Chiến', 'Onslaught', 'Một người mẹ sống trong khu nhà xe phải liều mình bảo vệ gia đình khi một mối hiểm họa thoát ra từ căn cứ quân sự bí mật. Khi lực lượng lính đánh thuê kéo đến để phong tỏa mọi thứ, cuộc chiến sinh tồn của cô nhanh chóng biến thành cuộc đối đầu không lối thoát.', 'When a rogue squad of genetically engineered super soldiers break loose in the desert, a badass Army sniper must unleash hell to protect her young daughter.', 'https://image.tmdb.org/t/p/w780/eAs7G3yFaULpfwfVdGvPo5HmFJS.jpg', 'https://image.tmdb.org/t/p/w1280/pmPXXniQlb4EdYY0gVZO90rf54F.jpg', 'https://www.youtube.com/watch?v=AMLCbpM1fRQ', 'Adam Wingard', ARRAY['Adria Arjona', 'Dan Stevens', 'Eric Wareheim', 'Reginald VelJohnson', 'Michael Biehn', 'Blake Kennedy', 'Alex Pereira', 'Drew Starkey']::TEXT[], ARRAY['Hành Động', 'Giật Gân', 'Kinh Dị']::TEXT[], 92, '2026-09-02', NULL, 'US: R', 5.6, 'ended'),
  ('4c9f09fc-372f-5af7-a61c-80de117574ce'::UUID, 969681, 'Người Nhện: Khởi Đầu Mới', 'Spider-Man: Brand New Day', 'Không còn Tony Stark, MJ hay Ned kề cận, Peter buộc phải đơn thân độc mã đối diện với phe đối đầu bí ẩn. Tuy nhiên, khi áp lực ngày càng gia tăng, nó kích hoạt một sự biến đổi thể chất bất ngờ, đe dọa chính sự tồn tại của anh. Đồng thời, một chuỗi tội phạm bí ẩn mới xuất hiện, kéo theo một trong những mối đe dọa mạnh mẽ nhất mà Spider-Man từng đối mặt.', NULL, 'https://image.tmdb.org/t/p/w780/wqGZVSCUSXE92WH2zyol2REaqT4.jpg', 'https://image.tmdb.org/t/p/w1280/4tjxYg2AbOzzG9G1YuiT2NzYhlH.jpg', 'https://www.youtube.com/watch?v=RKev8MVJViU', 'Destin Daniel Cretton', ARRAY['Tom Holland', 'Sadie Sink', 'Tramell Tillman', 'Zendaya', 'Jacob Batalon', 'Jon Bernthal', 'Mark Ruffalo', 'Florence Pugh']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Hành Động', 'Phiêu Lưu']::TEXT[], 150, '2026-07-29', NULL, 'US: PG-13', 8.5, 'ended'),
  ('f2809f17-c907-5ff7-b393-8bd8ca247eda'::UUID, 1368337, 'The Odyssey', 'The Odyssey', 'Câu chuyện theo chân Odysseus trong hành trình kéo dài 10 năm trở về nhà sau cuộc chiến thành Troy, nơi ông phải đối mặt với các vị thần, quái vật và vô vàn thử thách, đồng thời nỗ lực đoàn tụ với vợ và giành lại vương quốc của mình.', NULL, 'https://image.tmdb.org/t/p/w780/7876PK6gosE13Uq1B6nRxf7AJLT.jpg', 'https://image.tmdb.org/t/p/w1280/iDiTY1wA35YWzTmXLTtqaxtN6tc.jpg', 'https://www.youtube.com/watch?v=o4s236zGkMM', 'Christopher Nolan', ARRAY['Matt Damon', 'Tom Holland', 'Anne Hathaway', 'Robert Pattinson', 'Himesh Patel', 'Charlize Theron', 'John Leguizamo', 'Travis Scott']::TEXT[], ARRAY['Phiêu Lưu', 'Hành Động', 'Giả Tưởng']::TEXT[], 173, '2026-07-15', NULL, 'US: R', 8, 'ended'),
  ('50c8634a-500c-5277-b81c-704d30438fd0'::UUID, 1384216, 'Chòm Sao Bất Diệt', 'The Dog Stars', 'Sau một đại dịch chết chóc, những người sống sót vẫn cố níu kéo những giá trị xưa cũ của nhân loại. Nhưng thế giới nay đã không còn như trước...', 'After the world''s population has been ravaged by a pandemic, a man lives a lonesome existence in a Colorado airplane hangar with his dog and a dour gunman he has befriended. When a mysterious transmission comes through on the radio while he’s flying his old Cessna, it sparks a hunt for the provenance of the sound.', 'https://image.tmdb.org/t/p/w780/3HUEoP7BlFJ97YCtoN05FaYpYgs.jpg', 'https://image.tmdb.org/t/p/w1280/3k7GzxOdLZkN3eZsuhLi2eRzkXO.jpg', 'https://www.youtube.com/watch?v=-xSxaE1ClEE', 'Ridley Scott', ARRAY['Jacob Elordi', 'Josh Brolin', 'Margaret Qualley', 'Guy Pearce', 'Benedict Wong', 'Allison Janney', 'Ewen Bremner', 'Sam Spruell']::TEXT[], ARRAY['Hành Động', 'Giật Gân', 'Khoa Học Viễn Tưởng']::TEXT[], 119, '2026-08-26', NULL, 'US: R', 7.2, 'ended'),
  ('9e1f8986-c7ed-5f9a-aea6-85fbb29893b3'::UUID, 1291595, 'Quỷ Quyệt: Ranh Giới Vô Định', 'Insidious: Out of the Further', 'Ba kẻ rình rập xâm nhập một khu dân cư yên tĩnh và kéo một gia đình mới chuyển đến sang cõi linh hồn. Tại đó, họ phát hiện ra một sự thật kinh hoàng: cõi âm đang dần xâm lấn thế giới thực.', 'Gemma, a young mother raising her daughter in the house she grew up in, discovers she can travel into The Further, where she possesses an ability to bring what lives there back to the real world.', 'https://image.tmdb.org/t/p/w780/u1ZyMm7HcYO1CJwtk28dStDH9Bp.jpg', 'https://image.tmdb.org/t/p/w1280/p40lmrdI4blcAPZQMTPaiy5v5Ym.jpg', 'https://www.youtube.com/watch?v=gXjurDkYnEM', 'Jacob Chase', ARRAY['Amelia Eve', 'Island Austin', 'Brandon Perea', 'Lin Shaye', 'Maisie Richardson-Sellers', 'Sam Spruell', 'Joseph Lopez', 'Robina Beard']::TEXT[], ARRAY['Kinh Dị', 'Giật Gân']::TEXT[], 106, '2026-08-19', NULL, 'US: PG-13', 7.7, 'ended'),
  ('3bb70e2e-2f51-5e1f-a552-0451bcea5a5e'::UUID, 755898, 'Cuộc Chiến Giữa Các Thế Giới', 'War of the Worlds', 'Will Radford — chuyên gia phân tích an ninh mạng hàng đầu của Bộ An ninh Nội địa — chuyên theo dõi các mối đe dọa đến an ninh quốc gia thông qua một chương trình giám sát diện rộng. Nhưng một cuộc tấn công bất ngờ từ một thực thể bí ẩn đã khiến anh bắt đầu nghi ngờ: phải chăng chính phủ đang che giấu điều gì đó… không chỉ với anh mà với toàn thế giới?', 'Will Radford is a top analyst for Homeland Security who tracks potential threats through a mass surveillance program, until one day an attack by an unknown entity leads him to question whether the government is hiding something from him... and from the rest of the world.', 'https://image.tmdb.org/t/p/w780/3e6GQvCA9hguxqfqA75BDvG7Vvp.jpg', 'https://image.tmdb.org/t/p/w1280/iZLqwEwUViJdSkGVjePGhxYzbDb.jpg', 'https://www.youtube.com/watch?v=d9erkpdh5o0', 'Rich Lee', ARRAY['Ice Cube', 'Eva Longoria', 'Clark Gregg', 'Iman Benson', 'Henry Hunter Hall', 'Devon Bostick', 'Andrea Savage', 'Nicole Pulliam']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Giật Gân']::TEXT[], 91, '2025-07-29', NULL, 'US: PG-13', 4, 'ended'),
  ('0e116cbf-2578-59d7-a629-d6f4bb060755'::UUID, 1003596, 'Avengers: Ngày Tận Thế', 'Avengers: Doomsday', 'Avengers: Doomsday theo chân những người hùng được yêu mến đến từ ba vũ trụ khác nhau, khi họ bị cuốn vào một hành trình va chạm sinh tử và phải đối mặt với một mối đe dọa mang tính sống còn chưa từng có trong lịch sử.', NULL, 'https://image.tmdb.org/t/p/w780/2NRUUSow5XBcmFXJta7W5JrfWk7.jpg', 'https://image.tmdb.org/t/p/w1280/rObL4of4eFA8yWaN9pRFo9aOVNi.jpg', 'https://www.youtube.com/watch?v=msxsRECi7F8', 'Joe Russo', ARRAY['Robert Downey Jr.', 'Chris Evans', 'Chris Hemsworth', 'Pedro Pascal', 'Paul Rudd', 'Anthony Mackie', 'Florence Pugh', 'Vanessa Kirby']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Hành Động', 'Phiêu Lưu']::TEXT[], 165, '2026-12-16', NULL, 'AR: +13', 0, 'coming_soon'),
  ('212791c6-74e5-5e70-afe2-a5d3e7f086be'::UUID, 1302904, 'Bùa Yêu: Bí Mật Gia Tộc', 'Practical Magic 2', 'Bùa Yêu: Bí Mật Gia Tộc đưa khán giả đến thế giới phép thuật đầy mê hoặc, nơi những bí ẩn dưới ánh trăng và sức mạnh ma thuật gia truyền vẫn luôn hiện hữu. Lần này, hai chị em nhà Owens phải cùng nhau đối mặt với một lời nguyền đen tối đang đe dọa chia cắt gia đình mãi mãi.', 'The Owens sisters must confront the dark curse that threatens to unravel their family once and for all.', 'https://image.tmdb.org/t/p/w780/fNyixhNFs5iWZ3QXhdT8t8D6lsk.jpg', 'https://image.tmdb.org/t/p/w1280/oIglj0Jy9duG4LnrRUpH8n001Pk.jpg', 'https://www.youtube.com/watch?v=Ho10_4IX1jE', 'Susanne Bier', ARRAY['Sandra Bullock', 'Nicole Kidman', 'Joey King', 'Maisie Williams', 'Xolo Maridueña', 'Lee Pace', 'Dianne Wiest', 'Stockard Channing']::TEXT[], ARRAY['Lãng Mạn', 'Giả Tưởng', 'Hài']::TEXT[], 130, '2026-09-09', NULL, 'US: PG-13', 7.2, 'ended'),
  ('a947555e-a1f2-5bce-9052-9a74078cd684'::UUID, 1712451, 'Resident Dead', 'Resident Dead', 'A man keeping his recently zombified daughter secure in hopes of a cure is tasked with delivering an unknown package through hordes of undead. If he succeeds, he will be given a cure for his daughter. If he fails, or opens the package, they will both be killed.', 'A man keeping his recently zombified daughter secure in hopes of a cure is tasked with delivering an unknown package through hordes of undead. If he succeeds, he will be given a cure for his daughter. If he fails, or opens the package, they will both be killed.', 'https://image.tmdb.org/t/p/w780/qKhMVWwFikSUzOpkhOl35GBLkGH.jpg', 'https://image.tmdb.org/t/p/w1280/yKx5gYrYgakKZuUWAsuFDStBroy.jpg', 'https://www.youtube.com/watch?v=M1vupS1Tzfg', 'Ryan Ebert', ARRAY['John Wells', 'Isabel Ramirez', 'Thandiwe McMillan', 'Hamid-Reza Benjamin Thompson', 'Jarod Brock', 'Sai Piña', 'Chase Breithoff', 'Rob Eubanks']::TEXT[], ARRAY['Kinh Dị']::TEXT[], 89, '2026-09-04', NULL, NULL, 5.5, 'ended'),
  ('c1b04e45-a9c3-5397-914c-448006176327'::UUID, 1084244, 'Câu Chuyện Đồ Chơi 5', 'Toy Story 5', 'Khi Bonnie được tặng chiếc máy tính bảng Lilypad và dần mê mẩn món đồ chơi mới, Buzz, Woody, Jessie cùng cả nhóm bỗng đứng trước nguy cơ bị lãng quên. Để giành lại giờ chơi, họ phải đối đầu với “đối thủ” hiện đại nhất từ trước đến nay: một màn hình nhỏ nhưng có sức hút quá lớn.', 'When Bonnie receives a Lilypad tablet as a gift and becomes obsessed, Buzz, Woody, Jessie and the rest of the gang''s jobs become exponentially harder when they have to go head to head with the all-new threat to playtime.', 'https://image.tmdb.org/t/p/w780/8ZE3s8PN5yRpTidymRWpI0jvs7j.jpg', 'https://image.tmdb.org/t/p/w1280/qjTqY5coNiz6sVtPng40IzltsoN.jpg', 'https://www.youtube.com/watch?v=QftAW9TTmuQ', 'Andrew Stanton', ARRAY['Joan Cusack', 'Tom Hanks', 'Tim Allen', 'Conan O''Brien', 'Scarlett Spears', 'Greta Lee', 'Shelby Rabara', 'Mykal-Michelle Harris']::TEXT[], ARRAY['Hoạt Hình', 'Gia Đình', 'Hài', 'Phiêu Lưu']::TEXT[], 102, '2026-06-17', NULL, 'US: PG', 8.3, 'ended'),
  ('b4607ad0-7643-5320-9f00-3272181aa1ff'::UUID, 1108427, 'Hành Trình Của Moana', 'Moana', 'Nghe theo tiếng gọi của Đại Dương, Moana dũng cảm rời đảo Motunui, lần đầu vượt qua rạn san hô để khám phá thế giới rộng lớn. Cùng á thần Maui, cô bắt đầu hành trình phiêu lưu đầy kỳ diệu với sứ mệnh mang lại sự thịnh vượng cho quê hương.', 'Teenage Moana answers the Ocean''s call and, for the first time, voyages beyond the reef of her island of Motunui with infamous demigod Maui on an unforgettable journey to restore prosperity to her people.', 'https://image.tmdb.org/t/p/w780/lwqKqiBsGVBtQBZF9ZTunthBCyI.jpg', 'https://image.tmdb.org/t/p/w1280/c6BPbkO5Npt1OdwttAxCFo06wtH.jpg', 'https://www.youtube.com/watch?v=EEz5xbzYPKI', 'Thomas Kail', ARRAY['Catherine Lagaʻaia', 'Dwayne Johnson', 'Rena Owen', 'John Tui', 'Frankie Adams', 'Jemaine Clement', 'Emma Puahi-Shapazian', 'Amaya Masoli']::TEXT[], ARRAY['Gia Đình', 'Giả Tưởng', 'Hài', 'Phiêu Lưu']::TEXT[], 115, '2026-07-08', NULL, 'US: PG', 7.5, 'ended'),
  ('a8eec9a9-40d9-564d-aca2-5af8b027c64b'::UUID, 687163, 'Thoát Khỏi Tận Thế', 'Project Hail Mary', 'Mất trí nhớ và lạc lõng trên một con tàu vũ trụ, một phi hành gia khám phá ra rằng anh là hy vọng duy nhất của nhân loại trước bờ vực tuyệt chủng. Một liên minh bất ngờ được hình thành, nắm giữ vận mệnh của tất cả.', NULL, 'https://image.tmdb.org/t/p/w780/7NzV9SN5ocWzMrdQw9fFDgLYVJC.jpg', 'https://image.tmdb.org/t/p/w1280/8Tfys3mDZVp4tNoH2ktm06a0Tau.jpg', 'https://www.youtube.com/watch?v=RMnv3zqNWTQ', 'Phil Lord', ARRAY['Ryan Gosling', 'Sandra Hüller', 'James Ortiz', 'Lionel Boyce', 'Milana Vayntrub', 'Ken Leung', 'Priya Kansara', 'Mia Soteriou']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Phiêu Lưu']::TEXT[], 157, '2026-03-15', NULL, 'US: PG-13', 8.6, 'ended'),
  ('21ec7ed4-4919-5654-beac-08c900ec4c83'::UUID, 1101383, 'Ngày Tàn Của Phố Oak', 'The End of Oak Street', 'Sau khi một thảm họa thiên nhiên xé toạc Phố Oak khỏi khu ngoại ô và đưa con phố đến một nơi xa lạ, gia đình Platt nhanh chóng nhận ra rằng chỉ bằng cách luôn đứng bên nhau, họ mới có thể vượt qua vận mệnh nghiệt ngã này.', NULL, 'https://image.tmdb.org/t/p/w780/fprITg7E3v7Hj9wGKmCXCBVLSHq.jpg', 'https://image.tmdb.org/t/p/w1280/b9q9VmbXDvJmTziRqkwdEmFdwhr.jpg', 'https://www.youtube.com/watch?v=GdgB7z32w5U', 'David Robert Mitchell', ARRAY['Anne Hathaway', 'Ewan McGregor', 'Maisy Stella', 'Christian Convery', 'Jordan Alexa Davis', 'P.J. Byrne', 'Hudson Meek', 'Anne Gee Byrd']::TEXT[], ARRAY['Khoa Học Viễn Tưởng', 'Bí Ẩn', 'Giật Gân']::TEXT[], 100, '2026-08-12', NULL, 'US: PG-13', 7.1, 'ended'),
  ('d29fefe6-1414-5b41-be8f-b1a87003bf0a'::UUID, 1480613, 'La silla', 'La silla', 'Daniel Lonces is a successful horror writer who decides to put himself in his protagonist’s shoes and experience firsthand what it means to be tied and gagged. But a tragic accident leaves his wife dead, him trapped, and his 11-month-old baby defenseless. Desperate, David struggles to free himself while facing unexpected dangers inside and outside his home.', 'Daniel Lonces is a successful horror writer who decides to put himself in his protagonist’s shoes and experience firsthand what it means to be tied and gagged. But a tragic accident leaves his wife dead, him trapped, and his 11-month-old baby defenseless. Desperate, David struggles to free himself while facing unexpected dangers inside and outside his home.', 'https://image.tmdb.org/t/p/w780/9aAABL8r22S1bOSeknfjrODuKME.jpg', 'https://image.tmdb.org/t/p/w1280/l2B2WTUqgePLN6kh9uLCYy63Pyk.jpg', 'https://www.youtube.com/watch?v=0rE2n_tpp-E', 'Angel de la Cruz', ARRAY['Jaime Lorente', 'Christina Ochoa', 'Eva Rufo', 'Rodrigo Poisón', 'Alba de la Fuente', 'Marta Fuenar', 'Estíbaliz Veiga', 'Iñaki Urriza']::TEXT[], ARRAY['Giật Gân', 'Kinh Dị']::TEXT[], 75, '2026-05-29', NULL, 'BR: 14', 7, 'ended'),
  ('4e953ab8-29ef-5944-8edf-bc133a43e486'::UUID, 464003, 'Em Chưa 18', 'Em Chưa 18', 'Câu chuyện bắt đầu với Hoàng, một Tay chơi “chất lầy” bảnh tỏn, thu nhập ngất ngưởng, sống cùng quy luật "không có đêm thứ 2" với bất kỳ cô nàng nào. Định mệnh ập đến khi chàng trai trong mơ của bao người đàn ông gặp gỡ Linh Đan. Dĩ nhiên, cả hai đã có mối tình chớp nhoáng và không hề có gì khác biệt với những cô gái trước đây, cho đến khi Hoàng phát hiện ra bạn gái mới của mình chưa đủ 18 tuổi. Từ đây, cả thế giới đào hoa của chàng "lầy gái" số một bất ngờ thu nhỏ lại trong lưới tình của cô học trò xinh đẹp tinh quái.', NULL, 'https://image.tmdb.org/t/p/w780/phXbIGRmNZduZwnBjC0dBZfn8lr.jpg', 'https://image.tmdb.org/t/p/w1280/vo1MUU9liVIsk9dGeZCLyK6JvGR.jpg', 'https://www.youtube.com/watch?v=_affkHceSj4', 'Lê Thanh Sơn', ARRAY['Kaity Nguyễn', 'Kiều Minh Tuấn', 'Will', 'Nguyễn Tiến Dũng', 'Kiều Trinh', 'Châu Bùi', 'Alexandra Nguyễn', 'Võ Ngọc Trai']::TEXT[], ARRAY['Chính Kịch', 'Hài']::TEXT[], 90, '2017-04-28', NULL, NULL, 6.5, 'ended'),
  ('e6798bd8-ddda-51b2-8850-ee57f8476b10'::UUID, 383200, 'Siêu Trộm', 'Siêu Trộm', 'Nội dung phim nói về những mánh khóe trong thế giới tội phạm siêu kỹ thuật, một hacker có tên là Bóng Ma đã tạo ra phần mềm có thể khóa ổ cứng của máy tính và buộc nạn nhân sử dụng phải trả một khoản tiền chuộc bằng những đồng tiền ảo. Đa Đa (Nhung Kate), một trinh sát đặc nhiệm, được chỉ đạo hợp tác với liên đoàn cảnh sát quốc tế Interpol và lực lượng đặc nhiệm Việt để bắt Bóng Ma. Nhưng phải dùng một tên trộm để bắt một tên cướp. Đa Đa bí mật tập hợp một nhóm trộm: một ảo thuật gia (Jack Magic), một bậc thầy về ngụy trang (Luhan), một vận động viên thể thao tí hon (Linh), một hacker (Vy), và một kẻ cung cấp thông tin (Phúc) đã từng làm việc cho Bóng Ma. Tuy nhiên Bóng Ma hacker luôn đi trước một bước. Cuộc săn bắt giữa mèo và chuột xảy ra sau đó với nhiều tình huống bất ngờ lôi cuốn khán giả khám phá ai là Bóng Ma và ai chiếm được những đồng tiền ảo.', 'To catch Interpol''s most-wanted hacker, special Agent Dada must assemble a team of criminals with  various special skillsets.', 'https://image.tmdb.org/t/p/w780/tXxYnMLw0fFVaTPyLyIYW2S2li4.jpg', 'https://image.tmdb.org/t/p/w1280/9z6uqKs5gmiWNUZDWHKnaB4Ky27.jpg', 'https://www.youtube.com/watch?v=3gR9cQLHBSA', 'Hàm Trần', ARRAY['Nhung Kate', 'Huyme', 'Petey Majik Nguyễn', 'Suboi', 'Mai Thế Hiệp', 'Lâm Thanh Mỹ', 'Ngô Thanh Vân', '태오']::TEXT[], ARRAY['Hành Động']::TEXT[], 102, '2016-02-05', NULL, NULL, 7.2, 'ended'),
  ('4b42d406-e4e4-57c0-9639-fb29a2bb7a97'::UUID, 210626, 'Mỹ Nhân Kế', 'Mỹ Nhân Kế', 'Mỹ nhân kế là một bộ phim võ hiệp - cổ trang của Việt Nam do Nguyễn Quang Dũng làm đạo diễn và viết kịch bản. Chuyện phim xoay quanh băng nhóm của Kiều Thị (do Thanh Hằng thủ vai) và các nữ sát thủ trá hình kiều nữ ở Đường Sơn quán: Đào Thị (Ngọc Quyên), Mai Thị (Diễm My 9x) và Liễu Thị (Kim Dung). Họ cướp của người giàu, quan lại tham ô với mong muốn tích góp đủ số tiền để có được cuộc sống như ý.', 'In the remote, shoreline Duong Son Tavern, the beautiful landlady Kieu Thi (Thanh Hang) lures weary travellers, bandits and officials into her establishment with the help of her three stunning hostesses. But rather than sell themselves, the girls rob and murder their guests, hording a growing pile of gold for a rainy day.  In their latest haul, however, the women discover the bound and desperate Linh Lan (Tang Thanh Ha) hidden in a coffin. She begs them to spare her life and train her in martial arts, so she can kill evil general Quan Du, who murdered her family. Kieu Thi agrees, and takes Linh Lan under her wing, but it soon transpires not everyone is who they originally claimed to be.', 'https://image.tmdb.org/t/p/w780/uKJAbzBxBkbkklSxMlTp3PaNnsn.jpg', 'https://image.tmdb.org/t/p/w1280/ow9Z7mr9KL2TVMYfIIYKODCIDgP.jpg', NULL, 'Nguyễn Quang Dũng', ARRAY['Thanh Hằng', 'Lê Thái Hòa', 'Diễm My 9x', 'Ngọc Quyên', 'Tăng Thanh Hà', 'Kim Dung', 'Phạm Anh Khoa']::TEXT[], ARRAY['Hành Động']::TEXT[], 99, '2013-03-13', NULL, 'JP: R15+', 5.5, 'ended'),
  ('077916c9-253a-5cba-9bd0-aeb43aec8e5a'::UUID, 162539, 'Surname Viêt Given Name Nam', 'Surname Viêt Given Name Nam', 'The film evolves around questions of identity, popular memory and culture. While focusing on aspects of Vietnamese reality as seen through the lives and history of women resistance in Vietnam and in the U.S, it raises questions on the politics of interviewing and documenting.', 'The film evolves around questions of identity, popular memory and culture. While focusing on aspects of Vietnamese reality as seen through the lives and history of women resistance in Vietnam and in the U.S, it raises questions on the politics of interviewing and documenting.', 'https://image.tmdb.org/t/p/w780/tlvMUtwV4epz57VvL1nE6JcM2xd.jpg', 'https://image.tmdb.org/t/p/w1280/z8M0lUFo0JHan5jZGFdMDyNIMPQ.jpg', NULL, 'Trịnh T. Minh-hà', ARRAY['Tran Thi Hein', 'Ngo Kim Nhuy', 'Khien Lai', 'Tran Tai Bich Yen', 'Lan Trinh', 'Sue Whitfield']::TEXT[], ARRAY['Phim Tài Liệu', 'Lịch Sử', 'Chiến Tranh']::TEXT[], 108, '1989-04-01', NULL, NULL, 5.5, 'ended'),
  ('4a94a6bf-cba8-5e65-88d8-27b4956804e9'::UUID, 1140135, 'Kẻ Ẩn Danh', 'Kẻ Ẩn Danh', 'Lâm - một người đàn ông từng là xã hội đen nhưng lại mất trí nhớ và nay đang lẩn trốn như một người bình thường, kiếm sống bằng lao động chân tay. Lâm sống cùng vợ - Hạnh và con gái riêng của cô là Hiền. Hiền vẫn chưa chấp nhận tình yêu thương của chú Lâm dành cho mình. Hiền lớn lên với sự bốc đồng và bị dụ dỗ bởi Tiến - một thanh niên đạo đức giả chuyên dụ dỗ những cô gái vào nhà thổ để trở thành gái mại dâm. Xuyên suốt bộ phim là hành trình đi tìm con gái của Lâm', 'Tells the story of Lam - a man who used to be a gangster but lost his memory and now hides like an ordinary person, making a living by manual labor. Lam lives with his wife - Hanh and her stepdaughter Hien. Hien still has not accepted the love of Uncle Lam for her. Hien grew up impulsive and was seduced by Tien - a hypocritical young man who lured girls into brothels to become prostitutes. Throughout the film is the journey to find Lam''s daughter.', 'https://image.tmdb.org/t/p/w780/7D5mmr1Q4rPrSyLMN0AFvnd0tst.jpg', 'https://image.tmdb.org/t/p/w1280/aupEpYEgmL0bQ4ZkqtWB8yDjdXG.jpg', 'https://www.youtube.com/watch?v=9yVmRrrxoOc', 'Trần Trọng Dần', ARRAY['Kiều Minh Tuấn', 'Mạc Văn Khoa', 'Quốc Trường', 'Vân Trang', 'Mai Cát Vi', 'Mạnh Lân', 'Thừa Tuấn Anh', 'Đàm Phương Linh']::TEXT[], ARRAY['Hành Động', 'Chính Kịch', 'Gia Đình', 'Hài']::TEXT[], 98, '2023-08-25', NULL, NULL, 5.9, 'ended'),
  ('a9ce9f92-b96e-59bd-b4f0-43cb5ce5c2ad'::UUID, 786170, 'Thiên Thần Hộ Mệnh', 'Thiên Thần Hộ Mệnh', 'Cái chết của một cô ca sĩ nổi tiếng dẫn đến sự thành công của một cô ca sĩ trẻ khác. Câu chuyện này có liên quan như thế nào đến sự giúp đỡ của một "thiên thần hộ mệnh"?', NULL, 'https://image.tmdb.org/t/p/w780/vHzXJST28rfjrlfnYhdl0ohAWsL.jpg', 'https://image.tmdb.org/t/p/w1280/aO6Xj3tzHxtJqqTgIHIu9KATnOm.jpg', 'https://www.youtube.com/watch?v=mMZhID_KX8k', 'Victor Vũ', ARRAY['Trúc Anh', 'AMEE', 'Salim', 'Samuel An', 'Trọng Trinh', 'Thanh Thủy', 'Thu Vu', 'Tran Le Nguyen']::TEXT[], ARRAY['Giật Gân', 'Chính Kịch', 'Kinh Dị']::TEXT[], 127, '2021-04-30', NULL, 'GB: 18', 7.3, 'ended'),
  ('ca06e006-3196-5801-9a1a-305f11b35b54'::UUID, 483657, 'Linh Duyên: Bí Mật Từ Hình Nhân', 'Linh Duyên: Bí Mật Từ Hình Nhân', 'Linh Duyên có những diễn viên khá quen thuộc như Dustin Nguyễn, Kim Tuyến, Trương Quỳnh Anh, Tim, Sam… Trong đó, Kim Tuyến là cái tên gây được nhiều chú ý khi cũng từng là nữ chính trong dự án kinh dị thành công trước đó là Ngủ Với Hồn Ma (đạo diễn Bá Vũ). Giữ vai trò "xương sống" suốt toàn mạch của bộ phim, Kim Tuyến đã hoàn thành gần như xuất sắc vai diễn của mình. Suốt cả một bộ phim, cảm xúc mà nhân vật Hương của Kim Tuyến thể hiện khá thuyết phục khán giả và tạo được nhiều ấn tượng.', NULL, 'https://image.tmdb.org/t/p/w780/qr6k7puh4cnrPHBi785Bo8YOWia.jpg', 'https://image.tmdb.org/t/p/w1280/ngclwkLdHmSTq9OXlNrDBoyDBlc.jpg', 'https://www.youtube.com/watch?v=F1SKVavQ228', 'Võ Ngọc', ARRAY['Kim Tuyến', 'Dustin Nguyễn', 'Trương Quỳnh Anh', 'Hòa Minzy', 'Tim', 'Tuyết Thu', 'Nguyễn Chánh Tín', 'Trung Dân']::TEXT[], ARRAY['Kinh Dị']::TEXT[], 88, '2017-02-24', NULL, NULL, 6, 'ended'),
  ('d5224e5a-c99a-5ffe-951c-1cf537691669'::UUID, 334693, 'Đoạt Hồn', 'Đoạt Hồn', 'Đoạt hồn là câu chuyện xoay quanh bi kịch của gia đình Gia Huy, một thương gia bán đá quý. Trong một lần gia đình đi làm lễ thánh, cô con gái út 8 tuổi tên Ái của gia đình bị trượt chân ngã xuống sông và chết đuối. Một tuần sau đó, người cậu Thức nhận được tin tìm thấy xác bé Ái ở Châu Đốc bên bờ sông Hậu Giang. Nhưng kỳ lạ thay, khi tới nơi nhận xác cháu, cậu Thức được chứng kiến cảnh bé Ái từ cõi chết trở về. Sau khi bé Ái được đưa về nhà, nhiều sự kiện ma quái cứ thế bắt đầu xảy ra.', 'A young girl falls into a river and drowns. When her body is found in a remote village along the river, her uncle arrives to claim her body, only to find that she is very much alive. But when she returns to her family, unexplainable occurrences lead them to believe she is possessed.', 'https://image.tmdb.org/t/p/w780/cefUKWm7mNPodfUVkTzpLz1HQKk.jpg', 'https://image.tmdb.org/t/p/w1280/69ggYM2umSwmuLiIQX9aSyqrsZD.jpg', NULL, 'Hàm Trần', ARRAY['Trần Bảo Sơn', 'Nguyễn Thị Ngọc Hiệp', 'Hong An Nguyen', 'Lâm Thanh Mỹ', 'Mai Thế Hiệp', 'Kiều Chinh', 'Nguyễn Minh Trang', 'Thương Tín']::TEXT[], ARRAY['Bí Ẩn', 'Kinh Dị', 'Chính Kịch']::TEXT[], 99, '2014-07-18', NULL, NULL, 7.5, 'ended'),
  ('6e9d88f5-0af5-55f3-b580-07ce998c076a'::UUID, 1628819, 'TÀI', 'TÀI', 'Tài đã trải qua hành trình đầy khó khăn, làm đủ mọi nghề, thậm chí là những phi vụ nguy hiểm phải đặt cược mạng sống để bảo vệ “tài sản” quý giá nhất đời mình. Liệu Tài có đủ nghị lực và tinh thần để vượt lên trên nghịch cảnh, trong gang tấc sự sống? Bộ phim đem đến tiếng cười, tình yêu và sự bao dung mạnh mẽ về những mối quan hệ tình thân và xã hội trong những ngày đầu xuân 2026.', NULL, 'https://image.tmdb.org/t/p/w780/8EsVJLdGGpBmGM7HyygfyOQ81WC.jpg', 'https://image.tmdb.org/t/p/w1280/2PRrqjXvSo5PkVoWekYwq78QeM7.jpg', 'https://www.youtube.com/watch?v=krJCguh8l_4', 'Mai Tài Phến', ARRAY['Vinh Râu', 'Mai Tài Phến', 'Mỹ Tâm', 'Kim Hải', 'Huỳnh Thi', 'Long Đẹp Trai', 'Công Ninh', 'Hạnh Thúy']::TEXT[], ARRAY['Hành Động', 'Hài']::TEXT[], 101, '2026-03-06', NULL, 'CA: PG', 0, 'ended'),
  ('52b1f555-c219-5524-9bf1-3211050bba12'::UUID, 1641479, 'Anh Hùng', 'Anh Hùng', 'Câu chuyện phim theo chân Hùng (Thái Hòa) - người cha đơn thân kiêm tài xế taxi và đồng nghiệp hãng xe là Tuấn (Võ Tấn Phát) bị cuốn vào một phi vụ lừa đảo từ thiện tiền tỉ trong khi sinh mạng cô con gái nhỏ của anh đang nằm gọn trong tay tử thần.', NULL, 'https://image.tmdb.org/t/p/w780/gDc2FCkTFfUg7MWpp7zm0D0b48h.jpg', 'https://image.tmdb.org/t/p/w1280/lRneBPpPRPzg2kHIY4yNZzLq3z8.jpg', 'https://www.youtube.com/watch?v=9fgmlmYme18', 'Võ Thạch Thảo', ARRAY['Thái Hòa', 'Võ Tấn Phát', 'Phương Thanh', 'Đoàn Thế Vinh', 'Hồng Ánh', 'Lê Thiện', 'Hoàng Minh Triết', 'Gia Tuệ']::TEXT[], ARRAY['Gia Đình', 'Chính Kịch']::TEXT[], 122, '2026-04-24', NULL, NULL, 7.5, 'ended'),
  ('f8fd1a3d-d437-5300-8235-a79274b1c9ad'::UUID, 1511747, 'Trại Buôn Người', 'Trại Buôn Người', 'Vì cứu em gái sa bẫy buôn người ở biên giới, Ny (Steven Nguyễn) cùng bạn thân bị bắt làm nô dịch trong sào huyệt lừa đảo tàn bạo. Tại đây, họ cùng các trinh sát nằm vùng và các nạn nhân hứng chịu bi kịch thể xác âm thầm lập kế hoạch trốn thoát.', NULL, 'https://image.tmdb.org/t/p/w780/lwoPa795ysdVSkvmlB93HyGH1SJ.jpg', 'https://image.tmdb.org/t/p/w1280/fhCV5kf3kzfgjpdiVCMuzHBXvxz.jpg', 'https://www.youtube.com/watch?v=eM7mM7VUv10', 'Dương Bảo Anh', ARRAY['Steven Nguyễn', 'Trầm Minh Hoàng', 'Huỳnh Minh Kiên', 'Tùng Mint', 'Võ Đình Hiếu', 'Quách Ngọc Ngoan', 'Như Quỳnh', 'Tuyết Thu']::TEXT[], ARRAY['Hành Động', 'Giật Gân']::TEXT[], 135, '2026-09-25', NULL, NULL, 6.7, 'ended'),
  ('e3971485-82d8-5327-8caa-383d3d03defb'::UUID, 175447, 'Lửa Phật', 'Lửa Phật', 'Chuyện phim bắt đầu từ một ngôi làng nhỏ, nơi những người dân vô tội đang bị gã giang hồ khét tiếng và đồng bọn của hắn ra sức quấy rối và ức hiếp. Cái gai trong mắt của chúng chính là Hiền – một người thợ làm bánh trong làng. Trước sự hống hách của bọn giang hồ, Hiền cùng với người vợ xinh đẹp của mình đã kêu gọi người dân trong làng đứng lên phản kháng. Cùng thời điểm đó, Đạo - một cao nhân bí ẩn đã đến và chứng kiến cuộc chiến không cân sức này. Đạo đã đứng về phía dân làng. Một cuộc quyết chiến nổ ra và quá khứ bí ẩn của Đạo cũng dần dần được hé lộ...', NULL, 'https://image.tmdb.org/t/p/w780/mtrWJOyNiHgM1QlJ6VXLCHFemBf.jpg', 'https://image.tmdb.org/t/p/w1280/78JyPTq8bMUlzeDbxBgFHkUtVwG.jpg', 'https://www.youtube.com/watch?v=2nUD-T3hQNA', 'Dustin Nguyễn', ARRAY['Dustin Nguyễn', 'Roger Yuan', 'Ngô Thanh Vân', 'Thái Hòa', 'Ngọc Diệp', 'Hiếu Hiền', 'Phi Thanh Vân', 'Bùi Văn Hải']::TEXT[], ARRAY['Giả Tưởng', 'Hành Động']::TEXT[], 102, '2013-08-21', NULL, 'VN: PG', 5.6, 'ended'),
  ('a82c2664-544c-5ef3-abc9-678bf4e7aa91'::UUID, 173380, 'Những Nụ Hôn Rực Rỡ', 'Những Nụ Hôn Rực Rỡ', 'Là bộ phim ca nhạc đầu tiên của điện ảnh Việt Nam, tác phẩm trở thành điểm nhấn sáng giá trong mùa phim Tết 2010. Ngoài kịch bản mới lạ cùng những màn múa hát lôi cuốn, câu chuyện về cô tiểu thư đỏng đảnh Thanh Lam nỗ lực cứu lấy khu resort ế khách gây được tiếng vang lớn nhờ dàn diễn viên đình đám: Thanh Hằng, Minh Hằng, Phương Thanh…', 'A group of staff and employees from a resort cheat a famous boy-band to perform for them in order to keep their business when one of the members stay in their resort. However, things turn out not they way they want. Therefore, these people have to do the show themselves and everybody has a chance to show their talents.', 'https://image.tmdb.org/t/p/w780/sOTlOxFH0cv0PNY31p4rcfhbpP2.jpg', 'https://image.tmdb.org/t/p/w1280/gYGKjYM9U9eG0nJr2oZK3UQo1ov.jpg', NULL, 'Nguyễn Quang Dũng', ARRAY['Thanh Hằng', 'Minh Hằng', 'Phương Thanh', 'Leon Lê', 'Võ Ngọc Trai', 'Phước Sang', 'Thủy Tiên', 'Minh Thư']::TEXT[], ARRAY['Âm Nhạc']::TEXT[], 98, '2010-01-15', NULL, 'VN: vietnam', 0, 'ended'),
  ('72f70f84-bc56-55be-877b-98a60137878b'::UUID, 579603, 'Trạng Quỳnh', 'Trạng Quỳnh', 'Nội dung bộ phim Trạng Quỳnh được phóng tác từ những giai thoại về nhân vật cùng tên trong dân gian Việt Nam. Chuyện phim xoay quanh Quỳnh (Quốc Anh) - một anh chàng thông minh, ma mãnh, rất thích bày trò trêu chọc người dân trong làng.  Quỳnh thầm thương trộm nhớ nàng Điềm (Nhã Phương) - con gái của thầy Đoàn (Tùng Tuki). Anh cứ thế ra sức tán tỉnh người trong mộng mà chưa thành. Song, cô gái tài sắc vẹn toàn còn sớm lọt vào mắt xanh của Trịnh Bá (Công Dương) - cháu của chúa Trịnh.  Gã dùng âm mưu hãm hại thầy Đoàn để ép Điềm phải làm đám cưới. Không chịu khuất phục, cô cùng Quỳnh và người bạn thân Xẩm (Trấn Thành) khăn gói lên kinh để báo quan.', NULL, 'https://image.tmdb.org/t/p/w780/tCAqxEaTG5VxlT4FqLQCfVv2IhU.jpg', 'https://image.tmdb.org/t/p/w1280/XStkB3cKYxbDjf8Wozg1zYNkU8.jpg', 'https://www.youtube.com/watch?v=RM78y39sdik', 'Đức Thịnh', ARRAY['Quốc Anh', 'Nhã Phương', 'Trấn Thành', 'Khả Như', 'Đức Thịnh', 'Văn Tùng', 'Bạch Long', 'Linh Trung']::TEXT[], ARRAY['Hài', 'Phiêu Lưu']::TEXT[], 92, '2019-02-05', NULL, NULL, 7, 'ended'),
  ('3c31f10c-592d-597b-8725-b305289875cc'::UUID, 64937, 'Chuyện Tình Xa Xứ', 'Chuyện Tình Xa Xứ', 'Một chàng công tử không thể sống thiếu gái đẹp và một anh mọt sách nhà nghèo cùng rơi vào vòng xoáy tình yêu trên đất Mỹ nhiều cám dỗ. Ai sẽ tìm được tình yêu đích thực?', NULL, 'https://image.tmdb.org/t/p/w780/33Zu7QcGKUoPXNZRJlle9flshPj.jpg', NULL, 'https://www.youtube.com/watch?v=Qj9EDnsT0QU', 'Victor Vũ', ARRAY['Kathy Uyen', 'Huy Khánh', 'Bình Minh', 'Ngọc Diệp', 'Tăng Bảo Quyên', 'Mario E. Garcia', 'Nguyễn Văn Phúc', 'Kim Xuân']::TEXT[], ARRAY['Chính Kịch', 'Hài', 'Lãng Mạn']::TEXT[], 120, '2009-02-13', NULL, NULL, 5, 'ended'),
  ('59feb68c-71ac-5b35-bf8b-7c43a7494d87'::UUID, 329851, 'Để Mai Tính 2', 'Để Mai Tính 2', 'Phim Để Mai Tính 2 (tên cũ: Để Hội Tính) của đạo diễn Charlie Nguyễn là phần ngoại truyện hài hước chưa kể của Để Mai Tính. Xoay quanh nhân vật Phạm Hương Hội (Thái Hòa). Từ một nhân vật phụ đã rất ấn tượng trong Để Mai Tính, nay còn tỏa sáng hơn với diện mạo mới, lý lịch mới, trong vai chính của phim Để Hội Tính. Là chủ tịch của một tập đoàn lớn, giàu có, nhưng Hội lại đem lòng yêu anh chàng họa sĩ phong trần tên Nam (Quang Sự). Dưới sự chỉ dẫn của trợ lý đắc lực (Huy Khánh), Hội đã "giả trai" để tiếp cận Nam. Nhưng Nam đang rất ngọt ngào bên người yêu Thư Lê (Diễm My 9x). Tan vỡ trong Để Mai Tính, liệu lần này Hội có chấp nhận tiếp tục thất bại trong tình yêu? Hội sẽ làm gì để loại bỏ tình địch Thư Lê và giành lấy tình yêu của mình?', 'A transgender Vietnamese businessman who becomes poor every time he falls in love with someone.', 'https://image.tmdb.org/t/p/w780/twaynwko42GtnWDqSN7nQ9xBkEl.jpg', 'https://image.tmdb.org/t/p/w1280/5LEuiQNzwT52c2ve3FOWbEf7lEt.jpg', 'https://www.youtube.com/watch?v=ajtdC0Pnoa8', 'Charlie Nguyễn', ARRAY['Thái Hòa', 'Kathy Uyen', 'Johnny Trí Nguyễn', 'Lâm Thanh Mỹ', 'Hoàng Phúc', 'Diễm My 9x', 'Huy Khánh', 'YaYa Trương Nhi']::TEXT[], ARRAY['Hài']::TEXT[], 94, '2014-01-01', NULL, NULL, 7.4, 'ended'),
  ('e8b34f40-dfd2-5101-9ae0-12bc7e12cc54'::UUID, 1326870, 'Năm Vua Hề Về Làng', 'Năm Vua Hề Về Làng', 'Thông tin phim đang được cập nhật.', NULL, 'https://image.tmdb.org/t/p/w780/9XUzjD6WWn58oPdoeNpUKhfGcbR.jpg', NULL, NULL, 'Lê Hoàng Hoa', ARRAY['Thành Được', 'La Thoại Tân', 'Thẩm Thúy Hằng', 'Thanh Nga', 'Ba Vân', 'Băng Châu', 'Kim Cương', 'Tùng Lâm']::TEXT[], ARRAY['Hài', 'Phiêu Lưu']::TEXT[], 110, '1974-08-07', NULL, NULL, 0, 'ended'),
  ('fbe02622-eff2-5eb3-b64a-4b03a1baffb0'::UUID, 1618321, 'Báu Vật Trời Cho', 'Báu Vật Trời Cho', 'Khi cậu bé sáu tuổi trong một gia đình đơn thân vô tình tìm được “người cha trời cho” của mình. Hàng loạt bí mật và định mệnh trớ trêu bị lật mở, để rồi mỗi người phải tự hỏi: Điều gì mới thật sự là báu vật trời cho trong đời mình?', 'BÁU VẬT TRỜI CHO is an emotionally rich, heartwarming film that celebrates family bonds for Tết 2026. Ngọc (Phương Anh Đào), a single mother who conceived her child through donor insemination, takes a seaside getaway to escape her past. There, she and her son Tô unexpectedly encounter Hồng (Tuấn Trần), a free-spirited fisherman who happens to be the donor behind Tô’s birth. This awkward reunion draws three strangers into a series of humorous yet tense situations as everything spirals beyond control. Is this “heaven-sent” father a destined gift, or merely life’s cruel twist of fate?', 'https://image.tmdb.org/t/p/w780/ljYwb65602RVFyWQCR9JkSYKXsy.jpg', 'https://image.tmdb.org/t/p/w1280/35lle2RJBcBm1BYuLkapCURLa4U.jpg', 'https://www.youtube.com/watch?v=dwfUi9SV5ss', 'Lê Thanh Sơn', ARRAY['Phương Anh Đào', 'Mì Gói', 'Tuấn Trần', 'Trung Dân', 'Quách Ngọc Ngoan', 'Võ Tấn Phát', 'Khương Lê', 'Thư Đan']::TEXT[], ARRAY['Hài', 'Gia Đình', 'Lãng Mạn']::TEXT[], 124, '2026-02-17', NULL, NULL, 6, 'ended'),
  ('f0adafab-fdf9-5a72-8ed5-e1a584c503af'::UUID, 362071, 'Trúng số', 'Trúng số', 'Ra tù sau 15 năm, bác Tư Phi (danh hài Chí Tài) bối rối không biết làm sao hòa nhập với cộng đồng. Bỗng dưng may mắn trúng số độc đắc 9 tỉ, vốn tính hào phóng, bác vung tiền ra, hứa tặng mỗi người 10 triệu đồng. Lập tức hàng trăm người nhao nhao kéo đến, gây nên một cảnh hỗn loạn chưa từng có, những rắc rối cũng đến theo...Không chỉ vui nhộn, hài hước, bộ phim do tài tử Dustin Nguyễn đạo diễn còn được Việt Nam chọn gửi đi tranh giải Oscar 2015 bởi câu chuyện cổ tích giữa đời thường, ấm áp tình người và cảnh quay đẹp, trau chuốt về làng quê Nam bộ. Phim lấy cảm hứng từ một sự kiện có thật ở Long An, khi cô Lành bán vé số thành thật trả lại vé độc đắc 6,6 tỷ đồng cho người mua thiếu bằng miệng.', 'Inspired by a true story, Jackpot (Trúng Số) is a heartfelt comedy.', 'https://image.tmdb.org/t/p/w780/unF8WC5w7MmKeKb2KJ5YGiaYWGh.jpg', 'https://image.tmdb.org/t/p/w1280/dGipWWFXsMmMvPNbttIVa1JxAgR.jpg', NULL, 'Dustin Nguyễn', ARRAY['Ninh Dương Lan Ngọc', 'Dustin Nguyễn', 'Chí Tài', 'Mai Thế Hiệp']::TEXT[], ARRAY['Hài']::TEXT[], 92, '2015-02-13', NULL, NULL, 6.7, 'ended'),
  ('c1c732eb-ecbb-541d-9f5d-69bac71d4049'::UUID, 1566122, 'Ai Thương Ai Mến', 'Ai Thương Ai Mến', 'Set against the riverine landscape of Vietnam’s Mekong Delta, Ai Thương Ai Mến centers on Hai Mến—a woman who loses both parents and is left to shoulder her family’s burdens alone amid debt and relentless personal tragedies. Along her arduous journey, she encounters Khả (Ngọc Thuận), a carefree, pleasure-seeking young heir who unexpectedly falls deeply in love with her, giving rise to a romance that is at once tender and heartbreaking. In parallel, the pure and gentle love story of the young couple Chờ and Thương emerges as a rare ray of light, before all three narrative threads are ultimately drawn into trials that deeply move the audience.', 'Set against the riverine landscape of Vietnam’s Mekong Delta, Ai Thương Ai Mến centers on Hai Mến—a woman who loses both parents and is left to shoulder her family’s burdens alone amid debt and relentless personal tragedies. Along her arduous journey, she encounters Khả (Ngọc Thuận), a carefree, pleasure-seeking young heir who unexpectedly falls deeply in love with her, giving rise to a romance that is at once tender and heartbreaking. In parallel, the pure and gentle love story of the young couple Chờ and Thương emerges as a rare ray of light, before all three narrative threads are ultimately drawn into trials that deeply move the audience.', 'https://image.tmdb.org/t/p/w780/ixU3QXGRxixnZzQKVoTu4OGNeRQ.jpg', 'https://image.tmdb.org/t/p/w1280/vhquDoJvcvZCzEjCF1DKWA3ULeR.jpg', 'https://www.youtube.com/watch?v=vLIh-mEuuTc', 'Thu Trang', ARRAY['Thu Trang', 'Trâm Anh', 'Võ Điền Gia Huy', 'Hồng Ánh', 'Khả Như', 'Trương Minh Thảo', 'La Thành', 'Tiến Luật']::TEXT[], ARRAY['Hài', 'Chính Kịch', 'Lãng Mạn']::TEXT[], 112, '2026-01-01', NULL, NULL, 0, 'ended'),
  ('c1c31f5d-f8a7-5ad4-bdeb-67edbea2dc7d'::UUID, 1470133, 'White Valentine', 'White Valentine', 'The movie focuses on Khanh Linh and DJ Kim''s love story. Khanh Linh decides to ignore everything to pursue her new love, even though she has a fiancé named Hung. Troubles persist after that.', 'The movie focuses on Khanh Linh and DJ Kim''s love story. Khanh Linh decides to ignore everything to pursue her new love, even though she has a fiancé named Hung. Troubles persist after that.', 'https://image.tmdb.org/t/p/w780/5hJOgVJbODyeuqSqtPCZfmP73Tc.jpg', NULL, NULL, 'Davina Hồng Ngân', ARRAY['Dieu Huyen', 'Vuong Thu Phuong', 'ปภังกร สกุลซ้ง']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 95, '2016-03-11', NULL, NULL, 0, 'ended'),
  ('2e6f62f1-ca0d-5b99-a299-e362330ba118'::UUID, 639412, 'Bí Mật Của Gió', 'Bí Mật Của Gió', 'Bí Mật Của Gió kể về cô nàng quái chiêu Linh khi cùng gia đình chuyển đến một ngôi nhà ma ám tại Đà Lạt, thành phố của sương mù bí ẩn và đầy lãng mạn. Bỗng nhiên Linh bắt buộc phải sống chung phòng với một hồn ma điển trai đến từ quá khứ. Từ những tình huống xung đột hài hước lúc ban đầu cả hai đã nảy sinh tình cảm và giúp nhau tìm ra được bí mật được chôn giấu suốt 45 năm.', 'Linh, an art student, moves to a new house where she encounters a ghost. She helps him to uncover the mysterious cause of his death realizing what’s important in her life.', 'https://image.tmdb.org/t/p/w780/7Ec6peTdtxcj3TZPD2xjQBdADUq.jpg', 'https://image.tmdb.org/t/p/w1280/JAnRaJXTPnmJKWE73Vs4ltRVuy.jpg', NULL, 'Nguyễn Phan Quang Bình', ARRAY['Quốc Anh', 'Khả Ngân', 'Hoàng Yến Chibi', 'Vo Bang Thanh', 'Yu Dương', 'Phi Điểu', 'Hữu Châu']::TEXT[], ARRAY['Lãng Mạn']::TEXT[], 90, '2020-01-31', NULL, NULL, 0, 'ended'),
  ('452b53b5-d021-5eb1-aa9d-b44647dd59ca'::UUID, 60084, 'Cánh Đồng Bất Tận', 'Cánh Đồng Bất Tận', 'Lấy bối cảnh ở đồng bằng sông Cửu Long của Việt Nam, bộ phim kể về câu chuyện của ông Võ và những người con của ông. Vô cùng tức giận vì sự không chung thủy của vợ, anh đã đốt nhà và tất cả những kỷ niệm của anh trong quá khứ.', 'Set in the Mekong Delta of Vietnam, the film tells a story of Mr. Võ and his children. Võ, enraged by his wife’s infidelity, burns down his house and all his memories of the past.', 'https://image.tmdb.org/t/p/w780/EHzcyuFO84ZxHV4mNsNl8bHPdG.jpg', 'https://image.tmdb.org/t/p/w1280/uC597yZ6CaEuy6a5T9sb0XjrdaB.jpg', 'https://www.youtube.com/watch?v=YET_mzttPDg', 'Nguyễn Phan Quang Bình', ARRAY['Dustin Nguyễn', 'Đỗ Thị Hải Yến', 'Tăng Thanh Hà', 'Ninh Dương Lan Ngọc', 'Võ Thanh Hòa']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 105, '2010-12-03', NULL, 'VN: PG-13', 6.3, 'ended'),
  ('d604eefd-06ba-5809-9810-9cf49937d228'::UUID, 616319, 'Nhà Cây', 'Nhà Cây', 'In 2045, a filmmaker lands on Mars and tries to make a film. “Home… Far away from home”, he recalls faces of people, thus a collection of moving images emerge.', 'In 2045, a filmmaker lands on Mars and tries to make a film. “Home… Far away from home”, he recalls faces of people, thus a collection of moving images emerge.', 'https://image.tmdb.org/t/p/w780/tT7NsewrH1yCQOSJkgDk99q030x.jpg', 'https://image.tmdb.org/t/p/w1280/rEpbyczlishq8rlWMCxPVVNwgXt.jpg', 'https://www.youtube.com/watch?v=qjck09Czc9Q', 'Truong Minh Quy', ARRAY['Thi Hau Cao', 'Van Lang Ho']::TEXT[], ARRAY['Phim Tài Liệu', 'Khoa Học Viễn Tưởng']::TEXT[], 84, '2019-08-12', NULL, NULL, 6, 'ended'),
  ('f24ed5f2-a70c-5bb7-b91d-f1b108555341'::UUID, 597127, 'Hãy tỉnh thức và sẵn sàng', 'Hãy tỉnh thức và sẵn sàng', 'On a street corner a mysterious conversation among three young men at street stalls. Meanwhile a traffic accident on a motorbike. The night brings together a sketch, a multicolor frame of reality.', 'On a street corner a mysterious conversation among three young men at street stalls. Meanwhile a traffic accident on a motorbike. The night brings together a sketch, a multicolor frame of reality.', 'https://image.tmdb.org/t/p/w780/vkuOuGl7U9t2m3SsQtImZahXiS7.jpg', 'https://image.tmdb.org/t/p/w1280/oNL7ejN98M3eHygKO7DJR0ycBYX.jpg', 'https://www.youtube.com/watch?v=LlJ8ybWtG8w', 'Phạm Thiên Ân', ARRAY['Vu Trong Tuyen', 'Trung Dong Cao', 'Le Quoc Bao Vi', 'Huynh Ngoc Hanh', 'Be Hieu']::TEXT[], ARRAY['Chính Kịch']::TEXT[], 14, '2019-05-23', NULL, 'SG: PG13', 6, 'ended'),
  ('34375a73-aa73-5b97-bf35-b2f96b1006c2'::UUID, 313594, 'Em bé Hà Nội', 'Em bé Hà Nội', 'A young girl searches for her father, a soldier in the PAVN, after her mother and sister are killed during Christmas Bombings.', 'A young girl searches for her father, a soldier in the PAVN, after her mother and sister are killed during Christmas Bombings.', 'https://image.tmdb.org/t/p/w780/bXDj2GderISsSL0ELmgNwme2yrv.jpg', 'https://image.tmdb.org/t/p/w1280/jfL2CbTdK4ETJSkg1wM6n9RJLQD.jpg', NULL, 'Hải Ninh', ARRAY['Lan Hương', 'Trà Giang', 'Thế Anh', 'Kim Xuân', 'Bich Van', 'Quỳnh Anh', 'Thanh Tú', 'Hà Văn Trọng']::TEXT[], ARRAY['Chiến Tranh', 'Chính Kịch']::TEXT[], 75, '1974-10-01', NULL, NULL, 7.2, 'ended')
) AS v(id, tmdb_id, title, original_title, description, overview_en, poster_url, backdrop_url, trailer_url, director, cast_members, genres, duration_minutes, release_date, age_rating, certification_origin, rating, status)
WHERE NOT EXISTS (
  SELECT 1 FROM public.movies m WHERE m.id = v.id OR (v.tmdb_id IS NOT NULL AND m.tmdb_id = v.tmdb_id)
)
ON CONFLICT (id) DO NOTHING;

COMMIT;
